(277, 't', 'Realizar la gestión básica para la creación y funcionamiento de una pequeña empresa y tener iniciativa en su actividad profesional con sentido de la responsabilidad social.', 2, 13, 21),
(278, 'u', 'Ejercer sus derechos y cumplir con las obligaciones derivadas de su actividad profesional, de acuerdo con lo establecido en la legislación vigente, participando activamente en la vida económica, social y cultural.', 2, 13, 22),
(279, 'a', 'Tramitar documentos o comunicaciones internas o externas en los circuitos de información de la empresa.', 1, 12, 1),
(280, 'b', 'Elaborar documentos y comunicaciones a partir de órdenes recibidas, información obtenida y/o necesidades detectadas.', 1, 12, 2),
(281, 'c', 'Detectar necesidades administrativas o de gestión de la empresa de diversos tipos, a partir del análisis de la información disponible y del entorno.', 1, 12, 3),
(282, 'd', 'Proponer líneas de actuación encaminadas a mejorar la eficiencia de los procesos administrativos en los que interviene.', 1, 12, 4),
(283, 'e', 'Clasificar, registrar y archivar comunicaciones y documentos según las técnicas apropiadas y los parámetros establecidos en la empresa.', 1, 12, 5),
(284, 'f', 'Gestionar los procesos de tramitación administrativa empresarial en relación a las áreas comercial, financiera, contable y fiscal, con una visión integradora de las mismas.', 1, 12, 6),
(285, 'g', 'Realizar la gestión contable y fiscal de la empresa, según los procesos y procedimientos administrativos, aplicando la normativa vigente y en condiciones de seguridad y calidad.', 1, 12, 7),
(286, 'h', 'Supervisar la gestión de tesorería, la captación de recursos financieros y el estudio de viabilidad de proyectos de inversión, siguiendo las normas y protocolos establecidos.', 1, 12, 8),
(287, 'i', 'Aplicar los procesos administrativos establecidos en la selección, contratación, formación y desarrollo de los Recursos Humanos, ajustándose a la normativa vigente y a la política empresarial.', 1, 12, 9),
(288, 'j', 'Organizar y supervisar la gestión administrativa de personal de la empresa, ajustándose a la normativa laboral vigente y a los protocolos establecidos.', 1, 12, 10),
(289, 'k', 'Realizar la gestión administrativa de los procesos comerciales, llevando a cabo las tareas de documentación y las actividades de negociación con proveedores, y de asesoramiento y relación con el cliente.', 1, 12, 11),
(290, 'l', 'Atender a los clientes/usuarios en el ámbito administrativo y comercial asegurando los niveles de calidad establecidos y ajustándose a criterios éticos y de imagen de la empresa/institución.', 1, 12, 12),
(291, 'm', 'Tramitar y realizar la gestión administrativa en la presentación de documentos en diferentes organismos y administraciones públicas, en plazo y forma requeridos.', 1, 12, 13),
(292, 'n', 'Adaptarse a las nuevas situaciones laborales, manteniendo actualizados los conocimientos científicos, técnicos y tecnológicos relativos a su entorno profesional, gestionando su formación y los recursos existentes en el aprendizaje a lo largo de la vida y utilizando las tecnologías de la información ', 2, 12, 14),
(293, 'ñ', 'Resolver situaciones, problemas o contingencias con iniciativa y autonomía en el ámbito de su competencia, con creatividad, innovación y espíritu de mejora en el trabajo personal y en el de los miembros del equipo.', 2, 12, 15),
(294, 'o', 'Organizar y coordinar equipos de trabajo con responsabilidad, supervisando el desarrollo del mismo, manteniendo relaciones fluidas y asumiendo el liderazgo, así como aportando soluciones a los conflictos grupales que se presenten.', 2, 12, 16),
(295, 'p', 'Comunicarse con sus iguales, superiores, clientes y personas bajo su responsabilidad, utilizando vías eficaces de comunicación, transmitiendo la información o conocimientos adecuados y respetando la autonomía y competencia de las personas que intervienen en el ámbito de su trabajo.', 2, 12, 17),
(296, 'q', 'Generar entornos seguros en el desarrollo de su trabajo y el de su equipo, supervisando y aplicando los procedimientos de prevención de riesgos laborales y ambientales, de acuerdo con lo establecido por la normativa y los objetivos de la empresa.', 2, 12, 18),
(297, 'r', 'Supervisar y aplicar procedimientos de gestión de calidad, de accesibilidad universal y de “diseño para todos”, en las actividades profesionales incluidas en los procesos de producción o prestación de servicios.', 2, 12, 19);
INSERT INTO `competencias_ciclos` (`id`, `codigo`, `texto`, `tipo`, `idCiclo`, `orden`) VALUES
(298, 's', 'Realizar la gestión básica para la creación y funcionamiento de una pequeña empresa y tener iniciativa en su actividad profesional con sentido de la responsabilidad social.', 2, 12, 20),
(299, 't', 'Ejercer sus derechos y cumplir con las obligaciones derivadas de su actividad profesional, de acuerdo con lo establecido en la legislación vigente, participando activamente en la vida económica, social y cultural.', 2, 12, 21),
(300, '1', 'Tramitar documentos o comunicaciones internas o externas en los circuitos de información de la empresa.', 1, 14, 1),
(301, '2', 'Elaborar documentos y comunicaciones a partir de órdenes recibidas o información obtenida.', 1, 14, 2),
(302, '3', 'Clasificar, registrar y archivar comunicaciones y documentos según las técnicas apropiadas y los parámetros establecidos en la empresa.', 1, 14, 3),
(303, '4', 'Registrar contablemente la documentación soporte correspondiente a la operativa de la empresa en condiciones de seguridad y calidad.', 1, 14, 4),
(304, '5', 'Realizar gestiones administrativas de tesorería, siguiendo las normas y protocolos establecidos por la gerencia con el fin de mantener la liquidez de la organización.', 1, 14, 5),
(305, '6', 'Efectuar las gestiones administrativas de las áreas de selección y formación de los recursos humanos de la empresa, ajustándose a la normativa vigente y a la política empresarial, bajo la supervisión del responsable superior del departamento.', 1, 14, 6),
(306, '7', 'Prestar apoyo administrativo en el área de gestión laboral de la empresa ajustándose a la normativa vigente y bajo la supervisión del responsable superior del departamento.', 1, 14, 7),
(307, '8', 'Realizar las gestiones administrativas de la actividad comercial registrando la documentación soporte correspondiente a determinadas obligaciones fiscales derivadas.', 1, 14, 8),
(308, '9', 'Desempeñar las actividades de atención al cliente/usuario en el ámbito administrativo y comercial asegurando los niveles de calidad establecidos y relacionados con la imagen de la empresa/institución.', 1, 14, 9),
(309, '10', 'Aplicar los protocolos de seguridad laboral y ambiental, higiene y calidad durante todo el proceso productivo, para evitar daños en las personas y en el ambiente.', 2, 14, 10),
(310, '11', 'Cumplir con los objetivos de la producción, actuando conforme a los principios de responsabilidad y manteniendo unas relaciones profesionales adecuadas con los miembros del equipo de trabajo.', 2, 14, 11),
(311, '12', 'Resolver problemas y tomar decisiones individuales siguiendo las normas y procedimientos establecidos, definidos dentro del ámbito de su competencia.', 2, 14, 12),
(312, '13', 'Mantener el espíritu de innovación, de mejora de los procesos de producción y de actualización de conocimientos en el ámbito de su trabajo.', 2, 14, 13),
(313, '14', 'Ejercer sus derechos y cumplir con las obligaciones derivadas de las relaciones laborales, de acuerdo con lo establecido en la legislación vigente.', 2, 14, 14),
(314, '15', 'Detectar y analizar oportunidades de empleo y autoempleo desarrollando una cultura emprendedora y adaptándose a diferentes puestos de trabajo y nuevas situaciones.', 2, 14, 15),
(315, '16', 'Participar de forma activa en la vida económica, social y cultural, con una actitud crítica y responsable.', 2, 14, 16),
(316, '17', 'Participar en las actividades de la empresa con respeto y actitudes de tolerancia.', 2, 14, 17),
(317, '18', 'Adaptarse a diferentes puestos de trabajo y nuevas situaciones laborales, originados por cambios tecnológicos y organizativos en los procesos productivos.', 2, 14, 18),
(318, '19', 'Participar en el trabajo en equipo respetando la jerarquía definida en la organización.', 2, 14, 19),
(319, 'a', 'Preparar equipos y aplicaciones informáticas para llevar a cabo la grabación, tratamiento e impresión de datos y textos, asegurando su funcionamiento.', 1, 15, 1),
(320, 'b', 'Elaborar documentos mediante las utilidades básicas de las aplicaciones informáticas de los procesadores de texto y hojas de cálculo aplicando procedimientos de escritura al tacto con exactitud y rapidez.', 1, 15, 2),
(321, 'c', 'Realizar tareas básicas de almacenamiento y archivo de información y documentación, tanto en soporte digital como convencional, de acuerdo con los protocolos establecidos.', 1, 15, 3),
(322, 'd', 'Realizar labores de reprografía y encuadernado básico de documentos de acuerdo a los criterios de calidad establecidos.', 1, 15, 4),
(323, 'e', 'Tramitar correspondencia y paquetería, interna o externa, utilizando los medios y criterios establecidos.', 1, 15, 5),
(324, 'f', 'Realizar operaciones básicas de tesorería, utilizando los documentos adecuados en cada caso.', 1, 15, 6),
(325, 'g', 'Recibir y realizar comunicaciones telefónicas e informáticas transmitiendo con precisión la información encomendada según los protocolos y la imagen corporativa.', 1, 15, 7),
(326, 'h', 'Realizar las tareas básicas de mantenimiento del almacén de material de oficina, preparando los pedidos que aseguren un nivel de existencias mínimo.', 1, 15, 8),
(327, 'i', 'Atender al cliente, utilizando las normas de cortesía y demostrando interés y preocupación por resolver satisfactoriamente sus necesidades.', 1, 15, 9),
(328, 'j', 'Resolver problemas predecibles relacionados con su entorno físico, social, personal y productivo, utilizando el razonamiento científico y los elementos proporcionados por las ciencias aplicadas y sociales.', 2, 15, 10),
(329, 'k', 'Actuar de forma saludable en distintos contextos cotidianos que favorezcan el desarrollo personal y social, analizando hábitos e influencias positivas para la salud humana.', 2, 15, 11),
(330, 'l', 'Valorar actuaciones encaminadas a la conservación del medio ambiente diferenciando las consecuencias de las actividades cotidianas que puedan afectar al equilibrio del mismo.', 2, 15, 12),
(331, 'm', 'Obtener y comunicar información destinada al autoaprendizaje y a su uso en distintos contextos de su entorno personal, social o profesional mediante recursos a su alcance y los propios de las tecnologías de la información y de la comunicación.', 2, 15, 13),
(332, 'n', 'Actuar con respeto y sensibilidad hacia la diversidad cultural, el patrimonio histórico-artístico y las manifestaciones culturales y artísticas, apreciando su uso y disfrute como fuente de enriquecimiento personal y social.', 2, 15, 14),
(333, 'ñ', 'Comunicarse con claridad, precisión y fluidez en distintos contextos sociales o profesionales y por distintos medios, canales y soportes a su alcance, utilizando y adecuando recursos lingüísticos orales y escritos propios de la lengua castellana y, en su caso, de la lengua cooficial.', 2, 15, 15),
(334, 'o', 'Comunicarse en situaciones habituales tanto laborales como personales y sociales utilizando recursos lingüísticos básicos en lengua extranjera.', 2, 15, 16),
(335, 'p', 'Realizar explicaciones sencillas sobre acontecimientos y fenómenos característicos de las sociedades contemporáneas a partir de información histórica y geográfica a su disposición.', 2, 15, 17),
(336, 'q', 'Adaptarse a las nuevas situaciones laborales originadas por cambios tecnológicos y organizativos en su actividad laboral, utilizando las ofertas formativas a su alcance y localizando los recursos mediante las tecnologías de la información y la comunicación.', 2, 15, 18),
(337, 'r', 'Cumplir las tareas propias de su nivel con autonomía y responsabilidad, empleando criterios de calidad y eficiencia en el trabajo asignado y efectuándolo de forma individual o como miembro de un equipo.', 2, 15, 19),
(338, 's', 'Comunicarse eficazmente, respetando la autonomía y competencia de las distintas personas que intervienen en su ámbito de trabajo, contribuyendo a la calidad del trabajo realizado.', 2, 15, 20),
(339, 't', 'Asumir y cumplir las medidas de prevención de riesgos y seguridad laboral en la realización de las actividades laborales evitando daños personales, laborales y ambientales.', 2, 15, 21),
(340, 'u', 'Cumplir las normas de calidad, de accesibilidad universal y diseño para todos que afectan a su actividad profesional.', 2, 15, 22),
(341, 'v', 'Actuar con espíritu emprendedor, iniciativa personal y responsabilidad en la elección de los procedimientos de su actividad profesional.', 2, 15, 23),
(342, 'w', 'Ejercer sus derechos y cumplir con las obligaciones derivadas de su actividad profesional, de acuerdo con lo establecido en la legislación vigente, participando activamente en la vida económica, social y cultural.', 2, 15, 24);
