th=\"170\">\r\n<p><strong>El Regne de Val&egrave;ncia en la Corona d&rsquo;Arag&oacute;</strong></p>\r\n</td>\r\n<td width=\"53\">\r\n<p>8</p>\r\n</td>\r\n<td width=\"139\">\r\n<p>8 gen. &ndash; 25 gen.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"99\">\r\n<p><strong>UNITAT 7</strong></p>\r\n</td>\r\n<td width=\"170\">\r\n<p><strong>El naixement del mon modern</strong></p>\r\n</td>\r\n<td width=\"53\">\r\n<p>8</p>\r\n</td>\r\n<td width=\"139\">\r\n<p>27 gen. &ndash; 12 feb.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"99\">\r\n<p><strong>UNITAT 8</strong></p>\r\n</td>\r\n<td width=\"170\">\r\n<p><strong>L&rsquo;&egrave;poca dels grans descobriments geogr&agrave;fics</strong></p>\r\n</td>\r\n<td width=\"53\">\r\n<p>8</p>\r\n</td>\r\n<td width=\"139\">\r\n<p>15 feb. &ndash; 3 mar.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"99\">\r\n<p><strong>UNITAT 9</strong></p>\r\n</td>\r\n<td width=\"170\">\r\n<p><strong>L&rsquo;Imperi dels Austries</strong></p>\r\n</td>\r\n<td width=\"53\">\r\n<p>8</p>\r\n</td>\r\n<td width=\"139\">\r\n<p>5 mar. &ndash; 22 mar.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"99\">\r\n<p><strong>UNITAT 10 </strong></p>\r\n</td>\r\n<td width=\"170\">\r\n<p><strong>L&rsquo;Europa del s. XVII</strong></p>\r\n</td>\r\n<td width=\"53\">\r\n<p>8</p>\r\n</td>\r\n<td width=\"139\">\r\n<p>24 mar. &ndash; 23 abr.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"99\">\r\n<p><strong>TERCERA AVALUACI&Oacute;</strong></p>\r\n</td>\r\n<td width=\"170\">\r\n<p><strong>UNITATS 11-12-13-14</strong></p>\r\n</td>\r\n<td width=\"53\">\r\n<p><strong>25 SESSIONS</strong></p>\r\n</td>\r\n<td width=\"139\">\r\n<p><strong>TEMPORALITZACI&Oacute;</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"99\">\r\n<p><strong>UNITAT 11</strong></p>\r\n</td>\r\n<td width=\"170\">\r\n<p><strong>Els habitants del planeta</strong></p>\r\n</td>\r\n<td width=\"53\">\r\n<p>6</p>\r\n</td>\r\n<td width=\"139\">\r\n<p>26 abr. - 7 mai.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"99\">\r\n<p><strong>UNITAT 12</strong></p>\r\n</td>\r\n<td width=\"170\">\r\n<p><strong>La poblaci&oacute; espanyola</strong></p>\r\n</td>\r\n<td width=\"53\">\r\n<p>6</p>\r\n</td>\r\n<td width=\"139\">\r\n<p>10 mai &ndash; 21 mai.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"99\">\r\n<p><strong>UNITAT 13</strong></p>\r\n</td>\r\n<td width=\"170\">\r\n<p><strong>Les societats humanes i els fen&ograve;mens migratoris</strong></p>\r\n</td>\r\n<td width=\"53\">\r\n<p>6</p>\r\n</td>\r\n<td width=\"139\">\r\n<p>24 mai. &ndash; 4 jun.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"99\">\r\n<p><strong>UNITAT 14</strong></p>\r\n</td>\r\n<td width=\"170\">\r\n<p><strong>Les ciutats i els procesos d&rsquo;urbanitzaci&oacute;</strong></p>\r\n</td>\r\n<td width=\"53\">\r\n<p>6</p>\r\n</td>\r\n<td width=\"139\">\r\n<p>7 jun. &ndash; 18 jun.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(2013, 304, 6, '<p style=\"text-align: justify;\"><strong>Unidad 1. La fragmentaci&oacute;n del mundo antiguo</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>Pregunta clave.&nbsp;<em>&iquest;Qu&eacute; sucedi&oacute; con el antiguo Imperio romano?</em></li>\r\n<li>Un reino germ&aacute;nico: los visigodos en Hispania. Visigodos y bizantinos en Valencia</li>\r\n<li>Viaja al pasado.&nbsp;<em>Valerio se convierte en campesino</em></li>\r\n<li>El rinc&oacute;n del arte.&nbsp;<em>La cultura y el arte visigodos</em></li>\r\n<li>Bizancio, el Imperio romano de Oriente</li>\r\n<li>El Imperio carolingio</li>\r\n<li>Descubre.&nbsp;<em>&iquest;C&oacute;mo gobern&oacute; su Imperio Carlomagno?</em></li>\r\n<li>La aparici&oacute;n del Islam</li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><strong>&nbsp;Unidad 2. Al-Andalus</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>Pregunta clave.&nbsp;<em>&iquest;C&oacute;mo se expandi&oacute; el Islam?</em></li>\r\n<li>La conquista de Al-Andalus</li>\r\n<li>La evoluci&oacute;n de Al-Andalus (929-1492)</li>\r\n<li>Viaja al pasado.&nbsp;<em>Hammal, un campesino de la alquer&iacute;a</em></li>\r\n<li>Descubre.&nbsp;<em>Las ciudades de Al-Andalus</em></li>\r\n<li>Descubre.<em>&nbsp;Sarq Al-Andalus, un territorio andalus&iacute;</em></li>\r\n<li>El enigma.<em>&nbsp;&iquest;Cu&aacute;ntos libros ten&iacute;a la biblioteca de al-Hakam?</em></li>\r\n<li>El rinc&oacute;n del arte.&nbsp;<em>El arte andalus&iacute;</em></li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><strong>&nbsp;Unidad 3. La Europa feudal</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>Pregunta clave.&nbsp;<em>&iquest;C&oacute;mo se organizaba la sociedad medieval?</em></li>\r\n<li>La monarqu&iacute;a feudal</li>\r\n<li>Descubre.&nbsp;<em>Los privilegiados: la nobleza</em></li>\r\n<li>Viaja al pasado.&nbsp;<em>Rodrigo es armado caballero</em></li>\r\n<li>Los privilegiados: el clero</li>\r\n<li>El feudo: se&ntilde;ores y campesinos</li>\r\n<li>El enigma.<em>&nbsp;&iquest;Por qu&eacute; era tan dura la vida de los campesinos?</em></li>\r\n<li>Viaja al pasado.<em>&nbsp;Fray Pedro, un monje benedictino</em></li>\r\n</ol>\r\n<p style=\"text-align: justify;\">&nbsp;<strong>Unidad D1. La cultura y el arte del Rom&aacute;nico</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>&iquest;Fue el Rom&aacute;nico un arte esencialmente religioso?</li>\r\n<li>La arquitectura rom&aacute;nica</li>\r\n<li>La pintura y la escultura rom&aacute;nicas</li>\r\n</ol>\r\n<p style=\"text-align: justify;\">&nbsp;<strong>Unidad 4. El origen de los primeros reinos peninsulares (siglos VIII-XIII)</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>Pregunta clave.&nbsp;<em>&iquest;C&oacute;mo se formaron los primeros reinos y condados cristianos</em>?</li>\r\n<li>De reino de Asturias a reino de Le&oacute;n</li>\r\n<li>Los condados y reinos pirenaicos</li>\r\n<li>Descubre.&nbsp;<em>El Camino de Santiago</em></li>\r\n<li>El avance de los reinos cristianos</li>\r\n<li>Viaja al pasado.<em>&nbsp;Gonzalo funda una aldea</em></li>\r\n<li>Descubre.<em>&nbsp;La consolidaci&oacute;n de los reinos peninsulares</em></li>\r\n<li>El enigma.&nbsp;<em>&iquest;A cu&aacute;ntos reyes sirvi&oacute; el Cid Campeador?</em></li>\r\n<li>Descubre.&nbsp;<em>El Rom&aacute;nico en la Pen&iacute;nsula Ib&eacute;rica</em></li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><em>&nbsp;</em><strong>Unidad 5. Las ciudades de la Europa medieval</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>Pregunta clave.&nbsp;<em>&iquest;Por qu&eacute; crecieron las ciudades?</em></li>\r\n<li>Las ciudades medievales</li>\r\n<li>Los grupos sociales</li>\r\n<li>Viaja al pasado.&nbsp;<em>Un d&iacute;a en el mercado de la ciudad</em></li>\r\n<li>La expansi&oacute;n comercial</li>\r\n<li>Europa en la Baja Edad Media</li>\r\n<li>El enigma.<em>&nbsp;&iquest;Qu&eacute; fue la Peste Negra?</em></li>\r\n</ol>\r\n<p style=\"text-align: justify;\">&nbsp;<strong>Unidad D2. La cultura y el arte del G&oacute;tico</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>&iquest;C&oacute;mo se origin&oacute; el arte g&oacute;tico?</li>\r\n<li>La arquitectura g&oacute;tica</li>\r\n<li>La pintura y la escultura g&oacute;ticas</li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><em>&nbsp;</em><strong>Unidad 6. El Reino de Valencia en la Corona de Arag&oacute;n</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>Pregunta clave.&nbsp;<em>&iquest;Por qu&eacute; fue decisiva la batalla de las Navas de Tolosa?</em></li>\r\n<li>Descubre.&nbsp;<em>C&oacute;mo se conquistaron y repoblaron las tierras valencianas</em></li>\r\n<li>El gobierno de los reinos de la Corona de Arag&oacute;n</li>\r\n<li>La expansi&oacute;n de la Corona de Arag&oacute;n (s. XIII-XV)</li>\r\n<li>Viaja al pasado.&nbsp;<em>Bernat, un comerciante del Mediterr&aacute;neo</em></li>\r\n<li>El dinamismo del Reino de Valencia</li>\r\n<li>La Corona de Castilla</li>\r\n<li>El enigma.<em>&nbsp;&iquest;Por qu&eacute; hubo guerras civiles en la Baja Edad Media?</em></li>\r\n<li>Descubre.<em>&nbsp;El G&oacute;tico en la Pen&iacute;nsula Ib&eacute;rica</em></li>\r\n<li>Descubre.<em>&nbsp;El arte g&oacute;tico en el Reino de Valencia</em></li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><strong>&nbsp;Unidad 7. El nacimiento del mundo moderno</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>Pregunta clave.&nbsp;<em>&iquest;Por qu&eacute; la Edad Moderna se inicia en el siglo XV?</em></li>\r\n<li>El Humanismo, una revoluci&oacute;n cultural</li>\r\n<li>La Reforma protestante</li>\r\n<li>La Contrarreforma cat&oacute;lica</li>\r\n<li>El enigma.<em>&nbsp;El Renacimiento,&iquest;ruptura o retorno al pasado?</em></li>\r\n<li>El Renacimiento italiano</li>\r\n<li>La expansi&oacute;n del Renacimiento en Europa</li>\r\n<li>Descubre.&nbsp;<em>El Renacimiento en Espa&ntilde;a</em></li>\r\n<li>Descubre.&nbsp;<em>El Renacimiento valenciano</em></li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><strong><em>&nbsp;</em>Unidad 8. La &eacute;poca de los grandes descubrimientos geogr&aacute;ficos</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>Pregunta clave.&nbsp;<em>&iquest;Qu&eacute; nueva monarqu&iacute;a crearon los Reyes Cat&oacute;licos?</em></li>\r\n<li>La organizaci&oacute;n de la nueva monarqu&iacute;a</li>\r\n<li>Recuperaci&oacute;n econ&oacute;mica y desigualdad social</li>\r\n<li>La llegada a un nuevo continente</li>\r\n<li>El enigma.<em>&nbsp;&iquest;Cu&aacute;l fue el error de Col&oacute;n?</em></li>\r\n<li>Viaja al pasado.&nbsp;<em>Yoali, un campesono azteca</em></li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><em>&nbsp;</em><strong>Unidad 9. El Imperio de los Austrias</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>Pregunta clave.&nbsp;<em>&iquest;C&oacute;mo se form&oacute; el Imperio hisp&aacute;nico?</em></li>\r\n<li>Los conflictos internos. Las German&iacute;as en Valencia</li>\r\n<li>Los esfuerzos por mantener el Imperio.</li>\r\n<li>Am&eacute;rica, un territorio por explorar</li>\r\n<li>Viaja al pasado.&nbsp;<em>Diego, un emigrante de las Indias Occidentales</em></li>\r\n<li>El enigma.<em>&nbsp;&iquest;Qu&eacute; fue la revoluci&oacute;n de los precios?</em></li>\r\n<li>Descubre.<em>&nbsp;&iquest;Por qu&eacute; entr&oacute; en decadencia el Imperio hisp&aacute;nico?</em></li>\r\n<li>La crisis demogr&aacute;fica y econ&oacute;mica</li>\r\n<li>Descubre.<em>&nbsp;&iquest;C&oacute;mo era el Reino de Valencia bajo la monarqu&iacute;a de los Austrias?</em></li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><strong><em>&nbsp;</em>Unidad 10. La Europa del siglo XVII</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>Pregunta clave.&nbsp;<em>&iquest;Fue el siglo XVII una &eacute;poca de crisis en Europa?</em></li>\r\n<li>La Europa del absolutismo</li>\r\n<li>Conflictos en la Europa del siglo XVII</li>\r\n<li>Descubre.<em>&nbsp;El nacimiento de la ciewncia moderna</em></li>\r\n<li>El arte del Barroco</li>\r\n<li>La pintura barroca</li>\r\n<li>El Barroco en Espa&ntilde;a. El Barroco valenciana</li>\r\n<li>Descubre.<em>&nbsp;El Siglo de Oro de la pintura espa&ntilde;ola</em></li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><em>&nbsp;</em><strong>Unidad 11. Los habitantes del planeta</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>La poblaci&oacute;n del planeta</li>\r\n<li>Los pa&iacute;ses y las ciudades m&aacute;s poblados del mundo</li>\r\n<li>La estructura de la poblaci&oacute;n</li>\r\n<li>Descubre.&nbsp;<em>C&oacute;mo son los tipos de pir&aacute;mides de poblaci&oacute;n</em></li>\r\n<li>Din&aacute;micas y tendencias de la poblaci&oacute;n mundial</li>\r\n<li>Los modelos o reg&iacute;menes demogr&aacute;ficos</li>\r\n<li>La poblaci&oacute;n europea</li>\r\n</ol>\r\n<p style=\"text-align: justify;\">&nbsp;<strong>Unidad 12. La poblaci&oacute;n espa&ntilde;ola</strong></p>\r\n<p style=\"text-align: justify;\">Repasa.&nbsp;<em>La organizaci&oacute;n territorial de Espa&ntilde;a</em></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>El volumen de la poblaci&oacute;n espa&ntilde;ola</li>\r\n<li>La distribuci&oacute;n de la poblaci&oacute;n espa&ntilde;ola</li>\r\n<li>Descubre.&nbsp;<em>La estructura de la poblaci&oacute;n espa&ntilde;ola</em></li>\r\n<li>Din&aacute;micas y tendencias de la poblaci&oacute;n espa&ntilde;ola</li>\r\n<li>El poblamiento rural y el poblamiento urbano</li>\r\n</ol>\r\n<p style=\"text-align: justify;\">&nbsp;<strong>Unidad 13. Las sociedades humanas y los fen&oacute;menos migratorios</strong></p>\r\n<ol style=\"text-align: justify;\">\r\n<li>La organizaci&oacute;n de las sociedades</li>\r\n<li>Descubre.&nbsp;<em>La evoluci&oacute;n de la sociedad humana</em></li>\r\n<li>La diversidad de las sociedades europea y espa&ntilde;ola</li>\r\n<li>Las migraciones hoy</li>\r\n<li>Espa&ntilde;a: pa&iacute;s de emigrantes, pa&iacute;s de inmigrantes</li>\r\n<li>An&aacute;lisis de problemas.&nbsp;<em>&iquest;Qui&eacute;nes emigran fuera de Espa&ntilde;a?</em></li>\r\n</ol>\r\n<p style=\"text-align: justify;\">&nbsp;<strong>Unidad 14. Las ciudades y los procesos de urbanizaci&oacute;n</strong></p>\r\n<ol>\r\n<li style=\"text-align: justify;\">&iquest;Qu&eacute; se entiende por ciudad?</li>\r\n<li style=\"text-align: justify;\">La morfolog&iacute;a urbana</li>\r\n<li style=\"text-align: justify;\">La tipolog&iacute;a y la jerarqu&iacute;a mundial de ciudades</li>\r\n<li style=\"text-align: justify;\">Los paisajes urbanos</li>\r\n<li style=\"text-align: justify;\">Descubre.&nbsp;<em>La ciudad como ecosistema humano</em></li>\r\n<li style=\"text-align: justify;\">El espacio urbano espa&ntilde;ol</li>\r\n<li style=\"text-align: justify;\">Estudio de caso.&nbsp;<em>Las smart cities en Espa&ntilde;a</em></li>\r\n</ol>\r\n<p><strong>TEMPORALIZACI&Oacute;N&nbsp;</strong></p>\r\n<table>\r\n<tbody>\r\n<tr>\r\n<td width=\"271\">\r\n<p><strong>SEMANA</strong></p>\r\n</td>\r\n<td width=\"372\">\r\n<p><strong>UU.DD.</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"271\">\r\n<p>Del 14 al 18 de septiembre</p>\r\n</td>\r\n<td width=\"372\">\r\n<p>1-. La Prehistoria</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"271\">\r\n<p>Del 21 al 25 de septiembre</p>\r\n</td>\r\n<td width=\"372\">\r\n<p>1-. La Prehistoria</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"271\">\r\n<p>Del 28 al 2 de octubre</p>\r\n</td>\r\n<td width=\"372\">\r\n<p>2-. Civilizaci&oacute;n egipcia</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"271\">\r\n<p>Del 5 al 8 de octubre</p>\r\n</td>\r\n<td width=\"372\">\r\n<p>2-. Civilizaci&oacute;n egipcia</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"271\">\r\n<p>Del 13 al 16 de octubre</p>\r\n</td>\r\n<td width=\"372\">\r\n<p>3-. Grecia cl&aacute;sica</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"271\">\r\n<p>Del 19 al 23 de octubre</p>\r\n</td>\r\n<td width=\"372\">\r\n<p>3-. Grecia cl&aacute;sica</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"271\">\r\n<p>Del 26 al 30 de octubre</p>\r\n</td>\r\n<td width=\"372\">\