>7</p>\r\n</td>\r\n<td width=\"312\">\r\n<p>Maquillaje y decoraci&oacute;n de u&ntilde;as</p>\r\n</td>\r\n<td width=\"66\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"66\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"65\">\r\n<p>X</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td width=\"56\">\r\n<p>8</p>\r\n</td>\r\n<td width=\"312\">\r\n<p>Fichas de procesos</p>\r\n</td>\r\n<td width=\"66\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"66\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td width=\"65\">\r\n<p>X</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style=\"font-weight: 400;\">TEMPORALIZACI&Oacute;N <strong>RALIZACIO&Igrave;N DE LAS UNIDADES DIDA&Igrave;CTICAS </strong></p>\r\n<p style=\"font-weight: 400;\">13/09: Presentacio&Igrave;n del mo&Igrave;dulo<br />14 /09: Entrega de Capacidades Terminales, evaluacio&Igrave;n y calificaciones</p>\r\n<p style=\"font-weight: 400;\"><strong>1&ordf; EVALUACIO&Igrave;N 2/12/2024</strong></p>\r\n<p style=\"font-weight: 400;\">Tema1 Examen 26/9/2024</p>\r\n<p style=\"font-weight: 400;\">Tema 2. Examen 24/10/2024</p>\r\n<p style=\"font-weight: 400;\">Tema 3 . Examen 28/11/2024</p>\r\n<p style=\"font-weight: 400;\">Tema 4 . Examen 10/1/2025</p>\r\n<p style=\"font-weight: 400;\">&nbsp;</p>\r\n<p style=\"font-weight: 400;\"><strong>2a EVALUACIO&Igrave;N 3/3/2025</strong></p>\r\n<p style=\"font-weight: 400;\">&nbsp;Tema 5 &nbsp; &nbsp;Examen 13/02/2025</p>\r\n<p style=\"font-weight: 400;\">&nbsp;Tema 6 &nbsp; &nbsp;Examen 27/03/2025</p>\r\n<p style=\"font-weight: 400;\">&nbsp;</p>\r\n<p style=\"font-weight: 400;\"><strong>3a EVALUACIO&Igrave;N Y FINAL 5/5/2025</strong></p>\r\n<p style=\"font-weight: 400;\">Tema 7 17/04/2025 &nbsp;Examen.&nbsp;</p>\r\n<p style=\"font-weight: 400;\">Pra&Igrave;cticas finales y anexos durante todo el periodo de la 3&ordf; evaluaci&oacute;n</p>\r\n<p style=\"font-weight: 400;\">&Eacute;xamenes de recuperaci&oacute;n y entrega de trabajos: la semana siguiente al examen de cada tema.</p>'),
