INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3087, 397, 40, '<center>\r\n<table width=\"649\" cellspacing=\"0\" cellpadding=\"7\">\r\n<tbody>\r\n<tr>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #7ba0cd; border-right: 1px solid #ffffff; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"110\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Resultados de aprendizaje</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #ffffff; border-right: 1px solid #ffffff; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"386\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Criterios de evaluaci&oacute;n</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #ffffff; border-right: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"108\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Unidades <br /> de trabajo</strong></span></span></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>1.</strong></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong> Distingue las caracter&iacute;sticas del sector productivo y define los puestos de trabajo relacion&aacute;ndolos con las competencias profesionales expresadas en el t&iacute;tulo</strong></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">.</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">__%</span></span></span></span></span></p>\r\n<p><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>DUALIZA 100%</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">a</span></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">) Se han analizado las principales oportunidades de empleo y de inserci&oacute;n laboral en el sector profesional, identificando las posibilidades de empleo y analizado sus requerimientos actuales para el perfil profesional. __%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">b) Se ha comparado los diferentes requerimientos exigidos por el mercado laboral con las exigencias para el trabajo en la funci&oacute;n p&uacute;blica relacionados con el sector privado. __%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">c) Se ha reflexionado sobre las actitudes y aptitudes requeridas actualmente para la actividad profesional relacionadas con el t&iacute;tulo, as&iacute; como las competencias personales y sociales m&aacute;s relevantes para el sector identificando nuestra zona de desarrollo pr&oacute;ximo. __%</span></span></span></span></span></p>\r\n<p><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>TODOS DUALIZAN </strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"108\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>Unidad 1</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">. An&aacute;lisis del sector profesional</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal; margin-bottom: 0.04cm;\"><br /> </p>\r\n<p style=\"font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>2. Alcanza las competencias necesarias para la obtenci&oacute;n del t&iacute;tulo de T&eacute;cnico B&aacute;sico en Prevenci&oacute;n de Riesgos Laborales</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">.</span></span></span></span></span></p>\r\n<p><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">30</span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong> %</strong></span></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">a) Se ha valorado la importancia de la cultura preventiva en todos los &aacute;mbitos actividades de la empresa u organismo equiparado relacionado las condiciones laborales con la salud de la persona trabajadora identificando y clasificando los factores de riesgo en la actividad y los da&ntilde;os derivados de los mismos, especialmente las situaciones de riesgo m&aacute;s habituales en los entornos de trabajo del sector profesional relacionado con el t&iacute;tulo. _4_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">b) Se han clasificado y descrito los tipos de da&ntilde;os profesionales, con especial referencia a accidentes de trabajo y enfermedades profesionales, relacionados con el perfil profesional del t&iacute;tulo. 4%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">c) Se ha determinado la evaluaci&oacute;n de riesgos en la empresa u organismo equiparado y definido las t&eacute;cnicas de prevenci&oacute;n y de protecci&oacute;n que deben aplicarse para evitar los da&ntilde;os en su origen y minimizar sus consecuencias. _3_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">d) Se han analizado los protocolos de actuaci&oacute;n en caso de emergencia. 3__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">e) Se han determinado los principales derechos y deberes en materia de prevenci&oacute;n de riesgos laborales. 4__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">f) Se han clasificado las distintas formas de gesti&oacute;n de la prevenci&oacute;n en la empresa u organismo equiparado, en funci&oacute;n de los distintos criterios establecidos en la normativa sobre prevenci&oacute;n de riesgos laborales y determinado las formas de representaci&oacute;n de las personas trabajadoras en la empresa u organismo equiparado en materia de prevenci&oacute;n de riesgos.</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">3__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #00000