(3090, 398, 40, '<p class=\"western\" style=\"line-height: 0.56cm; margin-bottom: 0.21cm;\"><span style=\"font-family: Bookman Old Style, serif;\"><span style=\"font-size: small;\">Los resultados de aprendizaje estan incluidos en el apartado 3.3 Resultados de aprendizaje<br /></span></span></p>\r\n<p class=\"western\" style=\"line-height: 0.56cm; margin-bottom: 0.21cm;\">&nbsp;</p>\r\n<p>&nbsp;</p>'),
