INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3093, 396, 38, '<p>Los Resultados de aprendizaje, que se dualizan en la empresa son:</p>\r\n<center>\r\n<table width=\"649\" cellspacing=\"0\" cellpadding=\"7\">\r\n<tbody>\r\n<tr>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #7ba0cd; border-right: 1px solid #ffffff; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"110\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Resultados de aprendizaje</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #ffffff; border-right: 1px solid #ffffff; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"386\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Criterios de evaluaci&oacute;n</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #ffffff; border-right: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"108\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Unidades <br /> de trabajo</strong></span></span></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>1.</strong></span></span></span></span> <span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>Distingue las caracter&iacute;sticas del sector productivo y define los puestos de trabajo relacion&aacute;ndolos con las competencias profesionales expresadas en el t&iacute;tulo.</strong></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">__%</span></span></span></span></span></p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>DUALIZA 100%</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">a</span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">) Se han analizado las principales oportunidades de empleo y de inserci&oacute;n laboral en el sector profesional, identificando las posibilidades de empleo y analizado sus requerimientos actuales para el perfil profesional. __%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">b) Se ha comparado los diferentes requerimientos exigidos por el mercado laboral con las exigencias para el trabajo en la funci&oacute;n p&uacute;blica relacionados con el sector privado. __%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">c) Se ha reflexionado sobre las actitudes y aptitudes requeridas actualmente para la actividad profesional relacionadas con el t&iacute;tulo, as&iacute; como las competencias personales y sociales m&aacute;s relevantes para el sector identificando nuestra zona de desarrollo pr&oacute;ximo. __%</span></span></span></span></span></p>\r\n<p><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>TODOS DUALIZAN </strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"108\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>Unidad 1</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">. An&aacute;lisis del sector profesional</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"font-style: normal; margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>5. Aplica las estrategias para el aprendizaje aut&oacute;nomo reconociendo su valor profesionalizador, dise&ntilde;ando y optimizando su propio entorno de aprendizaje haciendo uso de las tecnolog&iacute;as digitales como herramientas de aprendizaje aut&oacute;nomo, siendo coherente con su identidad digital y sus propios objetivos profesionales planteados en su plan de desarrollo individual.</strong></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\">_5_%</span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">a) Se ha tomado conciencia de la responsabilidad individual en el desarrollo profesional valorando la actitud de aprendizaje permanente para el desarrollo de propias y nuevas competencias. 1__% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">b) Se ha identificado la empleabilidad como capacidad de adaptaci&oacute;n al entorno laboral. _1_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">c) Se han conocido y utilizado herramientas, fuentes de informaci&oacute;n, conexiones y actividades para la configuraci&oacute;n de un entorno personal de aprendizaje para la empleabilidad. _1_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">d) Se ha puesto en pr&aacute;ctica la competencia digital para configurar un entorno personal de aprendizaje para la empleabilidad. _1_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">e) Se ha analizado el concepto de identidad digital y su impacto en la empleabilidad. _1_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>AULA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">f) Se ha justificado el dise&ntilde;o de su entorno de aprendizaje basado en c&oacute;mo este mejora la empleabilidad. __% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">g) Se ha elaborado su plan de desarrollo individual como herramienta para la mejora de la empleabilidad. _2_%</span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong> AULA</strong></span></span></span></span> </span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">h) Se han aplicado las herramientas de aprendizaje aut&oacute;nomo para su desarrollo personal y profesional. _1_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>AULA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">i) Se ha dise&ntilde;ado el entorno de aprendizaje que permite alcanzar el plan de desarrollo individual. _1_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>AULA</strong></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"108\">\r\n<p style=\"font-style: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"font-style: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"font-style: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"font-style: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>Unidad 11.</strong></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\"> El aprendizaje aut&oacute;nomo y la competencia digital.</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><em><strong>Proyecto 4.</strong></em></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><em><span style=\"font-weight: normal;\"> Genera tu entorno personal de aprendizaje.</span></em></span></span></span></span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</center>'),
(3094, 396, 39, ''),
(3095, 396, 40, '<p>No se dualiza el m&oacute;dulo de IPE I</p>\r\n<h2>&nbsp;</h2>'),
(3096, 396, 19, '<p style=\"line-height: 100%; margin-bottom: 0cm;\">EXTRAESCOLARES</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\">1. Salida Feria Orientaci&oacute;n Mutxamel con 4&ordm; ESO FOPP</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\">2. Salida Feria Empleo con 1DAW, 1SMRA, 1SMRC</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\">&nbsp;</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\">COMPLEMENTARIAS</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\">1. Charlas de SECOT para FOPP, 1SMRA, 1SMRC, 2DAW (plan FEM FUTUR).</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\">2. Talleres de primeros auxilios y otras charlas de la Cruz Roja para FOPP, 1SMRA, 1SMRC, 1DAW.</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\">3. Charlas AEAT para FOPP (tienen un tema de educaci&oacute;n fiscal), 1SMRA, 1SMRC, 1DAW.&nbsp;</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\">4. Charlas de empresario/as de Inform&aacute;tica para 2DAW.</p>'),
(3097, 18, 2, '<p>Esta programaci&oacute;n est&aacute; desarrollada para el centro en el que se imparte, el I.E.S San Vicente.</p>\r\n<p>El I.E.S San Vicente es un centro p&uacute;blico ubicado en el n&uacute;cleo urbano de San Vicente, el cual cuenta con una poblaci&oacute;n que ronda los 55.000 habitantes, donde acuden numerosos alumnos y alumnas de zonas cercanas con menor poblaci&oacute;n, como puede ser Agost, en r&eacute;gimen diurno y vespertino.</p>\r\n<p>Las variables del entorno general del centro son las siguientes:</p>\r\n<p>- Climatolog&iacute;a: Veranos calurosos y temperaturas moderadas en invierno, con escasas lluvias.</p>\r\n<p>- Sistema de comunicaciones: El centro est&aacute; bien comunicado, tanto de forma interna (transporte p&uacute;blico) como externa (carreteras de todo tipo). Adem&aacute;s, est&aacute; pr&oacute;ximo a la salida del mismo. Este factor facilita las posibilidades de desplazamiento para actividades extraescolares y complementarias.</p>\r\n<p>- Nivel de renta familiar: La gran mayor&iacute;a del alumnado que acude al centro pertenece a familias de un nivel socio-econ&oacute;mico medio-alto.</p>\r\n<p>- Tejido empresarial: Predominan las peque&ntilde;as y medianas empresas del sector servicios, las cuales satisfacen las necesidades del sector industrial de la zona. Como consecuencia, existe una creciente demanda de profesionales del sector TICs.</p>\r\n<p>Respecto a las caracter&iacute;sticas concretas del centro, se trata de un instituto con amplia oferta educativa, y que cuenta con una gran cantidad de recursos humanos y tecnol&oacute;gicos.</p>\r\n<p>Se concretan a continuaci&oacute;n las variables del entorno espec&iacute;fico:</p>\r\n<ul>\r\n<li>Oferta educativa: Adem&aacute;s de ESO y Bachillerato, el instituto ofrece ciclos formativos de las siguientes familias profesionales: Administraci&oacute;n y Gesti&oacute;n, Imagen Personal, Inform&aacute;tica y Comunicaciones as&iacute; como cursos de especializaci&oacute;n de esta &uacute;ltima familia. Algunos de los ciclos ofertados presentan adem&aacute;s modalidad dual y semipresencial.</li>\r\n<li>Alumnado: Hay un total de 1800 alumnos y alumnas matriculados en el instituto y existe cierta diversidad multicultural, pero en su mayor&iacute;a son estudiantes ya nacidos en Espa&ntilde;a y conocen el idioma.</li>\r\n<li>Profesorado: Hay un total de 175 docentes en el centro, siendo el departamento de inform&aacute;tica el m&aacute;s numeroso de todos, con un total de 48 docentes.</li>\r\n<li>Instalaciones y equipamientos: El instituto cuenta con biblioteca, aula de convivencia, aulas de usos m&uacute;ltiples y aulas inform&aacute;ticas con adecuados recursos tecnol&oacute;gicos (ordenadores para alumnado y profesorado, pantallas digitales t&aacute;ctiles, proyectores&hellip;).</li>\r\n<li>Barreras arquitect&oacute;nicas: El centro carece de ellas, ya que cuenta con acceso para personas con movilidad reducida y ascensor.</li>\r\n<li>Programas educativos y de innovaci&oacute;n: Se llevan a cabo en secundaria programas de educaci&oacute;n biling&uuml;e y en ciclos formativos, algunos m&oacute;dulos se imparten en ingl&eacute;s o valenciano.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Respecto al perfil concreto del alumnado del m&oacute;dulo de \"LMSGI\", al estar enmarcado en un ciclo de grado superior, suele contar con las siguientes caracter&iacute;sticas:</p>\r\n<ol>\r\n<li>Son mayores de edad.</li>\r\n<li>Muestran inter&eacute;s y motivaci&oacute;n por adquirir competencias.</li>\r\n<li>Cuentan con ciertos conocimientos espec&iacute;ficos, ya que vienen de superar Bachillerato, de terminar otros estudios de Formaci&oacute;n Profesional, o incluso interrumpir o finalizar una carrera universitaria.</li>\r\n<li>Tienen claro el camino profesional que quieren seguir.</li>\r\n<li>Presentan inquietudes profesionales.</li>\r\n</ol>'),
(3098, 18, 25, ''),
(3100, 18, 23, '<p>Los instrumentos de evaluaci&oacute;n empleados tanto en el plano conceptual, como procedimental como actitudinal, ser&aacute;n los siguientes:</p>\r\n<table border=\"1\">\r\n<tbody>\r\n<tr>\r\n<th>Tipo de instrumento</th>\r\n<th>Intrumento</th>\r\n<th>Descripci&oacute;n</th>\r\n</tr>\r\n<tr>\r\n<td>Conceptuales y procedimentales</td>\r\n<td>I1</td>\r\n<td>Pruebas objetivas globales: Aquellas que vienen referidas a los contenidos de una o unidades did&aacute;cticas, como ser&aacute;n los cuestionarios, tests o examenes.</td>\r\n</tr>\r\n<tr>\r\n<td>Conceptuales y procedimentales</td>\r\n<td>I2</td>\r\n<td>Trabajos individuales: Supuestos pr&aacute;cticos, ejercicios y actividades del estudiante de forma unitaria.</td>\r\n</tr>\r\n<tr>\r\n<td>Conceptuales y procedimentales</td>\r\n<td>I3</td>\r\n<td>Tareas grupales y proyectos: Aquellos que el alumno lleva a cabo junto a otros/as compa&ntilde;eros/as, como es el caso de actividades pr&aacute;cticas y proyectos.</td>\r\n</tr>\r\n<tr>\r\n<td>Actitudinales</td>\r\n<td>I4</td>\r\n<td>Participaci&oacute;n en debates, foros y predisposici&oacute;n a intervenir en el proceso de aprendizaje, valorada mediante r&uacute;brica: Se refiere a la actividad y al inter&eacute;s mostrado en dichas tareas comunicativas, adem&aacute;s de la participaci&oacute;n y la atenci&oacute;n en las sesiones.</td>\r\n</tr>\r\n<tr>\r\n<td>Actitudinales</td>\r\n<td>I5</td>\r\n<td>Participaci&oacute;n activa en grupos de trabajo, valorada mediante r&uacute;brica: Vinculado al esfuerzo, la cooperaci&oacute;n y el desempe&ntilde;o en las tareas grupales y de proyecto.</td>\r\n</tr>\r\n<tr>\r\n<td>Actitudinales</td>\r\n<td>I6</td>\r\n<td>Orden y limpieza en la presentaci&oacute;n de tareas, valorada mediante r&uacute;brica: En las tareas redactadas, en las orales y tambi&eacute;n en las resueltas con c&oacute;digo.</td>\r\n</tr>\r\n<tr>\r\n<td>Actitudinales</td>\r\n<td>I7</td>\r\n<td>Informe de cumplimiento en los plazos de entrega: Un instrumento muy importante vinculado a la puntualidad y a la seriedad en el trabajo.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(3102, 18, 15, '<p>Para atender las diversas necesidades educativas del aula, se contemplar&aacute;n las siguientes medidas:</p>\r\n<ol>\r\n<li>Desarrollo de cuestionarios de diagn&oacute;stico previo, los cuales permitir&aacute;n detectar el nivel de conocimientos y motivaci&oacute;n del alumnado, de forma que el docente pueda valorar el punto de partida y las estrategias a seguir.</li>\r\n<li>Flexibilizaci&oacute;n de los tiempos de entrega de las diferentes tareas.</li>\r\n<li>Propuesta de actividades con diferente grado de dificultad, como es el caso de las actividades de ampliaci&oacute;n o refuerzo, atendiendo a las capacidades e inter&eacute;s de los estudiantes.</li>\r\n<li>Selecci&oacute;n de perfiles \"analista\" y \"gestor\", en los ejercicios de trabajo en grupo, entre aquellos estudiantes que muestren mayor destreza, de forma que sean ellos mismos quienes apoyen al resto de miembros de su equipo de trabajo</li>\r\n</ol>\r\n<p>Y en general, todos aquellos cambios en la metodolog&iacute;a que el docente identifique como precisos, consultando con el departamento de orientaci&oacute;n y jefatura de estudios cuando se requiera.</p>'),
(3103, 18, 17, '<p>Los materiales f&iacute;sicos empleados en el m&oacute;dulo consistir&aacute;n principalmente en un aula de inform&aacute;tica con pizarra, conexi&oacute;n a Internet, proyector o PDI y equipos inform&aacute;ticos conectados en red, tanto para el profesorado como para el alumnado.</p>\r\n<p>A nivel software se utilizar&aacute; la plataforma AULES como repositorio de materiales y entregas, adem&aacute;s del software propio para trabajar en el m&oacute;dulo entre el cual se encontrar&aacute; XAMPP.</p>'),
(3104, 18, 31, '<p>En la medida de lo posible se deber&aacute;n priorizar y facilitar al m&aacute;ximo los medios telem&aacute;ticos para realizar cualquier tipo de comunicaci&oacute;n entre los profesores y las familias o los alumnos. Por ello, se utilizar&aacute;n los canales que se enumeran a continuaci&oacute;n.</p>'),
(3105, 18, 33, '<p>Es la plataforma proporcionada por la Conselleria de Educaci&oacute;n, Cultura y Deporte para mantener comunicaci&oacute;n entre los centros educativos y los alumnos y sus familias. Por ello, se utilizar&aacute; como canal oficial para comunicar y transmitir telem&aacute;ticamente toda la informaci&oacute;n y el seguimiento de los alumnos.</p>'),
(3106, 18, 32, '<p>A pesar de no tratarse de una plataforma dise&ntilde;ada espec&iacute;ficamente para la comunicaci&oacute;n con las familias o los alumnos, estos podr&aacute;n hacer uso de sus credenciales para estar al corriente de los avances que se vayan realizando durante el curso, e incluso recibir notificaciones en sus dispositivos m&oacute;viles y/o correo electr&oacute;nico.</p>'),
(3107, 18, 36, '<p>Se trata de una plataforma de videoconferencias que facilita las reuniones en l&iacute;nea y los seminarios web.</p>\r\n<p>El IES San Vicente dispone de acceso a las herramientas de Microsoft Teams, con lo que dicho canal de comunicaci&oacute;n tambi&eacute;n podr&aacute; ser utilizado durante el presente curso acad&eacute;mico.</p>'),
(3108, 18, 34, '<p>Todo el personal docente en centros educativos de la Generalitat Valenciana dispone de una direcci&oacute;n de correo electr&oacute;nico de uso corporativo. Por ello, tambi&eacute;n se utilizar&aacute; el env&iacute;o de correos electr&oacute;nicos como medio de comunicaci&oacute;n.</p>'),
(3109, 18, 35, '<p>Eventualmente tambi&eacute;n se utilizar&aacute; el tel&eacute;fono del centro como canal de comunicaci&oacute;n, siempreque el centro se encuentre abierto.</p>'),
(3111, 366, 1, '<p>El presente documento corresponde a la programaci&oacute;n did&aacute;ctica del m&oacute;dulo de&nbsp;<strong>Proyecto Intermodular</strong>, que se imparte en el primer curso del ciclo formativo de grado superior de&nbsp;<strong>Desarrollo de Aplicaciones Multiplataforma</strong>, en adelante DAM.</p>\r\n<p>Este modulo&nbsp;se desarrolla a lo largo de los tres trimestres del curso acad&eacute;mico distribuido en una carga horaria de 1 hora semanal.</p>\r\n<p>Las bases legislativas m&aacute;s relevantes que fundamentan esta programaci&oacute;n did&aacute;ctica son las siguientes:</p>\r\n<p>a) Ley Org&aacute;nica 3/2020, de 29 de diciembre (LOMLOE), por la que se modifica la Ley Org&aacute;nica 2/2006, de 3 de mayo, de Educaci&oacute;n (LOE)</p>\r\n<p>b) Real Decreto 1147/2011, de 29 de julio, por el que se establece la ordenaci&oacute;n general de la formaci&oacute;n profesional del sistema educativo.</p>\r\n<p>c) RESOLUCI&Oacute;N de 8 de agosto de 2024, de la Secretar&iacute;a Auton&oacute;mica de Educaci&oacute;n, por la cual se dictan instrucciones sobre ordenaci&oacute;n acad&eacute;mica y de organizaci&oacute;n de los centros que imparten Formaci&oacute;n Profesional durante el curso 2024-2025 en la Comunitat Valenciana.</p>\r\n<p>d) DECRETO 252/2019, de 29 de noviembre, del Consell, de regulaci&oacute;n de la organizaci&oacute;n y el funcionamiento de los centros p&uacute;blicos que imparten ense&ntilde;anzas de Educaci&oacute;n Secundaria Obligatoria, Bachillerato y Formaci&oacute;n Profesional.</p>\r\n<p>e) ORDEN 79/2010, de 27 de agosto, de la Conselleria de Educaci&oacute;n, por la que se regula la evaluaci&oacute;n del alumnado de los ciclos formativos de Formaci&oacute;n Profesional del sistema educativo en el &aacute;mbito territorial de la Comunitat Valenciana.</p>\r\n<p>f) Real Decreto 405/2023, de 29 de mayo, por el que se actualizan los t&iacute;tulos de la formaci&oacute;n profesional del sistema educativo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Multiplataforma y T&eacute;cnico Superior en Desarrollo de Aplicaciones Web, y se fijan sus ense&ntilde;anzas m&iacute;nimas.</p>\r\n<p>g) Real Decreto de T&iacute;tulo 450/2010 de 16 de abril, por el que se establece el t&iacute;tulo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Multiplataforma y se fijan sus ense&ntilde;anzas m&iacute;nimas.</p>\r\n<p>h) Orden 58/2012 de 5 de septiembre por la que se establece el curr&iacute;culo correspondiente al t&iacute;tulo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Multiplataforma para la Comunidad Valenciana.</p>\r\n<p>i)&nbsp;Real Decreto 659/2023, de 18 de julio, por el que se desarrolla la ordenaci&oacute;n del Sistema de Formaci&oacute;n Profesional.</p>\r\n<p>j) Real Decreto 500/2024, de 21 de mayo, por el que se modifican determinados reales decretos por los que se establecen t&iacute;tulos de Formaci&oacute;n Profesional de grado superior y se fijan sus ense&ntilde;anzas m&iacute;nimas.</p>'),
(3112, 366, 2, '<p>Esta programaci&oacute;n est&aacute; desarrollada para el centro en el que se imparte, el I.E.S San Vicente.</p>\r\n<p>El I.E.S San Vicente es un centro p&uacute;blico ubicado en el n&uacute;cleo urbano de San Vicente, el cual cuenta con una poblaci&oacute;n que ronda los 55.000 habitantes, donde acuden numerosos alumnos y alumnas de zonas cercanas con menor poblaci&oacute;n, como puede ser Agost, en r&eacute;gimen diurno y vespertino.</p>\r\n<p>Las variables del entorno general del centro son las siguientes:</p>\r\n<p>- Climatolog&iacute;a: Veranos calurosos y temperaturas moderadas en invierno, con escasas lluvias.</p>\r\n<p>- Sistema de comunicaciones: El centro est&aacute; bien comunicado, tanto de forma interna (transporte p&uacute;blico) como externa (carreteras de todo tipo). Adem&aacute;s, est&aacute; pr&oacute;ximo a la salida del mismo. Este factor facilita las posibilidades de desplazamiento para actividades extraescolares y complementarias.</p>\r\n<p>- Nivel de renta familiar: La gran mayor&iacute;a del alumnado que acude al centro pertenece a familias de un nivel socio-econ&oacute;mico medio-alto.</p>\r\n<p>- Tejido empresarial: Predominan las peque&ntilde;as y medianas empresas del sector servicios, las cuales satisfacen las necesidades del sector industrial de la zona. Como consecuencia, existe una creciente demanda de profesionales del sector TICs.</p>\r\n<p>Respecto a las caracter&iacute;sticas concretas del centro, se trata de un instituto con amplia oferta educativa, y que cuenta con una gran cantidad de recursos humanos y tecnol&oacute;gicos.</p>\r\n<p>Se concretan a continuaci&oacute;n las variables del entorno espec&iacute;fico:</p>\r\n<ul>\r\n<li>Oferta educativa: Adem&aacute;s de ESO y Bachillerato, el instituto ofrece ciclos formativos de las siguientes familias profesionales: Administraci&oacute;n y Gesti&oacute;n, Imagen Personal, Inform&aacute;tica y Comunicaciones as&iacute; como cursos de especializaci&oacute;n de esta &uacute;ltima familia. Algunos de los ciclos ofertados presentan adem&aacute;s modalidad dual y semipresencial.</li>\r\n<li>Alumnado: Hay un total de 1800 alumnos y alumnas matriculados en el instituto y existe cierta diversidad multicultural, pero en su mayor&iacute;a son estudiantes ya nacidos en Espa&ntilde;a y conocen el idioma.</li>\r\n<li>Profesorado: Hay un total de 175 docentes en el centro, siendo el departamento de inform&aacute;tica el m&aacute;s numeroso de todos, con un total de 48 docentes.</li>\r\n<li>Instalaciones y equipamientos: El instituto cuenta con biblioteca, aula de convivencia, aulas de usos m&uacute;ltiples y aulas inform&aacute;ticas con adecuados recursos tecnol&oacute;gicos (ordenadores para alumnado y profesorado, pantallas digitales t&aacute;ctiles, proyectores&hellip;).</li>\r\n<li>Barreras arquitect&oacute;nicas: El centro carece de ellas, ya que cuenta con acceso para personas con movilidad reducida y ascensor.</li>\r\n<li>Programas educativos y de innovaci&oacute;n: Se llevan a cabo en secundaria programas de educaci&oacute;n biling&uuml;e y en ciclos formativos, algunos m&oacute;dulos se imparten en ingl&eacute;s o valenciano.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Respecto al perfil concreto del alumnado del m&oacute;dulo de \"Bases de datos\", en adelante BBDD, al estar enmarcado en un ciclo de grado superior, suele contar con las siguientes caracter&iacute;sticas:</p>\r\n<ol>\r\n<li>Son mayores de edad.</li>\r\n<li>Muestran inter&eacute;s y motivaci&oacute;n por adquirir competencias.</li>\r\n<li>Cuentan con ciertos conocimientos espec&iacute;ficos, ya que vienen de superar Bachillerato, de terminar otros estudios de Formaci&oacute;n Profesional, o incluso interrumpir o finalizar una carrera universitaria.</li>\r\n<li>Tienen claro el camino profesional que quieren seguir.</li>\r\n<li>Presentan inquietudes profesionales.</li>\r\n</ol>'),
(3113, 366, 25, ''),
(3115, 366, 7, '<p style=\"font-size: 1.1em; display: inline !important;\">Los&nbsp;<strong>principios metodol&oacute;gicos</strong>&nbsp;que se aplicar&aacute;n en el m&oacute;dulo ser&aacute;n los siguientes:</p>\r\n<p style=\"font-size: 1.1em;\"><strong>PM1</strong>: Establecer relaciones significativas entre los nuevos conocimientos y los ya establecidos o con las experiencias previas del alumnado.</p>\r\n<p style=\"font-size: 1.1em;\"><strong>PM2</strong>: Usar estrategias de presentaci&oacute;n organizadas y atractivas, con el objetivo de aumentar la motivaci&oacute;n del alumnado.</p>\r\n<p style=\"font-size: 1.1em;\"><strong>PM3</strong>: Fomentar la interacci&oacute;n alumnado-profesorado y alumnado-alumnado para la confrontaci&oacute;n de puntos de vista, toma de decisiones, y la superaci&oacute;n de conflictos mediante di&aacute;logo y cooperaci&oacute;n.</p>\r\n<p style=\"font-size: 1.1em;\"><strong>PM4</strong>: Garantizar la funcionalidad de los aprendizajes, asegurando que puedan ser utilizados en las circunstancias reales en que el estudiante los necesite.</p>\r\n<p style=\"font-size: 1.1em;\"><strong>PM5</strong>: Ajustar la ayuda pedag&oacute;gica a las distintas necesidades del alumnado, y facilitar recursos o estrategias variadas para responder a sus motivaciones, intereses y capacidades.</p>\r\n<p style=\"font-size: 1.1em;\"><strong>PM6</strong>: Realizar la evaluaci&oacute;n de forma continua y personalizada, respecto al estudiante en su desarrollo y aport&aacute;ndole informaci&oacute;n sobre sus progresos, sin comparar con normas est&aacute;ndar de rendimiento.</p>\r\n<p style=\"font-size: 1.1em;\"><strong>PM7</strong>: Presentar los contenidos con una estructuraci&oacute;n clara de sus relaciones, planteando la interrelaci&oacute;n entre distintos contenidos de una materia y de distintas materias.</p>\r\n<p style=\"font-size: 1.1em;\">&nbsp;</p>\r\n<p style=\"font-size: 1.1em;\">En base a los principios del apartado anterior, se establecen estas&nbsp;<strong><u>estrategias de ense&ntilde;anza-aprendizaje</u></strong>&nbsp;para el presente m&oacute;dulo:</p>\r\n<ul style=\"font-size: 1.1em;\">\r\n<li>Conocimiento de las preconcepciones del alumnado, para detectar posibles ideas err&oacute;neas y para construir los nuevos conocimientos a partir de las ideas previas.\r\n<ul>\r\n<li>T&eacute;cnicas: debates interrogativos y cuestionarios antes de exponer nuevos contenidos.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de introducci&oacute;n y motivaci&oacute;n.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<ul style=\"font-size: 1.1em;\">\r\n<li>Tratamiento de posibles situaciones problem&aacute;ticas, dirigiendo el docente el proceso de aprendizaje para detectar a tiempo los problemas de comprensi&oacute;n y resolverlos eficazmente.\r\n<ul>\r\n<li>T&eacute;cnicas: llevar a cabo un seguimiento especial del alumnado al tratar contenidos complejos, dando mucho feedback en la correcciones y realizando actividades junto a ellos.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de descubrimiento dirigido.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<ul style=\"font-size: 1.1em;\">\r\n<li>Identificaci&oacute;n de las ideas fundamentales, haci&eacute;ndose especial hincapi&eacute; en determinados contenidos y actividades y promoviendo la consolidaci&oacute;n de los contenidos prioritarios.\r\n<ul>\r\n<li>T&eacute;cnicas: exposici&oacute;n con mayor detenimiento de los contenidos prioritarios y realizaci&oacute;n de varias actividades sobre cada uno de&nbsp; ellos, para afianzar el aprendizaje.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de consolidaci&oacute;n.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<ul style=\"font-size: 1.1em;\">\r\n<li>Conexi&oacute;n de los contenidos con el entorno y su funcionalidad, para que el alumnado vea la utilidad de lo que aprende y conozca su aplicaci&oacute;n real en la empresa, a partir de las actividades.\r\n<ul>\r\n<li>T&eacute;cnicas: relaci&oacute;n de los contenidos explicados con los perfiles profesionales de programador web, as&iacute; como realizaci&oacute;n de&nbsp; &nbsp; actividades y ejemplos vinculados al mundo laboral.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de consolidaci&oacute;n, pr&aacute;cticas y complementarias.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<ul style=\"font-size: 1.1em;\">\r\n<li>Promoci&oacute;n de la autonom&iacute;a del alumnado en su propio aprendizaje, fomentando la capacidad del estudiante para buscar la informaci&oacute;n necesaria para desempe&ntilde;ar su trabajo, as&iacute; como su capacidad de adaptaci&oacute;n a situaciones diferentes que podr&iacute;an darse en el entorno laboral.\r\n<ul>\r\n<li>T&eacute;cnicas: proveer al alumnado de direcciones web fiables y pautas para buscar informaci&oacute;n de cara a realizar las actividades&nbsp; &nbsp;propuestas. Adem&aacute;s, en las actividades de investigaci&oacute;n, dejar un margen amplio para el desarrollo de sus propios criterios y creatividad.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de investigaci&oacute;n y proyectos.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<ul style=\"font-size: 1.1em;\">\r\n<li>Potenciaci&oacute;n de la participaci&oacute;n del alumnado para fomentar su capacidad para hablar en p&uacute;blico y su expresi&oacute;n oral. Tambi&eacute;n se favorece el respeto hacia las opiniones de los dem&aacute;s.\r\n<ul>\r\n<li>T&eacute;cnicas: m&eacute;todo interrogativo durante las explicaciones, exposici&oacute;n de actividades realizadas por los estudiantes y debates sobre&nbsp; los contenidos del m&oacute;dulo relacionados con temas de actualidad.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de introducci&oacute;n/motivaci&oacute;n y comunicaci&oacute;n de resultados.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<ul style=\"font-size: 1.1em;\">\r\n<li>Alta relevancia del apoyo visual en las explicaciones, para facilitar la asimilaci&oacute;n de ciertos contenidos y simplificar la interiorizaci&oacute;n de aquellos que se usar&aacute;n con asiduidad durante el curso.\r\n<ul>\r\n<li>T&eacute;cnicas: utilizar materiales con un alto nivel de ilustraci&oacute;n como infograf&iacute;as y v&iacute;deos e incluir algunos mapas conceptuales.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: se aplicar&aacute; en todo tipo de actividades.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<ul style=\"font-size: 1.1em;\">\r\n<li>Impulso del trabajo en grupo, apostando en ciertas unidades por el desarrollo de tareas de forma colectiva, siempre tomando las medidas preventivas para asegurar la participaci&oacute;n de todos los integrantes del equipo y para llevar a cabo una evaluaci&oacute;n y un seguimiento justo del proceso.\r\n<ul>\r\n<li>T&eacute;cnicas: alternar tareas individuales con grupales, y tambi&eacute;n tareas breves con otras m&aacute;s largas.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de introducci&oacute;n/motivaci&oacute;n, de investigaci&oacute;n y proyectos.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p style=\"font-size: 1.1em;\">&nbsp;</p>\r\n<p style=\"font-size: 1.1em;\">Como resultado de todo ello, se contar&aacute;n con los siguientes&nbsp;<strong><u>tipos de actividades</u></strong>:</p>\r\n<ol style=\"font-size: 1.1em;\">\r\n<li>De introducci&oacute;n-motivaci&oacute;n. Se realizar&aacute;n en la primera sesi&oacute;n de trabajo de algunas de las unidades did&aacute;cticas. Se dirigir&aacute;n a promover la curiosidad del estudiante intentando despertar su inter&eacute;s.</li>\r\n<li>De desarrollo o actividades productivas. Las cuales adem&aacute;s podr&aacute;n ser de descubrimiento dirigido, investigaci&oacute;n o exposici&oacute;n oral.</li>\r\n<li>Actividades de consolidaci&oacute;n. Ser&aacute;n actividades nuevas, pero en ellas se repetir&aacute;n algunos contenidos que ya hab&iacute;an sido trabajados anteriormente, con el objetivo de afianzar lo aprendido y reforzar aquellos contenidos que se consideran m&aacute;s importantes.</li>\r\n<li>Proyectos. Estas actividades tendr&aacute;n una extensi&oacute;n m&aacute;s larga que el resto, y podr&aacute;n ser tanto de car&aacute;cter individual como de car&aacute;cter grupal.</li>\r\n<li>De refuerzo. Ir&aacute;n dirigidas a estudiantes que tienen dificultades para alcanzar los objetivos previstos para una unidad did&aacute;ctica, a fin de que estos puedan alcanzar los mismos.</li>\r\n<li>De ampliaci&oacute;n. Ir&aacute;n dirigidas a estudiantes que alcancen los objetivos previstos antes de lo esperado, y que puedan alcanzar niveles de conocimiento superiores al exigido. Por lo general ser&aacute;n apartados extra &ndash;de car&aacute;cter voluntario&ndash; que se a&ntilde;adir&aacute;n a las actividades obligatorias.</li>\r\n<li>De evaluaci&oacute;n. Tienen como finalidad determinar el nivel de consecuci&oacute;n de capacidades adquiridas por el estudiante.</li>\r\n<li>De recuperaci&oacute;n. Son actividades destinadas a aquellos estudiantes que, una vez ha terminado el proceso de evaluaci&oacute;n, han obtenido calificaciones negativas.</li>\r\n</ol>'),
(3117, 366, 23, '<p>Los instrumentos de evaluaci&oacute;n empleados tanto en el plano conceptual, como procedimental como actitudinal, ser&aacute;n los siguientes:</p>\r\n<table border=\"1\" cellpadding=\"5\">\r\n<tbody>\r\n<tr>\r\n<th>Tipo de instrumento</th>\r\n<th>Intrumento</th>\r\n<th>Descripci&oacute;n</th>\r\n</tr>\r\n<tr>\r\n<td>Conceptuales y procedimentales</td>\r\n<td>I1</td>\r\n<td>Pruebas objetivas globales: Aquellas que vienen referidas a los contenidos de una o unidades did&aacute;cticas, como ser&aacute;n los cuestionarios, tests o examenes.</td>\r\n</tr>\r\n<tr>\r\n<td>Conceptuales y procedimentales</td>\r\n<td>I2</td>\r\n<td>Trabajos individuales: Supuestos pr&aacute;cticos, ejercicios y actividades del estudiante de forma unitaria.</td>\r\n</tr>\r\n<tr>\r\n<td>Conceptuales y procedimentales</td>\r\n<td>I3</td>\r\n<td>Tareas grupales y proyectos: Aquellos que el alumno lleva a cabo junto a otros/as compa&ntilde;eros/as, como es el caso de actividades pr&aacute;cticas y proyectos.</td>\r\n</tr>\r\n<tr>\r\n<td>Actitudinales</td>\r\n<td>I4</td>\r\n<td>Participaci&oacute;n en debates, foros y predisposici&oacute;n a intervenir en el proceso de aprendizaje, valorada mediante r&uacute;brica: Se refiere a la actividad y al inter&eacute;s mostrado en dichas tareas comunicativas, adem&aacute;s de la participaci&oacute;n y la atenci&oacute;n en las sesiones.</td>\r\n</tr>\r\n<tr>\r\n<td>Actitudinales</td>\r\n<td>I5</td>\r\n<td>Participaci&oacute;n activa en grupos de trabajo, valorada mediante r&uacute;brica: Vinculado al esfuerzo, la cooperaci&oacute;n y el desempe&ntilde;o en las tareas grupales y de proyecto.</td>\r\n</tr>\r\n<tr>\r\n<td>Actitudinales</td>\r\n<td>I6</td>\r\n<td>Orden y limpieza en la presentaci&oacute;n de tareas, valorada mediante r&uacute;brica: En las tareas redactadas, en las orales y tambi&eacute;n en las resueltas con c&oacute;digo.</td>\r\n</tr>\r\n<tr>\r\n<td>Actitudinales</td>\r\n<td>I7</td>\r\n<td>Informe de cumplimiento en los plazos de entrega: Un instrumento muy importante vinculado a la puntualidad y a la seriedad en el trabajo.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(3118, 366, 10, '<p>La calificaci&oacute;n final del m&oacute;dulo se calcular&aacute; seg&uacute;n la media ponderada siguiente:</p>\r\n<p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Nota m&oacute;dulo= SP * 0,8 + ETT* 0,2</p>\r\n<p>Siendo ,\"SP\" los supuestos pr&aacute;cticos (actividades, ejercicios, proyecto y otros artefactos de car&aacute;cter pr&aacute;ctico) y \"ETT\", la actitud, asistencia, participaci&oacute;n, trabajo en clase y resto de elementos transversales planteados.</p>\r\n<p>Adem&aacute;s, deber&aacute;n tenerse en cuenta los siguientes aspectos:</p>\r\n<ol>\r\n<li>Ser&aacute; necesario obtener una calificaci&oacute;n m&iacute;nima de 5 sobre 10 en los coeficientes de supuestos pr&aacute;cticos \"SP\" para poder superar el m&oacute;dulo, adem&aacute;s de sumar, como m&iacute;nimo un 5, sobre 10, el c&aacute;lculo de la media ponderada total.</li>\r\n<li>Todos los supuestos pr&aacute;cticos planteados deber&aacute;n superarse con una nota m&iacute;nima cuantitativa de 5 o cualitativa de \"Superado\" para poder superar el m&oacute;dulo, pudiendo el docente decidir que haya actividades que requieran de una nota m&iacute;nima de 6 para ser superados, debido a su peso dentro de los contenidos del m&oacute;dulo.</li>\r\n<li>Los supuestos pr&aacute;cticos podr&aacute;n ser defendidos y argumentados por el estudiante de forma oral o escrita, en caso de que el docente as&iacute; lo considere.</li>\r\n<li>El docente podr&aacute; proponer supuestos pr&aacute;cticos o pruebas evaluativas que ser&aacute;n de obligatoria realizaci&oacute;n, entrega y superaci&oacute;n sin que cuenten con una nota cuantitativa, se tratar&aacute; de actividades o pruebas que se evaluar&aacute;n como Superado/No superado.</li>\r\n<li>Todas las pruebas y actividades planteadas en el m&oacute;dulo tendr&aacute;n asignada una fecha de entrega m&aacute;xima, si el estudiante realiza la entrega entre 1 y 5 d&iacute;as depu&eacute;s de tal fecha sin justificaci&oacute;n pertinente, solo podr&aacute; obtener una puntuaci&oacute;n m&aacute;xima de 5. Si la realizaci&oacute;n de la entrega se realiza pasados 5 d&iacute;as de su fecha de finalizaci&oacute;n sin justificaci&oacute;n, la prueba o actividad ser&aacute; calificada con un cero.</li>\r\n<li>Se podr&aacute;n realizar&aacute;n recuperaciones de los supuestos pr&aacute;cticos, en los casos en los que el docente as&iacute; lo considere y sin que por ello el alumnado pierda la evaluaci&oacute;n cont&iacute;nua. La puntuaci&oacute;n m&aacute;xima en tales recuperaciones ser&aacute; de un 6.</li>\r\n<li>Las faltas de asistencia del estudiante no deber&aacute;n superar el 15% del total de sesiones del curso, en caso contrario, el estudiante perder&aacute; la evaluaci&oacute;n continua y deber&aacute; ir a un examen final que recoger&aacute; todos los contenidos de las unidades did&aacute;cticas del m&oacute;dulo, adem&aacute;s de entregar los ejercicios y proyectos planteados para cada una.</li>\r\n</ol>'),
(3119, 366, 22, '<p class=\"p1\">Dentro del Plan de mejora del centro, la Comisi&oacute;n de Coordinaci&oacute;n Pedag&oacute;gica en reuni&oacute;n celebrada el 5 de septiembre de 2019, ha aprobado unos criterios de correcci&oacute;n ortogr&aacute;fica que deben ser aplicados en todas las &aacute;reas, materias y cursos. Tiene, por tanto, car&aacute;cter prescriptivo y&nbsp;<strong>son de obligado cumplimiento&nbsp;</strong>para todo el profesorado<strong>.</strong></p>\r\n<p class=\"p1\">Ciclos Formativos de Grado Superior:&nbsp;Penalizaci&oacute;n de 0,25 puntos por error gr&aacute;fico (0,15 por tilde), hasta un m&aacute;ximo de 2,5 puntos.</p>'),
(3120, 366, 11, '<p>A lo largo de las diferentes unidades did&aacute;cticas, se realizar&aacute;n &nbsp;actividades de refuerzo y ampliaci&oacute;n.</p>\r\n<p>Para aquellos estudiantes que presenten problemas para poder desarrollar alguna parte del proyecto o las actividades, se propondr&aacute;n ejercicios que permitan reforzar los contenidos vistos en clase.</p>\r\n<p>Por otra parte, aquellos alumnos avanzados que alcancen facilmente los objetivos perseguidos en cada una de las unidades, tendr&aacute;n la posibilidad de proponer ampliaciones del proyecto o al profesor para ampliar conocimientos, as&iacute; como llevar a cabo actividades de ampliaci&oacute;n propuestas por el docente.</p>'),
(3122, 366, 13, '<p>La recuperaci&oacute;n del m&oacute;dulo se realizar&aacute; entregando los supuestos pr&aacute;cticos no superados, o algunos alternativos que el profesorado considere. Adem&aacute;s, el profesorado se reserva el derecho a realizar una prueba final escrita u oral al alumnado que no haya superado los ejercicios propuestos durante el curso.</p>\r\n<p>En la convocatoria extraordinaria se solicitar&aacute; al alumnado la entrega de algunos ejercicios pr&aacute;cticos y/o la realizaci&oacute;n de una prueba final (examen), a criterio del profesorado.</p>\r\n<p>&nbsp;</p>'),
(3123, 366, 14, '<p><strong>Recuperaci&oacute;n para alumnado de segundo curso</strong></p>\r\n<p>El alumnado que se encuentre en esta situaci&oacute;n y no pueda asistir a clase presencial, por coincidir el horario lectivo de este m&oacute;dulo con otros que se cursen de segundo curso, deber&aacute; realizar y superar con un m&iacute;nimo de 5 todos los supuestos pr&aacute;cticos que se planteen por cada unidad did&aacute;ctica en el m&oacute;dulo y que se publicar&aacute;n en el aula virtual del centro, adem&aacute;s de realizar las pruebas evaluatorias o propuestas por el docente, los cuales tambi&eacute;n necesitar&aacute;n de una nota m&iacute;nima de 5 para su superaci&oacute;n.</p>\r\n<p>Para ello, deber&aacute; inscribirse en el correspondiente curso y hacer llegar las actividades realizadas para su correcci&oacute;n y puntuaci&oacute;n a trav&eacute;s de AULES.</p>\r\n<p>Para superar el m&oacute;dulo el estudiante deber&aacute; aprobar con un m&iacute;nimo de 5 todas las activides y proyecto propuestos, siendo la nota final obtenida el resultado de la f&oacute;rmula&nbsp;<em>SP (supuestos pr&aacute;cticos)*1 </em>&nbsp;<span style=\"font-weight: 400;\">tal cual se&nbsp;indica en detalle en el apartado&nbsp;<em>7.Criterios de recuperaci&oacute;n</em>&nbsp;del presente documento.</span></p>');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3124, 366, 15, '<p>Para atender las diversas necesidades educativas del aula, se contemplar&aacute;n las siguientes medidas:</p>\r\n<ol>\r\n<li>Desarrollo de cuestionarios de diagn&oacute;stico previo, los cuales permitir&aacute;n detectar el nivel de conocimientos y motivaci&oacute;n del alumnado, de forma que el docente pueda valorar el punto de partida y las estrategias a seguir.</li>\r\n<li>Flexibilizaci&oacute;n de los tiempos de entrega de las diferentes tareas.</li>\r\n<li>Propuesta de actividades con diferente grado de dificultad, como es el caso de las actividades de ampliaci&oacute;n o refuerzo, atendiendo a las capacidades e inter&eacute;s de los estudiantes.</li>\r\n<li>Selecci&oacute;n de perfiles \"analista\" y \"gestor\", en los ejercicios de trabajo en grupo, entre aquellos estudiantes que muestren mayor destreza, de forma que sean ellos mismos quienes apoyen al resto de miembros de su equipo de trabajo</li>\r\n</ol>\r\n<p>Y en general, todos aquellos cambios en la metodolog&iacute;a que el docente identifique como precisos, consultando con el departamento de orientaci&oacute;n y jefatura de estudios cuando se requiera.</p>'),
(3125, 366, 16, '<p><span style=\"font-weight: 400;\">Tal como establece la&nbsp;</span><strong>ORDEN 44/2011</strong><span style=\"font-weight: 400;\">, de 7 de junio (DOCV del d&iacute;a 16/06/2011), de la Conselleria de Educaci&oacute;n, por la que se regulan los planes para el fomento de la lectura en los centros docentes de la Comunidad Valenciana, la comprensi&oacute;n lectora se trabajar&aacute; en todas las &aacute;reas y a fin de fomentar el h&aacute;bito de la lectura se deber&aacute; dedicar un tiempo diario a la misma.</span></p>\r\n<p>A fin de que el alumnado desarrolle su comprensi&oacute;n lectora, se aplicar&aacute;n estrategias que le faciliten su consecuci&oacute;n, como son:</p>\r\n<ul>\r\n<li>Favorecer que los alumnos activen y desarrollen sus conocimientos previos.</li>\r\n<li>Permitir que el alumno busque por s&iacute; solo la informaci&oacute;n, jerarquice ideas y se oriente dentro de un texto.</li>\r\n<li>Activar sus conocimientos previos tanto acerca del contenido como de la forma del texto.</li>\r\n<li>Relacionar la informaci&oacute;n del texto con sus propias vivencias, con sus conocimientos, con otros textos, etc.</li>\r\n<li>Jerarquizar la informaci&oacute;n e integrarla con la de otros textos.</li>\r\n<li>Reordenar la informaci&oacute;n en funci&oacute;n de su prop&oacute;sito.</li>\r\n<li>Ayudar a que los alumnos elaboren hip&oacute;tesis sobre el tema del texto que se va a leer con apoyo de los gr&aacute;ficos o im&aacute;genes que aparecen junto a &eacute;l.</li>\r\n<li>Realizar preguntas espec&iacute;ficas sobre lo le&iacute;do.</li>\r\n<li>Formular preguntas abiertas, que no puedan contestarse con un s&iacute; o un no.</li>\r\n<li>Coordinar una discusi&oacute;n acerca de lo le&iacute;do.</li>\r\n</ul>\r\n<p>Para la ense&ntilde;anza y el aprendizaje de la lectura vamos a trabajar con:</p>\r\n<ul>\r\n<li>Lectura de textos cortos relacionados con el tema y preguntas relacionadas con ellas.</li>\r\n<li>Lectura de materiales que se habilitar&aacute;n en la plataforma AULES del centro educativo.</li>\r\n<li>Lectura en voz alta motivadora de materiales de clase con su explicaci&oacute;n correspondiente.</li>\r\n<li>Lectura silenciosa que antecede a la comprensi&oacute;n, estudio y memorizaci&oacute;n.</li>\r\n<li>Lectura de peri&oacute;dicos y comentarios en clase de informaciones relacionadas con la materia.</li>\r\n</ul>\r\n<p>En cada unidad did&aacute;ctica se dedicar&aacute;n entre 10-15 minutos a la lectura de textos relacionados con los contenidos de la unidad que se est&eacute; tratando, tanto aquellos provistos por los libros y materiales, como los elaborados por los propios estudiantes &nbsp;(ejercicios realizados como actividades para casa, actividades de investigaci&oacute;n, etc.). Se incrementar&aacute; el tiempo en funci&oacute;n del nivel de progresi&oacute;n de los grupos.</p>\r\n<p>Dise&ntilde;o y aplicaci&oacute;n de las estrategias de comprensi&oacute;n lectora:</p>\r\n<ul>\r\n<li>Se realizaran actividades en cada unidad did&aacute;ctica leyendo individualmente para ejercitar la comprensi&oacute;n</li>\r\n</ul>'),
(3126, 366, 17, '<p>Los materiales f&iacute;sicos empleados en el m&oacute;dulo consistir&aacute;n principalmente en un aula de inform&aacute;tica con pizarra, conexi&oacute;n a Internet, proyector o PDI y equipos inform&aacute;ticos conectados en red, tanto para el profesorado como para el alumnado.</p>\r\n<p>A nivel software se utilizar&aacute; la plataforma AULES como repositorio de materiales y entregas, adem&aacute;s del software propio para trabajar en el m&oacute;dulo entre el cual se encontrar&aacute; XAMPP.</p>\r\n<p>&nbsp;</p>'),
(3127, 366, 31, '<p>En la medida de lo posible se deber&aacute;n priorizar y facilitar al m&aacute;ximo los medios telem&aacute;ticos para realizar cualquier tipo de comunicaci&oacute;n entre los profesores y las familias o los alumnos. Por ello, se utilizar&aacute;n los canales que se enumeran a continuaci&oacute;n.</p>'),
(3128, 366, 33, '<p>Es la plataforma proporcionada por la Conselleria de Educaci&oacute;n, Cultura y Deporte para mantener comunicaci&oacute;n entre los centros educativos y los alumnos y sus familias. Por ello, se utilizar&aacute; como canal oficial para comunicar y transmitir telem&aacute;ticamente toda la informaci&oacute;n y el seguimiento de los alumnos.</p>'),
(3129, 366, 32, '<p>A pesar de no tratarse de una plataforma dise&ntilde;ada espec&iacute;ficamente para la comunicaci&oacute;n con las familias o los alumnos, estos podr&aacute;n hacer uso de sus credenciales para estar al corriente de los avances que se vayan realizando durante el curso, e incluso recibir notificaciones en sus dispositivos m&oacute;viles y/o correo electr&oacute;nico.</p>'),
(3130, 366, 36, '<p>Se trata de una plataforma de videoconferencias que facilita las reuniones en l&iacute;nea y los seminarios web.</p>\r\n<p>El IES San Vicente dispone de acceso a las herramientas de Microsoft Teams, con lo que dicho canal de comunicaci&oacute;n tambi&eacute;n podr&aacute; ser utilizado durante el presente curso acad&eacute;mico.</p>'),
(3131, 366, 34, '<p>Todo el personal docente en centros educativos de la Generalitat Valenciana dispone de una direcci&oacute;n de correo electr&oacute;nico de uso corporativo. Por ello, tambi&eacute;n se utilizar&aacute; el env&iacute;o de correos electr&oacute;nicos como medio de comunicaci&oacute;n.</p>'),
(3132, 366, 35, '<p>Eventualmente tambi&eacute;n se utilizar&aacute; el tel&eacute;fono del centro como canal de comunicaci&oacute;n, siempreque el centro se encuentre abierto.</p>'),
(3136, 404, 15, '<p>Se llevar&aacute; a cabo una evaluaci&oacute;n inicial, por la que se procurar&aacute; detectar cu&aacute;l es el problema de aprendizaje concreto que presenta el alumno/a, es decir, determinar qu&eacute; es lo que no consigue realizar dentro del trabajo acad&eacute;mico y, en funci&oacute;n de ello, determinar el objetivo a cubrir por &eacute;l. Como instrumento se pueden utilizar pruebas escritas mediante cuestionarios sencillos, entrevistas y, si es necesario, la ayuda de especialistas en el centro.</p>\r\n<p>Los resultados de esta evaluaci&oacute;n determinar&aacute;n la necesidad o no de apoyos de especialistas para el tratamiento m&aacute;s adecuado de las necesidades del alumnado.</p>\r\n<p>En definitiva, habr&aacute; que valorar el avance detectado y la consecuci&oacute;n de los objetivos se&ntilde;alados para el alumno/a con problemas concretos de aprendizaje.</p>'),
(3137, 404, 16, '<p>El m&oacute;dulo de FOPP implementar&aacute; la parte que le corresponde del Programa de Fomento de la Lectura que desarrolla el centro. Estableciendo libros de lectura obligatoria, a t&iacute;tulo de ejemplo, La buena suerte de Fernando Tr&iacute;as de Bes y Francesc Rovira, El libro negro del emprendedor de Fernando Tr&iacute;as de Bes, El pez que no quiso evolucionar de Francisco Muro, La asertividad de Eva Bach, El caballero de la armadura oxidada de Robert Fisher, El guerrero pac&iacute;fico de Dan Millman, Qui&eacute;n se ha comido mi queso, de Spencer Johnson, El hombre que cambi&oacute; su casa por un tulip&aacute;n de Fernando Tr&iacute;as de Bes, 365 ideas para cambiar tu vida, Francesc Miralles, El mundo en tus manos de Elsa Punset, Br&uacute;jula para navegantes emocionales...y todos aquellos que el profesorado considere oportuno.</p>\r\n<p>&nbsp;</p>'),
(3138, 404, 17, '<p>Se trata de los apoyos y recursos que se utilizan para poder alcanzar los objetivos marcados. El profesor dejar&aacute; material a los alumnos para desarrollar los contenidos.</p>\r\n<p>El libro de texto es el de la editorial <strong>McGraw Hill</strong> para esta asignatura. Otros materiales estar&aacute;n disponibles a trav&eacute;s de <strong>Aules</strong>.</p>\r\n<ul>\r\n<li>Aula virtual:\r\n<ul>\r\n<li>A trav&eacute;s de la plataforma \"Aules\" se colgar&aacute;n contenidos, actividades, pel&iacute;culas y diversos materiales que se utilizar&aacute; durante el curso.</li>\r\n</ul>\r\n</li>\r\n<li>Libros de lectura obligatoria.</li>\r\n<li>Pel&iacute;culas y documentales obligatorios.</li>\r\n<li>Otros recursos.</li>\r\n</ul>'),
(3139, 404, 1, '<p class=\"p1\">La programaci&oacute;n did&aacute;ctica de la asignatura Formaci&oacute;n y Orientaci&oacute;n Personal y Profesional incluida en la LOMLOE Ley Org&aacute;nica 3/2020 (LOMLOE), de 29 de diciembre, por la que se modifica la actual Ley Org&aacute;nica 2/2006 (LOE), de 3 de mayo, de Educaci&oacute;n., aparece en 4 curso de la E.S.O, como optativa.</p>\r\n<p>El sistema educativo contribuye a que el alumnado desarrolle plenamente su personalidad, refuerce su autonom&iacute;a y el conocimiento de s&iacute; mismo y del entorno en el que va a vivir y a abrirse camino. La materia Formaci&oacute;n y Orientaci&oacute;n Personal y Profesional propone una aproximaci&oacute;n al conocimiento de lo humano a partir de disciplinas que lo analizan desde el conocimiento de los procesos biol&oacute;gicos, psicol&oacute;gicos e intelectuales que regulan la conducta, la cognici&oacute;n y el aprendizaje; desde el conocimiento del individuo como parte de una construcci&oacute;n social y cultural; y desde el an&aacute;lisis de los elementos que definen las organizaciones sociales y los grupos humanos. Esta aproximaci&oacute;n va a permitir <strong>despertar la curiosidad por el conocimiento de la propia persona, de su proceso de aprendizaje y del entorno sociocultural en el que se encuentra, de modo que incremente su autonom&iacute;a y su confianza en su propio logro,</strong> y facilite su aprendizaje a lo largo de la vida y su desempe&ntilde;o acad&eacute;mico y profesional.</p>\r\n<p>&nbsp;</p>'),
(3140, 404, 2, '<p class=\"p1\">Se realiza teniendo en cuenta:</p>\r\n<p class=\"p1\">-<strong>Normativa nacional</strong><br /><br />&nbsp;Ley Org&aacute;nica 3/2020 (LOMLOE), de 29 de diciembre, por la que se modifica la actual Ley Org&aacute;nica 2/2006 (LOE), de 3 de mayo, de Educaci&oacute;n.&nbsp; Ley Org&aacute;nica 2/2006 (LOE) de 3 de mayo, de educaci&oacute;n<br /><br />&nbsp;Real Decreto 217/2022, de 29 de marzo, por el que se establece la ordenaci&oacute;n y las ense&ntilde;anzas m&iacute;nimas de la Educaci&oacute;n Secundaria Obligatoria.</p>\r\n<p class=\"p1\"><strong>Normativa auton&oacute;mica</strong></p>\r\n<p class=\"p1\">Decreto 107/2022, de 5 de agosto, del Consell, por el que se establece la ordenaci&oacute;n y el curr&iacute;culo de Educaci&oacute;n Secundaria Obligatoria y DECRETO 66/2024, de 21 de junio, del Consell, por el que se modifica el decreto 107/2022 del Consell</p>\r\n<p class=\"p1\">Para desarrollar una programaci&oacute;n did&aacute;ctica correcta y &uacute;til para una adecuada formaci&oacute;n de los alumnos no se puede trabajar de espaldas a la realidad social y econ&oacute;mica en la que &eacute;stos viven.</p>\r\n<p class=\"p1\">El centro en el que se contextualiza esta programaci&oacute;n es el IES San Vicente, situado en la localidad de San Vicente del Raspeig (Alicante). En este centro, se imparten el ciclo formativo de grado superior de Administraci&oacute;n de Sistemas Inform&aacute;ticos en Red, Desarrollo de Aplicaciones Multiplataforma en su modalidad presencial y semipresencial, Administraci&oacute;n y Finanzas, y de grado medio de Sistemas Microinform&aacute;ticos y Redes, &nbsp;de Gesti&oacute;n Administrativa y Finanzas. As&iacute; como FP B&aacute;sica, ESO y Bachillerato.</p>\r\n<p class=\"p1\">El centro cuenta con los medios y recursos suficientes para el desarrollo de la asignatura, concretamente el aula dispone de proyector, pantalla y pizarra.</p>'),
(3142, 404, 6, '<p class=\"western\" style=\"line-height: 100%; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\"><strong>PRIMERA EVALUACI&Oacute;N Bloque 1</strong></span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 0.5cm; margin-bottom: 0cm;\" align=\"left\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\">Unidad 1: El ser humano</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 0.5cm; margin-bottom: 0cm;\" align=\"left\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\">Unidad 2: La identidad personal</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 0.5cm; margin-bottom: 0cm;\" align=\"left\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\">Unidad 3: Nosotros y los dem&aacute;s</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\"><strong>SEGUNDA EVALUACI&Oacute;N Bloque 2</strong></span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 0.5cm; margin-bottom: 0cm;\" align=\"left\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\">Unidad 4: Creatividad y ocio saludable</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 0.5cm; margin-bottom: 0cm;\" align=\"left\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\">Unidad 5: El ciudadano y la administraci&oacute;n.</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 0.5cm; margin-bottom: 0cm;\" align=\"left\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\">Unidad 6: El itinerario formativo</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\"><strong>TERCERA EVALUACI&Oacute;N Bloque 3</strong></span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 0.5cm; margin-bottom: 0cm;\" align=\"left\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\">Unidad 7: El mundo del trabajo</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 0.5cm; margin-bottom: 0cm;\" align=\"left\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\">Unidad 8: La b&uacute;squeda de empleo</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 0.5cm; margin-bottom: 0cm;\" align=\"left\"><span style=\"font-family: Times New Roman, serif;\"><span style=\"font-size: small;\">Unidad 9: Proyecto personal</span></span></p>'),
(3143, 404, 9, '<div class=\"cblq fondo\">\r\n<div class=\"cte\">\r\n<p><strong>Competencia espec&iacute;fica 1:<br />1.1. Reconocer los procesos cognitivos y emocionales b&aacute;sicos y reflexionar<br />sobre el propio aprendizaje.<br />1.2. Reconocer y gestionar la ansiedad en situaciones de estr&eacute;s, en los<br />contextos personales, acad&eacute;micos y profesionales, mediante estrategias de<br />control de las emociones.<br />1.3. Identificar y analizar cr&iacute;ticamente las fortalezas, debilidades, metas,<br />intereses y valores personales para aplicarlos en la planificaci&oacute;n del<br />proyecto personal, acad&eacute;mico y profesional.<br />1.4. Reconocer situaciones de riesgo y h&aacute;bitos de vida saludables,<br />investigar de forma rigurosa los medios para mejorar la salud f&iacute;sica y mental<br />y utilizar la informaci&oacute;n adquirida para mejorar los h&aacute;bitos de la vida<br />cotidiana.</strong></p>\r\n<p><strong>Competencia espec&iacute;fica 2:<br />2.1 Analizar las habilidades socioemocionales necesarias para<br />desenvolverse en los contextos interpersonales y profesionales y planificar<br />algunas estrategias para mejorarlas.<br />2.2. Identificar creencias y valores culturales y sociales que influyen en la<br />construcci&oacute;n de la identidad personal.<br />2.3. Analizar y argumentar los derechos de las personas valorando la<br />diversidad y planteando acciones frente a las situaciones de violencia y<br />exclusi&oacute;n.<br />2.4. Participar de manera activa en din&aacute;micas de trabajo grupal y<br />cooperativo contribuyendo a la elaboraci&oacute;n de proyectos colaborativos,<br />poniendo en acci&oacute;n habilidades comunicativas y estrategias<br />que permitan llegar a consensos.<br />2.5 Investigar los sesgos y estereotipos que pueden influir en la<br />construcci&oacute;n de expectativas sobre las posibilidades personales,<br />acad&eacute;micas y profesionales.</strong></p>\r\n<p><strong>Competencia espec&iacute;fica 3:<br />3.1 Buscar, seleccionar y manejar cr&iacute;ticamente informaci&oacute;n de distintas<br />fuentes para tomar decisiones vocacionales de los &aacute;mbitos personal,<br />acad&eacute;mico y profesional.<br />3.2 Participar activamente en las visitas a centros de formaci&oacute;n y centros de<br />trabajo y analizar la informaci&oacute;n significativa.<br />3.3 Explorar los distintos campos profesionales conociendo los requisitos,<br />las v&iacute;as de acceso, los estudios necesarios y las condiciones laborales.<br />3.4. Investigar y analizar las caracter&iacute;sticas del mercado laboral, los<br />cambios del entorno profesional y productivo y los empleos emergentes,<br />detectando las habilidades que mejor se adaptan a esta nueva realidad.<br />3.5. Identificar las diferentes opciones de empleo, a partir de las<br />posibilidades de inserci&oacute;n por cuenta ajena y por cuenta propia y explorar<br />las relaciones presentes en cada una de ellas.</strong></p>\r\n<p><strong>Competencia espec&iacute;fica 4:</strong></p>\r\n<span style=\"font-size: small;\">4.1 Analizar el contexto social, en relaci&oacute;n con la familia, amistades, situaci&oacute;n econ&oacute;mica y oportunidades acad&eacute;micas y profesionales y valorar los apoyos con los que se cuentan y las dificultades a superar.</span>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">4.2 Identificar las cualidades personales y apoyos del entorno con los que afrontar con eficacia nuevos retos y facilitar el proceso de transici&oacute;n a la vida adulta.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">4.3 Contrastar y comparar la informaci&oacute;n recopilada planteando hip&oacute;tesis, identificando las opciones que mejor se adaptan a nuestros intereses y evaluando su viabilidad. </span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">4.4 Verificar en el proceso de toma de decisiones si los pasos nos conducen a la meta correcta o se requiere realizar ajustes o replantear los objetivos.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">4. 5 Tomar decisiones a partir de los valores y expectativas propias sin ceder a modas, presi&oacute;n social o conductas de evitaci&oacute;n, asumiendo la responsabilidad de las decisiones.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\"><strong>Competencia espec&iacute;fica 5:</strong></span></p>\r\n<span style=\"font-size: small;\">5.1 Priorizar las necesidades e identificar los intereses personales y vocacionales mediante la exploraci&oacute;n de las oportunidades acad&eacute;micas y profesionales que ofrece el entorno mostrando las destrezas necesarias en el proceso de toma de decisiones. </span>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">5.2 Explorar el mundo laboral y extraer conclusiones sobre el futuro profesional propio. </span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">5.3 Construir el entorno personal de aprendizaje para el desarrollo personal, acad&eacute;mico y profesional a lo largo de la vida. </span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">5.4 Elaborar un proyecto personal, acad&eacute;mico y profesional propio, incorporando el autoconocimiento, el conocimiento del entorno acad&eacute;mico y profesional y la aproximaci&oacute;n al mundo laboral</span></p>\r\n</div>\r\n</div>'),
(3145, 404, 7, '<p>El enfoque metodol&oacute;gico de la asignatura &laquo;Formaci&oacute;n y Orientaci&oacute;n Personal y Profesional&raquo; ha de partir de los conocimientos que tienen los alumnos de la realidad que les rodea as&iacute; como de sus expectativas e intereses. A trav&eacute;s de actividades eminentemente pr&aacute;cticas se ha de propiciar las condiciones favorables para que el alumno despliegue una actividad mental creativa y diversa que le permita la adquisici&oacute;n de conocimientos y experiencias.</p>\r\n<ul>\r\n<li>\r\n<ul>\r\n<li>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">A lo largo de las sesiones y, al hilo de los contenidos de las unidades did&aacute;cticas, se ir&aacute;n proponiendo </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>actividades</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> de diversa &iacute;ndole (juegos, din&aacute;micas, debates, v&iacute;deos, investigaci&oacute;n, proyectos, exposiciones orales, etc.) para realizar de forma </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>individual</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> o en </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>grupo</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">. La mayor&iacute;a de las tareas tendr&aacute;n como objetivo adquirir </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>habilidades</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> y conocer diversas herramientas para el </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>autoconocimiento</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">, mejorar la </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>relaci&oacute;n</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> con los dem&aacute;s y con el entorno, trabajar en </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>equipo</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">, buscar </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>informaci&oacute;n</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> fiable, </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>planificar</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> el </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>futuro</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> acad&eacute;mico y profesional y para ir cogiendo confianza en las exposiciones orales y mejorando el desempe&ntilde;o en la elaboraci&oacute;n de materiales de apoyo para dichas exposiciones.</span></span></p>\r\n</li>\r\n</ul>\r\n<p class=\"western\" style=\"line-height: 100%; margin-bottom: 0cm;\">&nbsp;</p>\r\n</li>\r\n</ul>'),
(3146, 404, 10, '<p>Como principio, no existe el instrumento o procedimiento ideal para evaluar. Cualquier instrumento bien dise&ntilde;ado y utilizado de forma apropiada puede ser adecuado siempre que se sea consciente del tipo de informaci&oacute;n que proporciona y de que &eacute;sta sea la que nos interesa. El problema surge cuando pretendemos evaluar con un &uacute;nico instrumento la variedad o riqueza de contenidos y capacidades desarrollados a lo largo de un per&iacute;odo. Por ello, es necesario utilizar t&eacute;cnicas variadas de evaluaci&oacute;n.</p>\r\n<p>En primer lugar, usaremos la observaci&oacute;n del trabajo de los alumnos como un procedimiento esencial para comprobar su progreso, tanto por ser un instrumento privilegiado para evaluar las actitudes y h&aacute;bitos en relaci&oacute;n con su trabajo, su inter&eacute;s y curiosidad, su participaci&oacute;n en las tareas colectivas, etc., como porque proporciona informaci&oacute;n de los alumnos en situaciones diversas y sin las interferencias que provoca el saber que se est&aacute; pasando un &ldquo;examen&rdquo;.</p>\r\n<p>Otro instrumento de evaluaci&oacute;n relacionado con las actividades de ense&ntilde;anza es la revisi&oacute;n de los trabajos de los alumnos, a trav&eacute;s del cuaderno en el que se recogen las tareas y actividades diarias, con el fin de obtener informaci&oacute;n sobre sus h&aacute;bitos y m&eacute;todos de trabajo, claridad en sus anotaciones, correcci&oacute;n en la expresi&oacute;n escrita y gr&aacute;fica, etc.</p>\r\n<p>Se calificar&aacute; mediante notas de clase en las que se valorar&aacute; el resultado en los ejercicios, actividades de clase, realizaci&oacute;n de trabajos e informes que el alumno habr&aacute; realizado de forma individual o en peque&ntilde;o grupo y servir&aacute;n para determinar el grado de consecuci&oacute;n de las competencias.</p>\r\n<p>Cada alumno llevar&aacute; en el cuaderno las tareas y actividades diarias que la profesora recoger&aacute; a lo largo de la evaluaci&oacute;n para formar parte de la nota de la asignatura.</p>\r\n<p><strong>Criterios de calificaci&oacute;n:</strong></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">Cada actividad ser&aacute; valorada num&eacute;ricamente entre 0 y 10 puntos</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">La calificaci&oacute;n de </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>CADA EVALUACI&Oacute;N</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> se obtendr&aacute; ponderando las diferentes actividades de la siguiente manera:</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>10%: Tareas cortas</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> al hilo de las unidades did&aacute;cticas realizadas en clase o en casa.</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>10%: Juegos y din&aacute;micas de grupo</strong></span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">Entre el </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>30% y el 40%: Cuestionarios escritos</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> que podr&aacute;n ser sobre los contenidos de las unidades did&aacute;cticas o sobre la experiencia y la reflexi&oacute;n del alumno o alumna en relaci&oacute;n con esos contenidos o con las actividades realizadas.</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">Entre el </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>10% y el 20%: trabajos y exposiciones individuales</strong></span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">Entre el </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>20% y el 30%: trabajos, exposiciones y proyectos en grupo</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">.</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">Los porcentajes se podr&aacute;n adaptar en cada evaluaci&oacute;n seg&uacute;n los contenidos y las actividades realizadas.</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">Se entender&aacute; que se ha </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>superado la evaluaci&oacute;n</strong></span></span> <span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>si la nota</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> obtenida despu&eacute;s del c&aacute;lculo descrito</span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong> iguala o supera el 5.</strong></span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">La </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>NOTA FINAL</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> del curso se obtendr&aacute; calculando la </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>media aritm&eacute;tica de las tres evaluaciones</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">.</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">Tanto a lo largo de cada evaluaci&oacute;n como al final del curso, el alumnado </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>podr&aacute; repetir las actividades que hayan obtenido una calificaci&oacute;n inferior a 5</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> siguiendo las indicaciones y haciendo las rectificaciones que proponga la profesora. </span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>OTRAS NOTAS IMPORTANTES SOBRE LA EVALUACI&Oacute;N:</strong></span></span></p>\r\n<ol>\r\n<li>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">En todas las tareas y actividades que se realicen de forma presencial distintas de los controles, </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>se reservar&aacute;n 2 puntos de los 10</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> de la calificaci&oacute;n para valorar la capacidad de trabajo en </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>equipo, la participaci&oacute;n, la iniciativa</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">, el respeto y la colaboraci&oacute;n para un buen ambiente de trabajo. Las </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>faltas</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> de </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>comportamiento</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> y las </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>faltas</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> de </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>asistencia</strong></span></span> <span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>podr&aacute;n</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> tenerse en cuenta hasta hacer </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>perder estos dos puntos</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">.</span></span></p>\r\n</li>\r\n<li>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">En las pruebas escritas y en los ejercicios redactados individualmente por el alumnado se prestar&aacute; especial atenci&oacute;n a la </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>expresi&oacute;n correcta, el empleo adecuado de los conceptos estudiados y la capacidad de relacionar los contenidos</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> que se eval&uacute;an con los del resto de la asignatura, con los de otras materias y con los hechos y realidades del contexto social y econ&oacute;mico. Tambi&eacute;n se valorar&aacute; el empleo de las tecnolog&iacute;as de la informaci&oacute;n y la capacidad de </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>di&aacute;logo</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> y de trabajo en </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>equipo</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> cuando sea el caso.</span></span></p>\r\n</li>\r\n<li>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>No se admitir&aacute;n trabajos fuera del plazo</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> establecido salvo en casos de fuerza mayor.</span></span></p>\r\n</li>\r\n<li>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">Atendiendo al Plan de Mejora del centro, se aplicar&aacute;n los </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>criterios ortogr&aacute;ficos</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> en la correcci&oacute;n de trabajos y controles de la siguiente manera:</span></span></p>\r\n</li>\r\n</ol>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">0,10 puntos de </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>penalizaci&oacute;n</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> por cada error ortogr&aacute;fico y 0,05 por cada tilde hasta un </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>m&aacute;ximo de 1,5 puntos</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">.</span></span></p>\r\n<p class=\"western\" lang=\"es-ES-u-co-trad\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\">&nbsp;</p>\r\n<p class=\"western\" style=\"line-height: 100%; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>COPIA EN TRABAJOS</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">:</span></span></p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">En el caso de que se compruebe que se ha presentado un trabajo o tarea copiado de alg&uacute;n compa&ntilde;ero o compa&ntilde;era o de internet, la calificaci&oacute;n del trabajo ser&aacute; de</span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong> cero, tanto para quien lo ha realizado como para quien lo ha copiado</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">. </span></span></p>\r\n<p class=\"western\" lang=\"es-ES-u-co-trad\" style=\"line-height: 100%; margin-bottom: 0cm;\">&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(3147, 404, 13, '<p>En caso de tener que ir a la convocatoria extraordinaria por no haber superado la asignatura, se realizar&aacute; una prueba escrita global de toda la materia. La calificaci&oacute;n ser&aacute; num&eacute;rica, con un valor comprendido entre 0 y 10 obtenido mediante redondeo.</p>\r\n<p>Para los alumnos que pierdan el derecho a la evaluaci&oacute;n continua, se realizar&aacute; una prueba escrita a final de curso, que consistir&aacute; en desarrollar una serie de preguntas relacionadas con los aspectos fundamentales de la materia, y que se valorar&aacute; seg&uacute;n se establece en los criterios de evaluaci&oacute;n ya mencionados. Adem&aacute;s presentar&aacute; un proyecto personal y profesional siguiendo las instrucciones del docente. Para recuperar la asignatura deber&aacute;n aprobar el proyecto personal y profesional&nbsp; y la prueba escrita global.</p>\r\n<p>Los alumnos que terminen 4&ordm; y tengan&nbsp; la asignatura pendiente tendr&aacute;n que examinarse de toda la materia as&iacute; como entregar todas aquellas tareas que previamente se les habr&aacute; indicado.</p>'),
(3148, 404, 11, '<p>Estas actividades se dise&ntilde;ar&aacute;n en funci&oacute;n de las necesidades y caracter&iacute;sticas de los alumnos que requieran de ellas.</p>'),
(3151, 404, 14, '<p>No hay alumnos con esta materia pendiente.</p>'),
(3152, 404, 18, '<p>FOPP Editorial Paraninfo.</p>\r\n<p>FOPP Editorial Editex.</p>\r\n<p>FOPP Editorial McMillan</p>\r\n<p>FOPP Editorial Mc Graw Hill</p>'),
(3153, 404, 19, ''),
(3154, 404, 20, ''),
(3155, 404, 23, '<p>Pruebas te&oacute;ricas, actividades en el aula, libreta, trabajos en grupo, presentaciones... todo aquello que utilicemos para trabajar servir&aacute; de instrumento de evaluaci&oacute;n.</p>\r\n<p class=\"western\" style=\"line-height: 100%; text-indent: 1.25cm; margin-bottom: 0cm;\"><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">Es conveniente que cada alumno o alumna lleve un cuaderno o diario de clase en el que </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>anote</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> lo que se ha hecho en cada </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>sesi&oacute;n</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\">, lo que ha </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>aprendido</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> y sus </span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"><strong>reflexiones</strong></span></span><span style=\"font-family: Times New Roman, serif;\"><span lang=\"es-ES-u-co-trad\"> o impresiones acerca de ello. Le servir&aacute; mucho para las pruebas finales de cada bloque. </span></span></p>'),
(3156, 404, 22, '<p>En este punto se sigue la normativa del centro para toda la ESO y Bachillerato.</p>'),
(3157, 404, 27, '<p>En la tercera evaluaci&oacute;n se han impartido los contenidos m&iacute;nimos y se han trabajado los &uacute;ltimos contenidos vistos en clase a trav&eacute;s del Aula Virtual del centro y de v&iacute;deotutor&iacute;as, as&iacute; como de material complementario recomendado por la profesora.</p>'),
(3158, 404, 28, '<p>Quedan pendientes de impartir el tema 7 de la Programaci&oacute;n.</p>'),
(3159, 404, 29, '<p>El alumno ser&aacute; evaluado a trav&eacute;s de una prueba on line. Adem&aacute;s, la profesora podr&aacute; requerir aquellos trabajos que considere oportunos como requisito para presentarse a la prueba on line.</p>'),
(3160, 404, 31, '<p>La comunicaci&oacute;n con el alumnado y las familias se llevar&aacute; a cabo a trav&eacute;s del correo corporativo gva, de las plataformas Itaca y Aules.</p>'),
(3161, 404, 32, '<p>Aules ser&aacute; la herramienta utilizada por los miembros del departamento de FOL para colgar todos los materiales complementarios al libro de texto as&iacute; como para recepcionar los trabajos y actividades.</p>\r\n<p>En caso de que sea conveniente o necesario por la situaci&oacute;n sanitaria ser&aacute; la herramienta que se utilizar&aacute; para hacer las pruebas objetivas de conocimientos o ex&aacute;menes.</p>'),
(3162, 404, 36, '<p>En caso de confinamiento o restricciones de movilidad que nos impidan la asistencia al centro educativo se utilizar&aacute; Webex para hacer v&iacute;deotutor&iacute;as.</p>'),
(3163, 404, 41, '<ul>\r\n<li>Competencia espec&iacute;fica n&uacute;m.1: Identificar en s&iacute; mismo algunos procesos psicol&oacute;gicos b&aacute;sicos implicados en el aprendizaje, la&nbsp;conducta y las emociones, desarrollando procesos de autorregulaci&oacute;n que le permitan un aprendizaje a lo largo de la vida.</li>\r\n</ul>\r\n<ul>\r\n<li>Competencia espec&iacute;fica n&uacute;m.2: Reconocer algunos factores personales y socioculturales que intervienen en la comprensi&oacute;n de s&iacute; mismo en relaci&oacute;n con los dem&aacute;s y en la adaptaci&oacute;n al contexto social y profesional, respetando y valorando la diversidad.</li>\r\n</ul>\r\n<ul>\r\n<li>Competencia espec&iacute;fica n&uacute;m.3: Explorar el entorno identificando las oportunidades de desarrollo personal, acad&eacute;mico y profesional utilizando de forma cr&iacute;tica la informaci&oacute;n.</li>\r\n</ul>\r\n<ul>\r\n<li>Competencia espec&iacute;fica n&uacute;m.4: Definir metas realistas, ajustadas al conocimiento de s&iacute; mismo, utilizando la informaci&oacute;n relevante para resolver la incertidumbre y adoptar una actitud proactiva en la toma de decisiones personales, acad&eacute;micas y profesionales.</li>\r\n</ul>\r\n<ul>\r\n<li>Competencia espec&iacute;fica n&uacute;m.5: Dise&ntilde;ar un proyecto personal, acad&eacute;mico y profesional propio conjugando las necesidades e intereses personales y vocacionales con las oportunidades del entorno y las destrezas necesarias en la toma de decisiones.</li>\r\n</ul>');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3164, 404, 42, '<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\"><strong>&nbsp;</strong></span></p>\r\n<h3 class=\"ta-justify\"><strong>Competencia espec&iacute;fica n&uacute;m.1: Identificar en s&iacute; mismo algunos procesos psicol&oacute;gicos b&aacute;sicos implicados en el aprendizaje, la&nbsp;conducta y las emociones, desarrollando procesos de autorregulaci&oacute;n que le permitan un aprendizaje a lo largo de la vida.</strong></h3>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\"><strong>Saberes b&aacute;sicos:</strong></span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Subbloque 1.1 Procesos psicol&oacute;gicos b&aacute;sicos y fundamentos biol&oacute;gicos de la conducta </span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Procesos psicol&oacute;gicos b&aacute;sicos implicados en el aprendizaje.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Procesos psicol&oacute;gicos b&aacute;sicos implicados en las emociones.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Fundamentos biol&oacute;gicos de la conducta.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Subbloque 1.2 Conocimiento de uno mismo</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Adolescencia y formaci&oacute;n de la identidad.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Fortalezas, debilidades, metas, intereses y valores.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Autopercepci&oacute;n, expectativas y autoeficacia.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Conductas de riesgo, adicciones y h&aacute;bitos de vida saludables.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Habilidades para la vida: cognitivas, emocionales y sociales.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Afrontamiento de la incertidumbre y el estr&eacute;s.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Habilidades de organizaci&oacute;n y gesti&oacute;n.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Autoconocimiento vocacional.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Ocio y tiempo libre.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Autonom&iacute;a personal.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><strong><span style=\"font-size: small;\">Competencia espec&iacute;fica n&uacute;m.2:<br />Reconocer algunos factores personales y socioculturales que intervienen en la comprensi&oacute;n de s&iacute; mismo en relaci&oacute;n con los dem&aacute;s y en la adaptaci&oacute;n al contexto social y profesional, respetando y valorando la diversidad.</span></strong></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\"><strong>Saberes b&aacute;sicos:</strong></span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Subbloque 1.3 Interacci&oacute;n social</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Cultura y desarrollo individual y social.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Desarrollo personal dentro del grupo. Influencia de la presi&oacute;n del grupo.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Conciencia social y compromiso con la justicia social.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Valor de la diversidad.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Convivencia y resoluci&oacute;n pac&iacute;fica de los conflictos.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Atribuciones sociales y estereotipos.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Habilidades para relacionarse y para la comunicaci&oacute;n eficaz.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><strong><span style=\"font-size: small;\">Competencia espec&iacute;fica n&uacute;m.3: Explorar el entorno identificando las oportunidades de desarrollo personal, acad&eacute;mico y profesional utilizando de forma cr&iacute;tica la informaci&oacute;n.</span></strong></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\"><strong>Saberes b&aacute;sicos:</strong></span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Bloque 2 Exploraci&oacute;n del entorno personal, acad&eacute;mico y profesional.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Subbloque 2.1 Fuentes de informaci&oacute;n para el desarrollo personal, acad&eacute;mico y profesional &bull; Internet y otras fuentes de informaci&oacute;n. &bull; Fiabilidad de las fuentes y actualidad de la informaci&oacute;n. &bull; Servicios de orientaci&oacute;n en el entorno personal, acad&eacute;mico y laboral. &bull; Mapa de recursos de informaci&oacute;n y asesoramiento. </span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Subbloque2.2 Oportunidades de desarrollo personal y social &bull; Oportunidades de participaci&oacute;n activa para el compromiso social. &bull; Opciones para el desarrollo de habilidades y competencias personales y sociales. Subbloque 2.3 Formaci&oacute;n acad&eacute;mica y profesional &bull; Campos profesionales y formaci&oacute;n asociada. &bull; Ocupaciones profesionales y estilos de vida. &bull; Bachillerato, Formaci&oacute;n Profesional y otras opciones de estudios despu&eacute;s de 4&ordm; de la ESO. &bull; Titulaciones, grados, cualificaciones y programas de formaci&oacute;n: oferta, acceso, vinculaciones y continuidad acad&eacute;mica y profesional. &bull; Oportunidades acad&eacute;micas en otros pa&iacute;ses. </span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Subbloque 2.4 Mundo laboral &bull; Exploraci&oacute;n y descubrimiento del entorno de trabajo. &bull; Opciones trabajo por cuenta ajena e iniciativa emprendedora. &bull; Mercado laboral y relaciones en entorno de trabajo. &bull; Revoluci&oacute;n digital en el entorno laboral</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><strong><span style=\"font-size: small;\">Competencia espec&iacute;fica n&uacute;m.4: Definir metas realistas, ajustadas al conocimiento de s&iacute; mismo, utilizando la informaci&oacute;n relevante para resolver la incertidumbre y adoptar una actitud proactiva en la toma de decisiones personales, acad&eacute;micas y profesionales</span></strong></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\"><strong>Saberes b&aacute;sicos:</strong></span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Bloque 3 Proceso de toma de decisiones y dise&ntilde;o de un proyecto personal, acad&eacute;mico y profesional</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Subbloque 3.1 Proceso de toma de decisiones</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">An&aacute;lisis reflexivo, sistem&aacute;tico y met&oacute;dico para la toma de decisiones.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Identificaci&oacute;n de las mejores opciones y planteamiento de hip&oacute;tesis y su viabilidad.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Factores que influyen en las decisiones.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Asunci&oacute;n de responsabilidades y an&aacute;lisis de los riesgos.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Verificaci&oacute;n de los resultados y detecci&oacute;n de errores.</span></p>\r\n<p><strong>Competencia espec&iacute;fica n&uacute;m.5: Dise&ntilde;ar un proyecto personal, acad&eacute;mico y profesional propio conjugando las necesidades e<br />intereses personales y vocacionales con las oportunidades del entorno y las destrezas necesarias en la toma de decisiones.</strong></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\"><strong>Saberes b&aacute;sicos</strong></span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Subbloque 3.2. Toma de decisiones para el desarrollo personal</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Cualidades personales y apoyos del entorno.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Habilidades para la gesti&oacute;n de la carrera.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Metas personales.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Planificaci&oacute;n de estrategias para mejorar el desarrollo y bienestar personal y social.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Subbloque 3.3. Toma de decisiones acad&eacute;micas y profesionales</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Descubrimiento de los intereses vocacionales y priorizaci&oacute;n de las necesidades.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Oportunidades acad&eacute;micas y profesionales, valorando aquellas que mejor se adaptan a las cualidades e intereses personales.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Identificaci&oacute;n del itinerario formativo y de otras &aacute;reas de mejora de las competencias acad&eacute;micas y profesionales.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Apoyos y recursos con los que se cuentan y dificultades a superar para alcanzar los objetivos.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Plan de orientaci&oacute;n acad&eacute;mica y profesional. Establecimiento de una hoja de ruta.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\"><span style=\"font-size: small;\">Subbloque 3.4. Aproximaci&oacute;n a la incorporaci&oacute;n al mundo laboral y aprendizaje a lo largo de la vida</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Estrategias e instrumentos para la b&uacute;squeda activa de empleo.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Estrategias y recursos b&aacute;sicos para el emprendimiento.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Entorno personal de aprendizaje para el desarrollo personal, acad&eacute;mico y profesional a lo largo de la vida.</span></p>\r\n<p class=\"western\" style=\"orphans: 0; widows: 0;\" align=\"left\">&bull; <span style=\"font-size: small;\">Aproximaci&oacute;n al concepto de desarrollo de la carrera profesional.</span></p>\r\n<p style=\"line-height: 100%; margin-bottom: 0cm;\">&nbsp;</p>');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3165, 404, 25, '<p><strong>Competencias clave que se deben adquirir</strong></p>\r\n<p>Las competencias clave que se recogen en el Perfil de salida son la adaptaci&oacute;n al sistema educativo espa&ntilde;ol de las competencias clave establecidas en la citada Recomendaci&oacute;n del Consejo de la Uni&oacute;n Europea. Esta adaptaci&oacute;n responde a la necesidad de vincular dichas competencias con los retos y desaf&iacute;os del siglo XXI, con los principios y fines del sistema educativo establecidos en la LOE y con el contexto escolar, ya que la Recomendaci&oacute;n se refiere al aprendizaje permanente que debe producirse a lo largo de toda la vida, mientras que el Perfil remite a un momento preciso y limitado del desarrollo personal, social y formativo del alumnado: la etapa de la ense&ntilde;anza b&aacute;sica.</p>\r\n<p>Con car&aacute;cter general, debe entenderse que la consecuci&oacute;n de las competencias y los objetivos previstos en la LOMLOE para las distintas etapas educativas est&aacute; vinculada a la adquisici&oacute;n y al desarrollo de las competencias clave recogidas en este Perfil de salida, y que son las siguientes:</p>\r\n<ul>\r\n<li>Competencia en comunicaci&oacute;n ling&uuml;&iacute;stica.</li>\r\n<li>Competencia pluriling&uuml;e.</li>\r\n<li>Competencia matem&aacute;tica y competencia en ciencia, tecnolog&iacute;a e ingenier&iacute;a.</li>\r\n<li>Competencia digital.</li>\r\n<li>Competencia personal, social y de aprender a aprender.</li>\r\n<li>Competencia ciudadana.</li>\r\n<li>Competencia emprendedora.</li>\r\n<li>Competencia en conciencia y expresi&oacute;n culturales.</li>\r\n</ul>\r\n<p>La transversalidad es una condici&oacute;n inherente al Perfil de salida, en el sentido de que todos los aprendizajes contribuyen a su consecuci&oacute;n. De la misma manera, la adquisici&oacute;n de cada una de las competencias clave contribuye a la adquisici&oacute;n de todas las dem&aacute;s. No existe jerarqu&iacute;a entre ellas, ni puede establecerse una correspondencia exclusiva con una &uacute;nica &aacute;rea, &aacute;mbito o materia, sino que todas se concretan en los aprendizajes de las distintas &aacute;reas, &aacute;mbitos o materias y, a su vez, se adquieren y desarrollan a partir de los aprendizajes que se producen en el conjunto de las mismas.</p>\r\n<p><strong>Descriptores operativos de las competencias clave en la ense&ntilde;anza b&aacute;sica</strong></p>\r\n<p>En cuanto a la dimensi&oacute;n aplicada de las competencias clave, se ha definido para cada una de ellas un conjunto de descriptores operativos, partiendo de los diferentes marcos europeos de referencia existentes.</p>\r\n<p>Los descriptores operativos de las competencias clave constituyen, junto con los objetivos de la etapa, el marco referencial a partir del cual se concretan las competencias espec&iacute;ficas de cada &aacute;rea, &aacute;mbito o materia. Esta vinculaci&oacute;n entre descriptores operativos y competencias espec&iacute;ficas propicia que de la evaluaci&oacute;n de estas &uacute;ltimas pueda colegirse el grado de adquisici&oacute;n de las competencias clave definidas en el Perfil de salida y, por tanto, la consecuci&oacute;n de las competencias y objetivos previstos para la etapa.</p>\r\n<p>Dado que las competencias se adquieren necesariamente de forma secuencial y progresiva, se incluyen tambi&eacute;n en el Perfil los descriptores operativos que orientan sobre el nivel de desempe&ntilde;o esperado al completar la Educaci&oacute;n Primaria, favoreciendo y explicitando as&iacute; la continuidad, la coherencia y la cohesi&oacute;n entre las dos etapas que componen la ense&ntilde;anza obligatoria.</p>\r\n<p><strong>Competencia en comunicaci&oacute;n ling&uuml;&iacute;stica (CCL)</strong></p>\r\n<p>La competencia en comunicaci&oacute;n ling&uuml;&iacute;stica supone interactuar de forma oral, escrita, signada o multimodal de manera coherente y adecuada en diferentes &aacute;mbitos y contextos y con diferentes prop&oacute;sitos comunicativos. Implica movilizar, de manera consciente, el conjunto de conocimientos, destrezas y actitudes que permiten comprender, interpretar y valorar cr&iacute;ticamente mensajes orales, escritos, signados o multimodales evitando los riesgos de manipulaci&oacute;n y desinformaci&oacute;n, as&iacute; como comunicarse eficazmente con otras personas de manera cooperativa, creativa, &eacute;tica y respetuosa.</p>\r\n<p>La competencia en comunicaci&oacute;n ling&uuml;&iacute;stica constituye la base para el pensamiento propio y para la construcci&oacute;n del conocimiento en todos los &aacute;mbitos del saber. Por ello, su desarrollo est&aacute; vinculado a la reflexi&oacute;n expl&iacute;cita acerca del funcionamiento de la lengua en los g&eacute;neros discursivos espec&iacute;ficos de cada &aacute;rea de conocimiento, as&iacute; como a los usos de la oralidad, la escritura o la signaci&oacute;n para pensar y para aprender. Por &uacute;ltimo, hace posible apreciar la dimensi&oacute;n est&eacute;tica del lenguaje y disfrutar de la cultura literaria.</p>\r\n<p><strong>Descriptores operativos</strong></p>\r\n<table border=\"1\" cellpadding=\"8\">\r\n<thead>\r\n<tr>\r\n<th><strong>Al completar la Educaci&oacute;n Primaria, el alumno o la alumna&hellip;</strong></th>\r\n<th><strong>Al completar la ense&ntilde;anza b&aacute;sica, el alumno o la alumna&hellip;</strong></th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p>CCL1. Expresa hechos, conceptos, pensamientos, opiniones o sentimientos de forma oral, escrita, signada o multimodal, con claridad y adecuaci&oacute;n a diferentes contextos cotidianos de su entorno personal, social y educativo, y participa en interacciones comunicativas con actitud cooperativa y respetuosa, tanto para intercambiar informaci&oacute;n y crear conocimiento como para construir v&iacute;nculos personales.</p>\r\n</td>\r\n<td>\r\n<p>CCL1. Se expresa de forma oral, escrita, signada o multimodal con coherencia, correcci&oacute;n y adecuaci&oacute;n a los diferentes contextos sociales, y participa en interacciones comunicativas con actitud cooperativa y respetuosa tanto para intercambiar informaci&oacute;n, crear conocimiento y transmitir opiniones, como para construir v&iacute;nculos personales.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CCL2. Comprende, interpreta y valora textos orales, escritos, signados o multimodales sencillos de los &aacute;mbitos personal, social y educativo, con acompa&ntilde;amiento puntual, para participar activamente en contextos cotidianos y para construir conocimiento.</p>\r\n</td>\r\n<td>\r\n<p>CCL2. Comprende, interpreta y valora con actitud cr&iacute;tica textos orales, escritos, signados o multimodales de los &aacute;mbitos personal, social, educativo y profesional para participar en diferentes contextos de manera activa e informada y para construir conocimiento.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CCL3. Localiza, selecciona y contrasta, con el debido acompa&ntilde;amiento, informaci&oacute;n sencilla procedente de dos o m&aacute;s fuentes, evaluando su fiabilidad y utilidad en funci&oacute;n de los objetivos de lectura, y la integra y transforma en conocimiento para comunicarla adoptando un punto de vista creativo, cr&iacute;tico y personal a la par que respetuoso con la propiedad intelectual.</p>\r\n</td>\r\n<td>\r\n<p>CCL3. Localiza, selecciona y contrasta de manera progresivamente aut&oacute;noma informaci&oacute;n procedente de diferentes fuentes, evaluando su fiabilidad y pertinencia en funci&oacute;n de los objetivos de lectura y evitando los riesgos de manipulaci&oacute;n y desinformaci&oacute;n, y la integra y transforma en conocimiento para comunicarla adoptando un punto de vista creativo, cr&iacute;tico y personal a la par que respetuoso con la propiedad intelectual.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CCL4. Lee obras diversas adecuadas a su progreso madurativo, seleccionando aquellas que mejor se ajustan a sus gustos e intereses; reconoce el patrimonio literario como fuente de disfrute y aprendizaje individual y colectivo; y moviliza su experiencia personal y lectora para construir y compartir su interpretaci&oacute;n de las obras y para crear textos de intenci&oacute;n literaria a partir de modelos sencillos.</p>\r\n</td>\r\n<td>\r\n<p>CCL4. Lee con autonom&iacute;a obras diversas adecuadas a su edad, seleccionando las que mejor se ajustan a sus gustos e intereses; aprecia el patrimonio literario como cauce privilegiado de la experiencia individual y colectiva; y moviliza su propia experiencia biogr&aacute;fica y sus conocimientos literarios y culturales para construir y compartir su interpretaci&oacute;n de las obras y para crear textos de intenci&oacute;n literaria de progresiva complejidad.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CCL5. Pone sus pr&aacute;cticas comunicativas al servicio de la convivencia democr&aacute;tica, la gesti&oacute;n dialogada de los conflictos y la igualdad de derechos de todas las personas, detectando los usos discriminatorios, as&iacute; como los abusos de poder, para favorecer la utilizaci&oacute;n no solo eficaz sino tambi&eacute;n &eacute;tica de los diferentes sistemas de comunicaci&oacute;n.</p>\r\n</td>\r\n<td>\r\n<p>CCL5. Pone sus pr&aacute;cticas comunicativas al servicio de la convivencia democr&aacute;tica, la resoluci&oacute;n dialogada de los conflictos y la igualdad de derechos de todas las personas, evitando los usos discriminatorios, as&iacute; como los abusos de poder, para favorecer la utilizaci&oacute;n no solo eficaz sino tambi&eacute;n &eacute;tica de los diferentes sistemas de comunicaci&oacute;n.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><strong>Competencia pluriling&uuml;e (CP)</strong></p>\r\n<p>La competencia pluriling&uuml;e implica utilizar distintas lenguas, orales o signadas, de forma apropiada y eficaz para el aprendizaje y la comunicaci&oacute;n. Esta competencia supone reconocer y respetar los perfiles ling&uuml;&iacute;sticos individuales y aprovechar las experiencias propias para desarrollar estrategias que permitan mediar y hacer transferencias entre lenguas, incluidas las cl&aacute;sicas, y, en su caso, mantener y adquirir destrezas en la lengua o lenguas familiares y en las lenguas oficiales. Integra, asimismo, dimensiones hist&oacute;ricas e interculturales orientadas a conocer, valorar y respetar la diversidad ling&uuml;&iacute;stica y cultural de la sociedad con el objetivo de fomentar la convivencia democr&aacute;tica.</p>\r\n<p><strong>Descriptores operativos</strong></p>\r\n<table border=\"1\" cellpadding=\"8\">\r\n<thead>\r\n<tr>\r\n<th><strong>Al completar la Educaci&oacute;n Primaria, el alumno o la alumna&hellip;</strong></th>\r\n<th><strong>Al completar la ense&ntilde;anza b&aacute;sica, el alumno o la alumna&hellip;</strong></th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p>CP1. Usa, al menos, una lengua, adem&aacute;s de la lengua o lenguas familiares, para responder a necesidades comunicativas sencillas y predecibles, de manera adecuada tanto a su desarrollo e intereses como a situaciones y contextos cotidianos de los &aacute;mbitos personal, social y educativo.</p>\r\n</td>\r\n<td>\r\n<p>CP1. Usa eficazmente una o m&aacute;s lenguas, adem&aacute;s de la lengua o lenguas familiares, para responder a sus necesidades comunicativas, de manera apropiada y adecuada tanto a su desarrollo e intereses como a diferentes situaciones y contextos de los &aacute;mbitos personal, social, educativo y profesional.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CP2. A partir de sus experiencias, reconoce la diversidad de perfiles ling&uuml;&iacute;sticos y experimenta estrategias que, de manera guiada, le permiten realizar transferencias sencillas entre distintas lenguas para comunicarse en contextos cotidianos y ampliar su repertorio ling&uuml;&iacute;stico individual.</p>\r\n</td>\r\n<td>\r\n<p>CP2. A partir de sus experiencias, realiza transferencias entre distintas lenguas como estrategia para comunicarse y ampliar su repertorio ling&uuml;&iacute;stico individual.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CP3. Conoce y respeta la diversidad ling&uuml;&iacute;stica y cultural presente en su entorno, reconociendo y comprendiendo su valor como factor de di&aacute;logo, para mejorar la convivencia.</p>\r\n</td>\r\n<td>\r\n<p>CP3. Conoce, valora y respeta la diversidad ling&uuml;&iacute;stica y cultural presente en la sociedad, integr&aacute;ndola en su desarrollo personal como factor de di&aacute;logo, para fomentar la cohesi&oacute;n social.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><strong>Competencia matem&aacute;tica y competencia en ciencia, tecnolog&iacute;a e ingenier&iacute;a (STEM)</strong></p>\r\n<p>La competencia matem&aacute;tica y competencia en ciencia, tecnolog&iacute;a e ingenier&iacute;a (competencia STEM por sus siglas en ingl&eacute;s) entra&ntilde;a la comprensi&oacute;n del mundo utilizando los m&eacute;todos cient&iacute;ficos, el pensamiento y representaci&oacute;n matem&aacute;ticos, la tecnolog&iacute;a y los m&eacute;todos de la ingenier&iacute;a para transformar el entorno de forma comprometida, responsable y sostenible.</p>\r\n<p>La competencia matem&aacute;tica permite desarrollar y aplicar la perspectiva y el razonamiento matem&aacute;ticos con el fin de resolver diversos problemas en diferentes contextos.</p>\r\n<p>La competencia en ciencia conlleva la comprensi&oacute;n y explicaci&oacute;n del entorno natural y social, utilizando un conjunto de conocimientos y metodolog&iacute;as, incluidas la observaci&oacute;n y la experimentaci&oacute;n, con el fin de plantear preguntas y extraer conclusiones basadas en pruebas para poder interpretar y transformar el mundo natural y el contexto social.</p>\r\n<p>La competencia en tecnolog&iacute;a e ingenier&iacute;a comprende la aplicaci&oacute;n de los conocimientos y metodolog&iacute;as propios de las ciencias para transformar nuestra sociedad de acuerdo con las necesidades o deseos de las personas en un marco de seguridad, responsabilidad y sostenibilidad.</p>\r\n<p><strong>Descriptores operativos</strong></p>\r\n<table border=\"1\" cellpadding=\"8\">\r\n<thead>\r\n<tr>\r\n<th><strong>Al completar la Educaci&oacute;n Primaria, el alumno o la alumna&hellip;</strong></th>\r\n<th><strong>Al completar la ense&ntilde;anza b&aacute;sica, el alumno o la alumna&hellip;</strong></th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p>STEM1. Utiliza, de manera guiada, algunos m&eacute;todos inductivos y deductivos propios del razonamiento matem&aacute;tico en situaciones conocidas, y selecciona y emplea algunas estrategias para resolver problemas reflexionando sobre las soluciones obtenidas.</p>\r\n</td>\r\n<td>\r\n<p>STEM1. Utiliza m&eacute;todos inductivos y deductivos propios del razonamiento matem&aacute;tico en situaciones conocidas, y selecciona y emplea diferentes estrategias para resolver problemas analizando cr&iacute;ticamente las soluciones y reformulando el procedimiento, si fuera necesario.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>STEM2. Utiliza el pensamiento cient&iacute;fico para entender y explicar algunos de los fen&oacute;menos que ocurren a su alrededor, confiando en el conocimiento como motor de desarrollo, utilizando herramientas e instrumentos adecuados, plante&aacute;ndose preguntas y realizando experimentos sencillos de forma guiada.</p>\r\n</td>\r\n<td>\r\n<p>STEM2. Utiliza el pensamiento cient&iacute;fico para entender y explicar los fen&oacute;menos que ocurren a su alrededor, confiando en el conocimiento como motor de desarrollo, plante&aacute;ndose preguntas y comprobando hip&oacute;tesis mediante la experimentaci&oacute;n y la indagaci&oacute;n, utilizando herramientas e instrumentos adecuados, apreciando la importancia de la precisi&oacute;n y la veracidad y mostrando una actitud cr&iacute;tica acerca del alcance y las limitaciones de la ciencia.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>STEM3. Realiza, de forma guiada, proyectos, dise&ntilde;ando, fabricando y evaluando diferentes prototipos o modelos, adapt&aacute;ndose ante la incertidumbre, para generar en equipo un producto creativo con un objetivo concreto, procurando la participaci&oacute;n de todo el grupo y resolviendo pac&iacute;ficamente los conflictos que puedan surgir.</p>\r\n</td>\r\n<td>\r\n<p>STEM3. Plantea y desarrolla proyectos dise&ntilde;ando, fabricando y evaluando diferentes prototipos o modelos para generar o utilizar productos que den soluci&oacute;n a una necesidad o problema de forma creativa y en equipo, procurando la participaci&oacute;n de todo el grupo, resolviendo pac&iacute;ficamente los conflictos que puedan surgir, adapt&aacute;ndose ante la incertidumbre y valorando la importancia de la sostenibilidad.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>STEM4. Interpreta y transmite los elementos m&aacute;s relevantes de algunos m&eacute;todos y resultados cient&iacute;ficos, matem&aacute;ticos y tecnol&oacute;gicos de forma clara y veraz, utilizando la terminolog&iacute;a cient&iacute;fica apropiada, en diferentes formatos (dibujos, diagramas, gr&aacute;ficos, s&iacute;mbolos&hellip;) y aprovechando de forma cr&iacute;tica, &eacute;tica y responsable la cultura digital para compartir y construir nuevos conocimientos.</p>\r\n</td>\r\n<td>\r\n<p>STEM4. Interpreta y transmite los elementos m&aacute;s relevantes de procesos, razonamientos, demostraciones, m&eacute;todos y resultados cient&iacute;ficos, matem&aacute;ticos y tecnol&oacute;gicos de forma clara y precisa y en diferentes formatos (gr&aacute;ficos, tablas, diagramas, f&oacute;rmulas, esquemas, s&iacute;mbolos...), aprovechando de forma cr&iacute;tica la cultura digital e incluyendo el lenguaje matem&aacute;tico-formal con &eacute;tica y responsabilidad, para compartir y construir nuevos conocimientos.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>STEM5. Participa en acciones fundamentadas cient&iacute;ficamente para promover la salud y preservar el medio ambiente y los seres vivos, aplicando principios de &eacute;tica y seguridad y practicando el consumo responsable.</p>\r\n</td>\r\n<td>\r\n<p>STEM5. Emprende acciones fundamentadas cient&iacute;ficamente para promover la salud f&iacute;sica, mental y social, y preservar el medio ambiente y los seres vivos; y aplica principios de &eacute;tica y seguridad en la realizaci&oacute;n de proyectos para transformar su entorno pr&oacute;ximo de forma sostenible, valorando su impacto global y practicando el consumo responsable.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><strong>Competencia digital (CD)</strong></p>\r\n<p>La competencia digital implica el uso seguro, saludable, sostenible, cr&iacute;tico y responsable de las tecnolog&iacute;as digitales para el aprendizaje, para el trabajo y para la participaci&oacute;n en la sociedad, as&iacute; como la interacci&oacute;n con estas.</p>\r\n<p>Incluye la alfabetizaci&oacute;n en informaci&oacute;n y datos, la comunicaci&oacute;n y la colaboraci&oacute;n, la educaci&oacute;n medi&aacute;tica, la creaci&oacute;n de contenidos digitales (incluida la programaci&oacute;n), la seguridad (incluido el bienestar digital y las competencias relacionadas con la ciberseguridad), asuntos relacionados con la ciudadan&iacute;a digital, la privacidad, la propiedad intelectual, la resoluci&oacute;n de problemas y el pensamiento computacional y cr&iacute;tico.</p>\r\n<p><strong>Descriptores operativos</strong></p>\r\n<table border=\"1\" cellpadding=\"8\">\r\n<thead>\r\n<tr>\r\n<th><strong>Al completar la Educaci&oacute;n Primaria, el alumno o la alumna&hellip;</strong></th>\r\n<th><strong>Al completar la ense&ntilde;anza b&aacute;sica, el alumno o la alumna&hellip;</strong></th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p>CD1. Realiza b&uacute;squedas guiadas en internet y hace uso de estrategias sencillas para el tratamiento digital de la informaci&oacute;n (palabras clave, selecci&oacute;n de informaci&oacute;n relevante, organizaci&oacute;n de datos...) con una actitud cr&iacute;tica sobre los contenidos obtenidos.</p>\r\n</td>\r\n<td>\r\n<p>CD1. Realiza b&uacute;squedas en internet atendiendo a criterios de validez, calidad, actualidad y fiabilidad, seleccionando los resultados de manera cr&iacute;tica y archiv&aacute;ndolos, para recuperarlos, referenciarlos y reutilizarlos, respetando la propiedad intelectual.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CD2. Crea, integra y reelabora contenidos digitales en distintos formatos (texto, tabla, imagen, audio, v&iacute;deo, programa inform&aacute;tico...) mediante el uso de diferentes herramientas digitales para expresar ideas, sentimientos y conocimientos, respetando la propiedad intelectual y los derechos de autor de los contenidos que reutiliza.</p>\r\n</td>\r\n<td>\r\n<p>CD2. Gestiona y utiliza su entorno personal digital de aprendizaje para construir conocimiento y crear contenidos digitales, mediante estrategias de tratamiento de la informaci&oacute;n y el uso de diferentes herramientas digitales, seleccionando y configurando la m&aacute;s adecuada en funci&oacute;n de la tarea y de sus necesidades de aprendizaje permanente.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CD3. Participa en actividades o proyectos escolares mediante el uso de herramientas o plataformas virtuales para construir nuevo conocimiento, comunicarse, trabajar cooperativamente, y compartir datos y contenidos en entornos digitales restringidos y supervisados de manera segura, con una actitud abierta y responsable ante su uso.</p>\r\n</td>\r\n<td>\r\n<p>CD3. Se comunica, participa, colabora e interact&uacute;a compartiendo contenidos, datos e informaci&oacute;n mediante herramientas o plataformas virtuales, y gestiona de manera responsable sus acciones, presencia y visibilidad en la red, para ejercer una ciudadan&iacute;a digital activa, c&iacute;vica y reflexiva.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CD4. Conoce los riesgos y adopta, con la orientaci&oacute;n del docente, medidas preventivas al usar las tecnolog&iacute;as digitales para proteger los dispositivos, los datos personales, la salud y el medioambiente, y se inicia en la adopci&oacute;n de h&aacute;bitos de uso cr&iacute;tico, seguro, saludable y sostenible de dichas tecnolog&iacute;as.</p>\r\n</td>\r\n<td>\r\n<p>CD4. Identifica riesgos y adopta medidas preventivas al usar las tecnolog&iacute;as digitales para proteger los dispositivos, los datos personales, la salud y el medioambiente, y para tomar conciencia de la importancia y necesidad de hacer un uso cr&iacute;tico, legal, seguro, saludable y sostenible de dichas tecnolog&iacute;as.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CD5. Se inicia en el desarrollo de soluciones digitales sencillas y sostenibles (reutilizaci&oacute;n de materiales tecnol&oacute;gicos, programaci&oacute;n inform&aacute;tica por bloques, rob&oacute;tica educativa&hellip;) para resolver problemas concretos o retos propuestos de manera creativa, solicitando ayuda en caso necesario.</p>\r\n</td>\r\n<td>\r\n<p>CD5. Desarrolla aplicaciones inform&aacute;ticas sencillas y soluciones tecnol&oacute;gicas creativas y sostenibles para resolver problemas concretos o responder a retos propuestos, mostrando inter&eacute;s y curiosidad por la evoluci&oacute;n de las tecnolog&iacute;as digitales y por su desarrollo sostenible y uso &eacute;tico.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><strong>Competencia personal, social y de aprender a aprender (CPSAA)</strong></p>\r\n<p>La competencia personal, social y de aprender a aprender implica la capacidad de reflexionar sobre uno mismo para autoconocerse, aceptarse y promover un crecimiento personal constante; gestionar el tiempo y la informaci&oacute;n eficazmente; colaborar con otros de forma constructiva; mantener la resiliencia; y gestionar el aprendizaje a lo largo de la vida. Incluye tambi&eacute;n la capacidad de hacer frente a la incertidumbre y a la complejidad; adaptarse a los cambios; aprender a gestionar los procesos metacognitivos; identificar conductas contrarias a la convivencia y desarrollar estrategias para abordarlas; contribuir al bienestar f&iacute;sico, mental y emocional propio y de las dem&aacute;s personas, desarrollando habilidades para cuidarse a s&iacute; mismo y a quienes lo rodean a trav&eacute;s de la corresponsabilidad; ser capaz de llevar una vida orientada al futuro; as&iacute; como expresar empat&iacute;a y abordar los conflictos en un contexto integrador y de apoyo.</p>\r\n<p><strong>Descriptores operativos</strong></p>\r\n<table border=\"1\" cellpadding=\"8\">\r\n<thead>\r\n<tr>\r\n<th><strong>Al completar la Educaci&oacute;n Primaria, el alumno o la alumna&hellip;</strong></th>\r\n<th><strong>Al completar la ense&ntilde;anza b&aacute;sica, el alumno o la alumna&hellip;</strong></th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p>CPSAA1. Es consciente de las propias emociones, ideas y comportamientos personales y emplea estrategias para gestionarlas en situaciones de tensi&oacute;n o conflicto, adapt&aacute;ndose a los cambios y armoniz&aacute;ndolos para alcanzar sus propios objetivos.</p>\r\n</td>\r\n<td>\r\n<p>CPSAA1. Regula y expresa sus emociones, fortaleciendo el optimismo, la resiliencia, la autoeficacia y la b&uacute;squeda de prop&oacute;sito y motivaci&oacute;n hacia el aprendizaje, para gestionar los retos y cambios y armonizarlos con sus propios objetivos.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CPSAA2. Conoce los riesgos m&aacute;s relevantes y los principales activos para la salud, adopta estilos de vida saludables para su bienestar f&iacute;sico y mental, y detecta y busca apoyo ante situaciones violentas o discriminatorias.</p>\r\n</td>\r\n<td>\r\n<p>CPSAA2. Comprende los riesgos para la salud relacionados con factores sociales, consolida estilos de vida saludable a nivel f&iacute;sico y mental, reconoce conductas contrarias a la convivencia y aplica estrategias para abordarlas.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CPSAA3. Reconoce y respeta las emociones y experiencias de las dem&aacute;s personas, participa activamente en el trabajo en grupo, asume las responsabilidades individuales asignadas y emplea estrategias cooperativas dirigidas a la consecuci&oacute;n de objetivos compartidos.</p>\r\n</td>\r\n<td>\r\n<p>CPSAA3. Comprende proactivamente las perspectivas y las experiencias de las dem&aacute;s personas y las incorpora a su aprendizaje, para participar en el trabajo en grupo, distribuyendo y aceptando tareas y responsabilidades de manera equitativa y empleando estrategias cooperativas.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CPSAA4. Reconoce el valor del esfuerzo y la dedicaci&oacute;n personal para la mejora de su aprendizaje y adopta posturas cr&iacute;ticas en procesos de reflexi&oacute;n guiados.</p>\r\n</td>\r\n<td>\r\n<p>CPSAA4. Realiza autoevaluaciones sobre su proceso de aprendizaje, buscando fuentes fiables para validar, sustentar y contrastar la informaci&oacute;n y para obtener conclusiones relevantes.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CPSAA5. Planea objetivos a corto plazo, utiliza estrategias de aprendizaje autorregulado y participa en procesos de auto y coevaluaci&oacute;n, reconociendo sus limitaciones y sabiendo buscar ayuda en el proceso de construcci&oacute;n del conocimiento.</p>\r\n</td>\r\n<td>\r\n<p>CPSAA5. Planea objetivos a medio plazo y desarrolla procesos metacognitivos de retroalimentaci&oacute;n para aprender de sus errores en el proceso de construcci&oacute;n del conocimiento.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><strong>Competencia ciudadana (CC)</strong></p>\r\n<p>La competencia ciudadana contribuye a que alumnos y alumnas puedan ejercer una ciudadan&iacute;a responsable y participar plenamente en la vida social y c&iacute;vica, bas&aacute;ndose en la comprensi&oacute;n de los conceptos y las estructuras sociales, econ&oacute;micas, jur&iacute;dicas y pol&iacute;ticas, as&iacute; como en el conocimiento de los acontecimientos mundiales y el compromiso activo con la sostenibilidad y el logro de una ciudadan&iacute;a mundial. Incluye la alfabetizaci&oacute;n c&iacute;vica, la adopci&oacute;n consciente de los valores propios de una cultura democr&aacute;tica fundada en el respeto a los derechos humanos, la reflexi&oacute;n cr&iacute;tica acerca de los grandes problemas &eacute;ticos de nuestro tiempo y el desarrollo de un estilo de vida sostenible acorde con los Objetivos de Desarrollo Sostenible planteados en la Agenda 2030.</p>\r\n<p><strong>Descriptores operativos</strong></p>\r\n<table border=\"1\" cellpadding=\"8\">\r\n<thead>\r\n<tr>\r\n<th><strong>Al completar la Educaci&oacute;n Primaria, el alumno o la alumna&hellip;</strong></th>\r\n<th><strong>Al completar la ense&ntilde;anza b&aacute;sica, el alumno o la alumna&hellip;</strong></th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p>CC1. Entiende los procesos hist&oacute;ricos y sociales m&aacute;s relevantes relativos a su propia identidad y cultura, reflexiona sobre las normas de convivencia, y las aplica de manera constructiva, dialogante e inclusiva en cualquier contexto.</p>\r\n</td>\r\n<td>\r\n<p>CC1. Analiza y comprende ideas relativas a la dimensi&oacute;n social y ciudadana de su propia identidad, as&iacute; como a los hechos culturales, hist&oacute;ricos y normativos que la determinan, demostrando respeto por las normas, empat&iacute;a, equidad y esp&iacute;ritu constructivo en la interacci&oacute;n con los dem&aacute;s en cualquier contexto.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CC2. Participa en actividades comunitarias, en la toma de decisiones y en la resoluci&oacute;n de los conflictos de forma dialogada y respetuosa con los procedimientos democr&aacute;ticos, los principios y valores de la Uni&oacute;n Europea y la Constituci&oacute;n espa&ntilde;ola, los derechos humanos y de la infancia, el valor de la diversidad, y el logro de la igualdad de g&eacute;nero, la cohesi&oacute;n social y los Objetivos de Desarrollo Sostenible.</p>\r\n</td>\r\n<td>\r\n<p>CC2. Analiza y asume fundadamente los principios y valores que emanan del proceso de integraci&oacute;n europea, la Constituci&oacute;n espa&ntilde;ola y los derechos humanos y de la infancia, participando en actividades comunitarias, como la toma de decisiones o la resoluci&oacute;n de conflictos, con actitud democr&aacute;tica, respeto por la diversidad, y compromiso con la igualdad de g&eacute;nero, la cohesi&oacute;n social, el desarrollo sostenible y el logro de la ciudadan&iacute;a mundial.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CC3. Reflexiona y dialoga sobre valores y problemas &eacute;ticos de actualidad, comprendiendo la necesidad de respetar diferentes culturas y creencias, de cuidar el entorno, de rechazar prejuicios y estereotipos, y de oponerse a cualquier forma de discriminaci&oacute;n o violencia.</p>\r\n</td>\r\n<td>\r\n<p>CC3. Comprende y analiza problemas &eacute;ticos fundamentales y de actualidad, considerando cr&iacute;ticamente los valores propios y ajenos, y desarrollando juicios propios para afrontar la controversia moral con actitud dialogante, argumentativa, respetuosa y opuesta a cualquier tipo de discriminaci&oacute;n o violencia.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CC4. Comprende las relaciones sist&eacute;micas entre las acciones humanas y el entorno, y se inicia en la adopci&oacute;n de estilos de vida sostenibles, para contribuir a la conservaci&oacute;n de la biodiversidad desde una perspectiva tanto local como global.</p>\r\n</td>\r\n<td>\r\n<p>CC4. Comprende las relaciones sist&eacute;micas de interdependencia, ecodependencia e interconexi&oacute;n entre actuaciones locales y globales, y adopta, de forma consciente y motivada, un estilo de vida sostenible y ecosocialmente responsable.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><strong>Competencia emprendedora (CE)</strong></p>\r\n<p>La competencia emprendedora implica desarrollar un enfoque vital dirigido a actuar sobre oportunidades e ideas, utilizando los conocimientos espec&iacute;ficos necesarios para generar resultados de valor para otras personas. Aporta estrategias que permiten adaptar la mirada para detectar necesidades y oportunidades; entrenar el pensamiento para analizar y evaluar el entorno, y crear y replantear ideas utilizando la imaginaci&oacute;n, la creatividad, el pensamiento estrat&eacute;gico y la reflexi&oacute;n &eacute;tica, cr&iacute;tica y constructiva dentro de los procesos creativos y de innovaci&oacute;n; y despertar la disposici&oacute;n a aprender, a arriesgar y a afrontar la incertidumbre. Asimismo, implica tomar decisiones basadas en la informaci&oacute;n y el conocimiento y colaborar de manera &aacute;gil con otras personas, con motivaci&oacute;n, empat&iacute;a y habilidades de comunicaci&oacute;n y de negociaci&oacute;n, para llevar las ideas planteadas a la acci&oacute;n mediante la planificaci&oacute;n y gesti&oacute;n de proyectos sostenibles de valor social, cultural y econ&oacute;mico-financiero.</p>\r\n<p><strong>Descriptores operativos</strong></p>\r\n<table border=\"1\" cellpadding=\"8\">\r\n<thead>\r\n<tr>\r\n<th><strong>Al completar la Educaci&oacute;n Primaria, el alumno o la alumna&hellip;</strong></th>\r\n<th><strong>Al completar la ense&ntilde;anza b&aacute;sica, el alumno o la alumna&hellip;</strong></th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p>CE1. Reconoce necesidades y retos que afrontar y elabora ideas originales, utilizando destrezas creativas y tomando conciencia de las consecuencias y efectos que las ideas pudieran generar en el entorno, para proponer soluciones valiosas que respondan a las necesidades detectadas.</p>\r\n</td>\r\n<td>\r\n<p>CE1. Analiza necesidades y oportunidades y afronta retos con sentido cr&iacute;tico, haciendo balance de su sostenibilidad, valorando el impacto que puedan suponer en el entorno, para presentar ideas y soluciones innovadoras, &eacute;ticas y sostenibles, dirigidas a crear valor en el &aacute;mbito personal, social, educativo y profesional.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CE2. Identifica fortalezas y debilidades propias utilizando estrategias de autoconocimiento y se inicia en el conocimiento de elementos econ&oacute;micos y financieros b&aacute;sicos, aplic&aacute;ndolos a situaciones y problemas de la vida cotidiana, para detectar aquellos recursos que puedan llevar las ideas originales y valiosas a la acci&oacute;n.</p>\r\n</td>\r\n<td>\r\n<p>CE2. Eval&uacute;a las fortalezas y debilidades propias, haciendo uso de estrategias de autoconocimiento y autoeficacia, y comprende los elementos fundamentales de la econom&iacute;a y las finanzas, aplicando conocimientos econ&oacute;micos y financieros a actividades y situaciones concretas, utilizando destrezas que favorezcan el trabajo colaborativo y en equipo, para reunir y optimizar los recursos necesarios que lleven a la acci&oacute;n una experiencia emprendedora que genere valor.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CE3. Crea ideas y soluciones originales, planifica tareas, coopera con otros en equipo, valorando el proceso realizado y el resultado obtenido, para llevar a cabo una iniciativa emprendedora, considerando la experiencia como una oportunidad para aprender.</p>\r\n</td>\r\n<td>\r\n<p>CE3. Desarrolla el proceso de creaci&oacute;n de ideas y soluciones valiosas y toma decisiones, de manera razonada, utilizando estrategias &aacute;giles de planificaci&oacute;n y gesti&oacute;n, y reflexiona sobre el proceso realizado y el resultado obtenido, para llevar a t&eacute;rmino el proceso de creaci&oacute;n de prototipos innovadores y de valor, considerando la experiencia como una oportunidad para aprender.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><strong>Competencia en conciencia y expresi&oacute;n culturales (CCEC)</strong></p>\r\n<p>La competencia en conciencia y expresi&oacute;n culturales supone comprender y respetar el modo en que las ideas, las opiniones, los sentimientos y las emociones se expresan y se comunican de forma creativa en distintas culturas y por medio de una amplia gama de manifestaciones art&iacute;sticas y culturales. Implica tambi&eacute;n un compromiso con la comprensi&oacute;n, el desarrollo y la expresi&oacute;n de las ideas propias y del sentido del lugar que se ocupa o del papel que se desempe&ntilde;a en la sociedad. Asimismo, requiere la comprensi&oacute;n de la propia identidad en evoluci&oacute;n y del patrimonio cultural en un mundo caracterizado por la diversidad, as&iacute; como la toma de conciencia de que el arte y otras manifestaciones culturales pueden suponer una manera de mirar el mundo y de darle forma.</p>\r\n<p><strong>Descriptores operativos</strong></p>\r\n<table border=\"1\" cellpadding=\"8\">\r\n<thead>\r\n<tr>\r\n<th><strong>Al completar la Educaci&oacute;n Primaria, el alumno o la alumna&hellip;</strong></th>\r\n<th><strong>Al completar la ense&ntilde;anza b&aacute;sica, el alumno o la alumna&hellip;</strong></th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p>CCEC1. Reconoce y aprecia los aspectos fundamentales del patrimonio cultural y art&iacute;stico, comprendiendo las diferencias entre distintas culturas y la necesidad de respetarlas.</p>\r\n</td>\r\n<td>\r\n<p>CCEC1. Conoce, aprecia cr&iacute;ticamente y respeta el patrimonio cultural y art&iacute;stico, implic&aacute;ndose en su conservaci&oacute;n y valorando el enriquecimiento inherente a la diversidad cultural y art&iacute;stica.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CCEC2. Reconoce y se interesa por las especificidades e intencionalidades de las manifestaciones art&iacute;sticas y culturales m&aacute;s destacadas del patrimonio, identificando los medios y soportes, as&iacute; como los lenguajes y elementos t&eacute;cnicos que las caracterizan.</p>\r\n</td>\r\n<td>\r\n<p>CCEC2. Disfruta, reconoce y analiza con autonom&iacute;a las especificidades e intencionalidades de las manifestaciones art&iacute;sticas y culturales m&aacute;s destacadas del patrimonio, distinguiendo los medios y soportes, as&iacute; como los lenguajes y elementos t&eacute;cnicos que las caracterizan.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CCEC3. Expresa ideas, opiniones, sentimientos y emociones de forma creativa y con una actitud abierta e inclusiva, empleando distintos lenguajes art&iacute;sticos y culturales, integrando su propio cuerpo, interactuando con el entorno y desarrollando sus capacidades afectivas.</p>\r\n</td>\r\n<td>\r\n<p>CCEC3. Expresa ideas, opiniones, sentimientos y emociones por medio de producciones culturales y art&iacute;sticas, integrando su propio cuerpo y desarrollando la autoestima, la creatividad y el sentido del lugar que ocupa en la sociedad, con una actitud emp&aacute;tica, abierta y colaborativa.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CCEC4. Experimenta de forma creativa con diferentes medios y soportes, y diversas t&eacute;cnicas pl&aacute;sticas, visuales, audiovisuales, sonoras o corporales, para elaborar propuestas art&iacute;sticas y culturales.</p>\r\n</td>\r\n<td>\r\n<p>CCEC4. Conoce, selecciona y utiliza con creatividad diversos medios y soportes, as&iacute; como t&eacute;cnicas pl&aacute;sticas, visuales, audiovisuales, sonoras o corporales, para la creaci&oacute;n de productos art&iacute;sticos y culturales, tanto de forma individual como colaborativa, identificando oportunidades de desarrollo personal, social y laboral, as&iacute; como de emprendimiento.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>'),
(3166, 18, 42, '<p>Reconocimiento de las caracter&iacute;sticas de lenguajes de marcas:</p>\r\n<p>&minus; Clasificaci&oacute;n. &minus; Caracter&iacute;sticas y &aacute;mbitos de aplicaci&oacute;n. &minus; Estructura y sintaxis. &minus; Herramientas de edici&oacute;n. &minus; Elaboraci&oacute;n de documentos bien formados. &minus; Utilizaci&oacute;n de espacios de nombres.</p>\r\n<p>Utilizaci&oacute;n de lenguajes de marcas en entornos web:</p>\r\n<p>&minus; Est&aacute;ndares web. Versiones. Clasificaci&oacute;n. &minus; Estructura de un documento HTML. &minus; Identificaci&oacute;n de etiquetas y atributos de HTML. &minus; Herramientas de dise&ntilde;o web. &minus; Hojas de estilo (CSS). &minus; Validaci&oacute;n de documentos HTML y CSS. &minus; Lenguajes de marcas para la sindicaci&oacute;n de contenidos.</p>\r\n<p>Manipulaci&oacute;n de documentos Web:</p>\r\n<p>&minus; Lenguajes de script de cliente. Caracter&iacute;sticas y sintaxis b&aacute;sica. Est&aacute;ndares. &minus; Selecci&oacute;n y acceso a elementos. &minus; Creaci&oacute;n y modificaci&oacute;n de elementos. &minus; Eliminaci&oacute;n de elementos. &minus; Manipulaci&oacute;n de estilos.</p>\r\n<p>Definici&oacute;n de esquemas y vocabularios en lenguajes de marcas:</p>\r\n<p>&minus; Tecnolog&iacute;as para la definici&oacute;n de documentos. Estructura y sintaxis. &minus; Creaci&oacute;n de descripciones de documentos. &minus; Asociaci&oacute;n de descripciones con documentos. Validaci&oacute;n. &minus; Herramientas de creaci&oacute;n y validaci&oacute;n.</p>\r\n<p>Conversi&oacute;n y adaptaci&oacute;n de documentos para el intercambio de informaci&oacute;n:</p>\r\n<p>&minus; Tecnolog&iacute;as de transformaci&oacute;n de documentos. Est&aacute;ndares. &Aacute;mbitos de aplicaci&oacute;n. &minus; Descripci&oacute;n de la estructura y de la sintaxis. &minus; Creaci&oacute;n y utilizaci&oacute;n de plantillas. Herramientas y depuraci&oacute;n. &minus; Conversi&oacute;n entre diferentes formatos de documentos.</p>\r\n<p>Almacenamiento de informaci&oacute;n:</p>\r\n<p>&minus; Sistemas de almacenamiento de informaci&oacute;n. Caracter&iacute;sticas. Tecnolog&iacute;as. &minus; Lenguajes de consulta y manipulaci&oacute;n en documentos. &minus; Consulta y manipulaci&oacute;n de informaci&oacute;n. &minus; Importaci&oacute;n y exportaci&oacute;n de bases de datos relacionales en diferentes formatos. &minus; Herramientas de tratamiento y almacenamiento de informaci&oacute;n en sistemas nativos. &minus; Almacenamiento y manipulaci&oacute;n de informaci&oacute;n en sistemas nativos.</p>\r\n<p>Sistemas de gesti&oacute;n empresarial:</p>\r\n<p>&minus; Aplicaciones de gesti&oacute;n empresarial. Tipos. Caracter&iacute;sticas. &minus; Instalaci&oacute;n. &minus; Administraci&oacute;n y configuraci&oacute;n. &minus; Integraci&oacute;n de m&oacute;dulos. &minus; Mecanismos de acceso seguro a la informaci&oacute;n. Roles y privilegios. &minus; Elaboraci&oacute;n de informes. &minus; Exportaci&oacute;n de informaci&oacute;n. &minus; Elaboraci&oacute;n de documentaci&oacute;n.</p>'),
(3169, 366, 9, '<p>En el apartado \"Resultados de aprendizaje\", detallado previamente, se relacionan los resultados de aprendizaje con sus correspondientes&nbsp;criterios de evaluci&oacute;n.</p>'),
(3170, 366, 18, '<p>Los materiales consultados para la confecci&oacute;n del presente documento y el m&oacute;dulo en s&iacute; son los siguientes:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Pressman, R. S., &amp; Maxim, B. R. (2020). <em>Software Engineering: A Practitioner\'s Approach (9th Edition).</em></strong> McGraw-Hill Education.</p>\r\n</li>\r\n<li>\r\n<p><strong>Rubin, K. S. (2012). <em>Essential Scrum: A Practical Guide to the Most Popular Agile Process.</em></strong> Addison-Wesley Professional.</p>\r\n</li>\r\n<li>\r\n<p><strong>Freeman, A., &amp; Robson, K. (2018). <em>Head First Git.</em></strong> O\'Reilly Media.</p>\r\n</li>\r\n<li>\r\n<p><strong>Farrell, J. (2021). <em>Microsoft Teams For Dummies.</em></strong> Wiley.<br />Una gu&iacute;a accesible sobre el uso de Microsoft Teams, herramienta clave para la colaboraci&oacute;n y comunicaci&oacute;n en equipos de desarrollo de software, cubriendo las competencias del RA4.</p>\r\n</li>\r\n</ul>\r\n<p>&nbsp;</p>'),
(3171, 366, 6, '<p>La secuenciaci&oacute;n y temporalizaci&oacute;n de las unidades did&aacute;cticas del m&oacute;dulo es la siguiente:</p>\r\n<table border=\"1\">\r\n<tbody>\r\n<tr>\r\n<th>UNIDAD</th>\r\n<th>SEMANAS</th>\r\n</tr>\r\n<tr>\r\n<td>UD 1. INTRODUCCI&Oacute;N AL PROYECTO INTERMODULAR</td>\r\n<td>09/09 -23/09</td>\r\n</tr>\r\n<tr>\r\n<td>UD2. COMUNICACI&Oacute;N EFECTIVA</td>\r\n<td>30/09-28/10</td>\r\n</tr>\r\n<tr>\r\n<td>UD3.DESARROLLO, PLANIFICACI&Oacute;N Y GESTI&Oacute;N DE PROYECTOS SOFTWARE</td>\r\n<td>04/11-06/01</td>\r\n</tr>\r\n<tr>\r\n<td>UD4. TRABAJO COLABORATIVO Y EN EQUIPO</td>\r\n<td>13/01-14/04</td>\r\n</tr>\r\n<tr>\r\n<td>UD5. CONTROL DE VERSIONES CON GIT EN UN PROYECTO SW</td>\r\n<td>21/04-fin</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>El&nbsp;<strong>primer trimestre</strong>&nbsp;incluir&aacute; las unidades did&aacute;cticas: UD1-UD2 y parte UD3</p>\r\n<p>El&nbsp;<strong>segundo trimestre</strong>&nbsp;incluir&aacute; las unidades did&aacute;cticas: UD3-UD4</p>\r\n<p>El&nbsp;<strong>tercer trimestre</strong>&nbsp;incluir&aacute; las unidades did&aacute;cticas: UD5</p>'),
(3173, 7, 40, ''),
(3175, 72, 35, ''),
(3176, 367, 1, '<p>El presente documento corresponde a la programaci&oacute;n did&aacute;ctica del m&oacute;dulo de Proyecto Intermodular, que se imparte en el primer curso del ciclo formativo de grado superior de Desarrollo de Aplicaciones Web, en adelante DAW.</p>\r\n<p>Este modulo se desarrolla a lo largo de los tres trimestres del curso acad&eacute;mico distribuido en una carga horaria de 1 hora semanal.</p>\r\n<p>Las bases legislativas m&aacute;s relevantes que fundamentan esta programaci&oacute;n did&aacute;ctica son las siguientes:</p>\r\n<p>a) Ley Org&aacute;nica 3/2020, de 29 de diciembre (LOMLOE), por la que se modifica la Ley Org&aacute;nica 2/2006, de 3 de mayo, de Educaci&oacute;n (LOE)</p>\r\n<p>b) Real Decreto 1147/2011, de 29 de julio, por el que se establece la ordenaci&oacute;n general de la formaci&oacute;n profesional del sistema educativo.</p>\r\n<p>c) RESOLUCI&Oacute;N de 8 de agosto de 2024, de la Secretar&iacute;a Auton&oacute;mica de Educaci&oacute;n, por la cual se dictan instrucciones sobre ordenaci&oacute;n acad&eacute;mica y de organizaci&oacute;n de los centros que imparten Formaci&oacute;n Profesional durante el curso 2024-2025 en la Comunitat Valenciana.</p>\r\n<p>d) DECRETO 252/2019, de 29 de noviembre, del Consell, de regulaci&oacute;n de la organizaci&oacute;n y el funcionamiento de los centros p&uacute;blicos que imparten ense&ntilde;anzas de Educaci&oacute;n Secundaria Obligatoria, Bachillerato y Formaci&oacute;n Profesional.</p>\r\n<p>e) ORDEN 79/2010, de 27 de agosto, de la Conselleria de Educaci&oacute;n, por la que se regula la evaluaci&oacute;n del alumnado de los ciclos formativos de Formaci&oacute;n Profesional del sistema educativo en el &aacute;mbito territorial de la Comunitat Valenciana.</p>\r\n<p>f) Real Decreto 405/2023, de 29 de mayo, por el que se actualizan los t&iacute;tulos de la formaci&oacute;n profesional del sistema educativo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Multiplataforma y T&eacute;cnico Superior en Desarrollo de Aplicaciones Web, y se fijan sus ense&ntilde;anzas m&iacute;nimas.</p>\r\n<p>g) Real Decreto de T&iacute;tulo 450/2010 de 16 de abril, por el que se establece el t&iacute;tulo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Multiplataforma y se fijan sus ense&ntilde;anzas m&iacute;nimas.</p>\r\n<p>h) Orden 58/2012 de 5 de septiembre por la que se establece el curr&iacute;culo correspondiente al t&iacute;tulo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Multiplataforma para la Comunidad Valenciana.</p>\r\n<p>i) Real Decreto 659/2023, de 18 de julio, por el que se desarrolla la ordenaci&oacute;n del Sistema de Formaci&oacute;n Profesional.</p>\r\n<p>j) Real Decreto 500/2024, de 21 de mayo, por el que se modifican determinados reales decretos por los que se establecen t&iacute;tulos de Formaci&oacute;n Profesional de grado superior y se fijan sus ense&ntilde;anzas m&iacute;nimas.</p>');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3177, 367, 2, '<p>Esta programaci&oacute;n est&aacute; desarrollada para el centro en el que se imparte, el I.E.S San Vicente.</p>\r\n<p>El I.E.S San Vicente es un centro p&uacute;blico ubicado en el n&uacute;cleo urbano de San Vicente, el cual cuenta con una poblaci&oacute;n que ronda los 55.000 habitantes, donde acuden numerosos alumnos y alumnas de zonas cercanas con menor poblaci&oacute;n, como puede ser Agost, en r&eacute;gimen diurno y vespertino.</p>\r\n<p>Las variables del entorno general del centro son las siguientes:</p>\r\n<p>- Climatolog&iacute;a: Veranos calurosos y temperaturas moderadas en invierno, con escasas lluvias.</p>\r\n<p>- Sistema de comunicaciones: El centro est&aacute; bien comunicado, tanto de forma interna (transporte p&uacute;blico) como externa (carreteras de todo tipo). Adem&aacute;s, est&aacute; pr&oacute;ximo a la salida del mismo. Este factor facilita las posibilidades de desplazamiento para actividades extraescolares y complementarias.</p>\r\n<p>- Nivel de renta familiar: La gran mayor&iacute;a del alumnado que acude al centro pertenece a familias de un nivel socio-econ&oacute;mico medio-alto.</p>\r\n<p>- Tejido empresarial: Predominan las peque&ntilde;as y medianas empresas del sector servicios, las cuales satisfacen las necesidades del sector industrial de la zona. Como consecuencia, existe una creciente demanda de profesionales del sector TICs.</p>\r\n<p>Respecto a las caracter&iacute;sticas concretas del centro, se trata de un instituto con amplia oferta educativa, y que cuenta con una gran cantidad de recursos humanos y tecnol&oacute;gicos.</p>\r\n<p>Se concretan a continuaci&oacute;n las variables del entorno espec&iacute;fico:</p>\r\n<ul>\r\n<li>Oferta educativa: Adem&aacute;s de ESO y Bachillerato, el instituto ofrece ciclos formativos de las siguientes familias profesionales: Administraci&oacute;n y Gesti&oacute;n, Imagen Personal, Inform&aacute;tica y Comunicaciones as&iacute; como cursos de especializaci&oacute;n de esta &uacute;ltima familia. Algunos de los ciclos ofertados presentan adem&aacute;s modalidad dual y semipresencial.</li>\r\n<li>Alumnado: Hay un total de 1800 alumnos y alumnas matriculados en el instituto y existe cierta diversidad multicultural, pero en su mayor&iacute;a son estudiantes ya nacidos en Espa&ntilde;a y conocen el idioma.</li>\r\n<li>Profesorado: Hay un total de 175 docentes en el centro, siendo el departamento de inform&aacute;tica el m&aacute;s numeroso de todos, con un total de 48 docentes.</li>\r\n<li>Instalaciones y equipamientos: El instituto cuenta con biblioteca, aula de convivencia, aulas de usos m&uacute;ltiples y aulas inform&aacute;ticas con adecuados recursos tecnol&oacute;gicos (ordenadores para alumnado y profesorado, pantallas digitales t&aacute;ctiles, proyectores&hellip;).</li>\r\n<li>Barreras arquitect&oacute;nicas: El centro carece de ellas, ya que cuenta con acceso para personas con movilidad reducida y ascensor.</li>\r\n<li>Programas educativos y de innovaci&oacute;n: Se llevan a cabo en secundaria programas de educaci&oacute;n biling&uuml;e y en ciclos formativos, algunos m&oacute;dulos se imparten en ingl&eacute;s o valenciano.</li>\r\n</ul>\r\n<p>Respecto al perfil concreto del alumnado del m&oacute;dulo de \"Bases de datos\", en adelante BBDD, al estar enmarcado en un ciclo de grado superior, suele contar con las siguientes caracter&iacute;sticas:</p>\r\n<p>1. Son mayores de edad.</p>\r\n<p>2. Muestran inter&eacute;s y motivaci&oacute;n por adquirir competencias.</p>\r\n<p>3. Cuentan con ciertos conocimientos espec&iacute;ficos, ya que vienen de superar Bachillerato, de terminar otros estudios de Formaci&oacute;n Profesional, o incluso interrumpir o finalizar una carrera universitaria.</p>\r\n<p>4. Tienen claro el camino profesional que quieren seguir.</p>\r\n<p>5. Presentan inquietudes profesionales.</p>'),
(3180, 367, 25, ''),
(3183, 367, 6, '<p>La secuenciaci&oacute;n y temporalizaci&oacute;n de las unidades did&aacute;cticas del m&oacute;dulo es la siguiente:</p>\r\n<table border=\"1\" cellpadding=\"5\">\r\n<tbody>\r\n<tr style=\"text-align: justify;\" bgcolor=\"#DDDDDD\">\r\n<td width=\"80%\">\r\n<p><strong>Unidad</strong></p>\r\n</td>\r\n<td width=\"20%\">\r\n<p><strong>Semanas</strong></p>\r\n</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td><strong>UD 1. INTRODUCCI&Oacute;N AL PROYECTO INTERMODULAR</strong></td>\r\n<td><strong>09/09 -23/09</strong></td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td><strong>UD2. COMUNICACI&Oacute;N EFECTIVA</strong></td>\r\n<td>\r\n<p><strong>30/09-28/11</strong></p>\r\n</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td><strong>UD3.DESARROLLO, PLANIFICACI&Oacute;N Y GESTI&Oacute;N DE PROYECTOS SOFTWARE</strong></td>\r\n<td>\r\n<p><strong>04/11-06/01</strong></p>\r\n</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td><strong>UD4. TRABAJO COLABORATIVO Y EN EQUIPO</strong></td>\r\n<td>\r\n<p><strong>13/01-14/03</strong></p>\r\n</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td><strong>UD5. CONTROL DE VERSIONES CON GIT EN UN PROYECTO SW</strong></td>\r\n<td>\r\n<p><strong>21/04-fin</strong></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>El <strong>primer trimestre</strong> incluir&aacute; las unidades did&aacute;cticas: UD1-UD2 y parte UD3</p>\r\n<p>El <strong>segundo trimestre</strong> incluir&aacute; las unidades did&aacute;cticas: UD3-UD4</p>\r\n<p>El <strong>tercer trimestre</strong> incluir&aacute; las unidades did&aacute;cticas: UD5</p>'),
(3184, 367, 7, '<p>Los principios metodol&oacute;gicos que se aplicar&aacute;n en el m&oacute;dulo ser&aacute;n los siguientes:</p>\r\n<p>PM1: Establecer relaciones significativas entre los nuevos conocimientos y los ya establecidos o con las experiencias previas del alumnado.</p>\r\n<p>PM2: Usar estrategias de presentaci&oacute;n organizadas y atractivas, con el objetivo de aumentar la motivaci&oacute;n del alumnado.</p>\r\n<p>PM3: Fomentar la interacci&oacute;n alumnado-profesorado y alumnado-alumnado para la confrontaci&oacute;n de puntos de vista, toma de decisiones, y la superaci&oacute;n de conflictos mediante di&aacute;logo y cooperaci&oacute;n.</p>\r\n<p>PM4: Garantizar la funcionalidad de los aprendizajes, asegurando que puedan ser utilizados en las circunstancias reales en que el estudiante los necesite.</p>\r\n<p>PM5: Ajustar la ayuda pedag&oacute;gica a las distintas necesidades del alumnado, y facilitar recursos o estrategias variadas para responder a sus motivaciones, intereses y capacidades.</p>\r\n<p>PM6: Realizar la evaluaci&oacute;n de forma continua y personalizada, respecto al estudiante en su desarrollo y aport&aacute;ndole informaci&oacute;n sobre sus progresos, sin comparar con normas est&aacute;ndar de rendimiento.</p>\r\n<p>PM7: Presentar los contenidos con una estructuraci&oacute;n clara de sus relaciones, planteando la interrelaci&oacute;n entre distintos contenidos de una materia y de distintas materias.</p>\r\n<p>En base a los principios del apartado anterior, se establecen estas estrategias de ense&ntilde;anza-aprendizaje para el presente m&oacute;dulo:</p>\r\n<ul>\r\n<li>Conocimiento de las preconcepciones del alumnado, para detectar posibles ideas err&oacute;neas y para construir los nuevos conocimientos a partir de las ideas previas.\r\n<ul>\r\n<li>T&eacute;cnicas: debates interrogativos y cuestionarios antes de exponer nuevos contenidos.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de introducci&oacute;n y motivaci&oacute;n.</li>\r\n</ul>\r\n</li>\r\n<li>Tratamiento de posibles situaciones problem&aacute;ticas, dirigiendo el docente el proceso de aprendizaje para detectar a tiempo los problemas de comprensi&oacute;n y resolverlos eficazmente.\r\n<ul>\r\n<li>T&eacute;cnicas: llevar a cabo un seguimiento especial del alumnado al tratar contenidos complejos, dando mucho feedback en la correcciones y realizando actividades junto a ellos.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de descubrimiento dirigido.</li>\r\n</ul>\r\n</li>\r\n<li>Identificaci&oacute;n de las ideas fundamentales, haci&eacute;ndose especial hincapi&eacute; en determinados contenidos y actividades y promoviendo la consolidaci&oacute;n de los contenidos prioritarios.\r\n<ul>\r\n<li>T&eacute;cnicas: exposici&oacute;n con mayor detenimiento de los contenidos prioritarios y realizaci&oacute;n de varias actividades sobre cada uno de&nbsp; ellos, para afianzar el aprendizaje.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de consolidaci&oacute;n.</li>\r\n</ul>\r\n</li>\r\n<li>Conexi&oacute;n de los contenidos con el entorno y su funcionalidad, para que el alumnado vea la utilidad de lo que aprende y conozca su aplicaci&oacute;n real en la empresa, a partir de las actividades.\r\n<ul>\r\n<li>T&eacute;cnicas: relaci&oacute;n de los contenidos explicados con los perfiles profesionales de programador web, as&iacute; como realizaci&oacute;n de&nbsp; &nbsp;actividades y ejemplos vinculados al mundo laboral.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de consolidaci&oacute;n, pr&aacute;cticas y complementarias.</li>\r\n</ul>\r\n</li>\r\n<li>Promoci&oacute;n de la autonom&iacute;a del alumnado en su propio aprendizaje, fomentando la capacidad del estudiante para buscar la informaci&oacute;n necesaria para desempe&ntilde;ar su trabajo, as&iacute; como su capacidad de adaptaci&oacute;n a situaciones diferentes que podr&iacute;an darse en el entorno laboral.\r\n<ul>\r\n<li>T&eacute;cnicas: proveer al alumnado de direcciones web fiables y pautas para buscar informaci&oacute;n de cara a realizar las actividades&nbsp; &nbsp;propuestas. Adem&aacute;s, en las actividades de investigaci&oacute;n, dejar un margen amplio para el desarrollo de sus propios criterios y creatividad.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de investigaci&oacute;n y proyectos.</li>\r\n</ul>\r\n</li>\r\n<li>Potenciaci&oacute;n de la participaci&oacute;n del alumnado para fomentar su capacidad para hablar en p&uacute;blico y su expresi&oacute;n oral. Tambi&eacute;n se favorece el respeto hacia las opiniones de los dem&aacute;s.\r\n<ul>\r\n<li>T&eacute;cnicas: m&eacute;todo interrogativo durante las explicaciones, exposici&oacute;n de actividades realizadas por los estudiantes y debates sobre&nbsp; los contenidos del m&oacute;dulo relacionados con temas de actualidad.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de introducci&oacute;n/motivaci&oacute;n y comunicaci&oacute;n de resultados.</li>\r\n</ul>\r\n</li>\r\n<li>Alta relevancia del apoyo visual en las explicaciones, para facilitar la asimilaci&oacute;n de ciertos contenidos y simplificar la interiorizaci&oacute;n de aquellos que se usar&aacute;n con asiduidad durante el curso.\r\n<ul>\r\n<li>T&eacute;cnicas: utilizar materiales con un alto nivel de ilustraci&oacute;n como infograf&iacute;as y v&iacute;deos e incluir algunos mapas conceptuales.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: se aplicar&aacute; en todo tipo de actividades.</li>\r\n</ul>\r\n</li>\r\n<li>Impulso del trabajo en grupo, apostando en ciertas unidades por el desarrollo de tareas de forma colectiva, siempre tomando las medidas preventivas para asegurar la participaci&oacute;n de todos los integrantes del equipo y para llevar a cabo una evaluaci&oacute;n y un seguimiento justo del proceso.\r\n<ul>\r\n<li>T&eacute;cnicas: alternar tareas individuales con grupales, y tambi&eacute;n tareas breves con otras m&aacute;s largas.</li>\r\n<li>Actividades de ense&ntilde;anza-aprendizaje: de introducci&oacute;n/motivaci&oacute;n, de investigaci&oacute;n y proyectos.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p>Como resultado de todo ello, se contar&aacute;n con los siguientes tipos de actividades :</p>\r\n<p>1. De introducci&oacute;n-motivaci&oacute;n. Se realizar&aacute;n en la primera sesi&oacute;n de trabajo de algunas de las unidades did&aacute;cticas. Se dirigir&aacute;n a promover la curiosidad del estudiante intentando despertar su inter&eacute;s.</p>\r\n<p>2. De desarrollo o actividades productivas. Las cuales adem&aacute;s podr&aacute;n ser de descubrimiento dirigido, investigaci&oacute;n o exposici&oacute;n oral.</p>\r\n<p>3. Actividades de consolidaci&oacute;n. Ser&aacute;n actividades nuevas, pero en ellas se repetir&aacute;n algunos contenidos que ya hab&iacute;an sido trabajados anteriormente, con el objetivo de afianzar lo aprendido y reforzar aquellos contenidos que se consideran m&aacute;s importantes.</p>\r\n<p>4. Proyectos. Estas actividades tendr&aacute;n una extensi&oacute;n m&aacute;s larga que el resto, y podr&aacute;n ser tanto de car&aacute;cter individual como de car&aacute;cter grupal.</p>\r\n<p>5. De refuerzo. Ir&aacute;n dirigidas a estudiantes que tienen dificultades para alcanzar los objetivos previstos para una unidad did&aacute;ctica, a fin de que estos puedan alcanzar los mismos.</p>\r\n<p>6. De ampliaci&oacute;n. Ir&aacute;n dirigidas a estudiantes que alcancen los objetivos previstos antes de lo esperado, y que puedan alcanzar niveles de conocimiento superiores al exigido. Por lo general ser&aacute;n apartados extra &ndash;de car&aacute;cter voluntario&ndash; que se a&ntilde;adir&aacute;n a las actividades obligatorias.</p>\r\n<p>7. De evaluaci&oacute;n. Tienen como finalidad determinar el nivel de consecuci&oacute;n de&nbsp;capacidades adquiridas por el estudiante.</p>\r\n<p>8. De recuperaci&oacute;n. Son actividades destinadas a aquellos estudiantes que, una vez ha terminado el proceso de evaluaci&oacute;n, han obtenido calificaciones negativas.</p>'),
(3186, 367, 23, '<p>Los instrumentos de evaluaci&oacute;n empleados tanto en el plano conceptual, como procedimental como actitudinal, ser&aacute;n los siguientes:</p>\r\n<table border=\"1\" cellpadding=\"5\">\r\n<tbody>\r\n<tr style=\"text-align: justify;\" bgcolor=\"#DDDDDD\">\r\n<td width=\"20%\">\r\n<p><strong>Tipo de instrumento</strong></p>\r\n</td>\r\n<td width=\"20%\">\r\n<p><strong>Intrumento</strong></p>\r\n</td>\r\n<td width=\"60%\">\r\n<p><strong>Descripci&oacute;n</strong></p>\r\n</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td>Conceptuales y procedimentales</td>\r\n<td><strong>I1</strong></td>\r\n<td>Pruebas objetivas globales: Aquellas que vienen referidas a los contenidos de una o unidades did&aacute;cticas, como ser&aacute;n los cuestionarios, tests o examenes.</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td>Conceptuales y procedimentales</td>\r\n<td><strong>I2</strong></td>\r\n<td>Trabajos individuales: Supuestos pr&aacute;cticos, ejercicios y actividades del estudiante de forma unitaria.</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td>Conceptuales y procedimentales</td>\r\n<td><strong>I3</strong></td>\r\n<td>Tareas grupales y proyectos: Aquellos que el alumno lleva a cabo junto a otros/as compa&ntilde;eros/as, como es el caso de actividades pr&aacute;cticas y proyectos.</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td>Actitudinales</td>\r\n<td><strong>I4</strong></td>\r\n<td>Participaci&oacute;n en debates, foros y predisposici&oacute;n a intervenir en el proceso de aprendizaje, valorada mediante r&uacute;brica: Se refiere a la actividad y al inter&eacute;s mostrado en dichas tareas comunicativas, adem&aacute;s de la participaci&oacute;n y la atenci&oacute;n en las sesiones.</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td>Actitudinales</td>\r\n<td><strong>I5</strong></td>\r\n<td>Participaci&oacute;n activa en grupos de trabajo, valorada mediante r&uacute;brica: Vinculado al esfuerzo, la cooperaci&oacute;n y el desempe&ntilde;o en las tareas grupales y de proyecto</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td>Actitudinales</td>\r\n<td><strong>I6</strong></td>\r\n<td>Orden y limpieza en la presentaci&oacute;n de tareas, valorada mediante r&uacute;brica: En las tareas redactadas, en las orales y tambi&eacute;n en las resueltas con c&oacute;digo.</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<td>Actitudinales</td>\r\n<td><strong>I7</strong></td>\r\n<td>Informe de cumplimiento en los plazos de entrega: Un instrumento muy importante vinculado a la puntualidad y a la seriedad en el trabajo.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>'),
(3187, 367, 9, '<p>En el apartado \"Resultados de aprendizaje\", detallado previamente, se relacionan los resultados de aprendizaje con sus correspondientes criterios de evaluci&oacute;n.</p>'),
(3188, 367, 10, '<p>La calificaci&oacute;n final del m&oacute;dulo se calcular&aacute; seg&uacute;n la media ponderada siguiente:</p>\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Nota m&oacute;dulo= SP * 0,8 + ETT* 0,2</p>\r\n<p>Siendo ,\"SP\" los supuestos pr&aacute;cticos (actividades, ejercicios, proyecto y otros artefactos de car&aacute;cter pr&aacute;ctico) y \"ETT\", la actitud, asistencia, participaci&oacute;n, trabajo en clase y resto de elementos transversales planteados.</p>\r\n<p>Adem&aacute;s, deber&aacute;n tenerse en cuenta los siguientes aspectos:</p>\r\n<p>1. Ser&aacute; necesario obtener una calificaci&oacute;n m&iacute;nima de 5 sobre 10 en los coeficientes de supuestos pr&aacute;cticos \"SP\" para poder superar el m&oacute;dulo, adem&aacute;s de sumar, como m&iacute;nimo un 5, sobre 10, el c&aacute;lculo de la media ponderada total.</p>\r\n<p>2. Todos los supuestos pr&aacute;cticos planteados deber&aacute;n superarse con una nota m&iacute;nima cuantitativa de 5 o cualitativa de \"Superado\" para poder superar el m&oacute;dulo, pudiendo el&nbsp;docente decidir que haya actividades que requieran de una nota m&iacute;nima de 6 para ser superados, debido a su peso dentro de los contenidos del m&oacute;dulo.</p>\r\n<p>3. Los supuestos pr&aacute;cticos podr&aacute;n ser defendidos y argumentados por el estudiante de forma oral o escrita, en caso de que el docente as&iacute; lo considere.</p>\r\n<p>4. El docente podr&aacute; proponer supuestos pr&aacute;cticos o pruebas evaluativas que ser&aacute;n de obligatoria realizaci&oacute;n, entrega y superaci&oacute;n sin que cuenten con una nota cuantitativa, se tratar&aacute; de actividades o pruebas que se evaluar&aacute;n como Superado/No superado.</p>\r\n<p>5. Todas las pruebas y actividades planteadas en el m&oacute;dulo tendr&aacute;n asignada una fecha de entrega m&aacute;xima, si el estudiante realiza la entrega entre 1 y 5 d&iacute;as depu&eacute;s de tal fecha sin justificaci&oacute;n pertinente, solo podr&aacute; obtener una puntuaci&oacute;n m&aacute;xima de 5. Si la realizaci&oacute;n de la entrega se realiza pasados 5 d&iacute;as de su fecha de finalizaci&oacute;n sin justificaci&oacute;n, la prueba o actividad ser&aacute; calificada con un cero.</p>\r\n<p>6. Se podr&aacute;n realizar&aacute;n recuperaciones de los supuestos pr&aacute;cticos, en los casos en los que el docente as&iacute; lo considere y sin que por ello el alumnado pierda la evaluaci&oacute;n cont&iacute;nua. La puntuaci&oacute;n m&aacute;xima en tales recuperaciones ser&aacute; de un 6.</p>\r\n<p>7. Las faltas de asistencia del estudiante (en grupos presenciales) no deber&aacute;n superar el 15% del total de sesiones del curso, en caso contrario, el estudiante perder&aacute; la evaluaci&oacute;n continua y deber&aacute; ir a un examen final que recoger&aacute; todos los contenidos de las unidades did&aacute;cticas del m&oacute;dulo, adem&aacute;s de entregar los ejercicios y proyectos planteados para cada una.</p>\r\n<p>8. Las actitudes inc&iacute;vicas se regular&aacute;n tal como sigue: 1&ordf; vez &gt; advertencia, 2&ordf; vez &gt; resta un punto a la nota del trimestre, 3&ordf; vez &gt; suspenso del trimestre y aviso a jefatura estudios.</p>'),
(3189, 367, 22, '<p>Dentro del Plan de mejora del centro, la Comisi&oacute;n de Coordinaci&oacute;n Pedag&oacute;gica en reuni&oacute;n celebrada el 5 de septiembre de 2019, ha aprobado unos criterios de correcci&oacute;n ortogr&aacute;fica que deben ser aplicados en todas las &aacute;reas, materias y cursos. Tiene, por tanto, car&aacute;cter prescriptivo y son de obligado cumplimiento para todo el profesorado.</p>\r\n<p>Ciclos Formativos de Grado Superior: Penalizaci&oacute;n de 0,25 puntos por error gr&aacute;fico (0,15 por tilde), hasta un m&aacute;ximo de 2,5 puntos.</p>'),
(3190, 367, 11, '<p>A lo largo de las diferentes unidades did&aacute;cticas, se realizar&aacute;n&nbsp; actividades de refuerzo y ampliaci&oacute;n.</p>\r\n<p>Para aquellos estudiantes que presenten problemas para poder desarrollar alguna parte del proyecto o las actividades, se propondr&aacute;n ejercicios que permitan reforzar los contenidos vistos en clase.</p>\r\n<p>Por otra parte, aquellos alumnos avanzados que alcancen facilmente los objetivos perseguidos en cada una de las unidades, tendr&aacute;n la posibilidad de proponer ampliaciones del proyecto o al profesor para ampliar conocimientos, as&iacute; como llevar a cabo actividades de ampliaci&oacute;n propuestas por el docente.</p>'),
(3192, 367, 13, '<p>La recuperaci&oacute;n del m&oacute;dulo se realizar&aacute; mediante los supuestos pr&aacute;cticos planteados que recoger&aacute; los contenidos de todas las unidades did&aacute;cticas del m&oacute;dulo, los cuales podr&aacute;n ser defendidos y justificados con una prueba objetiva escrita u oral cuando el docente as&iacute; lo considere.</p>\r\n<p>La nota de recuperaci&oacute;n del m&oacute;dulo se calcular&aacute; a partir de la siguiente f&oacute;rmula:</p>\r\n<p>Nota de recuperaci&oacute;n del m&oacute;dulo= SP * 1;</p>\r\n<p>Siendo \"SP\" los supuestos pr&aacute;cticos (actividades, ejercicios y proyecto).</p>\r\n<p>Para recuperar el m&oacute;dulo, deber&aacute;n cumplirse los siguientes requisitos en la f&oacute;rmula anterior:&nbsp; &nbsp; &nbsp; &nbsp;</p>\r\n<ul>\r\n<li>La nota de cada una de las partes deber&aacute; ser igual o superior a 5.</li>\r\n<li>La suma media ponderada total debe ser igual o superior a 5.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</li>\r\n<li>La nota de los supuestos pr&aacute;cticos individuales as&iacute; como las pruebas de evaluaci&oacute;n individuales deber&aacute; ser igual o superior a 5.</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">La prueba objetiva a realizar consistir&aacute; en un examen final o exposici&oacute;n de proyecto, que coincidir&aacute; con la convocatoria ordinaria.</p>\r\n<p style=\"text-align: justify;\">Si al finalizar la convocatoria ordinaria de junio, el alumno no consigue superar los objetivos m&iacute;nimos del m&oacute;dulo, el equipo educativo decidir&aacute; si repite el m&oacute;dulo de forma presencial el curso siguiente o si acceder&aacute; a la convocatoria extraordinaria de junio, seg&uacute;n especifica el D.O.G.V. 3.531 Resoluci&oacute;n del 24 de junio de 1999.</p>\r\n<p style=\"text-align: justify;\"><br />En la prueba extraordinaria de junio, el alumno deber&aacute; realizar una prueba de conocimientos te&oacute;rico/pr&aacute;cticos de todos los contenidos del curso.&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>'),
(3193, 367, 14, '<p><strong>Recuperaci&oacute;n para alumnado de segundo curso</strong></p>\r\n<p>El alumnado que se encuentre en esta situaci&oacute;n y no pueda asistir a clase presencial, por coincidir el horario lectivo de este m&oacute;dulo con otros que se cursen de segundo curso, deber&aacute; realizar y superar con un m&iacute;nimo de 5 todos los supuestos pr&aacute;cticos que se planteen por cada unidad did&aacute;ctica en el m&oacute;dulo y que se publicar&aacute;n en el aula virtual del centro, adem&aacute;s de realizar las pruebas evaluatorias o propuestas por el docente, los cuales tambi&eacute;n necesitar&aacute;n de una nota m&iacute;nima de 5 para su superaci&oacute;n.</p>\r\n<p>Para ello, deber&aacute; inscribirse en el correspondiente curso y hacer llegar las actividades realizadas para su correcci&oacute;n y puntuaci&oacute;n a trav&eacute;s de AULES.</p>\r\n<p>Para superar el m&oacute;dulo el estudiante deber&aacute; aprobar con un m&iacute;nimo de 5 todas las activides y proyecto propuestos, siendo la nota final obtenida el resultado de la f&oacute;rmula SP (supuestos pr&aacute;cticos)*1&nbsp; tal cual se indica en detalle en el apartado 7.Criterios de recuperaci&oacute;n del presente documento.</p>'),
(3194, 367, 15, '<p>Para atender las diversas necesidades educativas del aula, se contemplar&aacute;n las siguientes medidas:</p>\r\n<p>1. Desarrollo de cuestionarios de diagn&oacute;stico previo, los cuales permitir&aacute;n detectar el nivel de conocimientos y motivaci&oacute;n del alumnado, de forma que el docente pueda valorar el punto de partida y las estrategias a seguir.</p>\r\n<p>2. Flexibilizaci&oacute;n de los tiempos de entrega de las diferentes tareas.</p>\r\n<p>3. Propuesta de actividades con diferente grado de dificultad, como es el caso de las actividades de ampliaci&oacute;n o refuerzo, atendiendo a las capacidades e inter&eacute;s de los estudiantes.</p>\r\n<p>4. Selecci&oacute;n de perfiles \"analista\" y \"gestor\", en los ejercicios de trabajo en grupo, entre aquellos estudiantes que muestren mayor destreza, de forma que sean ellos mismos quienes apoyen al resto de miembros de su equipo de trabajo</p>\r\n<p>Y en general, todos aquellos cambios en la metodolog&iacute;a que el docente identifique como precisos, consultando con el departamento de orientaci&oacute;n y jefatura de estudios cuando se requiera.</p>'),
(3195, 367, 17, '<p>Los materiales f&iacute;sicos empleados en el m&oacute;dulo consistir&aacute;n principalmente en un aula de inform&aacute;tica con pizarra, conexi&oacute;n a Internet, proyector o PDI y equipos inform&aacute;ticos conectados en red, tanto para el profesorado como para el alumnado.</p>\r\n<p>A nivel software se utilizar&aacute; la plataforma AULES como repositorio de materiales y entregas.</p>'),
(3196, 367, 18, '<p>Los materiales consultados para la confecci&oacute;n del presente documento y el m&oacute;dulo en s&iacute; son los siguientes:</p>\r\n<ul>\r\n<li>Pressman, R. S., &amp; Maxim, B. R. (2020). Software Engineering: A Practitioner\'s Approach (9th Edition). McGraw-Hill Education.</li>\r\n<li>Rubin, K. S. (2012). Essential Scrum: A Practical Guide to the Most Popular Agile Process. Addison-Wesley Professional. Freeman, A., &amp; Robson, K. (2018). Head First Git. O\'Reilly Media.</li>\r\n<li>Farrell, J. (2021). Microsoft Teams For Dummies. Wiley. Una gu&iacute;a accesible sobre el uso de Microsoft Teams, herramienta clave para la colaboraci&oacute;n y comunicaci&oacute;n en equipos de desarrollo de software, cubriendo las competencias del RA4.</li>\r\n</ul>'),
(3198, 8, 41, '<p>El m&oacute;dulo de Implantaci&oacute;n de Sistemas Operativos contribuye a la competencia general del ciclo formativo de Administraci&oacute;n de Sistemas Inform&aacute;ticos y Redes \"<em>Configurar, administrar y mantener sistemas inform&aacute;ticos, garantizando la funcionalidad, la integridad de los recursos y servicios del sistema, con la calidad exigida y cumpliendo la reglamentaci&oacute;n vigente\".</em></p>'),
(3199, 55, 40, ''),
(3200, 404, 35, '<p>El telef&oacute;no del centro es <span data-dtype=\"d3ph\" data-local-attribute=\"d3ph\">965 93 65 05</span></p>\r\n<div class=\"QiO29e\">&nbsp;</div>'),
(3201, 107, 41, '<p></p>\r\n<p>Desde este m&oacute;dulo profesional se contribuye a las siguientes competencias profesionales, personales y sociales:</p>\r\n<p>1 - Acoplar los materiales para acometer el montaje y/o mantenimiento en sistemas microinform&aacute;ticos y redes de transmisi&oacute;n de datos.<br />2 - Realizar operaciones auxiliares de montaje de sistemas microinform&aacute;ticos y dispositivos auxiliares en condiciones de calidad.<br />3 - Realizar operaciones auxiliares de mantenimiento y reparaci&oacute;n de sistemas microinform&aacute;ticos garantizando su funcionamiento.<br />4 - Realizar las operaciones para el almacenamiento y transporte de sistemas, perif&eacute;ricos y consumibles, siguiendo criterios de seguridad y catalogaci&oacute;n.<br />5 - Realizar comprobaciones rutinarias de verificaci&oacute;n en el montaje y mantenimiento de sistemas y/o instalaciones.<br />6 - Montar canalizaciones para cableado de datos en condiciones de calidad y seguridad.<br />7 - Tender el cableado de redes de datos aplicando las t&eacute;cnicas y procedimientos normalizados.<br />8 - Manejar las herramientas del entorno usuario proporcionadas por el sistema operativo y los dispositivos de almacenamiento de informaci&oacute;n.<br />9 - Manejar aplicaciones ofim&aacute;ticas de procesador de textos para realizar documentos sencillos. &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 10 - &nbsp;Adaptarse a las nuevas situaciones laborales originadas por cambios tecnol&oacute;gicos y organizativos en su actividad laboral, utilizando las ofertas formativas a su alcance y localizando los recursos mediante las tecnolog&iacute;as de la informaci&oacute;n y la comunicaci&oacute;n.<br />11 - Cumplir las tareas propias de su nivel con autonom&iacute;a y responsabilidad, empleando criterios de calidad y eficiencia en el trabajo asignado y efectu&aacute;ndolo de forma individual o como miembro de un equipo.<br />12 - Comunicarse eficazmente, respetando la autonom&iacute;a y competencia de las distintas personas que intervienen en su &aacute;mbito de trabajo, contribuyendo a la calidad del trabajo realizado.<br />13 - Asumir y cumplir las medidas de prevenci&oacute;n de riesgos y seguridad laboral en la realizaci&oacute;n de las actividades laborales evitando da&ntilde;os personales, laborales y ambientales.<br />14 - Cumplir las normas de calidad, de accesibilidad universal y dise&ntilde;o</p>'),
(3202, 107, 23, '<p>&nbsp;</p>\r\n<div class=\"page\" title=\"Page 11\">\r\n<div class=\"layoutArea\">\r\n<div class=\"column\">\r\n<p>La evaluaci&oacute;n educativa se entiende como una actividad sistem&aacute;tica y continuada, integrada en el proceso educativo, cuya finalidad consiste en obtener la m&aacute;xima informaci&aacute;n sobre el alumno, el proceso educativo y todos los factores que en &aacute;l intervienen, para tomar decisiones con el fin de orientar y ayudar al alumno y mejorar el proceso educativo, reajustando objetivos, pensando programas, m&eacute;todos y recursos.</p>\r\n<p>El seguimiento del proceso de ensen&ntilde;anza-aprendizaje se lleva a cabo a trav&eacute;s de la evaluaci&oacute;n. &Eacute;sta ha de cumplir las siguientes caracter&iacute;sticas:</p>\r\n<p>Continua a lo largo de todo el proceso de aprendizaje. Se tendr&aacute; en cuenta la evaluaci&oacute;n inicial, la evaluaci&oacute;n formativa y la evaluación sumativa.</p>\r\n<p>Integradora: no s&oacute;lo se han de evaluar los contenidos, sino tambi&eacute;n el resto de componentes que forman parte de la formaci&oacute;n del alumnado, como actitudes, destrezas, comportamientos, capacidad de investigaci&oacute;n y de iniciativa, etc.</p>\r\n<p>Individualizadora: ha de ajustarse a las caracter&iacute;sticas personales de cada alumno/a.</p>\r\n<p>Orientadora: debe informar al alumnado del grado de evoluci&oacute;n conseguido respecto a los objetivos del m&oacute;dulo y la mejor forma de alcanzarlos.</p>\r\n<p>Dado que el enfoque de la metodolog&iacute;a did&aacute;ctica a emplear en este m&oacute;dulo es fundamentalmente procedimental, la evaluaci&oacute;n dar&aacute; mucha importancia a la realización de pr&aacute;cticas en el aula de inform&aacute;tica y a la presentaci&oacute;n de trabajos y ejercicios resueltos por parte de los alumnos. No obstante tambi&eacute;n se realizar&aacute;n una serie de pruebas escritas al t&eacute;rmino de cada uno de los bloques tem&aacute;ticos, cuyo objetivo es comprobar el grado de asimilaci&oacute;n de los contenidos conceptuales.</p>\r\n</div>\r\n</div>\r\n</div>'),
(3204, 14, 35, ''),
(3206, 404, 34, '<p>paulacaceres@iessanvicente.com</p>'),
(3208, 365, 6, '<table style=\"border: 1px solid black;\">\r\n<thead>\r\n<tr>\r\n<th style=\"text-align: center;\">Evaluaci&oacute;n</th>\r\n<th>Unidad de trabajo</th>\r\n</tr>\r\n<tr style=\"border: 1px solid black;\">\r\n<td style=\"text-align: center;\">1</td>\r\n<td>UT01. Teor&iacute;a de proyectos.</td>\r\n</tr>\r\n<tr>\r\n<td class=\"tg-baqh\" style=\"text-align: center;\">1</td>\r\n<td class=\"tg-0lax\">UT02. Herramientas de trabajo colaborativo. Trello y Jira.</td>\r\n</tr>\r\n<tr>\r\n<td class=\"tg-baqh\" style=\"text-align: center;\">1</td>\r\n<td class=\"tg-0lax\">UT02. Herramientas de trabajo colaborativo. Control de versiones.</td>\r\n</tr>\r\n<tr>\r\n<td class=\"tg-baqh\" style=\"text-align: center;\">2</td>\r\n<td class=\"tg-0lax\">UT02. Herramientas de trabajo colaborativo. Comunicaci&oacute;n en equipo.</td>\r\n</tr>\r\n<tr>\r\n<td class=\"tg-baqh\" style=\"text-align: center;\">2</td>\r\n<td class=\"tg-0lax\">UT02. Herramientas de trabajo colaborativo. Documentos colaborativos.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\">2</td>\r\n<td>UT03. Documentaci&oacute;n y reportes</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\">2</td>\r\n<td>UT04. Presentaciones</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\">3</td>\r\n<td>UT05. Elaboraci&oacute;n de un peque&ntilde;o proyecto desde 0.</td>\r\n</tr>\r\n</thead>\r\n</table>'),
(3210, 365, 25, ''),
(3212, 365, 7, '<p>El m&eacute;todo que se seguir&aacute; para el desarrollo de las clases ser&aacute; el siguiente:</p>\r\n<ol>\r\n<li>\r\n<p>Exposici&oacute;n de conceptos te&oacute;ricos en clase a partir de los materiales&nbsp;proporcionados por el profesorado y que&nbsp;estime convenientes para una mejor comprensi&oacute;n de los contenidos.</p>\r\n</li>\r\n<li>\r\n<p>Planteamiento de ejercicios y actividades en el aula de aquellos temas que lo permitan, resolvi&eacute;ndose aquellos que se estime oportuno.</p>\r\n</li>\r\n<li>\r\n<p>Presentaci&oacute;n en clase de las diversas pr&aacute;cticas a realizar y desarrollo en la misma de todas aquellas que el equipamiento permita.</p>\r\n</li>\r\n<li>\r\n<p>Realizaci&oacute;n de trabajos y exposiciones por parte del alumnado, de aquellos temas que se brinden a ello o que se propongan directamente por el profesor, con lo que se conseguir&aacute; una activa participaci&oacute;n y un mayor acercamiento a los conceptos y contenidos del modulo.</p>\r\n</li>\r\n<li>\r\n<p>En una etapa inicial del curso, se seguir&aacute; el m&eacute;todo tradicional de exposici&oacute;n por parte del profesor, con el fin de explicar los conceptos b&aacute;sicos que &eacute;ste m&oacute;dulo necesita para poder arrancar.</p>\r\n</li>\r\n</ol>'),
(3214, 365, 23, ''),
(3215, 365, 9, '<p class=\"parrafo_2\"><strong>RA1. Identifica necesidades del sector productivo relacion&aacute;ndolas con proyectos tipo que las puedan satisfacer.</strong></p>\r\n<p class=\"parrafo_2\"><strong>Criterios de evaluaci&oacute;n:</strong></p>\r\n<p class=\"parrafo_2\">a) Se han clasificado las empresas del sector por sus caracter&iacute;sticas organizativas y el tipo de producto o servicio que ofrecen.</p>\r\n<p class=\"parrafo\">b) Se han caracterizado las empresas tipo indicando la estructura organizativa y las funciones de cada departamento.</p>\r\n<p class=\"parrafo\">c) Se han identificado las necesidades m&aacute;s demandadas a las empresas.</p>\r\n<p class=\"parrafo\">d) Se han valorado las oportunidades de negocio previsibles en el sector.</p>\r\n<p class=\"parrafo\">e) Se ha identificado el tipo de proyecto requerido para dar respuesta a las demandas previstas.</p>\r\n<p class=\"parrafo\">f) Se han determinado las caracter&iacute;sticas espec&iacute;ficas requeridas al proyecto.</p>\r\n<p class=\"parrafo\">g) Se han determinado las obligaciones fiscales, laborales y de prevenci&oacute;n de riesgos y sus condiciones de aplicaci&oacute;n.</p>\r\n<p class=\"parrafo\">h) Se han identificado posibles ayudas o subvenciones para la incorporaci&oacute;n de nuevas tecnolog&iacute;as de producci&oacute;n o de servicio que se proponen.</p>\r\n<p class=\"parrafo\">i) Se ha elaborado el gui&oacute;n de trabajo que se va a seguir para la elaboraci&oacute;n del proyecto.</p>\r\n<p class=\"parrafo_2\"><strong>RA2. Dise&ntilde;a proyectos relacionados con las competencias expresadas en el t&iacute;tulo, incluyendo y desarrollando las fases que lo componen.</strong></p>\r\n<p class=\"parrafo_2\"><strong>Criterios de evaluaci&oacute;n:</strong></p>\r\n<p class=\"parrafo_2\">a) Se ha recopilado informaci&oacute;n relativa a los aspectos que van a ser tratados en el proyecto.</p>\r\n<p class=\"parrafo\">b) Se ha realizado el estudio de viabilidad t&eacute;cnica del mismo.</p>\r\n<p class=\"parrafo\">c) Se han identificado las fases o partes que componen el proyecto y su contenido.</p>\r\n<p class=\"parrafo\">d) Se han establecido los objetivos que se pretenden conseguir identificando su alcance.</p>\r\n<p class=\"parrafo\">e) Se han previsto los recursos materiales y personales necesarios para realizar el proyecto.</p>\r\n<p class=\"parrafo\">f) Se ha realizado el presupuesto econ&oacute;mico correspondiente.</p>\r\n<p class=\"parrafo\">g) Se han identificado las necesidades de financiaci&oacute;n para la puesta en marcha del mismo.</p>\r\n<p class=\"parrafo\">h) Se ha definido y elaborado la documentaci&oacute;n necesaria para su dise&ntilde;o.</p>\r\n<p class=\"parrafo\">i) Se han identificado los aspectos que se deben controlar para garantizar la calidad del proyecto.</p>\r\n<p class=\"parrafo_2\"><strong>RA3. Planifica la puesta en funcionamiento o ejecuci&oacute;n del proyecto, determinando el plan de intervenci&oacute;n y la documentaci&oacute;n asociada.</strong></p>\r\n<p class=\"parrafo_2\"><strong>Criterios de evaluaci&oacute;n:</strong></p>\r\n<p class=\"parrafo_2\">a) Se han secuenciado las actividades, orden&aacute;ndolas en funci&oacute;n de las necesidades de implementaci&oacute;n.</p>\r\n<p class=\"parrafo\">b) Se han determinado los recursos y la log&iacute;stica necesaria para cada actividad.</p>\r\n<p class=\"parrafo\">c) Se han identificado las necesidades de permisos y autorizaciones para llevar a cabo las actividades.</p>\r\n<p class=\"parrafo\">d) Se han determinado los procedimientos de actuaci&oacute;n o ejecuci&oacute;n de las actividades.</p>\r\n<p class=\"parrafo\">e) Se han identificado los riesgos inherentes a la ejecuci&oacute;n, definiendo el plan de prevenci&oacute;n de riesgos y los medios y equipos necesarios.</p>\r\n<p class=\"parrafo\">f) Se han planificado la asignaci&oacute;n de recursos materiales y humanos y los tiempos de ejecuci&oacute;n.</p>\r\n<p class=\"parrafo\">g) Se ha hecho la valoraci&oacute;n econ&oacute;mica que da respuesta a las condiciones de la ejecuci&oacute;n.</p>\r\n<p class=\"parrafo\">h) Se ha definido y elaborado la documentaci&oacute;n necesaria para la ejecuci&oacute;n.</p>\r\n<p class=\"parrafo_2\"><strong>RA4. Define los procedimientos para el seguimiento y control en la ejecuci&oacute;n del proyecto, justificando la selecci&oacute;n de variables e instrumentos empleados.</strong></p>\r\n<p class=\"parrafo_2\"><strong>Criterios de evaluaci&oacute;n:</strong></p>\r\n<p class=\"parrafo_2\">a) Se ha definido el procedimiento de evaluaci&oacute;n de las actividades o intervenciones.</p>\r\n<p class=\"parrafo\">b) Se han definido los indicadores de calidad para realizar la evaluaci&oacute;n.</p>\r\n<p class=\"parrafo\">c) Se ha definido el procedimiento para la evaluaci&oacute;n de las incidencias que puedan presentarse durante la realizaci&oacute;n de las actividades, su posible soluci&oacute;n y registro.</p>\r\n<p class=\"parrafo\">d) Se ha definido el procedimiento para gestionar los posibles cambios en los recursos y en las actividades, incluyendo el sistema de registro de los mismos.</p>\r\n<p class=\"parrafo\">e) Se ha definido y elaborado la documentaci&oacute;n necesaria para la evaluaci&oacute;n de las actividades y del proyecto.</p>\r\n<p class=\"parrafo\">f) Se ha establecido el procedimiento para la participaci&oacute;n en la evaluaci&oacute;n de los usuarios o clientes y se han elaborado los documentos espec&iacute;ficos.</p>\r\n<p class=\"parrafo\">g) Se ha establecido un sistema para garantizar el cumplimiento del pliego de condiciones del proyecto cuando este existe.</p>'),
(3216, 365, 10, '<p><strong>Modalidad semipresencial</strong></p>\r\n<p>Durante la evaluaci&oacute;n se propondr&aacute;n ejercicios de car&aacute;cter te&oacute;rico-pr&aacute;ctico semanales para que el alumno afiance los contenidos aprendidos en cada semana. Estas actividades son obligatorias, deber&aacute;n entregarse todas, y cada una debe tener al menos una puntuaci&oacute;n de 5. Las actividades no entregadas, entregadas fuera de plazo o copiadas, tendr&aacute;n una calificaci&oacute;n de 0.</p>\r\n<p>En la &uacute;ltima evaluaci&oacute;n se propondr&aacute; la realizaci&oacute;n de un peque&ntilde;o proyecto en la que se intentar&aacute; aunar contenidos impartidos en el resto de m&oacute;dulos. Dada la casu&iacute;stica de los ciclos semipresenciales en los que es posible que los alumnos no est&eacute;n matriculados en algunas de las asignaturas, se intentar&aacute; ajustar cada proyecto a la situaci&oacute;n de cada alumno.</p>\r\n<p>Dado que en este m&oacute;dulo no se realizar&aacute;n ex&aacute;menes por evaluaci&oacute;n, la nota final de cada evaluaci&oacute;n vendr&aacute; dada por la media de todos los ejercicios propuestos as&iacute; como la nota obtenida en el proyecto.</p>\r\n<p>La media de los ejercicicios supondr&aacute; un 60% de la nota final, y el proyecto un 40% de la nota.</p>\r\n<p>Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>'),
(3217, 365, 13, '<p>La recuperaci&oacute;n del m&oacute;dulo se realizar&aacute; mediante la entrega de una serie de supuestos pr&aacute;cticos que recogen los contenidos de todas las unidades did&aacute;cticas del m&oacute;dulo y/o una prueba objetiva que&nbsp;consistir&aacute; en un examen final sobre los contenidos o exposici&oacute;n de proyecto, que coincidir&aacute; con la convocatoria ordinaria.</p>\r\n<p>Para superar el m&oacute;dulo todos los supuestos pr&aacute;cticos y la prueba objetiva deben tener una calificaci&oacute;n igual o superior a 5. La nota final se calcular&aacute; mediante la media aritm&eacute;tica de los supuestos pr&aacute;cticas y la prueba objetiva en el caso de que se realice.</p>\r\n<p>El profesor podr&aacute; requerir la defensa y justificaci&oacute;n de los supuestos pr&aacute;cticos entregados.</p>\r\n<p>Si al finalizar la convocatoria ordinaria de junio, el alumno no consigue superar los objetivos m&iacute;nimos del m&oacute;dulo, el equipo educativo decidir&aacute; si repite el m&oacute;dulo de forma presencial el curso siguiente o si acceder&aacute; a la convocatoria extraordinaria de junio, seg&uacute;n especifica el D.O.G.V. 3.531 Resoluci&oacute;n del 24 de junio de 1999.</p>\r\n<p>En la prueba extraordinaria de julio, el alumno deber&aacute; realizar una prueba de conocimientos te&oacute;rico/pr&aacute;cticos de todos los contenidos del curso.</p>'),
(3218, 365, 14, '<p><strong>Recuperaci&oacute;n para alumnado de segundo curso</strong></p>\r\n<p>El alumnado que se encuentre en esta situaci&oacute;n y no pueda asistir a clase presencial, por coincidir el horario lectivo de este m&oacute;dulo con otros que se cursen de segundo curso, deber&aacute; realizar y superar con un m&iacute;nimo de 5 todos los supuestos pr&aacute;cticos que se planteen por cada unidad did&aacute;ctica en el m&oacute;dulo y que se publicar&aacute;n en el aula virtual del centro, adem&aacute;s de realizar las pruebas evaluatorias o propuestas por el docente, los cuales tambi&eacute;n necesitar&aacute;n de una nota m&iacute;nima de 5 para su superaci&oacute;n.</p>\r\n<p>Para ello, deber&aacute; inscribirse en el correspondiente curso y hacer llegar las actividades realizadas para su correcci&oacute;n y puntuaci&oacute;n a trav&eacute;s de AULES.</p>\r\n<p>Para superar el m&oacute;dulo el estudiante deber&aacute; aprobar con un m&iacute;nimo de 5 todas las activides y proyectos/ex&aacute;menes propuestos, calcul&aacute;ndose la nota final tal y como se indica en detalle en el apartado \"7.Criterios de recuperaci&oacute;n\" del presente documento.</p>'),
(3219, 397, 34, ''),
(3220, 397, 35, ''),
(3221, 397, 23, '');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3222, 402, 40, '<table width=\"649\" cellspacing=\"0\" cellpadding=\"7\">\r\n<tbody>\r\n<tr>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #7ba0cd; border-right: 1px solid #ffffff; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"110\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Resultados de aprendizaje</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #ffffff; border-right: 1px solid #ffffff; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"386\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Criterios de evaluaci&oacute;n</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #ffffff; border-right: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"108\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Unidades <br /> de trabajo</strong></span></span></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>1.</strong></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong> Distingue las caracter&iacute;sticas del sector productivo y define los puestos de trabajo relacion&aacute;ndolos con las competencias profesionales expresadas en el t&iacute;tulo</strong></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">.</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">__%</span></span></span></span></span></p>\r\n<p><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>DUALIZA 100%</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">a</span></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">) Se han analizado las principales oportunidades de empleo y de inserci&oacute;n laboral en el sector profesional, identificando las posibilidades de empleo y analizado sus requerimientos actuales para el perfil profesional. __%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">b) Se ha comparado los diferentes requerimientos exigidos por el mercado laboral con las exigencias para el trabajo en la funci&oacute;n p&uacute;blica relacionados con el sector privado. __%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">c) Se ha reflexionado sobre las actitudes y aptitudes requeridas actualmente para la actividad profesional relacionadas con el t&iacute;tulo, as&iacute; como las competencias personales y sociales m&aacute;s relevantes para el sector identificando nuestra zona de desarrollo pr&oacute;ximo. __%</span></span></span></span></span></p>\r\n<p><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>TODOS DUALIZAN </strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"108\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>Unidad 1</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">. An&aacute;lisis del sector profesional</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>2. Alcanza las competencias necesarias para la obtenci&oacute;n del t&iacute;tulo de T&eacute;cnico B&aacute;sico en Prevenci&oacute;n de Riesgos Laborales</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">.</span></span></span></span></span></p>\r\n<p><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">30</span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong> %</strong></span></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">a) Se ha valorado la importancia de la cultura preventiva en todos los &aacute;mbitos actividades de la empresa u organismo equiparado relacionado las condiciones laborales con la salud de la persona trabajadora identificando y clasificando los factores de riesgo en la actividad y los da&ntilde;os derivados de los mismos, especialmente las situaciones de riesgo m&aacute;s habituales en los entornos de trabajo del sector profesional relacionado con el t&iacute;tulo. _4_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">b) Se han clasificado y descrito los tipos de da&ntilde;os profesionales, con especial referencia a accidentes de trabajo y enfermedades profesionales, relacionados con el perfil profesional del t&iacute;tulo. 4%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">c) Se ha determinado la evaluaci&oacute;n de riesgos en la empresa u organismo equiparado y definido las t&eacute;cnicas de prevenci&oacute;n y de protecci&oacute;n que deben aplicarse para evitar los da&ntilde;os en su origen y minimizar sus consecuencias. _3_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">d) Se han analizado los protocolos de actuaci&oacute;n en caso de emergencia. 3__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">e) Se han determinado los principales derechos y deberes en materia de prevenci&oacute;n de riesgos laborales. 4__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">f) Se han clasificado las distintas formas de gesti&oacute;n de la prevenci&oacute;n en la empresa u organismo equiparado, en funci&oacute;n de los distintos criterios establecidos en la normativa sobre prevenci&oacute;n de riesgos laborales y determinado las formas de representaci&oacute;n de las personas trabajadoras en la empresa u organismo equiparado en materia de prevenci&oacute;n de riesgos.</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">3__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">g) Se ha valorado la importancia de la existencia de un plan preventivo en la empresa u organismo equiparado que incluya la secuenciaci&oacute;n de actuaciones a realizar en caso de emergencia y reflexionado sobre el contenido del mismo. _3_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">h) Se han determinado los requisitos y condiciones para la vigilancia de la salud de la persona trabajadora y su importancia como medida de prevenci&oacute;n. 3__%</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\">i) Se han identificado las t&eacute;cnicas b&aacute;sicas de primeros auxilios que han de ser aplicadas en el lugar del accidente ante distintos tipos de da&ntilde;os y la composici&oacute;n y uso del botiqu&iacute;n. 3__%</span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"108\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>Unidad 2.</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\"> Seguridad y salud en el trabajo</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>Unidad 3.</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\"> Prevenci&oacute;n de riesgos laborales</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>Unidad 4.</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\"> La organizaci&oacute;n y gesti&oacute;n de la prevenci&oacute;n.</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>Unidad 5</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">. La actuaci&oacute;n en caso de emergencia.</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><em><strong>Proyecto 1.</strong></em></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><em><span style=\"font-weight: normal;\"> &iexcl;Vive tu primera experiencia en prevenci&oacute;n de riesgos laborales!</span></em></span></span></span></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>3. Analiza sus condiciones laborales como persona trabajadora por cuenta ajena identific&aacute;ndolas en los principales tipos de cambios y vicisitudes relevantes que se pueden presentar en la relaci&oacute;n laboral en la normativa laboral y especialmente en el convenio colectivo del sector. </strong></span></span></span></span></span></p>\r\n<p style=\"font-style: normal;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>_40_%</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">a) Se han analizado los derechos y obligaciones derivados de la relaci&oacute;n laboral, as&iacute; como las condiciones de trabajo pactadas en un convenio colectivo aplicable al sector profesional relacionado con el t&iacute;tulo. _9_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">b) Se han comparado las principales modalidades de contrataci&oacute;n, localizando los diferentes modelos en las fuentes oficiales. _6_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">c) Se han identificado las caracter&iacute;sticas definitorias de los nuevos entornos de organizaci&oacute;n del trabajo y los derechos que conlleva. _1_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">d) Se han identificado los diferentes componentes del recibo de salario. _7_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">e) Se han identificado los recursos laborales existentes ante las diferentes vicisitudes que se pueden dar en la relaci&oacute;n laboral. 3% </span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">f) Se ha valorado el papel de la Seguridad Social como pilar esencial para la mejora de la calidad de vida de los ciudadanos. _7_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">g) Se han analizado las principales prestaciones derivadas de la suspensi&oacute;n y extinci&oacute;n de la relaci&oacute;n laboral. 7_%</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"108\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>Unidad 6</strong></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">. La relaci&oacute;n laboral.</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>Unidad 7</strong></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">. El contrato de trabajo.</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>Unidad 8</strong></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">. Salario y Seguridad Social.</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>Unidad 9.</strong></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\"> Modificaci&oacute;n, suspensi&oacute;n y extinci&oacute;n del contrato de trabajo.</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><em><strong>Proyecto 2.</strong></em></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><em><span style=\"font-weight: normal;\"> &iexcl;Vive tu primera experiencia profesional!</span></em></span></span></span></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>4. Analiza y eval&uacute;a su potencial profesional y sus intereses para guiarse en el proceso de autoorientaci&oacute;n y elabora una hoja de ruta para la inserci&oacute;n profesional en base al an&aacute;lisis de las competencias, intereses y destrezas personales.</strong></span></span></span></span></span></p>\r\n<p style=\"font-style: normal;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>25_ %</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">a) Se han evaluado los propios intereses, motivaciones, habilidades y destrezas en el marco de un proceso de autoconocimiento. _2_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">b) Se han analizado las cualidades y competencias personales afines a la actividad profesional relacionada con el perfil del t&iacute;tulo. _2_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">c) Se han determinado las competencias personales y sociales con valor para el empleo. 2__%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">d) Se han se&ntilde;alado las preferencias profesionales, intereses y metas en el marco de un proyecto profesional. _3_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">e) Se ha valorado el concepto de autoestima en el proceso de b&uacute;squeda de empleo. 1__%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">f) Se han identificado las fortalezas, debilidades, amenazas y oportunidades propias para la inserci&oacute;n profesional. 3__%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">g) Se han identificado expectativas de futuro para inserci&oacute;n profesional analizando competencias, intereses y destrezas personales. 2__%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">h) Se han valorado hitos importantes en la trayectoria vital con valor profesionalizador. _1_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">i) Se han identificado los itinerarios formativos profesionales relacionados con el perfil profesional. _3_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">j) Se han formulado objetivos profesionales y se ha determinado metas personales y profesionales para la mejora de la empleabilidad y las condiciones de inserci&oacute;n laboral. _3_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">k) Se ha trazado un plan de acci&oacute;n para desarrollar las &aacute;reas de mejora y potenciar las fortalezas personales con valor para el empleo. _3_%</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"108\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>Unidad 10</strong></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">. El proyecto profesional</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><em><strong>Proyecto 3</strong></em></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><em><span style=\"font-weight: normal;\">. Mi proyecto profesional</span></em></span></span></span></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>5. </strong></span></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>Aplica las estrategias para el aprendizaje aut&oacute;nomo reconociendo su valor profesionalizador, dise&ntilde;ando y optimizando su propio entorno de aprendizaje haciendo uso de las tecnolog&iacute;as digitales como herramientas de aprendizaje aut&oacute;nomo, siendo coherente con su identidad digital y sus propios objetivos profesionales planteados en su plan de desarrollo individual.</strong></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\">_5_%</span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">a) </span></span></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">Se ha tomado conciencia de la responsabilidad individual en el desarrollo profesional valorando la actitud de aprendizaje permanente para el desarrollo de propias y nuevas competencias. 1__% </span></span></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">b) </span></span></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">Se ha identificado la empleabilidad como capacidad de adaptaci&oacute;n al entorno laboral. _1_% </span></span></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">c) Se han conocido y utilizado herramientas, fuentes de informaci&oacute;n, conexiones y actividades para la configuraci&oacute;n de un entorno personal de aprendizaje para la empleabilidad. _1_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">d) Se ha puesto en pr&aacute;ctica la competencia digital para configurar un entorno personal de aprendizaje para la empleabilidad. _1_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">e) Se ha analizado el concepto de identidad digital y su impacto en la empleabilidad. _1_% </span></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>AULA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">f</span></span></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">) Se ha justificado el dise&ntilde;o de su entorno de aprendizaje basado en c&oacute;mo este mejora la empleabilidad. __% </span></span></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">g) Se ha elaborado su plan de desarrollo individual como herramienta para la mejora de la empleabilidad. _2_%</span></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong> AULA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">h) Se han aplicado las herramientas de aprendizaje aut&oacute;nomo para su desarrollo personal y profesional. _1_% </span></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>AULA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">i) Se ha dise&ntilde;ado el entorno de aprendizaje que permite alcanzar el plan de desarrollo individual. _1_% </span></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>AULA</strong></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"108\">\r\n<p style=\"font-style: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"font-style: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"font-style: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"font-style: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>Unidad 11.</strong></span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\"> El aprendizaje aut&oacute;nomo y la competencia digital.</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><em><strong>Proyecto 4.</strong></em></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><em><span style=\"font-weight: normal;\"> Genera tu entorno personal de aprendizaje.</span></em></span></span></span></span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(3224, 113, 17, '<div class=\"page\" title=\"Page 24\">\r\n<p class=\"western\" align=\"justify\">Por un lado se dispone de un aula espec&iacute;fica de inform&aacute;tica con al menos 20 ordenadores conectados en red y un servidor, que permitir&aacute;n la realizaci&oacute;n de pr&aacute;cticas sobre los sistemas operativos de las familias Microsoft y Linux. En el aula hay tambi&eacute;n pizarra de pl&aacute;stico, para evitar el polvo de tiza. Se contar&aacute;, as&iacute; mismo, con un proyector o televisor conectado al ordenador del profesor, lo que ayudar&aacute; a las exposiciones y a la ejemplificaci&oacute;n directa sobre el ordenador cuando sea necesario.</p>\r\n<p class=\"western\" align=\"justify\">Por otro lado, se debe disponer de acceso a Internet desde cualquier ordenador para las numerosas pr&aacute;cticas que lo requieren.</p>\r\n<p>Por último, en el módulo puede que ciertas actividades requieran el uso del dispositivo móvil por parte del alumnado (para documentar gráficamente la memoria de prácticas con ordenadores, por ejemplo). En estas circunstancias será el profesor quien indique al alumnado cuándo lo pueden usar y qué uso deben darle, estando prohibido cualquier otro uso diferente al indicado.</p>\r\n<div class=\"layoutArea\">&nbsp;</div>\r\n</div>'),
(3226, 400, 9, '<p><strong>1.&nbsp; RA Selecciona oportunidades de empleo, identificando las diferentes posibilidades de inserci&oacute;n y las alternativas de aprendizaje a lo largo de la vida.</strong></p>\r\n<p>Criterios de evaluaci&oacute;n:</p>\r\n<p>a) Se ha valorado la importancia de la formaci&oacute;n permanente como factor clave para la empleabilidad y la adaptaci&oacute;n a las exigencias del proceso productivo.</p>\r\n<p>b) Se han identificado los itinerarios formativo-profesionales relacionados con el perfil profesional del t&iacute;tulo profesional b&aacute;sico.</p>\r\n<p>c) Se han determinado las aptitudes y actitudes requeridas para la actividad profesional relacionada con el t&iacute;tulo profesional b&aacute;sico</p>\r\n<p>d) Se han identificado los principales v&iacute;as de inserci&oacute;n laboral para el t&iacute;tulo profesional b&aacute;sico.</p>\r\n<p>e) Se han determinado las t&eacute;cnicas utilizadas en el proceso de b&uacute;squeda de empleo.</p>\r\n<p>f) Se ha realizado la valoraci&oacute;n de la personalidad, aspiraciones, actitudes y formaci&oacute;n propia para la toma de decisiones.</p>\r\n<p><strong>RA2. Ejerce los derechos y cumple las obligaciones que se derivan de las relaciones laborales, reconoci&eacute;ndolas en los diferentes contratos de trabajo.</strong></p>\r\n<p>Criterios de evaluaci&oacute;n:</p>\r\n<p>a) Se han identificado los conceptos b&aacute;sicos del derecho del trabajo.</p>\r\n<p>b) Se han distinguido los principales organismos que intervienen en las relaciones entre empresarios y trabajadores.</p>\r\n<p>c) Se han determinado los derechos y obligaciones derivados de la relaci&oacute;n laboral. d) Se han clasificado las principales modalidades de contrataci&oacute;n.</p>\r\n<p>e) Se han identificado las causas y efectos de la modificaci&oacute;n, suspensi&oacute;n y extinci&oacute;n de la relaci&oacute;n laboral. f) Se ha analizado el recibo de salarios, identificando los principales elementos que lo integran.</p>\r\n<p>g) Se han analizado las diferentes medidas de conflicto colectivo y los procedimientos de soluci&oacute;n de conflictos.</p>\r\n<p>h) Se han determinado las condiciones de trabajo pactadas en un convenio colectivo aplicable al sector relacionado con el t&iacute;tulo profesional b&aacute;sico.</p>\r\n<p>RA3. Determina la acci&oacute;n protectora del sistema de la Seguridad Social ante las distintas contingencias cubiertas, identificando las distintas clases de prestaciones.</p>\r\n<p>Criterios de evaluaci&oacute;n:</p>\r\n<p>a) Se ha valorado el papel de la Seguridad Social como pilar esencial para la mejora de la calidad de vida de los ciudadanos.</p>\r\n<p>b) Se han enumerado las diversas contingencias que cubre el sistema de Seguridad Social. c) Se han identificado los reg&iacute;menes existentes en el sistema de Seguridad Social.</p>\r\n<p>d) Se han identificado las obligaciones de empresario y trabajador dentro del sistema de Seguridad Social.</p>\r\n<p>e) Se han clasificado las prestaciones del sistema de Seguridad Social, identificando los requisitos necesarios, especialmente en caso de enfermedad, accidente y paro.</p>'),
(3228, 365, 41, '<p>Seg&uacute;n se indica en el Real Decreto 1629/2009, de 30 de octubre, por el que se establece el t&iacute;tulo de T&eacute;cnico Superior en Adminsitraci&oacute;n de Sistemas Inform&aacute;ticos en Red y se fijan sus ense&ntilde;anzas m&iacute;nimas: \"La formaci&oacute;n del m&oacute;dulo se relaciona con todos los objetivos generales del ciclo y las competencias profesionales, personales y sociales del t&iacute;tulo.\"</p>'),
(3232, 18, 41, '<p>La competencia general del ciclo de DAM consiste en desarrollar, implantar, documentar y mantener aplicaciones inform&aacute;ticas multiplataforma, utilizando tecnolog&iacute;as y entornos de desarrollo espec&iacute;ficos, garantizando el acceso a los datos de forma segura y cumpliendo los criterios de &laquo;usabilidad&raquo; y calidad exigidas en los est&aacute;ndares establecidos.</p>'),
(3233, 366, 41, '<p>La competencia general del ciclo de DAM consiste en desarrollar, implantar, documentar y mantener aplicaciones inform&aacute;ticas multiplataforma, utilizando tecnolog&iacute;as y entornos de desarrollo espec&iacute;ficos, garantizando el acceso a los datos de forma segura y cumpliendo los criterios de &laquo;usabilidad&raquo; y calidad exigidas en los est&aacute;ndares establecidos.</p>'),
(3235, 367, 41, '<p>La competencia general del T&eacute;cnico Superior en DAW consiste en desarrollar, implantar, y mantener aplicaciones web, con independencia del modelo empleado y utilizando tecnolog&iacute;as espec&iacute;ficas, garantizando el acceso a los datos de forma segura y cumpliendo los criterios de accesibilidad, usabilidad y calidad exigidas en los est&aacute;ndares establecidos.</p>'),
(3236, 55, 41, '<p><em>Desarrollar, implantar, documentar y mantener aplicaciones inform&aacute;ticas multiplataforma, utilizando tecnolog&iacute;as y entornos de desarrollo espec&iacute;ficos, garantizando el acceso a los datos de forma segura y cumpliendo los criterios de &laquo;usabilidad&raquo; y calidad exigidas en los est&aacute;ndares establecidos.</em></p>'),
(3237, 65, 41, '<p><span style=\"font-weight: 500;\">La competencia general del T&eacute;cnico Superior en DAW consiste en desarrollar, implantar, y mantener aplicaciones web, con independencia del modelo empleado y utilizando tecnolog&iacute;as espec&iacute;ficas, garantizando el acceso a los datos de forma segura y cumpliendo los criterios de accesibilidad, usabilidad y calidad exigidas en los est&aacute;ndares establecidos.</span></p>\r\n<p><span style=\"font-weight: 500;\">El m&oacute;dulo actual contribuye a esta competencia general, ya que capacita a los estudiantes para gestionar todo el comportamiento de una aplicaci&oacute;n web en el lado del servidor. Llevar a cabo una correcta programaci&oacute;n en dicho entorno, as&iacute; como manejar adecuadamente el acceso a datos, se antojan fundamentales para garantizar la adquisici&oacute;n de la competencia general del t&iacute;tulo.</span></p>'),
(3239, 314, 41, '<p>Este m&oacute;dulo profesional contiene la formaci&oacute;n necesaria para desempe&ntilde;ar la<br />funci&oacute;n de an&aacute;lisis forense.<br />La funci&oacute;n de an&aacute;lisis forense incluye aspectos como el an&aacute;lisis de dispositivos de<br />almacenamiento no vol&aacute;til, de ficheros Logs, dispositivos m&oacute;viles, Cloud e IoT.</p>\r\n<p>Las actividades profesionales asociadas a esta funci&oacute;n se aplican en la extracci&oacute;n<br />de las evidencias para su an&aacute;lisis mediante la estrategia adecuada que garantice la<br />disponibilidad de los recursos.</p>'),
(3240, 312, 41, '<p>La competencia general de este curso de especializaci&oacute;n consiste en definir e implementar estrategias de seguridad en los sistemas de informaci&oacute;n realizando diagn&oacute;sticos de ciberseguridad, identificando vulnerabilidades e implementando las medidas necesarias para mitigarlas aplicando la normativa vigente y est&aacute;ndares del sector, siguiendo los protocolos de calidad, de prevenci&oacute;n de riesgos laborales y respeto ambiental.</p>'),
(3241, 315, 41, '<p>La competencia general de este curso de especializaci&oacute;n consiste en definir e implementar estrategias de seguridad en los sistemas de informaci&oacute;n realizando diagn&oacute;sticos de ciberseguridad, identificando vulnerabilidades e implementando las medidas necesarias para mitigarlas aplicando la normativa vigente y est&aacute;ndares del sector, siguiendo los protocolos de calidad, de prevenci&oacute;n de riesgos laborales y respeto ambiental.</p>'),
(3242, 311, 41, '<p>La competencia general de este curso de especializaci&oacute;n consiste en definir e implementar estrategias de seguridad en los sistemas de informaci&oacute;n realizando diagn&oacute;sticos de ciberseguridad, identificando vulnerabilidades e implementando las medidas necesarias para mitigarlas aplicando la normativa vigente y est&aacute;ndares del sector, siguiendo los protocolos de calidad, de prevenci&oacute;n de riesgos laborales y respeto ambiental.</p>'),
(3243, 316, 41, '<p>La competencia general de este curso de especializaci&oacute;n consiste en definir e implementar estrategias de seguridad en los sistemas de informaci&oacute;n realizando diagn&oacute;sticos de ciberseguridad, identificando vulnerabilidades e implementando las medidas necesarias para mitigarlas aplicando la normativa vigente y est&aacute;ndares del sector, siguiendo los protocolos de calidad, de prevenci&oacute;n de riesgos laborales y respeto ambiental.</p>'),
(3244, 313, 41, '<p>La competencia general de este curso de especializaci&oacute;n consiste en definir e implementar estrategias de seguridad en los sistemas de informaci&oacute;n realizando diagn&oacute;sticos de ciberseguridad, identificando vulnerabilidades e implementando las medidas necesarias para mitigarlas aplicando la normativa vigente y est&aacute;ndares del sector, siguiendo los protocolos de calidad, de prevenci&oacute;n de riesgos laborales y respeto ambienta.</p>'),
(3245, 389, 41, '<p>La competencia general de este curso de especializaci&oacute;n consiste en programar y aplicar sistemas inteligentes que optimizan la gesti&oacute;n de la informaci&oacute;n y la explotaci&oacute;n de datos masivos, garantizando el acceso a los datos de forma segura y cumpliendo los criterios de accesibilidad, usabilidad y calidad exigidas en los est&aacute;ndares establecidos, as&iacute; como los principios &eacute;ticos y legales.</p>'),
(3246, 324, 41, '<p>La competencia general de este curso de especializaci&oacute;n consiste en <em>programar y aplicar sistemas inteligentes que optimizan la gesti&oacute;n de la informaci&oacute;n y la explotaci&oacute;n de datos masivos, garantizando el acceso a los datos de forma segura y cumpliendo los criterios de accesibilidad, usabilidad y calidad, exigidas en los est&aacute;ndares establecidos, as&iacute; como los principios &eacute;ticos y legales</em>.</p>'),
(3247, 320, 41, '<p>La competencia general de este curso de especializaci&oacute;n consiste en programar y aplicar sistemas inteligentes que optimizan la gesti&oacute;n de la informaci&oacute;n y la explotaci&oacute;n de datos masivos, garantizando el acceso a los datos de forma segura y cumpliendo los criterios de accesibilidad, usabilidad y calidad exigidas en los est&aacute;ndares establecidos, as&iacute; como los principios &eacute;ticos y legales.</p>'),
(3248, 321, 41, '<p>La competencia general de este curso de especializaci&oacute;n consiste en programar y aplicar sistemas inteligentes que optimizan la gesti&oacute;n de la informaci&oacute;n y la explotaci&oacute;n de datos masivos, garantizando el acceso a los datos de forma segura y cumpliendo los criterios de accesibilidad, usabilidad y calidad exigidas en los est&aacute;ndares establecidos, as&iacute; como los principios &eacute;ticos y legales.</p>');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3249, 323, 41, '<p>La competencia general de este curso de especializaci&oacute;n consiste en programar y aplicar<br />sistemas inteligentes que optimizan la gesti&oacute;n de la informaci&oacute;n y la explotaci&oacute;n de datos<br />masivos, garantizando el acceso a los datos de forma segura y cumpliendo los criterios de accesibilidad, usabilidad y calidad, exigidas en los est&aacute;ndares establecidos, as&iacute; como los principios &eacute;ticos y legales.</p>'),
(3250, 160, 1, '<p>adsfasdfasdf</p>'),
(3251, 425, 19, '<p>obra de teatro</p>'),
(3275, 67, 23, '<p>Para poder valorar la consecuci&oacute;n de objetivos por parte del alumnado dispondremos de diversos m&eacute;todos, t&eacute;cnicas e instrumentos que, aplicando los criterios de evaluaci&oacute;n correspondientes, nos permitir&aacute;n conocer el grado de integraci&oacute;n de estos objetivos. Entre estos m&eacute;todos, t&eacute;cnicas e instrumentos se encuentran:</p>\r\n<p>Los instrumentos utilizados para la evaluaci&oacute;n, entre otros, son los siguientes:</p>\r\n<ul>\r\n<li>Observaci&oacute;n sistem&aacute;tica.</li>\r\n<li>Preguntas en clase.</li>\r\n<li>Trabajos, pr&aacute;cticas y actividades individuales y en grupo.</li>\r\n<li>Repositorios de C&oacute;digo y Control de Versiones (evidencias en Git/GitHub/GitLab, uso adecuado de issues, ramas y PRs).</li>\r\n<li>Entrevistas y Tutor&iacute;as Individualizadas (defensa de pr&aacute;cticas, revisi&oacute;n de decisiones de dise&ntilde;o).</li>\r\n<li>Pruebas.</li>\r\n</ul>'),
(3276, 67, 38, '<p>La <strong>formaci&oacute;n en empresa</strong> es una parte esencial de la nueva <strong>Formaci&oacute;n Profesional dual</strong>, regulada por el<strong> Real Decreto 659/2023, de 18 de julio</strong>, que desarrolla la Ley Org&aacute;nica 3/2022. Este modelo integra la formaci&oacute;n te&oacute;rica del centro educativo con la pr&aacute;ctica en entornos reales de trabajo, de forma coordinada y planificada. De esta manera, la formaci&oacute;n en empresa se convierte en un elemento estructural del ciclo formativo, orientado a que el alumnado adquiera las competencias profesionales necesarias y alcance los <strong>resultados de aprendizaje</strong> establecidos en el curr&iacute;culo oficial de su t&iacute;tulo.</p>\r\n<p>En el <strong>r&eacute;gimen general de la FP dual</strong>, la formaci&oacute;n en empresa representa entre el <strong>25% y el 35%</strong> de la duraci&oacute;n total del ciclo, sin que exista una relaci&oacute;n laboral con la empresa. Durante este periodo, el estudiante desarrolla actividades reales vinculadas a los <strong>resultados de aprendizaje</strong> del ciclo, siguiendo un <strong>plan de formaci&oacute;n individualizado</strong> dise&ntilde;ado conjuntamente por el centro educativo y la empresa. Esta coordinaci&oacute;n garantiza una experiencia formativa de calidad, pr&aacute;ctica y ajustada a las necesidades del sector profesional.</p>'),
(3278, 67, 18, '<ol>\r\n<li><a href=\"https://www.amazon.es/hagas-pensar-Actualizaci%C3%B3n-T%C3%ADtulos-Especiales/dp/8441537275\">No me hagas pensar, Steve krug</a></li>\r\n<li><a href=\"https://olgacarreras.blogspot.com/2024/02/libro-accesibilidad-web-wcag-22-de.html\">Accesibilidad Web WCAG 2.2 de forma sencilla, Olga Revilla y Olga Carreras</a></li>\r\n<li><a href=\"https://olgacarreras.blogspot.com/2023/07/resena-del-libro-guia-aplicaciones.html\">Gu&iacute;a Aplicaciones m&oacute;viles accesibles, Olga Carreras</a></li>\r\n<li><a href=\"https://olgacarreras.blogspot.com/2020/04/resena-guia-todo-en-uno-sobre-la.html\">Gu&iacute;a todo en uno sobre la accesibilidad web en Espa&ntilde;a.</a></li>\r\n<li><a href=\"https://olgacarreras.blogspot.com/2015/11/pautas-accesibilidad-usabilidad-movil.html\">Pautas&nbsp;de usabilidad y accesibilidad m&oacute;vil</a></li>\r\n<li><a href=\"https://www.amazon.es/Las-leyes-del-Utilizando-experiencia-ebook/dp/B0BKC48Z82\">Las leyes del UX, Jon Yablonski</a></li>\r\n<li><a href=\"https://www.amazon.es/Lean-UX-principios-experiencia-Emprende/dp/8416125023\">Lean UX, Jeff Gothelf</a></li>\r\n<li><a href=\"https://www.amazon.es/Experiencia-Usuario-Principios-y-M%C3%A9todos-ebook/dp/B00TIXX0MA\">Experiencia de usuario: Principios y m&eacute;todos. Yusef Hassan Montero</a></li>\r\n<li><a href=\"https://www.amazon.es/Usabilidad-Deja-sufrir-Social-Media/dp/8441539804\">Usabilidad. Deja de sufrir. Daniel Torres Burriel</a></li>\r\n<li><a href=\"https://www.amazon.es/Haz-f%C3%A1cil-imposible-T%C3%ADtulos-Especiales/dp/8441527547\">Haz f&aacute;cil lo imposible, Steve Krug</a></li>\r\n<li><a href=\"https://www.amazon.es/Psicolog%C3%ADa-del-color-colores-sentimientos/dp/8425219779\">Psicolog&iacute;a del color: C&oacute;mo act&uacute;an los colores sobre los sentimientos y la raz&oacute;n. Eva Heller</a></li>\r\n</ol>'),
(3279, 41, 23, '<p data-start=\"1145\" data-end=\"1271\">Para valorar el grado de consecuci&oacute;n de los resultados de aprendizaje, se emplear&aacute;n m&uacute;ltiples y variados instrumentos de evaluaci&oacute;n:</p>\r\n<ol data-start=\"1273\" data-end=\"2386\">\r\n<li data-start=\"1273\" data-end=\"1521\">\r\n<p data-start=\"1276\" data-end=\"1309\"><strong data-start=\"1276\" data-end=\"1307\">Pruebas escritas y/u orales</strong></p>\r\n<ul data-start=\"1313\" data-end=\"1521\">\r\n<li data-start=\"1313\" data-end=\"1364\">\r\n<p data-start=\"1315\" data-end=\"1364\">Ex&aacute;menes te&oacute;ricos por Unidades de Programaci&oacute;n (UP).</p>\r\n</li>\r\n<li data-start=\"1466\" data-end=\"1521\">\r\n<p data-start=\"1468\" data-end=\"1521\">Examen final ordinario y, en su caso, extraordinario.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1523\" data-end=\"1722\">\r\n<p data-start=\"1526\" data-end=\"1549\"><strong data-start=\"1526\" data-end=\"1547\">Pruebas pr&aacute;cticas</strong></p>\r\n<ul data-start=\"1553\" data-end=\"1722\">\r\n<li data-start=\"1553\" data-end=\"1609\">\r\n<p data-start=\"1555\" data-end=\"1609\">Ejecuci&oacute;n de procedimientos en taller o laboratorio.</p>\r\n</li>\r\n<li data-start=\"1613\" data-end=\"1662\">\r\n<p data-start=\"1615\" data-end=\"1662\">Resoluci&oacute;n de incidencias reales o simuladas.</p>\r\n</li>\r\n<li data-start=\"1666\" data-end=\"1722\">\r\n<p data-start=\"1668\" data-end=\"1722\">Manejo de herramientas, equipos y software espec&iacute;fico.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1724\" data-end=\"1921\">\r\n<p data-start=\"1727\" data-end=\"1755\"><strong data-start=\"1727\" data-end=\"1753\">Trabajos y actividades</strong></p>\r\n<ul data-start=\"1759\" data-end=\"1921\">\r\n<li data-start=\"1759\" data-end=\"1822\">\r\n<p data-start=\"1761\" data-end=\"1822\">Res&uacute;menes, esquemas, mapas conceptuales previos a ex&aacute;menes.</p>\r\n</li>\r\n<li data-start=\"1826\" data-end=\"1875\">\r\n<p data-start=\"1828\" data-end=\"1875\">Actividades de investigaci&oacute;n y documentaci&oacute;n.</p>\r\n</li>\r\n<li data-start=\"1879\" data-end=\"1921\">\r\n<p data-start=\"1881\" data-end=\"1921\">Ejercicios de an&aacute;lisis y dise&ntilde;o t&eacute;cnico.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1923\" data-end=\"2164\">\r\n<p data-start=\"1926\" data-end=\"1970\"><strong data-start=\"1926\" data-end=\"1968\">Observaci&oacute;n sistem&aacute;tica del profesor/a</strong></p>\r\n<ul data-start=\"1974\" data-end=\"2164\">\r\n<li data-start=\"1974\" data-end=\"2028\">\r\n<p data-start=\"1976\" data-end=\"2028\">Cumplimiento de normas de seguridad y uso de EPIs.</p>\r\n</li>\r\n<li data-start=\"2032\" data-end=\"2097\">\r\n<p data-start=\"2034\" data-end=\"2097\">Organizaci&oacute;n, limpieza y mantenimiento del puesto de trabajo.</p>\r\n</li>\r\n<li data-start=\"2101\" data-end=\"2164\">\r\n<p data-start=\"2103\" data-end=\"2164\">Actitud, colaboraci&oacute;n y autonom&iacute;a en el desarrollo de tareas.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"2166\" data-end=\"2386\">\r\n<p data-start=\"2169\" data-end=\"2193\"><strong data-start=\"2169\" data-end=\"2191\">Otros instrumentos</strong></p>\r\n<ul data-start=\"2197\" data-end=\"2386\">\r\n<li data-start=\"2197\" data-end=\"2251\">\r\n<p data-start=\"2199\" data-end=\"2251\">Portafolio o recopilaci&oacute;n de trabajos y pr&aacute;cticas.</p>\r\n</li>\r\n<li data-start=\"2255\" data-end=\"2318\">\r\n<p data-start=\"2257\" data-end=\"2318\">Entregas y registros digitales en Aules.</p>\r\n</li>\r\n<li data-start=\"2322\" data-end=\"2386\">\r\n<p data-start=\"2324\" data-end=\"2386\">Informes de seguimiento en caso de formaci&oacute;n en empresa (FE).</p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ol>'),
(3281, 41, 38, ''),
(3283, 417, 1, '<p>Uno de los primeros conceptos a considerar en una programaci&oacute;n es el concepto de curr&iacute;culo, que seg&uacute;n contiene la Ley Org&aacute;nica 2/2006, de 3 de Mayo (LOE), en el Art&iacute;culo 6 se entiende como &ldquo;el conjunto de objetivos, competencias b&aacute;sicas, contenidos, m&eacute;todos pedag&oacute;gicos y criterios de evaluaci&oacute;n de cada una de las ense&ntilde;anzas reguladas&rdquo;. El siguiente marco legislativo es aplicable al Ciclo Formativo de Grado Superior de Desarrollo de Aplicaciones Web&nbsp;(en adelante DAW) para la Comunidad Valenciana, que sirve de referencia para la elaboraci&oacute;n de esta Programaci&oacute;n Did&aacute;ctica:</p>\r\n<ul>\r\n<li><strong>Ley Org&aacute;nica 2/2006</strong>&nbsp;de Educaci&oacute;n (LOE), de 3 de Mayo, que se refiere a la Formaci&oacute;n Profesional Espec&iacute;fica en sus Art&iacute;culos 39 a 44.</li>\r\n<li><strong>Ley Org&aacute;nica 3/2022</strong>, de 31 de marzo, de ordenaci&oacute;n e integraci&oacute;n de la Formaci&oacute;n Profesional.</li>\r\n<li><strong>Real Decreto 659/2023</strong>, de 18 de julio, ha establecido la ordenaci&oacute;n general de la formaci&oacute;n profesional del sistema educativo, y define en el art&iacute;culo&nbsp;12 la estructura de los t&iacute;tulos de formaci&oacute;n profesional tomando como base el Cat&aacute;logo Nacional de Cualificaciones Profesionales, las directrices fijadas por la Uni&oacute;n Europea y otros aspectos de inter&eacute;s social.</li>\r\n<li><strong>Real Decreto 686/2010</strong>, de 20&nbsp;de mayo, por el que se establece el t&iacute;tulo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Web&nbsp;y se fijan sus ense&ntilde;anzas m&iacute;nimas. Bas&aacute;ndose en este Real Decreto la Comunitat Valenciana establece el curr&iacute;culo completo de estas nuevas ense&ntilde;anzas de Formaci&oacute;n Profesional Espec&iacute;fica ampliando y contextualizando los contenidos de los m&oacute;dulos profesionales, respetando el perfil profesional del mismo.</li>\r\n<li><strong>ORDEN 78/2010</strong>, de 27 de agosto, de la Conselleria de Educaci&oacute;n, por la que se regulan determinados aspectos de la ordenaci&oacute;n y organizaci&oacute;n acad&eacute;mica de los ciclos formativos de Formaci&oacute;n Profesional del sistema educativo en el &aacute;mbito territorial de la Comunitat Valenciana.</li>\r\n<li><strong>ORDEN 8/2025</strong>, de 30 de abril, de la Conselleria de Educaci&oacute;n, por la que se regula la evaluaci&oacute;n del alumnado de los ciclos formativos de Formaci&oacute;n Profesional del sistema educativo en el &aacute;mbito territorial de la Comunitat Valenciana.</li>\r\n<li><strong>Decreto&nbsp;117/2025</strong>, de 5 de agosto, del Consell, por el que establecen los curr&iacute;culos de los ciclos formativos de Grado B&aacute;sico de Formaci&oacute;n Profesional, en aplicaci&oacute;n de la Ley Org&aacute;nica 3/2022, de 31 de marzo, de ordenaci&oacute;n e integraci&oacute;n de la Formaci&oacute;n Profesional.</li>\r\n<li><strong>Decreto&nbsp;114/2025</strong>, de 29 de julio, del Consell, por el que se establecen los curr&iacute;culos de los ciclos formativos de grado medio y de grado superior de Formaci&oacute;n Profesional, en aplicaci&oacute;n de la Ley org&aacute;nica 3/2022, de 31 de marzo, de ordenaci&oacute;n e integraci&oacute;n de la Formaci&oacute;n Profesional.</li>\r\n<li><strong>Orden&nbsp;8/2025</strong>, de 22 de abril, de la Conselleria de Educaci&oacute;n, Cultura, Universidades y Empleo, por la que se regula la evaluaci&oacute;n del proceso de ense&ntilde;anza-aprendizaje en ciclos formativos y cursos de especializaci&oacute;n derivados de la Ley org&aacute;nica 3/2022, de 31 de marzo, de ordenaci&oacute;n e integraci&oacute;n de la Formaci&oacute;n Profesional.</li>\r\n<li><strong>Real Decreto 659/2023</strong>, de 18 de julio, por el que se desarrolla la ordenaci&oacute;n del Sistema de Formaci&oacute;n Profesional.</li>\r\n</ul>\r\n<p>El perfil profesional del t&iacute;tulo de T&eacute;cnico Superior en DAW&nbsp;viene expresado por la competencia general, las competencias profesionales, personales y sociales y la relaci&oacute;n de cualificaciones y, en su caso, las unidades de competencia del Cat&aacute;logo Nacional de Cualificaciones Profesionales incluidas en el t&iacute;tulo.</p>\r\n<p>El m&oacute;dulo optativo de <strong>Introducci&oacute;n a la nube&nbsp;</strong>tiene una duraci&oacute;n de&nbsp;<strong>100 horas</strong>&nbsp;totales, impartidas a raz&oacute;n de&nbsp;<strong>3&nbsp;horas semales</strong>.&nbsp;Y se&nbsp;encuentra&nbsp;en el segundo curso del Ciclo Formativo de Grado Superior correspondiente al t&iacute;tulo de Desarrollo de Aplicaciones Web.</p>'),
(3284, 423, 1, '<p data-start=\"307\" data-end=\"911\">En la sociedad actual, los videojuegos se han consolidado como una de las principales manifestaciones culturales y tecnol&oacute;gicas del siglo XXI. M&aacute;s all&aacute; de su dimensi&oacute;n l&uacute;dica, constituyen un sector de gran impacto econ&oacute;mico, social y art&iacute;stico, que combina disciplinas tan diversas como la narrativa, el dise&ntilde;o gr&aacute;fico, la programaci&oacute;n, la m&uacute;sica o la inteligencia artificial. Los videojuegos son hoy en d&iacute;a uno de los principales motores de innovaci&oacute;n tecnol&oacute;gica, al mismo tiempo que se han convertido en una forma de comunicaci&oacute;n, expresi&oacute;n y socializaci&oacute;n para millones de j&oacute;venes en todo el mundo.</p>\r\n<p data-start=\"913\" data-end=\"1528\">Desde una perspectiva educativa, el <strong data-start=\"949\" data-end=\"987\">dise&ntilde;o y desarrollo de videojuegos</strong> representa una oportunidad para acercar al alumnado a un aprendizaje activo, creativo y multidisciplinar. A trav&eacute;s de esta materia, se fomenta no solo la adquisici&oacute;n de competencias digitales, sino tambi&eacute;n habilidades de pensamiento computacional, resoluci&oacute;n de problemas, trabajo en equipo, gesti&oacute;n de proyectos y creatividad. Todo ello conecta directamente con el enfoque competencial de la <strong data-start=\"1381\" data-end=\"1391\">LOMLOE</strong>, que pone el acento en que el alumnado adquiera herramientas para desenvolverse de forma cr&iacute;tica y responsable en la sociedad digital.</p>\r\n<p data-start=\"1530\" data-end=\"1997\">Por otro lado, esta materia responde a la necesidad de reducir la brecha digital, ofreciendo al alumnado un espacio en el que no solo consuman tecnolog&iacute;a, sino que aprendan a crearla y comprenderla. De este modo, se contribuye a formar ciudadanos activos, cr&iacute;ticos y capaces de aprovechar las oportunidades que ofrece la sociedad de la informaci&oacute;n, en consonancia con los objetivos de la <strong data-start=\"1918\" data-end=\"1944\">Agenda Digital Europea</strong> y la <strong data-start=\"1950\" data-end=\"1994\">Estrategia de Educaci&oacute;n y Formaci&oacute;n 2030</strong>.</p>\r\n<h4 data-start=\"1530\" data-end=\"1997\">Marco legal</h4>\r\n<p data-start=\"204\" data-end=\"775\">La materia optativa <strong data-start=\"224\" data-end=\"278\">&ldquo;Dise&ntilde;o y desarrollo de videojuegos&rdquo; en 2.&ordm; de ESO</strong> se fundamenta en la normativa educativa vigente, que apuesta por una formaci&oacute;n competencial, inclusiva y adaptada a la sociedad digital del siglo XXI.</p>\r\n<ul>\r\n<li data-start=\"204\" data-end=\"775\">La <strong data-start=\"433\" data-end=\"485\">Ley Org&aacute;nica 3/2020, de 29 de diciembre (LOMLOE)</strong>, que modifica la LOE, establece la importancia de integrar la <strong data-start=\"548\" data-end=\"637\">competencia digital, la creatividad, el pensamiento cr&iacute;tico y el trabajo colaborativo</strong> en el curr&iacute;culo, permitiendo que los centros oferten optativas vinculadas a los intereses del alumnado y a los retos sociales actuales.</li>\r\n<li data-start=\"204\" data-end=\"775\">A nivel estatal, el <strong data-start=\"797\" data-end=\"838\">Real Decreto 217/2022, de 29 de marzo</strong>, sobre las ense&ntilde;anzas m&iacute;nimas de la ESO, refuerza esta idea al se&ntilde;alar la necesidad de flexibilidad curricular para incorporar materias que potencien la <strong data-start=\"992\" data-end=\"1062\">alfabetizaci&oacute;n digital, la resoluci&oacute;n de problemas y la innovaci&oacute;n</strong>.</li>\r\n<li data-start=\"204\" data-end=\"775\">En la <strong data-start=\"1073\" data-end=\"1097\">Comunidad Valenciana</strong>, el <strong data-start=\"1102\" data-end=\"1138\">Decreto 108/2022, de 5 de agosto</strong>, regula el curr&iacute;culo de la ESO, incluyendo la oferta de optativas como v&iacute;a para atender la diversidad y fomentar propuestas innovadoras. Asimismo, normas auton&oacute;micas como el <strong data-start=\"1313\" data-end=\"1355\">Decreto 104/2018 (equidad e inclusi&oacute;n)</strong> y el <strong data-start=\"1361\" data-end=\"1406\">Decreto 195/2022 (igualdad y convivencia)</strong> subrayan la relevancia de un uso educativo, creativo y responsable de la tecnolog&iacute;a.</li>\r\n</ul>\r\n<p data-start=\"1495\" data-end=\"1716\">En este marco, la materia de <strong data-start=\"2942\" data-end=\"2996\">&ldquo;Dise&ntilde;o y desarrollo de videojuegos&rdquo; en 2.&ordm; de ESO</strong> se justifica como una propuesta innovadora que responde tanto a los retos planteados por la sociedad actual como a las directrices normativas, contribuyendo al desarrollo integral del alumnado mediante el uso pedag&oacute;gico de una de las herramientas culturales y tecnol&oacute;gicas m&aacute;s influyentes de nuestro tiempo.</p>'),
(3286, 423, 25, '<p>La materia <strong data-start=\"641\" data-end=\"679\">Dise&ntilde;o y desarrollo de videojuegos</strong> contribuye de manera significativa al desarrollo de las competencias clave establecidas en la LOMLOE (RD 217/2022).</p>\r\n<p>A continuaci&oacute;n, se presenta la relaci&oacute;n entre cada competencia y los <strong data-start=\"865\" data-end=\"892\">descriptores operativos</strong> m&aacute;s directamente vinculados a la asignatura:</p>\r\n<ol>\r\n<li><strong>Competencia en comunicaci&oacute;n ling&uuml;&iacute;stica (CCL)</strong>\r\n<ul>\r\n<li>Expresar ideas, proyectos y procesos de forma oral y escrita, adecu&aacute;ndose al contexto comunicativo.</li>\r\n<li>Comprender y utilizar el vocabulario espec&iacute;fico vinculado al dise&ntilde;o y la programaci&oacute;n de videojuegos.</li>\r\n</ul>\r\n</li>\r\n<li><strong>Competencia pluriling&uuml;e (CP)</strong>\r\n<ul>\r\n<li>Utilizar de forma b&aacute;sica recursos en otras lenguas (manuales, tutoriales, interfaces de programas) para resolver problemas o ampliar conocimientos.</li>\r\n<li>Valorar la diversidad ling&uuml;&iacute;stica en los videojuegos como medio de comunicaci&oacute;n global.</li>\r\n</ul>\r\n</li>\r\n<li><strong>Competencia matem&aacute;tica y competencia en ciencia, tecnolog&iacute;a e ingenier&iacute;a (CMCT)</strong>\r\n<ul>\r\n<li>Aplicar el pensamiento l&oacute;gico y matem&aacute;tico para resolver problemas de programaci&oacute;n por bloques.</li>\r\n<li>Utilizar conceptos b&aacute;sicos de coordenadas, variables, algoritmos y secuencias para el dise&ntilde;o de videojuegos.</li>\r\n<li>Abordar problemas tecnol&oacute;gicos con autonom&iacute;a, creatividad y esp&iacute;ritu cr&iacute;tico.</li>\r\n</ul>\r\n</li>\r\n<li><strong>Competencia digital (CD)</strong>\r\n<ul>\r\n<li>Crear y editar recursos digitales (sprites, escenarios, personajes) utilizando programas espec&iacute;ficos.</li>\r\n<li>Desarrollar proyectos mediante la programaci&oacute;n por bloques, aplicando principios b&aacute;sicos de pensamiento computacional.</li>\r\n<li>Hacer un uso seguro, responsable y creativo de la tecnolog&iacute;a.</li>\r\n</ul>\r\n</li>\r\n<li><strong>Competencia personal, social y de aprender a aprender (CPSAA)</strong>\r\n<ol>\r\n<li>Colaborar en equipos de trabajo, asumiendo diferentes roles y responsabilidades.</li>\r\n<li>Autorregular el propio aprendizaje, identificando errores y corrigi&eacute;ndolos en el proceso de dise&ntilde;o.</li>\r\n<li>Desarrollar estrategias de pensamiento cr&iacute;tico y creativo para la resoluci&oacute;n de problemas.</li>\r\n</ol>\r\n</li>\r\n<li><strong>Competencia ciudadana (CC)</strong>\r\n<ul>\r\n<li>Entender los videojuegos como un producto cultural y social con impacto en la vida cotidiana.</li>\r\n<li>Reflexionar sobre el respeto a la propiedad intelectual, las licencias de uso y los derechos de autor.</li>\r\n<li>Valorar el uso &eacute;tico y responsable de la tecnolog&iacute;a.</li>\r\n</ul>\r\n</li>\r\n<li><strong>Competencia emprendedora (CE)</strong>\r\n<ul>\r\n<li>Dise&ntilde;ar, planificar y presentar un producto final (videojuego) aplicando iniciativa, organizaci&oacute;n y creatividad.</li>\r\n<li>Transformar una idea en un proyecto, gestionando recursos, tiempo y roles de equipo.</li>\r\n<li>Aceptar los errores como parte del proceso creativo y de innovaci&oacute;n.</li>\r\n</ul>\r\n</li>\r\n<li><strong>Competencia en conciencia y expresi&oacute;n culturales (CCEC)</strong>\r\n<ul>\r\n<li>Crear productos culturales originales (videojuegos) como medio de expresi&oacute;n personal y colectiva.</li>\r\n<li>Apreciar los videojuegos como manifestaciones culturales y art&iacute;sticas contempor&aacute;neas.</li>\r\n<li>Integrar distintas formas de lenguaje (visual, narrativo, musical) en el proceso creativo.</li>\r\n</ul>\r\n</li>\r\n</ol>\r\n<table style=\"margin-left: auto; margin-right: auto;\" border=\"1\" width=\"100%\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>CCL</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>CP</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>CMCT</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>CD</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>CPSAA</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>CC</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>CE</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>CCEC</p>\r\n</td>\r\n</tr>\r\n<tr style=\"text-align: center;\">\r\n<td>\r\n<p>CE1</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n</tr>\r\n<tr style=\"text-align: center;\">\r\n<td>\r\n<p>CE2</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr style=\"text-align: center;\">\r\n<td>\r\n<p>CE3</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n</tr>\r\n<tr style=\"text-align: center;\">\r\n<td>\r\n<p>CE4</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n<td>\r\n<p>x</p>\r\n</td>\r\n<td>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\">\r\n<p style=\"text-align: center;\">CE5</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>x</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>x</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>x</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>x</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>x</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\">\r\n<p style=\"text-align: center;\">CE6</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>x</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>x</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>x</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>&nbsp;</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>x</p>\r\n</td>\r\n<td style=\"text-align: center;\">\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(3288, 423, 42, '<p data-start=\"289\" data-end=\"660\">Los <strong>saberes b&aacute;sicos</strong> constituyen los aprendizajes imprescindibles que el alumnado debe alcanzar en esta materia, en coherencia con lo dispuesto en la <strong data-start=\"438\" data-end=\"448\">LOMLOE</strong>, el <strong data-start=\"453\" data-end=\"468\">RD 217/2022</strong> y el <strong data-start=\"474\" data-end=\"521\">Decreto 108/2022 de la Comunitat Valenciana</strong>. Se formulan de manera competencial, integrando conocimientos, destrezas y actitudes que garantizan el desarrollo integral del alumnado.</p>\r\n<p data-start=\"662\" data-end=\"784\"><strong>Bloque 1. Creatividad y bases de programaci&oacute;n</strong></p>\r\n<ul>\r\n<li>Reconocer las etapas del proceso de creaci&oacute;n de un videojuego, desde la concepci&oacute;n de la idea hasta su presentaci&oacute;n final.</li>\r\n<li>Formular ideas, objetivos, reglas y guiones b&aacute;sicos para estructurar un videojuego sencillo.</li>\r\n<li>Introducir los conceptos fundamentales de programaci&oacute;n por bloques: eventos, bucles, condiciones y variables simples.</li>\r\n<li>Crear sprites, personajes y escenarios con herramientas digitales de edici&oacute;n gr&aacute;fica (como Piskel o Inkscape).</li>\r\n<li>Aplicar principios b&aacute;sicos de dise&ntilde;o visual (color, forma, coherencia est&eacute;tica) en la creaci&oacute;n de elementos gr&aacute;ficos.</li>\r\n<li>Dise&ntilde;ar y programar un videojuego simple tipo &ldquo;arcade&rdquo; o &ldquo;matamarcianos&rdquo;, aplicando estructuras b&aacute;sicas de control.</li>\r\n<li>Fomentar la creatividad, la resoluci&oacute;n de problemas y el pensamiento l&oacute;gico en el proceso de dise&ntilde;o.</li>\r\n</ul>\r\n<p><strong>Bloque 2. Desarrollo de juegos m&aacute;s complejos</strong></p>\r\n<ul>\r\n<li>Dise&ntilde;ar personajes, niveles y mec&aacute;nicas avanzadas que aumenten la jugabilidad del videojuego.</li>\r\n<li>Implementar f&iacute;sica simple en el juego (gravedad, saltos, colisiones, movimiento de enemigos).</li>\r\n<li>Programar sistemas de puntuaci&oacute;n, vidas y niveles que refuercen la progresi&oacute;n y el reto del jugador.</li>\r\n<li>Gestionar pantallas, men&uacute;s o cambios de nivel, integrando la l&oacute;gica de transici&oacute;n entre escenas.</li>\r\n<li>Aplicar estrategias de depuraci&oacute;n de errores y mejora iterativa del c&oacute;digo.</li>\r\n<li>Documentar el proceso de desarrollo del videojuego, registrando avances y decisiones tomadas.</li>\r\n<li>Valorar la importancia del trabajo met&oacute;dico y la perseverancia en la resoluci&oacute;n de problemas t&eacute;cnicos.</li>\r\n</ul>\r\n<p><strong>Bloque 3. Proyecto colaborativo y ciudadan&iacute;a digital</strong></p>\r\n<ul>\r\n<li>Planificar y desarrollar proyectos colaborativos de creaci&oacute;n de videojuegos, aplicando metodolog&iacute;as &aacute;giles (como Scrum).</li>\r\n<li>Asumir roles y responsabilidades en el equipo (programador, dise&ntilde;ador, coordinador, tester, etc.).</li>\r\n<li>Organizar tareas, tiempos y entregas parciales de forma eficiente.</li>\r\n<li>Elaborar una memoria o documentaci&oacute;n t&eacute;cnica que recoja el proceso, las decisiones y las mejoras del proyecto.</li>\r\n<li>Presentar y exponer p&uacute;blicamente el videojuego final, comunicando los aspectos t&eacute;cnicos y creativos.</li>\r\n<li>Participar en procesos de evaluaci&oacute;n entre iguales y reflexi&oacute;n cr&iacute;tica sobre el trabajo propio y el del grupo.</li>\r\n<li>Aplicar principios de propiedad intelectual, licencias abiertas y uso &eacute;tico de los recursos digitales.</li>\r\n<li>Analizar cr&iacute;ticamente los valores, estereotipos y representaciones presentes en los videojuegos.</li>\r\n<li>Promover la inclusi&oacute;n, igualdad, diversidad cultural y sostenibilidad en el dise&ntilde;o de los videojuegos.</li>\r\n<li>Adoptar h&aacute;bitos de seguridad digital, respeto y convivencia positiva en entornos tecnol&oacute;gicos.</li>\r\n</ul>'),
(3289, 423, 6, '<p>Los saberes b&aacute;sicos se desarrollan a lo largo del curso en tres bloques tem&aacute;ticos que marcan la progresi&oacute;n del aprendizaje, m&aacute;s un bloque transversal que se trabaja de forma continua.</p>\r\n<p><strong>Bloque 1. Creatividad y bases del videojuego (1er trimestre)</strong></p>\r\n<ul>\r\n<li>Iniciaci&oacute;n a la cultura del videojuego y a la &eacute;tica digital.</li>\r\n<li>Ideaci&oacute;n de proyectos sencillos: guion b&aacute;sico, objetivos, reglas y personajes.</li>\r\n<li>Creaci&oacute;n de gr&aacute;ficos simples en dos dimensiones con herramientas digitales (Piskel, Inkscape).</li>\r\n<li>Introducci&oacute;n a la programaci&oacute;n visual (MakeCode Arcade): movimiento, colisiones, marcadores.</li>\r\n<li>Aplicaci&oacute;n de nociones matem&aacute;ticas y f&iacute;sicas b&aacute;sicas (coordenadas, desplazamientos, saltos).</li>\r\n</ul>\r\n<p><strong>Bloque 2. Desarrollo de juegos m&aacute;s completos (2&ordm; trimestre)</strong></p>\r\n<ul>\r\n<li>Ampliaci&oacute;n de mec&aacute;nicas y din&aacute;micas de juego: dificultad, exploraci&oacute;n, recompensas.</li>\r\n<li>Dise&ntilde;o de niveles y escenarios con animaciones y fondos en capas.</li>\r\n<li>Creaci&oacute;n de interfaces comprensibles: men&uacute;s, indicadores, barras de energ&iacute;a.</li>\r\n<li>Programaci&oacute;n intermedia: procedimientos, listas, niveles, estados de partida.</li>\r\n<li>Implementaci&oacute;n de comportamientos autom&aacute;ticos sencillos en personajes/enemigos.</li>\r\n<li>Pruebas de jugabilidad y criterios de mejora.</li>\r\n<li>Introducci&oacute;n a la accesibilidad en videojuegos (colores, contraste, ayudas, niveles de dificultad).</li>\r\n</ul>\r\n<p><strong>Bloque 3. Proyecto colaborativo (3er trimestre)</strong></p>\r\n<ul>\r\n<li>Desarrollo de un videojuego en equipo, asumiendo roles diferenciados.</li>\r\n<li>Planificaci&oacute;n con objetivos, tiempos y reparto de tareas.</li>\r\n<li>Integraci&oacute;n de gr&aacute;ficos, sonidos y programaci&oacute;n en un producto final.</li>\r\n<li>Pruebas, recogida de opiniones y mejora del proyecto.</li>\r\n<li>Elaboraci&oacute;n de memoria breve y presentaci&oacute;n p&uacute;blica del juego (capturas, video, exposici&oacute;n oral).</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p><strong>Contenidos transversales (a lo largo de todo el curso)</strong></p>\r\n<ul>\r\n<li>Competencia digital y seguridad: contrase&ntilde;as, privacidad, copias de seguridad.</li>\r\n<li>Respeto de la propiedad intelectual y uso de recursos con licencias abiertas.</li>\r\n<li>Educaci&oacute;n en valores: igualdad, inclusi&oacute;n, lenguaje no sexista, convivencia positiva.</li>\r\n<li>Comunicaci&oacute;n: redacci&oacute;n clara de guiones y documentos, exposici&oacute;n oral de proyectos.</li>\r\n<li>Sostenibilidad y responsabilidad: reflexi&oacute;n cr&iacute;tica sobre el consumo tecnol&oacute;gico.</li>\r\n</ul>\r\n<p>--- BORRADOR</p>\r\n<p>La materia <strong data-start=\"401\" data-end=\"439\">Dise&ntilde;o y desarrollo de videojuegos</strong> se organiza en tres bloques, uno por trimestre, que permiten una progresi&oacute;n gradual: desde la iniciaci&oacute;n a la creatividad y la programaci&oacute;n b&aacute;sica, hasta el desarrollo de proyectos m&aacute;s complejos y la realizaci&oacute;n de un proyecto colaborativo final.&nbsp;</p>\r\n<table style=\"border-collapse: collapse; width: 100%;\">\r\n<thead>\r\n<tr style=\"background-color: #f2f2f2;\">\r\n<th style=\"border: 1px solid #ccc; padding: 8px; text-align: left;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px; font-weight: 400;\">Trimestre</span></span></th>\r\n<th style=\"border: 1px solid #ccc; padding: 8px; text-align: left;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px; font-weight: 400;\">Contenidos principales</span></span></th>\r\n<th style=\"border: 1px solid #ccc; padding: 8px; text-align: left;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px; font-weight: 400;\">Temporalizaci&oacute;n estimada</span></span></th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">1.&ordm; Trimestre<br />Bloque 1: Creatividad y bases de programaci&oacute;n</span></span></td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">- Introducci&oacute;n al proceso de creaci&oacute;n de un videojuego.<br /> - Boceto y guion sencillo con objetivos, reglas y enemigos.<br /> - Creaci&oacute;n de sprites y escenarios con Piskel/Inkscape.<br /> - Programaci&oacute;n guiada de un videojuego tipo matamarcianos en MakeCode Arcade.<br /> - Conceptos b&aacute;sicos de programaci&oacute;n: bucles, condicionales, variables simples.</span></span></td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">Septiembre &ndash; Diciembre<br />(10-12 semanas)</span></span></td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">2.&ordm; Trimestre<br />Bloque 2: Desarrollo de juegos m&aacute;s complejos</span></span></td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">- Dise&ntilde;o detallado de personajes, niveles y mec&aacute;nicas.<br /> - Programaci&oacute;n de un juego de plataformas o de mazmorras en vista superior.<br /> - Aplicaci&oacute;n de f&iacute;sica sencilla: gravedad, saltos, movimiento de enemigos.<br /> - Gesti&oacute;n de niveles, puntuaci&oacute;n y vidas.<br /> - Trabajo m&aacute;s aut&oacute;nomo en dise&ntilde;o y programaci&oacute;n con m&iacute;nimos obligatorios.</span></span></td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">Enero &ndash; Marzo<br />(10-11 semanas)</span></span></td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">3.&ordm; Trimestre<br />Bloque 3: Proyecto colaborativo</span></span></td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">- Planificaci&oacute;n de un videojuego en grupo.<br /> - Introducci&oacute;n a la metodolog&iacute;a Scrum: roles, tareas, entregas parciales.<br /> - Desarrollo completo del proyecto (dise&ntilde;o, programaci&oacute;n, testeo).<br /> - Documentaci&oacute;n breve del proceso.<br /> - Presentaci&oacute;n y exposici&oacute;n p&uacute;blica de los juegos creados.</span></span></td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">Abril &ndash; Junio<br />(9-10 semanas)</span></span></td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">Transversales<br />(todo el curso)</span></span></td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">- Cultura digital y &eacute;tica: propiedad intelectual, licencias, bienestar digital.<br /> - Educaci&oacute;n en valores: igualdad, inclusi&oacute;n y respeto en los videojuegos.<br /> - Comunicaci&oacute;n y expresi&oacute;n: guiones, documentaci&oacute;n t&eacute;cnica, presentaciones orales.<br /> - Ciudadan&iacute;a digital: convivencia, seguridad y responsabilidad en entornos digitales.</span></span></td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><span style=\"font-family: Arial, Verdana;\"><span style=\"font-size: 17.6px;\">Septiembre &ndash; Junio</span></span></td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(3292, 423, 9, '<p>Los <strong data-start=\"1297\" data-end=\"1324\">criterios de evaluaci&oacute;n</strong> constituyen la referencia principal para valorar el grado de adquisici&oacute;n de los resultados de aprendizaje. Se formulan en coherencia con los <strong data-start=\"1466\" data-end=\"1485\">saberes b&aacute;sicos</strong>, los <strong data-start=\"1491\" data-end=\"1518\">objetivos de la materia</strong> y las <strong data-start=\"1525\" data-end=\"1547\">competencias clave</strong>.</p>\r\n<p>&nbsp;</p>\r\n<table style=\"border-collapse: collapse; width: 100%;\">\r\n<thead>\r\n<tr style=\"background-color: #f2f2f2;\">\r\n<th style=\"border: 1px solid #ccc; padding: 8px; text-align: center;\">CE</th>\r\n<th style=\"border: 1px solid #ccc; padding: 8px; text-align: center;\">Criterios de evaluaci&oacute;n</th>\r\n<th style=\"border: 1px solid #ccc; padding: 8px; text-align: center;\">Competencias clave relacionadas</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><strong>CE1.</strong> Elabora un guion y un boceto de videojuego sencillo, definiendo objetivos, reglas y personajes.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">- Identifica las fases principales de creaci&oacute;n de un videojuego.<br>- Elabora un guion simple con objetivos, reglas y enemigos.<br>- Representa gr&aacute;ficamente sus ideas de forma clara y comprensible.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">CCEC, CD, CPSAA</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><strong>CE2.</strong> Dise&ntilde;a y edita personajes y escenarios digitales con programas de creaci&oacute;n gr&aacute;fica.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">- Crea sprites y escenarios originales con herramientas digitales.<br>- Aplica criterios b&aacute;sicos de dise&ntilde;o gr&aacute;fico (color, forma, proporci&oacute;n).<br>- Integra los recursos gr&aacute;ficos en un prototipo funcional.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">CCEC, CD</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><strong>CE3.</strong> Programa un videojuego sencillo aplicando conceptos b&aacute;sicos de programaci&oacute;n por bloques.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">- Utiliza instrucciones de movimiento, colisiones y puntuaci&oacute;n.<br>- Aplica bucles, condicionales y variables en situaciones pr&aacute;cticas.<br>- Detecta y corrige errores simples en la programaci&oacute;n.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">CMCT, CD, CPSAA</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><strong>CE4.</strong> Desarrolla videojuegos de complejidad media aplicando estructuras de programaci&oacute;n y f&iacute;sica sencilla.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">- Dise&ntilde;a mec&aacute;nicas y niveles m&aacute;s elaborados, aplicando jugabilidad.<br>- Implementa gravedad, saltos y movimiento de enemigos.<br>- Gestiona sistemas de vidas, puntuaci&oacute;n y niveles.<br>- Integra gr&aacute;ficos y sonido de forma coherente.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">CMCT, CD, CCEC, CE</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><strong>CE5.</strong> Planifica y desarrolla un proyecto colaborativo de videojuego integrando todas las fases de creaci&oacute;n.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">- Participa en la planificaci&oacute;n del proyecto, asumiendo roles y tareas.<br>- Colabora en el desarrollo del videojuego respetando las normas del grupo.<br>- Documenta de forma b&aacute;sica el proceso de creaci&oacute;n.<br>- Presenta y defiende p&uacute;blicamente el producto final.<br>- Eval&uacute;a de forma cr&iacute;tica el propio trabajo y el de los compa&ntilde;eros.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">CE, CPSAA, CC, CD</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\"><strong>CE6.</strong> Aplica principios de ciudadan&iacute;a digital, creatividad y respeto en el desarrollo de videojuegos.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">- Respeta las licencias y la propiedad intelectual en el uso de recursos digitales.<br>- Reconoce el valor cultural de los videojuegos como manifestaciones art&iacute;sticas.<br>- Demuestra actitudes inclusivas, igualitarias y de respeto en el trabajo en equipo.<br>- Analiza cr&iacute;ticamente estereotipos y valores en los videojuegos.</td>\r\n<td style=\"border: 1px solid #ccc; padding: 8px;\">CC, CCEC, CD, CPSAA</td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(3293, 423, 10, '<p>La calificaci&oacute;n se basar&aacute; en los <strong data-start=\"338\" data-end=\"403\">criterios de evaluaci&oacute;n definidos en la presente programaci&oacute;n</strong>, en coherencia con los <strong data-start=\"427\" data-end=\"502\">resultados de aprendizaje, las competencias clave y los saberes b&aacute;sicos</strong> de la LOMLOE. El proceso evaluador se desarrollar&aacute; con car&aacute;cter <strong data-start=\"567\" data-end=\"605\">objetivo, transparente y formativo</strong>, de modo que el alumnado conozca en todo momento qu&eacute; se espera de &eacute;l, c&oacute;mo se valoran sus producciones y qu&eacute; posibilidades tiene de mejora.</p>\r\n<p>Las <strong>evidencias de aprendizaje</strong> (proyectos, ejercicios, presentaciones, participaci&oacute;n, retos) se calificar&aacute;n seg&uacute;n la siguiente ponderaci&oacute;n, mediante los instrumentos de evaluaci&oacute;n adecuados:</p>\r\n<ul>\r\n<li>Proyectos y juegos creados: 50 %</li>\r\n<li>Ejercicios individuales y retos: 25 %</li>\r\n<li>Participaci&oacute;n, implicaci&oacute;n y trabajo en equipo: 10 %</li>\r\n<li>Presentaci&oacute;n y defensa de proyectos: 15 %</li>\r\n</ul>\r\n<p>La <strong data-start=\"157\" data-end=\"181\">nota trimestral </strong>se calcula aplicando la ponderaci&oacute;n establecida a cada una de las evidencias de aprendizaje. Cada evidencia se califica en una <strong data-start=\"309\" data-end=\"336\">escala de 1 a 10 puntos</strong>, con un decimal, y la media ponderada de todas ellas determina la calificaci&oacute;n final del trimestre.</p>\r\n<p data-start=\"440\" data-end=\"755\"><strong data-start=\"440\" data-end=\"451\">Ejemplo</strong>: si un alumno obtiene un <strong data-start=\"477\" data-end=\"497\">7,5 en proyectos</strong> (50 %), un <strong data-start=\"509\" data-end=\"530\">6,8 en ejercicios</strong> (25 %), un <strong data-start=\"542\" data-end=\"586\">8,0 en participaci&oacute;n y trabajo en equipo</strong> (10 %) y un <strong data-start=\"599\" data-end=\"638\">7,0 en la presentaci&oacute;n del proyecto</strong> (15 %), la nota trimestral ser&aacute;:&nbsp;(7,5 &times; 0,50) + (6,8 &times; 0,25) + (8,0 &times; 0,10) + (7,0 &times; 0,15) = <strong data-start=\"744\" data-end=\"752\">7,25</strong>.</p>\r\n<p>La <strong data-start=\"1181\" data-end=\"1211\">nota final del curso </strong>ser&aacute;&nbsp;la <strong data-start=\"1218\" data-end=\"1261\">media aritm&eacute;tica de los tres trimestres</strong>.&nbsp;Para poder hacer media, es obligatorio obtener, como m&iacute;nimo un<strong data-start=\"1314\" data-end=\"1341\">&nbsp;4,0 en cada trimestre</strong>.&nbsp;Para <strong data-start=\"1352\" data-end=\"1374\">aprobar la materia</strong>, la nota final del curso debe ser <strong>mayor o igual que&nbsp;5,0</strong>.</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(3295, 64, 40, '<table>\r\n<tbody>\r\n<tr style=\"border: 1px solid black; text-align: justify;\">\r\n<th>Resultados de aprendizaje</th>\r\n<th>Impartidos en el centro</th>\r\n<th>Impartidos en la empresa</th>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<th>RA1: Selecciona las arquitecturas y tecnolog&iacute;as de programaci&oacute;n sobre clientes Web, identificando y analizando las capacidades y caracter&iacute;sticas de cada una.</th>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<th>RA2: Escribe sentencias simples, aplicando la sintaxis del lenguaje y verificando su ejecuci&oacute;n sobre navegadores Web.</th>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<th>RA3: Escribe c&oacute;digo, identificando y aplicando las funcionalidades aportadas por los objetos predefinidos del lenguaje.</th>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<th>RA4: Programa c&oacute;digo para clientes Web analizando y utilizando estructuras definidas por el usuario.</th>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<th>RA5: Desarrolla aplicaciones Web interactivas integrando mecanismos de manejo de eventos.</th>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr style=\"text-align: justify;\">\r\n<th>RA6: Desarrolla aplicaciones web analizando y aplicando las caracter&iacute;sticas del modelo de objetos del documento.</th>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<th style=\"text-align: justify;\">RA7: Desarrolla aplicaciones Web din&aacute;micas, reconociendo y aplicando mecanismos de comunicaci&oacute;n as&iacute;ncrona entre cliente y servidor.</th>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(3296, 67, 25, '<p>Las competencias b&aacute;sicas o competencias clave acompa&ntilde;an al alumnado <strong>durante su etapa de desarrollo educativo</strong>, y tambi&eacute;n posteriormente <strong>a lo largo de toda su vida, aprendizaje permanente</strong>, desarrollo integral y arm&oacute;nico de la persona; se inician en la Educaci&oacute;n Infantil, se desarrollan en la Educaci&oacute;n Primaria y se alcanzan su manejo en la Educaci&oacute;n Secundaria con la obtenci&oacute;n del Graduado, si bien en el Bachiller y la <strong>Formaci&oacute;n Profesional se refuerzan, consolidan y se ampl&iacute;an.</strong></p>\r\n<p>Existen tres tipos de competencias en la Formaci&oacute;n Profesional, seg&uacute;n el&nbsp;<strong>art&iacute;culo 7 del Real Decreto 659/2023</strong>. Cada una de ellas tiene un objetivo concreto que ayuda a los alumnos a estar preparados para el mundo laboral:&nbsp;</p>\r\n<ul class=\"wp-block-list\">\r\n<li><strong>Competencia general</strong>:&nbsp;describe las principales funciones que una persona debe saber hacer en su profesi&oacute;n.&nbsp;</li>\r\n<li><strong>Competencias profesionales, personales y sociales</strong>:&nbsp;se refieren a los conocimientos y habilidades que permiten a los estudiantes ser m&aacute;s aut&oacute;nomos y responsables en su trabajo</li>\r\n<li><strong>Cualificaciones profesionales y unidades de competencia</strong>:&nbsp;se refieren a las capacidades necesarias para desempe&ntilde;ar bien un trabajo espec&iacute;fico.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3297, 64, 25, '<p>Las competencias b&aacute;sicas o competencias clave acompa&ntilde;an al alumnado&nbsp;<strong>durante su etapa de desarrollo educativo</strong>, y tambi&eacute;n posteriormente&nbsp;<strong>a lo largo de toda su vida, aprendizaje permanente</strong>, desarrollo integral y arm&oacute;nico de la persona; se inician en la Educaci&oacute;n Infantil, se desarrollan en la Educaci&oacute;n Primaria y se alcanzan su manejo en la Educaci&oacute;n Secundaria con la obtenci&oacute;n del Graduado, si bien en el Bachiller y la&nbsp;<strong>Formaci&oacute;n Profesional se refuerzan, consolidan y se ampl&iacute;an.</strong></p>\r\n<p>Existen tres tipos de competencias en la Formaci&oacute;n Profesional, seg&uacute;n el&nbsp;<strong>art&iacute;culo 7 del&nbsp;Real Decreto 659/2023</strong>. Cada una de ellas tiene un objetivo concreto que ayuda a los alumnos a estar preparados para el mundo laboral:&nbsp;</p>\r\n<ul class=\"wp-block-list\">\r\n<li><strong>Competencia general</strong>:&nbsp;describe las principales funciones que una persona debe saber hacer en su profesi&oacute;n.&nbsp;</li>\r\n<li><strong>Competencias profesionales, personales y sociales</strong>:&nbsp;se refieren a los conocimientos y habilidades que permiten a los estudiantes ser m&aacute;s aut&oacute;nomos y responsables en su trabajo</li>\r\n<li><strong>Cualificaciones profesionales y unidades de competencia</strong>:&nbsp;se refieren a las capacidades necesarias para desempe&ntilde;ar bien un trabajo espec&iacute;fico.</li>\r\n</ul>\r\n<p>&nbsp;</p>'),
(3298, 417, 25, '<p>Las competencias b&aacute;sicas o competencias clave acompa&ntilde;an al alumnado&nbsp;<strong>durante su etapa de desarrollo educativo</strong>, y tambi&eacute;n posteriormente&nbsp;<strong>a lo largo de toda su vida, aprendizaje permanente</strong>, desarrollo integral y arm&oacute;nico de la persona; se inician en la Educaci&oacute;n Infantil, se desarrollan en la Educaci&oacute;n Primaria y se alcanzan su manejo en la Educaci&oacute;n Secundaria con la obtenci&oacute;n del Graduado, si bien en el Bachiller y la&nbsp;<strong>Formaci&oacute;n Profesional se refuerzan, consolidan y se ampl&iacute;an.</strong></p>\r\n<p>Existen tres tipos de competencias en la Formaci&oacute;n Profesional, seg&uacute;n el&nbsp;<strong>art&iacute;culo 7 del&nbsp;Real Decreto 659/2023</strong>. Cada una de ellas tiene un objetivo concreto que ayuda a los alumnos a estar preparados para el mundo laboral:&nbsp;</p>\r\n<ul class=\"wp-block-list\">\r\n<li><strong>Competencia general</strong>:&nbsp;describe las principales funciones que una persona debe saber hacer en su profesi&oacute;n.&nbsp;</li>\r\n<li><strong>Competencias profesionales, personales y sociales</strong>:&nbsp;se refieren a los conocimientos y habilidades que permiten a los estudiantes ser m&aacute;s aut&oacute;nomos y responsables en su trabajo</li>\r\n<li><strong>Cualificaciones profesionales y unidades de competencia</strong>:&nbsp;se refieren a las capacidades necesarias para desempe&ntilde;ar bien un trabajo espec&iacute;fico.</li>\r\n</ul>\r\n<p>&nbsp;</p>'),
(3301, 417, 42, '<p><mark>Voy por aqu&iacute;</mark></p>'),
(3302, 282, 23, '<p>En las diferentes situaciones de aprendizaje que se plantean, los/as profesores/as del m&oacute;dulo utilizar&aacute;n alguno o todos los instrumentos de recogida y registro de informaci&oacute;n que aqu&iacute; se recogen:</p>\r\n<ul>\r\n<li>cuestionarios para recoger informaci&oacute;n sobre el nivel de satisfacci&oacute;n del alumnado, dificultades o conocimientos previos.</li>\r\n<li>ex&aacute;menes escritos que recojan conocimientos te&oacute;rico/pr&aacute;cticos. Con preguntas tipo test o desarrollo.</li>\r\n<li>pruebas pr&aacute;cticas en las que el alumnado demuestra su capacidad para realizar diferentes tareaas en equipos reales o m&aacute;quinas virtuales.</li>\r\n<li>portafolio del/la alumno/a en el cual recoja evidencias del trabajo desarrollado a lo largo del m&oacute;dulo.</li>\r\n<li>res&uacute;mnes de los bloques de teror&iacute;a o esquemas que puedan servir como repaso de los conceptos que se consideren m&aacute;s importantes. A veces, se realizar&aacute;n a mano y se entregar&aacute;n en papel.</li>\r\n<li>r&uacute;bricas que nos ayuden a evaluar de manera objetiva aspectos espec&iacute;ficos de una prueba.</li>\r\n<li>observaci&oacute;n sistem&aacute;tica d elos comportamientos, habilidades y actitudes durante el trabajo en clase.</li>\r\n<li>tutor&iacute;as colectivas o individualizadas para conocer el nivel de comprensi&oacute;n, detectar dudas o fallos conceptuales.</li>\r\n<li>registros anect&oacute;ditos con observaciones relevantes del docente sobre conductas, dificultades, logros, incidencias, etc.</li>\r\n<li>memorias o documentaci&oacute;n t&eacute;cnica escrita por el/la alumno/a tras&nbsp;una pr&aacute;ctica o proyecto.</li>\r\n<li>resoluci&oacute;n de retos propuetos donde el docente crear unas situaciones que el alumno debe analizar y resolver.</li>\r\n<li>evaluaci&oacute;n entre iguales: es una estrategia que permite al alumnado observar, valorar y aprender del trabajo de sus compa&ntilde;eros. No solo aporta informaci&oacute;n valiosa al docente, sino que tambi&eacute;n promueve la&nbsp;<strong data-start=\"423\" data-end=\"484\">autoevaluaci&oacute;n, la responsabilidad y la reflexi&oacute;n cr&iacute;tica.</strong></li>\r\n</ul>\r\n<p>&nbsp;</p>'),
(3303, 406, 1, '<p>La siguiente programaci&oacute;n did&aacute;ctica tratar&aacute; de establecer los conceptos b&aacute;sicos te&oacute;ricos y pr&aacute;cticos, as&iacute; como los objetivos que se pretenden alcanzar en el desarrollo del m&oacute;dulo de Digitalizaci&oacute;n que se imparte en el segundo curso del Ciclo Formativo de grado medio de Sistemas Microinform&aacute;ticos y Redes (SMR). El citado m&oacute;dulo tiene una duraci&oacute;n total de 32 horas</p>'),
(3306, 406, 25, '<p style=\"text-align: justify;\">Las competencias b&aacute;sicas o competencias clave acompa&ntilde;an al alumnado durante su etapa de desarrollo educativo, y tambi&eacute;n posteriormente a lo largo de toda su vida, aprendizaje permanente, desarrollo integral y arm&oacute;nico de la persona; se inician en la Educaci&oacute;n Infantil, se desarrollan en la Educaci&oacute;n Primaria y se alcanzan su manejo en la Educaci&oacute;n Secundaria con la obtenci&oacute;n del Graduado, si bien en el Bachiller y la Formaci&oacute;n Profesional se refuerzan, consolidan y se ampl&iacute;an.</p>\r\n<p style=\"text-align: justify;\"><br />Las competencias clave para el Sistema Educativo Espa&ntilde;ol son (Orden ECD/65/2015) las<br />siguientes:<br />1. Comunicaci&oacute;n ling&uuml;&iacute;stica.<br />2. Competencia matem&aacute;tica y competencias b&aacute;sicas en ciencia y tecnolog&iacute;a.<br />3. Competencia digital.<br />4. Aprender a aprender.<br />5. Competencias sociales y c&iacute;vicas.<br />6. Sentido de iniciativa y esp&iacute;ritu emprendedor.<br />7. Conciencia y expresiones culturales.</p>\r\n<p style=\"text-align: justify;\"><br />Desde este m&oacute;dulo formativo se contribuir&aacute; a afianzar dichas competencias a lo largo de su formaci&oacute;n. Por otra parte, este m&oacute;dulo desarrolla competencias profesionales, personales y sociales espec&iacute;ficas de dicha formaci&oacute;n, de forma que, para su adquisici&oacute;n el alumnado deber&aacute; poner en pr&aacute;ctica a su vez las competencias clave adquiridas en las etapas de educaci&oacute;n obligatoria</p>'),
(3307, 406, 41, '<p>Las <strong data-start=\"2629\" data-end=\"2676\">competencias en el m&oacute;dulo de digitalizaci&oacute;n</strong> se centran en que el alumno de Grado Medio entienda el contexto de transformaci&oacute;n digital, conozca las tecnolog&iacute;as que lo impulsan, y sea capaz de <strong data-start=\"2824\" data-end=\"2878\">aplicar soluciones digitales b&aacute;sicas y sostenibles</strong> en el sector productivo de la inform&aacute;tica y las redes.</p>'),
(3310, 406, 6, '<p style=\"text-align: justify;\">La temporalizaci&oacute;n del presente m&oacute;dulo se ha establecido en base a una carga lectiva horaria semanal de 1 hora, lo que supone una carga total anual de 34 horas. La secuencia prevista de los contenidos corresponde a lo indicado en el EFD/659/2024. Por tanto, la ponderaci&oacute;n de peso de los resultados de aprendizaje, y la distribuci&oacute;n de las horas en unidades did&aacute;cticas y evaluaciones, incluido el tiempo dedicado a pruebas, correcci&oacute;n de actividades y actividades extraescolares, etc.., es la siguiente:</p>\r\n<p style=\"text-align: justify;\">UD0.- INTRODUCCI&Oacute;N&nbsp; &nbsp; &nbsp;1 hora<br />UD1.- ECONOM&Iacute;A LINEAL Y CIRCULAR&nbsp; &nbsp; &nbsp;5 horas&nbsp;&nbsp;<br />UD2.- LA 4&ordf; REVOLUCI&Oacute;N INDUSTRIAL&nbsp; &nbsp; &nbsp;5 horas<br />UD3.- CLOUD Y SISTEMAS CONECTADOS&nbsp; &nbsp; &nbsp;5 horas<br />UD4.- CARACTER&Iacute;STICAS DE LOS SISTEMAS DE PRODUCCI&Oacute;N 5 horas<br />UD5.- PLAN DE TRANSFORMACI&Oacute;N&nbsp; &nbsp; &nbsp;13 horas</p>'),
(3311, 406, 7, '<p>El m&eacute;todo que se seguir&aacute; para el desarrollo de las clases ser&aacute; el siguiente:</p>\r\n<p>Exposici&oacute;n de conceptos te&oacute;ricos en clase a partir de los apuntes de la asignatura y los materiales complementarios que el profesor estime convenientes para una mejor comprensi&oacute;n de los contenidos.</p>\r\n<p>Planteamiento de ejercicios y actividades en el aula de aquellos temas que lo permitan, resolvi&eacute;ndose aquellos que se estime oportuno.</p>\r\n<p>Presentaci&oacute;n en clase de las diversas pr&aacute;cticas a realizar y desarrollo en la misma de todas aquellas que el equipamiento permita.</p>\r\n<p>Realizaci&oacute;n de trabajos y exposiciones por parte del alumnado, de aquellos temas que se brinden a ello o que se propongan directamente por el profesor, con lo que se conseguir&aacute; una activa participaci&oacute;n y un mayor acercamiento a los conceptos y contenidos del modulo.</p>\r\n<p>En una etapa inicial del curso, se seguir&aacute; el m&eacute;todo tradicional de exposici&oacute;n por parte del profesor, con el fin de explicar los conceptos b&aacute;sicos que &eacute;ste m&oacute;dulo necesita para poder arrancar. Tan pronto como sea posible, la metodolog&iacute;a pasar&aacute; a ser fundamentalmente procedimental, con la realizaci&oacute;n de pr&aacute;cticas, invitando al alumno, bien individualmente o bien en grupo, a que exponga su planteamiento ante sus compa&ntilde;eros, para efectuar los pertinentes comentarios, intercambio de pareceres y discusi&oacute;n de las soluciones propuestas.</p>\r\n<p>En la medida de lo posible se tendr&aacute; una atenci&oacute;n individualizada por parte de los profesores a cada alumno o grupo de alumnos. Se fomentar&aacute; que cada uno plantee sus dudas o problemas sobre el ejercicio. Finalmente se comentar&aacute;n las posibles soluciones, as&iacute; como los fallos y errores que suelen cometerse de forma m&aacute;s habitual</p>'),
(3313, 406, 23, '<p data-start=\"581\" data-end=\"736\">A continuaci&oacute;n pasamos a detallar los instrumentos de evaluaci&oacute;n.</p>\r\n<ol data-start=\"738\" data-end=\"2675\">\r\n<li data-start=\"738\" data-end=\"979\">\r\n<p data-start=\"741\" data-end=\"763\"><strong data-start=\"741\" data-end=\"761\">Pruebas escritas</strong></p>\r\n<ul data-start=\"767\" data-end=\"979\">\r\n<li data-start=\"767\" data-end=\"979\">\r\n<p data-start=\"769\" data-end=\"979\">Cuestionarios tipo test, de preguntas cortas, de desarrollo, etc., para comprobar los conocimientos te&oacute;ricos sobre digitalizaci&oacute;n, herramientas digitales, conceptos como econom&iacute;a circular, cloud computing, etc.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"981\" data-end=\"1269\">\r\n<p data-start=\"984\" data-end=\"1008\"><strong data-start=\"984\" data-end=\"1006\">Trabajos pr&aacute;cticos</strong></p>\r\n<ul data-start=\"1012\" data-end=\"1269\">\r\n<li data-start=\"1012\" data-end=\"1136\">\r\n<p data-start=\"1014\" data-end=\"1136\">Proyectos o estudios de caso donde el alumno elabore un plan de transformaci&oacute;n digital para una empresa ficticia o real.</p>\r\n</li>\r\n<li data-start=\"1140\" data-end=\"1269\">\r\n<p data-start=\"1142\" data-end=\"1269\">Ejercicios de aplicaci&oacute;n pr&aacute;ctica de tecnolog&iacute;as digitales (uso de plataformas en la nube, herramientas de colaboraci&oacute;n, etc.).</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1271\" data-end=\"1540\">\r\n<p data-start=\"1274\" data-end=\"1316\"><strong data-start=\"1274\" data-end=\"1314\">Actividades en clase / participaci&oacute;n</strong></p>\r\n<ul data-start=\"1320\" data-end=\"1540\">\r\n<li data-start=\"1320\" data-end=\"1413\">\r\n<p data-start=\"1322\" data-end=\"1413\">Resoluci&oacute;n de problemas en grupo, debates, participaci&oacute;n oral, actividades colaborativas.</p>\r\n</li>\r\n<li data-start=\"1417\" data-end=\"1540\">\r\n<p data-start=\"1419\" data-end=\"1540\">Actividades de an&aacute;lisis de casos actuales en el sector productivo (c&oacute;mo digitalizaci&oacute;n ha cambiado procesos productivos).</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1542\" data-end=\"1679\">\r\n<p data-start=\"1545\" data-end=\"1586\"><strong data-start=\"1545\" data-end=\"1584\">Portfolios / cuaderno de evidencias</strong></p>\r\n<ul data-start=\"1590\" data-end=\"1679\">\r\n<li data-start=\"1590\" data-end=\"1679\">\r\n<p data-start=\"1592\" data-end=\"1679\">Recogida de trabajos realizados, reflexiones sobre lo aprendido, autoevaluaciones, etc.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1681\" data-end=\"1898\">\r\n<p data-start=\"1684\" data-end=\"1717\"><strong data-start=\"1684\" data-end=\"1715\">Proyectos finales de m&oacute;dulo</strong></p>\r\n<ul data-start=\"1721\" data-end=\"1898\">\r\n<li data-start=\"1721\" data-end=\"1898\">\r\n<p data-start=\"1723\" data-end=\"1898\">Integraci&oacute;n de varios conceptos y competencias: por ejemplo un proyecto donde se apliquen tecnolog&iacute;as, se haga un plan, se consideren costes, impacto en recursos humanos, etc.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1900\" data-end=\"2094\">\r\n<p data-start=\"1903\" data-end=\"1945\"><strong data-start=\"1903\" data-end=\"1943\">Presentaciones orales / exposiciones</strong></p>\r\n<ul data-start=\"1949\" data-end=\"2094\">\r\n<li data-start=\"1949\" data-end=\"2094\">\r\n<p data-start=\"1951\" data-end=\"2094\">Exposici&oacute;n del proyecto final o de los trabajos pr&aacute;cticos ante el profesor o compa&ntilde;eros, defendiendo las decisiones tomadas en el plan digital.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"2096\" data-end=\"2240\">\r\n<p data-start=\"2099\" data-end=\"2140\"><strong data-start=\"2099\" data-end=\"2138\">Tareas online / pr&aacute;cticas digitales</strong></p>\r\n<ul data-start=\"2144\" data-end=\"2240\">\r\n<li data-start=\"2144\" data-end=\"2240\">\r\n<p data-start=\"2146\" data-end=\"2240\">Uso de plataformas digitales para realizar actividades, quizzes, foros, autoevaluaciones, etc.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"2242\" data-end=\"2384\">\r\n<p data-start=\"2245\" data-end=\"2280\"><strong data-start=\"2245\" data-end=\"2278\">Autoevaluaci&oacute;n y coevaluaci&oacute;n</strong></p>\r\n<ul data-start=\"2284\" data-end=\"2384\">\r\n<li data-start=\"2284\" data-end=\"2384\">\r\n<p data-start=\"2286\" data-end=\"2384\">Reflexi&oacute;n del alumno sobre su progreso y evaluaci&oacute;n mutua entre alumnos en trabajos colaborativos.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"2386\" data-end=\"2550\">\r\n<p data-start=\"2389\" data-end=\"2414\"><strong data-start=\"2389\" data-end=\"2412\">Evaluaci&oacute;n continua</strong></p>\r\n<ul data-start=\"2418\" data-end=\"2550\">\r\n<li data-start=\"2418\" data-end=\"2550\">\r\n<p data-start=\"2420\" data-end=\"2550\">Seguimiento a lo largo del curso, con entregas parciales de actividades, participaci&oacute;n, trabajos, etc., que suman a la nota final.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ol>'),
(3314, 406, 9, '<p>UNIDAD DID&Aacute;CTICA 1: ECONOM&Iacute;A LINEAL Y CIRCULAR</p>\r\n<p>RA1 Establece las diferencias entre la Econom&iacute;a Lineal (EL) y la Econom&iacute;a Circular (EC), identificando las ventajas de la EC en relaci&oacute;n con el medioambiente y el desarrollo sostenible <br />CE <br />A. Se han identificado las etapas &laquo;t&iacute;picas&raquo; de los modelos basados en EL y modelos basados en EC. <br />B. Se ha analizado cada etapa de los modelos EL y EC y su repercusi&oacute;n en el medio ambiente. <br />C. Se ha valorado la importancia del reciclaje en los modelos econ&oacute;micos. <br />D. Se han identificado procesos reales basados en EL. <br />E. Se han identificado procesos reales basados en EC. <br />F. Se han comparado los modelos anteriores en relaci&oacute;n con su impacto medioambiental y los ODS (Objetivos de Desarrollo Sostenible).</p>\r\n<p>UNIDAD DID&Aacute;CTICA 2: LA 4.&ordf; REVOLUCI&Oacute;N INDUSTRIAL</p>\r\n<p>RA2 Caracteriza los principales aspectos de la 4.&ordf; Revoluci&oacute;n Industrial indicando los cambios y las ventajas que se producen tanto desde el punto de vista de los clientes como de las empresas <br />CE <br />A. Se han relacionado los sistemas ciberf&iacute;sicos con la evoluci&oacute;n industrial. <br />B. Se ha analizado el cambio producido en los sistemas automatizados. <br />C. Se ha descrito la combinaci&oacute;n de la parte f&iacute;sica de las industrias con el software, IoT (Internet de las cosas), comunicaciones, entre otros. <br />D. Se ha descrito la interrelaci&oacute;n entre el mundo f&iacute;sico y el virtual. <br />E. Se ha relacionado la migraci&oacute;n a entornos 4.0 con la mejora de los resultados de las empresas. <br />F. Se han identificado las ventajas para clientes y empresas.</p>\r\n<p>UNIDAD DID&Aacute;CTICA 3: CLOUD Y SISTEMAS CONECTADOS</p>\r\n<p>RA3 Identifica la estructura de los sistemas basados en cloud/nube describiendo su tipolog&iacute;a y campo de aplicaci&oacute;n <br />CE <br />A. Se han identificado los diferentes niveles de la cloud/nube. <br />B. Se han identificado las principales funciones de la cloud/nube (procesamiento de datos, intercambio de informaci&oacute;n, ejecuci&oacute;n de aplicaciones, entre otros). <br />C. Se ha descrito el concepto de edge computing y su relaci&oacute;n con la cloud/nube. <br />D. Se han definido los conceptos de fog y mist y sus zonas de aplicaci&oacute;n en el conjunto. <br />E. Se han identificado las ventajas que proporciona la utilizaci&oacute;n de la cloud/nube en los sistemas conectados.</p>\r\n<p>UNIDAD DID&Aacute;CTICA 4: CARACTER&Iacute;STICAS DE LOS SISTEMAS DE PRODUCCI&Oacute;N</p>\r\n<p>RA4 Compara los sistemas de producci&oacute;n/prestaci&oacute;n de servicios digitalizados con los sistemas cl&aacute;sicos identificando las mejoras introducidas <br />CE <br />A. Se han identificado las tecnolog&iacute;as habilitadoras (THD) actuales que definen un sistema digitalizado. <br />B. Se han descrito las caracter&iacute;sticas y aplicaciones del IoT, IA (Inteligencia Artificial), Big Data, tecnolog&iacute;a 5G, la rob&oacute;tica colaborativa, Blockchain, Ciberseguridad, fabricaci&oacute;n aditiva, realidad virtual, gemelos digitales, entre otras. <br />C. Se ha descrito la contribuci&oacute;n de las THD a la mejora de la productividad y la eficiencia de los sistemas productivos o de prestaci&oacute;n de servicios. <br />D. Se ha relacionado la alineaci&oacute;n entre las unidades funcionales de las empresas que conforman el sistema y el objetivo del mismo. <br />E. Se ha relacionado la implantaci&oacute;n de las tecnolog&iacute;as habilitadoras (sens&oacute;rica, tratamiento de datos, automatizaci&oacute;n y comunicaciones, entre otras) con la reducci&oacute;n de costes y la mejora de la competitividad. <br />F. Se han relacionado las tecnolog&iacute;as disruptivas con aplicaciones concretas en los sectores productivos. <br />G. Se han definido los sistemas de almacenamiento de datos no convencionales y el acceso a los mismos desde cada unidad. <br />H. Se han descrito las mejoras producidas en el sistema y en cada una de sus etapas.</p>\r\n<p>UNIDAD DID&Aacute;CTICA 5: PLAN DE TRANSFORMACI&Oacute;N</p>\r\n<p>RA5 Elabora un plan de transformaci&oacute;n de una empresa cl&aacute;sica del sector en el que se enmarca el t&iacute;tulo, basada en una EL, al concepto 4.0, determinando los cambios a introducir en las principales fases del sistema e indicando c&oacute;mo afectar&iacute;a a los recursos humanos <br />CE <br />A. Se ha definido a nivel de bloques el diagrama de funcionamiento de la empresa cl&aacute;sica. <br />B. Se han identificado las etapas susceptibles de ser digitalizadas. <br />C. Se han definido las tecnolog&iacute;as implicadas en cada una de las etapas. <br />D. Se ha establecido la conexi&oacute;n de las etapas digitalizadas con el resto del sistema. <br />E. Se ha elaborado un diagrama de bloques del sistema digitalizado. <br />F. Se ha elaborado un informe de viabilidad y de las mejoras introducidas. <br />G. Se ha analizado la mejora en la producci&oacute;n y gesti&oacute;n de residuos, entre otras. <br />H. Se ha elaborado un documento con la secuencia del plan de transformaci&oacute;n y los recursos empleados.</p>'),
(3315, 406, 10, '<p>Al final de cada unidad did&aacute;ctica, se realizar&aacute; una prueba de conocimientos te&oacute;rico/pr&aacute;cticos para todos los alumnos, siendo necesario obtener un m&iacute;nimo de 5 puntos para poder superar la unidad.</p>\r\n<p>Igualmente, en cada unidad se propondr&aacute;n actividades que los alumnos deben realizar, quedando reflejadas en una memoria (para cada actividad) que deber&aacute;n presentar en formato electr&oacute;nico al profesor para su revisi&oacute;n. En estas se valorar&aacute; tanto la correcci&oacute;n, como la presentaci&oacute;n y la documentaci&oacute;n. No podr&aacute; superarse la evaluaci&oacute;n si no se obtiene como m&iacute;nimo 5 puntos en el apartado de actividades.</p>\r\n<p>La calificaci&oacute;n de cada uno de las tres evaluaciones estar&aacute; compuesta por la nota de las pruebas te&oacute;rico/pr&aacute;cticas, con una ponderaci&oacute;n del 60%, y la nota de las actividades, con una ponderaci&oacute;n del 40%.</p>\r\n<p>Nota UD 1 = ( examen * 50% ) + ( actividades * 50% )&nbsp; &nbsp;--&gt; 20% del total final<br />Nota UD 2 = ( examen * 50% ) + ( actividades * 50% )&nbsp; &nbsp;--&gt; 20% del total final<br />Nota UD 3 = ( examen * 50% ) + ( actividades * 50% )&nbsp; &nbsp;--&gt; 20% del total final<br />Nota UD 4 = ( examen * 50% ) + ( actividades * 50% )&nbsp; &nbsp;--&gt; 20% del total final<br />Nota UD 5 = ( examen * 50% ) + ( actividades * 50% ) &nbsp; --&gt; 20% del total final</p>\r\n<p>La copia en ex&aacute;menes y/o plagio de trabajos u otras actividades propuestas supondr&aacute; la no superaci&oacute;n de dicho examen, trabajo o actividad con una calificaci&oacute;n de un \"0\". La reiteraci&oacute;n en la copia o plagio, al menos dos veces, supondr&aacute; el suspenso autom&aacute;tico e inmediato en la correspondiente convocatoria con una calificaci&oacute;n de un \"1\".</p>\r\n<p>La nota final del m&oacute;dulo se obtendr&aacute; considerando las notas de los bloques tem&aacute;ticos y otros aspectos, como el comportamiento en clase, la asistencia, participaci&oacute;n, integraci&oacute;n en grupos de trabajo... se valorar&aacute; en un 10% de la nota final.</p>\r\n<p>Por otra parte, actitudes como utilizar el ordenador para jugar, instalar software no autorizado, cambiar la configuraci&oacute;n de los equipos (fondo, salvapantallas, etc.), actitudes que impidan el funcionamiento de clase con interrupciones continuas, no traer material o no realizar entregas de determinadas actividades/ejercicios, ser&aacute; tenido en cuenta y penalizado, ya bien sea con la p&eacute;rdida de un punto completo en la evaluaci&oacute;n o mediante la p&eacute;rdida parcial de dicho punto.</p>'),
(3316, 417, 6, '<p style=\"text-align: justify;\">La temporizaci&oacute;n de los contenidos para el m&oacute;dulo optativo de Introducci&oacute;n a la nube p&uacute;blica es:</p>\r\n<p style=\"text-align: justify;\">Primera evaluaci&oacute;n</p>\r\n<ul>\r\n<li><strong>Unidad 1: Conceptos b&aacute;sicos sistemas Cloud</strong>:</li>\r\n<li><strong>Unidad 2: AWS. Infraestructura, seguridad y gesti&oacute;n de redes</strong>:&nbsp;</li>\r\n<li><strong>Unidad 3: AWS. Computaci&oacute;n y automatizaci&oacute;n escalado</strong>:&nbsp;</li>\r\n</ul>\r\n<p>Segunda evaluaci&oacute;n</p>\r\n<ul>\r\n<li><strong>Unidad 4: AWS. Almacenamiento y BBDD</strong>:&nbsp;</li>\r\n<li><strong>Unidad 5: AWS. Optimizaci&oacute;n y monitorizaci&oacute;n de recursos</strong>:&nbsp;</li>\r\n<li><strong>Unidad 6: Introducci&oacute;n a Azure. Caracter&iacute;sticas diferenciales</strong>:&nbsp;</li>\r\n</ul>\r\n<p>Tercera evaluaci&oacute;n</p>\r\n<ul>\r\n<li><strong>Unidad 7: Valoraci&oacute;n de proveedores alternativos</strong>:&nbsp;</li>\r\n<li><strong>Unidad 8: Proyecto despliegue</strong>:&nbsp;</li>\r\n</ul>'),
(3317, 417, 7, '<p>El m&eacute;todo que se seguir&aacute; para el desarrollo de las clases ser&aacute; el siguiente:</p>\r\n<ol>\r\n<li>Exposici&oacute;n de conceptos te&oacute;ricos en clase a partir de los apuntes y los materiales complementarios que el profesor estime convenientes para una mejor comprensi&oacute;n de los contenidos.</li>\r\n<li>Planteamiento de ejercicios y actividades en el aula de aquellos temas que lo permitan, resolvi&eacute;ndose aquellos que se estime oportuno.</li>\r\n<li>Presentaci&oacute;n en clase de las diversas pr&aacute;cticas a realizar y desarrollo en la misma de todas aquellas que el equipamiento permita.</li>\r\n<li>Realizaci&oacute;n de trabajos y exposiciones por parte del alumnado, de aquellos temas que se brinden a ello o que se propongan directamente por el profesor, con lo que se conseguir&aacute; una activa participaci&oacute;n y un mayor acercamiento a los conceptos y contenidos del modulo.</li>\r\n</ol>\r\n<p style=\"text-align: justify;\"><br />Tan pronto como sea posible, la metodolog&iacute;a pasar&aacute; a ser fundamentalmente procedimental, con la realizaci&oacute;n de pr&aacute;cticas, invitando al alumno, bien individualmente o bien en grupo, a que resuelva retos cuya resoluci&oacute;n debe exponer ante sus compa&ntilde;eros, para efectuar los pertinentes comentarios, intercambio de pareceres y discusi&oacute;n de las soluciones propuestas.</p>\r\n<p style=\"text-align: justify;\"><br />En la medida de lo posible se tendr&aacute; una atenci&oacute;n individualizada por parte de los profesores a cada alumno o grupo de alumnos. Se fomentar&aacute; que cada uno plantee sus dudas o problemas sobre el ejercicio. Finalmente se comentar&aacute;n las posibles soluciones, as&iacute; como los fallos y errores que suelen cometerse de forma m&aacute;s habitual.&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>'),
(3319, 417, 23, '<p>A continuaci&oacute;n se exponen los criterios de evaluaci&oacute;n y calificaci&oacute;n, as&iacute; como las&nbsp;actividades propuestas a realizar como refuerzo o ampliaci&oacute;n.</p>\r\n<p>Para la evaluaci&oacute;n en s&iacute;, se llevar&aacute; a cabo la correcci&oacute;n de los trabajos realizados por los alumnos. Se valorar&aacute; la presentaci&oacute;n, la expresi&oacute;n, la ortograf&iacute;a y la puntualidad en la entrega.</p>\r\n<p>Se realizar&aacute; un examen trimestral de contenido fundamentalmente pr&aacute;ctico, para los temas que correspondan a cada trimestre seg&uacute;n la secuenciaci&oacute;n anteriormente expuesta. Si el profesor/a lo considera oportuno, podr&aacute; sustituir el examen de un bloque por alguna/s pr&aacute;ctica/s que permita valorar la adquisici&oacute;n de los conocimientos y destrezas de dicho bloque por parte del alumno.</p>\r\n<p>Para superar cada evaluaci&oacute;n deber&aacute;n cumplirse los m&iacute;nimos establecidos en los criterios de calificaci&oacute;n, expuestos m&aacute;s adelante en esta secci&oacute;n.</p>'),
(3320, 417, 9, '<p>RA1. Comprende los fundamentos de la computaci&oacute;n en la nube, sus ventajas frente a sistemas tradicionales, el marco de adopci&oacute;n, los principios de migraci&oacute;n y los aspectos clave de facturaci&oacute;n, como estimaci&oacute;n y optimizaci&oacute;n de costos.</p>\r\n<ul>\r\n<li>Se ha comprendido los conceptos fundamentales de la computaci&oacute;n en la nube.</li>\r\n<li>Se ha demostrado la capacidad para explicar las ventajas de la nube frente a sistemas tradicionales.</li>\r\n<li>Se ha participado en actividades relacionadas con el ecosistema de servicios en la nube.</li>\r\n<li>Se han identificado los principios b&aacute;sicos de la facturaci&oacute;n y costos en la nube.</li>\r\n<li>Se ha hecho uso correcto de herramientas para estimar y gestionar presupuestos.</li>\r\n<li>Se ha participado en actividades pr&aacute;cticas sobre gesti&oacute;n de costos.</li>\r\n</ul>\r\n<p>RA2. Identifica los componentes clave de la infraestructura global de la nube, diferenciando servicios principales, regiones, zonas de disponibilidad y aplicando medidas b&aacute;sicas de seguridad como el modelo de responsabilidad compartida, gesti&oacute;n de accesos y protecci&oacute;n de datos.</p>\r\n<ul>\r\n<li>Se ha adquirido conocimiento de los componentes de una infraestructura global en la nube.</li>\r\n<li>Se ha demostrado la capacidad para explorar y describir las principales categor&iacute;as de servicios disponibles.</li>\r\n<li>Se ha realizado una evaluaci&oacute;n del uso adecuado de servicios b&aacute;sicos en ejercicios pr&aacute;cticos.</li>\r\n<li>Se ha comprendido el modelo de responsabilidad compartida en la nube.</li>\r\n<li>Se ha aplicado medidas de seguridad b&aacute;sicas mediante herramientas de gesti&oacute;n de acceso.</li>\r\n<li>Se han realizado ejercicios sobre gesti&oacute;n de usuarios y pol&iacute;ticas de seguridad.</li>\r\n</ul>\r\n<p>RA3. Dise&ntilde;a y configura redes virtuales y servicios de c&oacute;mputo en la nube, aplicando buenas pr&aacute;cticas de seguridad, estrategias de balanceo de carga, escalado autom&aacute;tico y aprovechando tecnolog&iacute;as serverless, contenedores y m&aacute;quinas virtuales seg&uacute;n casos de uso espec&iacute;ficos.</p>\r\n<ul>\r\n<li>Se ha realizado el dise&ntilde;o y configuraci&oacute;n de redes virtuales privadas. Se ha aplicado buenas pr&aacute;cticas de seguridad en redes y arquitecturas.</li>\r\n<li>Se ha participado activamente en la creaci&oacute;n y configuraci&oacute;n de una red funcional.</li>\r\n<li>Se ha realizado la selecci&oacute;n de servicios de computaci&oacute;n adecuados seg&uacute;n casos de uso.</li>\r\n<li>Se ha llevado a cabo la configuraci&oacute;n y gesti&oacute;n de balanceo de carga y escalado autom&aacute;tico.</li>\r\n<li>Se han desarrollado pr&aacute;cticas relacionadas con la optimizaci&oacute;n de recursos computacionales.</li>\r\n</ul>\r\n<p>RA4. Gestiona servicios de almacenamiento y bases de datos en la nube, seleccionando tecnolog&iacute;as adecuadas para casos espec&iacute;ficos, y dise&ntilde;a arquitecturas escalables y resilientes utilizando herramientas de monitoreo y optimizaci&oacute;n para mejorar el rendimiento.</p>\r\n<ul>\r\n<li>Se ha realizado la diferenciaci&oacute;n entre tecnolog&iacute;as de almacenamiento en la nube.</li>\r\n<li>Se ha llevado a cabo la configuraci&oacute;n y gesti&oacute;n de bases de datos en un entorno de nube.</li>\r\n<li>Se ha trabajado en la resoluci&oacute;n de problemas pr&aacute;cticos sobre almacenamiento y bases de datos.</li>\r\n<li>Se ha dise&ntilde;ado arquitecturas escalables y resilientes basadas en las mejores pr&aacute;cticas.</li>\r\n<li>Se ha hecho uso de herramientas de monitoreo y recomendaciones de optimizaci&oacute;n.</li>\r\n<li>Se ha participado en actividades que simulen el an&aacute;lisis y mejora de arquitecturas existentes.</li>\r\n</ul>'),
(3321, 119, 42, '<p><span class=\"NormalTextRun SCXW15208195 BCX0\" data-ccp-parastyle=\"heading 2\">Blo</span><span class=\"NormalTextRun SCXW15208195 BCX0\" data-ccp-parastyle=\"heading 2\">que</span><span class=\"NormalTextRun SCXW15208195 BCX0\" data-ccp-parastyle=\"heading 2\"> 1:</span> <span class=\"NormalTextRun SCXW15208195 BCX0\" data-ccp-parastyle=\"heading 2\">Dispositivos digitales e Internet. CE1</span><span class=\"NormalTextRun SCXW15208195 BCX0\" data-ccp-parastyle=\"heading 2\">.</span></p>\r\n<table style=\"font-weight: 400;\" border=\"1\" cellpadding=\"5\" data-tablestyle=\"Custom\" data-tablelook=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"text-align: center;\" data-celllook=\"4369\">\r\n<p style=\"text-align: center;\"><strong>CONTENIDOS&nbsp;</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Ordenador personal, dispositivos m&oacute;viles y otros&nbsp; dispositivos de uso dom&eacute;stico y educativo.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:97,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Funcionamiento b&aacute;sico y caracter&iacute;sticas&nbsp; m&aacute;s importantes de los dispositivos digitales.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:97,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Sistemas operativos comunes y aplicaciones.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:97,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Redes de dispositivos. Cimientos y formas&nbsp; de acceso a Internet.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:97,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">La brecha&nbsp; digital.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:97,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">H&aacute;bitos b&aacute;sicos de seguridad para&nbsp; proteger los dispositivos.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:97,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Implicaciones del uso de los dispositivos digitales para&nbsp; la salud,&nbsp; la sostenibilidad&nbsp; y el&nbsp; medio ambiente. Obsolescencia.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:97,&quot;335559739&quot;:0,&quot;335559740&quot;:261}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p><span data-contrast=\"none\">Bloque 2: Busca, selecci&oacute;n, organizaci&oacute;n y creaci&oacute;n de contenidos&nbsp; digitales. CE2.</span><span data-ccp-props=\"{&quot;134245418&quot;:true,&quot;134245529&quot;:true,&quot;335551550&quot;:6,&quot;335551620&quot;:6,&quot;335559738&quot;:40,&quot;335559739&quot;:0}\">&nbsp;</span></p>\r\n<table border=\"1\" cellpadding=\"5\" data-tablestyle=\"Custom\" data-tablelook=\"0\">\r\n<tbody>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p style=\"text-align: center;\"><strong>CONTENIDOS&nbsp;</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Tipo de buscadores web y sus&nbsp;&nbsp; herramientas de filtraje.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:134,&quot;335559737&quot;:90,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Selecci&oacute;n de informaci&oacute;n en medios digitales a trav&eacute;s&nbsp; de buscadores&nbsp; web contrastando la veracidad.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:97,&quot;335559739&quot;:0,&quot;335559740&quot;:261,&quot;469777462&quot;:[4811],&quot;469777927&quot;:[0],&quot;469777928&quot;:[1]}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Lectura e interpretaci&oacute;n de informaci&oacute;n de medios digitales.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:134,&quot;335559737&quot;:90,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Propiedad intelectual y derechos&nbsp; de autor&iacute;a.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:134,&quot;335559737&quot;:90,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Detecci&oacute;n de noticias&nbsp; falsas, bolas y discursos&nbsp; de odio. Implicaciones sociales.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:134,&quot;335559737&quot;:90,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Organizaci&oacute;n de la&nbsp; informaci&oacute;n. Operaciones b&aacute;sicas con archivos y carpetas.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:134,&quot;335559737&quot;:90,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Personalizaci&oacute;n del entorno de&nbsp;&nbsp; trabajo.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:134,&quot;335559737&quot;:90,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Creaci&oacute;n b&aacute;sica de contenidos&nbsp; con herramientas digitales.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:134,&quot;335559737&quot;:90,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Est&eacute;tica y lenguaje&nbsp; audiovisual.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:134,&quot;335559737&quot;:90,&quot;335559738&quot;:121,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<p><span data-contrast=\"none\">Bloque 3: Identidad digital. CE3. </span><span data-ccp-props=\"{&quot;134245418&quot;:true,&quot;134245529&quot;:true,&quot;335551550&quot;:6,&quot;335551620&quot;:6,&quot;335559738&quot;:40,&quot;335559739&quot;:0}\">&nbsp;</span></p>\r\n<table border=\"1\" cellpadding=\"5\" data-tablestyle=\"Custom\" data-tablelook=\"0\">\r\n<tbody>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p style=\"text-align: center;\"><strong>CONTENIDOS&nbsp;</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">La identidad&nbsp; personal en Internet. Alias y avatares.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"none\">Autoconcepto y percepci&oacute;n&nbsp; externa de la&nbsp; identidad digital.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Referencias socioculturales en la construcci&oacute;n&nbsp; de la&nbsp; identidad digital. Personas influyentes.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Exposici&oacute;n personal en la red.&nbsp; La huella&nbsp; digital.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Conductas y h&aacute;bitos&nbsp; para&nbsp; cuidar la identidad&nbsp; digital.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559738&quot;:1,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">La privacidad&nbsp; en la red.&nbsp; La protecci&oacute;n&nbsp; de los&nbsp; datos de car&aacute;cter&nbsp; personal. Informaci&oacute;n y consentimiento.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559737&quot;:85,&quot;335559739&quot;:0,&quot;335559740&quot;:256}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335551550&quot;:6,&quot;335551620&quot;:6,&quot;335559685&quot;:0,&quot;335559731&quot;:0,&quot;335559738&quot;:0,&quot;335559739&quot;:0,&quot;335559740&quot;:360}\">&nbsp;</span></p>\r\n<p><span data-contrast=\"none\">Bloque 4: Relaciones en entorno digital. CE4.</span><span data-ccp-props=\"{&quot;134245418&quot;:true,&quot;134245529&quot;:true,&quot;335551550&quot;:6,&quot;335551620&quot;:6,&quot;335559738&quot;:40,&quot;335559739&quot;:0}\">&nbsp;</span></p>\r\n<table border=\"1\" cellpadding=\"5\" data-tablestyle=\"Custom\" data-tablelook=\"0\">\r\n<tbody>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p style=\"text-align: center;\"><strong>CONTENIDOS&nbsp;</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Amistad virtual y f&iacute;sica.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Entornos digitales de intercambio social y juegos&nbsp; en l&iacute;nea</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Estrategias para&nbsp; una ciberconviv&egrave;ncia igualitaria, segura y saludable.&nbsp; Hashtag digital.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Ventajas y beneficios&nbsp; de las&nbsp; interacciones en entorno digital.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Riesgos y amenazas&nbsp; del uso de dispositivos&nbsp; y relaciones&nbsp; en red: ciberacoso y fraudes.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559738&quot;:1,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td data-celllook=\"4369\">\r\n<p><span data-contrast=\"auto\">Adicciones: tecno addicci&oacute;n, nomof&ograve;bia y ludopat&iacute;a&nbsp; en l&iacute;nea.</span><span data-ccp-props=\"{&quot;134245417&quot;:false,&quot;201341983&quot;:0,&quot;335559685&quot;:88,&quot;335559738&quot;:1,&quot;335559739&quot;:0,&quot;335559740&quot;:240}\">&nbsp;</span></p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(3322, 128, 41, '<p style=\"line-height: 130%; orphans: 2; widows: 2;\" align=\"justify\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri, serif;\"><span class=\"oXzekf\" data-huuid=\"11049387225717572446\">El conjunto integrado de conocimientos, habilidades (saber hacer), destrezas (capacidad para aplicar el saber hacerI y actitudes ( saber estar) que una persona necesita para desempe&ntilde;ar correctamente una actividad profesional, adapt&aacute;ndose a las exigencias del mercado laboral. </span><span class=\"oXzekf\" data-huuid=\"11049387225717574607\">Este enfoque educativo busca que el alumno pueda aplicar lo aprendido en situaciones pr&aacute;cticas del mundo real, no solo en la teor&iacute;a</span></span></span></p>\r\n<p>&nbsp;</p>'),
(3323, 128, 23, ''),
(3324, 128, 38, '<p data-start=\"176\" data-end=\"421\"><strong data-start=\"176\" data-end=\"189\">Objetivo:</strong> Aplicar los resultados de aprendizaje del m&oacute;dulo en un entorno real, desarrollando competencias personales, sociales, emocionales y emprendedoras, as&iacute; como habilidades para la innovaci&oacute;n y la sostenibilidad del sector productivo.</p>\r\n<h3 data-start=\"423\" data-end=\"453\">Contenidos y actividades</h3>\r\n<ul data-start=\"454\" data-end=\"977\">\r\n<li data-start=\"454\" data-end=\"575\">\r\n<p data-start=\"456\" data-end=\"575\">Participaci&oacute;n activa en proyectos y tareas del equipo, asumiendo responsabilidades y tomando decisiones cooperativas.</p>\r\n</li>\r\n<li data-start=\"576\" data-end=\"661\">\r\n<p data-start=\"578\" data-end=\"661\">Aplicaci&oacute;n de t&eacute;cnicas de comunicaci&oacute;n oral y escrita adaptadas a cada situaci&oacute;n.</p>\r\n</li>\r\n<li data-start=\"662\" data-end=\"784\">\r\n<p data-start=\"664\" data-end=\"784\">Gesti&oacute;n del tiempo, planificaci&oacute;n de actividades y resoluci&oacute;n de conflictos con flexibilidad e inteligencia emocional.</p>\r\n</li>\r\n<li data-start=\"785\" data-end=\"881\">\r\n<p data-start=\"787\" data-end=\"881\">Desarrollo de habilidades emprendedoras y colaboraci&oacute;n en procesos de innovaci&oacute;n sostenible.</p>\r\n</li>\r\n<li data-start=\"882\" data-end=\"977\">\r\n<p data-start=\"884\" data-end=\"977\">Uso de herramientas digitales para mejorar procesos de innovaci&oacute;n e investigaci&oacute;n aplicada.</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"979\" data-end=\"995\">Evaluaci&oacute;n</h3>\r\n<ul data-start=\"996\" data-end=\"1279\">\r\n<li data-start=\"996\" data-end=\"1086\">\r\n<p data-start=\"998\" data-end=\"1086\">Observaci&oacute;n directa del desempe&ntilde;o en la empresa y grado de participaci&oacute;n en proyectos.</p>\r\n</li>\r\n<li data-start=\"1087\" data-end=\"1175\">\r\n<p data-start=\"1089\" data-end=\"1175\">Valoraci&oacute;n del trabajo en equipo, comunicaci&oacute;n, liderazgo y resoluci&oacute;n de problemas.</p>\r\n</li>\r\n<li data-start=\"1176\" data-end=\"1279\">\r\n<p data-start=\"1178\" data-end=\"1279\">Informe del tutor de empresa, coordinado con el profesor, sobre la aplicaci&oacute;n de competencias y RA.</p>\r\n</li>\r\n</ul>');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3325, 128, 39, '<p data-start=\"253\" data-end=\"438\">La evaluaci&oacute;n de los <strong data-start=\"274\" data-end=\"308\">Resultados de Aprendizaje (RA)</strong> se realizar&aacute; de manera <strong data-start=\"332\" data-end=\"364\">continua, formativa y global</strong>, considerando tanto el proceso como los productos finales del alumnado.</p>\r\n<h3 data-start=\"440\" data-end=\"457\">Seguimiento</h3>\r\n<ul data-start=\"458\" data-end=\"760\">\r\n<li data-start=\"458\" data-end=\"577\">\r\n<p data-start=\"460\" data-end=\"577\">Observaci&oacute;n continua de la participaci&oacute;n, implicaci&oacute;n y actitud del alumnado en clase y en la formaci&oacute;n en empresa.</p>\r\n</li>\r\n<li data-start=\"578\" data-end=\"682\">\r\n<p data-start=\"580\" data-end=\"682\">Revisi&oacute;n peri&oacute;dica de trabajos, proyectos, exposiciones y otras actividades relacionadas con los RA.</p>\r\n</li>\r\n<li data-start=\"683\" data-end=\"760\">\r\n<p data-start=\"685\" data-end=\"760\">Feedback individualizado para orientar la mejora y reforzar competencias.</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"762\" data-end=\"778\">Evaluaci&oacute;n</h3>\r\n<ul data-start=\"779\" data-end=\"1164\">\r\n<li data-start=\"779\" data-end=\"900\">\r\n<p data-start=\"781\" data-end=\"900\">Se valorar&aacute; la <strong data-start=\"796\" data-end=\"885\">aplicaci&oacute;n pr&aacute;ctica de competencias personales, sociales, emocionales y emprendedoras</strong> (RA2 y RA3).</p>\r\n</li>\r\n<li data-start=\"901\" data-end=\"1032\">\r\n<p data-start=\"903\" data-end=\"1032\">Se analizar&aacute; la <strong data-start=\"919\" data-end=\"1029\">capacidad de trabajo en equipo, liderazgo, comunicaci&oacute;n, planificaci&oacute;n, gesti&oacute;n de conflictos e innovaci&oacute;n</strong>.</p>\r\n</li>\r\n<li data-start=\"1033\" data-end=\"1164\">\r\n<p data-start=\"1035\" data-end=\"1164\">La evaluaci&oacute;n incluir&aacute; evidencia de aprendizaje en <strong data-start=\"1086\" data-end=\"1161\">proyectos, actividades de empresa, exposiciones y entregables digitales</strong>.</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"1166\" data-end=\"1184\">Calificaci&oacute;n</h3>\r\n<ul data-start=\"1185\" data-end=\"1604\">\r\n<li data-start=\"1185\" data-end=\"1328\">\r\n<p data-start=\"1187\" data-end=\"1328\">Cada RA se calificar&aacute; seg&uacute;n los criterios establecidos en la programaci&oacute;n, con ponderaci&oacute;n proporcional a su importancia dentro del m&oacute;dulo.</p>\r\n</li>\r\n<li data-start=\"1329\" data-end=\"1428\">\r\n<p data-start=\"1331\" data-end=\"1428\">Ser&aacute; imprescindible obtener una calificaci&oacute;n m&iacute;nima de <strong data-start=\"1386\" data-end=\"1402\">5 en cada RA</strong> para superar el m&oacute;dulo.</p>\r\n</li>\r\n<li data-start=\"1429\" data-end=\"1604\">\r\n<p data-start=\"1431\" data-end=\"1604\">La calificaci&oacute;n final integrar&aacute; la evaluaci&oacute;n de todos los RA, combinando la <strong data-start=\"1508\" data-end=\"1601\">participaci&oacute;n, la pr&aacute;ctica en empresa, los proyectos y las pruebas escritas o entregables</strong>.</p>\r\n</li>\r\n</ul>'),
(3326, 128, 40, '<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><u><span style=\"text-decoration: none;\">5% RA2.<strong> Aplica estrategias relacionadas con las competencias personales, sociales y emocionales para el empleo en b&uacute;squeda de la mejora de su empleabilidad.</strong></span></u></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">a) Se ha valorado la importancia de las competencias personales y sociales en la empleabilidad en el sector de referencia. 1%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">b) Se ha participado activamente en el establecimiento de los objetivos del equipo y en la toma de decisiones del mismo y asumido la responsabilidad de las acciones y decisiones del grupo, participando activamente en el logro de unos objetivos compartidos cooperando con otras personas y compartiendo el liderazgo.1%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">c) Se han incorporado al propio proceso de aprendizaje las t&eacute;cnicas y recursos de presentaci&oacute;n y comunicaci&oacute;n, tanto orales como escritos, adecuados para una comunicaci&oacute;n efectiva y afectiva siendo capaz de adaptarlos a cada situaci&oacute;n y circunstancias, valorando las oportunidades y dificultades que ofrece cada una de ellas. 1%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">d) Se han aplicado t&eacute;cnicas y estrategias para la gesti&oacute;n del tiempo disponible para alcanzar los objetivos tanto individuales como del equipo y programado las actividades necesarias 0,5%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">e) Se han aplicado estrategias para canalizar las emociones mostrando una actitud flexible en las relaciones con otras personas. 0,5%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">f) Se han desarrollado estrategias para la programaci&oacute;n de actividades atendiendo a criterios de organizaci&oacute;n eficiente y previendo las posibles dificultades.0,5%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">g) Se ha reaccionado de forma flexible y positiva ante conflictos y situaciones nuevas, aprovechando las oportunidades y gestionando las dificultades haciendo uso de estrategias relacionadas con la inteligencia emocional. 0,5%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><u><span style=\"text-decoration: none;\">5%RA3.<strong> Pone en pr&aacute;ctica las habilidades emprendedoras necesarias para el desarrollo de procesos de innovaci&oacute;n e investigaci&oacute;n aplicadas que promuevan la modernizaci&oacute;n del sector productivo hacia un modelo sostenible.</strong></span></u></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">a) Se ha identificado el concepto de innovaci&oacute;n y su relaci&oacute;n con la construcci&oacute;n de una sociedad m&aacute;s sostenible que mejore en el bienestar de los individuos. 0,5%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">b) Se han analizado las distintas metodolog&iacute;as para emprender y su importancia para favorecer la innovaci&oacute;n y como fuente de creaci&oacute;n de empleo y bienestar social. 0,5%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">c) Se han aplicado las habilidades emprendedoras necesarias para promover el</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">emprendimiento y el intraemprendimiento. 0,5%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">d) Se ha puesto en pr&aacute;ctica el trabajo colaborativo como requisito para el desarrollo de procesos de innovaci&oacute;n. 1%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">e) Se ha desarrollado la competencia digital necesaria para la mejora de los procesos de innovaci&oacute;n e investigaci&oacute;n aplicadas que promuevan la modernizaci&oacute;n del sector productivo.2%</span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal; text-decoration: none;\" align=\"left\"><span style=\"color: #000000;\"><span style=\"font-family: Liberation Serif, serif;\"><span style=\"font-size: medium;\"><span style=\"text-decoration: none;\">f) Se han incorporado los objetivos de las pol&iacute;ticas e iniciativas relacionadas con la sostenibilidad y el medio ambiente a la estrategia empresarial enfocada al desarrollo de un modelo econ&oacute;mico y social sostenible.0,5%</span></span></span></span></p>'),
(3328, 128, 35, ''),
(3329, 340, 41, '<p>&nbsp;</p>\r\n<p>La competencia general de este t&iacute;tulo consiste en aplicar t&eacute;cnicas de limpieza, cambios de forma y color del cabello, as&iacute; como t&eacute;cnicas b&aacute;sicas de maquillaje, depilaci&oacute;n, manicura y pedicura, atendiendo al cliente y preparando los equipos, materiales y a&eacute;reas de trabajo con responsabilidad e iniciativa personal, operando con la calidad indicada, observando las normas de prevenci&oacute;n de riesgos laborales y protecci&oacute;n medioambiental correspondientes y comunic&aacute;ndose de forma oral y escrita en lengua castellana y en su caso en la lengua cooficial propia as&iacute; como en alguna lengua extranjera.</p>\r\n<p>&nbsp;</p>'),
(3330, 406, 11, '<p>El profesorado de este m&oacute;dulo formativo propondr&aacute; tanto actividades de refuerzo como de ampliaci&oacute;n, para as&iacute; atender a la diversidad del alumnado del aula.</p>\r\n<p>Por una parte, las actividades de refuerzo tienen como objetivo aclarar las lagunas de conocimiento detectadas en los alumnos. Podr&aacute;n tener car&aacute;cter general o de recuperaci&oacute;n. De esta forma, las actividades de recuperaci&oacute;n est&aacute;n orientadas para los alumnos que no hayan superado pruebas de conocimientos previamente impartidos.</p>\r\n<p>Las actividades de ampliaci&oacute;n estar&aacute;n dise&ntilde;adas para no tener inactivos a los alumnos aventajados en la resoluci&oacute;n de las actividades. Tiene como finalidad alcanzar niveles de conocimiento superiores a los inicialmente considerados</p>'),
(3332, 406, 44, '<p>Para poder optimizar los espacios del centro ser&aacute; importante incluir criterios claros para coordinar el uso compartido de los recursos entre los diferentes m&oacute;dulos y grupos. Los espacios como&nbsp;aulas de inform&aacute;tica, sal&oacute;n de actos, etc&nbsp;deben estar adecuadamente organizados y optimizados para el desarrollo de actividades que permitan alcanzar los RRAA. Se pueden establecer prioridades o protocolos de uso de espacios como las Aulas ATECA, EMPR&Eacute;N u otros similares. En la web del centro habr&aacute; una reserva de espacios para poder planificar con anterioridad. La mayor&iacute;a del curso se impartir&aacute; en el aula de inform&aacute;tica de referencia.</p>\r\n<p>En cuanto a los equipamientos o herramientas necesarias para la impartici&oacute;n del curso se realizar&aacute;n a principio del curso a la jefatura o coordinaci&oacute;n del departamento para que se encarge de reservar o comprar el equipamiento o herramientas adecuadas.</p>'),
(3333, 406, 13, '<p>A final del curso, los alumnos con evaluaciones suspensas o aquellos a los que se les haya retirado la evaluaci&oacute;n continua por superar el 15% de faltas de asistencia se examinar&aacute;n de los trimestres pendientes en la evaluaci&oacute;n ordinaria. Para poder realizar la recuperaci&oacute;n en la evaluaci&oacute;n ordinaria, ser&aacute; obligatorio tener entregados, al menos, el 85% de los trabajos, pr&aacute;cticas y ejercicios pleanteados que no se hayan entregado anteriormente en una fecha determinada por el profesor antes de la fecha del examen.</p>\r\n<p>La recuperaci&oacute;n de los bloques tem&aacute;ticos suspendidos se realizar&aacute; en un examen final de toda la materia del m&oacute;dulo, sin que existan ex&aacute;menes de recuperaci&oacute;n parciales.</p>\r\n<p>Si al finalizar la convocatoria ordinaria, el alumno no consigue superar los objetivos m&iacute;nimos del m&oacute;dulo, el equipo educativo decidir&aacute; si repite el m&oacute;dulo de forma presencial el curso siguiente o si acceder&aacute; a la convocatoria extraordinaria, seg&uacute;n especifica el D.O.G.V. 3.531 Resoluci&oacute;n del 24 de junio de 1999.</p>\r\n<p>En la convocatoria extraordinaria, el alumno deber&aacute; realizar una prueba de conocimientos te&oacute;rico/pr&aacute;cticos de todos los contenidos del m&oacute;dulo. La no comparecencia a la prueba de conocimientos referida conllevar&aacute; la no superaci&oacute;n del m&oacute;dulo.</p>'),
(3334, 406, 14, '<p>Los alumnos con el m&oacute;dulo pendiente que no asistan habitualmente a clase, para la convocatoria ordinaria del m&oacute;dulo, ser&aacute;n evaluados aproximadamente entre los meses de mayo y junio, de acuerdo con las directrices generales especificadas por el equipo directivo para la asignaci&oacute;n de fechas para la realizaci&oacute;n de dichas pruebas. Para la convocatoria extraordinaria se regir&aacute;n seg&uacute;n los mismos criterios que el resto de alumnos del m&oacute;dulo. Estos alumnos deber&aacute;n realizar una prueba de conocimientos te&oacute;rico/pr&aacute;cticos de todos los contenidos del m&oacute;dulo. La no comparecencia a la prueba de conocimientos referida conllevar&aacute; la no superaci&oacute;n del m&oacute;dulo.</p>'),
(3335, 26, 23, '<p>En las diferentes situaciones de aprendizaje que se plantean, los/as profesores/as del m&oacute;dulo utilizar&aacute;n alguno o todos los instrumentos de recogida y registro de informaci&oacute;n que aqu&iacute; se recogen:</p>\r\n<ul>\r\n<li>cuestionarios para recoger informaci&oacute;n sobre el nivel de satisfacci&oacute;n del alumnado, dificultades o conocimientos previos.</li>\r\n<li>ex&aacute;menes escritos que recojan conocimientos te&oacute;rico/pr&aacute;cticos. Con preguntas tipo test o desarrollo.</li>\r\n<li>pruebas pr&aacute;cticas en las que el alumnado demuestra su capacidad para realizar diferentes tareaas en equipos reales o m&aacute;quinas virtuales.</li>\r\n<li>portafolio del/la alumno/a en el cual recoja evidencias del trabajo desarrollado a lo largo del m&oacute;dulo.</li>\r\n<li>res&uacute;emnes de los bloques de teror&iacute;a o esquemas que puedan servir como repaso de los conceptos que se consideren m&aacute;s importantes. A veces, se realizar&aacute;n a mano y se entregar&aacute;n en papel.</li>\r\n<li>r&uacute;bricas que nos ayuden a evaluar de manera objetiva aspectos espec&iacute;ficos de una prueba.</li>\r\n<li>observaci&oacute;n sistem&aacute;tica d elos comportamientos, habilidades y actitudes durante el trabajo en clase.</li>\r\n<li>tutor&iacute;as colectivas o indovidualizadas para conocer el nivel de comprensi&oacute;n, detectar dudas o fallos conceptuales.</li>\r\n<li>registros anect&oacute;ditos con observaciones relevantes del docente sobre conductas, dificultades, logros, incidencias, etc.</li>\r\n<li>memorias o documentaci&oacute;n t&eacute;cnica escrita por el/la alumno/a tras&nbsp;una pr&aacute;ctica o proyecto.</li>\r\n<li>resoluci&oacute;n de retos propuetos donde el docente crear unas situaciones que el alumno debe analizar y resolver.</li>\r\n<li>evaluaci&oacute;n entre iguales: es una estrategia que permite al alumnado observar, valorar y aprender del trabajo de sus compa&ntilde;eros. No solo aporta informaci&oacute;n valiosa al docente, sino que tambi&eacute;n promueve la <strong data-start=\"423\" data-end=\"484\">autoevaluaci&oacute;n, la responsabilidad y la reflexi&oacute;n cr&iacute;tica.</strong></li>\r\n</ul>\r\n<p>&nbsp;</p>'),
(3336, 406, 40, '<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(3337, 26, 44, '<p data-start=\"474\" data-end=\"758\">La impartici&oacute;n del ciclo de T&eacute;cnico en Sistemas Microinform&aacute;ticos y Redes se realizar&aacute; conforme a lo establecido en el <strong data-start=\"593\" data-end=\"619\">Real Decreto 1691/2007</strong>, por el que se establece el t&iacute;tulo y sus ense&ntilde;anzas m&iacute;nimas, y el <strong data-start=\"686\" data-end=\"706\">Decreto 167/2008</strong>, por el que se implanta en la Comunidad Valenciana.</p>\r\n<p data-start=\"760\" data-end=\"798\">Se utilizar&aacute;&nbsp;<strong data-start=\"802\" data-end=\"822\">Aula polivalente t&eacute;cnica, de inform&aacute;tica&nbsp;</strong>equipada con los recursos necesarios para el desarrollo de los m&oacute;dulos pr&aacute;cticos como el que nos ocupa y para el desarrollo de contenidos te&oacute;ricos y actividades de grupo.</p>\r\n<p data-start=\"1008\" data-end=\"1148\">Estos espacios cumplen los requisitos de seguridad, accesibilidad y superficie m&iacute;nima, garantizando un entorno adecuado para el aprendizaje.</p>\r\n<p data-start=\"1150\" data-end=\"1189\">Los <strong data-start=\"1154\" data-end=\"1179\">equipamientos m&iacute;nimos</strong> incluyen:</p>\r\n<p data-start=\"1150\" data-end=\"1189\">&nbsp;</p>\r\n<ul>\r\n<li data-start=\"1191\" data-end=\"1243\">\r\n<p data-start=\"1193\" data-end=\"1243\">Puestos inform&aacute;ticos completos (uno por alumno/a).</p>\r\n</li>\r\n<li data-start=\"1244\" data-end=\"1326\">\r\n<p data-start=\"1246\" data-end=\"1326\">Equipos de red: switches, routers, puntos de acceso, cableado estructurado, etc.</p>\r\n</li>\r\n<li data-start=\"1327\" data-end=\"1381\">\r\n<p data-start=\"1329\" data-end=\"1381\">Herramientas de montaje y mantenimiento de hardware.</p>\r\n</li>\r\n<li data-start=\"1382\" data-end=\"1499\">\r\n<p data-start=\"1384\" data-end=\"1499\">Software actualizado: sistemas operativos, m&aacute;quinas virtuales, herramientas de seguridad y administraci&oacute;n de redes.</p>\r\n</li>\r\n<li data-start=\"1382\" data-end=\"1499\">Conexi&oacute;n a Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>'),
(3339, 26, 46, '<p>A continuaci&oacute;n&nbsp;presentamos una serie de <strong data-start=\"47\" data-end=\"71\">propuestas de mejora</strong> en el desarrollo del ciclo formativo de <strong data-start=\"112\" data-end=\"161\">T&eacute;cnico en Sistemas Microinform&aacute;ticos y Redes</strong>, basadas en el <strong data-start=\"177\" data-end=\"200\">marco legal vigente</strong> (Real Decreto 1691/2007 y Decreto 167/2008 del Consell), enfocadas tanto a nivel pedag&oacute;gico como organizativo, de espacios y equipamientos, dentro del contexto de la Comunidad Valenciana que ser&iacute;a interesante implementar en cursos posteriores:</p>\r\n<ol>\r\n<li><strong>Actualizaci&oacute;n constante de los equipos inform&aacute;ticos</strong> sustituyendo peri&oacute;dicamente los equipos obsoletos por otros que respondan a los est&aacute;ndares tecnol&oacute;gicos actuales del sector. Actualmente est&aacute;n en buenas condiciones y podemos utilizarlos durante m&aacute;s tiempo.</li>\r\n<li><strong>Ampliaci&oacute;n y mejora del aula</strong>:&nbsp;Optimizar el espacio de trabajo para pr&aacute;cticas colaborativas (islas de trabajo, mobiliario modular, etc.).</li>\r\n<li><strong>Continuar fomentando&nbsp;las metodolog&iacute;as activas</strong>: donde actualmente&nbsp;aplicamos metodolog&iacute;as como <strong data-start=\"1672\" data-end=\"1713\">Aprendizaje Basado en Proyectos (ABP)</strong> o <strong data-start=\"1716\" data-end=\"1753\">Aprendizaje Basado en Retos (ABR)</strong>, desarrollando productos reales (por ejemplo, instalando m&aacute;quinas virtuales con Sistemas Operativos como Windows 11) pero esta tarea debe continuar en el tiempo en cursos posteriores.</li>\r\n<li><strong>Continuar fomentando del trabajo colaborativo</strong>&nbsp;donde actualmente ya se incorporan&nbsp;din&aacute;micas de trabajo cooperativo, roles en grupo y evaluaci&oacute;n entre iguales para reforzar las competencias transversales.</li>\r\n<li><strong>Colaboraci&oacute;n con empresas del sector en un futuro cercano</strong>. Vamos a necesitar incrementar la cantidad de empresas donde nuestro alumnado har&aacute; sus pr&aacute;cticas en este mismo curso. Concretamente estableciendo convenios nuevos para la realizaci&oacute;n de la <strong>Formaci&oacute;n en empresa </strong>de este curso.</li>\r\n<li><strong>Accesibilidad e inclusi&oacute;n</strong>: seguimos trabajando para garantizar&nbsp;que el aula y los materiales digitales est&eacute;n adaptados a las necesidades del alumnado con diversidad funcional. Instalamos software para personas con dificultad visual para dar respuesta a las necesidades del grupo.</li>\r\n</ol>'),
(3340, 116, 46, '<p>Con el objetivo de optimizar la acci&oacute;n docente y, en consecuencia, elevar la calidad del proceso de ense&ntilde;anza-aprendizaje, se proponen diversas l&iacute;neas de mejora orientadas a la actualizaci&oacute;n tecnol&oacute;gica y metodol&oacute;gica del m&oacute;dulo. Entre ellas, destaca la utilizaci&oacute;n de sistemas operativos modernos y plenamente vigentes en el entorno profesional, la simulaci&oacute;n de instalaciones de redes que reproduzcan escenarios empresariales reales, y el empleo de herramientas ofim&aacute;ticas de car&aacute;cter profesional. Asimismo, se considera fundamental la incorporaci&oacute;n en el aula del estudio y la pr&aacute;ctica con las herramientas y servicios de Internet m&aacute;s relevantes en la actualidad, as&iacute; como la profundizaci&oacute;n en t&eacute;cnicas b&aacute;sicas de seguridad inform&aacute;tica que fomenten en el alumnado h&aacute;bitos responsables y seguros en el uso de las tecnolog&iacute;as.</p>'),
(3341, 26, 40, '<p>&nbsp;Teniendo en cuenta que este m&oacute;dulo contribuye al curr&iacute;culo en 128h, si reservamos un 10% de estas horas a los saberes que se alcanzar&aacute;n en la Formaci&oacute;n en empresa, podemos distribuir las horas de la siguiente manera:</p>\r\n<p>&nbsp;</p>\r\n<table>\r\n<thead>\r\n<tr>\r\n<th>C&oacute;digo</th>\r\n<th>Resultado de Aprendizaje</th>\r\n<th>Horas Centro Educativo</th>\r\n<th>Horas FE</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA1</td>\r\n<td data-label=\"Resultado\">Reconoce las caracter&iacute;sticas de los sistemas de archivos, describiendo sus tipos y aplicaciones.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;4</td>\r\n<td data-label=\"Horas FE\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA1.1</td>\r\n<td data-label=\"Resultado\">Identifica y describe los elementos funcionales de un sistema inform&aacute;tico, as&iacute; como los sistemas de numeraci&oacute;n que emplea.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;4</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA1.2</td>\r\n<td data-label=\"Resultado\">Conoce las caracter&iacute;sticas principales de los diferentes sistemas de archivos m&aacute;s utilizados.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;4</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA2</td>\r\n<td data-label=\"Resultado\">Instala sistemas operativos, relacionando sus caracter&iacute;sticas con el hardware del equipo y el software de aplicaci&oacute;n.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;15</td>\r\n<td data-label=\"Horas FE\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA2.1</td>\r\n<td data-label=\"Resultado\">Describe la arquitectura y funciones b&aacute;sicas de un sistema operativo.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;3</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA2.2</td>\r\n<td data-label=\"Resultado\">Planifica y prepara la instalaci&oacute;n de un sistema operativo.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;10</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA2.3</td>\r\n<td data-label=\"Resultado\">Configura los par&aacute;metros b&aacute;sicos de la instalaci&oacute;n y actualiza el sistema operativo.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;10</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA3</td>\r\n<td data-label=\"Resultado\">Realiza tareas b&aacute;sicas de configuraci&oacute;n de sistemas operativos, interpretando requerimientos y describiendo los procedimientos seguidos.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;4</td>\r\n<td data-label=\"Horas FE\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA3.1</td>\r\n<td data-label=\"Resultado\">Configura el entorno de trabajo del sistema operativo en base a las preferencias de los usuarios.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;4</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA3.2</td>\r\n<td data-label=\"Resultado\">Realiza la configuraci&oacute;n de los elementos b&aacute;sicos del sistema operativo que garantizan el funcionamiento correcto del sistema.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;4</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA4</td>\r\n<td data-label=\"Resultado\">Realiza operaciones b&aacute;sicas de administraci&oacute;n de sistemas operativos, interpretando requerimientos y optimizando el sistema para su uso.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;6</td>\r\n<td data-label=\"Horas FE\">&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA4.1</td>\r\n<td data-label=\"Resultado\">Administra los usuarios del sistema, estableciendo los permisos adecuados para cada tipo de cuenta.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;10</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA4.2</td>\r\n<td data-label=\"Resultado\">Aplica criterios para optimizar el rendimiento del sistema.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;6</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA4.3</td>\r\n<td data-label=\"Resultado\">Monitoriza el sistema para detectar cualquier error o acceso inadecuado a los recursos del sistema.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;6</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA4.4</td>\r\n<td data-label=\"Resultado\">Gestiona los procesos del sistema y usuario.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;10</td>\r\n<td data-label=\"Horas FE\">&nbsp;1</td>\r\n</tr>\r\n<tr>\r\n<td class=\"code\" data-label=\"C&oacute;digo\">RA5</td>\r\n<td data-label=\"Resultado\">Crea m&aacute;quinas virtuales identificando su campo de aplicaci&oacute;n e instalando software espec&iacute;fico.</td>\r\n<td data-label=\"Horas Centro Educativo\">&nbsp;15</td>\r\n<td data-label=\"Horas FE\">&nbsp;2</td>\r\n</tr>\r\n</tbody>\r\n<tfoot>\r\n<tr>\r\n<td colspan=\"2\" data-label=\"Total Horas\">Total Horas:</td>\r\n<td class=\"sum\" data-label=\"Horas Centro Educativo\">&nbsp;115</td>\r\n<td class=\"sum\" data-label=\"Horas FE\">&nbsp;13</td>\r\n</tr>\r\n</tfoot>\r\n</table>\r\n<p>&nbsp;Teniendo siempre en cuenta que la distribuci&oacute;n final de horas se concreta en el momento de la realizaci&oacute;n de la documentaci&oacute;n de la FE en la plataforma SA&Oacute;. Donde se atiende a criterios como la empresa asignada, el puesto que desempe&ntilde;ar&aacute; el alumno, etc.</p>\r\n<p>Siendo este planteamiento una propuesta que se acerca a la realidad todo lo posible por nuestra parte.</p>'),
(3342, 406, 20, '<p data-start=\"556\" data-end=\"887\">Aunque la asignatura de Digitalizaci&oacute;n en el segundo curso del Ciclo Formativo de Grado Medio se imparte en castellano, se fomenta la exposici&oacute;n del alumnado a la terminolog&iacute;a t&eacute;cnica en lengua inglesa, dado que el ingl&eacute;s es el idioma de referencia en el &aacute;mbito de las tecnolog&iacute;as de la informaci&oacute;n y la comunicaci&oacute;n.</p>\r\n<p data-start=\"889\" data-end=\"1210\">De esta forma, sin tratarse de un programa biling&uuml;e, se incorporan elementos de sensibilizaci&oacute;n ling&uuml;&iacute;stica y terminolog&iacute;a espec&iacute;fica en ingl&eacute;s, con el objetivo de contribuir al desarrollo de la competencia pluriling&uuml;e y a la mejora de la empleabilidad del alumnado en contextos profesionales internacionales.</p>\r\n<p data-start=\"889\" data-end=\"1210\">Esto contribuye al desarrollo de la competencia ling&uuml;&iacute;stica, digital y de empleabilidad del alumnado, en coherencia con los principios de la LOMLOE y las directrices europeas sobre educaci&oacute;n pluriling&uuml;e.</p>'),
(3344, 406, 46, '<p>Entre las propuestas de mejora cabe destacar que se pueden realizar propuestas en base a metodolog&iacute;a, contenidos, recursos, innovaci&oacute;n, evaluaci&oacute;n. Como mejora se puede realizar:</p>\r\n<ul>\r\n<li><strong>Aprendizaje basado en proyectos (ABP)</strong>: Integrar proyectos pr&aacute;cticos que combinen varias unidades did&aacute;cticas, como la creaci&oacute;n de una campa&ntilde;a digital completa o la automatizaci&oacute;n de un flujo de trabajo. Esto aumenta la motivaci&oacute;n y la comprensi&oacute;n aplicada.</li>\r\n<li><strong>Gamificaci&oacute;n</strong>: Incluir retos, badges o puntuaciones para motivar la participaci&oacute;n y reforzar conceptos t&eacute;cnicos.</li>\r\n<li><strong>Flipped classroom (clase invertida)</strong>: Proporcionar v&iacute;deos o tutoriales de conceptos te&oacute;ricos para que el tiempo de clase se dedique a pr&aacute;cticas, resoluci&oacute;n de problemas y trabajo colaborativo.</li>\r\n</ul>\r\n<p>Tambi&eacute;n se pueden a&ntilde;adir actualizaciones tecnol&oacute;gicas en cuanto a herramientas y plataformas digitales&nbsp;para que el alumnado trabaje con tecnolog&iacute;as reales y actuales. O plataformas interactivas: Usar herramientas como Kahoot, Genially o Padlet para reforzar conceptos de forma din&aacute;mica.</p>\r\n<p>Y en cuanto a innovaci&oacute;n se puede trabajar con:&nbsp;</p>\r\n<ul>\r\n<li><strong>Proyectos interdisciplinares</strong>: Colaborar con otras asignaturas (empresa, inform&aacute;tica, administraci&oacute;n) para que los proyectos tengan un enfoque m&aacute;s global.</li>\r\n<li><strong>Introducci&oacute;n a nuevas tecnolog&iacute;as</strong>: Incluir nociones de Inteligencia Artificial, an&aacute;lisis de datos o marketing digital b&aacute;sico.</li>\r\n<li><strong>Fomento de la creatividad digital</strong>: Talleres de dise&ntilde;o de contenidos, v&iacute;deo o presentaciones interactivas.</li>\r\n</ul>'),
(3345, 116, 23, '<p>La recogida de informaci&oacute;n relativa al progreso y rendimiento del alumnado se llevar&aacute; a cabo principalmente a trav&eacute;s de la plataforma educativa AULES, donde se registrar&aacute;n las diferentes actividades pr&aacute;cticas desarrolladas a lo largo de las unidades de programaci&oacute;n, as&iacute; como las calificaciones y observaciones correspondientes. En cuanto a las pruebas escritas o ex&aacute;menes, estos podr&aacute;n realizarse tanto mediante la propia plataforma AULES como de forma presencial en soporte papel. En este &uacute;ltimo caso, los ex&aacute;menes f&iacute;sicos ser&aacute;n debidamente archivados y conservados en el departamento, garantizando as&iacute; la trazabilidad y la disponibilidad de la informaci&oacute;n para su consulta o revisi&oacute;n cuando sea necesario.</p>'),
(3346, 116, 40, '<p>Los resultados de aprendizaje que se van a dualizar con las empresas son los siguientes:</p>\r\n<ul>\r\n<li><strong>RA3</strong>: Utiliza aplicaciones de un paquete ofim&aacute;tico, relacion&aacute;ndolas con sus aplicaciones.</li>\r\n<li><strong>RA4</strong>: Emplea utilidades proporcionadas por Internet, configur&aacute;ndolas e identificando su funcionalidad y prestaciones.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Respecto al <strong>RA3</strong> se llevar&aacute; a la empresa el <strong>30%</strong> del mismo lo que equivale a dos criterios de evaluaci&oacute;n que ser&aacute;n dualizados con esta. Estos criterios son los siguientes:</p>\r\n<ul>\r\n<li><strong>3.B</strong>) Se han utilizado los procedimientos de creaci&oacute;n, modificaci&oacute;n y manipulaci&oacute;n de documentos utilizando las herramientas del procesador de textos.</li>\r\n<li><strong>3.C</strong>) Se ha formateado un texto mejorando su presentaci&oacute;n utilizando distintos tipos de letras y alineaciones.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Para el <strong>RA4</strong> se llevar&aacute; a la empresa el <strong>15%</strong> lo que equivale a un criterio de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li><strong>4.A</strong>) Se han utilizado las herramientas para la navegaci&oacute;n por p&aacute;ginas web reconociendo la estructura de Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Estos criterios no se evaluar&aacute;n &iacute;ntegramente en la empresa, ya que para garantizar que se adquieren los conocimientos m&iacute;nimos de estos por parte del alumnado, su calificaci&oacute;n se repartir&aacute; de la siguiente manera. La nota de los <strong>CE</strong> ser&aacute; un <strong>15%</strong> de la calificaci&oacute;n que obtengan en pr&aacute;cticas y el <strong>85%</strong> restante se evaluar&aacute; en el centro con actividades durante el desarrollo de las unidades asociadas a ellos.</p>'),
(3347, 116, 44, '<p>Las sesiones del m&oacute;dulo se desarrollar&aacute;n en el aula asignada al grupo por el centro educativo, la cual deber&aacute; estar equipada con un n&uacute;mero suficiente de ordenadores para que todo el alumnado pueda trabajar de forma individual y realizar las distintas actividades programadas. Dichos equipos deber&aacute;n contar con las prestaciones necesarias para ejecutar con fluidez sistemas operativos tanto Windows como Linux, as&iacute; como para el funcionamiento estable de m&aacute;quinas virtuales, permitiendo as&iacute; la simulaci&oacute;n y pr&aacute;ctica de entornos reales de trabajo. Asimismo, ser&aacute; imprescindible que dispongan de conexi&oacute;n a Internet con el fin de facilitar la b&uacute;squeda de informaci&oacute;n, la investigaci&oacute;n y el uso de recursos did&aacute;cticos en l&iacute;nea que complementen el proceso de ense&ntilde;anza-aprendizaje.</p>'),
(3349, 116, 20, '<p>Para este m&oacute;dulo en concreto no se aplica ning&uacute;n plan de ense&ntilde;anza biling&uuml;e.</p>'),
(3351, 282, 45, '<ul>\r\n<li>Real Decreto 1629/2009, de 30 de octubre, por el que se establece el t&iacute;tulo de T&eacute;cnico Superior en Administraci&oacute;n de Sistemas Inform&aacute;ticos en Red y se fijan sus ense&ntilde;anzas m&iacute;nimas.</li>\r\n<li>Real Decreto 127/2014, de 28 de febrero, por el que se regulan aspectos espec&iacute;ficos de la Formaci&oacute;n Profesional B&aacute;sica de las ense&ntilde;anzas de formaci&oacute;n profesional del sistema educativo, se aprueban catorce t&iacute;tulos profesionales b&aacute;sicos, se fijan sus curr&iacute;culos b&aacute;sicos y se modifica el Real Decreto 1850/2009, de 4 de diciembre, sobre expedici&oacute;n de t&iacute;tulos acad&eacute;micos y profesionales correspondientes a las ense&ntilde;anzas establecidas en la Ley Org&aacute;nica 2/2006, de 3 de mayo, de Educaci&oacute;n.</li>\r\n<li>Real Decreto 356/2014, de 16 de mayo, por el que se establecen siete t&iacute;tulos de Formaci&oacute;n Profesional B&aacute;sica del cat&aacute;logo de t&iacute;tulos de las ense&ntilde;anzas de Formaci&oacute;n Profesional.</li>\r\n<li>Real Decreto 479/2020, de 7 de abril, por el que se establece el Curso de especializaci&oacute;n en ciberseguridad en entornos de las tecnolog&iacute;as de la informaci&oacute;n y se fijan los aspectos b&aacute;sicos del curr&iacute;culo.</li>\r\n<li>Real Decreto 279/2021, de 20 de abril, por el que se establece el Curso de especializaci&oacute;n en Inteligencia Artificial y Big Data y se fijan los aspectos b&aacute;sicos del curr&iacute;culo.</li>\r\n<li>Real Decreto 405/2023, de 29 de mayo, por el que se actualizan los t&iacute;tulos de la P&aacute;g 3/28 I.E.S. San Vicente formaci&oacute;n profesional del sistema educativo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Multiplataforma y T&eacute;cnico Superior en Desarrollo de Aplicaciones Web, de la familia profesional Inform&aacute;tica y Comunicaciones, y se fijan sus ense&ntilde;anzas m&iacute;nimas.</li>\r\n<li>Real Decreto 659/2023, de 18 de julio, por el que se desarrolla la ordenaci&oacute;n del Sistema de Formaci&oacute;n Profesional.</li>\r\n<li>Real Decreto 498/2024, de 21 de mayo, por el que se modifican determinados reales decretos por los que se establecen t&iacute;tulos de Formaci&oacute;n Profesional de grado b&aacute;sico y se fijan sus ense&ntilde;anzas m&iacute;nimas.</li>\r\n<li>Orden EFD/658/2024, de 25 de junio, por la que se determina el curr&iacute;culo y se regulan determinados aspectos organizativos para los ciclos formativos de grado b&aacute;sico en el &aacute;mbito de gesti&oacute;n del Ministerio de Educaci&oacute;n, Formaci&oacute;n Profesional y Deportes.</li>\r\n<li>Decreto 114/2025, de 29 de julio, del Consell, por el que se establecen los curr&iacute;culos de los ciclos formativos de grado medio y de grado superior de Formaci&oacute;n Profesional, en aplicaci&oacute;n de la Ley org&aacute;nica 3/2022, de 31 de marzo, de ordenaci&oacute;n e integraci&oacute;n de la Formaci&oacute;n Profesional.</li>\r\n</ul>'),
(3354, 4, 46, '<p>Entre las propuestas de mejora cabe destacar que se pueden realizar propuestas en base a metodolog&iacute;a, contenidos, recursos, innovaci&oacute;n, evaluaci&oacute;n. Como mejora se puede realizar .</p>\r\n<p>Aprendizaje basado en proyectos (ABP): Integrar proyectos pr&aacute;cticos que combinen varias unidades did&aacute;cticas, como la creaci&oacute;n de una campa&ntilde;a digital completa o la automatizaci&oacute;n de un flujo de trabajo. Esto aumenta la motivaci&oacute;n y la comprensi&oacute;n aplicada.</p>\r\n<p>Gamificaci&oacute;n: Incluir retos, badges o puntuaciones para motivar la participaci&oacute;n y reforzar conceptos t&eacute;cnicos.</p>\r\n<p>Flipped classroom (clase invertida): Proporcionar v&iacute;deos o tutoriales de conceptos te&oacute;ricos para que el tiempo de clase se dedique a pr&aacute;cticas, resoluci&oacute;n de problemas y trabajo colaborativo.</p>\r\n<p>Tambi&eacute;n se pueden a&ntilde;adir actualizaciones tecnol&oacute;gicas en cuanto a herramientas y plataformas digitales para que el alumnado trabaje con tecnolog&iacute;as reales y actuales. O Plataformas interactivas: Usar herramientas como Kahoot, Genially o Padlet para reforzar conceptos de forma din&aacute;mica.</p>\r\n<p>Y en cuanto a innovaci&oacute;n se puede trabajar con</p>\r\n<p>Proyectos interdisciplinares: Colaborar con otras asignaturas (empresa, inform&aacute;tica, administraci&oacute;n) para que los proyectos tengan un enfoque m&aacute;s global.</p>\r\n<p>Introducci&oacute;n a nuevas tecnolog&iacute;as: Incluir nociones de Inteligencia Artificial, an&aacute;lisis de datos o marketing digital b&aacute;sico.</p>\r\n<p>Fomento de la creatividad digital: Talleres de dise&ntilde;o de contenidos, v&iacute;deo o presentaciones interactivas.</p>'),
(3355, 4, 23, '<p data-start=\"581\" data-end=\"736\">A continuaci&oacute;n pasamos a detallar los instrumentos de evaluaci&oacute;n.-</p>\r\n<ol data-start=\"738\" data-end=\"2675\">\r\n<li data-start=\"738\" data-end=\"979\">\r\n<p data-start=\"741\" data-end=\"763\"><strong data-start=\"741\" data-end=\"761\">Pruebas escritas</strong></p>\r\n<ul data-start=\"767\" data-end=\"979\">\r\n<li data-start=\"767\" data-end=\"979\">\r\n<p data-start=\"769\" data-end=\"979\">Cuestionarios tipo test, de preguntas cortas, de desarrollo, etc., para comprobar los conocimientos te&oacute;ricos sobre digitalizaci&oacute;n, herramientas digitales, conceptos como econom&iacute;a circular, cloud computing, etc.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"981\" data-end=\"1269\">\r\n<p data-start=\"984\" data-end=\"1008\"><strong data-start=\"984\" data-end=\"1006\">Trabajos pr&aacute;cticos</strong></p>\r\n<ul data-start=\"1012\" data-end=\"1269\">\r\n<li data-start=\"1012\" data-end=\"1136\">\r\n<p data-start=\"1014\" data-end=\"1136\">Proyectos o estudios de caso donde el alumno elabore un plan de transformaci&oacute;n digital para una empresa ficticia o real.</p>\r\n</li>\r\n<li data-start=\"1140\" data-end=\"1269\">\r\n<p data-start=\"1142\" data-end=\"1269\">Ejercicios de aplicaci&oacute;n pr&aacute;ctica de tecnolog&iacute;as digitales (uso de plataformas en la nube, herramientas de colaboraci&oacute;n, etc.).</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1271\" data-end=\"1540\">\r\n<p data-start=\"1274\" data-end=\"1316\"><strong data-start=\"1274\" data-end=\"1314\">Actividades en clase / participaci&oacute;n</strong></p>\r\n<ul data-start=\"1320\" data-end=\"1540\">\r\n<li data-start=\"1320\" data-end=\"1413\">\r\n<p data-start=\"1322\" data-end=\"1413\">Resoluci&oacute;n de problemas en grupo, debates, participaci&oacute;n oral, actividades colaborativas.</p>\r\n</li>\r\n<li data-start=\"1417\" data-end=\"1540\">\r\n<p data-start=\"1419\" data-end=\"1540\">Actividades de an&aacute;lisis de casos actuales en el sector productivo (c&oacute;mo digitalizaci&oacute;n ha cambiado procesos productivos).</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1542\" data-end=\"1679\">\r\n<p data-start=\"1545\" data-end=\"1586\"><strong data-start=\"1545\" data-end=\"1584\">Portfolios / cuaderno de evidencias</strong></p>\r\n<ul data-start=\"1590\" data-end=\"1679\">\r\n<li data-start=\"1590\" data-end=\"1679\">\r\n<p data-start=\"1592\" data-end=\"1679\">Recogida de trabajos realizados, reflexiones sobre lo aprendido, autoevaluaciones, etc.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1681\" data-end=\"1898\">\r\n<p data-start=\"1684\" data-end=\"1717\"><strong data-start=\"1684\" data-end=\"1715\">Proyectos finales de m&oacute;dulo</strong></p>\r\n<ul data-start=\"1721\" data-end=\"1898\">\r\n<li data-start=\"1721\" data-end=\"1898\">\r\n<p data-start=\"1723\" data-end=\"1898\">Integraci&oacute;n de varios conceptos y competencias: por ejemplo un proyecto donde se apliquen tecnolog&iacute;as, se haga un plan, se consideren costes, impacto en recursos humanos, etc.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"1900\" data-end=\"2094\">\r\n<p data-start=\"1903\" data-end=\"1945\"><strong data-start=\"1903\" data-end=\"1943\">Presentaciones orales / exposiciones</strong></p>\r\n<ul data-start=\"1949\" data-end=\"2094\">\r\n<li data-start=\"1949\" data-end=\"2094\">\r\n<p data-start=\"1951\" data-end=\"2094\">Exposici&oacute;n del proyecto final o de los trabajos pr&aacute;cticos ante el profesor o compa&ntilde;eros, defendiendo las decisiones tomadas en el plan digital.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"2096\" data-end=\"2240\">\r\n<p data-start=\"2099\" data-end=\"2140\"><strong data-start=\"2099\" data-end=\"2138\">Tareas online / pr&aacute;cticas digitales</strong></p>\r\n<ul data-start=\"2144\" data-end=\"2240\">\r\n<li data-start=\"2144\" data-end=\"2240\">\r\n<p data-start=\"2146\" data-end=\"2240\">Uso de plataformas digitales para realizar actividades, quizzes, foros, autoevaluaciones, etc.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"2242\" data-end=\"2384\">\r\n<p data-start=\"2245\" data-end=\"2280\"><strong data-start=\"2245\" data-end=\"2278\">Autoevaluaci&oacute;n y coevaluaci&oacute;n</strong></p>\r\n<ul data-start=\"2284\" data-end=\"2384\">\r\n<li data-start=\"2284\" data-end=\"2384\">\r\n<p data-start=\"2286\" data-end=\"2384\">Reflexi&oacute;n del alumno sobre su progreso y evaluaci&oacute;n mutua entre alumnos en trabajos colaborativos.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li data-start=\"2386\" data-end=\"2550\">\r\n<p data-start=\"2389\" data-end=\"2414\"><strong data-start=\"2389\" data-end=\"2412\">Evaluaci&oacute;n continua</strong></p>\r\n<ul data-start=\"2418\" data-end=\"2550\">\r\n<li data-start=\"2418\" data-end=\"2550\">\r\n<p data-start=\"2420\" data-end=\"2550\">Seguimiento a lo largo del curso, con entregas parciales de actividades, participaci&oacute;n, trabajos, etc., que suman a la nota final.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ol>'),
(3357, 414, 46, '<p>A continuaci&oacute;n&nbsp;presentamos una serie de&nbsp;<strong data-start=\"47\" data-end=\"71\">propuestas de mejora</strong>, enfocadas tanto a nivel pedag&oacute;gico como organizativo, de espacios y equipamientos que ser&iacute;a interesante implementar en cursos posteriores:</p>\r\n<ol>\r\n<li><strong>Actualizaci&oacute;n constante de los equipos inform&aacute;ticos</strong>&nbsp;sustituyendo peri&oacute;dicamente los equipos obsoletos por otros que respondan a los est&aacute;ndares tecnol&oacute;gicos actuales del sector. Actualmente est&aacute;n en buenas condiciones y podemos utilizarlos durante m&aacute;s tiempo.</li>\r\n<li><strong>Ampliaci&oacute;n y mejora del aula</strong>:&nbsp;Optimizar el espacio de trabajo para pr&aacute;cticas colaborativas (islas de trabajo, mobiliario modular, etc.).</li>\r\n<li><strong>Continuar fomentando&nbsp;las metodolog&iacute;as activas</strong>: donde actualmente&nbsp;aplicamos metodolog&iacute;as como&nbsp;<strong data-start=\"1672\" data-end=\"1713\">Aprendizaje Basado en Proyectos (ABP)</strong>&nbsp;o&nbsp;<strong data-start=\"1716\" data-end=\"1753\">Aprendizaje Basado en Retos (ABR)</strong>, desarrollando productos reales (por ejemplo, instalando m&aacute;quinas virtuales con Sistemas Operativos como Windows 11) pero esta tarea debe continuar en el tiempo en cursos posteriores.</li>\r\n<li><strong>Continuar fomentando del trabajo colaborativo</strong>&nbsp;donde actualmente ya se incorporan&nbsp;din&aacute;micas de trabajo cooperativo, roles en grupo y evaluaci&oacute;n entre iguales para reforzar las competencias transversales.</li>\r\n<li><strong>Colaboraci&oacute;n con empresas del sector en un futuro cercano</strong>. Vamos a necesitar incrementar la cantidad de empresas donde nuestro alumnado har&aacute; sus pr&aacute;cticas en este mismo curso. Concretamente estableciendo convenios nuevos para la realizaci&oacute;n de la&nbsp;<strong>Formaci&oacute;n en empresa&nbsp;</strong>de este curso.</li>\r\n<li><strong>Accesibilidad e inclusi&oacute;n</strong>: seguimos trabajando para garantizar&nbsp;que el aula y los materiales digitales est&eacute;n adaptados a las necesidades del alumnado con diversidad funcional. Instalamos software para personas con dificultad visual para dar respuesta a las necesidades del grupo.</li>\r\n</ol>');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3358, 414, 23, '<p>En las diferentes situaciones de aprendizaje que se plantean, los/as profesores/as del m&oacute;dulo utilizar&aacute;n alguno o todos los instrumentos de recogida y registro de informaci&oacute;n que aqu&iacute; se recogen:</p>\r\n<ul>\r\n<li>cuestionarios para recoger informaci&oacute;n sobre el nivel de satisfacci&oacute;n del alumnado, dificultades o conocimientos previos.</li>\r\n<li>ex&aacute;menes escritos que recojan conocimientos te&oacute;rico/pr&aacute;cticos. Con preguntas tipo test o desarrollo.</li>\r\n<li>pruebas pr&aacute;cticas en las que el alumnado demuestra su capacidad para realizar diferentes tareaas en equipos reales o m&aacute;quinas virtuales.</li>\r\n<li>portafolio del/la alumno/a en el cual recoja evidencias del trabajo desarrollado a lo largo del m&oacute;dulo.</li>\r\n<li>res&uacute;emnes de los bloques de teror&iacute;a o esquemas que puedan servir como repaso de los conceptos que se consideren m&aacute;s importantes. A veces, se realizar&aacute;n a mano y se entregar&aacute;n en papel.</li>\r\n<li>r&uacute;bricas que nos ayuden a evaluar de manera objetiva aspectos espec&iacute;ficos de una prueba.</li>\r\n<li>observaci&oacute;n sistem&aacute;tica d elos comportamientos, habilidades y actitudes durante el trabajo en clase.</li>\r\n<li>tutor&iacute;as colectivas o indovidualizadas para conocer el nivel de comprensi&oacute;n, detectar dudas o fallos conceptuales.</li>\r\n<li>registros anect&oacute;ditos con observaciones relevantes del docente sobre conductas, dificultades, logros, incidencias, etc.</li>\r\n<li>memorias o documentaci&oacute;n t&eacute;cnica escrita por el/la alumno/a tras&nbsp;una pr&aacute;ctica o proyecto.</li>\r\n<li>resoluci&oacute;n de retos propuetos donde el docente crear unas situaciones que el alumno debe analizar y resolver.</li>\r\n<li>evaluaci&oacute;n entre iguales: es una estrategia que permite al alumnado observar, valorar y aprender del trabajo de sus compa&ntilde;eros. No solo aporta informaci&oacute;n valiosa al docente, sino que tambi&eacute;n promueve la&nbsp;<strong data-start=\"423\" data-end=\"484\">autoevaluaci&oacute;n, la responsabilidad y la reflexi&oacute;n cr&iacute;tica.</strong></li>\r\n</ul>\r\n<p>&nbsp;</p>'),
(3360, 414, 11, '<p><strong><span style=\"font-size: medium;\"><span style=\"font-weight: normal;\">El profesorado de este m&oacute;dulo formativo propondr&aacute; tanto actividades de refuerzo como de ampliaci&oacute;n, para as&iacute; atender a la diversidad del alumnado del aula.</span></span></strong></p>'),
(3361, 414, 44, '<p data-start=\"474\" data-end=\"758\">En el art&iacute;culo 5 de la ORDEN&nbsp;60/2012, de 25 de septiembre, de la Conselleria&nbsp;de Educaci&oacute;n, Formaci&oacute;n y Empleo por la que se establece<br />para la Comunitat Valenciana el curr&iacute;culo del ciclo&nbsp;formativo de Grado Superior correspondiente al t&iacute;tulo&nbsp;de T&eacute;cnico Superior en Desarrollo de Aplicaciones Web, se regula el uso de los espacios&nbsp;y equipamientos y dice as&iacute;:</p>\r\n<p data-start=\"474\" data-end=\"758\">\"Los espacios m&iacute;nimos que deben reunir los centros educativos&nbsp;para permitir el desarrollo de las ense&ntilde;anzas de este ciclo formativo,&nbsp;cumpliendo con la normativa sobre prevenci&oacute;n de riesgos laborales, as&iacute;&nbsp;como la normativa sobre seguridad y salud en el puesto de trabajo son&nbsp;los establecidos en el anexo V de esta orden.<br />Los espacios formativos establecidos pueden ser ocupados por&nbsp;diferentes grupos de alumnado que cursen el mismo u otros ciclos formativos<br />o etapas educativas y no necesariamente deben diferenciarse&nbsp;mediante cerramientos.<br />El equipamiento, adem&aacute;s de ser el necesario y suficiente para garantizar&nbsp;la adquisici&oacute;n de los resultados de aprendizaje y la calidad de la<br />ense&ntilde;anza al alumnado seg&uacute;n el sistema de calidad adoptado, deber&aacute;&nbsp;cumplir las siguientes condiciones:</p>\r\n<p data-start=\"474\" data-end=\"758\"><br />a) Los equipos, m&aacute;quinas, etc. dispondr&aacute;n de la instalaci&oacute;n necesaria&nbsp;para su correcto funcionamiento y cumplir&aacute;n con las normas de seguridad<br />y prevenci&oacute;n de riesgos y con cuantas otras sean de aplicaci&oacute;n.<br />b) Su cantidad y caracter&iacute;sticas deber&aacute; estar en funci&oacute;n del n&uacute;mero&nbsp;de alumnos/as y permitir la adquisici&oacute;n de los resultados de aprendizaje,<br />teniendo en cuenta los criterios de evaluaci&oacute;n y los contenidos que se&nbsp;incluyen en cada uno de los m&oacute;dulos profesionales que se impartan en<br />los referidos espacios.\"</p>\r\n<p data-start=\"474\" data-end=\"758\"><strong>Por tanto</strong>, para la impartici&oacute;n del m&oacute;dulo se utilizar&aacute; un&nbsp;<strong data-start=\"802\" data-end=\"822\">aula polivalente t&eacute;cnica, de inform&aacute;tica&nbsp;</strong>equipada con los recursos necesarios para el desarrollo de los m&oacute;dulos pr&aacute;cticos como el que nos ocupa y para el desarrollo de contenidos te&oacute;ricos y actividades de grupo.</p>\r\n<p data-start=\"1008\" data-end=\"1148\">Estos espacios cumplen los requisitos de seguridad, accesibilidad y superficie m&iacute;nima, garantizando un entorno adecuado para el aprendizaje. Adem&aacute;s de cumplir con las medidas m&iacute;nimas que se recogen en el <strong>Anexo V</strong>:&nbsp;Para 20 alumnos, un aula polivalente debe medir al menos 40m2 y un aula laboratorio como m&iacute;nimo 60m2.</p>\r\n<p data-start=\"1150\" data-end=\"1189\">Los&nbsp;<strong data-start=\"1154\" data-end=\"1179\">equipamientos m&iacute;nimos</strong>&nbsp;incluyen:</p>\r\n<ul>\r\n<li data-start=\"1191\" data-end=\"1243\">\r\n<p data-start=\"1193\" data-end=\"1243\">Puestos inform&aacute;ticos completos (uno por alumno/a).</p>\r\n</li>\r\n<li data-start=\"1244\" data-end=\"1326\">\r\n<p data-start=\"1246\" data-end=\"1326\">Equipos de red: switches, routers, puntos de acceso, cableado estructurado, etc.</p>\r\n</li>\r\n<li data-start=\"1327\" data-end=\"1381\">\r\n<p data-start=\"1329\" data-end=\"1381\">Herramientas de montaje y mantenimiento de hardware.</p>\r\n</li>\r\n<li data-start=\"1382\" data-end=\"1499\">\r\n<p data-start=\"1384\" data-end=\"1499\">Software actualizado: sistemas operativos, m&aacute;quinas virtuales, herramientas de seguridad y administraci&oacute;n de redes.</p>\r\n</li>\r\n<li data-start=\"1382\" data-end=\"1499\">Conexi&oacute;n a Internet.</li>\r\n</ul>'),
(3362, 414, 45, '<p>La normativa que&nbsp;regula el m&oacute;dulo de Sostenibilidad aplicada al sistema productivo en el ciclo formativo de grado superior en Desarrollo de aplicaciones web a nivel estatal queda recogida en el <strong>REAL DECRETO 686/2010, de 20 de mayo,</strong> por el que se establece el t&iacute;tulo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Web y se fijan sus ense&ntilde;anzas m&iacute;nimas y se concretaba en la Comunidad Valenciana mediante la&nbsp;<strong>ORDEN 60/2012, de 25 de septiembre</strong>, de la Conselleria&nbsp;de Educaci&oacute;n, Formaci&oacute;n y Empleo por la que se establece&nbsp;para la Comunitat Valenciana el curr&iacute;culo del ciclo&nbsp;formativo de Grado Superior correspondiente al t&iacute;tulo&nbsp;de T&eacute;cnico Superior en Desarrollo de Aplicaciones Web.</p>\r\n<p>Ha sido actualizada / reemplazada por una norma auton&oacute;mica m&aacute;s reciente: el <strong data-start=\"369\" data-end=\"418\">Decreto 114/2025, de 29 de julio, del Consell</strong>, por el que se establecen los curr&iacute;culos de los ciclos formativos de grado medio y superior de Formaci&oacute;n Profesional en la Comunitat Valenciana, en aplicaci&oacute;n de la Ley Org&aacute;nica 3/2022 de ordenaci&oacute;n e integraci&oacute;n de la FP. En su <strong>Anexo&nbsp;IX</strong>&nbsp;menciona&nbsp;el m&oacute;dulo que nos ocupa.</p>\r\n<p><strong>Real Decreto 659/2023,&nbsp;</strong>de 18 de julio, por el que se desarrolla la ordenaci&oacute;n del Sistema de Formaci&oacute;n Profesional.</p>\r\n<p>La modificaci&oacute;n de los&nbsp;t&iacute;tulos de FP y sus ense&ntilde;anzas m&iacute;nimas en el Grado Superior se regula en el&nbsp;<strong>Real Decreto 500/2024, de 21 de mayo, por el que se modifican determinados reales decretos por los que se establecen t&iacute;tulos de Formaci&oacute;n Profesional de grado superior y se fijan sus ense&ntilde;anzas m&iacute;nimas.</strong></p>\r\n<p><strong>Cuyo c&oacute;digo (1708), duraci&oacute;n del curr&iacute;culo b&aacute;sico, equivalencia en cr&eacute;ditos ECTS y resultados de aprendizaje y criterios de evaluaci&oacute;n figuran como anexo VIII del Real Decreto 659/2023, de 18 de julio.</strong></p>\r\n<p>&nbsp;</p>'),
(3364, 414, 13, '<p><span style=\"font-weight: 400;\">En caso de no superar la evaluaci&oacute;n del m&oacute;dulo en la evaluaci&oacute;n continua (Convocatoria ordinaria), el alumnado podr&aacute; superar el m&oacute;dulos en la convocatoria extraordinaria. Para ello deber&aacute;:</span></p>\r\n<ul>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Realizar la entrega y presentaci&oacute;n de un Plan de Sostenibilidad completo.</span></li>\r\n<li style=\"font-weight: 400;\"><span style=\"font-weight: 400;\">Realizar una prueba te&oacute;rico-pr&aacute;ctica sobre todo el contenido del m&oacute;dulo.</span></li>\r\n</ul>\r\n<p><span style=\"font-weight: 400;\">Nota final extraordinaria = 50% Plan de sostenibilidad + 50% Prueba te&oacute;rico-pr&aacute;ctica.</span></p>'),
(3365, 414, 14, '<p>Al ser el primer a&ntilde;o en que se imparte, no existe alumnado con el m&oacute;dulo pendiente.</p>'),
(3366, 414, 22, '<p class=\"p1\">Dentro del Plan de mejora del centro, la Comisi&oacute;n de Coordinaci&oacute;n Pedag&oacute;gica en reuni&oacute;n celebrada el 5 de septiembre de 2019, ha aprobado unos criterios de correcci&oacute;n ortogr&aacute;fica que deben ser aplicados en todas las &aacute;reas, materias y cursos. Tiene, por tanto, car&aacute;cter prescriptivo y&nbsp;<strong>son de obligado cumplimiento&nbsp;</strong>para todo el profesorado<strong>.</strong></p>\r\n<p class=\"p1\">Ciclos Formativos de Grado Medio:&nbsp;Penalizaci&oacute;n de 0,25 puntos por error gr&aacute;fico (0,15 por tilde), hasta un m&aacute;ximo de 2,5 puntos.</p>\r\n<p class=\"p1\">En este caso, estamos programando para un m&oacute;dulo en ingl&eacute;s y por tanto, en funci&oacute;n de la prueba que se trate se podr&aacute; penalizar en funci&oacute;n del error ortogr&aacute;fico.&nbsp;</p>'),
(3367, 112, 46, '<table border=\"1\" cellpadding=\"5\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p>ACAD&Eacute;MICAS</p>\r\n</td>\r\n<td>\r\n<p>La coordinaci&oacute;n con los profesores del departamento, as&iacute; como los de &aacute;mbitos, junto con el departamento de orientaci&oacute;n y jefatura de estudios, ha sido fluida, de tal manera que la evoluci&oacute;n del alumnado ha sido buena, reflej&aacute;ndose en el periodo de pr&aacute;cticas en empresas, con el Apto en valoraci&oacute;n final del aprendizaje del ciclo.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>INFRAESTRUCTURAS Y EQUIPAMIENTO</p>\r\n</td>\r\n<td>\r\n<p>Se ha utilizado el aula de inform&aacute;tica tanto para la utilizaci&oacute;n de los ordenadores, como para utilizarlo como zona de trabajo para soldar componentes electr&oacute;nicos.&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>ACTIVIDADES EXTRAESCOLARES</p>\r\n</td>\r\n<td>\r\n<p>Que el grupo sea m&aacute;s participativo para llevar a cabo&nbsp; las actividades complementarias y extraescolares programadas.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>ORGANIZACI&Oacute;N PEDAG&Oacute;GICA</p>\r\n</td>\r\n<td>\r\n<p>Proponer actividades para tutor&iacute;as desde el departamento de orientaci&oacute;n.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>CONVIVENCIA</p>\r\n</td>\r\n<td>\r\n<p>Hacen una labor encomiable con los alumnos con lo cual me gustar&iacute;a poder dar la enhorabuena al departamento de convivencia por su dedicaci&oacute;n y efectividad.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p>ESPACIOS</p>\r\n</td>\r\n<td>\r\n<p>Har&iacute;a falta un espacio taller para poder desarrollar los ejercicios pr&aacute;cticos de electr&oacute;nica.</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(3368, 71, 46, '<p>Entre las propuestas de mejora cabe destacar que se pueden realizar propuestas en base a metodolog&iacute;a, contenidos, recursos, innovaci&oacute;n, evaluaci&oacute;n. Como mejora se puede realizar .-</p>\r\n<ul>\r\n<li data-start=\"305\" data-end=\"568\">\r\n<p data-start=\"307\" data-end=\"568\">Aprendizaje basado en proyectos (ABP): Integrar proyectos pr&aacute;cticos que combinen varias unidades did&aacute;cticas, como la creaci&oacute;n de una campa&ntilde;a digital completa o la automatizaci&oacute;n de un flujo de trabajo. Esto aumenta la motivaci&oacute;n y la comprensi&oacute;n aplicada.</p>\r\n</li>\r\n<li data-start=\"569\" data-end=\"688\">\r\n<p data-start=\"571\" data-end=\"688\">Gamificaci&oacute;n: Incluir retos, badges o puntuaciones para motivar la participaci&oacute;n y reforzar conceptos t&eacute;cnicos.</p>\r\n</li>\r\n<li data-start=\"689\" data-end=\"888\">\r\n<p data-start=\"691\" data-end=\"888\">Flipped classroom (clase invertida): Proporcionar v&iacute;deos o tutoriales de conceptos te&oacute;ricos para que el tiempo de clase se dedique a pr&aacute;cticas, resoluci&oacute;n de problemas y trabajo colaborativo.</p>\r\n<p data-start=\"691\" data-end=\"888\">Tambi&eacute;n se pueden a&ntilde;adir actualizaciones tecnol&oacute;gicas en cuanto a herramientas y plataformas digitales&nbsp;para que el alumnado trabaje con tecnolog&iacute;as reales y actuales. O&nbsp;Plataformas interactivas: Usar herramientas como Kahoot, Genially o Padlet para reforzar conceptos de forma din&aacute;mica.</p>\r\nY en cuanto a innovaci&oacute;n se puede trabajar con&nbsp;</li>\r\n<li data-start=\"3554\" data-end=\"3715\">\r\n<p data-start=\"3556\" data-end=\"3715\">Proyectos interdisciplinares: Colaborar con otras asignaturas (empresa, inform&aacute;tica, administraci&oacute;n) para que los proyectos tengan un enfoque m&aacute;s global.</p>\r\n</li>\r\n<li data-start=\"3716\" data-end=\"3849\">\r\n<p data-start=\"3718\" data-end=\"3849\">Introducci&oacute;n a nuevas tecnolog&iacute;as: Incluir nociones de Inteligencia Artificial, an&aacute;lisis de datos o marketing digital b&aacute;sico.</p>\r\n</li>\r\n<li data-start=\"3850\" data-end=\"3963\">\r\n<p data-start=\"3852\" data-end=\"3963\">Fomento de la creatividad digital: Talleres de dise&ntilde;o de contenidos, v&iacute;deo o presentaciones interactivas.</p>\r\n</li>\r\n</ul>'),
(3369, 71, 44, '<p>Para poder optimizar los espacios del centro ser&aacute; importante incluir criterios claros para coordinar el uso compartido de los recursos entre los diferentes m&oacute;dulos y grupos. Los espacios como&nbsp;aulas de inform&aacute;tica, sal&oacute;n de actos, etc&nbsp;deben estar adecuadamente organizados y optimizados para el desarrollo de actividades que permitan alcanzar los RRAA. Se pueden establecer prioridades o protocolos de uso de espacios como las Aulas ATECA, EMPR&Eacute;N u otros similares. En la web del centro habr&aacute; una reserva de espacios para poder planificar con anterioridad. La mayor&iacute;a del curso se impartir&aacute; en el aula de inform&aacute;tica de referencia.</p>\r\n<p>En cuanto a los equipamientos o herramientas necesarias para la impartici&oacute;n del curso se realizar&aacute;n a principio del curso a la jefatura o coordinaci&oacute;n del departamento para que se encarge de reservar o comprar el equipamiento o herramientas adecuadas.</p>'),
(3370, 366, 45, '<p>Las bases legislativas m&aacute;s relevantes que fundamentan esta programaci&oacute;n did&aacute;ctica son las siguientes:</p>\r\n<p>a) Ley Org&aacute;nica 3/2020, de 29 de diciembre (LOMLOE), por la que se modifica la Ley Org&aacute;nica 2/2006, de 3 de mayo, de Educaci&oacute;n (LOE)</p>\r\n<p>b) Real Decreto 1147/2011, de 29 de julio, por el que se establece la ordenaci&oacute;n general de la formaci&oacute;n profesional del sistema educativo.</p>\r\n<p>c) RESOLUCI&Oacute;N de 8 de agosto de 2024, de la Secretar&iacute;a Auton&oacute;mica de Educaci&oacute;n, por la cual se dictan instrucciones sobre ordenaci&oacute;n acad&eacute;mica y de organizaci&oacute;n de los centros que imparten Formaci&oacute;n Profesional durante el curso 2024-2025 en la Comunitat Valenciana.</p>\r\n<p>d) DECRETO 252/2019, de 29 de noviembre, del Consell, de regulaci&oacute;n de la organizaci&oacute;n y el funcionamiento de los centros p&uacute;blicos que imparten ense&ntilde;anzas de Educaci&oacute;n Secundaria Obligatoria, Bachillerato y Formaci&oacute;n Profesional.</p>\r\n<p>e) ORDEN 79/2010, de 27 de agosto, de la Conselleria de Educaci&oacute;n, por la que se regula la evaluaci&oacute;n del alumnado de los ciclos formativos de Formaci&oacute;n Profesional del sistema educativo en el &aacute;mbito territorial de la Comunitat Valenciana.</p>\r\n<p>f) Real Decreto 405/2023, de 29 de mayo, por el que se actualizan los t&iacute;tulos de la formaci&oacute;n profesional del sistema educativo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Multiplataforma y T&eacute;cnico Superior en Desarrollo de Aplicaciones Web, y se fijan sus ense&ntilde;anzas m&iacute;nimas.</p>\r\n<p>g) Real Decreto de T&iacute;tulo 450/2010 de 16 de abril, por el que se establece el t&iacute;tulo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Multiplataforma y se fijan sus ense&ntilde;anzas m&iacute;nimas.</p>\r\n<p>h) Orden 58/2012 de 5 de septiembre por la que se establece el curr&iacute;culo correspondiente al t&iacute;tulo de T&eacute;cnico Superior en Desarrollo de Aplicaciones Multiplataforma para la Comunidad Valenciana.</p>\r\n<p>i)&nbsp;Real Decreto 659/2023, de 18 de julio, por el que se desarrolla la ordenaci&oacute;n del Sistema de Formaci&oacute;n Profesional.</p>\r\n<p>j) Real Decreto 500/2024, de 21 de mayo, por el que se modifican determinados reales decretos por los que se establecen t&iacute;tulos de Formaci&oacute;n Profesional de grado superior y se fijan sus ense&ntilde;anzas m&iacute;nimas.</p>'),
(3371, 52, 46, '<p>Con el objetivo de optimizar la acci&oacute;n docente y, en consecuencia, elevar la calidad del proceso de ense&ntilde;anza-aprendizaje, se propone incorporar una serie de mejoras orientadas a la actualizaci&oacute;n tecnol&oacute;gica y metodol&oacute;gica del m&oacute;dulo. Entre ellas, destaca el uso de frameworks modernos y actuales, como WPF (Windows Presentation Foundation), que permitan al alumnado trabajar con entornos de desarrollo profesionales. Asimismo, se fomentar&aacute; el dise&ntilde;o y desarrollo de interfaces basadas en principios de usabilidad y accesibilidad, garantizando el cumplimiento de la normativa vigente en materia de accesibilidad digital. Se promover&aacute; tambi&eacute;n el empleo de herramientas de desarrollo actualizadas, que reflejen las tendencias del sector tecnol&oacute;gico. Finalmente, se impulsar&aacute; la creaci&oacute;n de aplicaciones orientadas a la resoluci&oacute;n de problemas reales, con el prop&oacute;sito de fortalecer las competencias profesionales del alumnado y facilitar su incorporaci&oacute;n al mercado laboral.</p>'),
(3372, 52, 23, '<p>La recogida de informaci&oacute;n relativa al progreso y rendimiento del alumnado se llevar&aacute; a cabo principalmente a trav&eacute;s de la plataforma educativa AULES, donde se registrar&aacute;n las diferentes actividades pr&aacute;cticas desarrolladas a lo largo de las unidades de programaci&oacute;n, as&iacute; como las calificaciones y observaciones correspondientes. En cuanto a las pr&aacute;cticas finales o ex&aacute;menes, estos se entregar&aacute;n por AULES y se podr&aacute;n evaluar de manera oral para certificar la autor&iacute;a del proyecto por parte del alumnado. En este &uacute;ltimo caso, los ex&aacute;menes f&iacute;sicos ser&aacute;n debidamente archivados y conservados en el departamento, garantizando as&iacute; la trazabilidad y la disponibilidad de la informaci&oacute;n para su consulta o revisi&oacute;n cuando sea necesario.</p>'),
(3374, 408, 7, '<p>El m&eacute;todo que se seguir&aacute; para el desarrollo de las clases ser&aacute; principalmente pr&aacute;ctico, ya que el presente curso tiene una orientaci&oacute;n en el saber hacer. M&aacute;s concretamente el desarrollo de las clases versar&aacute; sobre los siguientes principios:</p>\r\n<ul>\r\n<li>Exposici&oacute;n de conceptos te&oacute;ricos en clase a partir de los recursos que el profesor estime oportuno.</li>\r\n<li>Planteamiento de ejercicios y actividades en el aula de aquellos temas que lo permitan, resolvi&eacute;ndose aquellos que se estime oportuno.</li>\r\n<li>Presentaci&oacute;n en clase de las diversas pr&aacute;cticas a realizar y desarrollo en la misma de todas aquellas que el equipamiento permita.</li>\r\n<li>Realizaci&oacute;n de trabajos y exposiciones por parte del alumnado, de aquellos temas que se brinden a ello o que se propongan directamente por el profesor, con lo que se conseguir&aacute; una activa participaci&oacute;n y un mayor acercamiento a los conceptos y contenidos del curso.</li>\r\n</ul>\r\n<p>&nbsp;</p>'),
(3376, 276, 45, '<h4>DECRETO 114/2025, de 29 de julio, del Consell, por el que se establecen los curr&iacute;culos de los ciclos formativos de grado medio y de grado superior de Formaci&oacute;n Profesional, en aplicaci&oacute;n de la Ley org&aacute;nica 3/2022, de 31 de marzo, de ordenaci&oacute;n e integraci&oacute;n de la Formaci&oacute;n Profesional.</h4>\r\n<div class=\"imc--estat--link--box\">&nbsp;</div>'),
(3377, 16, 1, '<p style=\"text-align: justify;\">La siguiente programaci&oacute;n did&aacute;ctica tratar&aacute; de establecer los conceptos b&aacute;sicos te&oacute;ricos y pr&aacute;cticos, as&iacute; como los objetivos que se pretenden alcanzar en el desarrollo del m&oacute;dulo de Programaci&oacute;n que se imparte en el primer curso del Ciclo Formativo de grado superior de Desarrollo de Aplicaciones Web (DAW). El citado m&oacute;dulo tiene una duraci&oacute;n total de 256 horas.</p>'),
(3378, 16, 6, '<p class=\"western\" style=\"text-indent: 1cm; line-height: 100%; text-align: justify;\" align=\"justify\">En la siguiente tabla se especifican las unidades y el tiempo de clase asociado para la planificaci&oacute;n, y que de esta forma, coincidan los ex&aacute;menes de cada evaluaci&oacute;n de la modalidad semipresencial con la finalizaci&oacute;n aproximada de los temas. Adem&aacute;s, el proyecto final exige una presencialidad y un seguimiento diario en la modalidad presencial que no se tiene en la semipresencial, por lo que se pueden dedicar m&aacute;s semanas a ver con m&aacute;s calma otros contenidos:</p>\r\n<table style=\"margin-top: 0px; margin-bottom: 0px;\">\r\n<thead>\r\n<tr>\r\n<th style=\"border-width: 1px; border-style: solid; text-align: center;\" scope=\"col\">Temas</th>\r\n<th style=\"border-width: 1px; border-style: solid; text-align: center;\" scope=\"col\">Semanas</th>\r\n<th style=\"border-width: 1px; border-style: solid; text-align: center;\" scope=\"col\">Semanas</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; ;text-align: center;\">&nbsp;</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">Presencial</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">Semi</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">1. Toma de contacto con C#</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">2</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">2</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">2. Estructuras de control</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">4</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">4</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">3. Tipos de datos b&aacute;sicos</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">2</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">2</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">4. Arrays y estructuras</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">2</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">3</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">5. Funciones</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">3</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">3</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">6. Programaci&oacute;n Orientada a Objetos</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">5</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">6</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">7. Gesti&oacute;n din&aacute;mica de memoria</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">3</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">3</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">8. Ficheros</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">3</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">3</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">9. Bibliotecas de uso frecuente</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">2</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">2</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">10. Persistencia de objetos</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">1</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">1</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">11. Acceso a bases de datos relacionales</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">1</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">1</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">Proyecto final</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">3</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">2</td>\r\n</tr>\r\n<tr>\r\n<td style=\"border-width: 1px; border-style: none; text-align: center;\">&nbsp;</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">32</td>\r\n<td style=\"border-width: 1px; border-style: solid; text-align: center;\">32</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"western\" style=\"text-indent: 1cm; line-height: 100%; text-align: justify;\" align=\"justify\">Dicho tiempo de clase puede variar ligeramente en funci&oacute;n de los festivos que se tengan durante el curso, y de las caracter&iacute;sticas del grupo, que puede que requieran de alg&uacute;n d&iacute;a extra m&aacute;s en alg&uacute;n tema para terminar de afianzar conceptos.</p>\r\n<p class=\"western\" style=\"text-indent: 1cm; line-height: 100%; text-align: justify;\" align=\"justify\">En cuanto a la secuenciaci&oacute;n, se impartir&aacute;n las siguientes unidades en cada trimestre del curso:</p>\r\n<ul>\r\n<li class=\"western\" style=\"line-height: 100%; text-align: justify;\"><strong>1<sup>a</sup> evaluaci&oacute;n</strong><span style=\"font-weight: normal;\">: unidades 1 a 5 (presencial) y 1 a 4 (semipresencial)<br /></span></li>\r\n<li class=\"western\" style=\"line-height: 100%; text-align: justify;\"><strong>2<sup>a</sup> </strong><span style=\"font-weight: normal;\"><strong>evaluaci&oacute;n</strong>: unidades 6 a 8 (presencial) y 5 a 6 (semipresencial)<br /></span></li>\r\n<li class=\"western\" style=\"line-height: 100%; text-align: justify;\"><strong>3<sup>a</sup> </strong><span style=\"font-weight: normal;\"><strong>evaluaci&oacute;n</strong>: resto de unidades, junto con el proyecto final que se ir&aacute; planteando y desarrollando ya desde el inicio de la segunda evaluaci&oacute;n.</span></li>\r\n</ul>\r\n<p class=\"western\" style=\"line-height: 100%; text-align: justify;\" align=\"justify\"><span style=\"font-weight: normal;\">La diferencia de tiempos entre la modalidad presencial y semipresencial viene dada por la semana de ex&aacute;menes para la modalidad semipresencial, que suele ser una o dos semanas antes de cada evaluaci&oacute;n, dando menos tiempo para finalizar los temas previstos en cada evaluaci&oacute;n. En realidad, en la modalidad semipresencial el tema 5 se deja empezado antes de finalizar la primera evaluaci&oacute;n, y el tema 7 se comienza antes de finalizar la segunda.</span></p>\r\n<p class=\"western\" style=\"text-indent: 1cm; line-height: 100%; text-align: justify;\" align=\"justify\">&nbsp;</p>'),
(3379, 16, 7, '<p class=\"western\" style=\"text-indent: 1cm; line-height: 100%; text-align: justify;\" align=\"justify\">El m&eacute;todo que se seguir&aacute; para el desarrollo de las clases ser&aacute; el siguiente:</p>\r\n<ul>\r\n<li style=\"text-align: justify;\">Exposici&oacute;n de conceptos te&oacute;ricos en clase a partir de los apuntes y los materiales complementarios que el profesor estime convenientes para una mejor comprensi&oacute;n de los contenidos.</li>\r\n<li style=\"text-align: justify;\">Planteamiento de ejercicios y actividades en el aula de aquellos temas que lo permitan, resolvi&eacute;ndose aquellos que se estime oportuno.</li>\r\n<li style=\"text-align: justify;\">Presentaci&oacute;n en clase de las diversas pr&aacute;cticas a realizar y desarrollo en la misma de todas aquellas que el equipamiento permita.</li>\r\n<li style=\"text-align: justify;\"><span lang=\"es-ES\">Realizaci&oacute;n de trabajos y exposiciones por parte del alumnado, de aquellos temas que se brinden a ello o que se propongan directamente por el profesor,&nbsp;</span>con lo que se conseguir&aacute; una activa participaci&oacute;n y un mayor acercamiento a los conceptos y contenidos del m&oacute;dulo.</li>\r\n<li style=\"text-align: justify;\">En una etapa inicial del curso, se seguir&aacute; el m&eacute;todo tradicional de exposici&oacute;n por parte del profesor, con el fin de explicar los conceptos b&aacute;sicos que este m&oacute;dulo necesita para poder arrancar.</li>\r\n<li style=\"text-align: justify;\">Tan pronto como sea posible, la metodolog&iacute;a pasar&aacute; a ser fundamentalmente procedimental, con la realizaci&oacute;n de pr&aacute;cticas, invitando al alumno, bien individualmente o bien en grupo, a que exponga su planteamiento ante sus compa&ntilde;eros, para efectuar los pertinentes comentarios, intercambio de pareceres y discusi&oacute;n de las soluciones propuestas.</li>\r\n<li style=\"text-align: justify;\">En la medida de lo posible se tendr&aacute; una atenci&oacute;n individualizada por parte de los profesores a cada alumno o grupo de alumnos. Se fomentar&aacute; que cada uno plantee sus dudas o problemas sobre el ejercicio. Finalmente se comentar&aacute;n las posibles soluciones, as&iacute; como los fallos y errores que suelen cometerse de forma m&aacute;s habitual.</li>\r\n<li style=\"text-align: justify;\">En la modalidad semipresencial, la metodolog&iacute;a debe ser algo diferente, al carecer de horas de clase propiamente dichas. En este caso, la mayor parte del seguimiento se realizar&aacute; a trav&eacute;s del Aula Virtual. Se publicar&aacute; en dicha Aula el trabajo a realizar durante cada semana: apuntes de teor&iacute;a que leer y revisar, ejercicios a realizar, v&iacute;deos a visualizar. Cada semana las tutor&iacute;as colectivas se dedicar&aacute;n a resolver las dudas de car&aacute;cter general sobre las tareas a realizar esa semana, y a la explicaci&oacute;n de conceptos o problemas m&aacute;s complejos que requieran de dichas explicaciones. Tambi&eacute;n se dispondr&aacute; de horas de tutor&iacute;a individual para atender las dudas espec&iacute;ficas que tengan los alumnos sobre lo visto hasta ahora. Pero, a diferencia de la modalidad presencial, en este m&oacute;dulo es importante la parte autodidacta del alumnado, siendo el Aula Virtual la principal v&iacute;a de comunicaci&oacute;n, y las horas de tutor&iacute;a un complemento para repasar o solucionar lo que haya quedado menos claro.</li>\r\n</ul>'),
(3381, 16, 9, '<p class=\"western\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 100%; text-align: justify;\" align=\"left\">Para superar el m&oacute;dulo es necesario:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\">En la modalidad presencial, las ausencias a clase no superar&aacute;n el 15% del horario lectivo seg&uacute;n lo regulado en el Reglamento de R&eacute;gimen Interior de Centro.</li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\">No tener actitudes contrarias a las normas de convivencia.</li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\">Haber realizado satisfactoriamente las actividades programadas como indispensables por el profesor.</li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\">En el proyecto globalizador deber&aacute; haber obtenido al menos la calificaci&oacute;n de 5 sobre 10</li>\r\n</ul>\r\n<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\">En la modalidad presencial, la asistencia a clase es obligatoria (por ley), debido al elevado contenido pr&aacute;ctico del m&oacute;dulo, por tanto, aquellos alumnos que no asistan como m&iacute;nimo al 80% de las horas, no tendr&aacute;n derecho a la evaluaci&oacute;n continua y deber&aacute;n realizar un examen final de todo el m&oacute;dulo. Por ello, cada falta de asistencia&nbsp;<strong>no justificada </strong>se penalizar&aacute; rebajando en 0,25 puntos la nota de la correspondiente evaluaci&oacute;n, como forma efectiva de que un 15% de las faltas (15 horas de las casi 100 que integran cada evaluaci&oacute;n) supongan un suspenso casi autom&aacute;tico en la evaluaci&oacute;n en cuesti&oacute;n.</p>\r\n<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\">En la modalidad presencial, durante cada evaluaci&oacute;n se realizar&aacute;n frecuentes ejercicios con nota, como forma de comprobar la evoluci&oacute;n del alumnado. Al final de cada evaluaci&oacute;n se realizar&aacute;n actividades te&oacute;ricas y pr&aacute;cticas de evaluaci&oacute;n que ser&aacute; necesario superar (al menos obtener 5 sobre 10) para aprobar esa evaluaci&oacute;n. Deber&aacute;n presentarse a una prueba final en junio los alumnos cuya nota media del curso sea inferior a 5,00.</p>\r\n<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\">Con relaci&oacute;n al proyecto final, es importante insistir en que, como requisito IMPRESCINDIBLE para superar el m&oacute;dulo, se deber&aacute; completar el proyecto (y su memoria), de modo que el proyecto sea &ldquo;realmente utilizable&rdquo;, tenga un nivel de dificultad razonable para un proyecto final, y muestre buenas costumbres de programaci&oacute;n (en cuanto a estructuraci&oacute;n, uso de comentarios y limpieza de c&oacute;digo).</p>\r\n<p style=\"text-align: justify;\">En la modalidad semipresencial, las pr&aacute;cticas ser&aacute;n de dos tipos: unas de autocorrecci&oacute;n, donde pasado el plazo de finalizaci&oacute;n se publicar&aacute;n las soluciones en el Aula Virtual para que los propios alumnos revisen su pr&aacute;ctica, y otras (normalmente 2 por evaluaci&oacute;n) de correcci&oacute;n por parte del profesor. Las primeras no tendr&aacute;n calificaci&oacute;n asociada, sino que su realizaci&oacute;n es recomendable para llevar el m&oacute;dulo al d&iacute;a.<br /><br />Adem&aacute;s, en lo que se refiere a las pr&aacute;cticas en el caso de la modalidad semipresencial, se exigir&aacute; que dichas entregas cumplan un patr&oacute;n determinado, en cuanto a ficheros entregados, nombres de los mismos, y estructuraci&oacute;n en carpetas, para as&iacute; facilitar el proceso de correcci&oacute;n, y acostumbrar al alumnado a cumplir unas pautas de entrega que luego tambi&eacute;n se le podr&aacute;n exigir en otros m&oacute;dulos o en el mundo laboral. As&iacute;, y en cuanto a las pr&aacute;cticas corregidas por el profesor, la segunda entrega de pr&aacute;cticas que no cumpla los requisitos se evaluar&aacute; al 50% de la nota m&aacute;xima (es decir, se podr&aacute; obtener como mucho un 5), y a partir de la tercera entrega incorrecta, la nota en esa(s) pr&aacute;ctica(s) mal entregada(s) ser&aacute; de cero.<br /><br />En cuanto a la actitud en la modalidad semipresencial, obviamente no se puede valorar el comportamiento y participaci&oacute;n en clase, pero s&iacute; en los foros, de forma que se valorar&aacute;n positivamente tanto las preguntas meditadas y razonadas que se hagan, como las respuestas con cierta entidad, o comentarios que sean importantes. Quedan fuera de esta valoraci&oacute;n preguntas simples (por ejemplo, \"&iquest;C&oacute;mo se realiza el ejercicio X?\") y respuestas triviales (\"No lo s&eacute;\", \"Mira en esta web...\"), as&iacute; como cualquier otra forma de participaci&oacute;n que solo busque aparecer en el foro. Tambi&eacute;n se valorar&aacute; en el apartado de actitud la participaci&oacute;n (voluntaria) del alumnado en tareas que se puedan ir proponiendo (concursos o retos de programaci&oacute;n, olimpiadas inform&aacute;ticas, etc.).</p>'),
(3382, 16, 10, '<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">En la <strong>modalidad presencial</strong>, los baremos detallados son los siguientes:</span></span></span></p>\r\n<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">Calificaci&oacute;n de la </span><span style=\"font-size: medium;\"><strong>primera</strong></span><span style=\"font-size: medium;\"> evaluaci&oacute;n:</span></span></span></p>\r\n<ul style=\"text-align: justify;\">\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">80% nota ponderada de los ex&aacute;menes de la siguiente manera</span></span><br />\r\n<ul>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Examen temas 1,2 : 20%</span></span></li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Examen tema 3 : 20%</span></span></li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Examen tema 4: 30%</span></span></li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Examen tema 5: 30%</span></span></li>\r\n</ul>\r\n</li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">20% ejercicios evaluados realizados en clase</span></span></li>\r\n</ul>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">En todos los ex&aacute;menes se debe sacar al menos un 4 para hacer media con el resto.</span></span></p>\r\n<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">Calificaci&oacute;n de la </span><span style=\"font-size: medium;\"><strong>segunda </strong></span><span style=\"font-size: medium;\">evaluaci&oacute;n:</span></span></span></p>\r\n<ul style=\"text-align: justify;\">\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">80% media de los ex&aacute;menes realizados</span></span></li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">20% ejercicios evaluados realizados en clase</span></span></li>\r\n</ul>\r\n<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">Calificaci&oacute;n&nbsp;</span><span style=\"font-size: medium;\"><strong>final</strong></span><span style=\"font-size: medium;\">:</span></span></span></p>\r\n<ul style=\"text-align: justify;\">\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">80% de las evaluaciones, ponderadas de la siguiente forma:</span></span>\r\n<ul>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">20% primera evaluaci&oacute;n</span></span></li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">40% segunda evaluaci&oacute;n</span></span></li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">40% tercera evaluaci&oacute;n, que se puede desglosar como:</span></span>\r\n<ul>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">80% media de los ex&aacute;menes realizados</span></span></li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">20% ejercicios evaluados realizados en clase</span></span></li>\r\n</ul>\r\n</li>\r\n</ul>\r\n</li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">10% proyecto globalizador</span></span></li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">10% formaci&oacute;n en empresa</span></span></li>\r\n</ul>\r\n<p style=\"text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">En la <strong>modalidad semipresencial</strong>, se han procurado establecer unos criterios de calificaci&oacute;n que resulten equivalentes para los alumnos que siguen el curso puntualmente, y aquellos que deciden acudir directamente a las pruebas oficiales de junio. Por otra parte, se pretende que, aquellos alumnos que se examinen por parciales trimestrales, puedan conservar su nota, en caso de ser buena. As&iacute;, los baremos son los siguientes:<br /><br />En el caso de alumnos de <em><strong>seguimiento continuo</strong></em> y regular durante todo el curso:</span></span></p>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\"><strong>Calificaci&oacute;n de cada evaluaci&oacute;n:</strong></span></span></p>\r\n<ul>\r\n<li style=\"text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">90% nota de examen, donde:<br />Si la nota de una evaluaci&oacute;n es superior a la de alguna evaluaci&oacute;n anterior, autom&aacute;ticamente se asume esa nota para la evaluaci&oacute;n anterior con menos nota.<br />Si la nota de una evaluaci&oacute;n es inferior a la de alguna evaluaci&oacute;n anterior, el alumno conserva la nota de la antigua evaluaci&oacute;n sin verse disminuida por la nueva.<br />De esta forma, se premia a los alumnos que acuden a ex&aacute;menes de cada evaluaci&oacute;n y obtienen buena nota, y se da una nueva oportunidad de recuperar a los alumnos que no obtuvieron buenos resultados en evaluaciones previas pero luego obtienen mejores notas.</span></span></li>\r\n<li style=\"text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">10% ejercicios obligatorios realizados en el Aula Virtual<br /></span></span></li>\r\n</ul>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\"><strong>Calificaci&oacute;n final.</strong></span></span></p>\r\n<ul>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">15% nota de la primera evaluaci&oacute;n</span></span></li>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">35% nota de la segunda evaluaci&oacute;n</span></span></li>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">35% nota de la tercera evaluaci&oacute;n</span></span></li>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">15% proyecto final</span></span><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\"><br /></span></span></li>\r\n</ul>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">En el caso de alumnos que acudan directamente al <strong><em>examen final</em></strong>, su calificaci&oacute;n final ser&aacute;:<br /></span></span></p>\r\n<ul>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">90% examen y pr&aacute;cticas, de los cuales:</span></span>\r\n<ul>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">90% nota examen final</span></span></li>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">10% pr&aacute;cticas propuestas</span></span></li>\r\n</ul>\r\n</li>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">10% proyecto final</span></span></li>\r\n</ul>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\"><br />En ning&uacute;n caso se podr&aacute; aprobar una evaluaci&oacute;n si:<br /></span></span></p>\r\n<ul>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">La nota media de pr&aacute;cticas o ejercicios es inferior a 5.</span></span></li>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">La nota de ex&aacute;menes es inferior a 4.</span></span></li>\r\n<li><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">La nota de una de las pr&aacute;cticas o ejercicios es inferior a 3.<br /></span></span></li>\r\n</ul>\r\n<p style=\"text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">En cuanto a la actitud extra en la modalidad semipresencial, al no poder valorar comportamiento y actitud en clase, se valorar&aacute; la participaci&oacute;n activa en los foros, concursos de programaci&oacute;n y propuestas realizadas por los profesores del m&oacute;dulo.</span></span></p>\r\n<p style=\"text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\"><br />A efectos de la calificaci&oacute;n, tambi&eacute;n se debe tener en cuenta que la copia (de trabajos o en ex&aacute;menes) es considerada una falta grave, y se tomar&aacute;n las medidas oportunas en todas las partes implicadas.</span></span></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3383, 16, 11, '<p>Se dispone de diversidad de actividades de refuerzo y ampliaci&oacute;n por unidad did&aacute;ctica. Con este tipo de actividades pretendemos dar respuesta a los diferentes ritmos de aprendizaje que presentan los alumnos. Las actividades de refuerzo permitir&aacute;n que alumnos con un ritmo de aprendizaje menor lleguen a alcanzar las capacidades de la unidad, mientras que las actividades de ampliaci&oacute;n permitir&aacute;n que alumnos con un ritmo de aprendizaje mayor puedan profundizar en los contenidos de la unidad una vez alcanzadas las capacidades.</p>'),
(3385, 16, 13, '<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">En el bloque de programaci&oacute;n estructurada y orientada a objetos, dado que se trata de conocimientos claramente incrementales, en los que cada nuevo tema se apoya en los anteriores, no habr&aacute; actividades extraordinarias de recuperaci&oacute;n durante el curso: las posibles notas negativas se deber&aacute;n compensar con ejercicios y ex&aacute;menes posteriores (que, adem&aacute;s, tendr&aacute;n m&aacute;s ponderaci&oacute;n a medida que avance el curso). Si aun as&iacute;, alg&uacute;n alumno llega a final de curso sin haber logrado una media de aprobado, podr&aacute; realizar el examen final, en el que se le evaluar&aacute; de todos los conocimientos adquiridos a lo largo del curso. En caso de suspender dicho examen final, se propondr&aacute; al alumno una serie de actividades a realizar, y deber&aacute; realizar el examen de la convocatoria extraordinaria, tambi&eacute;n de todo el contenido de este bloque.</span></span></span></p>\r\n<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">Tanto en el caso de tener que realizar el examen de la convocatoria ordinaria como el de la convocatoria extraordinaria, el alumno deber&aacute; realizar tambi&eacute;n un proyecto final, con una carga lectiva de 30 horas, que ponga en pr&aacute;ctica la mayor parte de lo aprendido durante el curso. El contenido de dicho proyecto final deber&aacute; ser aceptado previamente por el profesor. Adem&aacute;s, el profesorado puede requerir que el alumno entregue algunas pr&aacute;cticas que tenga pendientes de aprobar.</span></span></span></p>\r\n<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">Concretando m&aacute;s el caso de la&nbsp;<strong>modalidad semipresencial:</strong></span></span></span></p>\r\n<ul style=\"text-align: justify;\">\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">En el examen de cada evaluaci&oacute;n se incluir&aacute;n conceptos de las evaluaciones anteriores, con lo que, superando dicho examen, se considerar&aacute; superado el de la evaluaci&oacute;n pasada que se tenga suspenso. Adem&aacute;s, se tendr&aacute; un examen final ordinario con todos los contenidos del m&oacute;dulo, que servir&aacute; tanto de recuperaci&oacute;n para quienes hayan suspendido alguna evaluaci&oacute;n como para quienes opten por la modalidad final y no se hayan presentado a alguno (o todos) los ex&aacute;menes trimestrales.</span></span></span></li>\r\n<li lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">En cuanto a las pr&aacute;cticas, se propondr&aacute;n pr&aacute;cticas de recuperaci&oacute;n de la 1&ordf; y 2&ordf; evaluaciones durante la tercera, para aquellos alumnos que no las entregaron en su d&iacute;a o no alcanzaron la nota m&iacute;nima exigible.</span></span></span></li>\r\n</ul>\r\n<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">Esto posibilitar&aacute; que los alumnos que no hayan podido llevar el m&oacute;dulo al d&iacute;a, y presentar los trabajos y ex&aacute;menes trimestrales, tengan tambi&eacute;n opci&oacute;n de superar el m&oacute;dulo, acumulando todo el trabajo exigido hasta el final de curso.&nbsp;</span></span></span></p>\r\n<p lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%; text-align: justify;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: small;\"><span style=\"font-size: medium;\">De cara a la evaluaci&oacute;n extraordinaria, se realizar&aacute; otro examen completo global para quienes no superaron el examen en la evaluaci&oacute;n ordinaria, y un proyecto final para quienes no superaron la parte pr&aacute;ctica y/o el proyecto final en la evaluaci&oacute;n ordinaria.</span></span></span></p>'),
(3386, 16, 14, '<p style=\"text-align: justify;\">En el caso de la modalidad presencial, el n&uacute;mero de horas del m&oacute;dulo impide que el alumnado lo tenga pendiente mientras cursa segundo.</p>\r\n<p style=\"text-align: justify;\">En el caso de la modalidad semipresencial, los alumnos con el m&oacute;dulo pendiente ser&aacute;n evaluados como si se tratara de una matriculaci&oacute;n ordinaria (y no un m&oacute;dulo pendiente), por lo que no cabe ninguna distinci&oacute;n respecto al resto de alumnos.</p>'),
(3387, 16, 20, '<p>En el citado Real Decreto, en su Art&iacute;culo 6, &ldquo;Ense&ntilde;anza biling&uuml;e&rdquo; se detalla que:</p>\r\n<p>El curr&iacute;culo de este ciclo formativo incorpora la lengua inglesa de forma integrada en al menos dos m&oacute;dulos profesionales de entre los que componen la totalidad del ciclo formativo. Estos m&oacute;dulos se impartir&aacute;n por el profesorado con atribuci&oacute;n docente en los mismos y que, adem&aacute;s, posea la habilitaci&oacute;n ling&uuml;&iacute;stica correspondiente al nivel B2 del Marco Com&uacute;n Europeo de referencia para las lenguas.</p>\r\n<p>Al objeto de garantizar que la ense&ntilde;anza biling&uuml;e se imparta en los dos cursos acad&eacute;micos del ciclo formativo de forma continuada se elegir&aacute;n m&oacute;dulos profesionales de ambos cursos.</p>\r\n<p>Los m&oacute;dulos susceptibles de ser impartidos en lengua inglesa son los se&ntilde;alados el anexo III.</p>\r\n<p>Con car&aacute;cter excepcional, y para quienes lo soliciten, en el caso de alumnos o alumnas con discapacidad que puedan presentar dificultades en su expresi&oacute;n oral (par&aacute;lisis cerebral, sordera...), se establecer&aacute;n medidas de flexibilizaci&oacute;n y/o alternativas en el requisito de impartici&oacute;n de m&oacute;dulos en lengua inglesa, de forma que puedan cursar todas las ense&ntilde;anzas de los m&oacute;dulos profesionales en su lengua materna.</p>\r\n<p>En el caso del ciclo de Desarrollo de Aplicaciones Web en el I.E.S. San Vicente, se ha optado por impartir en ingl&eacute;s el m&oacute;dulo de Entornos de Desarrollo. Por lo tanto, este aspecto no afecta durante el presente curso al m&oacute;dulo de Programaci&oacute;n. Aun as&iacute;, se tratar&aacute; de fomentar en los alumnos la consulta de materiales en ingl&eacute;s, mucho m&aacute;s abundantes que en castellano, e incluso la elaboraci&oacute;n en ingl&eacute;s de sus propios programas (nombres de variables y clases, comentarios, documentaci&oacute;n, etc).</p>'),
(3388, 16, 22, '<p class=\"p1\">Dentro del Plan de mejora del centro, la Comisi&oacute;n de Coordinaci&oacute;n Pedag&oacute;gica en reuni&oacute;n celebrada el 5 de septiembre de 2019, ha aprobado unos criterios de correcci&oacute;n ortogr&aacute;fica que deben ser aplicados en todas las &aacute;reas, materias y cursos. Tiene, por tanto, car&aacute;cter prescriptivo y&nbsp;<strong>son de obligado cumplimiento&nbsp;</strong>para todo el profesorado<strong>.</strong></p>\r\n<p class=\"p1\">Ciclos Formativos de Grado Superior:&nbsp;Penalizaci&oacute;n de 0,25 puntos por error gr&aacute;fico (0,15 por tilde), hasta un m&aacute;ximo de 2,5 puntos.</p>'),
(3389, 16, 27, '<p>Se ha realizado el tema 8 (ficheros) y repasado conceptos del tema 9 (librer&iacute;as adicionales) que ya se hab&iacute;an ido introduciendo a lo largo del curso.</p>\r\n<p>S&oacute;lo se han mencionado por encima los temas de Serializaci&oacute;n y Bases de datos.</p>\r\n<p>Como repaso de todos los temas del curso se realiza un proyecto integrador que este a&ntilde;o no es necesario para aprobar la asignatura como en a&ntilde;os anteriore. S&oacute;lo sirve para subir nota para aquellos que tienen aprobadas las 2 primeras evaluaciones. S&iacute; ser&aacute; necesario aprobar para aquellos que tengan alguna evaluaci&oacute;n suspendida.</p>'),
(3390, 16, 28, '<p>Los temas de Serializaci&oacute;n e integraci&oacute;n de bases de datos s&oacute;lo se han mencionado por encima pero no es necesario reforzar en segundo porque en 2 DAW no son necesarios estos conceptos. Los conceptos esenciales de programaci&oacute;n se han visto durante el curso y se han reforzado durante el tercer trimestre.</p>'),
(3391, 16, 29, '<p>Se realizar&aacute; la entrega de un proyecto integrador personalizado para cada alumno que se quiera presentar al examen que se realizar&aacute; mediante aules.</p>'),
(3392, 423, 41, ''),
(3393, 51, 45, ''),
(3394, 125, 1, '<p>El m&oacute;dulo de IPE I se imparte en el primer curso de todos los t&iacute;tulos LOE. Tiene una carga horaria de 90 horas lectivas, distribuidas en tres sesiones por semana. La presente programaci&oacute;n est&aacute; realizada para los ciclos formativos de Grado Superior de las familias profesionales de Inform&aacute;tica y Administraci&oacute;n y Gesti&oacute;n.</p>\r\n<p>Seg&uacute;n el art. 23 del RD 1147/2011 de ordenaci&oacute;n de la formaci&oacute;n profesional:</p>\r\n<ol>\r\n<li>Todos los ciclos formativos incluir&aacute;n la formaci&oacute;n necesaria para conocer las oportunidades de aprendizaje, las oportunidades de empleo, la organizaci&oacute;n del trabajo, las relaciones en la empresa, la legislaci&oacute;n laboral b&aacute;sica, as&iacute; como los derechos y deberes que se derivan de las relaciones laborales, para facilitar el acceso al empleo o la reinserci&oacute;n laboral en igualdad de g&eacute;nero y no discriminaci&oacute;n de las personas con discapacidad.</li>\r\n<li>Este m&oacute;dulo incorporar&aacute; la formaci&oacute;n en la prevenci&oacute;n de riesgos laborales, sin perjuicio de su tratamiento transversal en otros m&oacute;dulos profesionales, seg&uacute;n lo exija el perfil profesional.</li>\r\n<li>La formaci&oacute;n establecida en este m&oacute;dulo profesional capacita para llevar a cabo responsabilidades profesionales equivalentes a las que precisan las actividades de nivel b&aacute;sico en prevenci&oacute;n de riesgos laborales, establecidas en el Real Decreto 39/1997, de 17 de enero, por el que se aprueba el Reglamento de los Servicios de Prevenci&oacute;n.</li>\r\n<li>La concreci&oacute;n curricular de este m&oacute;dulo profesional estar&aacute; contextualizada a las caracter&iacute;sticas propias de cada familia profesional o del sector productivo correspondiente al t&iacute;tulo.</li>\r\n</ol>'),
(3395, 125, 2, '<h4 class=\"documento-tit\"><strong>Real Decreto 659/2023, de 18 de julio, por el que se desarrolla la ordenaci&oacute;n del Sistema de Formaci&oacute;n Profesional. cita en su art. 10<br /></strong></h4>\r\n<p class=\"parrafo\">Los centros del Sistema de Formaci&oacute;n Profesional aplicar&aacute;n los curr&iacute;culos establecidos por cada Administraci&oacute;n competente, adaptando su programaci&oacute;n y metodolog&iacute;as a las caracter&iacute;sticas de las personas en formaci&oacute;n, con especial atenci&oacute;n a las necesidades de aquellas que presenten una discapacidad o cualquier otra necesidad espec&iacute;fica, y teniendo en cuenta las posibilidades formativas del entorno productivo.</p>\r\n<p class=\"parrafo\">Las administraciones apoyar&aacute;n el desarrollo curricular y la adaptaci&oacute;n de los curr&iacute;culos por los centros, favoreciendo la elaboraci&oacute;n de modelos abiertos de programaci&oacute;n docente, con la implantaci&oacute;n de metodolog&iacute;as activas basadas en proyectos y retos, pr&oacute;ximas a la realidad productiva, y la utilizaci&oacute;n de recursos y materiales tecnol&oacute;gicos que garanticen la calidad y actualizaci&oacute;n de la formaci&oacute;n, mejoren el aprendizaje y atiendan a las distintas necesidades de cada persona en formaci&oacute;n.</p>\r\n<p>Consecuentemente, para desarrollar una programaci&oacute;n did&aacute;ctica correcta y &uacute;til para una adecuada formaci&oacute;n de los alumnos no se puede trabajar de espaldas a la realidad social y econ&oacute;mica en la que &eacute;stos viven.</p>\r\n<p>El centro en el que se contextualiza esta programaci&oacute;n es el IES San Vicente, situado en la localidad de San Vicente del Raspeig (Alicante). En este centro, se imparten los ciclos de la familia profesional de inform&aacute;tica, de administraci&oacute;n, y la FPB&aacute;sica de ambas familias.</p>\r\n<p>Junto con ello y en horario de ma&ntilde;ana en este centro se imparte E.S.O. y Bachillerato.</p>\r\n<p>El centro cuenta con los medios y recursos suficientes para el desarrollo tanto del ciclo formativo de forma general como del m&oacute;dulo de IPE I en particular. Concretamente los alumnos tienen a su disposici&oacute;n un aula de inform&aacute;tica en la que cuentan con un ordenador para cada uno as&iacute; como de acceso a Internet. Esta aula dispone tambi&eacute;n de proyector, pantalla y pizarra t&aacute;ctil, adem&aacute;s para desarrollar el m&oacute;dulo de IPE I contamos con un aula de teor&iacute;a.</p>\r\n<p>&nbsp;</p>\r\n<p class=\"parrafo\">&nbsp;</p>'),
(3396, 125, 6, '<p>La primera evaluaci&oacute;n comprender&aacute; las unidades del libro de texto&nbsp; de la 2 a la 6. La segunda evaluaci&oacute;n ir&aacute; desde la unidad 7 a la unidad 8. La tercera evaluaci&oacute;n comprender&aacute; las unidades 9, 1,10 y 11</p>'),
(3397, 125, 7, ''),
(3398, 125, 9, '<table cellspacing=\"0\" cellpadding=\"7\">\r\n<tbody>\r\n<tr>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #7ba0cd; border-right: 1px solid #ffffff; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Resultados de aprendizaje</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #ffffff; border-right: 1px solid #ffffff; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Criterios de evaluaci&oacute;n</strong></span></span></span></p>\r\n</td>\r\n</tr>\r\n<tr valign=\"top\">\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#d3dfee\">\r\n<p><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>1.</strong></span></span></span></span> <span style=\"color: #111111;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><span lang=\"es-ES\"><strong>Resultados de aprendizaj</strong></span></span></span></span><span style=\"color: #111111;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><span lang=\"es-ES\"><strong>e</strong></span></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">a</span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">) Se han analizado las principales oportunidades de empleo y de inserci&oacute;n laboral en el sector profesional, identificando las posibilidades de empleo y analizado sus requerimientos actuales para el perfil profesional. _1_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">b) Se ha comparado los diferentes requerimientos exigidos por el mercado laboral con las exigencias para el trabajo en la funci&oacute;n p&uacute;blica relacionados con el sector privado. _3_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">c) Se ha reflexionado sobre las actitudes y aptitudes requeridas actualmente para la actividad profesional relacionadas con el t&iacute;tulo, as&iacute; como las competencias personales y sociales m&aacute;s relevantes para el sector identificando nuestra zona de desarrollo pr&oacute;ximo. _1_%</span></span></span></span></span></p>\r\n<p><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>TODOS DUALIZAN </strong></span></span></span></p>\r\n</td>\r\n</tr>\r\n<tr valign=\"top\">\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#d3dfee\">\r\n<p><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>2. </strong></span></span></span></span> <span style=\"color: #111111;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><span lang=\"es-ES\"><strong>Resultados de aprendizaj</strong></span></span></span></span><span style=\"color: #111111;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><span lang=\"es-ES\"><strong>e</strong></span></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">a) Se ha valorado la importancia de la cultura preventiva en todos los &aacute;mbitos actividades de la empresa u organismo equiparado relacionado las condiciones laborales con la salud de la persona trabajadora identificando y clasificando los factores de riesgo en la actividad y los da&ntilde;os derivados de los mismos, especialmente las situaciones de riesgo m&aacute;s habituales en los entornos de trabajo del sector profesional relacionado con el t&iacute;tulo. _3_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">b) Se han clasificado y descrito los tipos de da&ntilde;os profesionales, con especial referencia a accidentes de trabajo y enfermedades profesionales, relacionados con el perfil profesional del t&iacute;tulo. 3%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">c) Se ha determinado la evaluaci&oacute;n de riesgos en la empresa u organismo equiparado y definido las t&eacute;cnicas de prevenci&oacute;n y de protecci&oacute;n que deben aplicarse para evitar los da&ntilde;os en su origen y minimizar sus consecuencias. _2_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">d) Se han analizado los protocolos de actuaci&oacute;n en caso de emergencia. 2_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">e) Se han determinado los principales derechos y deberes en materia de prevenci&oacute;n de riesgos laborales. 3__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">f) Se han clasificado las distintas formas de gesti&oacute;n de la prevenci&oacute;n en la empresa u organismo equiparado, en funci&oacute;n de los distintos criterios establecidos en la normativa sobre prevenci&oacute;n de riesgos laborales y determinado las formas de representaci&oacute;n de las personas trabajadoras en la empresa u organismo equiparado en materia de prevenci&oacute;n de riesgos.</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">3__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">g) Se ha valorado la importancia de la existencia de un plan preventivo en la empresa u organismo equiparado que incluya la secuenciaci&oacute;n de actuaciones a realizar en caso de emergencia y reflexionado sobre el contenido del mismo. _3_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">h) Se han determinado los requisitos y condiciones para la vigilancia de la salud de la persona trabajadora y su importancia como medida de prevenci&oacute;n. 3__%</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\">i) Se han identificado las t&eacute;cnicas b&aacute;sicas de primeros auxilios que han de ser aplicadas en el lugar del accidente ante distintos tipos de da&ntilde;os y la composici&oacute;n y uso del botiqu&iacute;n. 3__%</span></span></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\">\r\n<p><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>3.</strong></span></span></span></span></span> <span style=\"color: #111111;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>Resultados de aprendizaj</strong></span></span></span></span></span><span style=\"color: #111111;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>e</strong></span></span></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">a) Se han analizado los derechos y obligaciones derivados de la relaci&oacute;n laboral, as&iacute; como las condiciones de trabajo pactadas en un convenio colectivo aplicable al sector profesional relacionado con el t&iacute;tulo. _9_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">b) Se han comparado las principales modalidades de contrataci&oacute;n, localizando los diferentes modelos en las fuentes oficiales. _6_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">c) Se han identificado las caracter&iacute;sticas definitorias de los nuevos entornos de organizaci&oacute;n del trabajo y los derechos que conlleva. _1_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">d) Se han identificado los diferentes componentes del recibo de salario. _7_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">e) Se han identificado los recursos laborales existentes ante las diferentes vicisitudes que se pueden dar en la relaci&oacute;n laboral. 3% </span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">f) Se ha valorado el papel de la Seguridad Social como pilar esencial para la mejora de la calidad de vida de los ciudadanos. _7_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">g) Se han analizado las principales prestaciones derivadas de la suspensi&oacute;n y extinci&oacute;n de la relaci&oacute;n laboral. 7_%</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\">\r\n<p style=\"font-style: normal;\">&nbsp;4 Resultado de aprendizaje</p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">a) Se han evaluado los propios intereses, motivaciones, habilidades y destrezas en el marco de un proceso de autoconocimiento. _1_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">b) Se han analizado las cualidades y competencias personales afines a la actividad profesional relacionada con el perfil del t&iacute;tulo. _1_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">c) Se han determinado las competencias personales y sociales con valor para el empleo. 1__%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">d) Se han se&ntilde;alado las preferencias profesionales, intereses y metas en el marco de un proyecto profesional. _2_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">e) Se ha valorado el concepto de autoestima en el proceso de b&uacute;squeda de empleo. 1__%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">f) Se han identificado las fortalezas, debilidades, amenazas y oportunidades propias para la inserci&oacute;n profesional. 2__%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">g) Se han identificado expectativas de futuro para inserci&oacute;n profesional analizando competencias, intereses y destrezas personales. 2__%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">h) Se han valorado hitos importantes en la trayectoria vital con valor profesionalizador. _1_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">i) Se han identificado los itinerarios formativos profesionales relacionados con el perfil profesional. _3_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">j) Se han formulado objetivos profesionales y se ha determinado metas personales y profesionales para la mejora de la empleabilidad y las condiciones de inserci&oacute;n laboral. _3_%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">k) Se ha trazado un plan de acci&oacute;n para desarrollar las &aacute;reas de mejora y potenciar las fortalezas personales con valor para el empleo. _3_%</span></span></span></span></span></span></p>\r\n<p style=\"font-style: normal; font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr valign=\"top\">\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#d3dfee\">\r\n<p style=\"font-style: normal;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>5. <span style=\"color: #111111;\"><span style=\"font-size: medium;\">Resultados de aprendizaj</span></span><span style=\"color: #111111;\"><span style=\"font-size: medium;\">e</span></span></strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">a) Se ha tomado conciencia de la responsabilidad individual en el desarrollo profesional valorando la actitud de aprendizaje permanente para el desarrollo de propias y nuevas competencias. 0,25__% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">b) Se ha identificado la empleabilidad como capacidad de adaptaci&oacute;n al entorno laboral. 0.25_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">c) Se han conocido y utilizado herramientas, fuentes de informaci&oacute;n, conexiones y actividades para la configuraci&oacute;n de un entorno personal de aprendizaje para la empleabilidad. 0.25%</span></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">d) Se ha puesto en pr&aacute;ctica la competencia digital para configurar un entorno personal de aprendizaje para la empleabilidad. _0.25_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">e) Se ha analizado el concepto de identidad digital y su impacto en la empleabilidad. 0.5_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>AULA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">f) Se ha justificado el dise&ntilde;o de su entorno de aprendizaje basado en c&oacute;mo este mejora la empleabilidad. 0.5__% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>DUALIZA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">g) Se ha elaborado su plan de desarrollo individual como herramienta para la mejora de la empleabilidad. _1_%</span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong> AULA</strong></span></span></span></span> </span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">h) Se han aplicado las herramientas de aprendizaje aut&oacute;nomo para su desarrollo personal y profesional. _1_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>AULA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><span style=\"font-weight: normal;\">i) Se ha dise&ntilde;ado el entorno de aprendizaje que permite alcanzar el plan de desarrollo individual. _1_% </span></span></span></span></span><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>AULA</strong></span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\">&nbsp;</p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-style: normal;\"><strong>RESULTADO APRENDIZAJE 6:</strong></span></span></span></span></span></p>\r\n<p style=\"line-height: 100%; margin-bottom: 0.04cm;\">a) Se ha identificado y valorado el concepto de salud psicosocial como factor determinante del bienestar mental del individuo y de los entornos laborales saludables. 0,25%</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0.04cm;\">b) Se ha analizado la salud mental como desencadenante de siniestralidad y absentismo laboral, as&iacute; como su evoluci&oacute;n en los diferentes colectivos de trabajadores, especialmente en los grupos de poblaci&oacute;n joven 0,25%</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0.04cm;\">c) Se ha aprendido a reconocer e identificar los factores de riesgo psicosocial en el &aacute;mbito laboral.0,50%</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0.04cm;\">d) Se han identificado los diferentes tipos de da&ntilde;os derivados de los factores de riesgo psicosocial y su repercusi&oacute;n en los individuos y en las organizaciones, as&iacute; como su impacto en la competitividad y productividad de las empresas.1%</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0.04cm;\">e) Se han definido y delimitado los conceptos de estr&eacute;s laboral, tecnoestr&eacute;s y burnout como las principales consecuencias ante condiciones psicosociales desfavorables o adversas en el entorno laboral 1%</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0.04cm;\">f) Se han activado las estrategias de afrontamiento personal frente a los estresores derivados de las condiciones laborales as&iacute; como los recursos facilitadores del bienestar emocional de las personas a lo largo de su vida 1%</p>\r\n<p style=\"line-height: 100%; margin-bottom: 0.04cm;\">g) Se han determinado las medidas de intervenci&oacute;n a nivel social, empresarial y asistencial, que permitan la adecuada respuesta a las situaciones de conflicto en el &aacute;mbito laboral. 1%</p>\r\n<p style=\"font-style: normal; font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(3399, 125, 10, '<p>Se calificar&aacute; al alumno de uno a diez y la nota final saldr&aacute; de ponderar los resultados de aprendizaje:</p>\r\n<ul>\r\n<li>Un 70% las pruebas trimestrales de evaluaci&oacute;n, </li>\r\n<li>Un 20% trabajo en clase y en casa, tanto individual como grupal.</li>\r\n<li>Un 10% la actitud, trabajo, exposiciones de clase.</li>\r\n</ul>\r\n<p>Los alumnos tendr&aacute;n como actividades la visualizaci&oacute;n de pel&iacute;culas en casa con sus correspondientes fichas as&iacute; como la lectura de libros.</p>\r\n<p>Las faltas de ortograf&iacute;a bajar&aacute;n nota seg&uacute;n lo establecido en la normativa del centro.</p>\r\n<p>La no asistencia a clase en un porcentaje superior a un 15% del horario lectivo supondr&aacute; la p&eacute;rdida del derecho a la evaluaci&oacute;n continua tal y como se recoge en la normativa, salvo casos excepcionales a criterio del profesor. Las faltas que computar&aacute;n para calcular este porcentaje ser&aacute;n las no justificadas o aquellas cuya justificaci&oacute;n no es considerada v&aacute;lida por no constar organismo competente. Por otra parte, los retrasos o faltas de puntualidad tambi&eacute;n ser&aacute;n objeto de penalizaci&oacute;n por parte del profesor, consider&aacute;ndose un retraso como media falta de asistencia.</p>\r\n<p>Por otra parte, en los supuestos en los que la valoraci&oacute;n de los contenidos actitudinales del alumno sea muy negativa, la valoraci&oacute;n de los otros contenidos puede sufrir variaciones dando lugar a la evaluaci&oacute;n negativa del m&oacute;dulo, siendo necesaria la recuperaci&oacute;n de todos los contenidos.</p>\r\n<p>En <strong>la modalidad semipresencial</strong> la nota del examen ser&aacute; el 100% de la nota total del m&oacute;dulo. Los trabajos presentados en Aules por los alumnos a lo largo de todo el curso servir&aacute;n para subir nota. Podr&aacute; llegar a subir entre un 10 y un 20% de la nota en funci&oacute;n de las tareas presentadas y la participaci&oacute;n en tutor&iacute;as y foros.&nbsp;</p>\r\n<p>Las evaluaciones superadas liberar&aacute;n materia para la convocatoria ordinaria, que servir&aacute; de recuperaci&oacute;n para aquellos alumnos que hayan suspendido alguna de las evaluaciones.&nbsp;</p>\r\n<p>En la convocatoria extraordinaria se evaluar&aacute; el contenido del m&oacute;dulo en su totalidad.</p>'),
(3400, 125, 13, '<p>Las recuperaciones de las evaluaciones pendientes se realizar&aacute;n conforme a los siguientes criterios:</p>\r\n<ul>\r\n<li>La prueba, as&iacute; como su contenido, ser&aacute; seg&uacute;n determine el profesor.</li>\r\n<li>La calificaci&oacute;n m&aacute;xima que se puede obtener en la recuperaci&oacute;n ser&aacute; de un 5, si en el examen se obtiene hasta una puntuaci&oacute;n de hast 8&nbsp; &oacute; 6 si es superior a 8 puntos, en casos excepcionales de esfuerzo y trabajo del alumno, podr&iacute;a decidir el profesor subir esta nota de referencia a un 7.</li>\r\n</ul>\r\n<p><strong>La prueba extraordinaria de julio ser&aacute; SIEMPRE del contenido &iacute;ntegro del m&oacute;dulo de IPE I, no siendo posible examinarse en julio de evaluaciones sueltas, salvo circunstancias excepcionales que valorar&aacute; el profesor correspondiente o en su caso, el departamento.</strong></p>\r\n<p><strong>Las personas que en la prueba extraordinaria de julio no superen el m&oacute;dulo tendr&aacute;n que realizar las actividades propuestas por el departamento adem&aacute;s de presentarse a la prueba extraordinaria objetiva de conocimientos que se realizar&aacute; en Febrero-Marzo del curso siguiente.</strong></p>'),
(3401, 125, 11, ''),
(3402, 125, 15, ''),
(3403, 125, 16, '<p>El m&oacute;dulo de IPE I implementar&aacute; la parte que le corresponde del Programa de Fomento de la Lectura que desarrolla el centro. Estableciendo libros de lectura obligatoria.</p>\r\n<p>A t&iacute;tulo de ejemplo: La buena suerte de Fernando Tr&iacute;as de Bes y Francesc Rovira, El libro negro del emprendedor de Fernando Tr&iacute;as de Bes, El pez que no quiso evolucionar de Francisco Muro, La asertividad de Eva Bach, El caballero de la armadura oxidada de Robert Fisher, El guerrero pac&iacute;fico de Dan Millman, Qui&eacute;n se ha comido mi queso, de Spencer Johnson, El hombre que cambi&oacute; su casa por un tulip&aacute;n de Fernando Tr&iacute;as de Bes, 365 ideas para cambiar tu vida, Francesc Miralles, El mundo en tus manos de Elsa Punset, Br&uacute;jula para navegantes emocionales...y todos aquellos que el profesorado considere oportuno.</p>'),
(3404, 125, 17, '<p>Se trata de los apoyos y recursos que se utilizan para poder alcanzar los objetivos marcados. El profesor dejar&aacute; material a los alumnos para desarrollar los contenidos.</p>\r\n<p>Como manual se utilizar&aacute; el de la editorial Editex</p>\r\n<ul>\r\n<li><strong>Aula virtual:</strong>\r\n<ul>\r\n<li>A trav&eacute;s de la plataforma moodle Aules se colgar&aacute;n contenidos, actividades, pel&iacute;culas y diverso material que se utilizar&aacute; durante el curso</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<ul>\r\n<li><strong>Libros de lectura obligatoria.</strong></li>\r\n<li><strong>Pel&iacute;culas y documentales obligatorios.</strong></li>\r\n<li><strong>Otros recursos:</strong>\r\n<ul>\r\n<li>Art&iacute;culos de peri&oacute;dico.</li>\r\n<li>Modelaje (contratos, n&oacute;minas, documentos administrativos y contables, ...).</li>\r\n</ul>\r\n</li>\r\n</ul>'),
(3405, 125, 14, '<p>A los alumnos pendientes se les dise&ntilde;ar&aacute; un plan de recuperaci&oacute;n personal, y &nbsp;tendr&aacute;n que realizar las actividades propuestas por el departamento, entregarlas antes de la prueba extraordinaria y realizar esta.</p>'),
(3406, 125, 18, ''),
(3407, 125, 27, '<p>En la tercera evaluaci&oacute;n se han impartido los contenidos m&iacute;nimos y se han trabajado los &uacute;ltimos contenidos vistos en clase.</p>'),
(3408, 125, 28, '<p>Queda pendiente de impartir todo lo referente a Prevenci&oacute;n de Riesgos Laborales y el bloque de orientaci&oacute;n profesional, que se va a trabajar de forma voluntaria por parte del alumnado.</p>'),
(3409, 125, 29, '<p>El alumno ser&aacute; evaluado a trav&eacute;s de una prueba on line. Adem&aacute;s la profesora podr&aacute; requerir aquellos trabajos que considere oportuno como requisito para presentarse a la prueba on line.</p>'),
(3410, 125, 31, '<p>La comunicaci&oacute;n con el alumnado y las familias se llevar&aacute; a cabo a trav&eacute;s del correo corporativo gva, de las plataformas Itaca y Aules.</p>'),
(3411, 125, 32, '<p>Aules ser&aacute; la herramienta utilizada por los miembros del departamento de FOL para colgar todos los materiales complementarios al libro de texto as&iacute; como para recepcionar los trabajos y actividades.</p>\r\n<p>En caso de que sea conveniente o necesario por la situaci&oacute;n sanitaria ser&aacute; la herramienta que se utilizar&aacute; para hacer las pruebas objetivas de conocimientos o ex&aacute;menes.</p>'),
(3412, 125, 36, '<p>En caso de confinamiento o restricciones de movilidad que nos impidan la asistencia al centro educativo se utilizar&aacute; Teams para hacer v&iacute;deotutor&iacute;as.</p>'),
(3413, 125, 22, ''),
(3414, 125, 19, '');
INSERT INTO `contenidos_programaciones` (`id`, `idMateria`, `idApartado`, `texto`) VALUES
(3415, 125, 38, '<p>&nbsp;</p>\r\n<p data-start=\"176\" data-end=\"421\"><strong data-start=\"176\" data-end=\"189\">Objetivo:</strong> Aplicar los resultados de aprendizaje del m&oacute;dulo en un entorno real, desarrollando competencias personales, sociales, emocionales y emprendedoras, as&iacute; como habilidades para la innovaci&oacute;n y la sostenibilidad del sector productivo.</p>\r\n<h3 data-start=\"423\" data-end=\"453\">Contenidos y actividades</h3>\r\n<ul data-start=\"454\" data-end=\"977\">\r\n<li data-start=\"454\" data-end=\"575\">\r\n<p data-start=\"456\" data-end=\"575\">Participaci&oacute;n activa en proyectos y tareas del equipo, asumiendo responsabilidades y tomando decisiones cooperativas.</p>\r\n</li>\r\n<li data-start=\"576\" data-end=\"661\">\r\n<p data-start=\"578\" data-end=\"661\">Aplicaci&oacute;n de t&eacute;cnicas de comunicaci&oacute;n oral y escrita adaptadas a cada situaci&oacute;n.</p>\r\n</li>\r\n<li data-start=\"662\" data-end=\"784\">\r\n<p data-start=\"664\" data-end=\"784\">Gesti&oacute;n del tiempo, planificaci&oacute;n de actividades y resoluci&oacute;n de conflictos con flexibilidad e inteligencia emocional.</p>\r\n</li>\r\n<li data-start=\"785\" data-end=\"881\">\r\n<p data-start=\"787\" data-end=\"881\">Desarrollo de habilidades emprendedoras y colaboraci&oacute;n en procesos de innovaci&oacute;n sostenible.</p>\r\n</li>\r\n<li data-start=\"882\" data-end=\"977\">\r\n<p data-start=\"884\" data-end=\"977\">Uso de herramientas digitales para mejorar procesos de innovaci&oacute;n e investigaci&oacute;n aplicada.</p>\r\n</li>\r\n</ul>\r\n<h3 data-start=\"979\" data-end=\"995\">Evaluaci&oacute;n</h3>\r\n<ul data-start=\"996\" data-end=\"1279\">\r\n<li data-start=\"996\" data-end=\"1086\">\r\n<p data-start=\"998\" data-end=\"1086\">Observaci&oacute;n directa del desempe&ntilde;o en la empresa y grado de participaci&oacute;n en proyectos.</p>\r\n</li>\r\n<li data-start=\"1087\" data-end=\"1175\">\r\n<p data-start=\"1089\" data-end=\"1175\">Valoraci&oacute;n del trabajo en equipo, comunicaci&oacute;n, liderazgo y resoluci&oacute;n de problemas.</p>\r\n</li>\r\n<li data-start=\"1176\" data-end=\"1279\">\r\n<p data-start=\"1178\" data-end=\"1279\">Informe del tutor de empresa, coordinado con el profesor, sobre la aplicaci&oacute;n de competencias y RA.</p>\r\n</li>\r\n</ul>\r\n<center></center>'),
(3416, 125, 39, ''),
(3417, 125, 40, '<center>\r\n<table width=\"649\" cellspacing=\"0\" cellpadding=\"7\">\r\n<tbody>\r\n<tr>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #7ba0cd; border-right: 1px solid #ffffff; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"110\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Resultados de aprendizaje</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #ffffff; border-right: 1px solid #ffffff; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"386\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Criterios de evaluaci&oacute;n</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #7ba0cd; border-top: 1px solid #7ba0cd; border-bottom: 1px solid #7ba0cd; border-left: 1px solid #ffffff; border-right: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#7ba0cd\" width=\"108\">\r\n<p style=\"margin-top: 0.21cm;\" align=\"center\"><span style=\"color: #ffffff;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: medium;\"><strong>Unidades <br /> de trabajo</strong></span></span></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>1.</strong></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong> Distingue las caracter&iacute;sticas del sector productivo y define los puestos de trabajo relacion&aacute;ndolos con las competencias profesionales expresadas en el t&iacute;tulo</strong></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">.</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">__%</span></span></span></span></span></p>\r\n<p><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>DUALIZA 100%</strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">a</span></span></span></span></span><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">) Se han analizado las principales oportunidades de empleo y de inserci&oacute;n laboral en el sector profesional, identificando las posibilidades de empleo y analizado sus requerimientos actuales para el perfil profesional. __%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">b) Se ha comparado los diferentes requerimientos exigidos por el mercado laboral con las exigencias para el trabajo en la funci&oacute;n p&uacute;blica relacionados con el sector privado. __%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #c9211e;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">c) Se ha reflexionado sobre las actitudes y aptitudes requeridas actualmente para la actividad profesional relacionadas con el t&iacute;tulo, as&iacute; como las competencias personales y sociales m&aacute;s relevantes para el sector identificando nuestra zona de desarrollo pr&oacute;ximo. __%</span></span></span></span></span></p>\r\n<p><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><strong>TODOS DUALIZAN </strong></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"108\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>Unidad 1</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">. An&aacute;lisis del sector profesional</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal; margin-bottom: 0.04cm;\"><br /> </p>\r\n<p style=\"font-weight: normal;\">&nbsp;</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"background: #d3dfee; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#d3dfee\" width=\"110\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>2. Alcanza las competencias necesarias para la obtenci&oacute;n del t&iacute;tulo de T&eacute;cnico B&aacute;sico en Prevenci&oacute;n de Riesgos Laborales</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">.</span></span></span></span></span></p>\r\n<p><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">30</span></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong> %</strong></span></span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" valign=\"top\" bgcolor=\"#ffffff\" width=\"386\">\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">a) Se ha valorado la importancia de la cultura preventiva en todos los &aacute;mbitos actividades de la empresa u organismo equiparado relacionado las condiciones laborales con la salud de la persona trabajadora identificando y clasificando los factores de riesgo en la actividad y los da&ntilde;os derivados de los mismos, especialmente las situaciones de riesgo m&aacute;s habituales en los entornos de trabajo del sector profesional relacionado con el t&iacute;tulo. _4_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">b) Se han clasificado y descrito los tipos de da&ntilde;os profesionales, con especial referencia a accidentes de trabajo y enfermedades profesionales, relacionados con el perfil profesional del t&iacute;tulo. 4%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">c) Se ha determinado la evaluaci&oacute;n de riesgos en la empresa u organismo equiparado y definido las t&eacute;cnicas de prevenci&oacute;n y de protecci&oacute;n que deben aplicarse para evitar los da&ntilde;os en su origen y minimizar sus consecuencias. _3_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">d) Se han analizado los protocolos de actuaci&oacute;n en caso de emergencia. 3__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">e) Se han determinado los principales derechos y deberes en materia de prevenci&oacute;n de riesgos laborales. 4__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">f) Se han clasificado las distintas formas de gesti&oacute;n de la prevenci&oacute;n en la empresa u organismo equiparado, en funci&oacute;n de los distintos criterios establecidos en la normativa sobre prevenci&oacute;n de riesgos laborales y determinado las formas de representaci&oacute;n de las personas trabajadoras en la empresa u organismo equiparado en materia de prevenci&oacute;n de riesgos.</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"> <span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">3__%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">g) Se ha valorado la importancia de la existencia de un plan preventivo en la empresa u organismo equiparado que incluya la secuenciaci&oacute;n de actuaciones a realizar en caso de emergencia y reflexionado sobre el contenido del mismo. _3_%</span></span></span></span></span></p>\r\n<p style=\"margin-bottom: 0cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\">h) Se han determinado los requisitos y condiciones para la vigilancia de la salud de la persona trabajadora y su importancia como medida de prevenci&oacute;n. 3__%</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\">i) Se han identificado las t&eacute;cnicas b&aacute;sicas de primeros auxilios que han de ser aplicadas en el lugar del accidente ante distintos tipos de da&ntilde;os y la composici&oacute;n y uso del botiqu&iacute;n. 3__%</span></span></span></p>\r\n</td>\r\n<td style=\"background: #ffffff; border: 1px solid #7ba0cd; padding: 0cm 0.19cm;\" bgcolor=\"#ffffff\" width=\"108\">\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><strong>Unidad 2.</strong></span></span></span></span><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small;\"><span lang=\"es-ES\"><span style=\"font-weight: normal;\"> Seguridad y salud en el trabajo</span></span></span></span></span></p>\r\n<p style=\"font-weight: normal; margin-bottom: 0.04cm;\"><br /> </p>\r\n<p style=\"margin-bottom: 0.04cm;\"><span style=\"color: #000000;\"><span style=\"font-family: Calibri;\"><span style=\"font-size: small