(5153, 278, 55, '<p><strong>Grado Superior &ndash; Modalidad Presencial:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Prueba escrita: 70%</p>\r\n</li>\r\n<li>\r\n<p>R&uacute;brica, trabajos y actividades: 30%</p>\r\n</li>\r\n<li>N&uacute;mero de ex&aacute;menes: Uno por evaluaci&oacute;n</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li><strong>Grado Medio &ndash; Modalidad Presencial:</strong></li>\r\n</ul>\r\n<ul>\r\n<li>\r\n<p>Prueba escrita: 60%</p>\r\n</li>\r\n<li>\r\n<p>R&uacute;brica, trabajos y actividades: 40%</p>\r\n</li>\r\n<li>N&uacute;mero de ex&aacute;menes: Dos por evaluaci&oacute;n</li>\r\n</ul>\r\n<p><strong>Grado Superior &ndash; Modalidad Semipresencial:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Prueba escrita: 100% </p>\r\n</li>\r\n<li>N&uacute;mero de ex&aacute;menes: Uno por evaluaci&oacute;n</li>\r\n</ul>\r\n<p><strong>Nota m&iacute;nima para superar la evaluaci&oacute;n:</strong> 5 sobre 10.</p>\r\n<h3 class=\"western\"><strong>2. Condiciones generales para superar el m&oacute;dulo</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Es necesario obtener una <strong>nota igual o superior a 5 en todas las evaluaciones</strong> para superar el m&oacute;dulo.</p>\r\n</li>\r\n<li>\r\n<p>No se podr&aacute; aprobar una evaluaci&oacute;n si:</p>\r\n<ul>\r\n<li>\r\n<p>La <strong>nota media de los trabajos evaluables</strong> es inferior a 5, o</p>\r\n</li>\r\n<li>\r\n<p>La <strong>nota del examen</strong> es inferior a 5.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p>En caso de no alcanzar la calificaci&oacute;n m&iacute;nima en alguna evaluaci&oacute;n, el alumnado deber&aacute; <strong>recuperarla en la convocatoria ordinaria</strong>.</p>\r\n</li>\r\n</ul>\r\n<h3 class=\"western\"><strong>3. Convocatoria extraordinaria</strong></h3>\r\n<ul>\r\n<li>\r\n<p>Los alumnos que no superen el m&oacute;dulo en la convocatoria ordinaria se presentar&aacute;n a la convocatoria extraordinaria <strong>con toda la materia</strong>.</p>\r\n</li>\r\n<li>\r\n<p>Se deber&aacute;n <strong>realizar todos los trabajos propuestos</strong> durante el curso.</p>\r\n</li>\r\n<li>\r\n<p>Se realizar&aacute; una <strong>prueba te&oacute;rico-pr&aacute;ctica</strong> basada en los contenidos y trabajos del curso.</p>\r\n</li>\r\n<li>\r\n<p>Los alumnos que <strong>no entreguen los trabajos en los plazos establecidos</strong> no podr&aacute;n presentarse al examen extraordinario.</p>\r\n</li>\r\n</ul>'),
(5154, 278, 46, '<p>&nbsp;</p>\r\n<ul>\r\n<li data-start=\"147\" data-end=\"278\">\r\n<p data-start=\"150\" data-end=\"278\"><strong data-start=\"150\" data-end=\"166\">Metodolog&iacute;a:</strong> usar metodolog&iacute;as activas, retos, proyectos colaborativos y clase invertida; integrar herramientas digitales.</p>\r\n</li>\r\n<li data-start=\"279\" data-end=\"413\">\r\n<p data-start=\"282\" data-end=\"413\"><strong data-start=\"282\" data-end=\"297\">Contenidos:</strong> actualizar con casos reales, fomentar autoconocimiento y analizar itinerarios formativos y salidas profesionales.</p>\r\n</li>\r\n<li data-start=\"414\" data-end=\"522\">\r\n<p data-start=\"417\" data-end=\"522\"><strong data-start=\"417\" data-end=\"432\">Evaluaci&oacute;n:</strong> implementar r&uacute;bricas, autoevaluaci&oacute;n y evaluaci&oacute;n continua basada en proyectos y retos.</p>\r\n</li>\r\n<li data-start=\"523\" data-end=\"628\">\r\n<p data-start=\"526\" data-end=\"628\"><strong data-start=\"526\" data-end=\"558\">Actividades complementarias:</strong> m&aacute;s ferias, charlas, talleres pr&aacute;cticos y proyectos intermodulares.</p>\r\n</li>\r\n<li data-start=\"629\" data-end=\"743\">\r\n<p data-start=\"632\" data-end=\"743\"><strong data-start=\"632\" data-end=\"661\">Atenci&oacute;n a la diversidad:</strong> adaptar metodolog&iacute;as y materiales para alumnado con NEE o necesidades de apoyo.</p>\r\n</li>\r\n<li data-start=\"744\" data-end=\"883\">\r\n<p data-start=\"747\" data-end=\"883\"><strong data-start=\"747\" data-end=\"775\">Conexi&oacute;n con la empresa:</strong> aumentar la participaci&oacute;n de empresas locales y elaborar planes de itinerario profesional personalizados.</p>\r\n</li>\r\n</ul>\r\n<p>&nbsp;</p>'),
(5155, 278, 20, '<p>El ciclo de ASIR, se imparte en valenciano, el resto de ciclos fomativos de las diferentes familias en castellano</p>'),
(5157, 404, 55, '<p align=\"left\"><span lang=\"ES-TRAD\">Cada actividad ser&aacute; valorada num&eacute;ricamente entre 0 y 10 puntos</span></p>\r\n<p align=\"left\"><span lang=\"ES-TRAD\">&nbsp;</span><span lang=\"ES-TRAD\">La calificaci&oacute;n de CADA EVALUACI&Oacute;N se obtendr&aacute; ponderando las diferentes actividades de la siguiente manera:</span></p>\r\n<p align=\"left\"><span lang=\"ES-TRAD\">60%: Trabajos, exposiciones y proyectos en grupo</span><span lang=\"ES-TRAD\">. Se usar&aacute; la metodolog&iacute;a &aacute;gil </span><a href=\"https://www.thinkingwithyou.com/wp-content/uploads/2023/02/GuiaEduscrumEspanol.pdf\"><span lang=\"ES-TRAD\">eduScrum</span></a><span lang=\"ES-TRAD\"> para los trabajos en grupo.</span></p>\r\n<p align=\"left\"><span lang=\"ES-TRAD\">30%: Ex&aacute;menes </span><span lang=\"ES-TRAD\">sobre los contenidos de las unidades did&aacute;cticas, sobre la experiencia y la reflexi&oacute;n del alumnado en relaci&oacute;n con esos contenidos o con las actividades realizadas.</span></p>\r\n<p align=\"left\"><span lang=\"ES-TRAD\">10% Actitud y asistencia.</span></p>\r\n<p align=\"left\"><span lang=\"ES-TRAD\">Los porcentajes dentro de los m&aacute;rgenes indicados se podr&aacute;n adaptar en cada evaluaci&oacute;n seg&uacute;n los contenidos y las actividades realizadas.</span></p>\r\n<p align=\"left\"><span lang=\"ES-TRAD\">Se entender&aacute; que se ha superado la evaluaci&oacute;n si la nota obtenida despu&eacute;s del c&aacute;lculo descrito iguala o supera el 5.</span></p>\r\n<p align=\"left\"><span lang=\"ES-TRAD\">La NOTA FINAL del curso se obtendr&aacute; calculando la media aritm&eacute;tica de las tres evaluaciones.</span></p>\r\n<p align=\"left\"><span lang=\"ES-TRAD\">OTRAS NOTAS IMPORTANTES SOBRE LA EVALUACI&Oacute;N:</span> </p>\r\n<p align=\"left\"><!-- [if !supportLists]-->1.&nbsp;&nbsp;&nbsp;&nbsp; <!--[endif]--><span lang=\"ES-TRAD\">En todas las tareas y actividades que se realicen de forma presencial distintas de los controles, se reservar&aacute;n 1 punto de los 10 de la calificaci&oacute;n para valorar la capacidad de trabajo en equipo, la participaci&oacute;n, la iniciativa, el respeto y la colaboraci&oacute;n para un buen ambiente de trabajo. Las faltas de comportamiento y las faltas de asistencia podr&aacute;n tenerse en cuenta hasta hacer perder ese punto.</span></p>\r\n<p align=\"left\"><!-- [if !supportLists]-->2.&nbsp;&nbsp;&nbsp;&nbsp; <!--[endif]--><span lang=\"ES-TRAD\">En las pruebas escritas y en los ejercicios redactados individualmente por el alumnado se prestar&aacute; especial atenci&oacute;n a la expresi&oacute;n correcta, el empleo adecuado de los conceptos estudiados y la capacidad de relacionar los contenidos que se eval&uacute;an con los del resto de la asignatura, con los de otras materias y con los hechos y realidades del contexto social y econ&oacute;mico. Tambi&eacute;n se valorar&aacute; el empleo de las tecnolog&iacute;as de la informaci&oacute;n y la capacidad de di&aacute;logo y de trabajo en equipo cuando sea el caso.</span></p>\r\n<p align=\"left\"><!-- [if !supportLists]-->3.&nbsp;&nbsp;&nbsp;&nbsp; <!--[endif]--><span lang=\"ES-TRAD\">No se admitir&aacute;n trabajos fuera del plazo</span><span lang=\"ES-TRAD\"> establecido salvo en casos de fuerza mayor.</span></p>\r\n<p align=\"left\">&nbsp;<!-- [if !supportLists]-->4.&nbsp;&nbsp;&nbsp;&nbsp; <!--[endif]--><span lang=\"ES-TRAD\">Atendiendo al Plan de Mejora del centro, se aplicar&aacute;n los criterios ortogr&aacute;ficos en la correcci&oacute;n de trabajos y controles de la siguiente manera:</span></p>\r\n<p align=\"left\"><span lang=\"ES-TRAD\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0,10 puntos de penalizaci&oacute;n por cada error ortogr&aacute;fico y 0,05 por cada tilde hasta un m&aacute;ximo de 1,5</span><span lang=\"ES-TRAD\"> puntos</span><span lang=\"ES-TRAD\">.</span></p>');
INSERT INTO `criterios_evaluacion` (`idRA`, `codigo`, `texto`) VALUES
(1, 'a', 'Se han identificado las características generales de los lenguajes de marcas.'),
(1, 'b', 'Se han reconocido las ventajas que proporcionan en el tratamiento de la información.'),
(1, 'c', 'Se han clasificado los lenguajes de marcas e identificado los más relevantes.'),
(1, 'd', 'Se han diferenciado sus ámbitos de aplicación.'),
(1, 'e', 'Se ha reconocido la necesidad y los ámbitos específicos de aplicación de un lenguaje de marcas de propósito general.'),
