INSERT INTO `profesores` (`id`, `nombre`, `abreviatura`, `usuario`, `clave`, `idEspecialidad`, `grupo`, `orden`, `observaciones_horario`, `email`, `idDepartamento`, `jefe_departamento`, `activo`, `telefono`) VALUES
(1, 'Fernando Ruiz Rico', 'FRUI', 'fruiz', '29ce9ffe4a1cab3c48f9b42f7657fc1a', 'INF', 'PS', 4, 'Si puede ser el día que tenga clase por la mañana, no tenga por la tarde.Me gustarí­a entrar pronto por las mañanas.  Las horas de la tarde a media tarde (sobre las 5) y si puede ser en días distintos a los de Mari Chelo.', 'fernando@iessanvicente.com', 1, 1, 1, '667 92 16 60'),
(2, 'Nacho Cabanes Andreu', 'NCAB', 'ncabanes', 'ee1ea0585ea180f4301723bbf7485c30', 'INF', 'PS', 7, 'A ser posible, no las dos primeras horas de la mañana, para poder llevar a la princesa al colegio, y porque tendré que venir una tarde', NULL, 1, 0, 1, '649 24 22 23'),
(3, 'Juan Carlos Fuentes Miralles', 'JCFU', 'jcfuentes', 'd23bc9302a0a14d58e48ff33834a715b', 'SAI', 'PT', 12, 'Evitar últimas horas de la tarde, preferible primeras horas de la tarde. Juntar ambas jornadas en mañana y tarde .', 'juancarlos@iessanvicente.com', 1, 0, 1, '667640074'),
(4, 'Arturo Bernal Mayordomo', 'ABER', 'abernal', '4548e328335c8774d4775cee852c6079', 'SAI', 'PT', 14, 'Por la mañana preferiría horas intermedias. Sobre todo no primeras horas ya que comparto módulo de Cliente de DAW con Rosa Medina y no habría nadie para llevar a los niños al colegio.\r\nPor la tarde prefiero primeras horas para gestionar las extraescolares de los niños, y no coincidir con la hora de semipresencial que tiene Rosa Medina.', 'arturo@iessanvicente.com', 1, 0, 1, '656 68 57 16'),
(7, 'Marí­a Consuelo Rubio Sánchez', 'MRUB', 'mcrubio', '7cf220825f710fdd2a787bb07168acfc', 'INF', 'PS', 8, 'Prefiero dar clase las primeras horas de la mañana.\r\nPrefiero no tener clase por la mañana cuando tenga por la tarde. Si puede ser todo en una sola tarde mejor. Gracias.', 'marichelo@iessanvicente.com', 1, 0, 1, '670 33 26 38'),
(8, 'Antoni Salort Frasés', 'ASAL', 'tsalort', 'a8bbce81611f6adf58cbd2aff567b610', 'INF', 'PS', 6, 'Las horas de FCT todas seguidas, el lunes por la mañana, o el viernes por la mañana. \r\nEn caso de tener clases de mañana y de tarde el mismo día, prefiero no tenerlas seguidas.\r\nGracias.\r\n', 'toni@iessanvicente.com', 1, 0, 1, '657 14 03 76'),
(9, 'Francisco Garcí­a Muñoz', 'FGAR', 'fgarcia', '8c2ba0f21717253131d5d66a61154226', 'INF', 'PS', 2, 'Las horas de semi presencial prefiero PRIMERAS HORAS de la tarde Y ÚLTIMAS HORAS DE LA MAÑANA para que se junte con el turno de tarde (lo necesito también por motivos de otro trabajo para el que solicito compatibilidad todos los años). Las guardias por la tarde please.', 'fran@iessanvicente.com', 1, 0, 1, '667 22 45 56'),
(10, 'Álvaro Pérez Díez', 'APER', 'aperez', '5d423950f9960566cb5ef5b272e94c52', 'INF', 'PS', 17, '- Me gustaría entrar lo más tarde posible de lunes a jueves.\r\n - Y tener la mayor carga horaria los viernes por la tarde. ', 'alvaro@iessanvicente.com', 1, 0, 1, '658076072'),
(11, 'Sergi Aracil Pérez', 'SARA', 'saracil', '527d67483c4248b65ed92e898a6a5187', 'INF', 'PS', 16, 'A ser possible començar prompte les classes, a les 15:05.   \r\n', 'sergiaracil@iessanvicente.com', 1, 0, 1, '619 96 86 05'),
(12, 'Alejandro Amat Reina', 'AAMA', 'aamat', '0f78de79b18063abd4aeeb11a2e323e2', 'INF', 'PS', 13, 'Si puede ser me vendrí­a bien que mis horas de la mañana fueran al principio de la mañana y mis horas de la tarde al principio de la tarde. Si puede ser juntar las horas de la mañana con las de la tarde, aunque quede un hueco de una hora para comer.  Agradecería que en los módulos de DAM/DAW hayan bloques de 3 horas y no dejemos una hora suelta, en una hora no da tiempo a hacer nada. \r\nMuchas Gracias.', 'alex@iessanvicente.com', 1, 0, 1, '615 41 51 21'),
(13, 'Javier Carrasco Navarro', 'JCAR', 'jcarrasco', 'aaa209f81dea8aef44df479bc06db625', 'INF', 'PS', 5, 'La hora de mañana de semi, en la medida de lo posible, a últimas horas de la mañana.\r\nTambién serí­a interesante que el módulo de 4 horas pudiese impartirse como 2+2 y las horas de DAM/DAW seguidas.', 'javier@iessanvicente.com', 1, 0, 1, '619 82 04 79'),
(15, 'Javier Ivorra Torres', 'JIVO', 'jivorra', '9c616d9f49b520ed3d6733506555e1c1', 'INF', 'PS', 18, '-  Entrar a primera hora y salir lo antes posible, sobre todo martes y jueves.\r\n- Las horas de la mañana de los módulos semipresenciales, si es posible, ponerla a última hora (14:05) o a la anterior (13:10)\r\nMuchas gracias de antemano.', 'jivorratorres@gmail.com', 1, 0, 1, '637876144'),
(16, 'José Francisco Colom López', 'JCOL', 'jfcolom', '295d4ec203cb8bb7dbea03e4f92c4610', 'INF', 'PS', 22, 'Preferencia general: comenzar a las 7:55, gracias', 'jfcolom@iessanvicente.com', 1, 0, 1, '645861985'),
(23, 'Antonio Rodrí­guez Bas', 'AROD', 'arodriguez', 'b0baee9d279d34fa1dfd71aadb908c3f', 'SAI', 'PT', 15, 'Entrar todos los dí­as a las 10:40 horas para poder dejar a las niñas en el colegio.\r\nSalir todos los días a las 15:55(excepto miércoles) para poder recoger a las niñas del colegio.\r\nLas clases del semipresencial en el turno de tarde a ser posible a primeras horas(niñas cole),pero si no fuera posible, los viernes por la tarde podrí­a impartirlas de 15:05 hasta 18:50.\r\n\r\nSi fuera posible, me gustarí­a tener las horas pegadas en el turno de mañana y de tarde.\r\n\r\nGracias.', 'antonio@iessanvicente.com', 1, 0, 1, '655 47 32 91'),
(24, 'Mario Garcí­a Alcázar', 'MGAR', 'mgarcia', 'ed146b49ccf1e8609c3974bda89d8467', 'SAI', 'PT', 20, 'Prefiero no entrar a primeras horas ya que tengo un niño pequeño y tengo que cuadrar el horario con mi mujer ', 'mario@iessanvicente.com', 1, 0, 1, '606 33 72 49'),
(27, 'Jana Taboada León', 'JTAB', 'jtaboada', 'f4eacf1deee8eba9db6908838993ff59', 'SAI', 'PT', 24, 'Me gustaría poder entrar a partir las 9:45 para poder llevar a los niños al colegio. También me gustaría tener una mañana sin clase lectivas o bien un día tenerlas de 13 a 15 para poder reunirme con las empresas.', 'jana@iessanvicente.com', 1, 1, 1, '605 03 77 87'),
(28, 'Nacho Iborra Baeza', 'NIBO', 'niborra', '1527bc71d40ae5cdf9f1c406b1827500', 'INF', 'PS', 21, 'Me gustarí­a empezar a partir de las 15 cuando sea posible. Las guardias que me correspondan, repartidas entre mañana y tarde. La hora de proyecto del semi, en horario de mañana', 'nachoiborra@iessanvicente.com', 1, 0, 1, '645 15 26 56'),
(34, 'Nuria Tevar', 'TEVA', 'ntevar', '9ba904fe456d6ab034b9f7df36223948', 'FOL', 'PS', 1, '', NULL, 2, 0, 1, NULL),
(45, 'Ana María López Moya', 'AMLOPEZ', 'amlopez', '857f6b5269b8685962eabe0ff7efcb91', 'TEC', 'PS', NULL, '', NULL, 4, 1, 1, NULL),
