(4, 0, 25, 204, '<p><span data-contrast=\"auto\">Esta programaci&oacute;n de aula est&aacute; basada en la propuesta did&aacute;ctica del departamento para la asignatura.&nbsp;</span><span data-ccp-props=\"{&quot;134233117&quot;:true,&quot;134233118&quot;:true,&quot;335551550&quot;:6,&quot;335551620&quot;:6}\">&nbsp;</span></p>\r\n<p><span data-contrast=\"auto\">El desarrollo completo de cada Situaci&oacute;n de Aprendizaje, incluidas las actividades que se realizan y que, por tanto, permiten obtener las competencias, est&aacute;n subidas en un curso dentro de la plataforma Aules:  </span><span data-ccp-props=\"{&quot;134233117&quot;:true,&quot;134233118&quot;:true,&quot;335551550&quot;:6,&quot;335551620&quot;:6}\">&nbsp;</span></p>\r\n<p><a href=\"https://aules.edu.gva.es/eso03/course/view.php?id=333740\"><span data-contrast=\"none\">https://aules.edu.gva.es/eso03/course/view.php?id=333740</span></a><span data-contrast=\"auto\">.</span><span data-ccp-props=\"{&quot;134233117&quot;:true,&quot;134233118&quot;:true,&quot;335551550&quot;:6,&quot;335551620&quot;:6}\">&nbsp;</span></p>'),
(7, 0, 20, 194, ''),
(8, 0, 43, 179, '');
