(890, 404, 4, 'Definir metas realistas, ajustadas al conocimiento de sí mismo, utilizando la información relevante para resolver la incertidumbre y adoptar una actitud proactiva en la toma de decisiones personales, académicas y profesionales.', 0, 20, 1),
(891, 404, 5, 'Diseñar un proyecto personal, académico y profesional propio conjugando las necesidades e intereses personales y vocacionales con las oportunidades del entorno y las destrezas necesarias en la toma de decisiones.', 0, 20, 1),
(900, 161, 1, 'Identifica los conceptos básicos sobre seguridad y salud en el trabajo en el sector productivo asociado al perfil profesional.', 0, 9, 1),
(901, 161, 2, 'Evalúa los riesgos derivados de su actividad, analizando las condiciones de trabajo y los factores de riesgo presentes en su entorno laboral.', 5, 12, 1),
(902, 161, 3, 'Aplica las medidas de prevención y protección, analizando las situaciones de riesgo en el entorno laboral del título profesional básico.', 5, 12, 1),
(903, 161, 4, 'Desarrolla actividades de autoconocimiento que le permiten orientarse a campos profesionales motivadores en los que puede desplegar todas sus capacidades.', 0, 17, 1),
(904, 161, 5, 'Desarrolla habilidades sociales concretas que se han demostrado como fundamentales a la hora de encontrar un empleo y mantenerlo.', 5, 17, 1),
(905, 161, 6, 'Accede a la información de los posibles itinerarios académicos y/o profesionales que tiene a su alcance a través de la investigación y la reflexión libre de estereotipos vocacionales.', 5, 10, 1),
(906, 161, 7, 'Pone en marcha un itinerario propio analizando las distintas opciones educativas y profesionales, valorando las ventajas e inconvenientes de cada una de ellas y examinando aquellas que mejor se ajustan a sus posibilidades y preferencias.', 5, 10, 1),
(907, 161, 8, 'Conoce las estrategias de acceso al mercado de trabajo por cuenta ajena y utiliza las herramientas necesarias para el proceso de inserción laboral.', 0, 13, 1);
INSERT INTO `seguimiento_programaciones` (`id`, `idMateria`, `curso`, `evaluacion`, `temporalizacion`, `resultados`, `resultados_porcentaje`) VALUES
(4, 16, '2016/2017', 2, 'En la modalidad semipresencial, la secuenciaciÃ³n y temporalizaciÃ³n de unidades en este trimestre se ha visto alterada respecto a lo que venÃ­a siendo habitual, ya que, al adelantarse una semana la fecha tradicional de exÃ¡menes, y querer impartir el Tema 14 antes que otros aÃ±os, se ha movido el Tema 11 a los contenidos del tercer trimestre.\r\nEn la modalidad presencial, tambiÃ©n se ha realizado un ligero ajuste de temporizaciÃ³n, pero menor, al ser mÃ¡s fÃ¡cil aprovechar los dÃ­as sueltos que en la modalidad semipresencial.', 'En el caso de la modalidad semipresencial, se han tenido 74 alumnos matriculados en primer curso (36 del grupo A y 38 del B) , mÃ¡s otros 6 alumnos que han cursado el mÃ³dulo pertenecientes a segundo curso. De ellos, han aprobado el trimestre 13, lo que supone un porcentaje del 17,57%. Es un porcentaje bajo, y tambiÃ©n si lo comparamos con otros cursos anteriores. Incluso varios alumnos tienen pendientes de recuperar algunas prÃ¡cticas a estas alturas.\r\nEn la modalidad presencial:\r\nEn el grupo A han aprobado 11 de 25 alumnos matriculados lo que supone un 44% de aprobados. Un porcentaje bastante inferior a la evaluaciÃ³n anterior debido a que en esta evaluaciÃ³n se encuentran los contenidos mÃ¡s complicados del curso.\r\nEn el grupo B han aprobado 18 de 25, un 72% de los matriculados.', 34),
(5, 16, '2016/2017', 1, 'La secuenciaciÃ³n y temporalizaciÃ³n de unidades en este trimestre ha sido la habitual de otros aÃ±os (Temas 1 al 5) impartiÃ©ndose sin contratiempos.', 'En el caso de la modalidad semipresencial, se han tenido 74 alumnos matriculados en primer curso (36 del grupo A y 38 del grupo B), mÃ¡s otros 6 alumnos que han cursado el mÃ³dulo pertenecientes a segundo curso. De ellos, han aprobado el trimestre 25, lo que supone un porcentaje del 33.78%. Es un porcentaje bajo, pero teniendo en cuenta que en la modalidad semipresencial muchos alumnos tienden a abandonar al principio, entra dentro de lo normal.\r\nEn la modalidad presencial:\r\nEn el grupo A han aprobado 17 de 25 alumnos matriculados lo que supone un 68% de aprobados. Este alto porcentaje es debido a la simplicidad de los primeros temas de programaciÃ³n.\r\nEn el grupo B han aprobado 21 de 25 alumnos matriculados, un 84%.', 51),
(6, 71, '2016/2017', 1, 'Se han impartido las unidades de acorde lo establecido en la programaciÃ³n didÃ¡ctica. Las unidades vistas han sido:\r\nUnidad 1. Conceptos bÃ¡sicos de la seguridad informÃ¡tica\r\nUnidad 2. Seguridad pasiva. Hardware y almacenamiento\r\nUnidad 3. Seguridad Pasiva. RecuperaciÃ³n de datos\r\nUnidad 4. Sistemas de identificaciÃ³n. CriptografÃ­a', '\r\nHa habido una alta tasa de suspendidos principalmente porque no han realizado las tareas prÃ¡cticas de clase. Los alumnos no han mostrado interÃ©s por la asignatura aunque en todo momento se les ha intentado motivar.\r\nGrupo B:\r\nNÃºmero de alumnos: 24\r\nNÃºmero de aprobados: 13\r\n Lo que supone un 54% de aprobados.\r\n\r\nGrupo A:\r\nNÃºmero de alumnos: 25\r\nNÃºmero de aprobados: 6\r\nLo que supone un 24% de aprobados', 39),
(7, 51, '2016/2017', 3, 'La temporalizaciÃ³n ha sido la que se habÃ­a especificado en la programaciÃ³n didÃ¡ctica en la temporalizaciÃ³n inicial.\r\nPara el prÃ³ximo curso, se puede ver de meter material de Unity y reestructurar la segunda evaluaciÃ³n.', 'En el grupo de presencial, todos los alumnos que han entregado las prÃ¡cticas han superado el mÃ³dulo.\r\nEn el grupo de semipresencial, muy pocos alumnos han superado el mÃ³dulo, manifestando algunos de ellos la intenciÃ³n de superar la convocatoria extraordinaria de Junio.', 10),
(8, 12, '2016/2017', 3, 'La temporalizaciÃ³n ha sido la que se habÃ­a especificado en la programaciÃ³n didÃ¡ctica en la temporalizaciÃ³n inicial.\r\n', 'Todos los alumnos han superado la asignatura.', 100),
(9, 72, '2016/2017', 1, 'En los dos grupos se han impartido los contenidos indicados en la programaciÃ³n.', 'Una parte del alumnado sigue con interÃ©s el desarrollo del mÃ³ldulo. De entre ellos hay varios que requieren especial atenciÃ³n, porque si bien muestran interÃ©s, no trabajan lo suficiente y podrÃ­an aprobar. Una parte importante del alumnado no muestra ningÃºn interÃ©s en aprobar el mÃ³dulo y, aunque vienen a clase, han abandonado el mÃ³dulo \"de facto\". Se ha intentado que la presencia de este grupo no enturbie excesivamente la consecuciÃ³n de los objetivos por parte del alumnado interesado.\r\n\r\nEn el grupo A, el empleo del inglÃ©s como lengua vehicular ha requerido un esfuerzo extra por parte del alumnado y del profesor. Sin embargo, este punto no estÃ¡ impidiendo la consecuciÃ³n de los objetivos mÃ­nimos para aquellos alumnos que muestran ganas e intenciÃ³n de aprender.\r\n\r\nDe los mÃ¡s de 50 alumnos matriculados en ambos grupos sÃ³lo se han presentado al examen aproximadamente un 75%. El porcentaje de aprobados sobre los presentados es del 40%.', 40),
(10, 72, '2016/2017', 3, 'En los dos grupos se han impartido los contenidos indicados en la programaciÃ³n.', 'Una parte del alumnado sigue con interÃ©s el desarrollo del mÃ³ldulo. Una parte importante del alumnado sigue sin mostrar ningÃºn interÃ©s por el mÃ³dulo y, aunque vienen a clase, han abandonado el mÃ³dulo \"de facto\". Se ha intentado que la presencia de este grupo no enturbie excesivamente la consecuciÃ³n de los objetivos por parte del alumnado interesado.\r\n\r\nEn el grupo A, el empleo del inglÃ©s como lengua vehicular ha requerido un esfuerzo extra por parte del alumnado y del profesor. Sin embargo, este punto no estÃ¡ impidiendo la consecuciÃ³n de los objetivos mÃ­nimos para aquellos alumnos que muestran ganas e intenciÃ³n de aprender.\r\n\r\nDe los mÃ¡s de 50 alumnos matriculados en ambos grupos sÃ³lo se han presentado al examen aproximadamente un 65%. El porcentaje de aprobados sobre los presentados es del 45%.', 45),
(11, 118, '2016/2017', 1, 'Se ha impartido Ã­ntegramente el contenido de las unidades 1 y 2 (programaciÃ³n en Python)', 'El alumnado del grupo A-B-E ha mostrado en general mucho interÃ©s por el desarrollo de aplicaciones, y la mayorÃ­a ha adquirido con creces las capacidades propuestas.\r\nPor su parte, el grupo C-D muestra mayor interÃ©s por otros aspectos de la informÃ¡tica, por lo que se propone una mayor dedicaciÃ³n al resto de bloques de contenidos en las siguientes evaluaciones.', 100),
(12, 118, '2016/2017', 2, 'En el grupo A-B-E, se ha impartido Ã­ntegramente el bloque de programaciÃ³n, incluyendo una nueva unidad dedicada a las estructuras de datos en Python. AdemÃ¡s, han comenzado ha desarrollar pequeÃ±as aplicaciones en entorno web, cubriendo asÃ­ tambiÃ©n la unidad 5 del bloque 2.\r\nEn el grupo C-D se han estudiado superficialmente las unidades restantes del bloque de programaciÃ³n y se ha dedicado casi la totalidad del periodo al bloque de seguridad informÃ¡tica (unidad 7). Dicho bloque, se ha planteado con ejercicios que implican la difusiÃ³n de contenidos, cubriendo asÃ­ la unidad 6 del bloque 2.\r\n', 'El alumnado del grupo A-B-E ha mostrado en general mucho interÃ©s por el desarrollo de aplicaciones, y la mayorÃ­a ha adquirido con creces las capacidades propuestas. Seis alumnos de este grupo han solicitado participar en las olimpiadas informÃ¡ticas de la Universidad de Alicante. Sin embargo, por problemas de calendario de exÃ¡menes, solo uno de ellos ha podido participar efectivamente. \r\nPor su parte, el grupo C-D ha mostrado especial interÃ©s por la difusiÃ³n de contenidos empleando Wordpress, por lo que se ha potenciado esta vÃ­a para la adquisiciÃ³n de las capacidades propias de la asignatura.', 100),
(13, 17, '2016/2017', 1, 'Se ha cumplido la temporalizaciÃ³n prevista en la programaciÃ³n:\r\nUT 1. SISTEMAS DE ALMACENAMIENTO DE LA INFORMACIÃ“N \r\nUT 2. DISEÃ‘O CONCEPTUAL DE BASES DE DATOS \r\nUT 3. DISEÃ‘O LÃ“GICO DE BASES DE DATOS\r\n\r\n', '1Âº DAM semi B: Han habido un gran nÃºmero de suspensos debido a que los hay alumnos matriculados que no realizan las actividades del curso. NÃºmero de Alumnos: 36 NÃºmero de Aprobados: 10 \r\n1Âº DAM - A: Los resultados obtenidos no han sido buenos debido a que ha costado captar el paso de SI a ER debido a que no se han realizado ejercicios propuestos NÃºmero de alumnos: 25 NÃºmero de aprobados: 8\r\n1Âº DAM - B: Ha habido un gran nÃºmero de suspensos debido en buena parte a que los alumnos han encontrado muchas dificultades a la hora de interpretar los sistemas de informaciÃ³n y pasarlos a EER. NÃºmero de Alumnos: 28 NÃºmero de Aprobados: 11\r\n\r\n1ÂºDAM semi A: Ha habido un gran nÃºmero de suspensos debido a que  hay alumnos matriculados que no realizan las actividades del curso. NÃºmero de Alumnos: 46 NÃºmero de Aprobados: 11', 46),
(14, 17, '2016/2017', 2, 'Se han impartido las unidades de acorde lo establecido en la programaciÃ³n didÃ¡ctica. Las unidades vistas han sido: UT 4. DISEÃ‘O FÃSICO DE BASES DE DATOS \r\nUT 5. LENGUAJE MANIPULACIÃ“N DE UN SGBD \r\n', '1Âº DAM semi B: Han habido un gran nÃºmero de suspensos debido a que los hay alumnos matriculados que no realizan las actividades del curso. NÃºmero de Alumnos: 36 NÃºmero de Aprobados: 10 \r\n1Âº DAM - B Mayor nÃºmero de aprobados que en la primera evaluaciÃ³n debido, sobre todo, a que el lenguaje SQL entraÃ±a menor dificultad para el alumnado. NÃºmero de alumnos: 28 NÃºmero de aprobados:14\r\n\r\n1ÂºDAM semi A: Ha habido un gran nÃºmero de suspensos debido a que  hay alumnos matriculados que no realizan las actividades del curso. NÃºmero de Alumnos: 46 NÃºmero de Aprobados: 9\r\n1Âº DAM - Aumenta el numero de aprobados debido a que los alumnos realizan los ejercicios y se consigue asimilar la materia  NÃºmero de alumnos: 25 NÃºmero de aprobados: 15', 49),
(15, 71, '2016/2017', 3, 'Se han impartido las unidades de acorde lo establecido en la programaciÃ³n didÃ¡ctica. Las unidades vistas han sido:\r\nUnidad 5. Seguridad activa en el sistema\r\nUnidad 6. Seguridad activa en redes\r\nUnidad 7. Seguridad de alto nivel en redes: cortafuegos\r\nUnidad 8. Seguridad de alto nivel en redes: proxy', '\r\nHa habido una alta tasa de suspendidos principalmente porque no han realizado las tareas prÃ¡cticas de clase. Los alumnos no han mostrado interÃ©s por la asignatura aunque en todo momento se les ha intentado motivar.\r\nGrupo B:\r\nNÃºmero de alumnos: 24\r\nNÃºmero de aprobados: 10\r\nLo que supone un 43% de aprobados\r\nGrupo A:\r\nNÃºmero de alumnos: 25\r\nNÃºmero de aprobados: 7\r\nLo que supone un 28% de aprobados.\r\n', 35),
(16, 14, '2016/2017', 1, 'No se ha podido impartir todas las unidades planificadas para la esta evaluaciÃ³n. Las unidades que han sido vistas son:\r\nUT1: PRINCIPIOS DE SEGURIDAD Y ALTA DISPONIBILIDAD\r\nUT2: SEGURIDAD PASIVA. HARDWARE Y ALMACENAMIENTO\r\nUT3: SEGURIDAD PASIVA. RECUPERACIÃ“N DE DATOS\r\nUT4: CRIPTOGRAFÃA\r\n\r\nCon vistas al curso prÃ³ximo hay que reestructurar la secuenciaciÃ³n de contenidos, porque el temario es muy denso y no hay tiempo para tratar todos los puntos.\r\n', 'Han habido 2 suspensos. Uno debido a no haber superado el examen y otro por abandonar el mÃ³dulo y no entregar ningÃºn trabajo.\r\n\r\nNÃºmero de alumnos: 13\r\nNÃºmero de aprobados: 11\r\n', 84),
(17, 14, '2016/2017', 3, 'No se ha podido impartir todas las unidades planificadas para la esta evaluaciÃ³n. Las unidades que han sido vistas son:\r\nUT5: SEGURIDAD ACTIVA EN EL SISTEMA\r\nUT6: SEGURIDAD EN REDES CORPORATIVAS\r\nUT7: MALWARE\r\nUT8: SEGURIDAD PERIMETRAL. CORTAFUEGOS\r\nUT9: SEGURIDAD PERIMETRAL. PROXY\r\n\r\nCon vistas al curso prÃ³ximo hay que reestructurar la secuenciaciÃ³n de contenidos, porque el temario es muy denso y no hay tiempo para tratar todos los puntos.\r\n\r\nLas unidades que no se han podido tratar son:\r\nUT10: ALTA DISPONIBILIDAD\r\nUT11: LEGISLACIÃ“N Y NORMAS SOBRE SEGURIDAD\r\n', 'Han habido 1 suspenso. Debido a no entregar ningÃºn trabajo durante el curso.\r\n\r\nNÃºmero de alumnos: 13\r\nNÃºmero de aprobados: 12', 92),
(18, 52, '2016/2017', 1, 'Presencial, debido al permiso de paternidad del profesor y al no enviar sustituto desde Conselleria de EducaciÃ³n, no se ha podido completar los contenidos de esta evaluaciÃ³n.\r\n\r\nSemipresencial, se han impartido todas las unidades previstas para esta evaluaciÃ³n. ', 'Presencial, no se pudieron evaluar por la ausencia de profesor.\r\n\r\nSemipresencial, de los 38 alumnos matrÃ­culados solo se han presentado al examen 12 alumnos, de los cuales han aprobado 9. El porcentaje de aprobados sobre los presentados es del 75% pero 24% sobre el total.', 24),
(19, 52, '2016/2017', 3, 'Presencial, debido al permiso de paternidad del profesor y al no enviar sustituto desde Conselleria de EducaciÃ³n, no se ha podido completar los contenidos de esta evaluaciÃ³n.\r\n\r\nSemipresencial, se han impartido todas las unidades previstas para esta evaluaciÃ³n. ', 'Presencial, no se pudieron evaluar por la ausencia de profesor.\r\n\r\nSemipresencial, de los 38 alumnos matrÃ­culados solo se han presentado al examen 12 alumnos, de los cuales han aprobado 9. El porcentaje de aprobados sobre los presentados es del 75% pero 24% sobre el total.', 24),
(20, 18, '2016/2017', 1, 'Se han impartido todos los temas previstos en la programaciÃ³n (HTML y CSS), aunque ha habido que ir bastante rÃ¡pido para poder ver toda la materia. ', 'De 25 alumnos del grupo A (turno matutino) han aprobado 20 y suspendido 5. \r\nLas notas se reparten de la siguiente forma:\r\n- Sobresalientes: 7\r\n- Notables: 13\r\n- Suspendidos: 5 \r\n\r\n\r\nDe 24 alumnos del grupo B (turno vespertino) han aprobado 10 y suspendido 14. \r\nLas notas se reparten de la siguiente forma:\r\n- Sobresalientes: 2\r\n- Notables:3\r\n- Aprobados: 5\r\n- Suspendidos: 14 \r\nA los alumnos les ha parecido que el ritmo ha sido demasiado rÃ¡pido.\r\n\r\nAlumnos del grupo SEMIPRESENCIAL-A\r\nTotal alumnos: 44\r\nTotal aprobados: 7\r\n\r\nAlumonos del grupo SEMIPRESENCIAL-B\r\nTotal alumnos: 48\r\nTotal aprobados: 7\r\n\r\nAlumnos del grupo SEMIPRESENCIAL- pendientes\r\nTotal alumnos: 7\r\nTotal aprobados: 3\r\n', 32),
(21, 18, '2016/2017', 2, 'Los alumnos del grupo B (turno vespertino) se han quejado al tutor de que se va demasiado rÃ¡pido en el mÃ³dulo y que se exige demasiado trabajo para un mÃ³dulo de sÃ³lo 3 horas. Se habÃ­a planteado realizar un proyecto integrador para ver toda la parte de javascript, pero tras hablar con los alumnos hemos decidido que el proyecto sea opcional y que el que no haga el proyecto realizarÃ¡ un examen final. \r\nAnte la queja de los alumnos se ha reducido la velocidad de las clases, por lo que no nos ha dado tiempo a ver todo lo que tenÃ­amos planificado en la programaciÃ³n. Esto repercutirÃ¡ en la tercera evaluaciÃ³n, ya que tendremos que eliminar algo del temario. Se ha decidido que la parte que no se va a ver serÃ¡ PHP.\r\nEn esta segunda evaluaciÃ³n hemos empezado con javascript, aprovechando los conocimientos de programaciÃ³n que tenÃ­an los alumnos la parte de javascript bÃ¡sico se ha podido impartir mÃ¡s rÃ¡pidamente. DespuÃ©s nos hemos centrado, principalmente en el DOM y el BOM.\r\n\r\nGrupos de Semipresencial y ASIR\r\nSe ha impartido el bloque de Javascript, centrÃ¡ndonos principalmente en el DOM', 'En el grupo A (turno matutino) de 25 alumnos han aprobado 15 y suspendido 9. \r\nLas notas se reparten de la siguiente forma:\r\n- Sobresalientes: 6\r\n- Notables: 9\r\n- Aprobados: 5\r\n- Suspendidos: 5\r\n\r\n\r\nEn el grupo B (turno vespertino) de 24 alumnos han aprobado 15 y suspendido 9. \r\nLas notas se reparten de la siguiente forma:\r\n- Sobresalientes: 5\r\n- Notables: 4\r\n- Aprobados: 6\r\n- Suspendidos: 9\r\nLa principal causa por la cual los resultados han mejorado con respecto a la primera evaluaciÃ³n es que muchos alumnos han optado por realizar el proyecto (a pesar de que se quejaron al tutor de que era demasiado trabajo para un mÃ³dulo de tres horas), en lugar del examen. \r\n\r\nAlumnos del grupo semipresencial - A:\r\n-Total alumnos: 43\r\n-Total aprobados: 7\r\n\r\nAlumnos del grupo semipresencial -B:\r\n-Total alumnos: 48\r\n-Total aprobados: 4\r\n\r\nAlumnos del grupo semipresencial - pendientes:\r\n- Total alumnos: 7\r\n- Total aprobados: 3\r\n\r\n\r\n', 33),
(22, 70, '2016/2017', 1, 'Se han impartido todos los temas previstos en la programaciÃ³n (HTML y CSS), aunque ha habido que ir bastante rÃ¡pido para poder ver toda la materia. De 24 alumnos han aprobado 11 y suspendido 13. \r\n', 'Las notas se reparten de la siguiente forma:\r\n- Sobresalientes: 1\r\n- Notables: 2\r\n- Aprobados: 8\r\n- Suspendidos: 13\r\nLos malos resultados se deben principalmente al bajo nivel de base que tiene el grupo.', 46),
(23, 70, '2016/2017', 3, 'Inicialmente en la programaciÃ³n estaba previsto impartir wordpress y javascript bÃ¡sico, pero dado el bajo nivel del grupo y a peticiÃ³n de los propios alumnos se ha dedidido sustituir la parte de javascript por una introducciÃ³n a bootstrap. De 24 alumnos han aprobado 15, suspendido 7 y se han dado de baja 2 alumnos. \r\n', 'Las notas se reparten de la siguiente forma:\r\n- Sobresalientes: 0\r\n- Notables: 4\r\n- Aprobados: 11\r\n- Suspendidos: 7\r\nLos resultados han mejorado porque se ha trabajado por proyectos en lugar de por examen y porque los contenidos eran mÃ¡s sencillos y atractivos para los alumnos..', 68),
(24, 65, '2016/2017', 1, 'Se han impartido todos los temas planificados. Se ha trabajado por proyectos y se ha realizado un Ãºnico examen basado en uno de los proyectos que hicieron los alumnos.\r\nDe 22 alumnos han aprobado 4 han suspendido 4 y el resto no se ha presentado.', 'Las notas se reparten de la siguiente forma:\r\n- Sobresalientes: 1\r\n- Notables: 2\r\n- Aprobados: 0\r\n- Suspendidos: 4\r\n- No presentados 15\r\nSe expresa el porcentaje de aprobados en relaciÃ³n a los alumnos que han seguido el curso. El resto de alumnos no han dado seÃ±ales de vida.', 43),
(25, 65, '2016/2017', 3, 'Se han impartido todos los temas planificados, incluso ha dado tiempo a profundizar en algunos de los temas que no estaban programados. Se ha trabajado por proyectos y no se ha realizado ningÃºn examen. Los resultados obtenidos han sido muy satisfactorios con los alumnos que han terminado el curso, otros han decidido dejarlo para junio por temas de tiempo.\r\nDe 22 alumnos han aprobado 2 han suspendido 5 y el resto no se ha presentado.', 'Las notas se reparten de la siguiente forma:\r\n- Sobresalientes: 2\r\n- Notables: 0\r\n- Aprobados: 0\r\n- Suspendidos: 5\r\n- No presentados 15\r\nSe expresa el porcentaje de aprobados en relaciÃ³n a los alumnos que han seguido el curso. El resto de alumnos no han dado seÃ±ales de vida.', 29),
(26, 41, '2016/2017', 1, 'Nada destacable en la temporalizaciÃ³n de esta primera evaluaciÃ³n. \r\n\r\nQuizÃ¡ remarcar que el desarrollo de los tres primeros temas ha sido mÃ¡s rÃ¡pido que el programado ya que debido al retraso en el inicio del curso por la sustituciÃ³n de la profesora titular asÃ­ como que las clases no acaban en junio sino en mayo, era preciso reajustar las horas de cada tema para poder finalizar el temario en mayo y no en junio como estaba programado', 'El curso 1Âº A ha tenido una alta tasa de abandono por lo que el 50% de la clase consta como suspendido.\r\n\r\nEl grupo B ha tenido una tasa de aprobados del 22%.\r\n\r\n1Âº C ha sido un curso menos participativo pero con una tasa de suspendidos mucho menor que 1Âº A con cerca del 32%\r\n', 47),
(27, 110, '2016/2017', 1, 'Se ha impartido la unidad 1, y la unidad 2, previstas en la temporalizaciÃ³n', 'Algunos alumnos no entregan todas las tareas.', 80),
(28, 106, '2016/2017', 1, 'Se ha impartido la unidad 1, y la unidad 2, previstas en la temporalizaciÃ³n', 'Algunos alumnos no entregan todas las tareas.', 62),
(29, 106, '2016/2017', 2, 'Se ha impartido la unidad 3, y la unidad 5. La unidad 4 la hemos dejado para la evaluaciÃ³n 3, no previsto en la temporalizaciÃ³n.', 'Algunos alumnos no entregan todas las tareas. Algunos alumnos son absentistas.', 18),
(30, 106, '2016/2017', 3, 'Se ha impartido la unidad 4, y la unidad 6, no previsto en la temporalizaciÃ³n.', 'Algunos alumnos no entregan todas las tareas. Algunos alumnos son absentistas.', 18),
(31, 41, '2016/2017', 3, 'La tercera evaluaciÃ³n estaba programada para finalizar en junio, y dado que las clases han finalizado en mayo se ha tenido que ajustar la temporalizaciÃ³n de los temas 8,9 y 10 para poder finalizar toda la materia.', 'Ha ascendido ligeramente el nÃºmero de aprobados a un 56%, teniendo en cuenta que el resto de alumnos han dado la asignatura por perdida.\r\n\r\nEl grupo B ha tenido un 62% de aprobados.\r\n\r\nEl grupo C ha tenido mejores resultados con una tasa de aprobados de un 65% a pesar de que en esta Ãºltima evaluaciÃ³n algunos alumnos han abandonado la asignatura.', 61),
(32, 41, '2016/2017', 2, 'A pesar de haber adelantado el tema 4 a diciembre, en esta segunda evaluaciÃ³n se ha finalizado el tema 7 en abril tal y como estaba programado.', 'En 1Âº A sigue la alta tasa de abandonos con un 52% de suspendidos\r\n\r\nEn 1Âº B se incrementa ligeramente la tasa de aprobados hasta un 33%.\r\n\r\n1Âº C aumenta su tasa de suspendidos con cerca de un 48%', 44),
