eption Locked=\"false\" SemiHidden=\"true\" UnhideWhenUsed=\"true\"\r\n   Name=\"Mention\"/>\r\n  <w:LsdException Locked=\"false\" SemiHidden=\"true\" UnhideWhenUsed=\"true\"\r\n   Name=\"Smart Hyperlink\"/>\r\n </w:LatentStyles>\r\n</xml><![endif]--><!-- [if gte mso 10]>\r\n<style>\r\n /* Style Definitions */\r\ntable.MsoNormalTable\r\n	{mso-style-name:\"Tabla normal\";\r\n	mso-tstyle-rowband-size:0;\r\n	mso-tstyle-colband-size:0;\r\n	mso-style-noshow:yes;\r\n	mso-style-priority:99;\r\n	mso-style-parent:\"\";\r\n	mso-padding-alt:0cm 5.4pt 0cm 5.4pt;\r\n	mso-para-margin:0cm;\r\n	mso-para-margin-bottom:.0001pt;\r\n	mso-pagination:widow-orphan;\r\n	font-size:12.0pt;\r\n	font-family:\"Calibri\",sans-serif;\r\n	mso-ascii-font-family:Calibri;\r\n	mso-ascii-theme-font:minor-latin;\r\n	mso-hansi-font-family:Calibri;\r\n	mso-hansi-theme-font:minor-latin;\r\n	mso-fareast-language:EN-US;}\r\n</style>\r\n<![endif]--> <!--StartFragment--></p>\r\n<ul type=\"disc\">\r\n<li class=\"MsoNormal\" style=\"color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo1; tab-stops: list 36.0pt;\"><span style=\"font-size: 13.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-fareast-language: ES-TRAD;\">Grupo A (MA&Ntilde;ANA): En la evaluaci&oacute;n ordinaria, aprueban un total de XX alumnos de XX (XX%) y en la extraordinaria un total de XX alumnos de XX (XX%)</span></li>\r\n<li class=\"MsoNormal\" style=\"color: black; mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo1; tab-stops: list 36.0pt;\"><span style=\"font-size: 13.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; mso-fareast-language: ES-TRAD;\">Grupo B (TARDE): En la evaluaci&oacute;n ordinaria, aprueban un total de 12 alumnos de 16 (75%) y en la extraordinaria un total de 2 alumnos de los 4 convocados (50%). Siendo un 87,5% el total de alumnos aprobados al finalizar el curso.</span></li>\r\n<li class=\"MsoNormal\" style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-list: l0 level1 lfo1; tab-stops: list 36.0pt;\"><span style=\"font-size: 13.0pt; font-family: \'Arial\',sans-serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-fareast-language: ES-TRAD;\">Grupo C (MA&Ntilde;ANA): En la evaluaci&oacute;n ordinaria, aprueban un total de XX alumnos de XX (XX%) y en la extraordinaria un total de XX alumnos de XX (XX%)</span></li>\r\n</ul>\r\n<p><!--EndFragment--></p>', 87);
