(578, 14, '2022/2023', 2, '', '<p><strong>En el grupo presencial:</strong></p>\r\n<ul>\r\n<li>N&uacute;mero de alumnos: 10</li>\r\n<li>N&uacute;mero de suspensos:&nbsp;2</li>\r\n<li>N&uacute;mero de aprobados:&nbsp;8</li>\r\n<li>El % de aprobados ha sido: 80,00%</li>\r\n</ul>\r\n<p><strong>En el grupo&nbsp;semipresencial:</strong></p>\r\n<ul>\r\n<li>N&uacute;mero de alumnos:&nbsp;8</li>\r\n<li>N&uacute;mero de suspensos:&nbsp;3</li>\r\n<li>N&uacute;mero de aprobados:&nbsp;5</li>\r\n<li>El % de aprobados ha sido: 62,50%</li>\r\n</ul>', 72),
