INSERT INTO `seguimiento_programaciones_aula` (`id`, `idMateria`, `idGrupo`, `idProfesor`, `curso`, `evaluacion`, `temporalizacion`, `resultados`, `inclusion`, `num_aprobados`, `num_suspensos`, `num_otros`) VALUES
(1, 277, 35, 7, '2025/2026', 1, '<p>Se ha completado el primer bloque correspondiente a la ingenier&iacute;a del software y se ha comenzado con la programaci&oacute;n en Java, seg&uacute;n lo previsto en la programaci&oacute;n...</p>', '<p>La materia les resulta atractiva, y ello justifica los buenos resultados.</p>', '', 15, 2, 11),
(14, 281, 35, 7, '2025/2026', 1, '<p>Se ha completado el tema 5 (funciones) seg&uacute;n lo previsto en la programaci&oacute;n.</p>', '<p>Resultados bastante buenos, ya que la primera evaluaci&oacute;n es la m&aacute;s sencilla de todas.</p>', '', 15, 4, 0),
(15, 54, 7, 7, '2025/2026', 1, '<p>No se ha podido completar la unidad 2. Se decide no impartir JavaFX con hilos por falta de tiempo.</p>', '<p>El tema 2 (hilos) siempre resulta muy complicado para los alumnos. Se espera que la mayor&iacute;a de los alumnos suspensos recuperen la materia en las siguientes evaluaciones.&nbsp;</p>', '', 6, 7, 0);
