INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(2, 281, 1, 'Toma de contacto C#', 16, 1, 5, '', '', '', '', '', '', '<p>Instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>R&uacute;brica - 70%.&nbsp;\r\n<ul>\r\n<li>Examen te&oacute;rico-pr&aacute;ctico 45%</li>\r\n<li>Pr&aacute;ctica evaluada individualmente 25%</li>\r\n</ul>\r\n</li>\r\n<li>Observaci&oacute;n directa - 25%&nbsp;\r\n<ul>\r\n<li>Ejercicios semanales evaluados</li>\r\n<li>Ejercicios diarios</li>\r\n</ul>\r\n</li>\r\n<li>Evaluaci&oacute;n por pares - 5%&nbsp;\r\n<ul>\r\n<li>Los ejercicios semanales evaluados tienen este % de calificaci&oacute;n de los compa&ntilde;eros</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p>En modalidad <strong>semipresencial</strong>, al no contar con la presencia de alumnado en clase de forma regular, y disponer s&oacute;lo de una parte de la carga docente en las tutor&iacute;as colectivas, el peso de&nbsp;la evaluaci&oacute;n recaer&aacute; 100% en la r&uacute;brica, que a su vez se dividir&aacute; en supuestos pr&aacute;cticos peri&oacute;dicos durante el trimestre (30%) y una prueba presencial de control de los RA y criterios impartidos en ese trimestre (70%). La presente unidad tendr&aacute; el peso final indicado, distribuido entre los RA asociados.</p>', '', '', 0, 0, 0, 0),
(3, 281, 2, 'Estructuras de control', 32, 1, 10, '<p>En esta unidad se muestra al alumno la forma de comprobar condiciones y de crear bloques de instrucciones que se repitan dentro de un programa, as&iacute; como nociones b&aacute;sicas de control de excepciones y depuraci&oacute;n de c&oacute;digo</p>', '<p>Para adquirir fluidez en la programaci&oacute;n se debe ir realizando una aproximaci&oacute;n progresiva a los posibles problemas a solucionar a trav&eacute;s de programas.</p>', '<p>Se lleva a cabo en clase con los equipos habituales.&nbsp;</p>', '<p>Estructuras alternativas: If, If-else, Switch, Operador condicional<br /> Estructuras repetitivas: While, Do ... While, For. Break, continue<br /> Sentencia goto<br /> Nociones de dise&ntilde;o: diagramas de flujo<br /> Introducci&oacute;n a las excepciones<br /> Introducci&oacute;n a la depuraci&oacute;n de c&oacute;digo</p>', '<p>Realizaci&oacute;n de programas en los que se deba escoger entre dos opciones usando if.<br /> Realizaci&oacute;n de programas en los que se deba escoger entre un n&uacute;mero reducido de opciones usando if-else.<br /> Escoger una alternativa entre varias posibles con switch.<br /> Realizaci&oacute;n de bloques repetitivos cuya condici&oacute;n de salida se comprueba al comienzo (con while)<br /> Realizaci&oacute;n de bloques repetitivos cuya condici&oacute;n se comprueba al final (con do..while).<br /> Realizaci&oacute;n de bloques repetitivos con un n&uacute;mero de iteraciones conocido (con for).<br /> Realizaci&oacute;n de bloques repetitivos de todo tipo, en los que el alumno deba ser quien decida qu&eacute; m&eacute;todo usar.<br /> Ejemplo de uso de la sentencia goto y explicaci&oacute;n de la problem&aacute;tica asociada (desorden en el fuente).<br /> Creaci&oacute;n de diagramas de flujo para programas elementales.<br /> Seguimiento del valor de variables usando el depurador del entorno escogido.<br /> Interceptar errores b&aacute;sicos en tiempo de ejecuci&oacute;n (conversiones de tipo) usando control de excepciones.<br /> Depurar el c&oacute;digo de un programa incorrecto averiguando d&oacute;nde est&aacute; el posible error por ejecuci&oacute;n paso a paso</p>', '', '<p>Instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>R&uacute;brica - 70%.&nbsp;\r\n<ul>\r\n<li>Examen te&oacute;rico-pr&aacute;ctico 45%</li>\r\n<li>Pr&aacute;ctica evaluada individualmente 25%</li>\r\n</ul>\r\n</li>\r\n<li>Observaci&oacute;n directa - 25%&nbsp;\r\n<ul>\r\n<li>Ejercicios semanales evaluados</li>\r\n<li>Ejercicios diarios</li>\r\n</ul>\r\n</li>\r\n<li>Evaluaci&oacute;n por pares - 5%&nbsp;\r\n<ul>\r\n<li>Los ejercicios semanales evaluados tienen este % de calificaci&oacute;n de los compa&ntilde;eros</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p>En modalidad <strong>semipresencial</strong>, al no contar con la presencia de alumnado en clase de forma regular, y disponer s&oacute;lo de una parte de la carga docente en las tutor&iacute;as colectivas, el peso de&nbsp;la evaluaci&oacute;n recaer&aacute; 100% en la r&uacute;brica, que a su vez se dividir&aacute; en supuestos pr&aacute;cticos peri&oacute;dicos durante el trimestre (30%) y una prueba presencial de control de los RA y criterios impartidos en ese trimestre (70%). La presente unidad tendr&aacute; el peso final indicado, distribuido entre los RA asociados.</p>\r\n<p>&nbsp; Dimensiones de la r&uacute;brica:</p>\r\n<ul>\r\n<li>Saber escoger entre dos opciones usando if.</li>\r\n<li>Ser capaz de crear programas en los que se deba escoger entre un n&uacute;mero reducido de opciones usando if-else.</li>\r\n<li>Escoger una alternativa entre varias posibles con switch, conociendo el uso correcto de las sentencias break y default.</li>\r\n<li>Correcci&oacute;n en la realizaci&oacute;n de bloques repetitivos cuya condici&oacute;n de salida se comprueba al comienzo (con while)</li>\r\n<li>Correcci&oacute;n en la realizaci&oacute;n de bloques repetitivos cuya condici&oacute;n se comprueba al final (con do..while).</li>\r\n<li>Correcci&oacute;n en la realizaci&oacute;n de bloques repetitivos con un n&uacute;mero de iteraciones conocido (con for).</li>\r\n<li>Ser capaz de plantear bloques repetitivos de todo tipo, escogiendo un m&eacute;todo adecuado para el problema.</li>\r\n<li>Conocer la sentencia goto y los problemas que se pueden derivar de su uso.</li>\r\n<li>Ser capaz de crear diagramas de flujo para programas elementales que incluyan condiciones o repetici&oacute;n de bloques de programa.</li>\r\n<li>Poder analizar el flujo del programa y comprobar el valor de variables usando el depurador del entorno escogido.</li>\r\n<li>Interceptar de forma correcta errores b&aacute;sicos de conversi&oacute;n de tipo usando control de excepciones.</li>\r\n<li>Detectar errores sencillos en programas mediante mecanismos b&aacute;sicos de depuraci&oacute;n de c&oacute;digo</li>\r\n</ul>\r\n<p>Dimensi&oacute;n de la observaci&oacute;n directa:</p>\r\n<ul>\r\n<li>Seguimiento de las instrucciones para la realizaci&oacute;n de los retos</li>\r\n<li>Pensar antes de actuar, reflexi&oacute;n sobre la tarea a realizar</li>\r\n<li>Ejercicios en papel con correcci&oacute;n por compa&ntilde;eros y realizaci&oacute;n posterior en ordenador</li>\r\n</ul>\r\n<p>Dimensi&oacute;n de la evaluaci&oacute;n por pares</p>\r\n<ul>\r\n<li>Algunos de los retos realizados en clase ser&aacute;n evaluados por los compa&ntilde;eros</li>\r\n</ul>', '', '', 0, 1, 1, 1),
(5, 41, 1, 'Arquitectura y funcionamiento del ordenador', 14, 1, 3, '<p>En esta unidad se introduce al alumnado en los fundamentos del hardware de los sistemas inform&aacute;ticos. Se analizan los elementos que conforman la arquitectura b&aacute;sica de un ordenador, tomando como referencia el modelo de Von Neumann, as&iacute; como la funci&oacute;n y el funcionamiento de los componentes principales: la Unidad Central de Proceso (CPU), la memoria principal, los dispositivos de entrada/salida y los buses de comunicaci&oacute;n. A trav&eacute;s de actividades pr&aacute;cticas y simulaciones, el alumnado comprender&aacute; c&oacute;mo se ejecutan las instrucciones y c&oacute;mo interact&uacute;an los distintos elementos del sistema.</p>', '<p>Esta unidad constituye la base conceptual imprescindible para el desarrollo del m&oacute;dulo de <em data-start=\"1083\" data-end=\"1119\">Montaje y Mantenimiento de Equipos</em>, ya que proporciona la comprensi&oacute;n del funcionamiento interno de los ordenadores, necesaria para el montaje, diagn&oacute;stico y reparaci&oacute;n de equipos inform&aacute;ticos.</p>\r\n<p><br data-start=\"1278\" data-end=\"1281\" /> Los contenidos se relacionan directamente con los resultados de aprendizaje vinculados a la <strong data-start=\"1373\" data-end=\"1415\">identificaci&oacute;n de componentes internos</strong> y <strong data-start=\"1418\" data-end=\"1463\">comprensi&oacute;n de su interrelaci&oacute;n funcional</strong>. Adem&aacute;s, sientan las bases para m&oacute;dulos posteriores como <em data-start=\"1521\" data-end=\"1536\">Redes Locales</em> o <em data-start=\"1539\" data-end=\"1571\">Sistemas Operativos Monopuesto</em>.</p>\r\n<p><br data-start=\"1572\" data-end=\"1575\" /> El tratamiento de esta unidad contribuye a desarrollar competencias profesionales, personales y sociales como el rigor t&eacute;cnico, la resoluci&oacute;n de problemas y la autonom&iacute;a en el manejo de equipos y documentaci&oacute;n t&eacute;cnica.</p>', '', '<p>A lo largo de esta unidad se desarrollar&aacute;n los siguientes contenidos:</p>\r\n<p>1. Arquitectura de Von Newmann<br />2. Unidad Central de Proceso (CPU)<br />3. Memoria Principal<br />4. Ejecuci&oacute;n de una instrucci&oacute;n<br />5. Unidad de Entrada/Salida<br />6. Buses</p>\r\n<p>&nbsp;</p>', '<p>Se comenzar&aacute; la unidad con una exposici&oacute;n de los principales aspectos te&oacute;ricos mediante la presentaci&oacute;n disponible en Aules.</p>\r\n<p>Una vez vista esta parte inicial, se explicar&aacute; c&oacute;mo se ejecutan las instrucciones en el procesador y pasaremos a realizar ejercicios de este tipo, primero en la pizarra blanca y posteriormente en formato actividades entregables por Aules:</p>\r\n<ul>\r\n<li>Ejecuci&oacute;n de instrucciones 1</li>\r\n<li>Ejecuci&oacute;n de instrucciones 2</li>\r\n<li>Ejecuci&oacute;n de instrucciones 3</li>\r\n</ul>\r\n<p>Adicionalmente, se dejar&aacute;n en Aules diversos ejercicios de este mismo tipo con sus soluciones. Estos ejercicios est&aacute;n pensados para el alumnado que necesita afianzar el procedimiento y para detectar d&oacute;nde tienen los principales problemas a la hora de realizarlos. No ser&aacute; necesario que los entreguen por Aules.</p>\r\n<p>Finalizaremos la unidad con un examen te&oacute;rico al que preceder&aacute; la entrega del resumen, esquema o mapa conceptual que hayan realizado para ir afianzando transversalmente al m&oacute;dulo el empleo de t&eacute;cnicas de estudio.</p>', '', '<p>La evaluaci&oacute;n de la unidad se realizar&aacute; ponderando teor&iacute;a y pr&aacute;ctica al 50% en cada caso. No existir&aacute; nota m&iacute;nima en ninguno de los dos apartados para promediar.</p>\r\n<p>La evaluaci&oacute;n de la parte pr&aacute;ctica se basar&aacute; en r&uacute;bricas de evaluaci&oacute;n de los ejercicios y actividades desarrolladas, as&iacute; como en la observaci&oacute;n directa en el aula.&nbsp;</p>\r\n<p>La evaluaci&oacute;n de la parte te&oacute;rica se basar&aacute; en el examen te&oacute;rico al final de la unidad, la valoraci&oacute;n del resumen, esquema o mapa conceptual entregado antes del examen y la observaci&oacute;n directa en el aula.</p>', '', '', 1, 1, 1, 1),
(6, 41, 2, 'Componentes internos del ordenador I: Microprocesador y placa base', 20, 1, 6, '<p>En esta unidad se aborda el estudio detallado de los dos componentes esenciales que constituyen el n&uacute;cleo funcional del ordenador: el <strong data-start=\"478\" data-end=\"497\">microprocesador</strong> y la <strong data-start=\"503\" data-end=\"517\">placa base</strong>.</p>\r\n<p><br data-start=\"518\" data-end=\"521\" /> El alumnado conocer&aacute; la evoluci&oacute;n tecnol&oacute;gica de los procesadores, sus arquitecturas internas, las principales caracter&iacute;sticas t&eacute;cnicas y las tecnolog&iacute;as asociadas de los fabricantes m&aacute;s relevantes (Intel, AMD y Apple). Asimismo, se estudiar&aacute; la estructura, funciones y tipolog&iacute;as de las placas base, su relaci&oacute;n con el procesador mediante el socket, el chipset y los diferentes tipos de buses que permiten la interconexi&oacute;n de los distintos dispositivos del sistema.</p>\r\n<p><br data-start=\"987\" data-end=\"990\" /> Se combinar&aacute;n sesiones te&oacute;ricas con actividades pr&aacute;cticas de identificaci&oacute;n de componentes reales, interpretaci&oacute;n de esquemas y comparaci&oacute;n de especificaciones t&eacute;cnicas.</p>', '<p>Esta unidad resulta esencial para la formaci&oacute;n en el m&oacute;dulo de <em data-start=\"1255\" data-end=\"1291\">Montaje y Mantenimiento de Equipos</em>, ya que permite al alumnado comprender el papel fundamental del microprocesador y la placa base como elementos clave en el ensamblaje y rendimiento de un equipo inform&aacute;tico.</p>\r\n<p><br data-start=\"1465\" data-end=\"1468\" /> El conocimiento de las tecnolog&iacute;as de los principales fabricantes y de los distintos tipos de buses y sockets capacita al alumnado para realizar tareas de diagn&oacute;stico, actualizaci&oacute;n y sustituci&oacute;n de componentes con criterios t&eacute;cnicos adecuados.</p>\r\n<p><br data-start=\"1712\" data-end=\"1715\" /> Adem&aacute;s, la unidad contribuye directamente al desarrollo de competencias relacionadas con la <strong data-start=\"1807\" data-end=\"1862\">identificaci&oacute;n de componentes y sus caracter&iacute;sticas</strong>, la <strong data-start=\"1867\" data-end=\"1901\">evaluaci&oacute;n de compatibilidades</strong> y la <strong data-start=\"1907\" data-end=\"1967\">toma de decisiones en el montaje y reparaci&oacute;n de equipos</strong>.</p>\r\n<p><br data-start=\"1968\" data-end=\"1971\" /> A nivel transversal, fomenta el uso responsable de la tecnolog&iacute;a, la actualizaci&oacute;n permanente y la curiosidad cient&iacute;fica ante la evoluci&oacute;n del hardware.</p>', '', '<p>A lo largo de esta unidad se desarrollar&aacute;n los siguientes contenidos:</p>\r\n<ol>\r\n<li>El microprocesador\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>El procesador</li>\r\n<li>Arquitectura CISC/RISC</li>\r\n<li>Arquitectura interna\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Diagrama de bloques de una CPU</li>\r\n<li>Diagrama de bloques de una CPU multicore</li>\r\n</ol>\r\n</li>\r\n<li>Caracter&iacute;sticas\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Velocidad del procesador</li>\r\n<li>N&uacute;mero de n&uacute;cleos</li>\r\n<li>Memoria cach&eacute;</li>\r\n<li>Alimentaci&oacute;n</li>\r\n<li>Repertorio de instrucciones</li>\r\n<li>TDP</li>\r\n<li>Tecnolog&iacute;a base</li>\r\n</ol>\r\n</li>\r\n<li>Ley de Moore</li>\r\n<li>Tecnolog&iacute;as comunes a todas las marcas\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Computaci&oacute;n paralela</li>\r\n<li>Arquitectura superescalar</li>\r\n<li>Arquitectura multicore</li>\r\n<li>Generaciones de dise&ntilde;o de procesadores</li>\r\n</ol>\r\n</li>\r\n<li>Generaciones de procesadores\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Familia Intel Core</li>\r\n<li>Familia Intel Core Ultra</li>\r\n<li>Familia AMD Ryzen</li>\r\n<li>Familia Apple</li>\r\n</ol>\r\n</li>\r\n<li>Tecnolog&iacute;as Intel\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Hyperthreading</li>\r\n<li>TurboBoost</li>\r\n<li>Intel Thermal Velocity Boost</li>\r\n<li>Memoria Intel Optane</li>\r\n<li>Tecnolog&iacute;a de virtualizaci&oacute;n VT-x</li>\r\n<li>N&uacute;cleos E y n&uacute;cleos P</li>\r\n<li>Estados de inactividad</li>\r\n</ol>\r\n</li>\r\n<li>Tecnolog&iacute;as AMD\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Simultaneous Mutithreading (SMT)</li>\r\n<li>TurboCore 2</li>\r\n<li>Secure Virtual Machine (SVM)</li>\r\n<li>StoreMI</li>\r\n<li>Memory Guard</li>\r\n<li>Enduro</li>\r\n<li>Zero Core Power</li>\r\n<li>Power Tune</li>\r\n</ol>\r\n</li>\r\n<li>Procesadores Intel</li>\r\n<li>Significado del marcado Intel</li>\r\n<li>Procesadores AMD</li>\r\n<li>Significado del marcado AMD</li>\r\n</ol>\r\n</li>\r\n<li>La placa base\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>La placa base</li>\r\n<li>Factores de forma</li>\r\n<li>El socket o z&oacute;calo de la CPU\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Tipos de sockets</li>\r\n<li>Sockets Intel</li>\r\n<li>Sockets AMD</li>\r\n</ol>\r\n</li>\r\n<li>La BIOS</li>\r\n<li>El chipset. Esquema cl&aacute;sico</li>\r\n<li>El chipset. Esquema actual</li>\r\n<li>Buses\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>FSB</li>\r\n<li>QPI</li>\r\n<li>HyperTransport</li>\r\n<li>DMI</li>\r\n<li>UMI</li>\r\n<li>BSB</li>\r\n<li>IDE</li>\r\n<li>PCI</li>\r\n<li>AGP</li>\r\n<li>PCI Express</li>\r\n<li>SATA</li>\r\n<li>SATA Express</li>\r\n<li>M.2 NVMe</li>\r\n<li>Puerto serie</li>\r\n<li>Puerto paralelo</li>\r\n<li>USB</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>', '<p>Se comenzar&aacute; la unidad con una exposici&oacute;n de los principales aspectos te&oacute;ricos de procesadores mediante la presentaci&oacute;n disponible en Aules.</p>\r\n<p>Una vez vista esta parte inicial, alternaremos los siguientes ejercicios con m&aacute;s aspectos te&oacute;ricos, con los que podr&aacute;n ir complet&aacute;ndolos:</p>\r\n<ul>\r\n<li>Ejecuci&oacute;n de procesadores 1</li>\r\n<li>Ejecuci&oacute;n de procesadores 2: identificaci&oacute;n</li>\r\n</ul>\r\n<p>Una vez acabada la exposici&oacute;n de la presentaci&oacute;n de procesadores, alternaremos los ejercicios anteriores con la presentaci&oacute;n de placas base de Aules hasta tener base suficiente para abordar el ejercicio siguiente:</p>\r\n<ul>\r\n<li>Ejercicio de placas base 1: identificaci&oacute;n</li>\r\n</ul>\r\n<p>Si vemos que al grupo le ha costado afianzar los principales conceptos sobre tecnolog&iacute;as de procesadores y su relaci&oacute;n con placas base (z&oacute;calo), se dispone de otro ejercicio, en esta ocasi&oacute;n de investigaci&oacute;n en grupos de 3-4 personas (Ejercicio de procesadores 3). La finalidad del mismo es elaborar una presentaci&oacute;n con una investigaci&oacute;n sobre un procesador concreto y la placa base m&aacute;s adecuada para el mismo de forma razonada. Esta presentaci&oacute;n la expodr&iacute;a cada grupo ante el resto de la clase y as&iacute;, transversalmente, trabajamos la competencia de hablar en p&uacute;blico y defender las ideas propias.</p>\r\n<p>Finalizaremos la unidad con un examen te&oacute;rico al que preceder&aacute; la entrega del resumen, esquema o mapa conceptual que hayan realizado para ir afianzando transversalmente al m&oacute;dulo el empleo de t&eacute;cnicas de estudio.</p>', '', '<p>La evaluaci&oacute;n de la unidad se realizar&aacute; ponderando teor&iacute;a y pr&aacute;ctica al 50% en cada caso. No existir&aacute; nota m&iacute;nima en ninguno de los dos apartados para promediar.</p>\r\n<p>La evaluaci&oacute;n de la parte pr&aacute;ctica se basar&aacute; en r&uacute;bricas de evaluaci&oacute;n de los ejercicios y actividades desarrolladas, as&iacute; como en la observaci&oacute;n directa en el aula.&nbsp;</p>\r\n<p>La evaluaci&oacute;n de la parte te&oacute;rica se basar&aacute; en el examen te&oacute;rico al final de la unidad, la valoraci&oacute;n del resumen, esquema o mapa conceptual entregado antes del examen y la observaci&oacute;n directa en el aula.</p>', '', '', 1, 1, 1, 1),
(7, 41, 3, 'Componentes internos del ordenador II. Memoria y dispositivos de almacenamiento', 25, 1, 6, '<p>En esta unidad se estudian en profundidad los sistemas de <strong data-start=\"411\" data-end=\"439\">memoria y almacenamiento</strong> de los equipos inform&aacute;ticos, analizando su funci&oacute;n, estructura, jerarqu&iacute;a y evoluci&oacute;n tecnol&oacute;gica.</p>\r\n<p><br data-start=\"538\" data-end=\"541\" /> El alumnado aprender&aacute; a distinguir los distintos tipos de memoria (RAM, ROM, cach&eacute;) y sus caracter&iacute;sticas, comprendiendo c&oacute;mo influyen en el rendimiento del sistema. Tambi&eacute;n se abordar&aacute; la clasificaci&oacute;n, estructura y funcionamiento de los principales <strong data-start=\"792\" data-end=\"826\">dispositivos de almacenamiento</strong>, tanto magn&eacute;ticos como de estado s&oacute;lido, &oacute;pticos y flash.</p>\r\n<p><br data-start=\"884\" data-end=\"887\" /> A trav&eacute;s de actividades pr&aacute;cticas, se identifican f&iacute;sicamente los distintos m&oacute;dulos de memoria y unidades de almacenamiento, se comparan sus prestaciones y se realizan montajes y configuraciones b&aacute;sicas.</p>', '<p>El conocimiento de las memorias y dispositivos de almacenamiento es esencial para la correcta instalaci&oacute;n, mantenimiento y optimizaci&oacute;n de equipos inform&aacute;ticos, objetivos fundamentales del m&oacute;dulo Montaje y Mantenimiento de Equipos.<br />Esta unidad proporciona al alumnado las competencias necesarias para:</p>\r\n<ul>\r\n<li>Reconocer los distintos tipos de memoria y sus funciones en la jerarqu&iacute;a del sistema.</li>\r\n<li>Seleccionar adecuadamente componentes compatibles en funci&oacute;n del equipo y las necesidades de rendimiento.</li>\r\n<li>Diagnosticar y sustituir m&oacute;dulos defectuosos o ineficientes.</li>\r\n<li>Comprender la evoluci&oacute;n tecnol&oacute;gica del almacenamiento y su impacto en la velocidad y fiabilidad del sistema.</li>\r\n</ul>\r\n<p>Asimismo, fomenta el pensamiento anal&iacute;tico, la actualizaci&oacute;n tecnol&oacute;gica y la capacidad de tomar decisiones fundamentadas en criterios t&eacute;cnicos, contribuyendo al desarrollo de competencias profesionales, personales y sociales del perfil del t&eacute;cnico en Sistemas Microinform&aacute;ticos y Redes.</p>', '', '<p>A lo largo de esta unidad se desarrollar&aacute;n los siguientes contenidos:</p>\r\n<ol>\r\n<li>Memoria\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>La memoria</li>\r\n<li>Jerarqu&iacute;a de memoria</li>\r\n<li>Caracter&iacute;sticas de la memoria</li>\r\n<li>Tipos de memorias (RAM/ROM/cach&eacute;)</li>\r\n<li>Tecnolog&iacute;as base\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Memorias de ferrita</li>\r\n<li>SRAM</li>\r\n<li>DRAM</li>\r\n</ol>\r\n</li>\r\n<li>Tipos de memoria RAM\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>SIMM\r\n<ol>\r\n<li>30 contactos (DRAM)</li>\r\n<li>72 contactos (EDO)</li>\r\n</ol>\r\n</li>\r\n<li>DIMM\r\n<ol>\r\n<li>SDRAM</li>\r\n<li>DDR</li>\r\n<li>DDR2</li>\r\n<li>DDR3</li>\r\n<li>DDR4</li>\r\n<li>DDR5</li>\r\n</ol>\r\n</li>\r\n<li>SODIMM</li>\r\n</ol>\r\n</li>\r\n<li>Tecnolog&iacute;as de memoria RAM\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Dual/Tri/Quad channel</li>\r\n<li>Memorias buffered/unbuffered</li>\r\n</ol>\r\n</li>\r\n<li>Tipos de memorias ROM\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>ROM</li>\r\n<li>PROM</li>\r\n<li>EPROM</li>\r\n<li>EEPROM</li>\r\n</ol>\r\n</li>\r\n<li>Memoria cach&eacute;</li>\r\n</ol>\r\n</li>\r\n<li>Dispositivos de almacenamiento\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Definici&oacute;n y clasificaci&oacute;n</li>\r\n<li>Dispositivos magn&eacute;ticos</li>\r\n<li>Discos duros magn&eacute;ticos\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Estructura f&iacute;sica</li>\r\n</ol>\r\n</li>\r\n<li>Discos de estado s&oacute;lido (SSD)\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Estructura f&iacute;sica</li>\r\n<li>Tipos de memorias NAND\r\n<ol>\r\n<li>SLC</li>\r\n<li>MLC</li>\r\n<li>TLC</li>\r\n<li>QLC</li>\r\n</ol>\r\n</li>\r\n<li>Disposici&oacute;n de memorias\r\n<ol>\r\n<li>2D NAND</li>\r\n<li>3D NAND</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n<li>Estructura l&oacute;gica de los discos duros</li>\r\n<li>Caracter&iacute;sticas de los discos duros\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Capacidad</li>\r\n<li>Tiempo de acceso</li>\r\n<li>Densidad</li>\r\n<li>Memoria cach&eacute;</li>\r\n<li>Velocidad de transferencia</li>\r\n</ol>\r\n</li>\r\n<li>Disquete (floppy)</li>\r\n<li>Cintas magn&eacute;ticas</li>\r\n<li>Dispositivos &oacute;pticos\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Estructura f&iacute;sica</li>\r\n<li>Estructura l&oacute;gica</li>\r\n<li>CD</li>\r\n<li>DVD</li>\r\n<li>Blu-Ray Disc</li>\r\n</ol>\r\n</li>\r\n<li>Dispositivos flash\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>SSD SATA</li>\r\n<li>SSD M.2</li>\r\n</ol>\r\n</li>\r\n<li>Flash vs Magn&eacute;ticos</li>\r\n</ol>\r\n</li>\r\n</ol>', '<p>Se comenzar&aacute; la unidad con una exposici&oacute;n de los principales aspectos te&oacute;ricos de memoria mediante la presentaci&oacute;n disponible en Aules.</p>\r\n<p>Una vez vista esta parte inicial, alternaremos el siguiente ejercicio con m&aacute;s aspectos te&oacute;ricos, con los que podr&aacute;n ir complet&aacute;ndolo:</p>\r\n<ul>\r\n<li>Ejecuci&oacute;n de memoria 1: identificaci&oacute;n</li>\r\n</ul>\r\n<p>Adicionalmente, durante las sesiones te&oacute;ricas le proporcionaremos al alumnado memorias f&iacute;sicas y placas base para que intenten adivinar qu&eacute; memorias y placas ser&iacute;an compatibles, de forma que dinamicemos el aprendizaje rompiendo el ritmo con esta actividad.</p>\r\n<p>Una vez acabada la exposici&oacute;n de la presentaci&oacute;n de memoria, alternaremos los ejercicios anteriores con la presentaci&oacute;n de dispositivos de almacenamiento de Aules hasta tener base suficiente para abordar el ejercicio siguiente:</p>\r\n<ul>\r\n<li>Ejercicio de discos duros 1: identificaci&oacute;n</li>\r\n</ul>\r\n<p>A lo largo del tema se les proporcionar&aacute;n elementos f&iacute;sicos de diversos tipos para que puedan manipularlos, observarlos y comprender las diferencias y afianzar as&iacute; los contenidos te&oacute;ricos que se van desarrollando.</p>\r\n<p>Finalizaremos la unidad con un examen te&oacute;rico al que preceder&aacute; la entrega del resumen, esquema o mapa conceptual que hayan realizado para ir afianzando transversalmente al m&oacute;dulo el empleo de t&eacute;cnicas de estudio.</p>', '', '<p>La evaluaci&oacute;n de la unidad se realizar&aacute; ponderando teor&iacute;a y pr&aacute;ctica al 50% en cada caso. No existir&aacute; nota m&iacute;nima en ninguno de los dos apartados para promediar.</p>\r\n<p>La evaluaci&oacute;n de la parte pr&aacute;ctica se basar&aacute; en r&uacute;bricas de evaluaci&oacute;n de los ejercicios y actividades desarrolladas, as&iacute; como en la observaci&oacute;n directa en el aula.&nbsp;</p>\r\n<p>La evaluaci&oacute;n de la parte te&oacute;rica se basar&aacute; en el examen te&oacute;rico al final de la unidad, la valoraci&oacute;n del resumen, esquema o mapa conceptual entregado antes del examen y la observaci&oacute;n directa en el aula.</p>', '', '', 1, 1, 1, 1),
(8, 41, 4, 'Componentes internos del ordenador III: Adaptadores graficos, red y multimedia', 25, 1, 5, '<p>En esta unidad se analizan los <strong data-start=\"384\" data-end=\"413\">dispositivos de expansi&oacute;n</strong> que ampl&iacute;an las capacidades del ordenador, centr&aacute;ndose en los adaptadores <strong data-start=\"488\" data-end=\"500\">gr&aacute;ficos</strong>, <strong data-start=\"502\" data-end=\"512\">de red</strong> y <strong data-start=\"515\" data-end=\"529\">multimedia</strong>.</p>\r\n<p><br data-start=\"530\" data-end=\"533\" /> El alumnado estudiar&aacute; las funciones, componentes y tecnolog&iacute;as de las <strong data-start=\"603\" data-end=\"624\">tarjetas gr&aacute;ficas</strong>, comprendiendo el papel de la GPU, la VRAM y las arquitecturas actuales de procesamiento gr&aacute;fico (NVIDIA, AMD). Se abordar&aacute;n tambi&eacute;n los principales tipos de salidas de v&iacute;deo y las t&eacute;cnicas de renderizado modernas, como <em data-start=\"845\" data-end=\"858\">Ray Tracing</em> o <em data-start=\"861\" data-end=\"870\">Shading</em>.</p>\r\n<p><br data-start=\"871\" data-end=\"874\" /> En la segunda parte de la unidad se profundizar&aacute; en las <strong data-start=\"930\" data-end=\"962\">tarjetas de red y multimedia</strong>, incluyendo adaptadores Ethernet y Wi-Fi, tarjetas de sonido, capturadoras de v&iacute;deo y sintonizadoras, as&iacute; como otras tarjetas complementarias.</p>\r\n<p><br data-start=\"1105\" data-end=\"1108\" /> Las actividades pr&aacute;cticas permitir&aacute;n al alumnado identificar, instalar y configurar estos dispositivos, tanto en entornos f&iacute;sicos como virtuales.</p>', '<p>Esta unidad completa el estudio de los <strong data-start=\"1325\" data-end=\"1363\">componentes internos del ordenador</strong>, ampliando el conocimiento del alumnado sobre los dispositivos encargados del <strong data-start=\"1442\" data-end=\"1515\">procesamiento gr&aacute;fico, la comunicaci&oacute;n en red y la gesti&oacute;n multimedia</strong>.</p>\r\n<p><br data-start=\"1516\" data-end=\"1519\" /> Es fundamental para el desarrollo de competencias del m&oacute;dulo <em data-start=\"1580\" data-end=\"1616\">Montaje y Mantenimiento de Equipos</em>, especialmente en lo relativo a la <strong data-start=\"1652\" data-end=\"1741\">selecci&oacute;n, instalaci&oacute;n y verificaci&oacute;n de perif&eacute;ricos internos y tarjetas de expansi&oacute;n</strong>.</p>\r\n<p><br data-start=\"1742\" data-end=\"1745\" /> Adem&aacute;s, el contenido tiene una alta relevancia pr&aacute;ctica, ya que la configuraci&oacute;n de tarjetas gr&aacute;ficas y de red forma parte habitual de las tareas de los t&eacute;cnicos en sistemas microinform&aacute;ticos.</p>\r\n<p><br data-start=\"1937\" data-end=\"1940\" /> Contribuye, asimismo, a la adquisici&oacute;n de competencias transversales como la capacidad de an&aacute;lisis t&eacute;cnico, el aprendizaje aut&oacute;nomo ante la r&aacute;pida evoluci&oacute;n tecnol&oacute;gica, y la resoluci&oacute;n de incidencias en hardware especializado.</p>', '<p>Se comenzar&aacute; la unidad con una exposici&oacute;n de los principales aspectos te&oacute;ricos de tarjetas gr&aacute;ficas mediante la presentaci&oacute;n disponible en Aules.</p>\r\n<p>Una vez vista esta parte inicial, alternaremos los siguientes ejercicios con m&aacute;s aspectos te&oacute;ricos, con los que podr&aacute;n ir complet&aacute;ndolos:</p>\r\n<ul>\r\n<li>Trabajo en grupo: An&aacute;lisis y comparativa de tarjetas gr&aacute;ficas<br />Identificaci&oacute;n de tarjetas gr&aacute;ficas y de expansi&oacute;n</li>\r\n</ul>\r\n<p>Una vez acabada la exposici&oacute;n de la presentaci&oacute;n de tarjetas gr&aacute;ficas, alternaremos los ejercicios anteriores con la presentaci&oacute;n de tarjetas de red y multimedia de Aules hasta finalizar el tema, habiendo visto los componentes internos de un PC. En ese momento ya tendr&aacute;n la base suficiente para realizar presupuestos reales a partir de informaci&oacute;n de diferentes sitios de venta de componentes, por lo que se les solicitar&aacute; realizar la siguiente actividad:</p>\r\n<ul>\r\n<li>Elaboraci&oacute;n de presupuestos</li>\r\n</ul>\r\n<p>Finalizaremos la unidad con un examen te&oacute;rico al que preceder&aacute; la entrega del resumen, esquema o mapa conceptual que hayan realizado para ir afianzando transversalmente al m&oacute;dulo el empleo de t&eacute;cnicas de estudio.</p>', '<p>A lo largo de esta unidad se desarrollar&aacute;n los siguientes contenidos:</p>\r\n<ol>\r\n<li>Tarjetas gr&aacute;ficas\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Definici&oacute;n</li>\r\n<li>Aspecto</li>\r\n<li>Componentes\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>GPU</li>\r\n<li>RAMDAC</li>\r\n<li>VRAM</li>\r\n<li>Salidas de video</li>\r\n</ol>\r\n</li>\r\n<li>GPU\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>SM cores o CU/WGP</li>\r\n<li>Arquitecturas RDNA y GCN</li>\r\n<li>N&uacute;cleos CUDA</li>\r\n<li>GTX vs RTX</li>\r\n<li>SLI/NVLink/Crossfire</li>\r\n</ol>\r\n</li>\r\n<li>T&eacute;cnicas gr&aacute;ficas\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Antialiasing</li>\r\n<li>Shading</li>\r\n<li>Ray Tracing</li>\r\n</ol>\r\n</li>\r\n<li>RAMDAC</li>\r\n<li>VRAM\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>GDDR</li>\r\n<li>HBM</li>\r\n<li>Memoria dedicada/compartida</li>\r\n</ol>\r\n</li>\r\n<li>Salidas de video\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>VGA</li>\r\n<li>S-Video</li>\r\n<li>DVI</li>\r\n<li>HDMI</li>\r\n<li>DisplayPort</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n<li>Tarjetas de red y multimedia\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Tarjetas de red\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Tarjetas Ethernet</li>\r\n<li>Tarjetas Wi-Fi</li>\r\n</ol>\r\n</li>\r\n<li>Tarjetas multimedia\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Tarjetas de sonido</li>\r\n<li>Capturadoras de video</li>\r\n<li>Sintonizadoras de TV</li>\r\n</ol>\r\n</li>\r\n<li>Otras tarjetas\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>M&oacute;dem</li>\r\n<li>Ampliaci&oacute;n de puertos</li>\r\n<li>Adaptadoras</li>\r\n<li>Controladoras de disco</li>\r\n<li>PCMCIA</li>\r\n<li>ExpressCard</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>', '<p>Se comenzar&aacute; la unidad con una exposici&oacute;n de los principales aspectos te&oacute;ricos sobre tarjetas gr&aacute;ficas mediante la presentaci&oacute;n disponible en Aules.</p>\r\n<p>Una vez vista esta parte inicial, alternaremos el siguiente ejercicio con m&aacute;s aspectos te&oacute;ricos, con los que podr&aacute;n ir complet&aacute;ndolo:</p>\r\n<ul>\r\n<li>Trabajo en grupo: An&aacute;lisis y comparativa de tarjetas gr&aacute;ficas</li>\r\n</ul>\r\n<p>La presentaci&oacute;n en peque&ntilde;os grupos les permite desarrollar de forma transversal la competencia comunicativa y expositiva, aprovechando la atracci&oacute;n que ejercen las tarjetas gr&aacute;ficas en el alumnado por el gaming.</p>\r\n<p>Una vez acabada la exposici&oacute;n de la presentaci&oacute;n de tarjetas gr&aacute;ficas, alternaremos los ejercicios anteriores con la presentaci&oacute;n de tarjetas de red y multimedia disponible en Aules. Con esto se cierra el grupo de unidades que abarcan los componentes internos m&aacute;s relevantes de un equipo y ya estar&aacute;n en condiciones de abordar las siguientes actividades:</p>\r\n<ul>\r\n<li>Ejercicio de identificaci&oacute;n de tarjetas gr&aacute;ficas y de expansi&oacute;n (red, multimedia...)</li>\r\n<li>Elaboraci&oacute;n de presupuestos 1</li>\r\n<li>Elaboraci&oacute;n de presupuestos 2</li>\r\n</ul>\r\n<p>A lo largo del tema se les proporcionar&aacute;n elementos f&iacute;sicos de diversos tipos para que puedan manipularlos, observarlos y comprender las diferencias y afianzar as&iacute; los contenidos te&oacute;ricos que se van desarrollando.</p>\r\n<p>Finalizaremos la unidad con un examen te&oacute;rico al que preceder&aacute; la entrega del resumen, esquema o mapa conceptual que hayan realizado para ir afianzando transversalmente al m&oacute;dulo el empleo de t&eacute;cnicas de estudio.</p>', '', '<p>La evaluaci&oacute;n de la unidad se realizar&aacute; ponderando teor&iacute;a y pr&aacute;ctica al 50% en cada caso. No existir&aacute; nota m&iacute;nima en ninguno de los dos apartados para promediar.</p>\r\n<p>La evaluaci&oacute;n de la parte pr&aacute;ctica se basar&aacute; en r&uacute;bricas de evaluaci&oacute;n de los ejercicios y actividades desarrolladas, as&iacute; como en la observaci&oacute;n directa en el aula.&nbsp;</p>\r\n<p>La evaluaci&oacute;n de la parte te&oacute;rica se basar&aacute; en el examen te&oacute;rico al final de la unidad, la valoraci&oacute;n del resumen, esquema o mapa conceptual entregado antes del examen y la observaci&oacute;n directa en el aula.</p>', '', '', 1, 1, 1, 1),
(9, 41, 5, 'Ensamblado y secuencia de montaje de equipos informáticos', 42, 2, 25, '<p>En esta unidad el alumnado aprender&aacute; a <strong data-start=\"389\" data-end=\"423\">ensamblar equipos inform&aacute;ticos</strong> aplicando las normas de seguridad, el uso adecuado de herramientas y la correcta secuencia de montaje y desmontaje de los componentes.</p>\r\n<p>Se abordar&aacute;n los principios de <strong data-start=\"592\" data-end=\"629\">seguridad en el puesto de trabajo</strong>, con especial atenci&oacute;n a la prevenci&oacute;n de descargas electrost&aacute;ticas (ESD), la manipulaci&oacute;n de componentes electr&oacute;nicos y las precauciones frente a riesgos el&eacute;ctricos y mec&aacute;nicos.</p>\r\n<p>Asimismo, se estudiar&aacute;n las <strong data-start=\"839\" data-end=\"866\">herramientas necesarias</strong>, los distintos <strong data-start=\"882\" data-end=\"926\">tipos de cajas y fuentes de alimentaci&oacute;n</strong>, los <strong data-start=\"932\" data-end=\"961\">sistemas de refrigeraci&oacute;n</strong> y la <strong data-start=\"967\" data-end=\"1002\">metodolog&iacute;a pr&aacute;ctica de montaje</strong> paso a paso.</p>\r\n<p>La unidad culminar&aacute; con la realizaci&oacute;n de <strong data-start=\"1060\" data-end=\"1084\">pr&aacute;cticas integradas</strong>, en las que el alumnado ensamblar&aacute; un equipo completo a partir de sus componentes, siguiendo procedimientos t&eacute;cnicos y criterios de calidad profesional.</p>', '<p>Esta unidad constituye el eje pr&aacute;ctico fundamental del m&oacute;dulo <em data-start=\"1332\" data-end=\"1368\">Montaje y Mantenimiento de Equipos</em>, al desarrollar las destrezas t&eacute;cnicas que definen el perfil profesional del t&eacute;cnico en Sistemas Microinform&aacute;ticos y Redes.</p>\r\n<p>El conocimiento y aplicaci&oacute;n correcta de las normas de seguridad, la elecci&oacute;n y uso de herramientas, y la secuencia ordenada del montaje son competencias b&aacute;sicas para la instalaci&oacute;n, reparaci&oacute;n y mantenimiento de equipos inform&aacute;ticos.</p>\r\n<p>Adem&aacute;s, permite aplicar de manera integrada los conocimientos adquiridos en unidades anteriores sobre procesadores, placas base, memorias, fuentes de alimentaci&oacute;n y perif&eacute;ricos internos.</p>\r\n<p>Desde una perspectiva transversal, contribuye a la adquisici&oacute;n de h&aacute;bitos de trabajo seguro, ordenado y responsable, fomentando la <strong data-start=\"2052\" data-end=\"2112\">autonom&iacute;a, la precisi&oacute;n t&eacute;cnica y el trabajo cooperativo</strong>.</p>', '', '<p>A lo largo de esta unidad se desarrollar&aacute;n los siguientes contenidos:</p>\r\n<ol>\r\n<li>Advertencias de seguridad\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Pautas generales de seguridad</li>\r\n<li>Pautas generales en caso de incendio</li>\r\n<li>Advertencias en el lugar de trabajo</li>\r\n<li>ESD (Descarga electroest&aacute;tica)</li>\r\n<li>Variaciones en las corrientes</li>\r\n<li>Precauciones sobre los componentes</li>\r\n</ol>\r\n</li>\r\n<li>Herramientas\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Herramientas ESD</li>\r\n<li>Herramientas manuales</li>\r\n<li>Herramientas de limpieza y orden</li>\r\n<li>Herramientas de diagn&oacute;stico</li>\r\n</ol>\r\n</li>\r\n<li>La caja\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Elementos comunes</li>\r\n<li>Chasis</li>\r\n<li>Cubierta</li>\r\n<li>Panel frontal</li>\r\n<li>Cableado del panel frontal</li>\r\n<li>Bah&iacute;as de unidades</li>\r\n<li>Posici&oacute;n de la fuente de alimentaci&oacute;n</li>\r\n<li>Espaciadores de placa base</li>\r\n<li>Ranuras de puertos de E/S</li>\r\n<li>Salidas de tarjetas de expansi&oacute;n</li>\r\n<li>Ventilaci&oacute;n</li>\r\n<li>Tornillos</li>\r\n<li>Formato de cajas</li>\r\n</ol>\r\n</li>\r\n<li>La fuente de alimentaci&oacute;n\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>La fuente de alimentaci&oacute;n</li>\r\n<li>Factor de forma</li>\r\n<li>Fuentes modulares</li>\r\n<li>Fuentes redundantes</li>\r\n<li>Conectores ATX\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Conector principal ATX 20/24 pines</li>\r\n<li>Conector ATX 12V</li>\r\n<li>EPS</li>\r\n<li>PCI Express</li>\r\n<li>M&oacute;lex</li>\r\n<li>SATA</li>\r\n</ol>\r\n</li>\r\n<li>Potencia</li>\r\n<li>Certificaci&oacute;n 80 plus</li>\r\n<li>Cybenetics ETA y LAMBDA</li>\r\n</ol>\r\n</li>\r\n<li>Sistemas de refrigeraci&oacute;n\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Principios de la refrigeraci&oacute;n</li>\r\n<li>Refrigeraci&oacute;n por aire</li>\r\n<li>Refrigeraci&oacute;n l&iacute;quida</li>\r\n</ol>\r\n</li>\r\n<li>Secuencia de montaje\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Sacar cubiertas de la caja</li>\r\n<li>Descargarse electroest&aacute;ticamente</li>\r\n<li>Desconectar conectores de la fuente de alimentaci&oacute;n</li>\r\n<li>Sacar la fuente de alimentaci&oacute;n</li>\r\n<li>Sacar cables de los buses SATA</li>\r\n<li>Sacar los discos duros</li>\r\n<li>Sacar los lectores &oacute;pticos</li>\r\n<li>Desconectar los cables del frontal de la placa base</li>\r\n<li>Sacar las tarjetas de expansi&oacute;n</li>\r\n<li>Sacar la placa base</li>\r\n<li>Sacar la RAM</li>\r\n<li>Retirar refrigerador del procesador</li>\r\n</ol>\r\n</li>\r\n</ol>', '<p>Se comenzar&aacute; la unidad con una exposici&oacute;n de los principales aspectos te&oacute;ricos de las diferentes partes de tema mediante las presentaciones disponible en Aules.</p>\r\n<p>A medida que vamos viendo la parte te&oacute;rica y nunca antes de haber hablado de las advertencias de seguridad y la ESD, alternaremos el contenido te&oacute;rico ejercicio con ejercicios y actividades pr&aacute;cticas. Concretamente, est&aacute;n planificadas las siguientes tareas:</p>\r\n<ul>\r\n<li>Ejercicio de prevenci&oacute;n de riesgos</li>\r\n<li>Pr&aacute;ctica de (Des)montaje de un equipo</li>\r\n<li>Pr&aacute;ctica de caracterizaci&oacute;n del equipo de pr&aacute;cticas</li>\r\n<li>Pr&aacute;ctica de cambio de pasta t&eacute;rmica del equipo de pr&aacute;cticas</li>\r\n</ul>\r\n<p>A lo largo del tema se les asignar&aacute; un equipo de pr&aacute;cticas por pareja para que puedan realizar con &eacute;l las actividades pr&aacute;cticas establecidas y \"aprender haciendo\", afianzando as&iacute; los contenidos te&oacute;ricos de este tema clave del m&oacute;dulo.</p>\r\n<p>Durante las pr&aacute;cticas se les permitir&aacute; el uso de dispositivo m&oacute;vil con la &uacute;nica finalidad de tomar fotograf&iacute;as del proceso, de manera que posteriormente puedan elaborar una \"memoria de pr&aacute;cticas\" donde describan lo realizado y lo documenten gr&aacute;ficamente.</p>\r\n<p>Finalizaremos la unidad con un examen te&oacute;rico al que preceder&aacute; la entrega del resumen, esquema o mapa conceptual que hayan realizado para ir afianzando transversalmente al m&oacute;dulo el empleo de t&eacute;cnicas de estudio.</p>', '', '<p>La evaluaci&oacute;n de la unidad se realizar&aacute; ponderando teor&iacute;a y pr&aacute;ctica al 50% en cada caso. No existir&aacute; nota m&iacute;nima en ninguno de los dos apartados para promediar.</p>\r\n<p>La evaluaci&oacute;n de la parte pr&aacute;ctica se basar&aacute; en r&uacute;bricas de evaluaci&oacute;n de los ejercicios y actividades desarrolladas (30%) y la memoria de las actividades pr&aacute;cticas (70%), as&iacute; como en la observaci&oacute;n directa en el aula&nbsp;</p>\r\n<p>La evaluaci&oacute;n de la parte te&oacute;rica se basar&aacute; en el examen te&oacute;rico al final de la unidad, la valoraci&oacute;n del resumen, esquema o mapa conceptual entregado antes del examen y la observaci&oacute;n directa en el aula.</p>', '', '', 1, 1, 1, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(10, 41, 6, 'Reparación y mantenimiento de equipos informáticos. Imágenes y copias de seguridad', 40, 2, 40, '<p>En esta unidad el alumnado aprender&aacute; a <strong data-start=\"433\" data-end=\"490\">diagnosticar, reparar y mantener equipos inform&aacute;ticos</strong>, aplicando procedimientos t&eacute;cnicos y herramientas de verificaci&oacute;n. Se abordar&aacute;n las <strong data-start=\"575\" data-end=\"603\">comprobaciones iniciales</strong> y la interpretaci&oacute;n de <strong data-start=\"627\" data-end=\"679\">se&ntilde;ales ac&uacute;sticas, luminosas y mensajes de error</strong>, as&iacute; como la identificaci&oacute;n y soluci&oacute;n de los <strong data-start=\"726\" data-end=\"748\">fallos m&aacute;s comunes</strong> en los distintos componentes del sistema (fuente de alimentaci&oacute;n, placa base, procesador, memoria, discos, perif&eacute;ricos, etc.).</p>\r\n<p><br data-start=\"875\" data-end=\"878\" /> La segunda parte de la unidad se centrar&aacute; en la <strong data-start=\"926\" data-end=\"971\">gesti&oacute;n de im&aacute;genes y copias de seguridad</strong>, introduciendo al alumnado en las t&eacute;cnicas de <strong data-start=\"1018\" data-end=\"1041\">clonado de sistemas</strong>, creaci&oacute;n de <strong data-start=\"1055\" data-end=\"1076\">im&aacute;genes de disco</strong> y <strong data-start=\"1079\" data-end=\"1119\">planificaci&oacute;n de copias de seguridad</strong>. Se trabajar&aacute; con distintas herramientas y opciones de arranque, incluyendo BIOS, UEFI, Live CD y USB bootables, fundamentales para el mantenimiento preventivo y correctivo de los equipos.</p>\r\n<p><br data-start=\"1308\" data-end=\"1311\" /> Las actividades combinar&aacute;n pr&aacute;cticas de laboratorio, resoluci&oacute;n de incidencias simuladas y ejercicios de creaci&oacute;n de im&aacute;genes de respaldo.</p>', '<p data-start=\"1482\" data-end=\"1784\">Esta unidad representa la culminaci&oacute;n pr&aacute;ctica del m&oacute;dulo <em data-start=\"1540\" data-end=\"1576\">Montaje y Mantenimiento de Equipos</em>, integrando los conocimientos adquiridos sobre componentes, montaje y configuraci&oacute;n en tareas de <strong data-start=\"1674\" data-end=\"1715\">mantenimiento preventivo y correctivo</strong>.</p>\r\n<p data-start=\"1482\" data-end=\"1784\"><br data-start=\"1716\" data-end=\"1719\" /> Permite desarrollar competencias profesionales esenciales como:</p>\r\n<ul data-start=\"1785\" data-end=\"2088\">\r\n<li data-start=\"1785\" data-end=\"1878\">\r\n<p data-start=\"1787\" data-end=\"1878\"><strong data-start=\"1787\" data-end=\"1813\">Diagn&oacute;stico de aver&iacute;as</strong> mediante la interpretaci&oacute;n de s&iacute;ntomas y mensajes del sistema.</p>\r\n</li>\r\n<li data-start=\"1879\" data-end=\"1968\">\r\n<p data-start=\"1881\" data-end=\"1968\"><strong data-start=\"1881\" data-end=\"1927\">Aplicaci&oacute;n de procedimientos de reparaci&oacute;n</strong> con criterios t&eacute;cnicos y de seguridad.</p>\r\n</li>\r\n<li data-start=\"1969\" data-end=\"2088\">\r\n<p data-start=\"1971\" data-end=\"2088\"><strong data-start=\"1971\" data-end=\"2039\">Implementaci&oacute;n de copias de seguridad y restauraci&oacute;n de sistemas</strong>, garantizando la integridad de la informaci&oacute;n.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"2090\" data-end=\"2326\">&nbsp;</p>\r\n<p data-start=\"2090\" data-end=\"2326\">Asimismo, contribuye al desarrollo de actitudes profesionales como la responsabilidad, la precisi&oacute;n, la capacidad de an&aacute;lisis y la gesti&oacute;n eficiente de recursos tecnol&oacute;gicos, fundamentales para la empleabilidad en el sector inform&aacute;tico.</p>', '', '<p>A lo largo de esta unidad se desarrollar&aacute;n los siguientes contenidos:</p>\r\n<ol>\r\n<li>Reparaci&oacute;n y mantenimiento de equipos inform&aacute;ticos\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Comprobaciones iniciales</li>\r\n<li>Se&ntilde;ales ac&uacute;sticas</li>\r\n<li>Se&ntilde;ales luminosas</li>\r\n<li>Mensajes en pantalla</li>\r\n<li>Fallos comunes</li>\r\n<li>S&iacute;ntomas y comprobaciones de la fuente de alimentaci&oacute;n</li>\r\n<li>S&iacute;ntomas y comprobaciones de la memoria RAM</li>\r\n<li>S&iacute;ntomas y comprobaciones del procesador</li>\r\n<li>S&iacute;ntomas y comprobaciones de la placa base</li>\r\n<li>S&iacute;ntomas y comprobaciones del CD/DVD/Blu-Ray</li>\r\n<li>S&iacute;ntomas y comprobaciones de los discos duros</li>\r\n<li>S&iacute;ntomas y comprobaciones de las tarjetas de expansi&oacute;n (gr&aacute;fica, sonido, red)</li>\r\n<li>S&iacute;ntomas y comprobaciones de los perif&eacute;ricos (teclado, rat&oacute;n, monitor, impresora)</li>\r\n</ol>\r\n</li>\r\n<li>Im&aacute;genes y copias de seguridad\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Im&aacute;genes</li>\r\n<li>Diferencias entre im&aacute;genes y copias de seguridad</li>\r\n<li>Clonado de sistemas</li>\r\n<li>Copias de seguridad</li>\r\n<li>Tipos de copias de seguridad</li>\r\n<li>Ejemplo de esquemas de copias</li>\r\n<li>Opciones de arranque</li>\r\n<li>BIOS y UEFI</li>\r\n<li>Live CD y USB bootable&nbsp;</li>\r\n</ol>\r\n</li>\r\n</ol>', '<p>Se comenzar&aacute; la unidad con una exposici&oacute;n de los principales aspectos te&oacute;ricos de las primera parte del tema (reparaci&oacute;n y mantenimiento) mediante la presentaci&oacute;n disponible en Aules.</p>\r\n<p>A medida que vamos viendo la parte te&oacute;rica y recordando las advertencias de seguridad y la ESD vistas el tema anterior, alternaremos el contenido te&oacute;rico ejercicio con ejercicios y actividades pr&aacute;cticas. Concretamente, est&aacute;n planificadas las siguientes tareas:</p>\r\n<ul>\r\n<li>Pr&aacute;ctica de mantenimiento preventivo y limpieza del equipo de pr&aacute;cticas</li>\r\n<li>Pr&aacute;ctica de comprobaci&oacute;n de la fuente de alimentaci&oacute;n equipo de pr&aacute;cticas con t&eacute;ster ATX</li>\r\n<li>Pr&aacute;ctica de comprobaci&oacute;n de la fuente de alimentaci&oacute;n equipo de pr&aacute;cticas con pol&iacute;metro</li>\r\n</ul>\r\n<p>A lo largo del tema usar&aacute;n por parejas el equipo de pr&aacute;cticas asignado en el tema anterior para que puedan realizar con &eacute;l las actividades pr&aacute;cticas establecidas y \"aprender haciendo\", afianzando as&iacute; los contenidos te&oacute;ricos de este tema clave del m&oacute;dulo.</p>\r\n<p>Durante las pr&aacute;cticas se les permitir&aacute; el uso de dispositivo m&oacute;vil con la &uacute;nica finalidad de tomar fotograf&iacute;as del proceso, de manera que posteriormente puedan continuar ampliando la \"memoria de pr&aacute;cticas\" donde describan lo realizado y lo documenten gr&aacute;ficamente.</p>\r\n<p>Alternaremos las sesiones pr&aacute;cticas con la exposici&oacute;n te&oacute;rica de la segunda parte del tema (im&aacute;genes y copias de seguridad), realizando de esta segunda parte los siguientes ejercicios y actividades pr&aacute;cticas:</p>\r\n<ul>\r\n<li>Ejercicio de USB loaders y software de clonaci&oacute;n</li>\r\n<li>Pr&aacute;ctica de creaci&oacute;n de una imagen de una partici&oacute;n de disco</li>\r\n<li>Pr&aacute;ctica de restauraci&oacute;n de una imagen de una partici&oacute;n de disco</li>\r\n<li>Ejercicio de software de copias de seguridad</li>\r\n</ul>\r\n<p>Finalizaremos la unidad con un examen te&oacute;rico al que preceder&aacute; la entrega del resumen, esquema o mapa conceptual que hayan realizado para ir afianzando transversalmente al m&oacute;dulo el empleo de t&eacute;cnicas de estudio.</p>', '', '<p>La evaluaci&oacute;n de la unidad se realizar&aacute; ponderando teor&iacute;a y pr&aacute;ctica al 50% en cada caso. No existir&aacute; nota m&iacute;nima en ninguno de los dos apartados para promediar.</p>\r\n<p>La evaluaci&oacute;n de la parte pr&aacute;ctica se basar&aacute; en r&uacute;bricas de evaluaci&oacute;n de los ejercicios y actividades desarrolladas (50%) y la memoria de las actividades pr&aacute;cticas (50%), as&iacute; como en la observaci&oacute;n directa en el aula&nbsp;</p>\r\n<p>La evaluaci&oacute;n de la parte te&oacute;rica se basar&aacute; en el examen te&oacute;rico al final de la unidad, la valoraci&oacute;n del resumen, esquema o mapa conceptual entregado antes del examen y la observaci&oacute;n directa en el aula.</p>', '', '', 1, 1, 1, 1),
(11, 41, 7, 'Periféricos', 48, 3, 10, '<p>En esta unidad se estudian los <strong data-start=\"279\" data-end=\"308\">perif&eacute;ricos del ordenador</strong>, comprendiendo su clasificaci&oacute;n, funcionamiento y caracter&iacute;sticas t&eacute;cnicas. Se analizan los <strong data-start=\"401\" data-end=\"444\">perif&eacute;ricos de entrada, salida y mixtos</strong>, abordando tanto los dispositivos tradicionales (teclado, rat&oacute;n, monitor, impresora) como aquellos de &uacute;ltima generaci&oacute;n, incluyendo impresoras 3D y pantallas t&aacute;ctiles.</p>\r\n<p>El alumnado conocer&aacute; las tecnolog&iacute;as empleadas en cada tipo de dispositivo, los distintos conectores, los par&aacute;metros t&eacute;cnicos que determinan su calidad y rendimiento, y los procedimientos b&aacute;sicos de instalaci&oacute;n, configuraci&oacute;n y mantenimiento.</p>\r\n<p>Las actividades combinar&aacute;n an&aacute;lisis te&oacute;rico con <strong data-start=\"908\" data-end=\"968\">pr&aacute;cticas de reconocimiento, instalaci&oacute;n y configuraci&oacute;n</strong> de perif&eacute;ricos reales y virtualizados, fomentando la comprensi&oacute;n del papel de estos dispositivos en la interacci&oacute;n entre el usuario y el sistema inform&aacute;tico.</p>', '<p data-start=\"1159\" data-end=\"1431\">El estudio de los perif&eacute;ricos resulta esencial dentro del m&oacute;dulo <em data-start=\"1224\" data-end=\"1260\">Montaje y Mantenimiento de Equipos</em>, ya que estos dispositivos constituyen la interfaz entre el ordenador y el usuario.<br data-start=\"1344\" data-end=\"1347\" /> El conocimiento de sus tipos, caracter&iacute;sticas y mantenimiento permite al alumnado:</p>\r\n<ul data-start=\"1432\" data-end=\"1681\">\r\n<li data-start=\"1432\" data-end=\"1525\">\r\n<p data-start=\"1434\" data-end=\"1525\">Seleccionar los perif&eacute;ricos adecuados seg&uacute;n las necesidades del usuario o la instalaci&oacute;n.</p>\r\n</li>\r\n<li data-start=\"1526\" data-end=\"1579\">\r\n<p data-start=\"1528\" data-end=\"1579\">Detectar y corregir aver&iacute;as o incompatibilidades.</p>\r\n</li>\r\n<li data-start=\"1580\" data-end=\"1681\">\r\n<p data-start=\"1582\" data-end=\"1681\">Aplicar criterios de eficiencia, ergonom&iacute;a y sostenibilidad en la elecci&oacute;n y uso de dispositivos.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1683\" data-end=\"1944\">Adem&aacute;s, esta unidad fomenta la competencia digital y t&eacute;cnica, as&iacute; como valores transversales como la <strong data-start=\"1784\" data-end=\"1869\">seguridad, la accesibilidad, el reciclaje responsable y la innovaci&oacute;n tecnol&oacute;gica</strong> (por ejemplo, en el caso de las impresoras 3D o las pantallas t&aacute;ctiles).</p>', '', '<p>A lo largo de esta unidad se desarrollar&aacute;n los siguientes contenidos:</p>\r\n<ol>\r\n<li>Perif&eacute;ricos de entrada, salida y mixtos</li>\r\n<li>Perif&eacute;ricos de entrada\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Teclado\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Tipos de conectores</li>\r\n<li>Teclados de membrana</li>\r\n<li>Teclados mec&aacute;nicos</li>\r\n</ol>\r\n</li>\r\n<li>Rat&oacute;n\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Ratones optomec&aacute;nicos</li>\r\n<li>Ratones &oacute;pticos</li>\r\n<li>Ratones l&aacute;ser</li>\r\n<li>Ratones ergon&oacute;micos</li>\r\n<li>Trackballs</li>\r\n<li>Touchpads</li>\r\n<li>Ratones para gaming</li>\r\n</ol>\r\n</li>\r\n<li>Esc&aacute;ner\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Resoluci&oacute;n</li>\r\n<li>Profundidad de color</li>\r\n<li>Velocidad</li>\r\n<li>Tipos de esc&aacute;ner</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n<li>Perif&eacute;ricos de salida\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Monitor\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Tama&ntilde;o</li>\r\n<li>Relaci&oacute;n de aspecto</li>\r\n<li>Brillo, contraste y &aacute;ngulo de visi&oacute;n</li>\r\n<li>Puertos de conexi&oacute;n</li>\r\n<li>Resoluci&oacute;n</li>\r\n<li>Tiempo de respuesta</li>\r\n<li>Tasa de refresco</li>\r\n<li>Tipos de panel</li>\r\n</ol>\r\n</li>\r\n<li>Impresora\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Resoluci&oacute;n</li>\r\n<li>Velocidad de impresi&oacute;n</li>\r\n<li>Tipos y formatos de papel</li>\r\n<li>Impresoras l&aacute;ser</li>\r\n<li>Impresoras de inyecci&oacute;n de tinta</li>\r\n<li>Impresoras matriciales</li>\r\n<li>Impresoras t&eacute;rmicas</li>\r\n<li>Reciclaje de los cartuchos de tinta o t&oacute;ner</li>\r\n<li>Impresoras 3D</li>\r\n<li>Proceso de impresi&oacute;n 3D</li>\r\n<li>Impresoras 3D por deposici&oacute;n de material fundido (FDM)</li>\r\n<li>Impresi&oacute;n 3D por estereolitograf&iacute;a (SLA)</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n<li>Perif&eacute;ricos de entrada/salida (mixtos)\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Impresora multifunci&oacute;n</li>\r\n<li>Pantallas t&aacute;ctiles</li>\r\n</ol>\r\n</li>\r\n</ol>', '<p>Se comenzar&aacute; la unidad con una exposici&oacute;n de los principales aspectos te&oacute;ricos de perif&eacute;ricos mediante la presentaci&oacute;n disponible en Aules.</p>\r\n<p>Una vez vista esta parte inicial, alternaremos el siguiente ejercicio con m&aacute;s aspectos te&oacute;ricos, con los que podr&aacute;n ir complet&aacute;ndolo:</p>\r\n<ul>\r\n<li>Ejercicios de perif&eacute;ricos 1</li>\r\n<li>Ejercicio de presentaci&oacute;n por parejas de un perif&eacute;rico</li>\r\n<li>Pr&aacute;ctica de configuraci&oacute;n de un perif&eacute;rico</li>\r\n</ul>\r\n<p>En el ejercicio de presentaci&oacute;n por parejas de un perif&eacute;rico se permitir&aacute; elegir a cada grupo un perif&eacute;rico no visto en teor&iacute;a, de forma que tenga que realizar una investigaci&oacute;n sobre el mismo y sus caracter&iacute;sticas y posteriormente exponerlo a la clase. De esta forma, agregamos nuevos perif&eacute;ricos a los vistos en el tema de manera guiada por los intereses del alumnado. Adem&aacute;s, trabajamos de forma transversal la competencia comunicativa y expositiva.</p>\r\n<p>A lo largo del tema se les mostrar&aacute;n diversos perif&eacute;ricos de los analizados para que puedan manipularlos, observarlos y comprender las diferencias y afianzar as&iacute; los contenidos te&oacute;ricos que se van desarrollando. Igualmente, la actividad pr&aacute;ctica permite llevar a cabo la tarea de configuraci&oacute;n de un perif&eacute;rico, debiendo para ello lidiar con el manual de instrucciones del fabricante, los drivers, etc.</p>\r\n<p>Finalizaremos la unidad con un examen te&oacute;rico al que preceder&aacute; la entrega del resumen, esquema o mapa conceptual que hayan realizado para ir afianzando transversalmente al m&oacute;dulo el empleo de t&eacute;cnicas de estudio.</p>', '', '<p>La evaluaci&oacute;n de la unidad se realizar&aacute; ponderando teor&iacute;a y pr&aacute;ctica al 50% en cada caso. No existir&aacute; nota m&iacute;nima en ninguno de los dos apartados para promediar.</p>\r\n<p>La evaluaci&oacute;n de la parte pr&aacute;ctica se basar&aacute; en r&uacute;bricas de evaluaci&oacute;n de los ejercicios y actividades desarrolladas, as&iacute; como en la observaci&oacute;n directa en el aula.&nbsp;</p>\r\n<p>La evaluaci&oacute;n de la parte te&oacute;rica se basar&aacute; en el examen te&oacute;rico al final de la unidad, la valoraci&oacute;n del resumen, esquema o mapa conceptual entregado antes del examen y la observaci&oacute;n directa en el aula.</p>', '', '', 1, 1, 1, 1),
(12, 41, 8, 'Tendencias en el ensamblaje de equipos microinformáticos', 19, 3, 5, '<p>En esta unidad se analizan las <strong data-start=\"364\" data-end=\"397\">tendencias actuales y futuras</strong> en el dise&ntilde;o, montaje y evoluci&oacute;n de los equipos microinform&aacute;ticos. El alumnado explorar&aacute; las <strong data-start=\"492\" data-end=\"536\">innovaciones en el conjunto placa&ndash;chasis</strong>, la evoluci&oacute;n de los factores de forma, las nuevas posibilidades de conectividad y las plataformas <strong data-start=\"636\" data-end=\"667\">semiensambladas (barebones)</strong>.</p>\r\n<p>Se abordar&aacute;n tambi&eacute;n los <strong data-start=\"696\" data-end=\"741\">ordenadores de entretenimiento multimedia</strong>, los <strong data-start=\"747\" data-end=\"798\">equipos dise&ntilde;ados para aplicaciones espec&iacute;ficas</strong> (estaciones de trabajo, gaming, IA, entornos industriales), as&iacute; como el papel de la <strong data-start=\"883\" data-end=\"904\">inform&aacute;tica m&oacute;vil</strong> en la transformaci&oacute;n del mercado actual.</p>\r\n<p>Finalmente, se introducir&aacute; el fen&oacute;meno del <strong data-start=\"991\" data-end=\"1002\">modding</strong> como corriente alternativa, donde la personalizaci&oacute;n est&eacute;tica y funcional de los equipos representa una manifestaci&oacute;n t&eacute;cnica y creativa del hardware moderno.</p>\r\n<p>El alumnado desarrollar&aacute; una visi&oacute;n global y actualizada del sector, comprendiendo la importancia de la innovaci&oacute;n, la sostenibilidad y la adaptaci&oacute;n a los cambios tecnol&oacute;gicos.</p>', '<p data-start=\"1374\" data-end=\"1744\">Esta unidad cierra el m&oacute;dulo <em data-start=\"1403\" data-end=\"1439\">Montaje y Mantenimiento de Equipos</em>, proporcionando al alumnado una <strong data-start=\"1472\" data-end=\"1492\">visi&oacute;n de futuro</strong> sobre el sector inform&aacute;tico y las tendencias que marcan el dise&ntilde;o y montaje de equipos modernos.</p>\r\n<p data-start=\"1374\" data-end=\"1744\">Permite conectar los conocimientos adquiridos en unidades anteriores con las nuevas realidades tecnol&oacute;gicas, reforzando competencias relacionadas con:</p>\r\n<ul data-start=\"1745\" data-end=\"1981\">\r\n<li data-start=\"1745\" data-end=\"1795\">\r\n<p data-start=\"1747\" data-end=\"1795\">La <strong data-start=\"1750\" data-end=\"1792\">adaptaci&oacute;n a la evoluci&oacute;n del hardware</strong>.</p>\r\n</li>\r\n<li data-start=\"1796\" data-end=\"1861\">\r\n<p data-start=\"1798\" data-end=\"1861\">La <strong data-start=\"1801\" data-end=\"1834\">capacidad de an&aacute;lisis cr&iacute;tico</strong> ante nuevas tecnolog&iacute;as.</p>\r\n</li>\r\n<li data-start=\"1862\" data-end=\"1981\">\r\n<p data-start=\"1864\" data-end=\"1981\">La <strong data-start=\"1867\" data-end=\"1937\">aplicaci&oacute;n de criterios de innovaci&oacute;n, eficiencia y sostenibilidad</strong> en el montaje y mantenimiento de equipos.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1983\" data-end=\"2401\">Adem&aacute;s, fomenta actitudes emprendedoras y creativas, al mostrar &aacute;mbitos emergentes como el <strong data-start=\"2074\" data-end=\"2085\">modding</strong>, la <strong data-start=\"2090\" data-end=\"2111\">inform&aacute;tica m&oacute;vil</strong>, la <strong data-start=\"2116\" data-end=\"2142\">computaci&oacute;n cient&iacute;fica</strong> o el <strong data-start=\"2148\" data-end=\"2176\">ensamblaje personalizado</strong> para nichos profesionales y de ocio.</p>\r\n<p data-start=\"1983\" data-end=\"2401\">Esta unidad tambi&eacute;n contribuye al desarrollo de la competencia digital, la iniciativa personal y la actualizaci&oacute;n profesional continua, imprescindibles en el entorno tecnol&oacute;gico actual.</p>', '', '<p>A lo largo de esta unidad se desarrollar&aacute;n los siguientes contenidos:</p>\r\n<ol>\r\n<li>Nuevas posibilidades para el conjunto placa-chasis\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Evoluci&oacute;n de factores de forma y tendencias</li>\r\n<li>Innovaciones en chasis</li>\r\n<li>Conectividad y funcionalidad</li>\r\n</ol>\r\n</li>\r\n<li>Prestaciones y caracter&iacute;sticas de plataformas semiensambladas (barebones)\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Definici&oacute;n</li>\r\n<li>Ventajas</li>\r\n<li>Modelos representativos durante este a&ntilde;o</li>\r\n<li>Aplicaciones</li>\r\n<li>Limitaciones</li>\r\n</ol>\r\n</li>\r\n<li>Ordenadores de entretenimiento multimedia\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Concepto y funci&oacute;n</li>\r\n<li>Caracter&iacute;sticas clave</li>\r\n<li>Software multimedia</li>\r\n<li>Integraci&oacute;n</li>\r\n</ol>\r\n</li>\r\n<li>Equipos inform&aacute;ticos para campos de aplicaci&oacute;n espec&iacute;ficos\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Estaciones de trabajo para creativos</li>\r\n<li>PCs industriales</li>\r\n<li>Gaming competitivo</li>\r\n<li>IA y computaci&oacute;n cient&iacute;fica</li>\r\n</ol>\r\n</li>\r\n<li>Inform&aacute;tica m&oacute;vil como mercado emergente\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Dispositivos relevantes\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li>Smartphones</li>\r\n<li>Tablets</li>\r\n<li>Ultrabooks</li>\r\n<li>Dispositivos especializados (e-Readers, navegadores GPS, gafas RV/RA...)</li>\r\n</ol>\r\n</li>\r\n<li>Tendencias</li>\r\n</ol>\r\n</li>\r\n<li>El modding como corriente alternativa\r\n<ol style=\"list-style-type: lower-alpha;\">\r\n<li>Concepto</li>\r\n<li>Tipos de mooding</li>\r\n<li>T&eacute;cnicas y herramientas</li>\r\n<li>Comunidades y eventos</li>\r\n<li>Seguridad</li>\r\n</ol>\r\n</li>\r\n</ol>', '<p>Se comenzar&aacute; la unidad con una exposici&oacute;n de los principales aspectos te&oacute;ricos de cada apartado del tema mediante la presentaci&oacute;n disponible en Aules.</p>\r\n<p>La parte te&oacute;rica se ir&aacute; alternando con ejercicios con aspectos m&aacute;s pr&aacute;ticos, con los que podr&aacute;n ir completando la comprensi&oacute;n de la unidad:</p>\r\n<ul>\r\n<li>Ejercicios de barebones</li>\r\n<li>Presentaci&oacute;n con el an&aacute;lisis de un dispositivo m&oacute;vil</li>\r\n<li>Ejercicio sobre concursos de modding</li>\r\n</ul>\r\n<p>En el ejercicio de presentaci&oacute;n por parejas se permitir&aacute; elegir a cada grupo un dispositivo m&oacute;vil que les resulte atractivo, de forma que tenga que realizar una investigaci&oacute;n sobre el mismo y sus caracter&iacute;sticas y posteriormente exponerlo a la clase. De esta forma, agregamos nuevos dispositivos a los ya vistos en el tema de manera guiada por los intereses del alumnado. Adem&aacute;s, trabajamos de forma transversal la competencia comunicativa y expositiva.</p>\r\n<p>Finalizaremos la unidad con un examen te&oacute;rico al que preceder&aacute; la entrega del resumen, esquema o mapa conceptual que hayan realizado para ir afianzando transversalmente al m&oacute;dulo el empleo de t&eacute;cnicas de estudio.</p>', '', '<p>La evaluaci&oacute;n de la unidad se realizar&aacute; ponderando teor&iacute;a y pr&aacute;ctica al 50% en cada caso. No existir&aacute; nota m&iacute;nima en ninguno de los dos apartados para promediar.</p>\r\n<p>La evaluaci&oacute;n de la parte pr&aacute;ctica se basar&aacute; en r&uacute;bricas de evaluaci&oacute;n de los ejercicios y actividades desarrolladas, as&iacute; como en la observaci&oacute;n directa en el aula.&nbsp;</p>\r\n<p>La evaluaci&oacute;n de la parte te&oacute;rica se basar&aacute; en el examen te&oacute;rico al final de la unidad, la valoraci&oacute;n del resumen, esquema o mapa conceptual entregado antes del examen y la observaci&oacute;n directa en el aula.</p>', '', '', 1, 1, 1, 1),
(13, 281, 3, 'Tipos de datos básicos', 16, 1, 5, '<p>Una vez que el alumno tiene soltura con los n&uacute;meros enteros, se le introducen otros tipos de datos imprescindibles, como los n&uacute;meros reales, los caracteres o los booleanos, adem&aacute;s de otros tipos como las enumeraciones, y una primera toma de contacto con las cadenas de texto.</p>', '<p>Para avanzar en la programaci&oacute;n de sistemas complejos se requiere que el alumno comprenda todas las posibilidades de representaci&oacute;n de la informaci&oacute;n que nos ofrece un lenguaje de programaci&oacute;n.</p>', '<p>Se realizar&aacute; con los ordenadores de la clase o con sus ordenadores personales.</p>', '<p>Tipos de enteros: short/long, signed/unsigned.<br /> Sistemas de numeraci&oacute;n: binario, octal, hexadecimal.<br /> Representaci&oacute;n interna de los enteros<br /> Incremento y decremento<br /> Operaciones abreviadas: +=<br /> Tipo de dato real: Simple y doble precisi&oacute;n, c&oacute;mo mostrar en pantalla.<br /> Tipo de dato car&aacute;cter; c&oacute;mo mostrar en pantalla<br /> Secuencias de escape<br /> Introducci&oacute;n a las cadenas de texto<br /> Tipo enumerado y variables de tipo impl&iacute;cito</p>', '<p>Se realizar&aacute;n peque&ntilde;os retos para practicar:</p>\r\n<p>Realizar operaciones con n&uacute;meros enteros con o sin signo, de mayor o menor tama&ntilde;o.<br /> Cambiar n&uacute;meros enteros de un sistema de numeraci&oacute;n a otra (decimal, binario, octal, hexadecimal).<br /> Incrementar/decrementar el valor de una variable.<br /> Expresar operaciones con notaci&oacute;n abreviada.<br /> Realizaci&oacute;n de operaciones con n&uacute;meros reales, tanto de simple como de doble precisi&oacute;n.<br /> C&aacute;lculo del espacio ocupado por una variable o por un tipo de datos.<br /> Manejo de variables de tipo car&aacute;cter, incluyendo secuencias de escape.<br /> Manejo b&aacute;sico de cadenas de texto<br /> Uso de enumeraciones para problemas de rangos limitados de valores<br /> Uso de variables de tipo impl&iacute;cito</p>', '', '<p>Instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>R&uacute;brica - 70%.&nbsp;\r\n<ul>\r\n<li>Examen te&oacute;rico-pr&aacute;ctico 45%</li>\r\n<li>Pr&aacute;ctica evaluada individualmente 25%</li>\r\n</ul>\r\n</li>\r\n<li>Observaci&oacute;n directa - 25%&nbsp;\r\n<ul>\r\n<li>Ejercicios semanales evaluados</li>\r\n<li>Ejercicios diarios</li>\r\n</ul>\r\n</li>\r\n<li>Evaluaci&oacute;n por pares - 5%&nbsp;\r\n<ul>\r\n<li>Los ejercicios semanales evaluados tienen este % de calificaci&oacute;n de los compa&ntilde;eros</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p>En modalidad <strong>semipresencial</strong>, al no contar con la presencia de alumnado en clase de forma regular, y disponer s&oacute;lo de una parte de la carga docente en las tutor&iacute;as colectivas, el peso de&nbsp;la evaluaci&oacute;n recaer&aacute; 100% en la r&uacute;brica, que a su vez se dividir&aacute; en supuestos pr&aacute;cticos peri&oacute;dicos durante el trimestre (30%) y una prueba presencial de control de los RA y criterios impartidos en ese trimestre (70%). La presente unidad tendr&aacute; el peso final indicado, distribuido entre los RA asociados.</p>\r\n<p>Dimensiones de la r&uacute;brica:</p>\r\n<ul>\r\n<li>Operar con soltura con n&uacute;meros enteros con o sin signo, de mayor o menor tama&ntilde;o.</li>\r\n<li>Ser capaz de cambiar n&uacute;meros enteros de un sistema de numeraci&oacute;n a otra (decimal, binario, octal, hexadecimal).</li>\r\n<li>Saber c&oacute;mo incrementar/decrementar el valor de una variable y c&oacute;mo expresar operaciones con notaci&oacute;n abreviada.</li>\r\n<li>Realizar operaciones con n&uacute;meros reales, conociendo la diferencia entre simple y doble precisi&oacute;n y sabiendo cual elegir seg&uacute;n la situaci&oacute;n.</li>\r\n<li>Saber c&oacute;mo conocer el espacio ocupado por una variable o por un tipo de datos.</li>\r\n<li>Manejar variables de tipo car&aacute;cter, incluyendo secuencias de escape.</li>\r\n<li>Manejar textos simples: leer cadenas de caracteres desde el teclado, mostrarlas en pantalla, asignarles un valor y comparar con otras cadenas.</li>\r\n<li>Manejar tipos enumerados cuando corresponda hacerlo</li>\r\n<li>Utilizar variables de tipo impl&iacute;cito y ser conscientes de cu&aacute;ndo no es recomendable utilizarlas</li>\r\n</ul>\r\n<p>Dimensi&oacute;n de la observaci&oacute;n directa:</p>\r\n<ul>\r\n<li>Seguimiento de las instrucciones para la realizaci&oacute;n de los retos</li>\r\n<li>Ejercicios en papel con correcci&oacute;n por compa&ntilde;eros y realizaci&oacute;n posterior en ordenador</li>\r\n<li>Pensar antes de actuar, reflexi&oacute;n sobre la tarea a realizar</li>\r\n</ul>\r\n<p>Dimensi&oacute;n de la evaluaci&oacute;n por pares</p>\r\n<ul>\r\n<li>Algunos de los retos realizados en clase ser&aacute;n evaluados por los compa&ntilde;eros</li>\r\n</ul>', '', '', 0, 1, 1, 1),
(14, 281, 4, 'Arrays y estructuras', 16, 1, 5, '<p>Se muestran al alumno las estructuras de datos est&aacute;ticas y su manejo, tanto en lo que se refiere a los arrays unidimensionales, bidimensionales, multidimensionales, como a las estructuras, simples o anidadas. Tambi&eacute;n se profundiza m&aacute;s en el uso de las cadenas de texto.</p>', '<p>Se va profundizando en la utilizaci&oacute;n de tipos de datos cada vez m&aacute;s complejos a fin de que los alumnos sean capaces de reflejar los problemas a resolver del mundo real.</p>', '<p>Se realizar&aacute; en clase con sus equipos habituales.</p>', '<p>Conceptos b&aacute;sicos sobre tablas<br /> Arrays unidimensionales<br /> Arrays bidimensionales<br /> Arrays multidimensionales<br /> Arrays indeterminados<br /> Estructuras<br /> Estructuras anidadas<br /> Arrays de estructuras<br /> Cadenas de texto</p>', '<p>Se propondr&aacute;n los siguientes retos:</p>\r\n<ul>\r\n<li>Almacenar datos repetitivos empleando arrays.</li>\r\n<li>Almacenar datos compuestos empleando estructuras.</li>\r\n<li>Combinar el uso de estructuras y arrays para datos repetitivos formados por unidades m&aacute;s complejas.</li>\r\n<li>Procesado de cadenas de texto para obtener o modificar la informaci&oacute;n que contienen.</li>\r\n</ul>\r\n<p class=\"western\" lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\" align=\"justify\">&nbsp;</p>', '', '<p>Instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>R&uacute;brica - 70%.&nbsp;\r\n<ul>\r\n<li>Examen te&oacute;rico-pr&aacute;ctico 45%</li>\r\n<li>Pr&aacute;ctica evaluada individualmente 25%</li>\r\n</ul>\r\n</li>\r\n<li>Observaci&oacute;n directa - 25%&nbsp;\r\n<ul>\r\n<li>Ejercicios semanales evaluados</li>\r\n<li>Ejercicios diarios</li>\r\n</ul>\r\n</li>\r\n<li>Evaluaci&oacute;n por pares - 5%&nbsp;\r\n<ul>\r\n<li>Los ejercicios semanales evaluados tienen este % de calificaci&oacute;n de los compa&ntilde;eros</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p>En modalidad <strong>semipresencial</strong>, al no contar con la presencia de alumnado en clase de forma regular, y disponer s&oacute;lo de una parte de la carga docente en las tutor&iacute;as colectivas, el peso de&nbsp;la evaluaci&oacute;n recaer&aacute; 100% en la r&uacute;brica, que a su vez se dividir&aacute; en supuestos pr&aacute;cticos peri&oacute;dicos durante el trimestre (30%) y una prueba presencial de control de los RA y criterios impartidos en ese trimestre (70%). La presente unidad tendr&aacute; el peso final indicado, distribuido entre los RA asociados.</p>\r\n<p>Dimensiones de la r&uacute;brica:</p>\r\n<ul>\r\n<li>Saber c&oacute;mo almacenar datos repetitivos empleando arrays, acceder a ellos y manipularlos.</li>\r\n<li>Almacenar datos compuestos empleando estructuras, acceder a ellos y manipularlos..</li>\r\n<li>Combinar el uso de estructuras y arrays para datos repetitivos formados por unidades m&aacute;s complejas.</li>\r\n<li></li>\r\n</ul>\r\n<p>Dimensi&oacute;n de la observaci&oacute;n directa:</p>\r\n<ul>\r\n<li>Seguimiento de las instrucciones para la realizaci&oacute;n de los retos</li>\r\n<li>Ejercicios en papel con correcci&oacute;n por compa&ntilde;eros y realizaci&oacute;n posterior en ordenador</li>\r\n<li>Pensar antes de actuar, reflexi&oacute;n sobre la tarea a realizar</li>\r\n</ul>', '', '', 0, 0, 1, 1),
(15, 281, 5, 'Funciones', 24, 1, 5, '<p>Se van a presentar al alumno los conceptos b&aacute;sicos sobre funciones y se realizar&aacute;n diferentes retos para que el alumnos adquiera mediante la pr&aacute;ctica todos esos conceptos.</p>', '<p>El uso de funciones es una caracter&iacute;stica muy importante en cualquier convencional, pues permite realizar un desarrollo modular del programa al tiempo que facilita su mantenimiento y futuro uso en otras aplicaciones. Por eso, se dedica un tema a la creaci&oacute;n y uso de funciones, todav&iacute;a sin hablar de programaci&oacute;n orientada a objetos, de modo que se trate de conocimientos aplicables a otros lenguajes de programaci&oacute;n.</p>', '', '<ul>\r\n<li>Nociones de dise&ntilde;o modular de programas: Descomposici&oacute;n modular</li>\r\n<li>Conceptos b&aacute;sicos sobre funciones: Definici&oacute;n, Declaraci&oacute;n, Llamada</li>\r\n<li>Retorno de una funci&oacute;n</li>\r\n<li>Clases de funciones</li>\r\n<li>Clases de almacenamiento de las variables</li>\r\n<li>Par&aacute;metros de funciones</li>\r\n<li>Funciones y arrays</li>\r\n<li>Recursividad</li>\r\n<li>Otras funciones &uacute;tiles: TryParse y&nbsp;tests de programas</li>\r\n</ul>', '<p>A diferencia de la modalidad presencial, en la modalidad <strong>semipresencial</strong> esta unidad se impartir&aacute; durante el segundo trimestre, ya que en esta modalidad el alumnado traslada la formaci&oacute;n en empresa (FE) a segundo curso, y se cuenta con alguna semana m&aacute;s para ver&nbsp;algunos contenidos m&aacute;s pausadamente.</p>\r\n<p>Se realizar&aacute;n los siguientes retos:</p>\r\n<ul>\r\n<li>Dado un problema, aplicar t&eacute;cnicas de descomposici&oacute;n modular para obtener las funciones m&aacute;s adecuadas para su resoluci&oacute;n.</li>\r\n<li>Definici&oacute;n y uso de funciones, que devuelvan un valor o no (procedimientos).</li>\r\n<li>Definici&oacute;n de variables locales y globales.</li>\r\n<li>Uso de par&aacute;metros de funciones, por valor y por referencia.</li>\r\n<li>Creaci&oacute;n de funciones recursivas.</li>\r\n<li>Obtenci&oacute;n de distintos tipos b&aacute;sicos capturando excepciones en una sola l&iacute;nea con TryParse</li>\r\n<li>Probar el funcionamiento de programas sencillos mediante aserciones</li>\r\n</ul>', '', '<p>Instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>R&uacute;brica - 70%.&nbsp;\r\n<ul>\r\n<li>Examen te&oacute;rico-pr&aacute;ctico 45%</li>\r\n<li>Pr&aacute;ctica evaluada individualmente 25%</li>\r\n</ul>\r\n</li>\r\n<li>Observaci&oacute;n directa - 25%&nbsp;\r\n<ul>\r\n<li>Ejercicios semanales evaluados</li>\r\n<li>Ejercicios diarios</li>\r\n</ul>\r\n</li>\r\n<li>Evaluaci&oacute;n por pares - 5%&nbsp;\r\n<ul>\r\n<li>Los ejercicios semanales evaluados tienen este % de calificaci&oacute;n de los compa&ntilde;eros</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p>En modalidad <strong>semipresencial</strong>, al no contar con la presencia de alumnado en clase de forma regular, y disponer s&oacute;lo de una parte de la carga docente en las tutor&iacute;as colectivas, el peso de&nbsp;la evaluaci&oacute;n recaer&aacute; 100% en la r&uacute;brica, que a su vez se dividir&aacute; en supuestos pr&aacute;cticos peri&oacute;dicos durante el trimestre (30%) y una prueba presencial de control de los RA y criterios impartidos en ese trimestre (70%). La presente unidad tendr&aacute; el peso final indicado, distribuido entre los RA asociados.&nbsp;</p>\r\n<p>Dimensiones de la r&uacute;brica:</p>\r\n<ul>\r\n<li>El alumno debe ser capaz de, dado un problema, aplicar t&eacute;cnicas de descomposici&oacute;n modular para obtener las funciones m&aacute;s adecuadas para su resoluci&oacute;n.</li>\r\n<li>Definir funciones, llamarlas cuando sea necesario, usando valores de retorno o par&aacute;metros para intercambiar informaci&oacute;n.</li>\r\n<li>Definir variables locales para el trabajo interno de la funci&oacute;n.</li>\r\n<li>Definir funciones recursivas, como forma r&aacute;pida de resolver muchos problemas.</li>\r\n<li>Saber utilizar TryParse para el parseo de datos simples libre de excepciones</li>\r\n<li>Saber emplear aserciones para pruebas sencillas del funcionamiento de programas</li>\r\n</ul>\r\n<p>Dimensi&oacute;n de la observaci&oacute;n directa:</p>\r\n<ul>\r\n<li>Seguimiento de las instrucciones para la realizaci&oacute;n de los retos</li>\r\n<li>Ejercicios en papel con correcci&oacute;n por compa&ntilde;eros y realizaci&oacute;n posterior en ordenador</li>\r\n<li>Pensar antes de actuar, reflexi&oacute;n sobre la tarea a realizar</li>\r\n</ul>\r\n<p>Dimensi&oacute;n de la evaluaci&oacute;n por pares</p>\r\n<ul>\r\n<li>Algunos de los retos realizados en clase ser&aacute;n evaluados por los compa&ntilde;eros</li>\r\n</ul>', '', '', 1, 1, 1, 1),
(16, 281, 6, 'Programación orientada a objetos', 48, 2, 25, '<p class=\"western\" style=\"line-height: 100%;\" align=\"justify\">Se introducir&aacute; al alumno en conceptos como &ldquo;objeto&rdquo; y &ldquo;clase&rdquo;, as&iacute; como su definici&oacute;n y uso desde C#. Tambi&eacute;n se formalizar&aacute;n conceptos que hasta esta unidad hab&iacute;an quedado en el aire, como los especificadores de acceso.</p>\r\n<p class=\"western\" style=\"line-height: 100%;\" align=\"justify\">En esta unidad se profundizar&aacute; tambi&eacute;n en detalles m&aacute;s avanzados, como los constructores y destructores, m&eacute;todos y atributos static, el polimorfismo y la sobrecarga, la creaci&oacute;n de arrays de objetos, y las palabras reservadas override y this. Se establecen tambi&eacute;n las diferencias a nivel de herencia e implementaci&oacute;n entre clases, clases abstractas e interfaces.</p>\r\n<div>&nbsp;</div>', '<p>El objetivo principal de una aplicaci&oacute;n inform&aacute;tica es reflejar el mundo real para poder solucionar los problemas de ese mundo real. La programaci&oacute;n orientada a objetos nos da una herramienta para poder realizar ese reflejo del mundo real.</p>', '<p>En clase con sus equipos habituales.</p>', '<ul>\r\n<li>Conceptos de &ldquo;objeto&rdquo; y &ldquo;clase&rdquo;</li>\r\n<li>Definici&oacute;n de clases y de objetos desde C#</li>\r\n<li>Especificadores de acceso</li>\r\n<li>M&eacute;todos y atributos. Propiedades.</li>\r\n<li>Nociones b&aacute;sicas de UML. Generadores de c&oacute;digo.</li>\r\n<li>Composici&oacute;n de clases</li>\r\n<li>Herencia, superclases y subclases</li>\r\n<li>Polimorfismo. Sobrecarga.</li>\r\n<li>Sobreescritura de m&eacute;todos.</li>\r\n<li>M&eacute;todos abstractos y finales.</li>\r\n<li>Constructores y herencia.</li>\r\n<li>Clases abstractas e interfaces</li>\r\n<li>Arrays de objetos.</li>\r\n<li>La palabra &ldquo;this&rdquo;</li>\r\n<li>Sobrecarga de operadores</li>\r\n</ul>', '<p>Se realizar&aacute;n los siguientes retos:</p>\r\n<ul>\r\n<li>Extraer las clases, objetos y relaciones de herencia existentes en un problema real.</li>\r\n<li>Elaborar diagramas de clases para especificar la soluci&oacute;n a un problema real.</li>\r\n<li>Desarrollar programas aplicando los conceptos de la programaci&oacute;n orientada a objetos.</li>\r\n<li>Redise&ntilde;ar programas realizados anteriormente.</li>\r\n<li>A partir de diagramas de clases, plasmar fuentes que incluyan herencia a varios niveles.</li>\r\n<li>Distinguir mediante casos pr&aacute;cticos cu&aacute;ndo utilizar clases normales, clases abstractas o interfaces</li>\r\n<li>Crear subclases que redefinan algunos de los m&eacute;todos existentes en las superclases.</li>\r\n<li>Crear constructores que se apoyen en otros constructores o en otros m&eacute;todos de la superclase.</li>\r\n<li>Crear arrays de objetos.</li>\r\n<li>Crear clases que contengan operadores sobrecargados.</li>\r\n<li class=\"western\" lang=\"es-ES\" style=\"margin-top: 0.18cm; margin-bottom: 0.18cm; line-height: 130%;\">&nbsp;</li>\r\n</ul>', '', '<p>Instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>R&uacute;brica - 70%.&nbsp;\r\n<ul>\r\n<li>Examen te&oacute;rico-pr&aacute;ctico 45%</li>\r\n<li>Pr&aacute;ctica evaluada individualmente 25%</li>\r\n</ul>\r\n</li>\r\n<li>Observaci&oacute;n directa - 25%&nbsp;\r\n<ul>\r\n<li>Ejercicios semanales evaluados</li>\r\n<li>Ejercicios diarios</li>\r\n</ul>\r\n</li>\r\n<li>Evaluaci&oacute;n por pares - 5%&nbsp;\r\n<ul>\r\n<li>Los ejercicios semanales evaluados tienen este % de calificaci&oacute;n de los compa&ntilde;eros</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p>En modalidad <strong>semipresencial</strong>, al no contar con la presencia de alumnado en clase de forma regular, y disponer s&oacute;lo de una parte de la carga docente en las tutor&iacute;as colectivas, el peso de&nbsp;la evaluaci&oacute;n recaer&aacute; 100% en la r&uacute;brica, que a su vez se dividir&aacute; en supuestos pr&aacute;cticos peri&oacute;dicos durante el trimestre (30%) y una prueba presencial de control de los RA y criterios impartidos en ese trimestre (70%). La presente unidad tendr&aacute; el peso final indicado, distribuido entre los RA asociados.</p>\r\n<p>Dimensiones de la r&uacute;brica:</p>\r\n<ul>\r\n<li>Manejar con soltura conceptos como los de clase, herencia, encapsulaci&oacute;n, polimorfismo y sobrecarga.</li>\r\n<li>Ser capaz de extraer las clases, objetos y relaciones de herencia en un enunciado basado en el mundo real.</li>\r\n<li>Elaborar diagramas de clases para especificar la soluci&oacute;n a un problema real.</li>\r\n<li>Saber desarrollar programas aplicando los conceptos de la programaci&oacute;n orientada a objetos.</li>\r\n<li>Poder redise&ntilde;ar programas realizados en puntos anteriores del curso, aplicando en ellos las t&eacute;cnicas de la programaci&oacute;n orientada a objetos.</li>\r\n<li>Ser capaz de crear crear programas con m&aacute;s de un nivel de herencia.</li>\r\n<li>Poder redefinir correctamente m&eacute;todos existentes en las superclases.</li>\r\n<li>Identificar cu&aacute;ndo emplear clases abstractas o interfaces en la resoluci&oacute;n de un problema</li>\r\n<li>Saber crear constructores que se apoyen en otros constructores de la misma clase.</li>\r\n<li>Poder crear constructores que se apoyen en otros constructores de la superclase.</li>\r\n<li>Saber crear, inicializar y consultar arrays de objetos.</li>\r\n<li>Ser capaz de clases que contengan operadores sobrecargados.</li>\r\n</ul>\r\n<p>Dimensi&oacute;n de la observaci&oacute;n directa:</p>\r\n<ul>\r\n<li>Seguimiento de las instrucciones para la realizaci&oacute;n de los retos</li>\r\n<li>Ejercicios en papel con correcci&oacute;n por compa&ntilde;eros y realizaci&oacute;n posterior en ordenador</li>\r\n<li>Pensar antes de actuar, reflexi&oacute;n sobre la tarea a realizar</li>\r\n</ul>\r\n<p>Dimensi&oacute;n de la evaluaci&oacute;n por pares</p>\r\n<ul>\r\n<li>Algunos de los retos realizados en clase ser&aacute;n evaluados por los compa&ntilde;eros</li>\r\n</ul>', '', '', 0, 1, 1, 1),
(22, 51, 1, 'T0. Introducción a Kotlin', 9, 1, 2, '<p class=\"p1\">Este tema introduce el lenguaje de programaci&oacute;n <span class=\"s1\"><strong>Kotlin</strong></span>, lenguaje oficial para el desarrollo de aplicaciones Android. Se abordan los fundamentos esenciales necesarios para comprender la sintaxis, los tipos de datos, el control de flujo, las funciones, las clases y los principios b&aacute;sicos de la programaci&oacute;n orientada a objetos en Kotlin.</p>\r\n<p class=\"p1\">El prop&oacute;sito es que el alumnado adquiera la base conceptual y pr&aacute;ctica que servir&aacute; de soporte para los temas posteriores, donde se aplicar&aacute; Kotlin junto con <span class=\"s1\"><strong>Jetpack Compose</strong></span>, <span class=\"s1\"><strong>ViewModel</strong></span>, <span class=\"s1\"><strong>ROOM</strong></span> y otras librer&iacute;as del ecosistema Android moderno.</p>', '<p class=\"p1\">El dominio del lenguaje <span class=\"s1\"><strong>Kotlin</strong></span> es un requisito imprescindible para el desarrollo de aplicaciones Android contempor&aacute;neas. Desde 2019, Google lo ha establecido como el lenguaje preferido para esta plataforma debido a su <span class=\"s1\"><strong>concisi&oacute;n</strong></span>, <span class=\"s1\"><strong>seguridad</strong></span> y <span class=\"s1\"><strong>compatibilidad total con Java</strong></span>.</p>\r\n<p class=\"p1\">Comprender sus fundamentos permite al alumnado:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Adaptarse a las <span class=\"s1\"><strong>metodolog&iacute;as declarativas</strong></span> propias de Compose.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Aplicar <span class=\"s1\"><strong>buenas pr&aacute;cticas</strong></span> de programaci&oacute;n y arquitectura (MVVM, Clean Architecture).</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Transicionar con fluidez desde lenguajes imperativos (como Java) hacia paradigmas m&aacute;s expresivos y seguros.</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">Este tema act&uacute;a como un <span class=\"s1\"><strong>punto de partida metodol&oacute;gico</strong></span>, garantizando que todos los estudiantes partan de una base homog&eacute;nea y actualizada antes de abordar el desarrollo de interfaces, la persistencia de datos o el consumo de APIs.</p>', '<p class=\"p1\"><span class=\"s1\">El m&oacute;dulo </span><strong>Programaci&oacute;n Multimedia y Dispositivos M&oacute;viles (0489)</strong><span class=\"s1\"> se imparte en el segundo curso del </span><strong>Ciclo Formativo de Grado Superior en Desarrollo de Aplicaciones Multiplataforma (DAM)</strong><span class=\"s1\">.</span></p>\r\n<p class=\"p2\">Dentro de este contexto, el <span class=\"s2\"><strong>Tema 0</strong></span> se sit&uacute;a como una <span class=\"s2\"><strong>unidad de nivelaci&oacute;n inicial</strong></span> que conecta la formaci&oacute;n previa en Programaci&oacute;n y Acceso a Datos con las necesidades espec&iacute;ficas del desarrollo Android moderno.</p>\r\n<p class=\"p2\">Adem&aacute;s, este tema sirve para:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Consolidar la <span class=\"s1\"><strong>base sint&aacute;ctica y sem&aacute;ntica</strong></span> del lenguaje Kotlin.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Introducir el entorno de desarrollo <span class=\"s1\"><strong>Android Studio</strong></span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Preparar al alumnado para las unidades dedicadas a <span class=\"s1\"><strong>Jetpack Compose</strong></span>, <span class=\"s1\"><strong>Navegaci&oacute;n</strong></span>, <span class=\"s1\"><strong>Persistencia</strong></span> y <span class=\"s1\"><strong>Consumo de APIs</strong></span>.</p>\r\n</li>\r\n</ul>', '<ul>\r\n<li>0.1. Introducci&oacute;n</li>\r\n<li>0.2. Primer programa en Kotlin</li>\r\n<li>0.3. Expresividad</li>\r\n<li>0.4. Variables y tipos</li>\r\n<li>0.5. Control de flujo en Kotlin</li>\r\n<li>0.6. Clases y constructores</li>\r\n<li>0.7. Data classes y desestructuraci&oacute;n</li>\r\n<li>0.8. Sealed classes</li>\r\n<li>0.9. Pair</li>\r\n<li>0.10. Funciones</li>\r\n<li>0.11. Colecciones</li>\r\n<li>0.12. Enumerados</li>\r\n<li>0.13. Objetos y Companion Object</li>\r\n<li>0.14. Funciones avanzadas para colecciones en Kotlin</li>\r\n</ul>', '', '', '', '', '', 0, 1, 1, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(24, 51, 2, 'T1. Introducción a Jetpack Compose', 12, 1, 17, '<p class=\"p1\">Este tema introduce los fundamentos te&oacute;ricos y pr&aacute;cticos de <span class=\"s1\"><strong>Jetpack Compose</strong></span>, el toolkit moderno de Android para la creaci&oacute;n de interfaces de usuario declarativas con <span class=\"s1\"><strong>Kotlin</strong></span>.</p>\r\n<p class=\"p1\">Se analizan los principios que sustentan su funcionamiento interno, como la composici&oacute;n, la recomposici&oacute;n, la gesti&oacute;n del estado y el ciclo de vida, y se muestran los elementos b&aacute;sicos para crear interfaces reactivas, eficientes y adaptables.</p>\r\n<p class=\"p1\">El alumnado aprender&aacute; a comprender c&oacute;mo Compose reemplaza el modelo tradicional basado en vistas XML, adoptando un enfoque declarativo m&aacute;s coherente con las arquitecturas modernas como <span class=\"s1\"><strong>MVVM</strong></span> y <span class=\"s1\"><strong>Clean Architecture</strong></span>.</p>', '<p class=\"p1\">Jetpack Compose representa un cambio de paradigma en el desarrollo de interfaces Android.</p>\r\n<p class=\"p1\">Su modelo declarativo y la integraci&oacute;n directa con Kotlin facilitan la creaci&oacute;n de UIs reactivas, reduciendo la complejidad, el c&oacute;digo repetitivo y los errores comunes derivados de la manipulaci&oacute;n de vistas tradicionales.</p>\r\n<p class=\"p1\">Dominar los fundamentos de Compose es esencial para:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Comprender c&oacute;mo se estructura y actualiza la interfaz en funci&oacute;n del estado.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Integrar componentes visuales con la l&oacute;gica del <span class=\"s1\"><strong>ViewModel</strong></span> dentro de un entorno <span class=\"s1\"><strong>reactivo</strong></span> y <span class=\"s1\"><strong>modular</strong></span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Adoptar un estilo de programaci&oacute;n declarativo, orientado a la <span class=\"s1\"><strong>productividad</strong></span> y la <span class=\"s1\"><strong>mantenibilidad</strong></span>.</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">Este tema constituye la <span class=\"s2\"><strong>base conceptual y t&eacute;cnica</strong></span> sobre la que se construyen los temas posteriores dedicados a la composici&oacute;n de interfaces avanzadas, la navegaci&oacute;n, la persistencia de datos y la interacci&oacute;n con APIs.</p>', '<p class=\"p1\">Este tema se enmarca dentro del <span class=\"s1\"><strong>bloque de iniciaci&oacute;n al desarrollo moderno en Android</strong></span>, introduciendo los conceptos que transforman el modo en que se dise&ntilde;an y gestionan las interfaces.</p>\r\n<p class=\"p1\">Su aprendizaje es clave para la transici&oacute;n desde el modelo <span class=\"s1\"><strong>XML + Kotlin</strong></span> hacia el nuevo ecosistema <span class=\"s1\"><strong>Compose + Kotlin</strong></span>, en el que todo el ciclo de interfaz se expresa mediante c&oacute;digo Kotlin y funciones composables.</p>\r\n<p class=\"p1\">Se relaciona directamente con los resultados de aprendizaje del m&oacute;dulo (0489), especialmente los vinculados a:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">La </span><strong>implementaci&oacute;n de interfaces de usuario</strong><span class=\"s1\"> en dispositivos m&oacute;viles.</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">La </span><strong>aplicaci&oacute;n de arquitecturas modulares y patrones de dise&ntilde;o</strong><span class=\"s1\"> (MVVM).</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">La <span class=\"s1\"><strong>gesti&oacute;n del ciclo de vida</strong></span> y la interacci&oacute;n entre capas de presentaci&oacute;n, dominio y datos.</p>\r\n</li>\r\n</ul>', '<ul>\r\n<li>1.1. Fundamentos de Compose\r\n<ul>\r\n<li>1.1.1. &iquest;Qu&eacute; es Jetpack Compose?</li>\r\n<li>1.1.2. Diferencias entre el sistema basado en vistas y Jetpack Compose</li>\r\n<li>1.1.3. Ventajas de Jetpack Compose</li>\r\n<li>Ejemplo 1.1. UI reactiva con estado</li>\r\n</ul>\r\n</li>\r\n<li>1.2. Arquitectura de Compose\r\n<ul>\r\n<li>1.2.1. Componentes clave: Runtime, UI, Compiler</li>\r\n<li>Modularidad y escalabilidad</li>\r\n<li>Ejemplo 1.2. Modularidad</li>\r\n</ul>\r\n</li>\r\n<li>1.3. Trabajo del compilador (IR y transformaciones)\r\n<ul>\r\n<li>1.3.1. Funcionamiento del compilador en Compose</li>\r\n<li>1.3.2. Composable Compiler Plugin</li>\r\n<li>1.3.3. Transformaci&oacute;n en el Intermediate Representation (IR)</li>\r\n</ul>\r\n</li>\r\n<li>1.4. Conexi&oacute;n con el tiempo de ejecuci&oacute;n\r\n<ul>\r\n<li>1.4.1. C&oacute;mo se interpretan y ejecutan los Composables</li>\r\n<li>1.4.2. Sistema de slots y control de recomposici&oacute;n</li>\r\n<li>Ejemplo 1.4. Recomposici&oacute;n</li>\r\n</ul>\r\n</li>\r\n<li>1.5. Introducci&oacute;n a la UI de Compose\r\n<ul>\r\n<li>1.5.1. Estructura b&aacute;sica de un @Composable</li>\r\n<li>1.5.2. Layouts b&aacute;sicos en Compose</li>\r\n</ul>\r\n</li>\r\n<li>1.6. Composici&oacute;n y recomposici&oacute;n\r\n<ul>\r\n<li>1.6.1. &iquest;Qu&eacute; es la recomposici&oacute;n?</li>\r\n<li>1.6.2. Triggers de recomposici&oacute;n</li>\r\n</ul>\r\n</li>\r\n<li>1.7. Estado y diferenciaci&oacute;n inteligente\r\n<ul>\r\n<li>1.7.1. Estado observable</li>\r\n<li>1.7.2. Diferenciaci&oacute;n y control inteligente</li>\r\n<li>Ejemplo 1.7. Recomposici&oacute;n</li>\r\n</ul>\r\n</li>\r\n<li>1.8. Naturaleza y propiedades de las funciones componibles\r\n<ul>\r\n<li>1.8.1. Reglas de los Composables</li>\r\n<li>1.8.2. Efectos secundarios y pureza</li>\r\n<li>1.8.3. Buenas pr&aacute;cticas</li>\r\n</ul>\r\n</li>\r\n<li>1.9. Estrategias de migraci&oacute;n desde Views\r\n<ul>\r\n<li>1.9.1. Interoperabilidad entre Views y Compose</li>\r\n<li>1.9.2. AndroidView: Incluir Views en Compose</li>\r\n<li>1.9.3. ComposeView: Incluir Compose en layouts de Views</li>\r\n<li>1.9.4. Migraci&oacute;n progresiva</li>\r\n</ul>\r\n</li>\r\n<li>1.10. Ciclo de vida de una aplicaci&oacute;n m&oacute;vil\r\n<ul>\r\n<li>1.10.1. Ciclo de vida de una Activity</li>\r\n<li>1.10.2. Ciclo de vida de un Composable</li>\r\n<li>1.10.3. Relaci&oacute;n entre ciclos</li>\r\n</ul>\r\n</li>\r\n</ul>', '', '', '', '', '', 0, 1, 1, 1),
(25, 7, 1, 'Representación de la información', 9, 1, 5, '<p>En esta unidad el alumno aprender&aacute; sobre c&oacute;mo se traduce la informaci&oacute;n a un lenguaje que sea entendible por los sistemas inform&aacute;ticos. Tambi&eacute;n se ver&aacute;n las unidades de medida de informaci&oacute;n que se utilizan actualmente.</p>', '<p>Esta unidad es una unidad fundamental ya que sirve como base para entender muchos de los contenidos que se ver&aacute;n en unidades posteriores: bit, byte, tama&ntilde;os de las unidades de almacenamiento, direcciones de memoria, etc.</p>', '', '<ol>\r\n<li>Representaci&oacute;n de la informaci&oacute;n y unidades de medida.</li>\r\n<li>Sistemas de numeraci&oacute;n.\r\n<ul>\r\n<li>Decimal.</li>\r\n<li>Binario.</li>\r\n<li>Octal.</li>\r\n<li>Hexadecimal.</li>\r\n<li>Conversiones entre sistemas.</li>\r\n</ul>\r\n</li>\r\n<li>Representaci&oacute;n de la informaci&oacute;n alfanum&eacute;rica.\r\n<ul>\r\n<li>ASCII</li>\r\n<li>UNICODE</li>\r\n</ul>\r\n</li>\r\n</ol>', '<ul>\r\n<li>Representaci&oacute;n de la informaci&oacute;n y unidades de medida. Primero se expondr&aacute; que es la informaci&oacute;n, canales de comunicaci&oacute;n y c&oacute;mo se representa la informaci&oacute;n para poder ser entendible por un sistema inform&aacute;tico. Despu&eacute;s se ver&aacute;n las diferentes unidades de medida de informaci&oacute;n que se utilizan actualmente.</li>\r\n<li>Sistemas de numeraci&oacute;n. Los alumnos aprender&aacute;n cu&aacute;les son los sistemas de numeraci&oacute;n m&aacute;s utilizados en sistemas de informaci&oacute;n y c&oacute;mo se realiza la conversi&oacute;n entre ellos.</li>\r\n<li>Por &uacute;ltimo se trabajar&aacute;n los sistemas de codificaci&oacute;n que se utilizan para representar informaci&oacute;n alfanum&eacute;rica.</li>\r\n</ul>', '', '<p style=\"text-align: justify;\"><strong>Modalidad presencial</strong></p>\r\n<p style=\"text-align: justify;\">La asistencia a clase es obligatoria por ley, por tanto, aquellos alumnos que no asistan como m&iacute;nimo al 85% de las horas, no tendr&aacute;n derecho a la evaluaci&oacute;n continua y deber&aacute;n realizar un examen final de todo el m&oacute;dulo.</p>\r\n<p style=\"text-align: justify;\">&nbsp;Al final de cada unidad tem&aacute;tica o de varias relacionadas entre s&iacute; (mismo bloque), podr&aacute; realizarse una prueba te&oacute;rica o te&oacute;rico-pr&aacute;ctica seg&uacute;n la naturaleza de la unidad que servir&aacute; para medir el grado de destreza obtenido en la materia por el alumno. Como m&iacute;nimo se realizar&aacute; una prueba por trimestre. Estas pruebas englobar&aacute;n el contenido que se haya impartido desde la &uacute;ltima prueba realizada. Los per&iacute;odos en los que se imparten las unidades est&aacute;n especificados en el apartado Secuenciaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">As&iacute; mismo se establecer&aacute;n fechas de entrega de las distintas actividades que se vayan planteando a lo largo de cada trimestre. Las actividades no entregadas se puntuar&aacute;n como 0. Las actividades entregadas fuera de plazo podr&aacute;n calificarse como 0 o bien su nota se ver&aacute; reducida en funci&oacute;n del tiempo que se tarde en entregarse una vez terminado el plazo.</p>\r\n<p style=\"text-align: justify;\">La nota de cada evaluaci&oacute;n se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Pruebas objetivas sobre los contenidos te&oacute;ricos y pr&aacute;cticos realizados en la evaluaci&oacute;n</span></span>:&nbsp;<strong>70%.</strong></p>\r\n</li>\r\n<li>\r\n<p>E<span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">jercicios pr&aacute;cticos, ejercicios te&oacute;ricos, trabajos, supuestos te&oacute;rico-pr&aacute;cticos</span></span>:&nbsp;<strong>30%</strong>.&nbsp;</p>\r\n</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n 4,5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Por otra parte, actitudes como utilizar el ordenador para jugar, instalar software no autorizado, cambiar la configuraci&oacute;n de los equipos, actitudes que impidan el funcionamiento de clase con interrupciones continuas, no traer material, ser&aacute; tenido en cuenta y penalizado, independientemente de las sanciones que pudiera dictar el consejo escolar.</p>\r\n<p style=\"text-align: justify;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Modalidad semipresencial</strong></p>\r\n<p style=\"text-align: justify;\">En la modalidad semipresencial, la nota se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Test o ex&aacute;menes te&oacute;rico pr&aacute;cticos sobre los contenidos:&nbsp;<strong>70%</strong></span></span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Ejercicios te&oacute;rico-practicos, trabajos y pr&aacute;cticas presenciales:<strong>&nbsp;30%</strong></span></span></p>\r\n</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Durante la evaluaci&oacute;n se propondr&aacute;n ejercicios de car&aacute;cter te&oacute;rico-pr&aacute;ctico semanales para que el alumno afiance los contenidos aprendidos en cada semana. Estas actividades son obligatorias y deber&aacute;n entregarse todas para poder realizar la media de los ejercicios. Las actividades no entregadas, entregadas fuera de plazo o copiadas, tendr&aacute;n una calificaci&oacute;n de 0.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Aunque en la modalidad semipresencial, de forma general,&nbsp; la asistencia a las tutor&iacute;as no es obligatoria, la asignatura de Fundamentos de Hardware, seg&uacute;n lo dispuesto en la Resoluci&oacute;n de 22 de mayo de 2018 de la Direcci&oacute;n General de Formaci&oacute;n Profesional deber&aacute; realizar una serie de horas presenciales de forma obligatoria. Estas tutorias colectivas obligatorias tendr&aacute;n como objetivo realizar pr&aacute;cticas para el montaje y reparaci&oacute;n de equipos inform&aacute;ticos. La no asistencia a las sesiones de presencialidad obligatoria comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Al final de cada evaluaci&oacute;n se realizar&aacute; una prueba te&oacute;rico-pr&aacute;ctica que servir&aacute; para medir el grado de destreza obtenido en la materia por parte del alumno. La no asistencia a alguno de los ex&aacute;menes que se realizar&aacute;n de cada evaluaci&oacute;n comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n de 5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Para calcular la media del curso se realizar&aacute; una ponderaci&oacute;n en funci&oacute;n de los porcentajes asignados a cada unidad.</p>', '', '', 1, 1, 1, 1),
(26, 15, 1, 'Instalación y configuración de un sistema de gestión de bases de datos', 11, 1, 10, '<p>En esta unidad se estudia los tipos de instalaci&oacute;n y configuraci&oacute;n de un SGBD, los motores de almacenamiento, gesti&oacute;n de conexiones, redes y conjuntos de caracteres. Describe la configuraci&oacute;n del servidor, los comandos principales, el uso de variables del sistema y de sesi&oacute;n, y los ficheros de registro. Adem&aacute;s, ense&ntilde;a c&oacute;mo arrancarlo, administrarlo y monitorizar su funcionamiento.</p>', '<p>El conocimiento para la instalaci&oacute;n y configuraci&oacute;n de un sistema de gesti&oacute;n de bases de datos es necesario para:</p>\r\n<ul>\r\n<li>Instalar un servidor SGBD.</li>\r\n<li>Conocer las principales opciones de configuraci&oacute;n de un SGBD.</li>\r\n<li>Optimizar el funcionamiento de un SGBD.</li>\r\n<li>Monitorizar un SGBD.</li>\r\n<li>Aprender a gestionar ficheros de registro.</li>\r\n<li>Conocer la estructura del diccionario de datos de un SGBD.</li>\r\n</ul>', '', '<ul>\r\n<li>Funciones del sistema de gesti&oacute;n de bases de datos (SGBD).</li>\r\n<li>Componentes. Tipos.</li>\r\n<li>Arquitectura del sistema de gesti&oacute;n de bases de datos. Arquitectura ANSI/SPARC.</li>\r\n<li>Sistemas de gesti&oacute;n de bases de datos comerciales y libres.</li>\r\n<li>Instalaci&oacute;n y configuraci&oacute;n de un SGBD monocapa. Par&aacute;metros relevantes.</li>\r\n<li>Elementos de un SGBD de dos capas.</li>\r\n<li>Instalaci&oacute;n de un SGBD de dos capas.</li>\r\n<li>Interfaces est&aacute;ndar (ODBC, JDBC); conectores.</li>\r\n<li>Configuraci&oacute;n de los par&aacute;metros relevantes.</li>\r\n<li>Condiciones de inicio y de parada.</li>\r\n<li>Motor de la base de datos.</li>\r\n<li>Cuentas de administraci&oacute;n.</li>\r\n<li>Herramientas y software cliente del SGBD.</li>\r\n<li>Conexi&oacute;n: tiempos de espera, n&uacute;mero m&aacute;ximo de conexiones, etc.</li>\r\n<li>Estructura del diccionario de datos.<br />Ficheros LOG y mensajes de error.</li>\r\n<li>SGBD de tres capas.</li>\r\n<li>Otros sistemas de almacenamiento (XML, servicios de directorios...).</li>\r\n<li>Documentaci&oacute;n de la instalaci&oacute;n y la configuraci&oacute;n.</li>\r\n</ul>', '', '', '<p>El 60% de la nota final del m&oacute;dulo la determinar&aacute; la nota obtenida en la 1&ordf; evaluaci&oacute;n. El 40% de la nota final del m&oacute;dulo la determinar&aacute; la nota obtenida en la 2&ordf; evaluaci&oacute;n.<br /><br />En cada evaluaci&oacute;n se realizar&aacute;n:<br />- Pr&aacute;cticas y actividades evaluables, que ponderaran un 30% sobre la nota de la evaluaci&oacute;n.<br />- Examen te&oacute;rico-pr&aacute;ctico, que ponderaran un 70% sobre la nota de la evaluaci&oacute;n.<br /><br />En la modalidad semipresencial, ninguna de las actividades y ejercicios propuestos ser&aacute;n considerados evaluables y, por lo tanto, no se solicitar&aacute; su entrega para su evaluaci&oacute;n. Los criterios de evaluaci&oacute;n y calificaci&oacute;n se ajustar&aacute;n exclusivamente a la realizaci&oacute;n del examen, que ser&aacute; acorde a la cantidad de horas correspondientes a cada evaluaci&oacute;n.<br /><br />Para aprobar el m&oacute;dulo, considerando todas las notas sobre un m&aacute;ximo de 10 puntos, ser&aacute; necesario cumplir las siguientes condiciones:<br />5 o m&aacute;s puntos en la nota final para aprobar el m&oacute;dulo.<br />5 o m&aacute;s puntos en cada evaluaci&oacute;n.<br />4 o m&aacute;s puntos en los ex&aacute;menes te&oacute;rico-pr&aacute;cticos de cada evaluaci&oacute;n.<br />4 o m&aacute;s puntos en la nota ponderada de las pr&aacute;cticas y actividades evaluables de cada evaluaci&oacute;n, si las hubiera.<br />4 o m&aacute;s puntos en cada pr&aacute;ctica y actividad evaluable individual, si las hubiera.</p>', '', '', 1, 1, 1, 1),
(27, 51, 3, 'T2. Interfaz de usuario', 10, 1, 15, '<p class=\"p1\">En este tema se profundiza en la <span class=\"s1\"><strong>construcci&oacute;n de interfaces gr&aacute;ficas</strong></span> mediante <span class=\"s1\"><strong>Jetpack Compose</strong></span>, explorando la composici&oacute;n visual, los modificadores, los layouts, el posicionamiento, el dibujo personalizado y las capas de renderizado.</p>\r\n<p class=\"p1\">El alumnado aprender&aacute; a crear <span class=\"s1\"><strong>interfaces adaptables, estructuradas y eficientes</strong></span>, comprendiendo el papel de cada elemento en el proceso de composici&oacute;n y el flujo de medici&oacute;n, disposici&oacute;n y dibujo.</p>\r\n<p class=\"p1\">Adem&aacute;s, se introduce el uso de <span class=\"s1\"><strong>Scaffold</strong></span>, <span class=\"s1\"><strong>TopAppBar</strong></span>, <span class=\"s1\"><strong>BottomBar</strong></span> y otros componentes de estructura que permiten organizar pantallas completas, as&iacute; como la creaci&oacute;n de <span class=\"s1\"><strong>listas din&aacute;micas</strong></span> equivalentes a <span class=\"s2\">RecyclerView</span> mediante <span class=\"s2\">LazyColumn</span> y <span class=\"s2\">LazyRow</span>.</p>', '<p class=\"p1\">El dise&ntilde;o de interfaces constituye uno de los pilares del desarrollo de aplicaciones m&oacute;viles. Con Jetpack Compose, este proceso se transforma gracias a un enfoque <span class=\"s1\"><strong>declarativo y funcional</strong></span>, que reemplaza la jerarqu&iacute;a de vistas XML por <span class=\"s1\"><strong>funciones composables reutilizables</strong></span> y f&aacute;cilmente mantenibles.</p>\r\n<p class=\"p1\">Dominar estos conceptos permite al alumnado:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Comprender c&oacute;mo se organiza la <span class=\"s1\"><strong>estructura visual</strong></span> de una interfaz en Compose.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Controlar el uso de <span class=\"s1\"><strong>modificadores</strong></span> para definir tama&ntilde;o, posici&oacute;n, color, espaciado y comportamiento.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Dise&ntilde;ar <span class=\"s1\"><strong>layouts personalizados</strong></span> ajustados a las necesidades de la aplicaci&oacute;n.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Aplicar t&eacute;cnicas de <span class=\"s1\"><strong>dibujo y composici&oacute;n avanzada</strong></span>, fundamentales en temas posteriores (como animaciones o gr&aacute;ficos).</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">El tema es esencial para construir aplicaciones modernas, adaptables y coherentes con las directrices <span class=\"s1\"><strong>Material Design 3</strong></span>, integrando principios de usabilidad, consistencia y eficiencia visual.</p>', '<p class=\"p1\">Este tema se enmarca en el bloque dedicado a la <span class=\"s1\"><strong>interfaz de usuario en Android moderno</strong></span>, constituyendo la continuaci&oacute;n natural del tema anterior.</p>\r\n<p class=\"p1\">Mientras que el tema anterior abordaba los fundamentos te&oacute;ricos y conceptuales del sistema declarativo, este se centra en la <span class=\"s1\"><strong>aplicaci&oacute;n pr&aacute;ctica de los componentes de UI</strong></span>, el uso de layouts y el dibujo en pantalla.</p>', '<ul>\r\n<li>2.1. Modificadores\r\n<ul>\r\n<li>2.1.1. Sintaxis de encadenamiento</li>\r\n<li>2.1.2. Orden de aplicaci&oacute;n y optimizaci&oacute;n</li>\r\n<li>2.1.3. Modificadores internos vs personalizados</li>\r\n<li>Ejemplo 2.1. Modificadores</li>\r\n</ul>\r\n</li>\r\n<li>2.2. Layout personalizado con Modifier.layout\r\n<ul>\r\n<li>2.2.1. C&oacute;mo crear layouts con reglas propias</li>\r\n</ul>\r\n</li>\r\n<li>2.3. &Aacute;rbol de Layout y fases de renderizado\r\n<ul>\r\n<li>2.3.1. &iquest;Qu&eacute; es el Layout Tree?</li>\r\n<li>2.3.2. Fases de renderizado: composici&oacute;n, disposici&oacute;n, dibujo</li>\r\n<li>2.3.3. Herramientas relacionadas</li>\r\n</ul>\r\n</li>\r\n<li>2.4. Intr&iacute;nsecos y restricciones\r\n<ul>\r\n<li>2.4.1. Las medidas intr&iacute;nsecas</li>\r\n<li>2.4.2. Limitaciones de las medidas intr&iacute;nsecas</li>\r\n<li>2.4.3. Uso de BoxWithConstraints</li>\r\n</ul>\r\n</li>\r\n<li>2.5. Lienzo y gr&aacute;ficos\r\n<ul>\r\n<li>2.5.1. &iquest;Qu&eacute; es Canvas?</li>\r\n<li>2.5.2. Uso b&aacute;sico de Canvas</li>\r\n<li>2.5.3. Primitivas</li>\r\n<li>Ejemplo 2.5. Canvas sencillo</li>\r\n</ul>\r\n</li>\r\n<li>2.6. Capas de dibujo y graphicsLayer\r\n<ul>\r\n<li>2.6.1. &iquest;Qu&eacute; es graphicsLayer?</li>\r\n<li>Ejemplo 2.6. Rotar y escalar un Box</li>\r\n<li>2.6.2. Animaciones con graphicsLayer</li>\r\n</ul>\r\n</li>\r\n<li>2.7. Estructura visual con Scaffold y TopAppBar\r\n<ul>\r\n<li>2.7.1. &iquest;Qu&eacute; es Scaffold?</li>\r\n<li>2.7.2. Uso b&aacute;sico de Scaffold con TopAppBar</li>\r\n<li>2.7.3. A&ntilde;adiendo BottomAppBar y FloatingActionButton</li>\r\n<li>2.7.4. Organizaci&oacute;n de pantallas por secciones</li>\r\n</ul>\r\n</li>\r\n<li>2.8. Elementos b&aacute;sicos de la UI\r\n<ul>\r\n<li>2.8.1. Texto o etiqueta: Text (equivalente a TextView)</li>\r\n<li>2.8.2. Cuadro de texto: TextField (equivalente a EditText)</li>\r\n<li>2.8.3. Casilla: Checkbox</li>\r\n<li>2.8.4. Bot&oacute;n de opci&oacute;n: RadioButton</li>\r\n<li>2.8.5. Interruptor: Switch</li>\r\n<li>2.8.6. Imagen: Image (equivalente a ImageView)</li>\r\n<li>2.8.7. Cargar im&aacute;genes desde URL con librer&iacute;as externas</li>\r\n<li>2.8.8. Desplazamiento del contenido: ScrollView</li>\r\n</ul>\r\n</li>\r\n<li>2.9. Listas con LazyColumn y LazyRow\r\n<ul>\r\n<li>2.9.1. Diferencias clave respecto a RecyclerView</li>\r\n<li>2.9.2. Estructura b&aacute;sica con items</li>\r\n<li>2.9.3. Utilizando itemsIndexed</li>\r\n<li>2.9.4. Delegaci&oacute;n de eventos y selecci&oacute;n de &iacute;tems</li>\r\n<li>2.9.5. Optimizaci&oacute;n de listas grandes</li>\r\n<li>2.9.6. Ejemplo completo con LazyColumn</li>\r\n<li>2.9.7. LazyRow para scroll horizontal</li>\r\n</ul>\r\n</li>\r\n<li>2.10. Notificaciones visuales: Snackbar y Toast\r\n<ul>\r\n<li>2.10.1. Diferencias clave entre Snackbar y Toast</li>\r\n<li>2.10.2. Mostrar un Snackbar con acci&oacute;n</li>\r\n<li>2.10.3. Mostrar un Toast en Compose</li>\r\n<li>Ejemplo 2.10. Combinando ambos</li>\r\n</ul>\r\n</li>\r\n<li>2.11. Men&uacute;s en Jetpack Compose\r\n<ul>\r\n<li>2.11.1. Men&uacute; b&aacute;sico: DropdownMenu</li>\r\n<li>2.11.2. Men&uacute; en overflow de TopAppBar</li>\r\n<li>2.11.3. Men&uacute; largo y scrollable</li>\r\n<li>2.11.4. Men&uacute; con iconos y divisores</li>\r\n<li>2.11.5. Men&uacute; expuesto (Spinner): ExposedDropdownMenuBox</li>\r\n<li>2.11.6. Men&uacute; expuesto editable (autocomplete)</li>\r\n<li>2.11.7. Men&uacute; en cascada: CascadeDropdownMenu</li>\r\n</ul>\r\n</li>\r\n<li>2.12. Cuadros de di&aacute;logo (AlertDialog)\r\n<ul>\r\n<li>2.12.1. Cuadro de di&aacute;logo informativo</li>\r\n<li>2.12.2. Cuadro de di&aacute;logo b&aacute;sico</li>\r\n<li>2.12.3. Cuadro de di&aacute;logo personalizado</li>\r\n<li>2.12.4. Selecci&oacute;n de hora: TimePicker</li>\r\n<li>2.12.5. Selecci&oacute;n de fecha: DatePicker</li>\r\n<li>2.12.6. Buenas pr&aacute;cticas</li>\r\n</ul>\r\n</li>\r\n</ul>', '', '', '', '', '', 0, 1, 1, 1),
(28, 15, 2, 'Acceso a la información', 14, 1, 25, '<p>La gesti&oacute;n de usuarios y permisos, abarca la creaci&oacute;n de cuentas, asignaci&oacute;n y revocaci&oacute;n de privilegios, control de acceso, cifrado de contrase&ntilde;as y limitaci&oacute;n de recursos. Tambi&eacute;n aborda la seguridad en las conexiones mediante TLS/SSL y SSH, garantizando la autenticaci&oacute;n, confidencialidad e integridad de los datos entre cliente y servidor.</p>', '<p>Comprender y dominar el acceso a la informaci&oacute;n es fundamental para:</p>\r\n<ul>\r\n<li>Entender lo que es una cuenta de usuario.</li>\r\n<li>Entender el sistema de acceso a los recursos del servidor y el sistema de permisos.</li>\r\n<li>Aprender los comandos SQL para la gesti&oacute;n de cuentas y permisos</li>\r\n</ul>', '', '<ul>\r\n<li>Creaci&oacute;n, modificaci&oacute;n y eliminaci&oacute;n de vistas.</li>\r\n<li>Administraci&oacute;n de usuarios.</li>\r\n<li>Sin&oacute;nimos de tablas y vistas.</li>\r\n<li>Creaci&oacute;n y eliminaci&oacute;n de usuarios.</li>\r\n<li>Asignaci&oacute;n y desasignaci&oacute;n de derechos a usuarios. Puntos de acceso al sistema.</li>\r\n<li>Verificaci&oacute;n de los derechos de usuario.</li>\r\n<li>Seguridad en el acceso al sistema. Privilegios sobre la base de datos y sus elementos.</li>\r\n<li>Definici&oacute;n de roles; asignaci&oacute;n y desasignaci&oacute;n de roles a usuarios.</li>\r\n<li>Normativa legal vigente sobre protecci&oacute;n de datos.</li>\r\n</ul>', '', '', '<p>El 60% de la nota final del m&oacute;dulo la determinar&aacute; la nota obtenida en la 1&ordf; evaluaci&oacute;n. El 40% de la nota final del m&oacute;dulo la determinar&aacute; la nota obtenida en la 2&ordf; evaluaci&oacute;n.<br /><br />En cada evaluaci&oacute;n se realizar&aacute;n:<br />- Pr&aacute;cticas y actividades evaluables, que ponderaran un 30% sobre la nota de la evaluaci&oacute;n.<br />- Examen te&oacute;rico-pr&aacute;ctico, que ponderaran un 70% sobre la nota de la evaluaci&oacute;n.<br /><br />En la modalidad semipresencial, ninguna de las actividades y ejercicios propuestos ser&aacute;n considerados evaluables y, por lo tanto, no se solicitar&aacute; su entrega para su evaluaci&oacute;n. Los criterios de evaluaci&oacute;n y calificaci&oacute;n se ajustar&aacute;n exclusivamente a la realizaci&oacute;n del examen, que ser&aacute; acorde a la cantidad de horas correspondientes a cada evaluaci&oacute;n.<br /><br />Para aprobar el m&oacute;dulo, considerando todas las notas sobre un m&aacute;ximo de 10 puntos, ser&aacute; necesario cumplir las siguientes condiciones:<br />5 o m&aacute;s puntos en la nota final para aprobar el m&oacute;dulo.<br />5 o m&aacute;s puntos en cada evaluaci&oacute;n.<br />4 o m&aacute;s puntos en los ex&aacute;menes te&oacute;rico-pr&aacute;cticos de cada evaluaci&oacute;n.<br />4 o m&aacute;s puntos en la nota ponderada de las pr&aacute;cticas y actividades evaluables de cada evaluaci&oacute;n, si las hubiera.<br />4 o m&aacute;s puntos en cada pr&aacute;ctica y actividad evaluable individual, si las hubiera.</p>', '', '', 1, 1, 1, 1),
(29, 51, 4, 'T3. Intents y permisos', 10, 1, 8, '<p class=\"p1\">Este tema introduce el uso de <span class=\"s1\"><strong>Intents</strong></span> y la <span class=\"s1\"><strong>gesti&oacute;n de permisos</strong></span> en el desarrollo de aplicaciones Android modernas.</p>\r\n<p class=\"p1\">Se estudia c&oacute;mo los Intents permiten <span class=\"s1\"><strong>comunicar componentes</strong></span> &mdash;tanto internos de la aplicaci&oacute;n como externos del sistema&mdash;, as&iacute; como la manera de solicitar y controlar permisos sensibles (c&aacute;mara, ubicaci&oacute;n, micr&oacute;fono, etc.) siguiendo las pr&aacute;cticas actuales de <span class=\"s1\"><strong>seguridad y privacidad</strong></span> establecidas por Android.</p>\r\n<p class=\"p1\">El alumnado aprender&aacute; a:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Enviar y recibir datos entre actividades mediante <span class=\"s1\"><strong>Intents expl&iacute;citos e impl&iacute;citos</strong></span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Lanzar acciones del sistema (como abrir la c&aacute;mara o la galer&iacute;a).</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Solicitar permisos en tiempo de ejecuci&oacute;n de forma segura utilizando <span class=\"s1\"><strong>ActivityResultLauncher</strong></span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Integrar este comportamiento dentro de composables mediante <span class=\"s1\"><strong>rememberLauncherForActivityResult</strong></span>.</p>\r\n</li>\r\n</ul>', '<p class=\"p1\">El sistema Android est&aacute; dise&ntilde;ado sobre un modelo de componentes que cooperan entre s&iacute; mediante <span class=\"s1\"><strong>Intents</strong></span>. Comprender c&oacute;mo se comunican las actividades, servicios y aplicaciones externas es esencial para crear aplicaciones funcionales, seguras y respetuosas con la privacidad del usuario.</p>\r\n<p class=\"p1\">Asimismo, desde Android 6.0 (API 23), la gesti&oacute;n de <span class=\"s1\"><strong>permisos en tiempo de ejecuci&oacute;n</strong></span> es obligatoria para operaciones sensibles.</p>\r\n<p class=\"p1\">Por tanto, este tema es clave para:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">Entender la </span><strong>comunicaci&oacute;n entre componentes y aplicaciones</strong><span class=\"s1\">.</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Implementar correctamente la <span class=\"s1\"><strong>solicitud de permisos</strong></span> seg&uacute;n las pol&iacute;ticas actuales de Android.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">Aplicar buenas pr&aacute;cticas de </span><strong>seguridad, privacidad y experiencia de usuario</strong><span class=\"s1\">.</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Preparar la base para temas posteriores como <span class=\"s1\"><strong>multimedia</strong></span>, <span class=\"s1\"><strong>sensores</strong></span> o <span class=\"s1\"><strong>acceso a almacenamiento</strong></span>.</p>\r\n</li>\r\n</ul>', '<p class=\"p1\">Su aprendizaje permite comprender el ciclo de vida de las operaciones que involucran:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Comunicaci&oacute;n entre pantallas.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Llamadas a servicios del sistema (como c&aacute;mara, contactos o localizaci&oacute;n).</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Solicitud y control de permisos en tiempo de ejecuci&oacute;n.</p>\r\n</li>\r\n</ul>', '<ul>\r\n<li>3.1. Creaci&oacute;n y navegaci&oacute;n entre actividades\r\n<ul>\r\n<li>3.1.1. Crear nuevas Activity</li>\r\n<li>3.1.2. Enviar datos con Intent</li>\r\n<li>3.1.3. Recibir resultados</li>\r\n</ul>\r\n</li>\r\n<li>3.2. Gesti&oacute;n de permisos\r\n<ul>\r\n<li>3.2.1. &iquest;Qu&eacute; es un ViewModel?</li>\r\n<li>3.2.2. Integrar permisos con ViewModel</li>\r\n</ul>\r\n</li>\r\n<li>3.3. Intents impl&iacute;citos\r\n<ul>\r\n<li>3.3.1. Abrir una URL en el navegador del dispositivo</li>\r\n<li>3.3.2. Marcar un n&uacute;mero de tel&eacute;fono</li>\r\n<li>3.3.3. Abrir una aplicaci&oacute;n de mapas</li>\r\n<li>3.3.4. Escribir un correo electr&oacute;nico</li>\r\n<li>3.3.5. Crear una alarma</li>\r\n<li>3.3.6. Realizar una llamada telef&oacute;nica</li>\r\n</ul>\r\n</li>\r\n<li>3.4. Creaci&oacute;n y navegaci&oacute;n entre actividades\r\n<ul>\r\n<li>3.4.1. Crear nuevas Activity</li>\r\n<li>3.4.2. Enviar datos con Intent</li>\r\n<li>3.4.3. Recibir resultados con ActivityResultLauncher</li>\r\n<li>3.4.4. &iquest;Cu&aacute;ndo usar varias Activity?</li>\r\n</ul>\r\n</li>\r\n</ul>', '', '', '', '', '', 0, 1, 1, 1),
(30, 15, 3, 'Automatización de tareas. Construcción de guiones de administración', 14, 1, 25, '<p>La automatizaci&oacute;n de tareas en SGBD representa uno de los pilares fundamentales en la administraci&oacute;n moderna de bases de datos. Este enfoque sistem&aacute;tico permite a los administradores de bases de datos LDBA) optimizar el rendimiento, garantizar la integridad de los datos y mantener la continuidad operacional de los sistemas de informaci&oacute;n empresariales.<br />La implementaci&oacute;n efectiva de scripts de administraci&oacute;n no solo reduce la carga de trabajo manual, sino que tambi&eacute;n minimiza significativamente los errores humanos y asegura la consistencia en la ejecuci&oacute;n de procedimientos cr&iacute;ticos.</p>', '<p>Dominar la automatizaci&oacute;n de tareas y construcci&oacute;n de guiones de administraci&oacute;n es fundamental para:</p>\r\n<ul>\r\n<li>Automatizar operaciones sobre bases de datos relacionales.</li>\r\n<li>Incrementar la eficiencia de procesos repetitivos mediante procedimientos y funciones.</li>\r\n<li>Recorrer y procesar conjuntos de datos fila a fila con cursores.</li>\r\n<li>Implementar controles de integridad y auditor&iacute;a mediante triggers.</li>\r\n<li>Manejar excepciones y garantizar la consistencia de los datos en operaciones complejas.</li>\r\n</ul>', '', '<ul>\r\n<li>Herramientas para creaci&oacute;n de guiones; procedimientos de ejecuci&oacute;n.</li>\r\n<li>Planificaci&oacute;n de tareas de administraci&oacute;n mediante guiones.</li>\r\n<li>T&eacute;cnicas de planificaci&oacute;n de tareas.</li>\r\n<li>Herramientas de planificaci&oacute;n del SGBD: eventos, disparadores, excepciones, documentaci&oacute;n, entre otras.</li>\r\n</ul>', '', '', '<p>El 60% de la nota final del m&oacute;dulo la determinar&aacute; la nota obtenida en la 1&ordf; evaluaci&oacute;n. El 40% de la nota final del m&oacute;dulo la determinar&aacute; la nota obtenida en la 2&ordf; evaluaci&oacute;n.<br /><br />En cada evaluaci&oacute;n se realizar&aacute;n:<br />- Pr&aacute;cticas y actividades evaluables, que ponderaran un 30% sobre la nota de la evaluaci&oacute;n.<br />- Examen te&oacute;rico-pr&aacute;ctico, que ponderaran un 70% sobre la nota de la evaluaci&oacute;n.<br /><br />En la modalidad semipresencial, ninguna de las actividades y ejercicios propuestos ser&aacute;n considerados evaluables y, por lo tanto, no se solicitar&aacute; su entrega para su evaluaci&oacute;n. Los criterios de evaluaci&oacute;n y calificaci&oacute;n se ajustar&aacute;n exclusivamente a la realizaci&oacute;n del examen, que ser&aacute; acorde a la cantidad de horas correspondientes a cada evaluaci&oacute;n.<br /><br />Para aprobar el m&oacute;dulo, considerando todas las notas sobre un m&aacute;ximo de 10 puntos, ser&aacute; necesario cumplir las siguientes condiciones:<br />5 o m&aacute;s puntos en la nota final para aprobar el m&oacute;dulo.<br />5 o m&aacute;s puntos en cada evaluaci&oacute;n.<br />4 o m&aacute;s puntos en los ex&aacute;menes te&oacute;rico-pr&aacute;cticos de cada evaluaci&oacute;n.<br />4 o m&aacute;s puntos en la nota ponderada de las pr&aacute;cticas y actividades evaluables de cada evaluaci&oacute;n, si las hubiera.<br />4 o m&aacute;s puntos en cada pr&aacute;ctica y actividad evaluable individual, si las hubiera.</p>', '', '', 1, 1, 1, 1),
(31, 15, 4, 'Optimización del rendimiento. Monitorización y optimización', 14, 2, 20, '<p>Abordar la optimizaci&oacute;n y monitorizaci&oacute;n de un SGBD, centr&aacute;ndola en mejorar el rendimiento del sistema mediante ajustes de configuraci&oacute;n, &iacute;ndices, consultas eficientes y control del uso de recursos. El empleo de herramientas de diagn&oacute;stico, junto con t&eacute;cnicas de mantenimiento preventivo y an&aacute;lisis de rendimiento, es fundamental para garantizar la estabilidad, rapidez y eficiencia del servidor.</p>', '<p>Comprender y dominar la optimizaci&oacute;n del rendimiento y monitorizaci&oacute;n y optimizaci&oacute;n es fundamental para:</p>\r\n<ul>\r\n<li>Conocer los conceptos relacionados con la indexaci&oacute;n.</li>\r\n<li>Conocer los tipos de tablas en MySQL.</li>\r\n<li>Aprender a gestionar &iacute;ndices.</li>\r\n<li>Optimizar consultas.</li>\r\n<li>Saber parametrizar y optimizar el funcionamiento del servidor para adaptarlo a cada contexto.</li>\r\n<li>Aprender a monitorizar el funcionamiento del servidor con distintas herramientas.</li>\r\n</ul>', '', '<ul>\r\n<li>Herramientas de monitorizaci&oacute;n disponibles en el sistema gestor.</li>\r\n<li>Trazas, log y alertas.</li>\r\n<li>Elementos y par&aacute;metros susceptibles de ser monitorizados.</li>\r\n<li>Indices. Ventajas e inconvenientes.</li>\r\n<li>Optimizaci&oacute;n: almacenamiento en memoria, espacio en disco, estructura de la base de datos, &iacute;ndices, etc.</li>\r\n<li>Transferencia y comunicaciones.</li>\r\n<li>Ejecuci&oacute;n de consultas optimizadas.</li>\r\n<li>Herramientas y &oacute;rdenes para la gesti&oacute;n de &iacute;ndices.</li>\r\n<li>Herramientas para la creaci&oacute;n de alertas de rendimiento.</li>\r\n<li>Adaptaciones en el sistema inform&aacute;tico para optimizar el rendimiento del SGBD.</li>\r\n<li>Nuevas tendencias en herramientas de mapeo para SGBD orientados a objetos.</li>\r\n</ul>', '', '', '<p>El 60% de la nota final del m&oacute;dulo la determinar&aacute; la nota obtenida en la 1&ordf; evaluaci&oacute;n. El 40% de la nota final del m&oacute;dulo la determinar&aacute; la nota obtenida en la 2&ordf; evaluaci&oacute;n.<br /><br />En cada evaluaci&oacute;n se realizar&aacute;n:<br />- Pr&aacute;cticas y actividades evaluables, que ponderaran un 30% sobre la nota de la evaluaci&oacute;n.<br />- Examen te&oacute;rico-pr&aacute;ctico, que ponderaran un 70% sobre la nota de la evaluaci&oacute;n.<br /><br />En la modalidad semipresencial, ninguna de las actividades y ejercicios propuestos ser&aacute;n considerados evaluables y, por lo tanto, no se solicitar&aacute; su entrega para su evaluaci&oacute;n. Los criterios de evaluaci&oacute;n y calificaci&oacute;n se ajustar&aacute;n exclusivamente a la realizaci&oacute;n del examen, que ser&aacute; acorde a la cantidad de horas correspondientes a cada evaluaci&oacute;n.<br /><br />Para aprobar el m&oacute;dulo, considerando todas las notas sobre un m&aacute;ximo de 10 puntos, ser&aacute; necesario cumplir las siguientes condiciones:<br />5 o m&aacute;s puntos en la nota final para aprobar el m&oacute;dulo.<br />5 o m&aacute;s puntos en cada evaluaci&oacute;n.<br />4 o m&aacute;s puntos en los ex&aacute;menes te&oacute;rico-pr&aacute;cticos de cada evaluaci&oacute;n.<br />4 o m&aacute;s puntos en la nota ponderada de las pr&aacute;cticas y actividades evaluables de cada evaluaci&oacute;n, si las hubiera.<br />4 o m&aacute;s puntos en cada pr&aacute;ctica y actividad evaluable individual, si las hubiera.</p>', '', '', 1, 1, 1, 1),
(32, 15, 5, 'Aplicación de criterios de disponibilidad a bases de datos distribuidas y replicadas', 14, 2, 20, '<p>En esta unidad se abordan las bases de datos distribuidas y alta disponibilidad, explicando c&oacute;mo replicar datos entre servidores para garantizar continuidad del servicio y tolerancia a fallos. Describe los tipos de replicaci&oacute;n (maestro-esclavo y circular), la sincronizaci&oacute;n de datos, el balanceo de carga y el uso de cl&uacute;steres. Adem&aacute;s, aborda estrategias para minimizar interrupciones y asegurar la integridad y disponibilidad de la informaci&oacute;n.</p>', '<p>La aplicaci&oacute;n de criterios de disponibilidad a bases de datos distribuidas y replicadas permite:</p>\r\n<ul>\r\n<li>Conocer los conceptos de los sistemas distribuidos.</li>\r\n<li>Entender la replicaci&oacute;n, alta disponibilidad y balanceo de carga.</li>\r\n<li>Implementar un sistema de replicaci&oacute;n en un SGBD.</li>\r\n<li>Dise&ntilde;ar e implementar un cluster usando servidores un SGBD.</li>\r\n</ul>', '', '<ul>\r\n<li>Bases de datos distribuidas; reglas de Date.</li>\r\n<li>Tipos de SGBD distribuidos.</li>\r\n<li>Tipos de SGBD: homog&eacute;neos y heterog&eacute;neos.</li>\r\n<li>Distribuci&oacute;n de los datos: centralizados y no centralizados.</li>\r\n<li>Autonom&iacute;a de los nodos: compuestos, federados y multibase.</li>\r\n<li>Componentes de un SGBD distribuido.</li>\r\n<li>T&eacute;cnicas de fragmentaci&oacute;n.</li>\r\n<li>T&eacute;cnicas de asignaci&oacute;n.</li>\r\n<li>Consulta distribuida.</li>\r\n<li>Transacciones distribuidas.</li>\r\n<li>Optimizaci&oacute;n de consultas sobre bases de datos distribuidas.</li>\r\n<li>Replicaci&oacute;n.</li>\r\n<li>Configuraci&oacute;n del nodo maestro y los nodos esclavos.</li>\r\n</ul>', '', '', '<p>El 60% de la nota final del m&oacute;dulo la determinar&aacute; la nota obtenida en la 1&ordf; evaluaci&oacute;n. El 40% de la nota final del m&oacute;dulo la determinar&aacute; la nota obtenida en la 2&ordf; evaluaci&oacute;n.<br /><br />En cada evaluaci&oacute;n se realizar&aacute;n:<br />- Pr&aacute;cticas y actividades evaluables, que ponderaran un 30% sobre la nota de la evaluaci&oacute;n.<br />- Examen te&oacute;rico-pr&aacute;ctico, que ponderaran un 70% sobre la nota de la evaluaci&oacute;n.<br /><br />En la modalidad semipresencial, ninguna de las actividades y ejercicios propuestos ser&aacute;n considerados evaluables y, por lo tanto, no se solicitar&aacute; su entrega para su evaluaci&oacute;n. Los criterios de evaluaci&oacute;n y calificaci&oacute;n se ajustar&aacute;n exclusivamente a la realizaci&oacute;n del examen, que ser&aacute; acorde a la cantidad de horas correspondientes a cada evaluaci&oacute;n.<br /><br />Para aprobar el m&oacute;dulo, considerando todas las notas sobre un m&aacute;ximo de 10 puntos, ser&aacute; necesario cumplir las siguientes condiciones:<br />5 o m&aacute;s puntos en la nota final para aprobar el m&oacute;dulo.<br />5 o m&aacute;s puntos en cada evaluaci&oacute;n.<br />4 o m&aacute;s puntos en los ex&aacute;menes te&oacute;rico-pr&aacute;cticos de cada evaluaci&oacute;n.<br />4 o m&aacute;s puntos en la nota ponderada de las pr&aacute;cticas y actividades evaluables de cada evaluaci&oacute;n, si las hubiera.<br />4 o m&aacute;s puntos en cada pr&aacute;ctica y actividad evaluable individual, si las hubiera.</p>', '', '', 1, 1, 1, 1),
(33, 51, 5, 'T4. Navegación en Jetpack Compose', 15, 1, 4, '<p class=\"p1\">En este tema se estudia el <span class=\"s1\"><strong>sistema de navegaci&oacute;n declarativa en Jetpack Compose</strong></span>, que sustituye al modelo tradicional basado en <em>Fragments</em> y <em>NavHostFragment</em>.</p>\r\n<p class=\"p1\">Compose introduce un nuevo enfoque centrado en la <span class=\"s1\"><strong>definici&oacute;n de rutas y destinos composables</strong></span>, gestionados a trav&eacute;s de un <span class=\"s1\"><strong>NavController</strong></span> que controla la pila de pantallas (<em>back stack</em>) de manera autom&aacute;tica y reactiva.</p>\r\n<p class=\"p1\">El alumnado aprender&aacute; a:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">Implementar navegaci&oacute;n </span><strong>entre pantallas composables</strong><span class=\"s1\">.</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Enviar y recibir <span class=\"s1\"><strong>argumentos</strong></span> a trav&eacute;s de rutas parametrizadas.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gestionar el <span class=\"s1\"><strong>back stack</strong></span> y la navegaci&oacute;n condicional.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Crear <span class=\"s1\"><strong>gr&aacute;ficos de navegaci&oacute;n anidados</strong></span> y estructuras de interfaz completas con <span class=\"s2\">Scaffold</span>, <span class=\"s2\">TopAppBar</span>, <span class=\"s2\">BottomNavigation</span> y <span class=\"s2\">DrawerNavigation</span>.</p>\r\n</li>\r\n</ul>', '<p class=\"p1\">La navegaci&oacute;n es un pilar fundamental en el desarrollo de aplicaciones Android, ya que define el <span class=\"s1\"><strong>flujo de interacci&oacute;n del usuario</strong></span> y la <span class=\"s1\"><strong>organizaci&oacute;n modular</strong></span> de la interfaz.</p>\r\n<p class=\"p1\">En el paradigma Compose, la navegaci&oacute;n se integra de forma <span class=\"s1\"><strong>declarativa</strong></span>, coherente con los principios de <span class=\"s1\"><strong>MVVM</strong></span> y <span class=\"s1\"><strong>Clean Architecture</strong></span>, simplificando la gesti&oacute;n del ciclo de vida y reduciendo la complejidad respecto al modelo tradicional.</p>\r\n<p class=\"p1\">Dominar este sistema es imprescindible para:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Crear <span class=\"s1\"><strong>aplicaciones escalables</strong></span> y f&aacute;ciles de mantener.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">Separar responsabilidades entre </span><strong>pantallas (UI)</strong><span class=\"s1\"> y </span><strong>l&oacute;gica de presentaci&oacute;n (ViewModel)</strong><span class=\"s1\">.</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Aplicar una <span class=\"s1\"><strong>arquitectura reactiva</strong></span> basada en estado.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">Integrar la navegaci&oacute;n con </span><strong>componentes estructurales de interfaz</strong><span class=\"s1\"> como </span><span class=\"s2\">Scaffold</span><span class=\"s1\">.</span></p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">Este tema sirve adem&aacute;s de base para posteriores unidades dedicadas a <span class=\"s1\"><strong>persistencia</strong></span>, <span class=\"s1\"><strong>APIs</strong></span> y <span class=\"s1\"><strong>multimedia</strong></span>, donde la navegaci&oacute;n conecta m&oacute;dulos funcionales dentro de una aplicaci&oacute;n completa.</p>', '<p class=\"p1\">Este se enmarca dentro del bloque de <span class=\"s1\"><strong>arquitectura y flujo de interacci&oacute;n</strong></span> en aplicaciones Android modernas.</p>', '<ul>\r\n<li>4.1. Introducci&oacute;n a Navigation Compose\r\n<ul>\r\n<li>4.1.1. Beneficios frente a m&uacute;ltiples actividades</li>\r\n</ul>\r\n</li>\r\n<li>4.2. Definici&oacute;n de destinos (Composable)\r\n<ul>\r\n<li>4.2.1. Rutas con par&aacute;metros</li>\r\n<li>4.2.2. Paso de datos entre pantallas</li>\r\n</ul>\r\n</li>\r\n<li>4.3. Navegaci&oacute;n controlada con NavController\r\n<ul>\r\n<li>4.3.1. navigate(), popBackStack(), navigateUp()</li>\r\n<li>4.3.2. Manejo del stack y el bot&oacute;n &ldquo;atr&aacute;s&rdquo;</li>\r\n</ul>\r\n</li>\r\n<li>4.4. Navegaci&oacute;n con ViewModel y estado\r\n<ul>\r\n<li>4.4.1. Compartir estado entre pantallas</li>\r\n<li>4.4.2. Scope adecuado del ViewModel por destino</li>\r\n<li>Resumen de scopes de ViewModel</li>\r\n</ul>\r\n</li>\r\n</ul>', '', '', '', '', '', 0, 1, 1, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(34, 51, 6, 'T5. Arquitectura MVVM y Clean Architecture', 12, 1, 4, '<p class=\"p1\">Este tema aborda el estudio y aplicaci&oacute;n de la <span class=\"s1\"><strong>arquitectura MVVM (Model&ndash;View&ndash;ViewModel)</strong></span> dentro del ecosistema Android moderno, integr&aacute;ndola con los principios de <span class=\"s1\"><strong>Clean Architecture</strong></span>.</p>\r\n<p class=\"p1\">Se analizan los conceptos de <span class=\"s1\"><strong>separaci&oacute;n de responsabilidades</strong></span>, <span class=\"s1\"><strong>flujo unidireccional de datos (UDF)</strong></span> y <span class=\"s1\"><strong>gesti&oacute;n del estado</strong></span>, empleando componentes de <span class=\"s1\"><strong>Android Jetpack</strong></span> (ViewModel, LiveData, StateFlow) y su integraci&oacute;n directa con <span class=\"s1\"><strong>Jetpack Compose</strong></span>.</p>\r\n<p class=\"p1\">El alumnado aprender&aacute; a estructurar proyectos escalables y mantenibles, dividiendo el c&oacute;digo en capas &mdash;<span class=\"s1\"><strong>presentaci&oacute;n, dominio y datos</strong></span>&mdash;, de modo que cada parte de la aplicaci&oacute;n cumpla una funci&oacute;n claramente definida.</p>', '<p class=\"p1\">El uso de una arquitectura s&oacute;lida es esencial para el desarrollo profesional de aplicaciones Android.</p>\r\n<p class=\"p1\">El patr&oacute;n <span class=\"s1\"><strong>MVVM</strong></span>, combinado con los principios de <span class=\"s1\"><strong>Clean Architecture</strong></span>, permite crear proyectos:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\"><strong>Mantenibles</strong></span>, gracias a la separaci&oacute;n l&oacute;gica de responsabilidades.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\"><strong>Testeables</strong></span>, al desacoplar las capas y permitir el uso de dependencias simuladas.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\"><strong>Escalables</strong></span>, ya que facilitan la incorporaci&oacute;n de nuevas funcionalidades.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\"><strong>Reactivas</strong></span>, integrando flujos de datos que actualizan autom&aacute;ticamente la interfaz en Compose.</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">En el paradigma declarativo de Jetpack Compose, la arquitectura MVVM resulta especialmente relevante, pues facilita que la <span class=\"s1\"><strong>UI se derive directamente del estado expuesto por el ViewModel</strong></span>, sin depender de la manipulaci&oacute;n imperativa de vistas.</p>', '<p class=\"p1\"><span class=\"s1\">Este tema se enmarca dentro del bloque dedicado a la </span><strong>arquitectura y gesti&oacute;n del ciclo de vida en aplicaciones Android modernas</strong><span class=\"s1\">, situ&aacute;ndose tras la unidad sobre </span><strong>navegaci&oacute;n en Compose (Tema 4)</strong><span class=\"s1\">.</span></p>\r\n<p class=\"p3\">Constituye un <span class=\"s2\"><strong>punto de inflexi&oacute;n pedag&oacute;gico</strong></span>, ya que introduce la estructura que guiar&aacute; el desarrollo de todos los proyectos posteriores: persistencia con Room (Tema 6), consumo de APIs (Tema 7) y multimedia (Tema 8).</p>', '<ul>\r\n<li>5.1. &iquest;Qu&eacute; es MVVM?</li>\r\n<li>5.2. Separaci&oacute;n de responsabilidades</li>\r\n<li>5.3. ViewModel, Flow y LiveData</li>\r\n<li>5.4. Introducci&oacute;n a Clean Architecture\r\n<ul>\r\n<li>5.4.1. Capas: Presentation, Domain, Data</li>\r\n</ul>\r\n</li>\r\n<li>5.5. Uso de corutinas</li>\r\n<li>5.6. Pruebas unitarias b&aacute;sicas</li>\r\n</ul>', '', '', '', '', '', 0, 1, 1, 1),
(35, 51, 7, 'T6. Persistencia con ROOM', 14, 1, 7, '<p class=\"p1\">En este tema se estudia el uso de <span class=\"s1\"><strong>ROOM</strong></span>, la librer&iacute;a oficial de Android Jetpack que facilita la <span class=\"s1\"><strong>persistencia de datos locales</strong></span> mediante una abstracci&oacute;n sobre <span class=\"s1\"><strong>SQLite</strong></span>.</p>\r\n<p class=\"p1\">ROOM proporciona un acceso a la base de datos <span class=\"s1\"><strong>seguro, tipado y compatible con corrutinas y Flow</strong></span>, simplificando las operaciones CRUD (Create, Read, Update, Delete) y garantizando la integridad de los datos.</p>\r\n<p class=\"p1\">El alumnado aprender&aacute; a:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Definir <span class=\"s1\"><strong>entidades y relaciones</strong></span> de base de datos.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Crear <span class=\"s1\"><strong>consultas SQL</strong></span> mediante <span class=\"s2\">@Dao</span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Implementar <span class=\"s1\"><strong>repositorios</strong></span> dentro de una arquitectura MVVM.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Integrar ROOM con <span class=\"s1\"><strong>ViewModel y Compose</strong></span> para mostrar datos persistidos en la interfaz.</p>\r\n</li>\r\n</ul>', '<p class=\"p1\">La persistencia de datos es un requisito fundamental en el desarrollo de aplicaciones m&oacute;viles, especialmente en contextos donde el dispositivo puede <span class=\"s1\"><strong>funcionar sin conexi&oacute;n</strong></span> o se requiere <span class=\"s1\"><strong>almacenar informaci&oacute;n del usuario de forma local</strong></span>.</p>\r\n<p class=\"p1\">ROOM se ha convertido en la herramienta est&aacute;ndar para la gesti&oacute;n de bases de datos SQLite en Android, gracias a que:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Ofrece una capa de abstracci&oacute;n <span class=\"s1\"><strong>segura y declarativa</strong></span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Reduce errores mediante la <span class=\"s1\"><strong>validaci&oacute;n en tiempo de compilaci&oacute;n</strong></span> de las consultas SQL.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Se integra nativamente con <span class=\"s1\"><strong>corutinas, Flow y LiveData</strong></span>, facilitando la programaci&oacute;n reactiva.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Permite mantener una estructura limpia dentro de arquitecturas <span class=\"s1\"><strong>MVVM + Clean Architecture</strong></span>.</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">Este tema dota al alumnado de los conocimientos necesarios para dise&ntilde;ar sistemas de almacenamiento eficientes y seguros dentro de sus proyectos Android.</p>', '<p class=\"p1\"><span class=\"s1\">El </span><strong>Tema 6</strong><span class=\"s1\"> se enmarca en el bloque de </span><strong>persistencia y almacenamiento de datos</strong><span class=\"s1\">, situ&aacute;ndose despu&eacute;s del tema sobre </span><strong>arquitectura MVVM y Clean Architecture</strong><span class=\"s1\">.</span></p>\r\n<p class=\"p2\">La comprensi&oacute;n de ROOM es esencial para conectar la <span class=\"s2\"><strong>capa de datos</strong></span> con la <span class=\"s2\"><strong>capa de dominio</strong></span>, estableciendo una base s&oacute;lida sobre la que se construyen las unidades siguientes dedicadas a <span class=\"s2\"><strong>consumo de APIs con Retrofit</strong></span> (Tema 7) y <span class=\"s2\"><strong>almacenamiento multimedia</strong></span> (Tema 9).</p>', '<ul>\r\n<li>6.1. Introducci&oacute;n a ROOM</li>\r\n<li>6.2. Configuraci&oacute;n de ROOM en el proyecto</li>\r\n<li>6.3. Modelo</li>\r\n<li>6.4. Creaci&oacute;n del DAO</li>\r\n<li>6.5. Definici&oacute;n de la base de datos</li>\r\n<li>6.6. Uso de ROOM con ViewModel</li>\r\n<li>6.6.1. Consumir los datos desde la UI</li>\r\n</ul>', '', '', '', '', '', 0, 1, 1, 1),
(36, 51, 8, 'T7. Comunicación con APIs REST con Retrofit2', 15, 2, 11, '<p class=\"p1\">En este tema se estudia la <span class=\"s1\"><strong>comunicaci&oacute;n entre aplicaciones Android y servicios web</strong></span> mediante <span class=\"s1\"><strong>Retrofit2</strong></span>, la librer&iacute;a de referencia para el consumo de APIs REST en Android.</p>\r\n<p class=\"p1\">Retrofit permite realizar peticiones HTTP de forma <span class=\"s1\"><strong>tipada, segura y eficiente</strong></span>, integr&aacute;ndose f&aacute;cilmente con <span class=\"s1\"><strong>corutinas</strong></span>, <span class=\"s1\"><strong>Flow</strong></span>, <span class=\"s1\"><strong>Room</strong></span> y <span class=\"s1\"><strong>ViewModel</strong></span>, lo que la convierte en la herramienta ideal para trabajar dentro de arquitecturas <span class=\"s1\"><strong>MVVM + Clean Architecture</strong></span>.</p>\r\n<p class=\"p1\">El alumnado aprender&aacute; a:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Conectar una aplicaci&oacute;n Android con un servicio web RESTful.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Enviar y recibir datos en formato <span class=\"s1\"><strong>JSON</strong></span> mediante <span class=\"s1\"><strong>Retrofit + Moshi/Gson</strong></span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">Gestionar </span><strong>operaciones as&iacute;ncronas</strong><span class=\"s1\"> con </span><strong>corrutinas</strong><span class=\"s1\"> y </span><strong>ViewModel</strong><span class=\"s1\">.</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Implementar la <span class=\"s1\"><strong>sincronizaci&oacute;n de datos</strong></span> entre red y base de datos local.</p>\r\n</li>\r\n</ul>', '<p class=\"p1\">Las aplicaciones modernas dependen en gran medida de la comunicaci&oacute;n con servidores externos para acceder a informaci&oacute;n en tiempo real.</p>\r\n<p class=\"p1\">Retrofit2, parte del ecosistema <span class=\"s1\"><strong>Square</strong></span>, es la librer&iacute;a est&aacute;ndar en Android para establecer esta comunicaci&oacute;n, ya que:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Simplifica la gesti&oacute;n de peticiones HTTP mediante interfaces declarativas.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Convierte autom&aacute;ticamente las respuestas JSON en objetos Kotlin (data classes).</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Ofrece compatibilidad con <span class=\"s1\"><strong>corutinas</strong></span>, <span class=\"s1\"><strong>RxJava</strong></span>, <span class=\"s1\"><strong>Flow</strong></span> y herramientas de serializaci&oacute;n como <span class=\"s1\"><strong>Moshi</strong></span> o <span class=\"s1\"><strong>Gson</strong></span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Se integra con ROOM para lograr un modelo de <span class=\"s1\"><strong>offline-first</strong></span>, combinando datos locales y remotos.</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">El dominio de Retrofit2 capacita al alumnado para desarrollar <span class=\"s1\"><strong>aplicaciones conectadas</strong></span>, capaces de consumir servicios REST, enviar informaci&oacute;n al servidor y mantener sincron&iacute;a con el almacenamiento local.</p>', '<p class=\"p1\"><span class=\"s1\">El </span><strong>Tema 7</strong><span class=\"s1\"> se sit&uacute;a dentro del bloque de </span><strong>comunicaci&oacute;n de aplicaciones m&oacute;viles con servicios externos</strong><span class=\"s1\">, posterior a la unidad sobre </span><strong>persistencia con ROOM</strong><span class=\"s1\">.</span></p>\r\n<p class=\"p2\">Junto con los temas anteriores, permite aplicar de forma pr&aacute;ctica la <span class=\"s2\"><strong>arquitectura MVVM + Clean Architecture</strong></span>, estructurando proyectos Android que integran <span class=\"s2\"><strong>fuentes de datos locales y remotas</strong></span>.</p>', '<ul>\r\n<li>7.1. Introducci&oacute;n a APIs REST</li>\r\n<li>7.2. Retrofit2\r\n<ul>\r\n<li>7.2.1. Dependencias necesarias</li>\r\n</ul>\r\n</li>\r\n<li>7.3. Modelo</li>\r\n<li>7.4. Configuraci&oacute;n de Retrofit2\r\n<ul>\r\n<li>7.4.1. Manejo de errores y excepciones</li>\r\n</ul>\r\n</li>\r\n<li>7.5. Creaci&oacute;n del flujo e integraci&oacute;n con ViewModel\r\n<ul>\r\n<li>7.5.1. PullToRefreshBox en Jetpack Compose</li>\r\n</ul>\r\n</li>\r\n<li>7.6. Integraci&oacute;n con ROOM\r\n<ul>\r\n<li>7.6.1. Modelo</li>\r\n<li>7.6.2. Configuraci&oacute;n de la BD y DAO</li>\r\n<li>7.6.3. Datasource local</li>\r\n<li>7.6.4. Repository</li>\r\n<li>7.6.5. ViewModel</li>\r\n</ul>\r\n</li>\r\n</ul>', '', '', '', '', '', 0, 1, 1, 1),
(37, 51, 9, 'T8. Multimedia en Android', 12, 2, 16, '<p class=\"p1\">Este tema aborda el <span class=\"s1\"><strong>uso de recursos multimedia en Android</strong></span>, tanto desde el punto de vista de la <span class=\"s1\"><strong>captura y reproducci&oacute;n</strong></span> de contenidos como de su <span class=\"s1\"><strong>gesti&oacute;n y almacenamiento</strong></span> dentro del sistema.</p>\r\n<p class=\"p1\">El alumnado aprender&aacute; a trabajar con los principales componentes del framework multimedia de Android: <span class=\"s1\"><strong>c&aacute;mara, micr&oacute;fono, galer&iacute;a, sensores</strong></span> y <span class=\"s1\"><strong>reproductores de audio y v&iacute;deo</strong></span>, aplicando siempre los principios de seguridad y control de permisos.</p>\r\n<p class=\"p1\">Adem&aacute;s, se integrar&aacute;n las operaciones multimedia dentro de una arquitectura <span class=\"s1\"><strong>MVVM + Compose</strong></span>, utilizando el enfoque declarativo para representar en la interfaz los estados y resultados de cada acci&oacute;n (captura, grabaci&oacute;n, reproducci&oacute;n, etc.).</p>', '<p class=\"p1\">El manejo de contenidos multimedia es esencial en el desarrollo de aplicaciones m&oacute;viles modernas. Fotograf&iacute;as, grabaciones, v&iacute;deos o detecci&oacute;n de movimiento forman parte de funcionalidades comunes en apps de mensajer&iacute;a, redes sociales, fitness o entretenimiento.</p>\r\n<p class=\"p1\">El dominio de las APIs multimedia permite al alumnado:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\">Capturar y procesar im&aacute;genes, audio y v&iacute;deo desde dispositivos reales.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Integrar la c&aacute;mara y el micr&oacute;fono con interfaces declarativas de <span class=\"s1\"><strong>Jetpack Compose</strong></span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Utilizar <span class=\"s1\"><strong>MediaStore</strong></span> y <span class=\"s1\"><strong>ContentResolver</strong></span> para el almacenamiento de recursos.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Aplicar las pr&aacute;cticas m&aacute;s recientes de <span class=\"s1\"><strong>seguridad y permisos din&aacute;micos</strong></span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Sincronizar contenidos multimedia con el modelo de datos (ViewModel + Room).</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">Este tema constituye el bloque de aplicaci&oacute;n pr&aacute;ctica m&aacute;s avanzada antes del estudio de <span class=\"s2\"><strong>sensores y juegos (Tema 9 y 10)</strong></span>.</p>', '<p class=\"p1\">El <span class=\"s1\"><strong>Tema 8</strong></span> pertenece al bloque de <span class=\"s1\"><strong>interacci&oacute;n avanzada con hardware y recursos del dispositivo</strong></span>, continuando la l&iacute;nea de los temas sobre comunicaci&oacute;n y persistencia.</p>\r\n<p class=\"p1\">Conecta directamente con los temas 3 (Intents y permisos) y 6 (Persistencia con Room), ya que la mayor&iacute;a de las operaciones multimedia requieren permisos en tiempo de ejecuci&oacute;n y, en muchos casos, almacenamiento de los resultados en una base de datos o galer&iacute;a.</p>', '<ul>\r\n<li>8.1. Reproducci&oacute;n de audio y video\r\n<ul>\r\n<li>8.1.1. MediaPlayer (API Nativa)</li>\r\n<li>8.1.2. ExoPlayer</li>\r\n</ul>\r\n</li>\r\n<li>8.2. Captura de im&aacute;genes</li>\r\n<li>8.3. Captura de im&aacute;genes y v&iacute;deo con CameraX\r\n<ul>\r\n<li>8.3.1. Dependencias y permisos necesarias para CameraX</li>\r\n<li>8.3.2. Captura de im&aacute;genes b&aacute;sica con CameraX en Compose con vista previa</li>\r\n<li>8.3.3. Captura de v&iacute;deo con CameraX en Compose con vista previa</li>\r\n</ul>\r\n</li>\r\n<li>8.4. Selecci&oacute;n de im&aacute;genes desde la galer&iacute;a con el Photo Picker</li>\r\n<li>8.5. Grabaci&oacute;n de audio con MediaRecorder\r\n<ul>\r\n<li>8.5.1. Permisos necesarios</li>\r\n<li>8.5.2 MediaRecorder</li>\r\n<li>8.5.3 Ejemplo completo de Grabadora con cron&oacute;metro</li>\r\n</ul>\r\n</li>\r\n<li>8.6. Sensores b&aacute;sicos</li>\r\n</ul>', '', '', '', '', '', 0, 1, 1, 1),
(38, 51, 10, 'T9. Almacenamiento en Android', 11, 2, 4, '<p class=\"p1\">En este tema se estudian los <span class=\"s1\"><strong>m&eacute;todos de almacenamiento disponibles en Android</strong></span>, tanto para datos <span class=\"s1\"><strong>internos</strong></span> como <span class=\"s1\"><strong>externos</strong></span>, analizando su alcance, seguridad, limitaciones y casos de uso.</p>\r\n<p class=\"p1\">Se aborda el manejo de <span class=\"s1\"><strong>SharedPreferences</strong></span>, <span class=\"s1\"><strong>archivos internos y externos</strong></span>, <span class=\"s1\"><strong>MediaStore</strong></span>, y los mecanismos modernos de almacenamiento seguro mediante <span class=\"s1\"><strong>EncryptedSharedPreferences</strong></span> y <span class=\"s1\"><strong>DataStore</strong></span>.</p>\r\n<p class=\"p1\">El alumnado aprender&aacute; a seleccionar el m&eacute;todo de persistencia m&aacute;s adecuado seg&uacute;n el tipo y la sensibilidad de los datos, aplicando principios de <span class=\"s1\"><strong>seguridad, privacidad y eficiencia</strong></span> en el contexto de las aplicaciones m&oacute;viles modernas.</p>', '<p class=\"p1\">El almacenamiento es un componente esencial en cualquier aplicaci&oacute;n Android, ya que permite conservar informaci&oacute;n entre sesiones, guardar configuraciones, ficheros multimedia o documentos generados por el usuario.</p>\r\n<p class=\"p1\">Comprender las diferencias entre los distintos m&eacute;todos de almacenamiento es clave para:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">Gestionar correctamente los </span><strong>recursos y permisos del sistema</strong><span class=\"s1\">.</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">Aplicar las </span><strong>mejores pr&aacute;cticas de seguridad y privacidad</strong><span class=\"s1\">.</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Integrar los mecanismos de persistencia en una arquitectura <span class=\"s1\"><strong>MVVM + Clean Architecture</strong></span>.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Cumplir con las pol&iacute;ticas de <span class=\"s1\"><strong>Scoped Storage</strong></span> introducidas en Android 10 y reforzadas en versiones posteriores.</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">El dominio de estos conceptos permite al alumnado desarrollar aplicaciones que almacenan datos de forma <span class=\"s2\"><strong>eficiente, segura y compatible</strong></span> con futuras versiones del sistema operativo.</p>', '<p class=\"p1\">El <span class=\"s1\"><strong>Tema 9</strong></span> se sit&uacute;a dentro del bloque de <span class=\"s1\"><strong>persistencia y gesti&oacute;n de datos</strong></span> de Android, complementando lo aprendido en el <span class=\"s1\"><strong>Tema 6 (Persistencia con ROOM)</strong></span>.</p>\r\n<p class=\"p1\">Mientras ROOM se centra en la persistencia estructurada en bases de datos, este tema se enfoca en el <span class=\"s1\"><strong>almacenamiento de archivos, configuraciones y datos no relacionales</strong></span>, permitiendo una visi&oacute;n global de las opciones de persistencia en Android.</p>', '<ul>\r\n<li>9.1. Introducci&oacute;n al almacenamiento en Android</li>\r\n<li>9.2. Archivos internos</li>\r\n<li>9.3. SharedPreferences</li>\r\n<li>9.4. DataStore</li>\r\n<li>9.5. Storage Access Framework (SAF)</li>\r\n<li>9.6. Almacenamiento seguro de preferencias con Android Keystore + AES-GCM</li>\r\n<li>9.7. Buenas pr&aacute;cticas y eficiencia</li>\r\n</ul>', '', '', '', '', '', 0, 1, 1, 1),
(39, 51, 11, 'T10. Introducción a los motores de juego en Android', 13, 2, 12, '<p class=\"p1\">Este tema introduce los <span class=\"s1\"><strong>fundamentos de la programaci&oacute;n de videojuegos en Android</strong></span>, centr&aacute;ndose en la estructura b&aacute;sica de un <span class=\"s1\"><strong>motor de juegos</strong></span> y en el uso de librer&iacute;as y frameworks especializados como <span class=\"s1\"><strong>AndEngine</strong></span> y <span class=\"s1\"><strong>LibGDX</strong></span>.</p>\r\n<p class=\"p1\">Se analizan los elementos esenciales que intervienen en el ciclo de un videojuego &mdash;<span class=\"s1\"><strong>renderizado, entrada de usuario, animaci&oacute;n, f&iacute;sica y gesti&oacute;n de estados</strong></span>&mdash;, mostrando c&oacute;mo estos conceptos se aplican en el contexto del desarrollo m&oacute;vil con <span class=\"s1\"><strong>Kotlin</strong></span> y <span class=\"s1\"><strong>Jetpack Compose</strong></span>.</p>\r\n<p class=\"p1\">El alumnado aprender&aacute; a crear un proyecto de videojuego 2D desde cero, entender el funcionamiento de un <span class=\"s1\"><strong>Game Loop</strong></span> y conectar la l&oacute;gica del motor con la interfaz declarativa de Compose (para men&uacute;s, configuraciones o marcadores).</p>', '<p class=\"p1\">Los videojuegos representan uno de los sectores m&aacute;s innovadores dentro del desarrollo multimedia. Android ofrece un entorno ideal para el aprendizaje de t&eacute;cnicas de programaci&oacute;n gr&aacute;fica, f&iacute;sica b&aacute;sica, gesti&oacute;n de eventos y animaci&oacute;n.</p>\r\n<p class=\"p1\">El dominio de un motor de juegos permite al alumnado:</p>\r\n<ul>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">Comprender la </span><strong>arquitectura interna de los motores gr&aacute;ficos y de simulaci&oacute;n</strong><span class=\"s1\">.</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><span class=\"s1\">Aplicar conceptos de </span><strong>ciclo de vida, optimizaci&oacute;n y concurrencia</strong><span class=\"s1\">.</span></p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Implementar el <span class=\"s1\"><strong>Game Loop</strong></span> como estructura de control continua.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Integrar <span class=\"s1\"><strong>recursos multimedia</strong></span> (im&aacute;genes, sonido, sprites, colisiones) dentro de una arquitectura limpia.</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Utilizar <span class=\"s1\"><strong>Compose</strong></span> como interfaz auxiliar para pantallas de men&uacute;, configuraci&oacute;n o puntuaci&oacute;n.</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">De este modo, el tema ampl&iacute;a las competencias adquiridas en las unidades anteriores, integrando todos los conocimientos de la asignatura en un <span class=\"s2\"><strong>proyecto pr&aacute;ctico completo</strong></span>.</p>', '<p class=\"p1\"><span class=\"s1\">El </span><strong>Tema 10</strong><span class=\"s1\"> cierra el m&oacute;dulo profesional </span><strong>Programaci&oacute;n Multimedia y Dispositivos M&oacute;viles (0489)</strong><span class=\"s1\">, y forma parte del bloque dedicado a la </span><strong>interacci&oacute;n multimedia y dispositivos</strong><span class=\"s1\">.</span></p>\r\n<p class=\"p2\">Su finalidad es aplicar los conocimientos previos (arquitectura, persistencia, multimedia, sensores, etc.) en un entorno interactivo que combine <span class=\"s2\"><strong>l&oacute;gica, dise&ntilde;o visual y rendimiento en tiempo real</strong></span>.</p>', '', '', '', '', '', '', 0, 1, 1, 1),
(40, 7, 2, 'Sistemas informáticos. Introducción. Evolución. Estructura funcional.', 6, 1, 10, '<p>Esta unidad el alumno conocer&aacute; la evoluci&oacute;n de los sistemas inform&aacute;ticos as&iacute; como las diferentes generaciones de ordenadores que se distingue. Tambi&eacute;n aprender&aacute; los diferentes bloques funcionales en los que se divide un sistema inform&aacute;tico y c&oacute;mo interaccionan entre ellos para ejecutar instrucciones.&nbsp;</p>', '<p>Esta unidad sirve de base para que los alumnos aprendan los diferentes bloques funcionales en los que se divide un sistema y c&oacute;mo funcionan internamente, de esta manera cuando estudien los componentes hardware ver&aacute;n la correspondencia entre ellos y los bloques funcionales y ya tendr&aacute;n un conocimiento b&aacute;sico de c&oacute;mo funcionan internamente.</p>', '', '<ol>\r\n<li>Introducci&oacute;n a los sistemas inform&aacute;ticos.</li>\r\n<li>Evoluci&oacute;n de sistemas inform&aacute;ticos.</li>\r\n<li>Arquitectura de Von Neumann. Estructura funcional de un sistema inform&aacute;tico.\r\n<ol>\r\n<li>Unidad Central de Procesamiento&nbsp;</li>\r\n<li>Buses</li>\r\n<li>Unidad de memoria.</li>\r\n<li>El ciclo b&uacute;squeda, decodificaci&oacute;n y ejecuci&oacute;n de una instrucci&oacute;n.</li>\r\n<li>Unidad de entrada y salida.</li>\r\n</ol>\r\n</li>\r\n<li>Caracter&iacute;sticas de la CPU.</li>\r\n<li>Jerarqu&iacute;a de memoria.</li>\r\n</ol>', '<ul>\r\n<li>Primero se introducir&aacute; el concepto de sistema inform&aacute;tico y los diferentes elementos que lo componen.</li>\r\n<li>Se expondr&aacute; la evoluci&oacute;n de los sistemas inform&aacute;ticos desde su inicio y se distinguir&aacute;n las diferentes generaciones de sistemas inform&aacute;ticos.</li>\r\n<li>Se explicar&aacute; la arquitectura de Von Neumann como estructura funcional de un sistema inform&aacute;tico y se ver&aacute;n en detalle sus elementos principales.</li>\r\n<li>Se expondr&aacute;n las caracter&iacute;sticas de la CPU a nivel funcional que afectan al rendimiento de un sistema.</li>\r\n<li>Se distinguir&aacute;n los diferentes tipos de memoria que podemos encontrar a nivel funcional y su jerarqu&iacute;a.</li>\r\n</ul>', '', '<p style=\"text-align: justify;\"><strong>Modalidad presencial</strong></p>\r\n<p style=\"text-align: justify;\">La asistencia a clase es obligatoria por ley, por tanto, aquellos alumnos que no asistan como m&iacute;nimo al 85% de las horas, no tendr&aacute;n derecho a la evaluaci&oacute;n continua y deber&aacute;n realizar un examen final de todo el m&oacute;dulo.</p>\r\n<p style=\"text-align: justify;\">&nbsp;Al final de cada unidad tem&aacute;tica o de varias relacionadas entre s&iacute; (mismo bloque), podr&aacute; realizarse una prueba te&oacute;rica o te&oacute;rico-pr&aacute;ctica seg&uacute;n la naturaleza de la unidad que servir&aacute; para medir el grado de destreza obtenido en la materia por el alumno. Como m&iacute;nimo se realizar&aacute; una prueba por trimestre. Estas pruebas englobar&aacute;n el contenido que se haya impartido desde la &uacute;ltima prueba realizada. Los per&iacute;odos en los que se imparten las unidades est&aacute;n especificados en el apartado Secuenciaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">As&iacute; mismo se establecer&aacute;n fechas de entrega de las distintas actividades que se vayan planteando a lo largo de cada trimestre. Las actividades no entregadas se puntuar&aacute;n como 0. Las actividades entregadas fuera de plazo podr&aacute;n calificarse como 0 o bien su nota se ver&aacute; reducida en funci&oacute;n del tiempo que se tarde en entregarse una vez terminado el plazo.</p>\r\n<p style=\"text-align: justify;\">La nota de cada evaluaci&oacute;n se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Pruebas objetivas sobre los contenidos te&oacute;ricos y pr&aacute;cticos realizados en la evaluaci&oacute;n</span></span>:&nbsp;<strong>70%.</strong></p>\r\n</li>\r\n<li>\r\n<p>E<span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">jercicios pr&aacute;cticos, ejercicios te&oacute;ricos, trabajos, supuestos te&oacute;rico-pr&aacute;cticos</span></span>:&nbsp;<strong>30%</strong>.&nbsp;</p>\r\n</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n 4,5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Por otra parte, actitudes como utilizar el ordenador para jugar, instalar software no autorizado, cambiar la configuraci&oacute;n de los equipos, actitudes que impidan el funcionamiento de clase con interrupciones continuas, no traer material, ser&aacute; tenido en cuenta y penalizado, independientemente de las sanciones que pudiera dictar el consejo escolar.</p>\r\n<p style=\"text-align: justify;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Modalidad semipresencial</strong></p>\r\n<p style=\"text-align: justify;\">En la modalidad semipresencial, la nota se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Test o ex&aacute;menes te&oacute;rico pr&aacute;cticos sobre los contenidos:&nbsp;<strong>70%</strong></span></span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Ejercicios te&oacute;rico-practicos, trabajos y pr&aacute;cticas presenciales:<strong>&nbsp;30%</strong></span></span></p>\r\n</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Durante la evaluaci&oacute;n se propondr&aacute;n ejercicios de car&aacute;cter te&oacute;rico-pr&aacute;ctico semanales para que el alumno afiance los contenidos aprendidos en cada semana. Estas actividades son obligatorias y deber&aacute;n entregarse todas para poder realizar la media de los ejercicios. Las actividades no entregadas, entregadas fuera de plazo o copiadas, tendr&aacute;n una calificaci&oacute;n de 0.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Aunque en la modalidad semipresencial, de forma general,&nbsp; la asistencia a las tutor&iacute;as no es obligatoria, la asignatura de Fundamentos de Hardware, seg&uacute;n lo dispuesto en la Resoluci&oacute;n de 22 de mayo de 2018 de la Direcci&oacute;n General de Formaci&oacute;n Profesional deber&aacute; realizar una serie de horas presenciales de forma obligatoria. Estas tutorias colectivas obligatorias tendr&aacute;n como objetivo realizar pr&aacute;cticas para el montaje y reparaci&oacute;n de equipos inform&aacute;ticos. La no asistencia a las sesiones de presencialidad obligatoria comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Al final de cada evaluaci&oacute;n se realizar&aacute; una prueba te&oacute;rico-pr&aacute;ctica que servir&aacute; para medir el grado de destreza obtenido en la materia por parte del alumno. La no asistencia a alguno de los ex&aacute;menes que se realizar&aacute;n de cada evaluaci&oacute;n comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n de 5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Para calcular la media del curso se realizar&aacute; una ponderaci&oacute;n en funci&oacute;n de los porcentajes asignados a cada unidad.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>', '', '', 1, 1, 1, 1),
(41, 7, 3, 'Estructura física de un sistema informático. Componentes internos I.', 15, 1, 16, '<p>En esta unidad el alumno conocer&aacute; en detalle tres de los elementos principales que conforman un sistema inform&aacute;tico: placa base, procesador y RAM. Para cada uno de ellos se explicar&aacute; su funci&oacute;n, tipos, factores de forma, componentes y las caracter&iacute;sticas principales a tener en cuenta.</p>', '<p>Este tema es uno de los m&aacute;s importantes del m&oacute;dulo ya que se trabaja sobre los componentes principales de un sistema inform&aacute;tico, sus tipos, caracter&iacute;sticas y compatibilidad entre ellos. Estos conocimientos son muy importantes a la hora del ensamblaje de un sistema inform&aacute;tico.</p>', '', '<ol>\r\n<li>Placa base\r\n<ul>\r\n<li>Introducci&oacute;n.</li>\r\n<li>Factor de forma.</li>\r\n<li>Componentes de la placa base.\r\n<ul>\r\n<li>Socket CPU.</li>\r\n<li>Slot de memoria.</li>\r\n<li>Chipset.</li>\r\n<li>BIOS.</li>\r\n<li>Slots de expansi&oacute;n.</li>\r\n<li>Conectores de alimentaci&oacute;n.</li>\r\n<li>Conectores internos.</li>\r\n<li>Conectores externos.</li>\r\n<li>Puertos USB.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>Procesador\r\n<ul>\r\n<li>Introducci&oacute;n</li>\r\n<li>Arquitectura interna.</li>\r\n<li>Caracter&iacute;sticas de la CPU.</li>\r\n<li>Arquitectura 32 vs 64 bits.</li>\r\n<li>Tecnolog&iacute;as utilizadas en procesadores.</li>\r\n<li>Intel vs AMD.</li>\r\n<li>SoC.</li>\r\n</ul>\r\n</li>\r\n<li>RAM\r\n<ul>\r\n<li>Introducci&oacute;n.</li>\r\n<li>Estructura f&iacute;sica e interna de RAM.</li>\r\n<li>Caracter&iacute;sticas.</li>\r\n<li>Tipos de RAM.</li>\r\n<li>M&oacute;dulos de memoria.</li>\r\n<li>Memorias con registro.</li>\r\n<li>Sistemas de refrigeraci&oacute;n.</li>\r\n</ul>\r\n</li>\r\n</ol>\r\n<p>&nbsp;</p>', '<ul>\r\n<li>Placa base. En primer lugar se abordar&aacute; como primer componente en el ensamblado de un equipo la placa base. Se estudiar&aacute; su funci&oacute;n, factores de forma y componentes internos y externos</li>\r\n<li>Procesador. Se explicar&aacute; la funci&oacute;n del procesador dentro del sistema, su arquitectura, las caracter&iacute;sticas m&aacute;s relevantes. Se har&aacute; hincapi&eacute; en la diferencia entre arquitecturas de procesadores y se ver&aacute;n las diferentes tecnolog&iacute;as actuales que se utilizan en procesadores. Por &uacute;ltimo se ver&aacute; la nomenclatura utilizada en procesadores Intel y AMD y los procesadores SoC.</li>\r\n<li>RAM. Como &uacute;ltimo componente en esta unidad se estudiar&aacute; la funci&oacute;n de la RAM,&nbsp; su estructura interna, caracter&iacute;sticas m&aacute;s relevantes y tipos.</li>\r\n</ul>', '', '<p style=\"text-align: justify;\"><strong>Modalidad presencial</strong></p>\r\n<p style=\"text-align: justify;\">La asistencia a clase es obligatoria por ley, por tanto, aquellos alumnos que no asistan como m&iacute;nimo al 85% de las horas, no tendr&aacute;n derecho a la evaluaci&oacute;n continua y deber&aacute;n realizar un examen final de todo el m&oacute;dulo.</p>\r\n<p style=\"text-align: justify;\">&nbsp;Al final de cada unidad tem&aacute;tica o de varias relacionadas entre s&iacute; (mismo bloque), podr&aacute; realizarse una prueba te&oacute;rica o te&oacute;rico-pr&aacute;ctica seg&uacute;n la naturaleza de la unidad que servir&aacute; para medir el grado de destreza obtenido en la materia por el alumno. Como m&iacute;nimo se realizar&aacute; una prueba por trimestre. Estas pruebas englobar&aacute;n el contenido que se haya impartido desde la &uacute;ltima prueba realizada. Los per&iacute;odos en los que se imparten las unidades est&aacute;n especificados en el apartado Secuenciaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">As&iacute; mismo se establecer&aacute;n fechas de entrega de las distintas actividades que se vayan planteando a lo largo de cada trimestre. Las actividades no entregadas se puntuar&aacute;n como 0. Las actividades entregadas fuera de plazo podr&aacute;n calificarse como 0 o bien su nota se ver&aacute; reducida en funci&oacute;n del tiempo que se tarde en entregarse una vez terminado el plazo.</p>\r\n<p style=\"text-align: justify;\">La nota de cada evaluaci&oacute;n se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Pruebas objetivas sobre los contenidos te&oacute;ricos y pr&aacute;cticos realizados en la evaluaci&oacute;n</span></span>:&nbsp;<strong>70%.</strong></p>\r\n</li>\r\n<li>\r\n<p>E<span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">jercicios pr&aacute;cticos, ejercicios te&oacute;ricos, trabajos, supuestos te&oacute;rico-pr&aacute;cticos</span></span>:&nbsp;<strong>30%</strong>.&nbsp;</p>\r\n</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n 4,5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Por otra parte, actitudes como utilizar el ordenador para jugar, instalar software no autorizado, cambiar la configuraci&oacute;n de los equipos, actitudes que impidan el funcionamiento de clase con interrupciones continuas, no traer material, ser&aacute; tenido en cuenta y penalizado, independientemente de las sanciones que pudiera dictar el consejo escolar.</p>\r\n<p style=\"text-align: justify;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Modalidad semipresencial</strong></p>\r\n<p style=\"text-align: justify;\">En la modalidad semipresencial, la nota se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Test o ex&aacute;menes te&oacute;rico pr&aacute;cticos sobre los contenidos:&nbsp;<strong>70%</strong></span></span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Ejercicios te&oacute;rico-practicos, trabajos y pr&aacute;cticas presenciales:<strong>&nbsp;30%</strong></span></span></p>\r\n</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Durante la evaluaci&oacute;n se propondr&aacute;n ejercicios de car&aacute;cter te&oacute;rico-pr&aacute;ctico semanales para que el alumno afiance los contenidos aprendidos en cada semana. Estas actividades son obligatorias y deber&aacute;n entregarse todas para poder realizar la media de los ejercicios. Las actividades no entregadas, entregadas fuera de plazo o copiadas, tendr&aacute;n una calificaci&oacute;n de 0.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Aunque en la modalidad semipresencial, de forma general,&nbsp; la asistencia a las tutor&iacute;as no es obligatoria, la asignatura de Fundamentos de Hardware, seg&uacute;n lo dispuesto en la Resoluci&oacute;n de 22 de mayo de 2018 de la Direcci&oacute;n General de Formaci&oacute;n Profesional deber&aacute; realizar una serie de horas presenciales de forma obligatoria. Estas tutorias colectivas obligatorias tendr&aacute;n como objetivo realizar pr&aacute;cticas para el montaje y reparaci&oacute;n de equipos inform&aacute;ticos. La no asistencia a las sesiones de presencialidad obligatoria comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Al final de cada evaluaci&oacute;n se realizar&aacute; una prueba te&oacute;rico-pr&aacute;ctica que servir&aacute; para medir el grado de destreza obtenido en la materia por parte del alumno. La no asistencia a alguno de los ex&aacute;menes que se realizar&aacute;n de cada evaluaci&oacute;n comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n de 5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Para calcular la media del curso se realizar&aacute; una ponderaci&oacute;n en funci&oacute;n de los porcentajes asignados a cada unidad.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>', '', '', 1, 1, 1, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(42, 7, 4, 'Estructura física de un sistema informático. Componentes internos II.', 12, 1, 16, '<p>En esta unidad se abordar&aacute;n el resto de componentes necesarios para ensamblar un PC de forma completa como son las unidades de almacenamiento, tarjetas de expansi&oacute;n, caja y fuente de alimentaci&oacute;n.&nbsp;</p>', '<p>En esta unidad se abordan el resto de componentes necesarios para el ensamblado de un Pc as&iacute; como sus caracter&iacute;sticas, tipos y compatibilidad. La importancia de esta unidad radica en que sin esos conocimientos el alumno no estar&aacute; en disposici&oacute;n de ensamblar adecuadamente un equipo con todos sus componentes y completamente compatible.</p>', '', '<ol>\r\n<li>Unidades de almacenamiento.\r\n<ul>\r\n<li>Introducci&oacute;n.</li>\r\n<li>Dispositivos magn&eacute;ticos.\r\n<ul>\r\n<li>Disco duro.</li>\r\n<li>Cintas magn&eacute;ticas.</li>\r\n</ul>\r\n</li>\r\n<li>Dispositivos flash.<br />\r\n<ul>\r\n<li>Unidades SSD.</li>\r\n</ul>\r\n</li>\r\n<li>Dispositivos &oacute;pticos.</li>\r\n</ul>\r\n</li>\r\n<li>Tarjetas de expansi&oacute;n.&nbsp;\r\n<ul>\r\n<li>Tarjetas gr&aacute;ficas.</li>\r\n<li>Tarjetas de red.</li>\r\n<li>Tarjetas de sonido.</li>\r\n<li>Otras tarjetas de expansi&oacute;n.</li>\r\n</ul>\r\n</li>\r\n<li>Caja.</li>\r\n<li>Fuente de alimentaci&oacute;n.</li>\r\n</ol>', '<p>&nbsp;</p>\r\n<ul>\r\n<li>Unidades de almacenamiento. Primero se abordar&aacute; que es una unidad de almacenamiento para depu&eacute;s ver los diferentes tipos de unidades de almacenamiento y dentro de cada tipo los principales dispositivos de almacenamiento.</li>\r\n<li>Tarjetas de expansi&oacute;n. Se explicar&aacute; la necesidad de utiliza tarjetas de expansi&oacute;n en ciertos casos y se trabajar&aacute; sobre los principales tipos de tarjetas que se pueden ensamblar en el equipo as&iacute; como sus caracter&iacute;sticas principales.</li>\r\n<li>Caja. Se explicar&aacute; su funci&oacute;n, materiales, diferentes partes y la compatibilidad con el resto de elementos.</li>\r\n<li>Fuente de alimentaci&oacute;n. Por &uacute;ltimo se ver&aacute;n los diferentes tipos de fuente de alimentaci&oacute;n, sus caracter&iacute;sticas y c&oacute;mo elegir una fuente adecuada para un equipo.</li>\r\n</ul>\r\n<p>&nbsp;</p>', '', '<p style=\"text-align: justify;\"><strong>Modalidad presencial</strong></p>\r\n<p style=\"text-align: justify;\">La asistencia a clase es obligatoria por ley, por tanto, aquellos alumnos que no asistan como m&iacute;nimo al 85% de las horas, no tendr&aacute;n derecho a la evaluaci&oacute;n continua y deber&aacute;n realizar un examen final de todo el m&oacute;dulo.</p>\r\n<p style=\"text-align: justify;\">&nbsp;Al final de cada unidad tem&aacute;tica o de varias relacionadas entre s&iacute; (mismo bloque), podr&aacute; realizarse una prueba te&oacute;rica o te&oacute;rico-pr&aacute;ctica seg&uacute;n la naturaleza de la unidad que servir&aacute; para medir el grado de destreza obtenido en la materia por el alumno. Como m&iacute;nimo se realizar&aacute; una prueba por trimestre. Estas pruebas englobar&aacute;n el contenido que se haya impartido desde la &uacute;ltima prueba realizada. Los per&iacute;odos en los que se imparten las unidades est&aacute;n especificados en el apartado Secuenciaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">As&iacute; mismo se establecer&aacute;n fechas de entrega de las distintas actividades que se vayan planteando a lo largo de cada trimestre. Las actividades no entregadas se puntuar&aacute;n como 0. Las actividades entregadas fuera de plazo podr&aacute;n calificarse como 0 o bien su nota se ver&aacute; reducida en funci&oacute;n del tiempo que se tarde en entregarse una vez terminado el plazo.</p>\r\n<p style=\"text-align: justify;\">La nota de cada evaluaci&oacute;n se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Pruebas objetivas sobre los contenidos te&oacute;ricos y pr&aacute;cticos realizados en la evaluaci&oacute;n</span></span>:&nbsp;<strong>70%.</strong></p>\r\n</li>\r\n<li>\r\n<p>E<span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">jercicios pr&aacute;cticos, ejercicios te&oacute;ricos, trabajos, supuestos te&oacute;rico-pr&aacute;cticos</span></span>:&nbsp;<strong>30%</strong>.&nbsp;</p>\r\n</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n 4,5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Por otra parte, actitudes como utilizar el ordenador para jugar, instalar software no autorizado, cambiar la configuraci&oacute;n de los equipos, actitudes que impidan el funcionamiento de clase con interrupciones continuas, no traer material, ser&aacute; tenido en cuenta y penalizado, independientemente de las sanciones que pudiera dictar el consejo escolar.</p>\r\n<p style=\"text-align: justify;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Modalidad semipresencial</strong></p>\r\n<p style=\"text-align: justify;\">En la modalidad semipresencial, la nota se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Test o ex&aacute;menes te&oacute;rico pr&aacute;cticos sobre los contenidos:&nbsp;<strong>70%</strong></span></span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Ejercicios te&oacute;rico-practicos, trabajos y pr&aacute;cticas presenciales:<strong>&nbsp;30%</strong></span></span></p>\r\n</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Durante la evaluaci&oacute;n se propondr&aacute;n ejercicios de car&aacute;cter te&oacute;rico-pr&aacute;ctico semanales para que el alumno afiance los contenidos aprendidos en cada semana. Estas actividades son obligatorias y deber&aacute;n entregarse todas para poder realizar la media de los ejercicios. Las actividades no entregadas, entregadas fuera de plazo o copiadas, tendr&aacute;n una calificaci&oacute;n de 0.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Aunque en la modalidad semipresencial, de forma general,&nbsp; la asistencia a las tutor&iacute;as no es obligatoria, la asignatura de Fundamentos de Hardware, seg&uacute;n lo dispuesto en la Resoluci&oacute;n de 22 de mayo de 2018 de la Direcci&oacute;n General de Formaci&oacute;n Profesional deber&aacute; realizar una serie de horas presenciales de forma obligatoria. Estas tutorias colectivas obligatorias tendr&aacute;n como objetivo realizar pr&aacute;cticas para el montaje y reparaci&oacute;n de equipos inform&aacute;ticos. La no asistencia a las sesiones de presencialidad obligatoria comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Al final de cada evaluaci&oacute;n se realizar&aacute; una prueba te&oacute;rico-pr&aacute;ctica que servir&aacute; para medir el grado de destreza obtenido en la materia por parte del alumno. La no asistencia a alguno de los ex&aacute;menes que se realizar&aacute;n de cada evaluaci&oacute;n comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n de 5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Para calcular la media del curso se realizar&aacute; una ponderaci&oacute;n en funci&oacute;n de los porcentajes asignados a cada unidad.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>', '', '', 1, 1, 1, 1),
(43, 7, 5, 'Ensamblaje y puesta en marcha de un sistema informático.', 18, 2, 16, '<p>En esta unidad se trabajar&aacute; el montaje y reparaci&oacute;n de un sistema inform&aacute;tico teniendo en cuenta ciertas medidas de seguridad para proteger al t&eacute;cnico y a los componentes.</p>', '<p>Esta unidad es una de las m&aacute;s importantes del m&oacute;dulo ya que en ella se ponen en pr&aacute;ctica los conocimientos adquiridos en las unidades anteriores. Para ello, el alumno practicar&aacute; en el laboratorio c&oacute;mo montar un sistema inform&aacute;tico as&iacute; como diferentes t&eacute;cnicas para comprobar el funcionamiento adecuado de cada uno de los componentes.</p>', '', '<ul>\r\n<li>Precauciones y medidas de seguridad.</li>\r\n<li>Herramientas y dispositivos de chequeo de componentes.</li>\r\n<li>Secuencia de ensamblaje de un equipo inform&aacute;tico.</li>\r\n<li>Detenci&oacute;n de problemas de funcionamiento y sus causas. Reparaci&oacute;n de equipos.</li>\r\n<li>Monitorizaci&oacute;n y herramientas software de chequeo.</li>\r\n</ul>', '<p>Primero se explicar&aacute;n las precauciones y medidas de seguridad a tener en cuenta al trabajar con componentes inform&aacute;ticos y herramientas que se pueden utilizar aumentar nuestra seguridad y la de los componentes.</p>\r\n<p>Despu&eacute;s se ver&aacute;n las diferentes herramientas a utilizar para ensamblar equipos as&iacute; como otros dispositivos para chequear el funcionamiento de los componentes.</p>\r\n<p>A continuaci&oacute;n se ver&aacute;n los pasos necesarios para el ensamblaje de un equipo inform&aacute;tico y comenzar&aacute;n las pr&aacute;cticas en el taller. Al mismo tiempo se trabajar&aacute; la detecci&oacute;n de fallos en el montaje de un equipo y sus causas.</p>\r\n<p>Por &uacute;ltimo, una vez montados los equipos se utilizar&aacute; software para comprobar el correcto funcionamiento de los equipos y para el testeo de componentes.</p>', '', '<p style=\"text-align: justify;\"><strong>Modalidad presencial</strong></p>\r\n<p style=\"text-align: justify;\">La asistencia a clase es obligatoria por ley, por tanto, aquellos alumnos que no asistan como m&iacute;nimo al 85% de las horas, no tendr&aacute;n derecho a la evaluaci&oacute;n continua y deber&aacute;n realizar un examen final de todo el m&oacute;dulo.</p>\r\n<p style=\"text-align: justify;\">&nbsp;Al final de cada unidad tem&aacute;tica o de varias relacionadas entre s&iacute; (mismo bloque), podr&aacute; realizarse una prueba te&oacute;rica o te&oacute;rico-pr&aacute;ctica seg&uacute;n la naturaleza de la unidad que servir&aacute; para medir el grado de destreza obtenido en la materia por el alumno. Como m&iacute;nimo se realizar&aacute; una prueba por trimestre. Estas pruebas englobar&aacute;n el contenido que se haya impartido desde la &uacute;ltima prueba realizada. Los per&iacute;odos en los que se imparten las unidades est&aacute;n especificados en el apartado Secuenciaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">As&iacute; mismo se establecer&aacute;n fechas de entrega de las distintas actividades que se vayan planteando a lo largo de cada trimestre. Las actividades no entregadas se puntuar&aacute;n como 0. Las actividades entregadas fuera de plazo podr&aacute;n calificarse como 0 o bien su nota se ver&aacute; reducida en funci&oacute;n del tiempo que se tarde en entregarse una vez terminado el plazo.</p>\r\n<p style=\"text-align: justify;\">La nota de cada evaluaci&oacute;n se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Pruebas objetivas sobre los contenidos te&oacute;ricos y pr&aacute;cticos realizados en la evaluaci&oacute;n</span></span>:&nbsp;<strong>70%.</strong></p>\r\n</li>\r\n<li>\r\n<p>E<span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">jercicios pr&aacute;cticos, ejercicios te&oacute;ricos, trabajos, supuestos te&oacute;rico-pr&aacute;cticos</span></span>:&nbsp;<strong>30%</strong>.&nbsp;</p>\r\n</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n 4,5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Por otra parte, actitudes como utilizar el ordenador para jugar, instalar software no autorizado, cambiar la configuraci&oacute;n de los equipos, actitudes que impidan el funcionamiento de clase con interrupciones continuas, no traer material, ser&aacute; tenido en cuenta y penalizado, independientemente de las sanciones que pudiera dictar el consejo escolar.</p>\r\n<p style=\"text-align: justify;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Modalidad semipresencial</strong></p>\r\n<p style=\"text-align: justify;\">En la modalidad semipresencial, la nota se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Test o ex&aacute;menes te&oacute;rico pr&aacute;cticos sobre los contenidos:&nbsp;<strong>70%</strong></span></span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Ejercicios te&oacute;rico-practicos, trabajos y pr&aacute;cticas presenciales:<strong>&nbsp;30%</strong></span></span></p>\r\n</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Durante la evaluaci&oacute;n se propondr&aacute;n ejercicios de car&aacute;cter te&oacute;rico-pr&aacute;ctico semanales para que el alumno afiance los contenidos aprendidos en cada semana. Estas actividades son obligatorias y deber&aacute;n entregarse todas para poder realizar la media de los ejercicios. Las actividades no entregadas, entregadas fuera de plazo o copiadas, tendr&aacute;n una calificaci&oacute;n de 0.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Aunque en la modalidad semipresencial, de forma general,&nbsp; la asistencia a las tutor&iacute;as no es obligatoria, la asignatura de Fundamentos de Hardware, seg&uacute;n lo dispuesto en la Resoluci&oacute;n de 22 de mayo de 2018 de la Direcci&oacute;n General de Formaci&oacute;n Profesional deber&aacute; realizar una serie de horas presenciales de forma obligatoria. Estas tutorias colectivas obligatorias tendr&aacute;n como objetivo realizar pr&aacute;cticas para el montaje y reparaci&oacute;n de equipos inform&aacute;ticos. La no asistencia a las sesiones de presencialidad obligatoria comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Al final de cada evaluaci&oacute;n se realizar&aacute; una prueba te&oacute;rico-pr&aacute;ctica que servir&aacute; para medir el grado de destreza obtenido en la materia por parte del alumno. La no asistencia a alguno de los ex&aacute;menes que se realizar&aacute;n de cada evaluaci&oacute;n comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n de 5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Para calcular la media del curso se realizar&aacute; una ponderaci&oacute;n en funci&oacute;n de los porcentajes asignados a cada unidad.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>', '', '', 1, 1, 1, 1),
(44, 7, 6, 'Implementación de un sistema informático. Soluciones empresariales.', 12, 2, 16, '<p>En esta unidad los alumnos conocer&aacute;n los sistemas inform&aacute;ticos que se utilizan en el entorno empresarial y cient&iacute;fico as&iacute; como el hardware utilizado en este tipo de sistemas.</p>', '<p>La&nbsp; importancia de esta unidad radica en la necesidad de los alumnos de conocer el hardware utilizado en el entorno empresarial que es donde trabajar&aacute;n una vez terminado este ciclo formativo.</p>', '', '<ul>\r\n<li>Sistemas inform&aacute;ticos como soluciones empresariales.</li>\r\n<li>Tipos de sistemas inform&aacute;ticos en el entorno empresarial y organizaciones.</li>\r\n<li>Servidores\r\n<ul>\r\n<li>Tipos.</li>\r\n<li>Hardware de servidores.</li>\r\n<li>Almacenamiento\r\n<ul>\r\n<li>RAID</li>\r\n<li>Tecnolog&iacute;as de almacenamiento.</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>', '<p>Primero se abordar&aacute; la importancia de conocer los sistemas inform&aacute;ticos en el entorno empresarial. Se expondr&aacute;n los diferentes tipos de sistemas inform&aacute;ticos que se pueden encontrarl y por &uacute;ltimo nos centraremos en las soluciones para servidores haciendo hincapi&eacute; en su hardware espec&iacute;fico y sus sistemas de almacenamiento.</p>', '', '<p style=\"text-align: justify;\"><strong>Modalidad presencial</strong></p>\r\n<p style=\"text-align: justify;\">La asistencia a clase es obligatoria por ley, por tanto, aquellos alumnos que no asistan como m&iacute;nimo al 85% de las horas, no tendr&aacute;n derecho a la evaluaci&oacute;n continua y deber&aacute;n realizar un examen final de todo el m&oacute;dulo.</p>\r\n<p style=\"text-align: justify;\">&nbsp;Al final de cada unidad tem&aacute;tica o de varias relacionadas entre s&iacute; (mismo bloque), podr&aacute; realizarse una prueba te&oacute;rica o te&oacute;rico-pr&aacute;ctica seg&uacute;n la naturaleza de la unidad que servir&aacute; para medir el grado de destreza obtenido en la materia por el alumno. Como m&iacute;nimo se realizar&aacute; una prueba por trimestre. Estas pruebas englobar&aacute;n el contenido que se haya impartido desde la &uacute;ltima prueba realizada. Los per&iacute;odos en los que se imparten las unidades est&aacute;n especificados en el apartado Secuenciaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">As&iacute; mismo se establecer&aacute;n fechas de entrega de las distintas actividades que se vayan planteando a lo largo de cada trimestre. Las actividades no entregadas se puntuar&aacute;n como 0. Las actividades entregadas fuera de plazo podr&aacute;n calificarse como 0 o bien su nota se ver&aacute; reducida en funci&oacute;n del tiempo que se tarde en entregarse una vez terminado el plazo.</p>\r\n<p style=\"text-align: justify;\">La nota de cada evaluaci&oacute;n se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Pruebas objetivas sobre los contenidos te&oacute;ricos y pr&aacute;cticos realizados en la evaluaci&oacute;n</span></span>:&nbsp;<strong>70%.</strong></p>\r\n</li>\r\n<li>\r\n<p>E<span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">jercicios pr&aacute;cticos, ejercicios te&oacute;ricos, trabajos, supuestos te&oacute;rico-pr&aacute;cticos</span></span>:&nbsp;<strong>30%</strong>.&nbsp;</p>\r\n</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n 4,5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Por otra parte, actitudes como utilizar el ordenador para jugar, instalar software no autorizado, cambiar la configuraci&oacute;n de los equipos, actitudes que impidan el funcionamiento de clase con interrupciones continuas, no traer material, ser&aacute; tenido en cuenta y penalizado, independientemente de las sanciones que pudiera dictar el consejo escolar.</p>\r\n<p style=\"text-align: justify;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Modalidad semipresencial</strong></p>\r\n<p style=\"text-align: justify;\">En la modalidad semipresencial, la nota se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Test o ex&aacute;menes te&oacute;rico pr&aacute;cticos sobre los contenidos:&nbsp;<strong>70%</strong></span></span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Ejercicios te&oacute;rico-practicos, trabajos y pr&aacute;cticas presenciales:<strong>&nbsp;30%</strong></span></span></p>\r\n</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Durante la evaluaci&oacute;n se propondr&aacute;n ejercicios de car&aacute;cter te&oacute;rico-pr&aacute;ctico semanales para que el alumno afiance los contenidos aprendidos en cada semana. Estas actividades son obligatorias y deber&aacute;n entregarse todas para poder realizar la media de los ejercicios. Las actividades no entregadas, entregadas fuera de plazo o copiadas, tendr&aacute;n una calificaci&oacute;n de 0.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Aunque en la modalidad semipresencial, de forma general,&nbsp; la asistencia a las tutor&iacute;as no es obligatoria, la asignatura de Fundamentos de Hardware, seg&uacute;n lo dispuesto en la Resoluci&oacute;n de 22 de mayo de 2018 de la Direcci&oacute;n General de Formaci&oacute;n Profesional deber&aacute; realizar una serie de horas presenciales de forma obligatoria. Estas tutorias colectivas obligatorias tendr&aacute;n como objetivo realizar pr&aacute;cticas para el montaje y reparaci&oacute;n de equipos inform&aacute;ticos. La no asistencia a las sesiones de presencialidad obligatoria comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Al final de cada evaluaci&oacute;n se realizar&aacute; una prueba te&oacute;rico-pr&aacute;ctica que servir&aacute; para medir el grado de destreza obtenido en la materia por parte del alumno. La no asistencia a alguno de los ex&aacute;menes que se realizar&aacute;n de cada evaluaci&oacute;n comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n de 5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Para calcular la media del curso se realizar&aacute; una ponderaci&oacute;n en funci&oacute;n de los porcentajes asignados a cada unidad.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>', '', '', 1, 1, 1, 1),
(45, 7, 7, 'Software de mantenimiento para sistemas informáticos.', 22, 3, 16, '<p>En este tema se realizar&aacute; la instalaci&oacute;n de diferentes tipos de software con diferentes licencias que se utilizan para el mantenimiento de sistemas inform&aacute;ticos.</p>', '<p>En esta unidad el alumno aprender&aacute; a utilizar software espec&iacute;fico para realizar particionamiento de discos, clonaci&oacute;n e im&aacute;genes de disco, copias de seguridad, tareas programadas etc. Una serie de tareas de mantenimiento que se realizan d&iacute;a a d&iacute;a en el entorno empresarial.</p>', '', '<ul>\r\n<li>Particionamiento de sistemas.</li>\r\n<li>Clonaci&oacute;n de discos. Creaci&oacute;n de im&aacute;genes. Puntos de restauraci&oacute;n.</li>\r\n<li>Copias de seguridad y t&eacute;cnicas de recuperaci&oacute;n de datos.</li>\r\n<li>Programaci&oacute;n de tareas.</li>\r\n</ul>', '<p>Primero se abordar&aacute; la importancia de ciertas tareas de mantenimiento a realizar en sistemas inform&aacute;ticos. Se mostrar&aacute; software espec&iacute;fico para cada una de las tareas con diferentes tipos de licencia. Se instalar&aacute; y analizar&aacute; el software necesario y se realizar&aacute;n las tareas que se han indicado en los contenidos:</p>\r\n<ul>\r\n<li>Particionamiento de disco.Recuperaci&oacute;n ante errores.</li>\r\n<li>Clonaci&oacute;n de disco. Im&aacute;genes de disco. Puntos de restauraci&oacute;n.</li>\r\n<li>Copias de seguridad y t&eacute;cnicas de recuperaci&oacute;n de datos.</li>\r\n<li>Tareas programadas.</li>\r\n</ul>', '', '<p style=\"text-align: justify;\"><strong>Modalidad presencial</strong></p>\r\n<p style=\"text-align: justify;\">La asistencia a clase es obligatoria por ley, por tanto, aquellos alumnos que no asistan como m&iacute;nimo al 85% de las horas, no tendr&aacute;n derecho a la evaluaci&oacute;n continua y deber&aacute;n realizar un examen final de todo el m&oacute;dulo.</p>\r\n<p style=\"text-align: justify;\">&nbsp;Al final de cada unidad tem&aacute;tica o de varias relacionadas entre s&iacute; (mismo bloque), podr&aacute; realizarse una prueba te&oacute;rica o te&oacute;rico-pr&aacute;ctica seg&uacute;n la naturaleza de la unidad que servir&aacute; para medir el grado de destreza obtenido en la materia por el alumno. Como m&iacute;nimo se realizar&aacute; una prueba por trimestre. Estas pruebas englobar&aacute;n el contenido que se haya impartido desde la &uacute;ltima prueba realizada. Los per&iacute;odos en los que se imparten las unidades est&aacute;n especificados en el apartado Secuenciaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">As&iacute; mismo se establecer&aacute;n fechas de entrega de las distintas actividades que se vayan planteando a lo largo de cada trimestre. Las actividades no entregadas se puntuar&aacute;n como 0. Las actividades entregadas fuera de plazo podr&aacute;n calificarse como 0 o bien su nota se ver&aacute; reducida en funci&oacute;n del tiempo que se tarde en entregarse una vez terminado el plazo.</p>\r\n<p style=\"text-align: justify;\">La nota de cada evaluaci&oacute;n se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Pruebas objetivas sobre los contenidos te&oacute;ricos y pr&aacute;cticos realizados en la evaluaci&oacute;n</span></span>:&nbsp;<strong>70%.</strong></p>\r\n</li>\r\n<li>\r\n<p>E<span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">jercicios pr&aacute;cticos, ejercicios te&oacute;ricos, trabajos, supuestos te&oacute;rico-pr&aacute;cticos</span></span>:&nbsp;<strong>30%</strong>.&nbsp;</p>\r\n</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n 4,5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Por otra parte, actitudes como utilizar el ordenador para jugar, instalar software no autorizado, cambiar la configuraci&oacute;n de los equipos, actitudes que impidan el funcionamiento de clase con interrupciones continuas, no traer material, ser&aacute; tenido en cuenta y penalizado, independientemente de las sanciones que pudiera dictar el consejo escolar.</p>\r\n<p style=\"text-align: justify;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Modalidad semipresencial</strong></p>\r\n<p style=\"text-align: justify;\">En la modalidad semipresencial, la nota se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Test o ex&aacute;menes te&oacute;rico pr&aacute;cticos sobre los contenidos:&nbsp;<strong>70%</strong></span></span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Ejercicios te&oacute;rico-practicos, trabajos y pr&aacute;cticas presenciales:<strong>&nbsp;30%</strong></span></span></p>\r\n</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Durante la evaluaci&oacute;n se propondr&aacute;n ejercicios de car&aacute;cter te&oacute;rico-pr&aacute;ctico semanales para que el alumno afiance los contenidos aprendidos en cada semana. Estas actividades son obligatorias y deber&aacute;n entregarse todas para poder realizar la media de los ejercicios. Las actividades no entregadas, entregadas fuera de plazo o copiadas, tendr&aacute;n una calificaci&oacute;n de 0.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Aunque en la modalidad semipresencial, de forma general,&nbsp; la asistencia a las tutor&iacute;as no es obligatoria, la asignatura de Fundamentos de Hardware, seg&uacute;n lo dispuesto en la Resoluci&oacute;n de 22 de mayo de 2018 de la Direcci&oacute;n General de Formaci&oacute;n Profesional deber&aacute; realizar una serie de horas presenciales de forma obligatoria. Estas tutorias colectivas obligatorias tendr&aacute;n como objetivo realizar pr&aacute;cticas para el montaje y reparaci&oacute;n de equipos inform&aacute;ticos. La no asistencia a las sesiones de presencialidad obligatoria comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Al final de cada evaluaci&oacute;n se realizar&aacute; una prueba te&oacute;rico-pr&aacute;ctica que servir&aacute; para medir el grado de destreza obtenido en la materia por parte del alumno. La no asistencia a alguno de los ex&aacute;menes que se realizar&aacute;n de cada evaluaci&oacute;n comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n de 5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Para calcular la media del curso se realizar&aacute; una ponderaci&oacute;n en funci&oacute;n de los porcentajes asignados a cada unidad.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>', '', '', 1, 1, 1, 1),
(47, 7, 8, 'Seguridad y protección ambiental en sistemas informáticos.', 6, 3, 5, '<p>En esta unidad el alumno conocer&aacute; la importancia de tomar medidas de seguridad en el desempe&ntilde;o de su trabajo como t&eacute;cnico as&iacute; como las medidas que se deben tomar para la protecci&oacute;n medioambiental.</p>', '<p>La seguridad en el trabajo es fundamental en el desarrollo de cualquier funci&oacute;n ya que puede afectar a la salud del t&eacute;cnico, por ello, el alumno deben conocer cuales son las medidas a tener en cuenta para prevenir problemas de salud.</p>\r\n<p>Por otro lado, la contaminaci&oacute;n medioambiental por dispositivos electr&oacute;nicos y su componentes es un hecho con lo que el alumno debe conocer cu&aacute;les son los principales problemas que puede causar la incorrecta gesti&oacute;n de residuos electr&oacute;nicos.&nbsp;</p>', '', '<ul>\r\n<li>Seguridad en el puesto de trabajo.\r\n<ul>\r\n<li>Prevenci&oacute;n de riesgos asociados al puesto de trabajo.</li>\r\n<li>Consejos a seguir en entornos inform&aacute;ticos.</li>\r\n</ul>\r\n</li>\r\n<li>Protecci&oacute;n medioambiental.\r\n<ul>\r\n<li>Residuos electr&oacute;nicos.</li>\r\n<li>Medidas para reducir el impacto medioambiental en inform&aacute;tica.</li>\r\n<li>Reciclaje de dispositivos electr&oacute;nicos.</li>\r\n</ul>\r\n</li>\r\n</ul>', '<p>En primer lugar se abordar&aacute; la seguridad en el puesto de trabajo, conociendo el marco legal asociado, los equipos de protecci&oacute;n, obligaciones de los empleadores y empleados con respecto a las medidas de seguridad y finalmente se abordar&aacute;n tipos espec&iacute;ficos para usuarios de equipos inform&aacute;ticos.</p>\r\n<p>Despu&eacute;s se abordar&aacute; la importancia de la protecci&oacute;n medioambiental, se explicar&aacute; el concepto de basura electr&oacute;nica y las medidas para reducir su impacto.</p>', '', '<p style=\"text-align: justify;\"><strong>Modalidad presencial</strong></p>\r\n<p style=\"text-align: justify;\">La asistencia a clase es obligatoria por ley, por tanto, aquellos alumnos que no asistan como m&iacute;nimo al 85% de las horas, no tendr&aacute;n derecho a la evaluaci&oacute;n continua y deber&aacute;n realizar un examen final de todo el m&oacute;dulo.</p>\r\n<p style=\"text-align: justify;\">&nbsp;Al final de cada unidad tem&aacute;tica o de varias relacionadas entre s&iacute; (mismo bloque), podr&aacute; realizarse una prueba te&oacute;rica o te&oacute;rico-pr&aacute;ctica seg&uacute;n la naturaleza de la unidad que servir&aacute; para medir el grado de destreza obtenido en la materia por el alumno. Como m&iacute;nimo se realizar&aacute; una prueba por trimestre. Estas pruebas englobar&aacute;n el contenido que se haya impartido desde la &uacute;ltima prueba realizada. Los per&iacute;odos en los que se imparten las unidades est&aacute;n especificados en el apartado Secuenciaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">As&iacute; mismo se establecer&aacute;n fechas de entrega de las distintas actividades que se vayan planteando a lo largo de cada trimestre. Las actividades no entregadas se puntuar&aacute;n como 0. Las actividades entregadas fuera de plazo podr&aacute;n calificarse como 0 o bien su nota se ver&aacute; reducida en funci&oacute;n del tiempo que se tarde en entregarse una vez terminado el plazo.</p>\r\n<p style=\"text-align: justify;\">La nota de cada evaluaci&oacute;n se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Pruebas objetivas sobre los contenidos te&oacute;ricos y pr&aacute;cticos realizados en la evaluaci&oacute;n</span></span>:&nbsp;<strong>70%.</strong></p>\r\n</li>\r\n<li>\r\n<p>E<span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">jercicios pr&aacute;cticos, ejercicios te&oacute;ricos, trabajos, supuestos te&oacute;rico-pr&aacute;cticos</span></span>:&nbsp;<strong>30%</strong>.&nbsp;</p>\r\n</li>\r\n</ul>\r\n<p style=\"text-align: justify;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n 4,5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Por otra parte, actitudes como utilizar el ordenador para jugar, instalar software no autorizado, cambiar la configuraci&oacute;n de los equipos, actitudes que impidan el funcionamiento de clase con interrupciones continuas, no traer material, ser&aacute; tenido en cuenta y penalizado, independientemente de las sanciones que pudiera dictar el consejo escolar.</p>\r\n<p style=\"text-align: justify;\">&nbsp;&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong>Modalidad semipresencial</strong></p>\r\n<p style=\"text-align: justify;\">En la modalidad semipresencial, la nota se calcular&aacute; de acuerdo a la siguiente ponderaci&oacute;n:</p>\r\n<ul style=\"text-align: justify;\">\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Test o ex&aacute;menes te&oacute;rico pr&aacute;cticos sobre los contenidos:&nbsp;<strong>70%</strong></span></span></p>\r\n</li>\r\n<li>\r\n<p><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">Ejercicios te&oacute;rico-practicos, trabajos y pr&aacute;cticas presenciales:<strong>&nbsp;30%</strong></span></span></p>\r\n</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Durante la evaluaci&oacute;n se propondr&aacute;n ejercicios de car&aacute;cter te&oacute;rico-pr&aacute;ctico semanales para que el alumno afiance los contenidos aprendidos en cada semana. Estas actividades son obligatorias y deber&aacute;n entregarse todas para poder realizar la media de los ejercicios. Las actividades no entregadas, entregadas fuera de plazo o copiadas, tendr&aacute;n una calificaci&oacute;n de 0.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Podr&aacute;n proponerse ejercicios pr&aacute;cticos de ampliaci&oacute;n en las unidades que el profesor o profesora considere adecuado. Estos ejercicios ser&aacute;n voluntarios y permitir&aacute;n sumar hasta un punto sobre diez en la nota de pr&aacute;cticas.</p>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Aunque en la modalidad semipresencial, de forma general,&nbsp; la asistencia a las tutor&iacute;as no es obligatoria, la asignatura de Fundamentos de Hardware, seg&uacute;n lo dispuesto en la Resoluci&oacute;n de 22 de mayo de 2018 de la Direcci&oacute;n General de Formaci&oacute;n Profesional deber&aacute; realizar una serie de horas presenciales de forma obligatoria. Estas tutorias colectivas obligatorias tendr&aacute;n como objetivo realizar pr&aacute;cticas para el montaje y reparaci&oacute;n de equipos inform&aacute;ticos. La no asistencia a las sesiones de presencialidad obligatoria comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Al final de cada evaluaci&oacute;n se realizar&aacute; una prueba te&oacute;rico-pr&aacute;ctica que servir&aacute; para medir el grado de destreza obtenido en la materia por parte del alumno. La no asistencia a alguno de los ex&aacute;menes que se realizar&aacute;n de cada evaluaci&oacute;n comportar&aacute; la p&eacute;rdida de la evaluaci&oacute;n continua.</p>\r\n<p style=\"text-align: justify;\">Para superar cada evaluaci&oacute;n del m&oacute;dulo, as&iacute; como la evaluaci&oacute;n final, ser&aacute; necesario que la media total de cada evaluaci&oacute;n sea al menos de 5 puntos, y adem&aacute;s ha de alcanzarse al menos una calificaci&oacute;n de 5 tanto en las pruebas te&oacute;rico-pr&aacute;cticas como en los trabajos y ejercicios propuestos por el profesor.</p>\r\n<p style=\"text-align: justify;\">Para calcular la media del curso se realizar&aacute; una ponderaci&oacute;n en funci&oacute;n de los porcentajes asignados a cada unidad.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>', '', '', 1, 1, 1, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(48, 26, 1, 'Introduction to computer systems', 18, 1, 8, '<p class=\"p1\">Esta unidad introduce los fundamentos de los sistemas inform&aacute;ticos, abordando sus principales componentes &mdash;hardware, software y tipos de sistemas&mdash; y la funci&oacute;n que desempe&ntilde;an dentro de un ordenador. Se estudian las distintas categor&iacute;as de software, la estructura y clasificaci&oacute;n de los sistemas operativos, as&iacute; como la forma en que estos gestionan la informaci&oacute;n y los recursos del sistema. Adem&aacute;s, se analiza la representaci&oacute;n digital de la informaci&oacute;n y las diferencias entre software libre y propietario, proporcionando una visi&oacute;n global de c&oacute;mo interact&uacute;an todos los elementos que conforman un sistema inform&aacute;tico moderno.</p>', '<p class=\"p1\">Este tema constituye la base conceptual del m&oacute;dulo de <em>Sistemas Operativos Monousuario (SOM)</em>, ya que ofrece al alumnado los conocimientos necesarios para comprender c&oacute;mo funcionan los sistemas operativos y su papel dentro del conjunto del sistema inform&aacute;tico. Entender la estructura, clasificaci&oacute;n y principios b&aacute;sicos de los sistemas operativos permite asentar los cimientos para el trabajo pr&aacute;ctico posterior, en el que se profundizar&aacute; en la instalaci&oacute;n, configuraci&oacute;n y administraci&oacute;n de distintos entornos operativos.&nbsp;Permite abordar con solidez las tareas de gesti&oacute;n y mantenimiento que se desarrollan en las unidades siguientes.</p>', '', '<ul>\r\n<li>\r\n<p class=\"p1\">Definici&oacute;n de sistema inform&aacute;tico</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Hardware y componentes b&aacute;sicos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Definici&oacute;n de software</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Tipos de software (de sistema, de aplicaci&oacute;n, firmware)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Tipos y clasificaci&oacute;n de ordenadores (mainframes, superordenadores, servidores, PCs)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Concepto de sistema operativo</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Estructura del sistema operativo (monol&iacute;tica, por capas, modular)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Sistemas operativos actuales</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Criterios de clasificaci&oacute;n de los sistemas operativos (por estructura, por n&uacute;mero de usuarios, multitarea, tipo de licencia, n&uacute;mero de CPUs)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Sistemas de representaci&oacute;n de la informaci&oacute;n (binario, hexadecimal, ASCII, Unicode) y su relaci&oacute;n con el sistema operativo</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Software libre vs. software propietario (licencias)</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">&nbsp;</p>', '<p>Presentaci&oacute;n de los conceptos b&aacute;sicos de sistemas y sus componentes</p>\r\n<p>Trabajo con ejemplos cotidianos en los que identificar componentes y tipos de sistemas</p>\r\n<p>Buscar y clasificar Sistemas Operativos seg&uacute;n distintos criterios</p>\r\n<p>Identificar, de sus equipos personales, qu&eacute; tipo de sistema &eacute;s y cuales son sus caracter&iacute;sticas</p>\r\n<p>Manejar las unidades de medida de los dispositivos de almacenamiento e identificar c&oacute;mo los representa el S.O.</p>\r\n<p>Buscar y comentar ejemplos de distintos tipos de software seg&uacute;n su licenciamiento</p>\r\n<p>Debate abierto y resoluci&oacute;n de dudas</p>', '', '<p>Pruebas objetivas&nbsp;(60 %)<br />Actividades en el aula (30 %)<br />Observaci&oacute;n directa y&nbsp;formaci&oacute;n entre iguales&nbsp;(10 %)</p>\n<p>&nbsp;</p>\n<p>Se deber&aacute; entregar un resumen de la parte te&oacute;rica de la unidad hecho a mano, antes de la realizaci&oacute;n de la prueba objetiva, aplic&aacute;ndose la penalizaci&oacute;n/bonificaci&oacute;n que corresponda a la nota del examen seg&uacute;n la siguiente r&uacute;brica: <br /><br />No entregado: -1,00 puntos <br />Satisfactorio: +0,00 puntos <br />Supera las expectativas: +1,00 puntos (Siempre que la prueba objetiva obtenga al menos una calificaci&oacute;n de 4 puntos)<br /><br /><br /></p>', '', '', 1, 1, 1, 1),
(49, 26, 2, 'Virtualization', 12, 1, 10, '<p class=\"p1\">Esta unidad introduce el concepto de virtualizaci&oacute;n y su comparaci&oacute;n con los sistemas f&iacute;sicos tradicionales. Se analizan sus ventajas e inconvenientes, los distintos tipos de hipervisores y las opciones b&aacute;sicas de configuraci&oacute;n de m&aacute;quinas virtuales. A trav&eacute;s del uso de VirtualBox, el alumnado aprende a crear y gestionar m&aacute;quinas virtuales, desplegar sistemas operativos Windows y Linux a partir de im&aacute;genes OVA, utilizar snapshots para la recuperaci&oacute;n de estados y aplicar integraciones como carpetas compartidas o portapapeles com&uacute;n. Finalmente, se eval&uacute;a el rendimiento de los sistemas virtualizados frente a los f&iacute;sicos mediante pruebas de CPU, memoria y disco.</p>', '<p class=\"p1\">La virtualizaci&oacute;n tiene un papel clave en el m&oacute;dulo <em>Sistemas Operativos Monousuario (SOM)</em>, ya que proporciona un entorno seguro y flexible para aprender a instalar y administrar distintos sistemas operativos sin comprometer el equipo f&iacute;sico del alumnado. Esta unidad permite desarrollar competencias pr&aacute;cticas esenciales para el trabajo t&eacute;cnico, como la gesti&oacute;n de hipervisores, el despliegue de entornos de prueba y la comparaci&oacute;n de configuraciones entre sistemas reales y virtuales. Adem&aacute;s, sienta las bases metodol&oacute;gicas del m&oacute;dulo, ya que todas las pr&aacute;cticas posteriores se realizar&aacute;n en entornos virtualizados, optimizando los recursos y fomentando una comprensi&oacute;n m&aacute;s profunda de la arquitectura de los sistemas operativos.</p>', '', '<ul>\r\n<li>\r\n<p class=\"p1\">Concepto de virtualizaci&oacute;n y comparaci&oacute;n con sistemas f&iacute;sicos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Ventajas e inconvenientes</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Tipos de hipervisores</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Introducci&oacute;n a VirtualBox</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Creaci&oacute;n de una m&aacute;quina virtual y comparaci&oacute;n con un sistema f&iacute;sico; opciones de configuraci&oacute;n del hipervisor</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Concepto de <em>Virtual Appliance</em> (aplicaci&oacute;n virtual)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Despliegue de m&aacute;quinas virtuales Windows/Linux a partir de un archivo OVA</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><em>Snapshots</em> o instant&aacute;neas</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\"><em>Guest Additions</em> / integraciones (portapapeles, carpetas compartidas)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Pruebas de rendimiento de m&aacute;quinas virtuales (CPU/RAM/Disco): comparaci&oacute;n entre el sistema anfitri&oacute;n y el invitado</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">&nbsp;</p>', '<p>Presentar escenarios en los que la virtualizaci&oacute;n surge y toma partido</p>\r\n<p>Revisar ventajas y desventajas de la virtualizaci&oacute;n frente a sistemas f&iacute;sicos</p>\r\n<p>Descubrimiento del sistema Virtualbox</p>\r\n<p>Creaci&oacute;n b&aacute;sica de VMs en Virtualbox y ajuste de los par&aacute;metros que el sistema permite</p>\r\n<p>Despliegue de Virtual Appliances</p>\r\n<p>Manipulaci&oacute;n de sistema de SnapShots</p>\r\n<p>Evaluaci&oacute;n del rendimiento de una VM frente a un sistema f&iacute;sico</p>', '', '<p>Pruebas objetivas (70 %)<br />Observaci&oacute;n directa y formaci&oacute;n entre iguales (30 %)</p>\r\n<p><br /><br /></p>', '', '', 1, 1, 1, 1),
(50, 26, 3, 'Operating System Functions', 16, 1, 10, '<p class=\"p1\">Esta unidad profundiza en las funciones esenciales que realiza un sistema operativo para gestionar los recursos de un equipo inform&aacute;tico. Se analizan los principales subsistemas: la gesti&oacute;n de procesos y servicios, la planificaci&oacute;n de tareas y los estados de ejecuci&oacute;n; la gesti&oacute;n de memoria y las t&eacute;cnicas que permiten optimizar su uso; y la organizaci&oacute;n del almacenamiento mediante particiones y sistemas de archivos. Tambi&eacute;n se abordan conceptos clave sobre la gesti&oacute;n de entrada/salida, la integridad de los sistemas de archivos mediante <em>journaling</em>, y la administraci&oacute;n de la seguridad basada en permisos y control de recursos. Ofrece una visi&oacute;n estructurada de c&oacute;mo el sistema operativo coordina el funcionamiento interno del ordenador.</p>', '<p class=\"p1\">Permite comprender en profundidad c&oacute;mo el sistema operativo controla y coordina los recursos del sistema, garantizando su eficiencia y estabilidad. A partir de estos conocimientos, el alumnado podr&aacute; entender y diagnosticar el comportamiento del sistema, optimizar su rendimiento y resolver incidencias relacionadas con procesos, memoria o almacenamiento. Adem&aacute;s, proporciona la base te&oacute;rica necesaria para abordar con solvencia las unidades pr&aacute;cticas posteriores dedicadas a la administraci&oacute;n, configuraci&oacute;n y mantenimiento de sistemas Windows y Linux.</p>', '', '<ul>\r\n<li>\r\n<p class=\"p1\">Introducci&oacute;n a las funciones del sistema operativo</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de procesos: conceptos de proceso y servicio</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Planificador de procesos (<em>scheduler</em>): visi&oacute;n general</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Estados de un proceso</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Algoritmos de planificaci&oacute;n (visi&oacute;n general)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de memoria: t&eacute;cnicas, fragmentaci&oacute;n, paginaci&oacute;n, segmentaci&oacute;n, memoria virtual</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Almacenamiento: tipos y estructura de discos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Particionado de discos (MBR/GPT)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Concepto de sistema de archivos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Principales sistemas de archivos (FAT32, NTFS, EXT4)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Sistemas de archivos transaccionales (<em>journaling</em>) (NTFS/EXT4): integridad y recuperaci&oacute;n</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de entrada/salida (<em>I/O management</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de la seguridad (recursos y permisos)</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">&nbsp;</p>', '<p class=\"p1\">Introducci&oacute;n guiada a las funciones b&aacute;sicas que realiza un sistema operativo en la gesti&oacute;n de recursos</p>\r\n<p class=\"p1\">An&aacute;lisis de ejemplos de procesos y servicios en ejecuci&oacute;n en distintos sistemas operativos</p>\r\n<p class=\"p1\">Observaci&oacute;n de los estados de los procesos y comprensi&oacute;n del papel del planificador</p>\r\n<p class=\"p1\">Demostraciones sobre la gesti&oacute;n de memoria: paginaci&oacute;n, segmentaci&oacute;n y memoria virtual</p>\r\n<p class=\"p1\">Exploraci&oacute;n pr&aacute;ctica de los tipos de sistemas de archivos y sus diferencias (FAT32, NTFS, EXT4)</p>\r\n<p class=\"p1\">Visualizaci&oacute;n del particionado de discos (MBR/GPT) y estructura del almacenamiento</p>\r\n<p class=\"p1\">Identificaci&oacute;n de los mecanismos de seguridad y permisos de acceso a recursos</p>\r\n<p class=\"p1\">S&iacute;ntesis y debate final sobre el papel del sistema operativo como intermediario entre hardware y usuario</p>', '', '<p>Pruebas objetivas&nbsp;(60 %)<br />Actividades en el aula (30 %)<br />Observaci&oacute;n directa y&nbsp;formaci&oacute;n entre iguales&nbsp;(10 %)</p>\r\n<p>&nbsp;</p>\r\n<p>Se deber&aacute; entregar un resumen de la parte te&oacute;rica de la unidad hecho a mano, antes de la realizaci&oacute;n de la prueba objetiva, aplic&aacute;ndose la penalizaci&oacute;n/bonificaci&oacute;n que corresponda a la nota del examen seg&uacute;n la siguiente r&uacute;brica: <br /><br />No entregado: -1,00 puntos <br />Satisfactorio: +0,00 puntos <br />Supera las expectativas: +1,00 puntos (Siempre que la prueba objetiva obtenga al menos una calificaci&oacute;n de 4 puntos)<br /><br /><br /></p>', '', '', 1, 1, 1, 1),
(51, 26, 4, 'Introduction to Windows', 12, 2, 10, '<p>Presenta los fundamentos del sistema operativo Windows, abordando sus principales versiones, ediciones y diferencias entre entornos de servidor y de escritorio. Se analizan las arquitecturas ARM y x86, las interfaces disponibles (gr&aacute;fica y de l&iacute;nea de comandos) y los tipos de usuarios y permisos. El alumnado explora la estructura del sistema de archivos, el uso del Explorador de archivos y las herramientas b&aacute;sicas de gesti&oacute;n, como el Administrador de tareas. Adem&aacute;s, se incluyen aspectos de personalizaci&oacute;n del entorno y configuraci&oacute;n b&aacute;sica del sistema, con el fin de familiarizarse con las operaciones m&aacute;s comunes dentro del entorno Windows 11.</p>', '<p class=\"p1\">Esta unidad introduce al alumnado en el trabajo pr&aacute;ctico con Windows, uno de los sistemas operativos m&aacute;s utilizados en entornos personales y profesionales. Dentro del m&oacute;dulo <em>Sistemas Operativos Monousuario (SOM)</em>, permite comprender la organizaci&oacute;n interna del sistema, los mecanismos de permisos y usuarios, y el uso de las herramientas b&aacute;sicas de administraci&oacute;n. Con estos conocimientos, los estudiantes podr&aacute;n desenvolverse con solvencia en tareas cotidianas de gesti&oacute;n, configuraci&oacute;n y resoluci&oacute;n de problemas, sentando las bases para unidades posteriores dedicadas a la administraci&oacute;n avanzada del sistema y a la comparaci&oacute;n con otros entornos, como Linux.</p>', '', '<ul>\r\n<li>\r\n<p class=\"p1\">Versiones de Windows (Server vs Escritorio)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Ediciones de Windows 11</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">ARM vs x86 (compatibilidad de hardware)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Interfaces: gr&aacute;fica (GUI) y de l&iacute;nea de comandos (CLI)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Tipos de usuarios</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Estructura de directorios</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Propiedades de los archivos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Permisos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Administrador de tareas (<em>Task Manager</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Personalizaci&oacute;n del escritorio y pantalla de bloqueo</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Explorador de archivos y opciones</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">&nbsp;</p>', '<p class=\"p1\">Presentaci&oacute;n de las versiones y ediciones de Windows, diferenciando entre entornos Server y Desktop</p>\r\n<p class=\"p1\">Comparaci&oacute;n entre arquitecturas ARM y x86 y an&aacute;lisis de compatibilidades</p>\r\n<p class=\"p1\">Exploraci&oacute;n de la interfaz gr&aacute;fica (GUI) y de la l&iacute;nea de comandos (CMD)</p>\r\n<p class=\"p1\">Identificaci&oacute;n de tipos de usuarios y sus permisos asociados</p>\r\n<p class=\"p1\">Recorrido pr&aacute;ctico por la estructura de directorios del sistema</p>\r\n<p class=\"p1\">An&aacute;lisis de propiedades de archivos y gesti&oacute;n de permisos desde el entorno gr&aacute;fico</p>\r\n<p class=\"p1\">Uso del Administrador de tareas para el control de procesos y recursos</p>\r\n<p class=\"p1\">Personalizaci&oacute;n del entorno de trabajo: escritorio, fondo y pantalla de bloqueo</p>\r\n<p class=\"p1\">Pr&aacute;ctica guiada con el Explorador de archivos y sus opciones avanzadas</p>', '', '<p>Pruebas objetivas&nbsp;(70 %)<br />Observaci&oacute;n directa y&nbsp;formaci&oacute;n entre iguales&nbsp;(30 %)</p>\r\n<p>&nbsp;</p>\r\n<p>Podr&aacute; requerirse entregar un resumen de la parte te&oacute;rica de la unidad hecho a mano, antes de la realizaci&oacute;n de la prueba objetiva, aplic&aacute;ndose la penalizaci&oacute;n/bonificaci&oacute;n que corresponda a la nota del examen seg&uacute;n la siguiente r&uacute;brica:<br /><br />No entregado: -1,00 puntos<br />Satisfactorio: +0,00 puntos<br />Supera las expectativas: +1,00 puntos (Siempre que la prueba objetiva obtenga al menos una calificaci&oacute;n de 4 puntos)<br /><br /></p>', '', '', 1, 1, 1, 1),
(52, 26, 5, 'Introduction to Linux', 13, 2, 10, '<p>Ofrece una introducci&oacute;n pr&aacute;ctica al entorno Linux, uno de los sistemas operativos m&aacute;s relevantes en el &aacute;mbito profesional y educativo. Se presentan sus principales distribuciones y las distintas interfaces de interacci&oacute;n, tanto gr&aacute;ficas como mediante la Shell. El alumnado aprende la estructura jer&aacute;rquica de directorios del sistema, los tipos de usuarios, las propiedades y permisos de los archivos, as&iacute; como el uso de variables de entorno y los ficheros clave que controlan la configuraci&oacute;n del sistema. Adem&aacute;s, se estudia el proceso de arranque, lo que permite comprender c&oacute;mo se inicia y estructura un sistema Linux desde sus primeras fases.</p>', '<p>Introduce al alumnado en el manejo de Linux, un sistema operativo ampliamente utilizado en servidores, dispositivos embebidos y entornos de desarrollo. El conocimiento de su estructura, permisos, comandos b&aacute;sicos y archivos de configuraci&oacute;n proporciona una base s&oacute;lida para las unidades pr&aacute;cticas posteriores centradas en la administraci&oacute;n avanzada y el trabajo en l&iacute;nea de comandos. Adem&aacute;s, permite comparar y comprender las diferencias fundamentales entre Linux y Windows, reforzando una visi&oacute;n completa y profesional de los sistemas operativos m&aacute;s comunes en el &aacute;mbito t&eacute;cnico.</p>', '', '<ul>\r\n<li>\r\n<p class=\"p1\">Principales distribuciones de Linux</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Interfaces: gr&aacute;fica (GUI) y de l&iacute;nea de comandos (<em>Shell</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Diferentes entornos gr&aacute;ficos en Linux</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Tipos de usuarios</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Estructura de directorios</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Propiedades de los archivos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Permisos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Variables de entorno</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Proceso de arranque del sistema</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Archivos de configuraci&oacute;n del sistema</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">&nbsp;</p>', '<p class=\"p1\">Presentaci&oacute;n de las principales distribuciones de Linux y sus diferencias</p>\r\n<p class=\"p1\">Reconocimiento de las interfaces disponibles: GUI y <em>Shell</em></p>\r\n<p class=\"p1\">Exploraci&oacute;n de distintos entornos gr&aacute;ficos (GNOME, KDE, XFCE, etc.)</p>\r\n<p class=\"p1\">Identificaci&oacute;n de tipos de usuarios y sus roles en el sistema</p>\r\n<p class=\"p1\">Navegaci&oacute;n por la estructura jer&aacute;rquica de directorios de Linux</p>\r\n<p class=\"p1\">An&aacute;lisis de propiedades y permisos de archivos desde el entorno gr&aacute;fico</p>\r\n<p class=\"p1\">Introducci&oacute;n a las variables de entorno y su utilidad pr&aacute;ctica</p>\r\n<p class=\"p1\">Demostraci&oacute;n del proceso de arranque y an&aacute;lisis de los archivos de configuraci&oacute;n principales</p>\r\n<p class=\"p1\">Actividades pr&aacute;cticas: comparaci&oacute;n entre la estructura y gesti&oacute;n de Windows y Linux</p>', '', '<p>Pruebas objetivas&nbsp;(70 %)<br />Observaci&oacute;n directa y&nbsp;formaci&oacute;n entre iguales&nbsp;(30 %)</p>\r\n<p>Podr&aacute; requerirse entregar un resumen de la parte te&oacute;rica de la unidad hecho a mano, antes de la realizaci&oacute;n de la prueba objetiva, aplic&aacute;ndose la penalizaci&oacute;n/bonificaci&oacute;n que corresponda a la nota del examen seg&uacute;n la siguiente r&uacute;brica:<br /><br />No entregado: -1,00 puntos<br />Satisfactorio: +0,00 puntos<br />Supera las expectativas: +1,00 puntos (Siempre que la prueba objetiva obtenga al menos una calificaci&oacute;n de 4 puntos)</p>', '', '', 1, 1, 1, 1),
(53, 26, 6, 'Basic OS Management via GUI', 12, 2, 10, '<p class=\"p1\">Aborda las tareas fundamentales de gesti&oacute;n de un sistema operativo utilizando su interfaz gr&aacute;fica. El alumnado aprende a configurar y administrar entornos Windows y Linux en modo gr&aacute;fico, incluyendo la instalaci&oacute;n de sistemas en arranque dual, la gesti&oacute;n de programas, servicios y usuarios, as&iacute; como la configuraci&oacute;n de red, almacenamiento y dispositivos. Se introduce el uso de herramientas como el Administrador de discos, los paneles de control y los asistentes de configuraci&oacute;n, junto con operaciones cr&iacute;ticas como la recuperaci&oacute;n del arranque o la gesti&oacute;n de actualizaciones. Adem&aacute;s, se realiza un trabajo pr&aacute;ctico que consiste en elaborar un plan de instalaci&oacute;n completo con particiones, sistemas de archivos y aplicaciones base.</p>', '<p class=\"p1\">Esta unidad representa la transici&oacute;n entre la comprensi&oacute;n te&oacute;rica del sistema operativo y su gesti&oacute;n pr&aacute;ctica. Dentro del m&oacute;dulo <em>Sistemas Operativos Monousuario (SOM)</em>, proporciona al alumnado las competencias necesarias para realizar tareas reales de instalaci&oacute;n, configuraci&oacute;n y mantenimiento en entornos Windows y Linux utilizando herramientas gr&aacute;ficas. Dominar estas funciones permite asegurar la operatividad del sistema, resolver incidencias comunes y preparar la base para el trabajo m&aacute;s avanzado en l&iacute;nea de comandos que se abordar&aacute; en las unidades siguientes. Adem&aacute;s, fomenta la autonom&iacute;a t&eacute;cnica y la capacidad de an&aacute;lisis en contextos de configuraci&oacute;n y diagn&oacute;stico de sistemas.</p>', '', '<ul>\r\n<li>\r\n<p class=\"p1\">Opciones de arranque (Windows, Linux, GRUB)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Instalaci&oacute;n de sistemas operativos en arranque dual (<em>dual-boot</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Entrega evaluable: &ldquo;Plan de instalaci&oacute;n&rdquo; (particiones, sistemas de archivos, aplicaciones base)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Instalaci&oacute;n y gesti&oacute;n de programas</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Configuraci&oacute;n del sistema (paneles de control/asistentes de configuraci&oacute;n)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de servicios mediante GUI en Windows y Linux</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de usuarios</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Actualizaciones del sistema operativo</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Perif&eacute;ricos y controladores (<em>drivers</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de discos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Configuraci&oacute;n de red</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Recursos compartidos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Recuperaci&oacute;n del arranque</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">&nbsp;</p>', '<p class=\"p1\">Revisi&oacute;n de los sistemas de arranque y gestores (Windows, Linux, GRUB)</p>\r\n<p class=\"p1\">Pr&aacute;ctica de instalaci&oacute;n de sistemas operativos en modo <em>dual-boot</em></p>\r\n<p class=\"p1\">Elaboraci&oacute;n del &ldquo;Plan de instalaci&oacute;n&rdquo; (particiones, FS, aplicaciones base) como entrega evaluable</p>\r\n<p class=\"p1\">Instalaci&oacute;n y desinstalaci&oacute;n de programas mediante herramientas gr&aacute;ficas</p>\r\n<p class=\"p1\">Configuraci&oacute;n del sistema a trav&eacute;s de paneles de control y asistentes</p>\r\n<p class=\"p1\">Gesti&oacute;n de servicios en Windows y Linux desde la interfaz gr&aacute;fica</p>\r\n<p class=\"p1\">Creaci&oacute;n y administraci&oacute;n de usuarios locales</p>\r\n<p class=\"p1\">Aplicaci&oacute;n de actualizaciones del sistema y controladores</p>\r\n<p class=\"p1\">Gesti&oacute;n de discos, particiones y unidades</p>\r\n<p class=\"p1\">Configuraci&oacute;n de red y recursos compartidos</p>\r\n<p class=\"p1\">Simulaci&oacute;n de escenarios de recuperaci&oacute;n del arranque del sistema</p>', '', '<p>Pruebas objetivas&nbsp;(70 %)<br />Observaci&oacute;n directa y&nbsp;formaci&oacute;n entre iguales&nbsp;(30 %)</p>\r\n<p>Podr&aacute; requerirse&nbsp;entregar un resumen de la parte te&oacute;rica de la unidad hecho a mano, antes de la realizaci&oacute;n de la prueba objetiva, aplic&aacute;ndose la penalizaci&oacute;n/bonificaci&oacute;n que corresponda a la nota del examen seg&uacute;n la siguiente r&uacute;brica: <br /><br />No entregado: -1,00 puntos <br />Satisfactorio: +0,00 puntos <br />Supera las expectativas: +1,00 puntos (Siempre que la prueba objetiva obtenga al menos una calificaci&oacute;n de 4 puntos)<br /><br /><br /></p>', '', '', 1, 1, 1, 1),
(54, 26, 7, 'Advanced Management & Linux CLI', 24, 3, 25, '<p class=\"p1\">Se centra en la administraci&oacute;n avanzada de sistemas Linux mediante la l&iacute;nea de comandos (CLI). El alumnado aprende a manejar el entorno de consola para ejecutar tareas de gesti&oacute;n del sistema operativo de forma eficiente y profesional. Se trabajan los comandos fundamentales para manipular archivos, usuarios, permisos, procesos y servicios, as&iacute; como la edici&oacute;n de archivos de configuraci&oacute;n y la automatizaci&oacute;n de tareas con herramientas como <em>cron</em> o <em>systemd timers</em>. Adem&aacute;s, se abordan conceptos clave sobre monitorizaci&oacute;n y an&aacute;lisis del sistema mediante registros y trazas, reforzando una comprensi&oacute;n pr&aacute;ctica del funcionamiento interno de Linux.</p>', '<p class=\"p1\">La l&iacute;nea de comandos constituye una herramienta esencial en la administraci&oacute;n de sistemas, especialmente en entornos Linux, donde muchas operaciones avanzadas no pueden realizarse desde la interfaz gr&aacute;fica. En el m&oacute;dulo <em>Sistemas Operativos Monousuario (SOM)</em>, esta unidad proporciona al alumnado las competencias necesarias para desenvolverse con soltura en entornos profesionales, realizar tareas de mantenimiento y diagn&oacute;stico, y automatizar procesos de administraci&oacute;n. El dominio del CLI fomenta la autonom&iacute;a t&eacute;cnica, la precisi&oacute;n en la ejecuci&oacute;n de tareas y la comprensi&oacute;n profunda de la arquitectura del sistema operativo, preparando al estudiante para el trabajo real en entornos de producci&oacute;n.</p>', '', '<ul>\r\n<li>\r\n<p class=\"p1\">Introducci&oacute;n a la l&iacute;nea de comandos (CLI) y comandos de ayuda</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Comandos b&aacute;sicos y de prop&oacute;sito general</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de archivos y carpetas mediante CLI</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Edici&oacute;n de texto en CLI (archivos de configuraci&oacute;n)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de usuarios mediante CLI</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de permisos mediante CLI</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de procesos mediante CLI</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de servicios mediante CLI (<em>systemd</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de paquetes mediante CLI</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Compresi&oacute;n y descompresi&oacute;n mediante CLI</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Automatizaci&oacute;n de tareas (<em>cron</em>, <em>systemd timers</em>, <em>scripting</em> b&aacute;sico)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Registros y trazas del sistema (<em>journalctl</em>, <em>/var/log</em>)</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">&nbsp;</p>', '<p class=\"p1\">ntroducci&oacute;n al entorno CLI y comandos de ayuda</p>\r\n<p class=\"p1\">Pr&aacute;cticas guiadas:<br /><br />- Comandos b&aacute;sicos y de prop&oacute;sito general</p>\r\n<p class=\"p1\">- Gesti&oacute;n de archivos, carpetas y permisos desde la terminal</p>\r\n<p class=\"p1\">- Edici&oacute;n de archivos de configuraci&oacute;n mediante editores en l&iacute;nea de comandos (<em>nano</em>, <em>vi</em>)</p>\r\n<p class=\"p1\">- Gesti&oacute;n de usuarios, procesos y servicios con <em>systemd</em></p>\r\n<p class=\"p1\">- Uso de herramientas de gesti&oacute;n de paquetes (apt, dnf, etc.)</p>\r\n<p class=\"p1\">- Pr&aacute;cticas de compresi&oacute;n y descompresi&oacute;n desde CLI</p>\r\n<p class=\"p1\">- Automatizaci&oacute;n de tareas con <em>cron</em> y <em>systemd timers</em></p>', '', '<p>Pruebas objetivas&nbsp;(80 %)<br />Actividades en el aula (10 %)<br />Observaci&oacute;n directa y&nbsp;formaci&oacute;n entre iguales&nbsp;(10 %)</p>\r\n<p>&nbsp;</p>\r\n<p>Podr&aacute; requerirse&nbsp;entregar un resumen de la parte te&oacute;rica de la unidad hecho a mano, antes de la realizaci&oacute;n de la prueba objetiva, aplic&aacute;ndose la penalizaci&oacute;n/bonificaci&oacute;n que corresponda a la nota del examen seg&uacute;n la siguiente r&uacute;brica: <br /><br />No entregado: -1,00 puntos <br />Satisfactorio: +0,00 puntos <br />Supera las expectativas: +1,00 puntos (Siempre que la prueba objetiva obtenga al menos una calificaci&oacute;n de 4 puntos)<br /><br /><br /></p>', '', '', 1, 1, 1, 1),
(55, 26, 8, 'Advanced Management & Windows CLI', 18, 3, 15, '<p class=\"p1\">Introduce la administraci&oacute;n avanzada del sistema operativo Windows a trav&eacute;s de la l&iacute;nea de comandos, utilizando tanto CMD como PowerShell. El alumnado aprende a ejecutar y automatizar tareas administrativas sin depender de la interfaz gr&aacute;fica, incluyendo la gesti&oacute;n de archivos, usuarios, grupos, procesos, servicios y software. Se trabajan herramientas nativas para la programaci&oacute;n de tareas, la consulta del Registro de Windows y el an&aacute;lisis de registros de eventos del sistema. Adem&aacute;s, se presentan utilidades modernas como <em>winget</em> y los cmdlets de PowerShell, que ampl&iacute;an las capacidades de administraci&oacute;n y permiten realizar operaciones m&aacute;s eficientes y seguras.</p>', '<p class=\"p1\">Complementa la formaci&oacute;n al proporcionar al alumnado habilidades de administraci&oacute;n avanzadas en Windows desde la l&iacute;nea de comandos. Comprender y dominar CMD y PowerShell permite ejecutar tareas de mantenimiento, configuraci&oacute;n y automatizaci&oacute;n con mayor control y precisi&oacute;n, tal como se requiere en entornos profesionales. Adem&aacute;s, este enfoque potencia la capacidad anal&iacute;tica y la resoluci&oacute;n de problemas mediante el uso de herramientas de diagn&oacute;stico y registro, preparando al estudiante para gestionar sistemas Windows de forma t&eacute;cnica y aut&oacute;noma, m&aacute;s all&aacute; del uso de interfaces gr&aacute;ficas.</p>', '', '<ul>\r\n<li>\r\n<p class=\"p1\">Introducci&oacute;n a la l&iacute;nea de comandos (CMD/PowerShell) y comandos de ayuda</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Comandos b&aacute;sicos</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de archivos y carpetas mediante CLI</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de usuarios y grupos mediante CLI (<em>net user</em>, <em>PowerShell</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Gesti&oacute;n de procesos y servicios mediante CLI (<em>tasklist/taskkill</em>, <em>sc</em>, <em>Get-Service</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Instalaci&oacute;n y actualizaci&oacute;n de software mediante CLI (<em>winget</em>, <em>PowerShell</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Programaci&oacute;n de tareas (<em>schtasks</em>, <em>ScheduledJobs</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Informaci&oacute;n de configuraci&oacute;n (Registro, <em>msinfo32</em>, <em>Get-ItemProperty</em>)</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Registros de eventos (<em>Event Viewer</em>, <em>wevtutil</em>, <em>Get-WinEvent</em>)</p>\r\n</li>\r\n</ul>', '<p class=\"p1\">Introducci&oacute;n al entorno CMD, con ejemplos de ayuda y sintaxis<br /><br />Pr&aacute;cticas guiadas:</p>\r\n<p class=\"p1\">- Ejecuci&oacute;n de comandos b&aacute;sicos y exploraci&oacute;n de la CLI en Windows</p>\r\n<p class=\"p1\">- Gesti&oacute;n de archivos, carpetas y permisos mediante comandos</p>\r\n<p class=\"p1\">- Administraci&oacute;n de usuarios y grupos (<em>net user</em>, <em>Get-LocalUser</em>)</p>\r\n<p class=\"p1\">- Gesti&oacute;n de procesos y servicios mediante CLI (<em>tasklist</em>, <em>sc</em>, <em>Get-Service</em>)</p>\r\n<p class=\"p1\">- Instalaci&oacute;n y actualizaci&oacute;n de software con <em>winget</em></p>\r\n<p class=\"p1\">- Programaci&oacute;n de tareas con <em>schtasks</em> y <em>ScheduledJobs</em></p>\r\n<p class=\"p1\">- Consulta de informaci&oacute;n de configuraci&oacute;n (Registro, <em>msinfo32</em>, <em>Get-ItemProperty</em>)</p>\r\n<p class=\"p1\">- Visualizaci&oacute;n y filtrado de registros de eventos (<em>Event Viewer</em>, <em>wevtutil</em>, <em>Get-WinEvent</em>)</p>\r\n<p class=\"p1\"><br />Comparativa entre la administraci&oacute;n avanzada de Windows y Linux por CLI</p>', '', '<p>Pruebas objetivas&nbsp;(80 %)<br />Actividades en el aula (10 %)<br />Observaci&oacute;n directa y&nbsp;formaci&oacute;n entre iguales&nbsp;(10 %)</p>\r\n<p>Podr&aacute; requerirse&nbsp;entregar un resumen de la parte te&oacute;rica de la unidad hecho a mano, antes de la realizaci&oacute;n de la prueba objetiva, aplic&aacute;ndose la penalizaci&oacute;n/bonificaci&oacute;n que corresponda a la nota del examen seg&uacute;n la siguiente r&uacute;brica: <br /><br />No entregado: -1,00 puntos <br />Satisfactorio: +0,00 puntos <br />Supera las expectativas: +1,00 puntos (Siempre que la prueba objetiva obtenga al menos una calificaci&oacute;n de 4 puntos)<br /><br /><br /></p>', '', '', 1, 1, 1, 1),
(56, 26, 9, 'New-generation Operating Systems', 8, 3, 2, '<p class=\"p1\">Esta unidad explora las nuevas tendencias en el &aacute;mbito de los sistemas operativos, analizando c&oacute;mo la movilidad, la nube y la integraci&oacute;n entre dispositivos han transformado su dise&ntilde;o y uso. El alumnado estudia las caracter&iacute;sticas y particularidades de los sistemas operativos m&oacute;viles, como Android e iOS, as&iacute; como las soluciones basadas en la nube que permiten la ejecuci&oacute;n y sincronizaci&oacute;n de entornos personales sin depender completamente del hardware local. Tambi&eacute;n se aborda el caso de los sistemas h&iacute;bridos, como ChromeOS, que combinan componentes locales y servicios en la nube, ofreciendo una visi&oacute;n moderna de la evoluci&oacute;n del concepto de sistema operativo.</p>', '<p>Ampl&iacute;a la perspectiva del alumnado sobre los sistemas operativos m&aacute;s all&aacute; de los entornos tradicionales de escritorio, conectando los conocimientos adquiridos en el m&oacute;dulo Sistemas Operativos Monousuario (SOM) con las tecnolog&iacute;as emergentes del mercado. Comprender los sistemas m&oacute;viles, los entornos basados en la nube y los modelos h&iacute;bridos permite anticipar la direcci&oacute;n en la que evoluciona la inform&aacute;tica personal y profesional. Adem&aacute;s, fomenta la adaptaci&oacute;n a nuevas plataformas y la comprensi&oacute;n de conceptos como sincronizaci&oacute;n, virtualizaci&oacute;n ligera y gesti&oacute;n de recursos distribuidos, habilidades clave para los t&eacute;cnicos en sistemas en un entorno digital cada vez m&aacute;s diversificado.</p>', '', '<ul>\r\n<li>\r\n<p class=\"p1\">Sistemas operativos m&oacute;viles</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Sistemas operativos monousuario basados en la nube</p>\r\n</li>\r\n<li>\r\n<p class=\"p1\">Sistemas operativos h&iacute;bridos: ChromeOS</p>\r\n</li>\r\n</ul>\r\n<p class=\"p1\">&nbsp;</p>', '<p class=\"p1\">Exploraci&oacute;n de los principales sistemas operativos m&oacute;viles (Android, iOS)</p>\r\n<p class=\"p1\">An&aacute;lisis de sus caracter&iacute;sticas, gesti&oacute;n de recursos y ecosistema de aplicaciones</p>\r\n<p class=\"p1\">Presentaci&oacute;n de los sistemas operativos basados en la nube y su integraci&oacute;n con servicios online</p>\r\n<p class=\"p1\">Estudio de los sistemas h&iacute;bridos como ChromeOS: funcionamiento y arquitectura mixta</p>\r\n<p class=\"p1\">Debate sobre las ventajas y limitaciones de los sistemas de nueva generaci&oacute;n frente a los tradicionales</p>\r\n<p class=\"p1\">Actividad final: reflexi&oacute;n comparativa sobre el futuro de los sistemas operativos</p>', '', '<p>Prueba objetiva&nbsp;(90 %)<br />Observaci&oacute;n directa y&nbsp;formaci&oacute;n entre iguales&nbsp;(10 %)</p>\r\n<p>Podr&aacute; requerirse&nbsp;entregar un resumen de la parte te&oacute;rica de la unidad hecho a mano, antes de la realizaci&oacute;n de la prueba objetiva, aplic&aacute;ndose la penalizaci&oacute;n/bonificaci&oacute;n que corresponda a la nota del examen seg&uacute;n la siguiente r&uacute;brica: <br /><br />No entregado: -1,00 puntos <br />Satisfactorio: +0,00 puntos <br />Supera las expectativas: +1,00 puntos (Siempre que la prueba objetiva obtenga al menos una calificaci&oacute;n de 4 puntos)<br /><br /><br /></p>', '', '', 1, 1, 1, 1),
(57, 8, 1, 'Fundamentos de los sistemas operativos', 28, 1, 15, '<p>Esta unidad introduce los conceptos b&aacute;sicos de los sistemas operativos, su evoluci&oacute;n, componentes y funciones principales. Se estudia el papel que cumplen en la gesti&oacute;n de los recursos de hardware y software, as&iacute; como los tipos de sistemas operativos existentes y sus arquitecturas.</p>', '<p>Comprender los fundamentos de los sistemas operativos es esencial para cualquier profesional de la inform&aacute;tica. Permite entender c&oacute;mo interact&uacute;an los programas con el hardware, c&oacute;mo se gestionan los recursos del sistema y c&oacute;mo se garantiza la estabilidad y seguridad de los procesos.</p>', '', '<div class=\"page\" title=\"Page 10\">\r\n<div class=\"layoutArea\">\r\n<div class=\"column\">\r\n<ul>\r\n<li>Concepto del sistema operativo</li>\r\n<li>Historia y evoluci&oacute;n del sistema operativo.</li>\r\n<li>Estructura de un sistema informático.</li>\r\n<li>Arquitectura de un sistema operativo.</li>\r\n<li>Funciones de un sistema operativo.&nbsp;</li>\r\n<li>Principales gestiones del sistema operativo: procesos, memoria, archivos y E/S.</li>\r\n<li>Tipos de sistemas operativos.</li>\r\n<li>Tipos de aplicaciones.</li>\r\n<li>Licencias y tipos de licencias.</li>\r\n</ul>\r\n</div>\r\n</div>\r\n</div>', '<ul>\r\n<li>Concepto y funciones de un sistema operativo.</li>\r\n<li>Historia y evoluci&oacute;n de los sistemas operativos.</li>\r\n<li>Tipos de sistemas operativos (monousuario, multiusuario, monoproceso, multiproceso, etc.).</li>\r\n<li>Interacci&oacute;n entre hardware, sistema operativo y software de aplicaci&oacute;n.</li>\r\n<li>Componentes principales: kernel, shell, sistema de archivos, controladores.</li>\r\n<li>Gesti&oacute;n de procesos, hilos, algoritmos de prioridad entre procesos y comunicaci&oacute;n entre procesos.</li>\r\n<li>Gesti&oacute;n de memoria. Memoria virtual y segmentaci&oacute;n</li>\r\n<li>Gesti&oacute;n de sistema de archivos. Tipos y caracter&iacute;sticas de los sistemas de archivos.</li>\r\n<li>Gesti&oacute;n de entrada y salida.</li>\r\n</ul>', '', '<ul>\r\n<li>La evaluaci&oacute;n de cada unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para el mismo.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:&nbsp;</li>\r\n<ul>\r\n<li><strong>ejercicios de clase:&nbsp;</strong>ser&aacute;n tareas realizadas en el transcurso de clase destinadas a la comprensi&oacute;n de conceptos te&oacute;ricos y pr&aacute;cticos fundamentales.</li>\r\n<li><strong>cuestionarios</strong>: permiten la autoevaluaci&oacute;n por parte del alumno/a de los conceptos vistos en la unidad.</li>\r\n<li><strong>pr&aacute;cticas individuales y grupales</strong>: est&aacute;n orientadas a profundizar y facilitar en la adquisici&oacute;n de los conceptos y destrezas pr&aacute;cticas planteadas en la unidad. Algunas de estas actividades podr&aacute; requerir defensa presencial o exposici&oacute;n oral.</li>\r\n<li><strong>proyectos individuales y grupales:&nbsp;</strong>permiten trabajar los resultados de aprendizaje vistos en varias unidades de manera transversal. En este caso, se puede solicitar la defensa y exposici&oacute;n oral de manera presencial y/o a trav&eacute;s de un videotutorial o videoconferencia, si la profesora lo considera necesario.</li>\r\n<li><strong>pruebas objetivas</strong>: permiten la evaluaci&oacute;n de los resultados de aprendizaje trabajados en la unidad en una &uacute;nica prueba realizada en clase.</li>\r\n</ul>\r\n</ul>\r\n<ul>\r\n<li><strong>En caso de que en la unidad se incluya la realizaci&oacute;n de una prueba objetiva (examen y/o exposici&oacute;n de proyecto final), se aplicar&aacute; </strong>la baremaci&oacute;n siguiente en la puntuaci&oacute;n obtenida en la unidad, siempre y cuando se supere una calificaci&oacute;n m&iacute;nima de 5 en la prueba objetiva:</li>\r\n<ul>\r\n<li>60% prueba objetiva (presencial)</li>\r\n<li>40% pr&aacute;cticas obligatorias/proyectos/ejercicios en clase</li>\r\n</ul>\r\n</ul>\r\n<p><strong>Consideraciones sobre los instrumentos de evaluaci&oacute;n de la unidad:</strong></p>\r\n<ul>\r\n<li>En aquellas pr&aacute;cticas y/o proyectos que se realicen de manera grupal, la calificaci&oacute;n podr&aacute; contar con una&nbsp;<strong>puntuaci&oacute;n individual y colectiva</strong>&nbsp;que permita valorar tanto la aportaci&oacute;n individual de cada alumno como el resultado global obtenido por el grupo, para obtener la calificaci&oacute;n final.</li>\r\n<li>Se podr&aacute;&nbsp;<strong>penalizar&nbsp;la&nbsp;calificaci&oacute;n</strong>&nbsp;m&aacute;xima de las pr&aacute;cticas entregadas con retraso o entregadas para recuperar una pr&aacute;ctica suspendida.</li>\r\n<li>La profesora se&nbsp;<strong>reserva el derecho a convocar al alumno&nbsp;</strong>para en caso de duda, poder&nbsp;<strong>comprobar los conceptos evaluados en las pr&aacute;cticas, proyectos o ejercicios</strong>.</li>\r\n</ul>', '', '', 1, 1, 1, 1),
(58, 8, 2, 'Arranque e instalación de sistemas operativos. Introducción a la virtualización', 29, 1, 15, '<p>En esta unidad se aborda el proceso de instalaci&oacute;n y arranque de distintos sistemas operativos, as&iacute; como los conceptos de virtualizaci&oacute;n y su aplicaci&oacute;n en entornos de administraci&oacute;n de sistemas.</p>', '<p>La instalaci&oacute;n y configuraci&oacute;n adecuada de un sistema operativo es una habilidad fundamental. Adem&aacute;s, la virtualizaci&oacute;n es una tecnolog&iacute;a clave que permite optimizar recursos, realizar pruebas y administrar m&uacute;ltiples entornos de manera eficiente y segura.</p>', '', '<ul>\r\n<li class=\"p1\">Gestores de arranque.</li>\r\n<li class=\"p1\">Consideraciones previas a la instalaci&oacute;n de sistemas operativos libres y propietarios.</li>\r\n<li class=\"p1\">Instalaci&oacute;n de sistemas operativos. Requisitos, versiones y licencias.</li>\r\n<li class=\"p1\">Instalaci&oacute;n/desinstalaci&oacute;n de aplicaciones. Requisitos, versiones y licencias.</li>\r\n<li class=\"page\" title=\"Page 10\">\r\n<div class=\"layoutArea\">\r\n<div class=\"column\">\r\n<p>Actualización de sistemas operativos y aplicaciones.</p>\r\n</div>\r\n</div>\r\n</li>\r\n<li class=\"p1\">Estructura de directorios de sistemas operativos libres y propietarios.</li>\r\n<li class=\"p1\">B&uacute;squeda de informaci&oacute;n del sistema mediante comandos y herramientas gr&aacute;ficas.</li>\r\n<li class=\"p1\">Identificaci&oacute;n del software instalado mediante comandos y herramientas gr&aacute;ficas.</li>\r\n<li class=\"p1\">Gesti&oacute;n de la informaci&oacute;n del sistema. Rendimiento. Estad&iacute;sticas.</li>\r\n<li class=\"p1\">Montaje y desmontaje de dispositivos en sistemas operativos. Automatizaci&oacute;n.</li>\r\n<li class=\"p1\">Herramientas de administraci&oacute;n de discos.Particiones y vol&uacute;menes. Desfragmentaci&oacute;n y chequeo.</li>\r\n</ul>', '<ul>\r\n<li>Proceso de arranque del sistema operativo (BIOS/UEFI, bootloader, kernel).</li>\r\n<li>Particionado de discos y sistemas de archivos.</li>\r\n<li>Instalaci&oacute;n de sistemas operativos (Windows y Linux).</li>\r\n<li>Instalaci&oacute;n de sistema de arranque Dual</li>\r\n<li>Incorporaci&oacute;n de discos, formateo y particionado. Montaje de discos temporal y permanente</li>\r\n<li>Configuraci&oacute;n inicial y gesti&oacute;n de controladores.</li>\r\n<li>Concepto de virtualizaci&oacute;n: tipos, ventajas y desventajas.</li>\r\n<li>Herramientas de virtualizaci&oacute;n: VirtualBox, VMware, Hyper-V.</li>\r\n<li>Creaci&oacute;n y administraci&oacute;n de m&aacute;quinas virtuales.</li>\r\n</ul>', '', '<ul>\r\n<li>La evaluaci&oacute;n de cada unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para el mismo.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:&nbsp;</li>\r\n<ul>\r\n<li><strong>ejercicios de clase:&nbsp;</strong>ser&aacute;n tareas realizadas en el transcurso de clase destinadas a la comprensi&oacute;n de conceptos te&oacute;ricos y pr&aacute;cticos fundamentales.</li>\r\n<li><strong>cuestionarios</strong>: permiten la autoevaluaci&oacute;n por parte del alumno/a de los conceptos vistos en la unidad.</li>\r\n<li><strong>pr&aacute;cticas individuales y grupales</strong>: est&aacute;n orientadas a profundizar y facilitar en la adquisici&oacute;n de los conceptos y destrezas pr&aacute;cticas planteadas en la unidad. Algunas de estas actividades podr&aacute; requerir defensa presencial o exposici&oacute;n oral.</li>\r\n<li><strong>proyectos individuales y grupales:&nbsp;</strong>permiten trabajar los resultados de aprendizaje vistos en varias unidades de manera transversal. En este caso, se puede solicitar la defensa y exposici&oacute;n oral de manera presencial y/o a trav&eacute;s de un videotutorial o videoconferencia, si la profesora lo considera necesario.</li>\r\n<li><strong>pruebas objetivas</strong>: permiten la evaluaci&oacute;n de los resultados de aprendizaje trabajados en la unidad en una &uacute;nica prueba realizada en clase.</li>\r\n</ul>\r\n</ul>\r\n<ul>\r\n<li><strong>En caso de que en la unidad se incluya la realizaci&oacute;n de una prueba objetiva (examen y/o exposici&oacute;n de proyecto final), se aplicar&aacute; </strong>la baremaci&oacute;n siguiente en la puntuaci&oacute;n obtenida en la unidad, siempre y cuando se supere una calificaci&oacute;n m&iacute;nima de 5 en la prueba objetiva:</li>\r\n<ul>\r\n<li>60% prueba objetiva (presencial)</li>\r\n<li>40% pr&aacute;cticas obligatorias/proyectos/ejercicios en clase</li>\r\n</ul>\r\n</ul>\r\n<p><strong>Consideraciones sobre los instrumentos de evaluaci&oacute;n de la unidad:</strong></p>\r\n<ul>\r\n<li>En aquellas pr&aacute;cticas y/o proyectos que se realicen de manera grupal, la calificaci&oacute;n podr&aacute; contar con una&nbsp;<strong>puntuaci&oacute;n individual y colectiva</strong>&nbsp;que permita valorar tanto la aportaci&oacute;n individual de cada alumno como el resultado global obtenido por el grupo, para obtener la calificaci&oacute;n final.</li>\r\n<li>Se podr&aacute;&nbsp;<strong>penalizar&nbsp;la&nbsp;calificaci&oacute;n</strong>&nbsp;m&aacute;xima de las pr&aacute;cticas entregadas con retraso o entregadas para recuperar una pr&aacute;ctica suspendida.</li>\r\n<li>La profesora se&nbsp;<strong>reserva el derecho a convocar al alumno&nbsp;</strong>para en caso de duda, poder&nbsp;<strong>comprobar los conceptos evaluados en las pr&aacute;cticas, proyectos o ejercicios</strong>.</li>\r\n</ul>', '', '', 1, 1, 1, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(59, 8, 3, 'Introducción a sistemas GNU/Linux y Windows', 35, 1, 15, '<p>Esta unidad se centra en el conocimiento y manejo b&aacute;sico de los sistemas operativos m&aacute;s utilizados en entornos profesionales: GNU/Linux y Microsoft Windows. Se introducen sus caracter&iacute;sticas, estructuras de archivos, comandos b&aacute;sicos y entornos gr&aacute;ficos que nos permiten la configuraci&oacute;n inicial del sistema, de la red y de las cuentas y grupos de usuarios.&nbsp;</p>', '<p>En esta unidad se parte de los sistemas ya instalados y configurados para iniciar la administraci&oacute;n de los mismos con comandos e interfaz gr&aacute;fica en los entornos m&aacute;s empleados: Windows y Linux.</p>', '', '<div class=\"page\" title=\"Page 10\">\r\n<div class=\"layoutArea\">\r\n<div class=\"column\">\r\n<div class=\"page\" title=\"Page 10\">\r\n<div class=\"layoutArea\">\r\n<div class=\"column\">\r\n<ul>\r\n<li>Ficheros de inicio de sistemas operativos.</li>\r\n<li>\r\n<p>Registro del sistema.</p>\r\n</li>\r\n<li>\r\n<p>Actualización y mantenimiento de controladores de dispositivos.</p>\r\n</li>\r\n<li>Registro del sistema.</li>\r\n<li>Actualización y mantenimiento de controladores de dispositivos.</li>\r\n<li>Administración de usuarios y grupos locales.</li>\r\n<li>Usuarios y grupos predeterminados.</li>\r\n<li>Seguridad de cuentas de usuario.</li>\r\n<li>Seguridad de contraseñas.</li>\r\n<li>Administración de perfiles locales de usuario.</li>\r\n<li>Configuración del protocolo TCP/IP en un cliente de red.</li>\r\n<li>Configuración de la resolución de nombres.</li>\r\n<li>Ficheros de configuración de red.</li>\r\n</ul>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', '<ul>\r\n<li>Caracter&iacute;sticas generales de GNU/Linux y Windows.</li>\r\n<li>Estructura del sistema de archivos.</li>\r\n<li>Uso b&aacute;sico de la l&iacute;nea de comandos (CMD, PowerShell, Bash).</li>\r\n<li>Gesti&oacute;n de usuarios y permisos b&aacute;sicos.</li>\r\n<li>Navegaci&oacute;n, b&uacute;squeda y manipulaci&oacute;n de archivos y directorios.</li>\r\n<li>Instalaci&oacute;n y gesti&oacute;n b&aacute;sica de software.</li>\r\n<li>Configuraci&oacute;n de red est&aacute;tica y din&aacute;mica (DHCP) mediante entorno gr&aacute;fico y comandos.</li>\r\n<li>Diferencias y similitudes entre ambos sistemas.</li>\r\n</ul>', '', '<ul>\r\n<li>La evaluaci&oacute;n de cada unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para el mismo.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:&nbsp;</li>\r\n<ul>\r\n<li><strong>ejercicios de clase:&nbsp;</strong>ser&aacute;n tareas realizadas en el transcurso de clase destinadas a la comprensi&oacute;n de conceptos te&oacute;ricos y pr&aacute;cticos fundamentales.</li>\r\n<li><strong>cuestionarios</strong>: permiten la autoevaluaci&oacute;n por parte del alumno/a de los conceptos vistos en la unidad.</li>\r\n<li><strong>pr&aacute;cticas individuales y grupales</strong>: est&aacute;n orientadas a profundizar y facilitar en la adquisici&oacute;n de los conceptos y destrezas pr&aacute;cticas planteadas en la unidad. Algunas de estas actividades podr&aacute; requerir defensa presencial o exposici&oacute;n oral.</li>\r\n<li><strong>proyectos individuales y grupales:&nbsp;</strong>permiten trabajar los resultados de aprendizaje vistos en varias unidades de manera transversal. En este caso, se puede solicitar la defensa y exposici&oacute;n oral de manera presencial y/o a trav&eacute;s de un videotutorial o videoconferencia, si la profesora lo considera necesario.</li>\r\n<li><strong>pruebas objetivas</strong>: permiten la evaluaci&oacute;n de los resultados de aprendizaje trabajados en la unidad en una &uacute;nica prueba realizada en clase.</li>\r\n</ul>\r\n</ul>\r\n<ul>\r\n<li><strong>En caso de que en la unidad se incluya la realizaci&oacute;n de una prueba objetiva (examen y/o exposici&oacute;n de proyecto final), se aplicar&aacute; </strong>la baremaci&oacute;n siguiente en la puntuaci&oacute;n obtenida en la unidad, siempre y cuando se supere una calificaci&oacute;n m&iacute;nima de 5 en la prueba objetiva:</li>\r\n<ul>\r\n<li>60% prueba objetiva (presencial)</li>\r\n<li>40% pr&aacute;cticas obligatorias/proyectos/ejercicios en clase</li>\r\n</ul>\r\n</ul>\r\n<p><strong>Consideraciones sobre los instrumentos de evaluaci&oacute;n de la unidad:</strong></p>\r\n<ul>\r\n<li>En aquellas pr&aacute;cticas y/o proyectos que se realicen de manera grupal, la calificaci&oacute;n podr&aacute; contar con una&nbsp;<strong>puntuaci&oacute;n individual y colectiva</strong>&nbsp;que permita valorar tanto la aportaci&oacute;n individual de cada alumno como el resultado global obtenido por el grupo, para obtener la calificaci&oacute;n final.</li>\r\n<li>Se podr&aacute;&nbsp;<strong>penalizar&nbsp;la&nbsp;calificaci&oacute;n</strong>&nbsp;m&aacute;xima de las pr&aacute;cticas entregadas con retraso o entregadas para recuperar una pr&aacute;ctica suspendida.</li>\r\n<li>La profesora se&nbsp;<strong>reserva el derecho a convocar al alumno&nbsp;</strong>para en caso de duda, poder&nbsp;<strong>comprobar los conceptos evaluados en las pr&aacute;cticas, proyectos o ejercicios</strong>.</li>\r\n</ul>', '', '', 1, 1, 1, 1),
(60, 8, 4, 'Scripting', 35, 2, 15, '<p>En esta unidad se ense&ntilde;a a automatizar tareas mediante la creaci&oacute;n de scripts en los entornos Linux (bash) y Windows (PowerShell), permitiendo optimizar procesos de administraci&oacute;n y mantenimiento del sistema.</p>', '<p>El scripting es una herramienta esencial para los administradores de sistemas, ya que reduce errores humanos, agiliza operaciones repetitivas y mejora la eficiencia del mantenimiento del sistema.</p>', '', '<ul>\r\n<li class=\"p1\">Lenguaje de scripting</li>\r\n<li class=\"p1\">Gesti&oacute;n de usuarios, archivos y procesos mediante el uso de scripts</li>\r\n<li class=\"p1\">Registros de sucesos.</li>\r\n<li class=\"p1\">Monitorizaci&oacute;n de sucesos.</li>\r\n<li class=\"p1\">Gesti&oacute;n de aplicaciones, procesos y subprocesos.</li>\r\n<li class=\"p1\">Tipos de copias de seguridad.</li>\r\n<li class=\"p1\">Planes de copias de seguridad.</li>\r\n<li class=\"p1\">Programaci&oacute;n de copias de seguridad.</li>\r\n<li class=\"p1\">Copias de seguridad</li>\r\n</ul>', '<ul>\r\n<li>Concepto de scripting y automatizaci&oacute;n.</li>\r\n<li>Introducci&oacute;n a Bash y PowerShell.</li>\r\n<li>Estructura y sintaxis b&aacute;sica de scripts.</li>\r\n<li>Variables, condicionales y bucles.</li>\r\n<li>Manipulaci&oacute;n de archivos y directorios desde scripts.</li>\r\n<li>Programaci&oacute;n de tareas de monitorizaci&oacute;n automatizadas.</li>\r\n<li>Ejemplos pr&aacute;cticos de automatizaci&oacute;n de administraci&oacute;n.</li>\r\n</ul>', '', '<ul>\r\n<li>La evaluaci&oacute;n de cada unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para el mismo.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:&nbsp;</li>\r\n<ul>\r\n<li><strong>ejercicios de clase:&nbsp;</strong>ser&aacute;n tareas realizadas en el transcurso de clase destinadas a la comprensi&oacute;n de conceptos te&oacute;ricos y pr&aacute;cticos fundamentales.</li>\r\n<li><strong>cuestionarios</strong>: permiten la autoevaluaci&oacute;n por parte del alumno/a de los conceptos vistos en la unidad.</li>\r\n<li><strong>pr&aacute;cticas individuales y grupales</strong>: est&aacute;n orientadas a profundizar y facilitar en la adquisici&oacute;n de los conceptos y destrezas pr&aacute;cticas planteadas en la unidad. Algunas de estas actividades podr&aacute; requerir defensa presencial o exposici&oacute;n oral.</li>\r\n<li><strong>proyectos individuales y grupales:&nbsp;</strong>permiten trabajar los resultados de aprendizaje vistos en varias unidades de manera transversal. En este caso, se puede solicitar la defensa y exposici&oacute;n oral de manera presencial y/o a trav&eacute;s de un videotutorial o videoconferencia, si la profesora lo considera necesario.</li>\r\n<li><strong>pruebas objetivas</strong>: permiten la evaluaci&oacute;n de los resultados de aprendizaje trabajados en la unidad en una &uacute;nica prueba realizada en clase.</li>\r\n</ul>\r\n</ul>\r\n<ul>\r\n<li><strong>En caso de que en la unidad se incluya la realizaci&oacute;n de una prueba objetiva (examen y/o exposici&oacute;n de proyecto final), se aplicar&aacute; </strong>la baremaci&oacute;n siguiente en la puntuaci&oacute;n obtenida en la unidad, siempre y cuando se supere una calificaci&oacute;n m&iacute;nima de 5 en la prueba objetiva:</li>\r\n<ul>\r\n<li>60% prueba objetiva (presencial)</li>\r\n<li>40% pr&aacute;cticas obligatorias/proyectos/ejercicios en clase</li>\r\n</ul>\r\n</ul>\r\n<p><strong>Consideraciones sobre los instrumentos de evaluaci&oacute;n de la unidad:</strong></p>\r\n<ul>\r\n<li>En aquellas pr&aacute;cticas y/o proyectos que se realicen de manera grupal, la calificaci&oacute;n podr&aacute; contar con una&nbsp;<strong>puntuaci&oacute;n individual y colectiva</strong>&nbsp;que permita valorar tanto la aportaci&oacute;n individual de cada alumno como el resultado global obtenido por el grupo, para obtener la calificaci&oacute;n final.</li>\r\n<li>Se podr&aacute;&nbsp;<strong>penalizar&nbsp;la&nbsp;calificaci&oacute;n</strong>&nbsp;m&aacute;xima de las pr&aacute;cticas entregadas con retraso o entregadas para recuperar una pr&aacute;ctica suspendida.</li>\r\n<li>La profesora se&nbsp;<strong>reserva el derecho a convocar al alumno&nbsp;</strong>para en caso de duda, poder&nbsp;<strong>comprobar los conceptos evaluados en las pr&aacute;cticas, proyectos o ejercicios</strong>.</li>\r\n</ul>', '', '', 1, 1, 1, 1),
(64, 25, 1, 'Empresa y aplicaciones ofimáticas', 8, 1, 10, '<p>Este tema aborda los conocimientos básicos sobre la empresa y su funcionamiento, junto con el uso de herramientas ofimáticas esenciales en el entorno laboral.</p>', '<p>El objetivo principal es que el alumnado comprenda cómo se organiza una empresa, qué funciones cumplen sus diferentes departamentos y cómo las tecnologías informáticas apoyan la gestión empresarial, conociendo así, las diferentes aplicaciones y suites ofimáticas existentes.</p>', '', '<p>1. Conceto de software<br>2. Tipos de software<br>3. Suite o paquete ofimático<br>4. Licencias de software<br>5. Instalación</p>', '<ul>\r\n<li>Explicación de las diferentes aplicaciones y suites ofimáticas</li>\r\n<li>Explicación de la labor que permite el conocimiento de este tema realizar en la empresa (manual de usuario, charlas, instalación de aplicaciones, configuración de aplicaciones)</li>\r\n<li>Prácticas sobre instalación</li>\r\n<li>Prácticas sobre configuración</li>\r\n</ul>', '', '<ul>\r\n<li>Sesiones prácticas (30 %):<br>Grado de participación e implicación en sesiones de ejercicios prácticos.<br>Entrega de ejercicios y prácticas a través del Aules.</li>\r\n</ul>\r\n<ul>\r\n<li>Pruebas objetivas (70 %):<br>Desarrollo de prácticas en el ordenador.</li>\r\n</ul>\r\n<p>Para calcular la calificación final del módulo se ponderarán las diferentes unidades.</p>\r\n<p> </p>', '', '', 1, 1, 1, 1),
(65, 25, 2, 'Aplicaciones de procesador de texto', 40, 1, 20, '<p>En este tema se estudia el uso y las funciones del procesador de texto, una de las herramientas ofim&aacute;ticas m&aacute;s utilizadas en el &aacute;mbito profesional y acad&eacute;mico.</p>', '<p>El prop&oacute;sito de este tema es que el alumnado aprenda a crear, editar, dar formato y presentar documentos de manera profesional, eficiente y estructurada.&nbsp;El tema fomenta el trabajo ordenado, la presentaci&oacute;n cuidada y la precisi&oacute;n en la comunicaci&oacute;n escrita, habilidades fundamentales en cualquier entorno laboral o administrativo.</p>', '', '<ol>\r\n<li>Personalizar el entorno</li>\r\n<li>Formateo de caracteres, uso de diferentes tipos y tama&ntilde;os de fuente, diferentes sangr&iacute;as y alineaciones de p&aacute;rrafo.</li>\r\n<li>Inclusi&oacute;n de cabeceras y pies de p&aacute;gina.</li>\r\n<li>Inclusi&oacute;n de esquemas con vi&ntilde;etas y listas numeradas.</li>\r\n<li>Inclusi&oacute;n de columnas period&iacute;sticas y secciones.</li>\r\n<li>Tablas, im&aacute;genes, dibujos y organigramas.</li>\r\n<li>Cartas, sobres, etiquetas y combinar correspondencia.</li>\r\n<li>Creaci&oacute;n de plantillas y formularios</li>\r\n<li>Macros de automatizaci&oacute;n</li>\r\n</ol>', '<ul>\r\n<li>Cada uno de los contenidos se explica en un tema</li>\r\n<li>De cada tema se realizan las pr&aacute;cticas necesarias&nbsp;hasta llegar a consolidar los conocimientos explicados y adquirir la destreza suficiente para su posterior aplicaci&oacute;n en el mundo laboral</li>\r\n<li>Se comienza por el formato de texto</li>\r\n<li>Se realizan encabezados, pi&eacute;s de p&aacute;gina, y listas</li>\r\n<li>Se insertan tablas, im&aacute;genes, esquemas...</li>\r\n<li>Se realizan sobres, etiquetas y combinaci&oacute;n de correspondencia</li>\r\n<li>Se utilizan plantillas, formularios y macros</li>\r\n</ul>', '', '<ul>\r\n<li>Sesiones pr&aacute;cticas (30 %):<br />Grado de participaci&oacute;n e implicaci&oacute;n en sesiones de ejercicios pr&aacute;cticos.<br />Entrega de ejercicios y pr&aacute;cticas a trav&eacute;s del Aules.</li>\r\n</ul>\r\n<ul>\r\n<li>Pruebas objetivas (70 %):<br />Desarrollo de pr&aacute;cticas en el ordenador.</li>\r\n</ul>\r\n<p>Para calcular la calificaci&oacute;n final del m&oacute;dulo se ponderar&aacute;n las diferentes unidades.</p>\r\n<p>&nbsp;</p>', '', '', 1, 1, 1, 1),
(66, 25, 3, 'Aplicaciones de hoja de cálculo', 40, 1, 20, '<p>En este tema se estudia el manejo de las hojas de c&aacute;lculo, una herramienta ofim&aacute;tica esencial para el tratamiento y an&aacute;lisis de datos num&eacute;ricos.</p>', '<p>La finalidad&nbsp;es que el alumnado aprenda a organizar, calcular y representar informaci&oacute;n de manera eficiente mediante f&oacute;rmulas, funciones y gr&aacute;ficos.&nbsp;Este tema refuerza la capacidad anal&iacute;tica y la precisi&oacute;n en el manejo de datos, preparando al estudiante para utilizar las hojas de c&aacute;lculo en tareas administrativas, contables y t&eacute;cnicas dentro del entorno laboral.</p>', '', '<p>&nbsp;</p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">1. Personalizar el entorno</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">2. Identificar los tipos de datos manejados en una hoja de c&aacute;lculo</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">3. Formateo de celdas.</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">4. Aplicaci&oacute;n de formatos a celdas y hojas.</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">5. Trabajo con rangos (contiguos y no contiguos)</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">6. Introducci&oacute;n de f&oacute;rmulas.</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">7. Manejo de funciones.</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">8. Creaci&oacute;n de gr&aacute;ficos diversos utilizando los asistentes.</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">9. Modificaci&oacute;n de gr&aacute;ficos.</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">10. Creaci&oacute;n de plantillas</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">11. Macros.</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">12. Hojas importadas de otras aplicaciones.</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">13. Exportar hojas a formatos de otras aplicaciones de hoja de c&aacute;lculo.</span></span></p>\r\n<p style=\"margin-bottom: 0cm; font-weight: normal; line-height: 100%; padding-left: 30px;\" align=\"left\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\">14. Uso de la hoja de c&aacute;lculo como una base de datos (filtrado, ordenamiento, &hellip;)</span></span></p>\r\n<p>&nbsp;</p>', '<ul>\r\n<li>Se trabaja la creaci&oacute;n y gesti&oacute;n de libros y hojas de trabajo</li>\r\n<li>El formato de celdas y rangos</li>\r\n<li>El uso de f&oacute;rmulas b&aacute;sicas y funciones avanzadas</li>\r\n<li>La representaci&oacute;n gr&aacute;fica de datos</li>\r\n<li>Tambi&eacute;n se abordan aspectos como la protecci&oacute;n de datos, la automatizaci&oacute;n de tareas y la impresi&oacute;n profesional de documentos.</li>\r\n</ul>', '', '<ul>\r\n<li>Sesiones pr&aacute;cticas (30 %):<br />Grado de participaci&oacute;n e implicaci&oacute;n en sesiones de ejercicios pr&aacute;cticos.<br />Entrega de ejercicios y pr&aacute;cticas a trav&eacute;s del Aules.</li>\r\n</ul>\r\n<ul>\r\n<li>Pruebas objetivas (70 %):<br />Desarrollo de pr&aacute;cticas en el ordenador.</li>\r\n</ul>\r\n<p>Para calcular la calificaci&oacute;n final del m&oacute;dulo se ponderar&aacute;n las diferentes unidades.</p>\r\n<p>&nbsp;</p>', '', '', 1, 1, 1, 1),
(67, 25, 4, 'Bases de datos ofimáticas', 40, 1, 10, '<p>En este tema se estudia el uso de las bases de datos ofim&aacute;ticas, herramientas dise&ntilde;adas para almacenar, organizar y gestionar informaci&oacute;n de forma estructurada.</p>', '<p>El prop&oacute;sito de este tema es que el alumnado aprenda a crear, mantener y consultar bases de datos utilizando aplicaciones ofim&aacute;ticas como Microsoft Access o LibreOffice Base. Adem&aacute;s&nbsp;fomenta la organizaci&oacute;n, la precisi&oacute;n y la gesti&oacute;n eficiente de la informaci&oacute;n, habilidades fundamentales para el trabajo en entornos administrativos y tecnol&oacute;gicos.</p>', '', '<p><strong><span style=\"font-weight: normal;\">1. Organizaci&oacute;n de las bases de datos relacionales</span></strong></p>\r\n<p><strong><span style=\"font-weight: normal;\">2. Creaci&oacute;n y manejo de tablas</span></strong></p>\r\n<p><strong><span style=\"font-weight: normal;\">3. Creaci&oacute;n de campos clave</span></strong></p>\r\n<p><strong><span style=\"font-weight: normal;\">4. Creaci&oacute;n y edici&oacute;n de &iacute;ndices</span></strong></p>\r\n<p><strong><span style=\"font-weight: normal;\">5. Consultas, formularios e informes</span></strong></p>\r\n<p><strong><span style=\"font-weight: normal;\">6. Herramientas m&aacute;s &uacute;tiles</span></strong></p>\r\n<p>&nbsp;</p>\r\n<p style=\"line-height: 150%; padding-left: 30px;\"><span style=\"font-family: Arial,sans-serif;\"><span style=\"font-size: medium;\"><strong><span style=\"font-weight: normal;\">&nbsp;</span></strong></span></span></p>', '<ul>\r\n<li>En primer lugar, se abordan los conceptos b&aacute;sicos de bases de datos relacionales, como tablas, campos, registros y relaciones</li>\r\n<li>Despu&eacute;s se estudia el dise&ntilde;o de formularios, consultas e informes</li>\r\n<li>Tambi&eacute;n se ense&ntilde;a a introducir, filtrar y ordenar datos, y a automatizar tareas administrativas mediante el uso de asistentes o funciones integradas</li>\r\n</ul>\r\n<p>&nbsp;Se van explicando todos estos conceptos y posteriormente se aplican por medio de pr&aacute;cticas, creando para ello, bases de datos,&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;estableciendo sus relaciones, realizando consultas, formularios e informes.</p>', '', '<ul>\r\n<li>Sesiones pr&aacute;cticas (30 %):<br />Grado de participaci&oacute;n e implicaci&oacute;n en sesiones de ejercicios pr&aacute;cticos.<br />Entrega de ejercicios y pr&aacute;cticas a trav&eacute;s del Aules.</li>\r\n</ul>\r\n<ul>\r\n<li>Pruebas objetivas (70 %):<br />Desarrollo de pr&aacute;cticas en el ordenador.</li>\r\n</ul>\r\n<p>Para calcular la calificaci&oacute;n final del m&oacute;dulo se ponderar&aacute;n las diferentes unidades.</p>\r\n<p>&nbsp;</p>', '', '', 1, 1, 1, 1),
(68, 25, 5, 'Aplicaciones de presentaciones', 40, 2, 10, '<p>En este tema se estudia el uso de las aplicaciones de presentaciones, herramientas ofim&aacute;ticas destinadas a dise&ntilde;ar y exponer informaci&oacute;n visualmente de forma clara y atractiva. Adem&aacute;s, potencia la creatividad, la comunicaci&oacute;n y el dominio de herramientas digitales, fundamentales para transmitir ideas de forma profesional y efectiva.</p>', '<p>La finalidad, es que el alumnado aprenda a crear presentaciones profesionales utilizando programas como Microsoft PowerPoint, LibreOffice Impress o equivalentes en l&iacute;nea.</p>', '', '<p>1. Personalizar el entorno<br>2. Identificar los elementos de una aplicaci&oacute;n de gesti&oacute;n de presentaciones: diapositivas, tipos de presentaciones<br>3. Identificar los tipos de vista asociados a una presentaci&oacute;n<br>4. Dise&ntilde;o de una presentaci&oacute;n utilizando plantillas predise&ntilde;adas<br>5. Dise&ntilde;o de una presentaci&oacute;n sin plantillas</p>', '<ul>\r\n<li>Se comienza explicando el entorno de trabajo y toda su potencial.</li>\r\n<li>Posteriormente se proponen diversas pr&aacute;cticas para afianzar las siguientes actividades:\r\n<ul>\r\n<li>Se trabaja la creaci&oacute;n y estructuraci&oacute;n de diapositivas</li>\r\n<li>La inserci&oacute;n de texto, im&aacute;genes, gr&aacute;ficos, tablas y elementos multimedia</li>\r\n<li>El uso de animaciones, transiciones y plantillas.</li>\r\n<li>Se ense&ntilde;a a adaptar el dise&ntilde;o al p&uacute;blico y al objetivo de la exposici&oacute;n, y a exportar o presentar el trabajo en distintos formatos.</li>\r\n</ul>\r\n</li>\r\n</ul>', '', '<ul>\r\n<li>Sesiones pr&aacute;cticas (30 %):<br>Grado de participaci&oacute;n e implicaci&oacute;n en sesiones de ejercicios pr&aacute;cticos.<br>Entrega de ejercicios y pr&aacute;cticas a trav&eacute;s del Aules.</li>\r\n</ul>\r\n<ul>\r\n<li>Pruebas objetivas (70 %):<br>Desarrollo de pr&aacute;cticas en el ordenador.</li>\r\n</ul>\r\n<p>Para calcular la calificaci&oacute;n final del m&oacute;dulo se ponderar&aacute;n las diferentes unidades.</p>\r\n<p>&nbsp;</p>', '', '', 1, 1, 1, 1),
(69, 25, 6, 'Edición de Imagen digital', 30, 2, 10, '<p>En este tema se estudia el uso de las aplicaciones de edici&oacute;n de imagen digital, herramientas que permiten crear, modificar y mejorar im&aacute;genes para distintos fines profesionales, educativos o personales.</p>', '<p>La finalidad de este tema, es que el alumnado aprenda a manejar programas de edici&oacute;n gr&aacute;fica como GIMP, Photoshop u otros equivalentes, aplicando t&eacute;cnicas b&aacute;sicas y avanzadas de retoque y composici&oacute;n.Tambi&eacute;n nos ayuda a fomentar la creatividad, la precisi&oacute;n t&eacute;cnica y el dominio de herramientas gr&aacute;ficas, esenciales en la comunicaci&oacute;n visual y en el entorno inform&aacute;tico actual.</p>', '', '<p>1. Trabajo b&aacute;sico con im&aacute;genes digitales</p>\r\n<p>2. Selecciones y efectos</p>\r\n<p>3. El men&uacute; de imagen</p>\r\n<p>4. Efectos sobre im&aacute;genes</p>\r\n<p>5. Imagen vectorial</p>', '<ul>\r\n<li>Se trabajan aspectos como la resoluci&oacute;n y el formato de imagen, el uso de capas y selecciones</li>\r\n<li>El ajuste de color, brillo y contraste</li>\r\n<li>La inserci&oacute;n de textos y efectos especiales</li>\r\n<li>Se ense&ntilde;a a optimizar im&aacute;genes para distintos soportes (web, impresi&oacute;n o presentaciones) y a respetar los derechos de autor y licencias de uso.</li>\r\n</ul>', '', '<ul>\r\n<li>Sesiones pr&aacute;cticas (30 %):<br />Grado de participaci&oacute;n e implicaci&oacute;n en sesiones de ejercicios pr&aacute;cticos.<br />Entrega de ejercicios y pr&aacute;cticas a trav&eacute;s del Aules.</li>\r\n</ul>\r\n<ul>\r\n<li>Pruebas objetivas (70 %):<br />Desarrollo de pr&aacute;cticas en el ordenador.</li>\r\n</ul>\r\n<p>Para calcular la calificaci&oacute;n final del m&oacute;dulo se ponderar&aacute;n las diferentes unidades.</p>\r\n<p>&nbsp;</p>', '', '', 1, 1, 1, 1),
(70, 25, 7, 'Edición de vídeo digital', 24, 2, 10, '<p>En este tema se estudia el uso de las aplicaciones de edici&oacute;n de v&iacute;deo digital, herramientas que permiten crear, modificar y montar producciones audiovisuales combinando im&aacute;genes, sonido, texto y efectos</p>', '<p>El objetivo final, es que el alumnado aprenda a editar v&iacute;deos de forma t&eacute;cnica y creativa, utilizando programas como OpenShot, DaVinci Resolve, Adobe Premiere o equivalentes de software libre.&nbsp;Este tema potencia la creatividad, la planificaci&oacute;n y el dominio de herramientas digitales, habilidades esenciales para la creaci&oacute;n de contenidos visuales en entornos educativos y profesionales.</p>', '', '<p>1. Formatos de v&iacute;deo</p>\r\n<p>2. Manipulaci&oacute;n de la l&iacute;nea de tiempo</p>\r\n<p>3. Selecci&oacute;n de escenas y transiciones</p>\r\n<p>4. Introducci&oacute;n de t&iacute;tulos y audio</p>\r\n<p>5. Creaci&oacute;n y grabaci&oacute;n de videos</p>\r\n<p>6. Importaci&oacute;n y exportaci&oacute;n de v&iacute;deos</p>', '<ul>\r\n<li>Comenzaremos trabajando conceptos como la captura e importaci&oacute;n de material audiovisual, la l&iacute;nea de tiempo y el montaje de clips</li>\r\n<li>Continuaremos con la inserci&oacute;n de transiciones, efectos, t&iacute;tulos y audio</li>\r\n<li>Tambi&eacute;n se trabajar&aacute; la exportaci&oacute;n en distintos formatos y calidades</li>\r\n<li>Por &uacute;ltimo abordaremos asuntos tales como, la organizaci&oacute;n de proyectos y el uso responsable de recursos multimedia respetando derechos de autor.</li>\r\n</ul>\r\n<p>&nbsp; &nbsp;El tema se llevar&aacute; a cabo de forma eminentemente pr&aacute;ctica.</p>', '', '<ul>\r\n<li>Sesiones pr&aacute;cticas (30 %):<br />Grado de participaci&oacute;n e implicaci&oacute;n en sesiones de ejercicios pr&aacute;cticos.<br />Entrega de ejercicios y pr&aacute;cticas a trav&eacute;s del Aules.</li>\r\n</ul>\r\n<ul>\r\n<li>Pruebas objetivas (70 %):<br />Desarrollo de pr&aacute;cticas en el ordenador.</li>\r\n</ul>\r\n<p>Para calcular la calificaci&oacute;n final del m&oacute;dulo se ponderar&aacute;n las diferentes unidades.</p>\r\n<p>&nbsp;</p>', '', '', 1, 1, 1, 1),
(71, 25, 8, 'Correo electrónico y agenda', 11, 2, 10, '<p>En este tema se estudia el uso de las aplicaciones de correo electr&oacute;nico y gesti&oacute;n de agenda, herramientas fundamentales para la comunicaci&oacute;n y organizaci&oacute;n del trabajo en entornos profesionales.</p>', '<p>El&nbsp;prop&oacute;sito del tema, es que el alumnado aprenda a enviar, recibir y gestionar mensajes electr&oacute;nicos, as&iacute; como a planificar tareas y citas mediante calendarios digitales.&nbsp;En &eacute;l se&nbsp;fomenta la organizaci&oacute;n, la responsabilidad y la comunicaci&oacute;n efectiva, competencias clave en el entorno laboral y administrativo moderno.</p>', '', '<p>1. Entorno de trabajo: configuraci&oacute;n y personalizaci&oacute;n</p>\r\n<p>2. Plantillas y firmas corporativas</p>\r\n<p>3. Foros de noticias (news)</p>\r\n<p>4. Libreta de direcciones</p>\r\n<p>5. Gesti&oacute;n de correos</p>\r\n<p>6. Gesti&oacute;n de la agenda</p>', '<ul>\r\n<li>Se comenzar&aacute; explicando algunos elementos de configuraci&oacute;n de gmail y outlook</li>\r\n<li>Se&nbsp;continuar&aacute; trabajando aspectos como la configuraci&oacute;n de cuentas de correo, la organizaci&oacute;n de bandejas y carpetas</li>\r\n<li>A continuaci&oacute;n tocaremos el tema del uso de firmas electr&oacute;nicas y archivos adjuntos</li>\r\n<li>Se comentar&aacute;n y tendr&aacute;n en cuenta las normas de comunicaci&oacute;n digital profesional</li>\r\n<li>Tambi&eacute;n se ense&ntilde;a a utilizar agendas electr&oacute;nicas para gestionar contactos, eventos, recordatorios y reuniones compartidas</li>\r\n</ul>', '', '<ul>\r\n<li>Sesiones pr&aacute;cticas (30 %):<br />Grado de participaci&oacute;n e implicaci&oacute;n en sesiones de ejercicios pr&aacute;cticos.<br />Entrega de ejercicios y pr&aacute;cticas a trav&eacute;s del Aules.</li>\r\n</ul>\r\n<ul>\r\n<li>Pruebas objetivas (70 %):<br />Desarrollo de pr&aacute;cticas en el ordenador.</li>\r\n</ul>\r\n<p>Para calcular la calificaci&oacute;n final del m&oacute;dulo se ponderar&aacute;n las diferentes unidades.</p>\r\n<p>&nbsp;</p>', '', '', 1, 1, 1, 1),
(72, 112, 1, 'Herramientas de taller de reparación', 35, 1, 8, '<p>En esta unidad vamos a ver:</p>\r\n<ul>\r\n<li>Conocer los diferentes tipos de herramientas manuales y el&eacute;ctricas que existen en el mercado destinados a la reparaci&oacute;n de equipos.</li>\r\n<li>Utilizar con seguridad las herramientas en cada caso.</li>\r\n<li>Utilizar un protocolo de desensamblado y ensamblado de equipos.</li>\r\n<li>Ensamblar y desensamblar equipos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>', '<p>Es necesario que el alumnado conozca las diferentes herramientas, asi como su utilizaci&oacute;n con seguridad. Conocer la forma de utilizaci&oacute;n de cada una de ellas.</p>', '', '<ul style=\"list-style-type: circle;\">\r\n<li>Destornilladores. Manuales y el&eacute;ctricos. Tipos de cabeza.</li>\r\n<li>Herramientas tipo llave. Alicates y sus tipos.</li>\r\n<li>Pinzas. Tijeras. Limas.</li>\r\n<li>Tornillo de banco. Lupa-flexo.</li>\r\n<li>Herramientas de medida: Flex&oacute;metro.</li>\r\n<li>Calibre. Micr&oacute;metro. Taladro.</li>\r\n<li>Brocas.</li>\r\n<li>Ensamblado y desensamblado de equipos.</li>\r\n</ul>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Los alumnos iran leyendo uno a uno un apartado del tema y a continuaci&oacute;n los explicar&eacute; poniendo ejemplos para su f&aacute;cil comprensi&oacute;n.</li>\r\n<li>Una vez terminado el tema haran un resumen de &eacute;ste.</li>\r\n<li>Realizaran el ejercicio tipo test del final del tema.</li>\r\n<li>Realizaran los ejercicios correspondientes al tema.</li>\r\n</ul>\r\n<p>Cada alumno realizar&aacute; todas las tareas anteriores en su libreta de la asignatura.</p>', '<p>Aula de inform&aacute;tica:</p>\r\n<ul>\r\n<li>Ordenadores conectados en red. El aula deber&aacute; disponer de al menos del suficiente n&uacute;mero de ordenadores para que no haya m&aacute;s de dos alumnos por puesto de trabajo, aunque es recomendable que cada alumno tenga su ordenador.</li>\r\n<li>Pizarra y altavoces</li>\r\n<li>Ca&ntilde;&oacute;n para mostrar la salida del ordenador del profesor a los alumnos.</li>\r\n<li>Ordenador-servidor conectado al ca&ntilde;&oacute;n.</li>\r\n<li>Conexi&oacute;n a Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Taller:</p>\r\n<ul>\r\n<li>Ordenadores antiguos.</li>\r\n<li>Electrodom&eacute;sticos para desmontar</li>\r\n<li>Componentes sueltos.</li>\r\n<li>Herramientas de taller.</li>\r\n<li>Material de limpieza de componentes.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>En cuanto al software a utilizar:</p>\r\n<ul>\r\n<li>Sistemas operativos Microsoft Windows, GNU/Linux</li>\r\n<li>Libre Office</li>\r\n<li>Programas de simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Libro de texto &ldquo;Equipos El&eacute;ctricos y electr&oacute;nicos&rdquo;. formaci&oacute;n Profesional B&aacute;sica,</p>\r\n<p>Juan Carlos Martin. Editorial Editex&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Diversos recursos de Internet.</p>', '<ol>\r\n<li>Observaci&oacute;n directa alumno/a: motivaci&oacute;n, inter&eacute;s, actitudes, comportamiento, asistencia, etc.</li>\r\n<li>Participaci&oacute;n en clase: intervenciones sobre actividades y ejercicios propuestos, valorando su dedicaci&oacute;n e inter&eacute;s.</li>\r\n<li>Realizaci&oacute;n de actividades individuales y grupales</li>\r\n<li>Prueba escrita al final de la unidad</li>\r\n</ol>', '<p>Esta es una de las unidades m&aacute;s importantes, ya que, con ella el alumno se iniciar&aacute; en el conocimiento de las diferentes herramientas que se puede encontrar en un taller de reparaci&oacute;n.</p>\r\n<p>El profesor har&aacute; una exposici&oacute;n te&oacute;rico-pr&aacute;ctica de la unidad, en un aula-taller, dotada de las herramientas y materiales necesarios para el desarrollo pr&aacute;ctico del m&oacute;dulo.</p>\r\n<p>Se describir&aacute;n las diferentes herramientas. Se debe insistir en la correcta utilizaci&oacute;n de &eacute;stas. Se utilizaran los elementos de seguridad necesarios para ello.</p>\r\n<p>El alumno realizar&aacute;, de forma individual o en grupo, el eval&uacute;o mi aprendizaje, la Pr&aacute;ctica Profesional resuelta y los Retos profesionales correspondientes.</p>\r\n<p>Todas las actividades se realizar&aacute;n en un aula-taller dotada de bancos de trabajo.</p>\r\n<p>Posteriormente, resolver&aacute; el cuestionario de la p&aacute;gina &ldquo;Eval&uacute;o mis conocimientos&rdquo; para afianzar los contenidos trabajados a lo largo de la unidad</p>', '', 1, 0, 0, 1),
(73, 116, 1, 'Implantación de Sistemas Operativos', 18, 1, 15, '<p>El objetivo de esta unidad es que el alumnado conozca los diferentes tipos de software, sus licencias y finalidad. Adem&aacute;s, deber&aacute;n identificar los principales sistemas operativos disponibles en la actualidad as&iacute; como comprender su proceso de instalaci&oacute;n.</p>', '<p>Esta unidad es de extrema importancia ya que supondr&aacute; una introducci&oacute;n a los diferentes sistemas operativos con los que se trabajar&aacute; durante&nbsp;todo el curso y adem&aacute;s les servir&aacute; de repaso a los contenidos que vieron en primer curso. Tambi&eacute;n la unidad permite evaluar de forma sencilla el nivel de cada estudiante y su relaci&oacute;n con la inform&aacute;tica.</p>', '<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>', '<ol>\r\n<li>El software.</li>\r\n<li>Licencias de software.</li>\r\n<li>El sistema operativo.</li>\r\n<li>Virtualizaci&oacute;n.</li>\r\n<li>Preparaci&oacute;n de la instalaci&oacute;n.</li>\r\n<li>Instalaci&oacute;n del SO Windows 10.</li>\r\n<li>Instalaci&oacute;n del SO Ubuntu.</li>\r\n<li>Postinstalaci&oacute;n del sistema.</li>\r\n</ol>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n de los diferentes tipos de software y sus funciones</li>\r\n<li>Explicaci&oacute;n de las licencias con ejemplos reales de su uso en el sector</li>\r\n<li>Explicaci&oacute;n y virtualizaci&oacute;n de un sistema operativo basado en Linux</li>\r\n<li>Explicaci&oacute;n y virtualizaci&oacute;n de un sistema operativo basado en Windows</li>\r\n<li>Configuraci&oacute;n post-instalacion de los diferentes sistemas operativos</li>\r\n<li>Realizaci&oacute;n de actividades de consolidaci&oacute;n propuestas por el libro de la asignatura</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>', '', '<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>', '', '', 0, 1, 1, 1),
(74, 116, 2, 'Sistema Operativo Windows', 26, 1, 10, '<p>El objetivo de esta unidad es que el alumnado profundice en el uso del sistema operativo Windows y sus diferentes posibilidades de configuraci&oacute;n y uso. Deber&aacute; de ser capaz de realizar operaciones b&aacute;sicas de administraci&oacute;n como la gesti&oacute;n de usuarios, ficheros y recursos del sistema.</p>', '<p>Esta unidad es importante, ya que, les permitir&aacute; conocer en profundidad uno de los sistemas operativos m&aacute;s utilizados del mundo y conocer en detalle todos sus trucos y bunas pr&aacute;cticas a la hora de usarlo y configurarlo.</p>', '<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>', '<ol>\r\n<li>Versiones de Windows.</li>\r\n<li>El escritorio.</li>\r\n<li>Las ventanas.</li>\r\n<li>Los archivos y carpetas.</li>\r\n<li>Las unidades.</li>\r\n<li>Administraci&oacute;n b&aacute;sica del sistema.</li>\r\n<li>Los permisos.</li>\r\n<li>Compartir en Windows.</li>\r\n<li>Herramientas administrativas.</li>\r\n<li>Hotkeys.</li>\r\n</ol>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n del escritorio de Windows y las diferentes opciones de ventanas.</li>\r\n<li>Explicaci&oacute;n de las operaciones de ficheros y c&oacute;mo trabajan en disco cada seg&uacute;n las que se apliquen.</li>\r\n<li>Uso de diferentes unidades dentro del sistema operativo, manejando su sistema de ficheros y c&oacute;mo administrarlas.</li>\r\n<li>Gesti&oacute;n de permisos dentro del sistema de ficheros de Windows.</li>\r\n<li>Uso de las principales herramientas administrativas en la gesti&oacute;n de controladores.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>', '', '<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>', '', '', 0, 1, 1, 1),
(75, 116, 3, 'Sistema Operativo Linux', 32, 1, 10, '<p>El objetivo de esta unidad es que el alumnado aprenda el uso de un sistema operativo Linux y sus diferentes posibilidades de configuraci&oacute;n y uso. Deber&aacute; de ser capaz de realizar operaciones b&aacute;sicas de administraci&oacute;n como la gesti&oacute;n de usuarios, ficheros y recursos del sistema. Tambi&eacute;n se ense&ntilde;ar&aacute;n nociones b&aacute;sicas de scripting, ya que en este sistema son muy usados y m&aacute;s desde un punto de vista de administraci&oacute;n.</p>', '<p>Esta unidad es importante, ya que, los sistemas operativos Linux est&aacute;n presentes en el 90% de los servidores del mundo, por este motivo han de conocer las nociones b&aacute;sicas para poder defenderse ante la gesti&oacute;n de este tipo de sistemas en un entorno profesional.</p>', '<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>', '<ol>\r\n<li>Sistemas operativos Linux.</li>\r\n<li>El entorno de trabajo de Ubuntu.</li>\r\n<li>Las ventanas.</li>\r\n<li>Los archivos y carpetas.</li>\r\n<li>Las unidades.</li>\r\n<li>Administraci&oacute;n b&aacute;sica.</li>\r\n<li>Los permisos.</li>\r\n<li>Compartir en Ubuntu.</li>\r\n</ol>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n de los escritorios en Linux y la realizaci&oacute;n de tareas b&aacute;sicas en la distribuci&oacute;n Ubuntu.</li>\r\n<li>Explicaci&oacute;n de las operaciones de ficheros y c&oacute;mo trabajan en disco cada seg&uacute;n las que se apliquen.</li>\r\n<li>Uso de las unidades dentro del sistema operativo y c&oacute;mo gestionarlas.</li>\r\n<li>Gesti&oacute;n de permisos dentro del sistema de ficheros de Linux.</li>\r\n<li>Configuraci&oacute;n de diferentes servicios dentro de Linux mediante interfaz y terminal.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>', '', '<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>', '', '', 0, 1, 1, 1),
(76, 116, 4, 'Sistemas Operativos en Red', 24, 1, 15, '<p>El objetivo de esta unidad es que el alumnado aprenda los diferentes tipos de redes de las que puede hacer uso un ordenador, especialmente en un entorno empresarial o de oficina. Se profundizar&aacute; en las principales topolog&iacute;as de red y los diferentes servicios que se pueden utilizar en estas.</p>', '<p>Esta unidad es importante, ya que, hoy en d&iacute;a Internet es el centro neur&aacute;lgico de cualquier actividad industrial, por tanto es necesario que el alumnado adquiera nociones b&aacute;sicas del funcionamiento de las redes en diferentes escenarios.</p>', '<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>', '<ol>\r\n<li>Red de comunicaci&oacute;n o datos.</li>\r\n<li>Tipos de redes: clasificaci&oacute;n.</li>\r\n<li>Topolog&iacute;as de red.</li>\r\n<li>Configuraciones l&oacute;gicas de red.</li>\r\n<li>Redes inal&aacute;mbricas.</li>\r\n<li>Impresoras en red.</li>\r\n</ol>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n de los principales usos de las redes en escenarios reales.</li>\r\n<li>Evaluaci&oacute;n del uso de los diferentes tipos de redes seg&uacute;n el entorno.</li>\r\n<li>Confecci&oacute;n de redes en simuladores reales para realizar pruebas de conexi&oacute;n.</li>\r\n<li>Compartici&oacute;n de recursos en redes locales desde diferentes sistemas operativos.</li>\r\n<li>Confecci&oacute;n de manuales de usuario para la configuraci&oacute;n.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>', '', '<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>', '', '', 0, 1, 1, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(77, 116, 5, 'El procesador de texto', 60, 2, 20, '<p>El objetivo de esta unidad es que el alumnado aprenda nociones b&aacute;sicas de ofim&aacute;tica, concretamente la elaboraci&oacute;n de documentos de texto haciendo uso de los procesadores de texto m&aacute;s habituales. Deber&aacute;n de elaborar estos documentos con unos m&iacute;nimos de presentaci&oacute;n y estilo que doten de profesionalidad a sus trabajos. &nbsp;</p>', '<p>Esta unidad es importante, ya que, hoy en d&iacute;a en cualquier trabajo en el que se utilice un ordenador, es necesario la creaci&oacute;n, elaboraci&oacute;n y edici&oacute;n de documentos de texto, por este motivo cualquier persona ha de poseer unos conocimientos m&iacute;nimos de la materia.</p>', '<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>', '<ol>\r\n<li>El procesador de texto.</li>\r\n<li>La ventana de Word 2016.</li>\r\n<li>Operaciones sobre documentos.</li>\r\n<li>Partes del documento.</li>\r\n<li>Visualizar el documento.</li>\r\n<li>Acciones b&aacute;sicas sobre el contenido.</li>\r\n<li>Formato de la p&aacute;gina.</li>\r\n<li>Formato de la fuente</li>\r\n<li>Formato del p&aacute;rrafo.</li>\r\n<li>Tablas.</li>\r\n<li>Ilustraciones.</li>\r\n<li>Objetos de texto.</li>\r\n<li>Revisi&oacute;n del texto.</li>\r\n</ol>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n de las diferentes funcionalidades de un software de ofim&aacute;tica.</li>\r\n<li>Explicaci&oacute;n de los controles de la interfaz de un editor de texto y sus diferentes opciones.</li>\r\n<li>Confecci&oacute;n de documentos profesionales siguiendo gu&iacute;as de estilos con diferentes tem&aacute;ticas.</li>\r\n<li>Creaci&oacute;n de tablas funcionales dentro de documentos para representar informaci&oacute;n relevante para los estudiantes.</li>\r\n<li>Confecci&oacute;n de gr&aacute;ficos avanzados dentro de documentos.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>', '', '<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>', '', '', 0, 1, 1, 1),
(78, 116, 6, 'Aplicaciones Ofimáticas', 22, 2, 15, '<p>El objetivo de esta unidad es que el alumnado aprenda nociones b&aacute;sicas de ofim&aacute;tica, concretamente la elaboraci&oacute;n de hojas de c&aacute;lculo, presentaciones y uso b&aacute;sico de gestores de bases de datos locales. Deber&aacute;n de elaborar diferentes actividades haciendo uso de estar herramientas simulando operaciones en entornos reales.</p>', '<p>Esta unidad es importante, ya que, hoy en d&iacute;a en cualquier trabajo en el que se utilice un ordenador se hace uso de hojas de c&aacute;lculo para presupuesto, presentaciones para proyectos o bases de datos para la gesti&oacute;n de usuario o inventario. Por este motivo, los estudiantes han de alcanzar un nivel b&aacute;sico en estas herramientas para desenvolverse de forma adecuada en el sector.</p>', '<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>', '<ol>\r\n<li>Suites ofim&aacute;ticas.</li>\r\n<li>Hojas de c&aacute;lculo.</li>\r\n<li>Bases de datos.</li>\r\n<li>Presentaciones multimedia.</li>\r\n<li>Aplicaciones ofim&aacute;ticas en la nube.</li>\r\n</ol>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n de las diferentes funcionalidades de un software de hojas de c&aacute;lculo.</li>\r\n<li>Elaboraci&oacute;n de un gestor de notas autom&aacute;tico.</li>\r\n<li>Explicaci&oacute;n de las diferentes funcionalidades de un software de base de datos.</li>\r\n<li>Elaboraci&oacute;n de un gestor de usuarios de gimnasio.</li>\r\n<li>Explicaci&oacute;n de las diferentes funcionalidades de un software de presentaci&oacute;n.</li>\r\n<li>Elaboraci&oacute;n de una presentaci&oacute;n sobre los contenidos estudiados.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>', '', '<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>', '', '', 0, 1, 1, 1),
(79, 116, 7, 'Servicios Básicos de Internet', 40, 2, 7, '<p>El objetivo de esta unidad es que el alumnado aprenda nociones b&aacute;sicas de los servicios m&aacute;s usados en internet, como la configuraci&oacute;n de navegadores, los diferentes buscadores y la comunicaci&oacute;n mediante correos electr&oacute;nicos o plataformas de mensajer&iacute;a instant&aacute;nea.</p>', '<p>Esta unidad es importante, ya que, hoy en d&iacute;a en cualquier trabajo se hace uso del correo electr&oacute;nico o de aplicaciones de comunicaci&oacute;n instant&aacute;nea y el alumnado ha de estar familiarizado con estas herramientas. Adem&aacute;s, hacer un buen uso de internet es esencial para ser mas productivo en las tareas de oficina.</p>', '<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>', '<ol>\r\n<li>Conceptos b&aacute;sicos.</li>\r\n<li>La web.</li>\r\n<li>El navegador.</li>\r\n<li>Los buscadores.</li>\r\n<li>El correo electr&oacute;nico.</li>\r\n<li>La mensajer&iacute;a instant&aacute;nea.</li>\r\n</ol>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n y configuraci&oacute;n de un navegador de internet y patrones de b&uacute;squeda en los principales exploradores.</li>\r\n<li>Configuraci&oacute;n de un correo electr&oacute;nico y sus principales caracter&iacute;sticas.</li>\r\n<li>Explicaci&oacute;n del funcionamiento de la mensajer&iacute;a instant&aacute;nea y su presencia en la actualidad</li>\r\n<li>Uso de una plataforma de comunicaci&oacute;n online para crear reuniones virtuales.</li>\r\n<li>Elaboraci&oacute;n de correos electr&oacute;nicos profesionales.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>', '', '<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>', '', '', 0, 1, 1, 1),
(80, 116, 8, 'Servicios Web', 14, 3, 4, '<p>El objetivo de esta unidad es que el alumnado conozca los diferentes servicios web que existen en la actualidad y comprendan su funcionamiento. &nbsp;</p>', '<p>Esta unidad es importante, ya que, hoy en d&iacute;a se hace uso de m&uacute;ltiples servicios web, pero en muchas ocasiones no se conoce su funcionamiento interno. Por este motivo, es esencial que el alumnado conozca en qu&eacute; consisten estos servicios en profundidad y aprendan a explotarlos de una forma &oacute;ptima.</p>', '<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>', '<ol>\r\n<li>Generaciones web.</li>\r\n<li>Foros.</li>\r\n<li>Blogs.</li>\r\n<li>Wikis.</li>\r\n<li>Sindicaci&oacute;n de contenidos.</li>\r\n<li>Redes sociales.</li>\r\n<li>Computaci&oacute;n en la nube.</li>\r\n<li>Gestores de contenidos.</li>\r\n<li>Redes y servicios p2p.</li>\r\n</ol>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n sobre qu&eacute; es la web y los principales protocolos que permiten su funcionamiento.</li>\r\n<li>Explicaci&oacute;n de los foros y uso real de uno de ellos.</li>\r\n<li>Creaci&oacute;n de un blog y participaci&oacute;n en una Wiki publica para aportar informaci&oacute;n.</li>\r\n<li>Investigaci&oacute;n sobre el estado del arte de las diferentes redes sociales y explicaci&oacute;n de los diferentes modelos que existen</li>\r\n<li>Manejo de gestores de contenido CMS</li>\r\n<li>Explicaci&oacute;n de las redes P2P y su uso en la actualidad</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>', '', '<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>', '', '', 0, 1, 1, 1),
(81, 116, 9, 'Seguridad Informática', 14, 3, 2, '<p>El objetivo de esta unidad es que el alumnado conozca las principales vulnerabilidades de seguridad de los sistemas y aprenda a protegerse de ellas. En la unidad se explicar&aacute;n buenas pr&aacute;cticas b&aacute;sicas de seguridad para proteger su actividad digital.</p>', '<p>Esta unidad es importante, ya que, hoy en d&iacute;a los ciberataques no cesan y cada vez m&aacute;s van en aumento. Por este motivo, esta unidad pretende que el alumnado adquiera consciencia de los peligros de internet, aprenda a identificarlos y protegerse de ellos, garantizando as&iacute; su seguridad en sus futuras actividades digitales.</p>', '<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>', '<ol>\r\n<li>Seguridad de un sistema inform&aacute;tico.</li>\r\n<li>Tipos de amenazas.</li>\r\n<li>Niveles de seguridad.</li>\r\n<li>An&aacute;lisis y control del riesgo.</li>\r\n<li>Mecanismos de seguridad f&iacute;sica.</li>\r\n<li>Mecanismos de seguridad l&oacute;gica.</li>\r\n<li>Ataques m&aacute;s comunes.</li>\r\n<li>Buenas pr&aacute;cticas.</li>\r\n</ol>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n sobre los diferentes ataques inform&aacute;ticos y c&oacute;mo prevenirlos.</li>\r\n<li>Niveles de protecci&oacute;n tanto f&iacute;sica como digital de los componentes inform&aacute;ticos.</li>\r\n<li>Buenas pr&aacute;cticas de ciberseguridad.</li>\r\n<li>Configuraci&oacute;n de un detector de malware.</li>\r\n<li>Configuraci&oacute;n de un bloqueador de rastreadores y scripts en un navegador.</li>\r\n<li>Explicaci&oacute;n y uso de un gestor de contrase&ntilde;as.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>', '', '<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>', '', '', 0, 1, 1, 1),
(82, 116, 10, 'Multimedia', 16, 3, 2, '<p>El objetivo de esta unidad es que el alumnado conozca los diferentes tipos de contenidos multimedia que existen en la actualidad, trabajar con ellos, reconocer plataformas de consumo y realizar conversiones de formatos &uacute;tiles en el d&iacute;a a d&iacute;a.</p>', '<p>Esta unidad es importante, ya que, en la actualidad existen numerosos formatos digitales para elaborar multimedia y desde un punto de vista de usuario, es necesario reconocer los principales formatos para trabajar de forma adecuada con cada uno de ellos. Adem&aacute;s, conocer m&eacute;todos de conversi&oacute;n eficaces es de gran ayuda en el trabajo inform&aacute;tico diario.</p>', '<p>Las clases se desarrollar&aacute;n en el aula asignada al grupo haciendo uso de los ordenadores de esta y los programas que estos disponen por defecto.</p>', '<ol>\r\n<li>Contenido multimedia.</li>\r\n<li>Herramientas para la creaci&oacute;n de contenido multimedia.</li>\r\n<li>Plataformas de contenido multimedia.</li>\r\n<li>Herramientas de conversi&oacute;n de formatos.</li>\r\n</ol>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Explicaci&oacute;n sobre los diferentes formatos multimedia que sirven para producir videos, m&uacute;sica e im&aacute;genes.</li>\r\n<li>Exposici&oacute;n de herramientas de creaci&oacute;n de contenido multimedia.</li>\r\n<li>Investigaci&oacute;n sobre las diferentes plataformas de generaci&oacute;n y consumo de contenido.</li>\r\n<li>Uso de herramientas de conversi&oacute;n de formatos &uacute;tiles para la gesti&oacute;n de documentos y ficheros multimedia.</li>\r\n</ul>\r\n<p>Cada una de las partes ir&aacute; acompa&ntilde;ada de sus respectivos ejercicios pr&aacute;cticos.</p>', '', '<p>Para la evaluaci&oacute;n de esta unidad se har&aacute;n uso de dos instrumentos de evaluaci&oacute;n:</p>\r\n<ul>\r\n<li>Tareas de clase</li>\r\n<li>Examen final de unidad</li>\r\n</ul>\r\n<p>Las tareas consistir&aacute;n en una serie de entregables mediante la plataforma AULES que llevar&aacute;n a la pr&aacute;ctica los diferentes conceptos vistos en clase. Para la correcci&oacute;n de estas tareas se har&aacute; uso de unas r&uacute;bricas de evaluaci&oacute;n asociadas a los CE de la unidad.</p>\r\n<p>El examen por su lado consistir&aacute; en una prueba objetiva con parte te&oacute;rica (tipo test) y una parte pr&aacute;ctica (redacci&oacute;n) sobre los conceptos vistos en la unidad y trabajados en las tareas.</p>\r\n<p>La nota final de la unidad se calcular&aacute; haciendo media con la nota de las diferentes tareas y el examen final y mediante esta nota se definir&aacute; si se han alcanzado o no los criterios de evaluaci&oacute;n (CE) asociados al Resultado de Aprendizaje (RA) de la unidad.</p>', '', '', 0, 1, 1, 1),
(83, 112, 2, 'Cableado y conexiones en equipos', 25, 1, 7, '<p>En esta unidad vamos a ver</p>\r\n<ul>\r\n<li>Conocer los diferentes tipos de cables utilizados en el interior de equipos.</li>\r\n<li>Manipular los tipos de cables que se utilizan en los equipos.</li>\r\n<li>Conocer las herramientas para el trabajo con cables.</li>\r\n<li>Conocer los elementos utilizados en el interior de equipos para el guiado de cables.</li>\r\n<li>Utilizar diferentes t&eacute;cnicas para el guiado y fijaci&oacute;n de cables en el interior de equipos.</li>\r\n<li>Utilizar t&eacute;cnicas de crimpado para la fijaci&oacute;n de terminales y punteras en cables.</li>\r\n<li>Identificar los diferentes tipos de conectores.</li>\r\n<li>Conocer los equipos y materiales utilizados para la realizaci&oacute;n de soldadura blanda.</li>\r\n<li>Utilizar t&eacute;cnicas de soldadura blanda para la realizaci&oacute;n de empalmes de cables.</li>\r\n</ul>\r\n<p>&nbsp;</p>', '<p>Los alumnos deberan conocer cada tipo de cable y su utilizacion, asi como las herramientas que se utilizan en cada uno de ellos. Tambi&eacute;n como soldar componentes electronicos con seguridad y eficacia.</p>', '', '<ol>\r\n<li>Cables y sus tipos</li>\r\n</ol>\r\n<p>- Unipolares: con funda, esmaltados</p>\r\n<p>- Multipolares: apantallados, de cinta</p>\r\n<p>- Fibra &oacute;ptica</p>\r\n<p>- Circuitos impresos</p>\r\n<p>- Herramientas para trabajar con cables</p>\r\n<ol start=\"2\">\r\n<li>Pelacables</li>\r\n</ol>\r\n<p>- Pelamangueras</p>\r\n<p>- Pinza pelacables</p>\r\n<p>- Peladora el&eacute;ctrica de hilos esmaltados</p>\r\n<p>- Herramientas para cables de fibra &oacute;ptica</p>\r\n<ol start=\"3\">\r\n<li>Guiado y fijaci&oacute;n de cables</li>\r\n</ol>\r\n<p>- Fundas y mallas protectoras</p>\r\n<p>- Tubos flexibles de fibra de vidrio</p>\r\n<p>- Fundas tranzadas de poli&eacute;ster</p>\r\n<p>- Fundas termoretr&aacute;ctiles</p>\r\n<p>- Bridas</p>\r\n<p>- Cinta helicoidal</p>\r\n<p>- Sistema de identificaci&oacute;n del cableado</p>\r\n<ol start=\"4\">\r\n<li>Terminaciones de cables</li>\r\n</ol>\r\n<p>- Crimpado o engastado</p>\r\n<p>- Terminales y punteras</p>\r\n<p>- Tenazas de crimpar o engastar</p>\r\n<p>- Bornes y conectores: regletas o clemas, bornes enchufables, conectores cable-cable, conectores cable-placa, conectores placa-placa</p>\r\n<ol start=\"5\">\r\n<li>Soldadura blanda</li>\r\n</ol>\r\n<p>- El esta&ntilde;o</p>\r\n<p>- Decapante</p>\r\n<p>- Soldador</p>\r\n<p>- Desoldador</p>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Los alumnos iran leyendo uno a uno un apartado del tema y a continuaci&oacute;n los explicar&eacute; poniendo ejemplos para su f&aacute;cil comprensi&oacute;n.</li>\r\n<li>Una vez terminado el tema haran un resumen de &eacute;ste.</li>\r\n<li>Realizaran el ejercicio tipo test del final del tema.</li>\r\n<li>Realizaran los ejercicios correspondientes al tema.</li>\r\n</ul>\r\n<p>Cada alumno realizar&aacute; todas las tareas anteriores en su libreta de la asignatura.</p>', '<p>Aula de inform&aacute;tica:</p>\r\n<ul>\r\n<li>Ordenadores conectados en red. El aula deber&aacute; disponer de al menos del suficiente n&uacute;mero de ordenadores para que no haya m&aacute;s de dos alumnos por puesto de trabajo, aunque es recomendable que cada alumno tenga su ordenador.</li>\r\n<li>Pizarra y altavoces</li>\r\n<li>Ca&ntilde;&oacute;n para mostrar la salida del ordenador del profesor a los alumnos.</li>\r\n<li>Ordenador-servidor conectado al ca&ntilde;&oacute;n.</li>\r\n<li>Conexi&oacute;n a Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Taller:</p>\r\n<ul>\r\n<li>Ordenadores antiguos.</li>\r\n<li>Electrodom&eacute;sticos para desmontar</li>\r\n<li>Componentes sueltos.</li>\r\n<li>Herramientas de taller.</li>\r\n<li>Material de limpieza de componentes.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>En cuanto al software a utilizar:</p>\r\n<ul>\r\n<li>Sistemas operativos Microsoft Windows, GNU/Linux</li>\r\n<li>Libre Office</li>\r\n<li>Programas de simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Libro de texto &ldquo;Equipos El&eacute;ctricos y electr&oacute;nicos&rdquo;. formaci&oacute;n Profesional B&aacute;sica,</p>\r\n<p>Juan Carlos Martin. Editorial Editex&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Diversos recursos de Internet.</p>', '<ol>\r\n<li>Observaci&oacute;n directa alumno/a: motivaci&oacute;n, inter&eacute;s, actitudes, comportamiento, asistencia, etc.</li>\r\n<li>Participaci&oacute;n en clase: intervenciones sobre actividades y ejercicios propuestos, valorando su dedicaci&oacute;n e inter&eacute;s.</li>\r\n<li>Realizaci&oacute;n de actividades individuales y grupales</li>\r\n<li>Prueba escrita al final de la unidad</li>\r\n</ol>', '<p>El profesor har&aacute; una exposici&oacute;n te&oacute;rica pr&aacute;ctica de la unidad, en un aula-taller, dotada de las herramientas y materiales necesarios para el desarrollo pr&aacute;ctico del m&oacute;dulo.</p>\r\n<p>Se describir&aacute;n como son y c&oacute;mo se utilizan las diferentes herramientas nombradas en la unidad, mostrando su uso pr&aacute;ctico y teniendo siempre presentas las medidas de seguridad aconsejadas para su correcta utilizaci&oacute;n.</p>\r\n<p>En esta unidad el alumno debe conocer de forma pr&aacute;ctica como se trabaja con diferentes tipos de cable y los elementos de conexi&oacute;n.</p>\r\n<p>El alumno realizar&aacute;, de forma individual o en grupo, las Eval&uacute;o mi aprendizaje, la Pr&aacute;ctica Profesional resuelta y las Reto profesional correspondientes.</p>\r\n<p>Todas las actividades se realizar&aacute;n en un aula-taller dotada de bancos de trabajo.</p>\r\n<p>Posteriormente, resolver&aacute; el TEST de la p&aacute;gina &ldquo;Eval&uacute;o mis conocimientos&rdquo; para afianzar los contenidos trabajados a lo largo de la unidad.</p>\r\n<p>A lo largo de la unidad se potenciar&aacute; la intervenci&oacute;n oral de los alumnos/as con actividades de debate, puesto que la unidad permite relacionar los conocimientos previos con los que se pretende que adquieran. Estas actividades persiguen un modelo constructivista.</p>\r\n<p>Asimismo, se potenciar&aacute; la comunicaci&oacute;n y el trabajo en equipo, la educaci&oacute;n no sexista y tolerante con otras culturas, la educaci&oacute;n para la convivencia, el uso de la lengua inglesa y los objetivos de desarrollo sostenible (ODS).</p>', '', 1, 0, 0, 1),
(84, 112, 3, 'Medidas eléctricas y su medida', 50, 1, 19, '<p>En esta unidad vamos a ver:&nbsp;</p>\r\n<ul>\r\n<li>Identificar las magnitudes el&eacute;ctricas b&aacute;sicas y las unidades en las que se miden.</li>\r\n<li>Conocer los tipos de corriente que pueden alimentar un circuito el&eacute;ctrico.</li>\r\n<li>Identificar las unidades de medida de las magnitudes el&eacute;ctricas y su m&uacute;ltiplos y subm&uacute;ltiplos.</li>\r\n<li>Calcular la resistencia equivalente en circuitos serie y paralelo de resistencias.</li>\r\n<li>Medir la resistencia el&eacute;ctrica con un pol&iacute;metro en circuitos de resistencias en serie y en paralelo.</li>\r\n<li>Identificar cada una de las partes de un pol&iacute;metro y para qu&eacute; sirven.</li>\r\n<li>Conocer las normas de seguridad que se han de tener en cuenta para realizar medidas el&eacute;ctricas.</li>\r\n<li>Medir tensiones e intensidades en circuitos de receptores serie y paralelo de corriente alterna.</li>\r\n<li>Entender la relaci&oacute;n que existen entre algunas magnitudes el&eacute;ctricas (ley de Ohm y potencia el&eacute;ctrica).</li>\r\n<li>Medir potencia el&eacute;ctrica de forma directa.</li>\r\n<li>Conocer diferentes instrumentos de medida y c&oacute;mo se conectan.</li>\r\n<li>Usar software de simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>', '<p>El alumno debe conocer las magnitudes electricas y sus relacciones entre ellas. Como se miden, con seguridad, utilizando un polimetro&nbsp; para ello.</p>', '', '<ol>\r\n<li>Tipos de corriente el&eacute;ctrica</li>\r\n</ol>\r\n<p>- Corriente continua</p>\r\n<p>- Corriente alterna</p>\r\n<ol start=\"2\">\r\n<li>Circuito el&eacute;ctrico</li>\r\n<li>Conexiones en serie y en paralelo</li>\r\n<li>Magnitudes el&eacute;ctricas b&aacute;sicas</li>\r\n</ol>\r\n<p>- M&uacute;ltiplos y subm&uacute;ltiplos</p>\r\n<p>- Resistencia el&eacute;ctrica: asociaci&oacute;n de resistencias en serie y en paralelo</p>\r\n<p>- Intensidad de corriente: medida de corriente en circuitos de receptores en serie y en paralelo</p>\r\n<p>- Tensi&oacute;n el&eacute;ctrica: medida de tensi&oacute;n el&eacute;ctrica en circuitos de receptores en serie y en paralelo</p>\r\n<ol start=\"5\">\r\n<li>Relaciones entre magnitudes el&eacute;ctricas</li>\r\n</ol>\r\n<p>- Ley de Ohm</p>\r\n<p>- Potencia el&eacute;ctrica</p>\r\n<ol start=\"6\">\r\n<li>El pol&iacute;metro</li>\r\n</ol>\r\n<p>- Medidas el&eacute;ctricas con el pol&iacute;metro: medida de tensi&oacute;n, medida de intensidad en corriente continua, medida de intensidad en corriente alterna, medida de resistencia el&eacute;ctrica, comprobaci&oacute;n de continuidad</p>\r\n<p>- Protecci&oacute;n del pol&iacute;metro</p>\r\n<p>- Simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos b&aacute;sicos con ordenador</p>\r\n<p>- Simulaci&oacute;n de medidas el&eacute;ctricas b&aacute;sicas con ordenador</p>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Los alumnos iran leyendo uno a uno un apartado del tema y a continuaci&oacute;n los explicar&eacute; poniendo ejemplos para su f&aacute;cil comprensi&oacute;n.</li>\r\n<li>Una vez terminado el tema haran un resumen de &eacute;ste.</li>\r\n<li>Realizaran el ejercicio tipo test del final del tema.</li>\r\n<li>Realizaran los ejercicios correspondientes al tema.</li>\r\n</ul>\r\n<p>Cada alumno realizar&aacute; todas las tareas anteriores en su libreta de la asignatura.</p>', '<p>Aula de inform&aacute;tica:</p>\r\n<ul>\r\n<li>Ordenadores conectados en red. El aula deber&aacute; disponer de al menos del suficiente n&uacute;mero de ordenadores para que no haya m&aacute;s de dos alumnos por puesto de trabajo, aunque es recomendable que cada alumno tenga su ordenador.</li>\r\n<li>Pizarra y altavoces</li>\r\n<li>Ca&ntilde;&oacute;n para mostrar la salida del ordenador del profesor a los alumnos.</li>\r\n<li>Ordenador-servidor conectado al ca&ntilde;&oacute;n.</li>\r\n<li>Conexi&oacute;n a Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Taller:</p>\r\n<ul>\r\n<li>Ordenadores antiguos.</li>\r\n<li>Electrodom&eacute;sticos para desmontar</li>\r\n<li>Componentes sueltos.</li>\r\n<li>Herramientas de taller.</li>\r\n<li>Material de limpieza de componentes.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>En cuanto al software a utilizar:</p>\r\n<ul>\r\n<li>Sistemas operativos Microsoft Windows, GNU/Linux</li>\r\n<li>Libre Office</li>\r\n<li>Programas de simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Libro de texto &ldquo;Equipos El&eacute;ctricos y electr&oacute;nicos&rdquo;. formaci&oacute;n Profesional B&aacute;sica,</p>\r\n<p>Juan Carlos Martin. Editorial Editex&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Diversos recursos de Internet.</p>', '<ol>\r\n<li>Observaci&oacute;n directa alumno/a: motivaci&oacute;n, inter&eacute;s, actitudes, comportamiento, asistencia, etc.</li>\r\n<li>Participaci&oacute;n en clase: intervenciones sobre actividades y ejercicios propuestos, valorando su dedicaci&oacute;n e inter&eacute;s.</li>\r\n<li>Realizaci&oacute;n de actividades individuales y grupales</li>\r\n<li>Prueba escrita al final de la unidad</li>\r\n</ol>', '<p>El profesor har&aacute; una exposici&oacute;n te&oacute;rica pr&aacute;ctica de la unidad, exponiendo que es la corriente el&eacute;ctrica, los diferentes tipos que existen y las magnitudes elementales.</p>\r\n<p>Debido a que el nivel matem&aacute;tico de los alumnos al que va dirigido esta unidad no puede ser el adecuado, se aconseja utilizar la calculadora para resolver las actividades de asociaci&oacute;n de resistencias, especialmente en paralelo.</p>\r\n<p>Posteriormente, los alumnos aprender&aacute;n a manejar el pol&iacute;metro, para medir, de forma pr&aacute;ctica, las magnitudes anteriormente explicadas.</p>\r\n<p>El profesor podr&aacute; recurrir al uso de software de simulaci&oacute;n el&eacute;ctrico-electr&oacute;nica para conocer las diferentes magnitudes el&eacute;ctricas, sus unidades y su forma de medirlas.</p>\r\n<p>El alumno realizar&aacute;, de forma individual o en grupo, las Eval&uacute;o mi aprendizaje, la Pr&aacute;ctica Profesional resuelta y las Reto profesional correspondientes.</p>\r\n<p>Todas las actividades se realizar&aacute;n en un aula-taller dotada de bancos de trabajo.</p>\r\n<p>Posteriormente, resolver&aacute; el TEST de la p&aacute;gina &ldquo;Eval&uacute;o mis conocimientos&rdquo; para afianzar los contenidos trabajados a lo largo de la unidad.</p>\r\n<p>A lo largo de la unidad se potenciar&aacute; la intervenci&oacute;n oral de los alumnos/as con actividades de debate, puesto que la unidad permite relacionar los conocimientos previos con los que se pretende que adquieran. Estas actividades persiguen un modelo constructivista.</p>\r\n<p>Asimismo, se potenciar&aacute; la comunicaci&oacute;n y el trabajo en equipo, la educaci&oacute;n no sexista y tolerante con otras culturas, la educaci&oacute;n para la convivencia, el uso de la lengua inglesa y los objetivos de desarrollo sostenible (ODS).</p>', '', 1, 0, 0, 1),
(85, 112, 4, 'Elementos de conmutación y protecciones', 35, 2, 6, '<p>En esta unidad vamos a ver:</p>\r\n<ul>\r\n<li>Conocer los modos de accionamiento de los diferentes elementos de conmutaci&oacute;n.</li>\r\n<li>Identificar los elementos de conmutaci&oacute;n por su s&iacute;mbolo.</li>\r\n<li>Identificar los dispositivos de conmutaci&oacute;n por su tipo de instalaci&oacute;n.</li>\r\n<li>Identificar los elementos de conmutaci&oacute;n por su n&uacute;mero de v&iacute;as y polos.</li>\r\n<li>Representar esquemas con dispositivos de conmutaci&oacute;n.</li>\r\n<li>Conocer las caracter&iacute;sticas el&eacute;ctricas de los dispositivos de conmutaci&oacute;n.</li>\r\n<li>Conocer y representar diferentes circuitos de conmutaci&oacute;n.</li>\r\n<li>Montar y probar circuitos con dispositivos de conmutaci&oacute;n.</li>\r\n<li>Identificar los diferentes tipos de fusibles y su representaci&oacute;n en los esquemas.</li>\r\n<li>Conocer los dispositivos utilizados para proteger los equipos contra el exceso de temperatura.</li>\r\n<li>Conocer componentes utilizados para la protecci&oacute;n contra sobretensiones.</li>\r\n<li>Comprobar componentes de protecci&oacute;n con un pol&iacute;metro.</li>\r\n</ul>', '<p>El alumno debera conocer los elementos de conmutaci&oacute;n, asi como sus caracteristicas el&eacute;ctricas, para poder seleccionar en cada esquema cual utilizar. Tambi&eacute;n utilizar elementos de protecci&oacute;n y como comprobarlos.</p>\r\n<p>&nbsp;</p>', '', '<ol>\r\n<li>Elementos de conmutaci&oacute;n</li>\r\n</ol>\r\n<p>- Modo de accionamiento: pulsadores, interruptores y conmutadores</p>\r\n<p>- Numero de polos y v&iacute;as</p>\r\n<p>- Caracter&iacute;sticas el&eacute;ctricas</p>\r\n<ol start=\"2\">\r\n<li>Circuitos b&aacute;sicos de conmutaci&oacute;n</li>\r\n</ol>\r\n<p>- Punto de luz</p>\r\n<p>- Punto de luz con l&aacute;mparas en paralelo</p>\r\n<p>- Encendido alternativo de l&aacute;mparas</p>\r\n<p>- Conmutaci&oacute;n de tres circuitos</p>\r\n<p>- L&aacute;mpara conmutada</p>\r\n<p>- Activaci&oacute;n de un motor condicionado a un final de carrera</p>\r\n<p>- Activaci&oacute;n de dos circuitos con un pulsador DPST</p>\r\n<p>- Inversi&oacute;n del sentido de giro de un motor</p>\r\n<ol start=\"3\">\r\n<li>Protecciones en el interior de equipos</li>\r\n</ol>\r\n<p>- Protecci&oacute;n contra sobrecorrientes</p>\r\n<p>- Protecci&oacute;n contra el exceso de temperatura</p>\r\n<p>- Protecci&oacute;n contra sobretensiones</p>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Los alumnos iran leyendo uno a uno un apartado del tema y a continuaci&oacute;n los explicar&eacute; poniendo ejemplos para su f&aacute;cil comprensi&oacute;n.</li>\r\n<li>Una vez terminado el tema haran un resumen de &eacute;ste.</li>\r\n<li>Realizaran el ejercicio tipo test del final del tema.</li>\r\n<li>Realizaran los ejercicios correspondientes al tema.</li>\r\n</ul>\r\n<p>Cada alumno realizar&aacute; todas las tareas anteriores en su libreta de la asignatura.</p>', '<p>Aula de inform&aacute;tica:</p>\r\n<ul>\r\n<li>Ordenadores conectados en red. El aula deber&aacute; disponer de al menos del suficiente n&uacute;mero de ordenadores para que no haya m&aacute;s de dos alumnos por puesto de trabajo, aunque es recomendable que cada alumno tenga su ordenador.</li>\r\n<li>Pizarra y altavoces</li>\r\n<li>Ca&ntilde;&oacute;n para mostrar la salida del ordenador del profesor a los alumnos.</li>\r\n<li>Ordenador-servidor conectado al ca&ntilde;&oacute;n.</li>\r\n<li>Conexi&oacute;n a Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Taller:</p>\r\n<ul>\r\n<li>Ordenadores antiguos.</li>\r\n<li>Electrodom&eacute;sticos para desmontar</li>\r\n<li>Componentes sueltos.</li>\r\n<li>Herramientas de taller.</li>\r\n<li>Material de limpieza de componentes.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>En cuanto al software a utilizar:</p>\r\n<ul>\r\n<li>Sistemas operativos Microsoft Windows, GNU/Linux</li>\r\n<li>Libre Office</li>\r\n<li>Programas de simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Libro de texto &ldquo;Equipos El&eacute;ctricos y electr&oacute;nicos&rdquo;. formaci&oacute;n Profesional B&aacute;sica,</p>\r\n<p>Juan Carlos Martin. Editorial Editex&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Diversos recursos de Internet.</p>', '<ol>\r\n<li>Observaci&oacute;n directa alumno/a: motivaci&oacute;n, inter&eacute;s, actitudes, comportamiento, asistencia, etc.</li>\r\n<li>Participaci&oacute;n en clase: intervenciones sobre actividades y ejercicios propuestos, valorando su dedicaci&oacute;n e inter&eacute;s.</li>\r\n<li>Realizaci&oacute;n de actividades individuales y grupales</li>\r\n<li>Prueba escrita al final de la unidad</li>\r\n</ol>', '<p>El profesor har&aacute; una exposici&oacute;n te&oacute;rico-pr&aacute;ctica de la unidad, exponiendo c&oacute;mo son y c&oacute;mo se conectan en los circuitos los diferentes elementos de conmutaci&oacute;n y protecci&oacute;n de equipos.</p>\r\n<p>Para mejorar la exposici&oacute;n, el profesor puede recurrir a software de simulaci&oacute;n, con el que mostrar detalladamente c&oacute;mo funcionan los dispositivos de conmutaci&oacute;n.</p>\r\n<p>Inicialmente los alumnos realizar&aacute;n, de forma individual o en grupo, la pr&aacute;ctica profesional resuelta, posteriormente las Reto profesional y por &uacute;ltimo las Eval&uacute;o mi aprendizaje de la unidad.</p>\r\n<p>Todas las actividades se realizar&aacute;n en un aula-taller dotada de bancos de trabajo.</p>\r\n<p>Posteriormente, resolver&aacute;n el TEST de la p&aacute;gina &ldquo;Eval&uacute;o mis conocimientos&rdquo; para afianzar los contenidos trabajados a lo largo de la unidad.</p>\r\n<p>A lo largo de la unidad se potenciar&aacute; la intervenci&oacute;n oral de los alumnos/as con actividades de debate, puesto que la unidad permite relacionar los conocimientos previos con los que se pretende que adquieran. Estas actividades persiguen un modelo constructivista.</p>\r\n<p>Asimismo, se potenciar&aacute; la comunicaci&oacute;n y el trabajo en equipo, la educaci&oacute;n no sexista y tolerante con otras culturas, la educaci&oacute;n para la convivencia, el uso de la lengua inglesa y los objetivos de desarrollo sostenible (ODS).</p>', '', 1, 1, 0, 1),
(86, 112, 5, 'Componentes eléctronicos pasivos', 45, 2, 14, '<p>En esta unidad vamos a ver:</p>\r\n<ul>\r\n<li>Conocer cu&aacute;les son los componentes de tipo pasivo m&aacute;s utilizados en electr&oacute;nica.</li>\r\n<li>Identificar los componentes pasivos por su s&iacute;mbolo.</li>\r\n<li>Identificar los diferentes tipos de resistencias de valor fijo.</li>\r\n<li>Identificar el valor &oacute;hmico de una resistencia por su c&oacute;digo de colores o c&oacute;digo alfanum&eacute;rico.</li>\r\n<li>Conocer cu&aacute;les son las potencias de disipaci&oacute;n normalizadas para las resistencias de carb&oacute;n.</li>\r\n<li>Identificar varios tipos de resistencias de valor variable.</li>\r\n<li>Comprobar resistencias de valor fijo y variable con el pol&iacute;metro.</li>\r\n<li>Conocer qu&eacute; es un condensador.</li>\r\n<li>Identificar los diferentes tipos de condensadores que se utilizan en equipos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n<li>Identificar el valor de un condensador por el c&oacute;digo de colores o c&oacute;digo alfanum&eacute;rico.</li>\r\n<li>Conocer los diferentes tipos de condensadores.</li>\r\n<li>Diferenciar entre condensadores polarizados o no.</li>\r\n<li>Medir la capacidad de un condensador con un pol&iacute;metro.</li>\r\n<li>Conocer diferentes tipos inductancias.</li>\r\n<li>Identificar las inductancias por su c&oacute;digo de colores o valor alfanum&eacute;rico.</li>\r\n<li>Conocer qu&eacute; es un transformador y para que se utiliza en los equipos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n<li>Identificar los devanados de un transformador.</li>\r\n<li>Medir tensiones en los devanados de un transformador.</li>\r\n</ul>', '<p>Deber&aacute; conocer los componentes pasivos, asi como sus caracteristicas electricas y como medirlos.</p>', '', '<ol>\r\n<li>Componentes electr&oacute;nicos pasivos</li>\r\n<li>Resistencias</li>\r\n</ol>\r\n<p>- El valor &oacute;hmico (Identificaci&oacute;n)</p>\r\n<p>- La potencia de disipaci&oacute;n</p>\r\n<p>- Tipos de resistencias de valor fijo: de carb&oacute;n, bobinadas, calefactoras</p>\r\n<p>- Tipos de resistencias de valor variable: potenci&oacute;metros, trimmers, LDR, NTC, PTC</p>\r\n<ol start=\"3\">\r\n<li>Condensadores</li>\r\n</ol>\r\n<p>- El valor de la capacidad. Identificaci&oacute;n y medida</p>\r\n<p>- Asociaci&oacute;n de condensadores</p>\r\n<p>- Tipos de condensadores: no polarizados y polarizados</p>\r\n<ol start=\"4\">\r\n<li>Inductancias o bobinas</li>\r\n</ol>\r\n<p>- El valor de la inductancia</p>\r\n<p>- Tipos de inductores</p>\r\n<ol start=\"5\">\r\n<li>El transformador</li>\r\n</ol>\r\n<p>- Funcionamiento</p>\r\n<p>- Partes</p>\r\n<p>- Tipos de transformadores usados en equipos</p>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Los alumnos iran leyendo uno a uno un apartado del tema y a continuaci&oacute;n los explicar&eacute; poniendo ejemplos para su f&aacute;cil comprensi&oacute;n.</li>\r\n<li>Una vez terminado el tema haran un resumen de &eacute;ste.</li>\r\n<li>Realizaran el ejercicio tipo test del final del tema.</li>\r\n<li>Realizaran los ejercicios correspondientes al tema.</li>\r\n</ul>\r\n<p>Cada alumno realizar&aacute; todas las tareas anteriores en su libreta de la asignatura.</p>', '<p>Aula de inform&aacute;tica:</p>\r\n<ul>\r\n<li>Ordenadores conectados en red. El aula deber&aacute; disponer de al menos del suficiente n&uacute;mero de ordenadores para que no haya m&aacute;s de dos alumnos por puesto de trabajo, aunque es recomendable que cada alumno tenga su ordenador.</li>\r\n<li>Pizarra y altavoces</li>\r\n<li>Ca&ntilde;&oacute;n para mostrar la salida del ordenador del profesor a los alumnos.</li>\r\n<li>Ordenador-servidor conectado al ca&ntilde;&oacute;n.</li>\r\n<li>Conexi&oacute;n a Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Taller:</p>\r\n<ul>\r\n<li>Ordenadores antiguos.</li>\r\n<li>Electrodom&eacute;sticos para desmontar</li>\r\n<li>Componentes sueltos.</li>\r\n<li>Herramientas de taller.</li>\r\n<li>Material de limpieza de componentes.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>En cuanto al software a utilizar:</p>\r\n<ul>\r\n<li>Sistemas operativos Microsoft Windows, GNU/Linux</li>\r\n<li>Libre Office</li>\r\n<li>Programas de simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Libro de texto &ldquo;Equipos El&eacute;ctricos y electr&oacute;nicos&rdquo;. formaci&oacute;n Profesional B&aacute;sica,</p>\r\n<p>Juan Carlos Martin. Editorial Editex&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Diversos recursos de Internet.</p>', '<ol>\r\n<li>Observaci&oacute;n directa alumno/a: motivaci&oacute;n, inter&eacute;s, actitudes, comportamiento, asistencia, etc.</li>\r\n<li>Participaci&oacute;n en clase: intervenciones sobre actividades y ejercicios propuestos, valorando su dedicaci&oacute;n e inter&eacute;s.</li>\r\n<li>Realizaci&oacute;n de actividades individuales y grupales</li>\r\n<li>Prueba escrita al final de la unidad</li>\r\n</ol>', '<p>El profesor har&aacute; una exposici&oacute;n te&oacute;rico-pr&aacute;ctica de la unidad, mostrando a los alumnos cuales son los componentes pasivos m&aacute;s utilizados en electr&oacute;nica, c&oacute;mo se identifican, cu&aacute;l es su s&iacute;mbolo y c&oacute;mo se obtiene su valor, bien leyendo el c&oacute;digo alfanum&eacute;rico que disponen en su encapsulado o bien mediante medici&oacute;n directa con el pol&iacute;metro.</p>\r\n<p>Inicialmente los alumnos realizar&aacute;n, de forma individual o en grupo, la pr&aacute;ctica profesional resuelta, posteriormente las Reto profesional y por &uacute;ltimo las Eval&uacute;o mi aprendizaje de la unidad.</p>\r\n<p>Posteriormente, resolver&aacute;n el TEST de la p&aacute;gina &ldquo;Eval&uacute;o mis conocimientos&rdquo; para afianzar los contenidos trabajados a lo largo de la unidad.</p>\r\n<p>Todas las actividades se realizar&aacute;n en un aula-taller dotado de bancos de trabajo.</p>\r\n<p>En esta unidad, es importante dejar finalizada la ficha de trabajo 6, ya que el transformador en ella montado, servir&aacute; para alimentar circuitos de pr&oacute;ximas unidades.</p>\r\n<p>A lo largo de la unidad se potenciar&aacute; la intervenci&oacute;n oral de los alumnos/as con actividades de debate, puesto que la unidad permite relacionar los conocimientos previos con los que se pretende que adquieran. Estas actividades persiguen un modelo constructivista.</p>\r\n<p>Asimismo, se potenciar&aacute; la comunicaci&oacute;n y el trabajo en equipo, la educaci&oacute;n no sexista y tolerante con otras culturas, la educaci&oacute;n para la convivencia, el uso de la lengua inglesa y los objetivos de desarrollo sostenible (ODS).</p>', '', 1, 0, 0, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(87, 112, 6, 'Componentes eléctronicos activos', 55, 2, 13, '<p>en esta unidad vamos a ver:</p>\r\n<ul>\r\n<li>Diferenciar entre componentes pasivos y activos.</li>\r\n<li>Identificar los componentes activos por su s&iacute;mbolo.</li>\r\n<li>Conocer qu&eacute; es un diodo y para qu&eacute; se utiliza.</li>\r\n<li>Polarizar correctamente los diodos.</li>\r\n<li>Montar una fuente de alimentaci&oacute;n con un puente de diodos.</li>\r\n<li>Conocer que son los diodos LED y como se conectan.</li>\r\n<li>Calcular la resistencia de polarizaci&oacute;n de un LED para una tensi&oacute;n determinada.</li>\r\n<li>Asociar LED en serie y en paralelo (y en antiparalelo) y calcular la resistencia de polarizaci&oacute;n del conjunto.</li>\r\n<li>Conocer qu&eacute; es un transistor y para qu&eacute; se utiliza.</li>\r\n<li>Diferenciar los tipos de transistores seg&uacute;n su polaridad.</li>\r\n<li>Conocer que es la ganancia de un transistor, como se calcula y como se mide con un pol&iacute;metro.</li>\r\n<li>Diferenciar los modos de funcionamiento de un transistor.</li>\r\n<li>Identificar las patillas de los diferentes modelos de transistores.</li>\r\n<li>Conocer qu&eacute; son los tiristores y TRIAC y qu&eacute; utilidades tienen.</li>\r\n<li>Identificar los circuitos integrados en el interior de los equipos electr&oacute;nicos.</li>\r\n<li>Conocer qu&eacute; es un rel&eacute; y para qu&eacute; se utiliza.</li>\r\n<li>Montar y probar diferentes circuitos con componentes electr&oacute;nicos activos.</li>\r\n</ul>', '<p>El alumnado deber&aacute; conocer los diferentes componentes activos, as&iacute; como coocer sus caracter&iacute;sticas el&eacute;ctricas. Tambi&eacute;n es necesario que sepan poder utilizarlos en circuitos el&eacute;ctricos y como medir sus caracter&iacute;sticas electricas.</p>', '', '<ol>\r\n<li>El diodo</li>\r\n</ol>\r\n<p>- Rectificaci&oacute;n de corriente</p>\r\n<p>- Puente de diodos</p>\r\n<ol start=\"2\">\r\n<li>El diodo LED</li>\r\n</ol>\r\n<p>- Resistencia de polarizaci&oacute;n</p>\r\n<p>- Asociaci&oacute;n de LED en serie y paralelo</p>\r\n<p>- LED de varios colores</p>\r\n<p>- Fotodiodos</p>\r\n<ol start=\"3\">\r\n<li>El transistor bipolar (BJT)</li>\r\n<li>El tiristor y el TRIAC</li>\r\n<li>Circuitos integrados (IC)</li>\r\n</ol>\r\n<p>6. El rel&eacute;</p>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Los alumnos iran leyendo uno a uno un apartado del tema y a continuaci&oacute;n los explicar&eacute; poniendo ejemplos para su f&aacute;cil comprensi&oacute;n.</li>\r\n<li>Una vez terminado el tema haran un resumen de &eacute;ste.</li>\r\n<li>Realizaran el ejercicio tipo test del final del tema.</li>\r\n<li>Realizaran los ejercicios correspondientes al tema.</li>\r\n</ul>\r\n<p>Cada alumno realizar&aacute; todas las tareas anteriores en su libreta de la asignatura.</p>', '<p>Aula de inform&aacute;tica:</p>\r\n<ul>\r\n<li>Ordenadores conectados en red. El aula deber&aacute; disponer de al menos del suficiente n&uacute;mero de ordenadores para que no haya m&aacute;s de dos alumnos por puesto de trabajo, aunque es recomendable que cada alumno tenga su ordenador.</li>\r\n<li>Pizarra y altavoces</li>\r\n<li>Ca&ntilde;&oacute;n para mostrar la salida del ordenador del profesor a los alumnos.</li>\r\n<li>Ordenador-servidor conectado al ca&ntilde;&oacute;n.</li>\r\n<li>Conexi&oacute;n a Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Taller:</p>\r\n<ul>\r\n<li>Ordenadores antiguos.</li>\r\n<li>Electrodom&eacute;sticos para desmontar</li>\r\n<li>Componentes sueltos.</li>\r\n<li>Herramientas de taller.</li>\r\n<li>Material de limpieza de componentes.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>En cuanto al software a utilizar:</p>\r\n<ul>\r\n<li>Sistemas operativos Microsoft Windows, GNU/Linux</li>\r\n<li>Libre Office</li>\r\n<li>Programas de simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Libro de texto &ldquo;Equipos El&eacute;ctricos y electr&oacute;nicos&rdquo;. formaci&oacute;n Profesional B&aacute;sica,</p>\r\n<p>Juan Carlos Martin. Editorial Editex&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Diversos recursos de Internet.</p>', '<ol>\r\n<li>Observaci&oacute;n directa alumno/a: motivaci&oacute;n, inter&eacute;s, actitudes, comportamiento, asistencia, etc.</li>\r\n<li>Participaci&oacute;n en clase: intervenciones sobre actividades y ejercicios propuestos, valorando su dedicaci&oacute;n e inter&eacute;s.</li>\r\n<li>Realizaci&oacute;n de actividades individuales y grupales</li>\r\n<li>Prueba escrita al final de la unidad</li>\r\n</ol>', '<p>El profesor har&aacute; una exposici&oacute;n te&oacute;rico-pr&aacute;ctica de la unidad, mostrando a los alumnos cuales son los componentes activos m&aacute;s utilizados en electr&oacute;nica.</p>\r\n<p>Inicialmente los alumnos realizar&aacute;n, de forma individual o en grupo, la pr&aacute;ctica profesional resuelta, posteriormente las Reto profesional y por &uacute;ltimo las Eval&uacute;o mi aprendizaje de la unidad.</p>\r\n<p>Todas las actividades se realizar&aacute;n en un aula-taller dotada de bancos de trabajo.</p>\r\n<p>Posteriormente, resolver&aacute;n el TEST de la p&aacute;gina &ldquo;Eval&uacute;o mis conocimientos&rdquo; para afianzar los contenidos trabajados a lo largo de la unidad.</p>\r\n<p>A lo largo de la unidad se potenciar&aacute; la intervenci&oacute;n oral de los alumnos/as con actividades de debate, puesto que la unidad permite relacionar los conocimientos previos con los que se pretende que adquieran. Estas actividades persiguen un modelo constructivista.</p>\r\n<p>Asimismo, se potenciar&aacute; la comunicaci&oacute;n y el trabajo en equipo, la educaci&oacute;n no sexista y tolerante con otras culturas, la educaci&oacute;n para la convivencia, el uso de la lengua inglesa y los objetivos de desarrollo sostenible (ODS).</p>', '', 1, 0, 0, 1),
(88, 112, 7, 'Circuitos en los equipos', 35, 3, 10, '<p>En esta unidad vamos a ver:</p>\r\n<ul>\r\n<li>Conocer las t&eacute;cnicas de ejecuci&oacute;n de circuitos en el interior de equipos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n<li>Identificar los diferentes tipos de placas de circuito impreso que se pueden utilizar para la fabricaci&oacute;n de circuitos electr&oacute;nicos.</li>\r\n<li>Conocer los pasos de fabricaci&oacute;n manual de una placa de circuito impreso de una cara.</li>\r\n<li>Montar placas de circuito impreso por el m&eacute;todo manual.</li>\r\n<li>Conocer algunos circuitos electr&oacute;nicos b&aacute;sicos muy utilizados en todo tipo de equipos.</li>\r\n<li>Montar varios circuitos en placas de circuito impreso.</li>\r\n</ul>', '<p>Los alumnos deber&aacute;n identificar los diferentes componentes y placas que se pueden encontrar dentro de un electrodom&eacute;stico o aparato y saber interpretar para qu&eacute; se utilizan.</p>', '', '<ol>\r\n<li>T&eacute;cnicas de ejecuci&oacute;n de circuitos en equipos</li>\r\n</ol>\r\n<p>- Circuitos cableados</p>\r\n<p>- Circuitos sobre placas de circuito impreso</p>\r\n<p>- Conexi&oacute;n por orificio pasante</p>\r\n<p>- Montaje superficial</p>\r\n<p>- Fabricaci&oacute;n de una placa de circuito impreso de forma manual</p>\r\n<ol start=\"2\">\r\n<li>Circuitos b&aacute;sicos de electr&oacute;nica</li>\r\n</ol>\r\n<p>- Fuente de alimentaci&oacute;n completa no estabilizada</p>\r\n<p>- Fuente de alimentaci&oacute;n sim&eacute;trica no estabilizada</p>\r\n<p>- Fuente de alimentaci&oacute;n estabilizada</p>\r\n<p>- Fuente de alimentaci&oacute;n sim&eacute;trica estabilizada</p>\r\n<p>- LED intermitente</p>\r\n<p>- Regulador de velocidad basado en TRIAC</p>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Los alumnos iran leyendo uno a uno un apartado del tema y a continuaci&oacute;n los explicar&eacute; poniendo ejemplos para su f&aacute;cil comprensi&oacute;n.</li>\r\n<li>Una vez terminado el tema haran un resumen de &eacute;ste.</li>\r\n<li>Realizaran el ejercicio tipo test del final del tema.</li>\r\n<li>Realizaran los ejercicios correspondientes al tema.</li>\r\n</ul>\r\n<p>Cada alumno realizar&aacute; todas las tareas anteriores en su libreta de la asignatura.</p>', '<p>Aula de inform&aacute;tica:</p>\r\n<ul>\r\n<li>Ordenadores conectados en red. El aula deber&aacute; disponer de al menos del suficiente n&uacute;mero de ordenadores para que no haya m&aacute;s de dos alumnos por puesto de trabajo, aunque es recomendable que cada alumno tenga su ordenador.</li>\r\n<li>Pizarra y altavoces</li>\r\n<li>Ca&ntilde;&oacute;n para mostrar la salida del ordenador del profesor a los alumnos.</li>\r\n<li>Ordenador-servidor conectado al ca&ntilde;&oacute;n.</li>\r\n<li>Conexi&oacute;n a Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Taller:</p>\r\n<ul>\r\n<li>Ordenadores antiguos.</li>\r\n<li>Electrodom&eacute;sticos para desmontar</li>\r\n<li>Componentes sueltos.</li>\r\n<li>Herramientas de taller.</li>\r\n<li>Material de limpieza de componentes.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>En cuanto al software a utilizar:</p>\r\n<ul>\r\n<li>Sistemas operativos Microsoft Windows, GNU/Linux</li>\r\n<li>Libre Office</li>\r\n<li>Programas de simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Libro de texto &ldquo;Equipos El&eacute;ctricos y electr&oacute;nicos&rdquo;. formaci&oacute;n Profesional B&aacute;sica,</p>\r\n<p>Juan Carlos Martin. Editorial Editex&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Diversos recursos de Internet.</p>', '<ol>\r\n<li>Observaci&oacute;n directa alumno/a: motivaci&oacute;n, inter&eacute;s, actitudes, comportamiento, asistencia, etc.</li>\r\n<li>Participaci&oacute;n en clase: intervenciones sobre actividades y ejercicios propuestos, valorando su dedicaci&oacute;n e inter&eacute;s.</li>\r\n<li>Realizaci&oacute;n de actividades individuales y grupales</li>\r\n<li>Prueba escrita al final de la unidad</li>\r\n</ol>', '<p>El profesor har&aacute; una exposici&oacute;n te&oacute;rico-pr&aacute;ctica de la unidad, mostrando a los alumnos algunos circuitos b&aacute;sicos utilizados en la t&eacute;cnica electr&oacute;nica.</p>\r\n<p>Inicialmente los alumnos realizar&aacute;n, de forma individual o en grupo, la pr&aacute;ctica profesional resuelta, posteriormente las Reto profesional y por &uacute;ltimo las Eval&uacute;o mi aprendizaje de la unidad.</p>\r\n<p>Todas las actividades se realizar&aacute;n en un aula-taller dotada de bancos de trabajo.</p>\r\n<p>Posteriormente, resolver&aacute;n el TEST de la p&aacute;gina &ldquo;Eval&uacute;o mis conocimientos&rdquo; para afianzar los contenidos trabajados a lo largo de la unidad.</p>\r\n<p>A lo largo de la unidad se potenciar&aacute; la intervenci&oacute;n oral de los alumnos/as con actividades de debate, puesto que la unidad permite relacionar los conocimientos previos con los que se pretende que adquieran. Estas actividades persiguen un modelo constructivista.</p>\r\n<p>Asimismo, se potenciar&aacute; la comunicaci&oacute;n y el trabajo en equipo, la educaci&oacute;n no sexista y tolerante con otras culturas, la educaci&oacute;n para la convivencia, el uso de la lengua inglesa y los objetivos de desarrollo sostenible (ODS).</p>', '', 1, 0, 0, 1),
(89, 112, 8, 'Motores y otros actuadores de electrodomésticos', 40, 3, 6, '<ul>\r\n<li>Identificar los diferentes tipos de motores que se pueden utilizar en electrodom&eacute;sticos.</li>\r\n<li>Conocer qu&eacute; son y c&oacute;mo funcionan los motores de corriente continua.</li>\r\n<li>Identificar cada una de las partes de los motores de corriente continua.</li>\r\n<li>Conocer qu&eacute; son y c&oacute;mo funciona los motores universales.</li>\r\n<li>Identificar las partes de los motores universales.</li>\r\n<li>Conocer c&oacute;mo se realiza la inversi&oacute;n del sentido de giro de los motores universales.</li>\r\n<li>Conocer c&oacute;mo se regula la velocidad de los motores universales.</li>\r\n<li>Comprobar los devanados de un motor universal de lavadora.</li>\r\n<li>Arrancar e invertir el sentido de giro de un motor universal de lavadora.</li>\r\n<li>Conocer qu&eacute; son y c&oacute;mo funcionan los motores monof&aacute;sicos de inducci&oacute;n.</li>\r\n<li>Identificar las partes de los motores de inducci&oacute;n.</li>\r\n<li>Conocer c&oacute;mo se arranca e invierte el sentido de giro en un motor monof&aacute;sico de inducci&oacute;n.</li>\r\n<li>Conocer c&oacute;mo se realiza el arranque de los motores monof&aacute;sicos de inducci&oacute;n de dos velocidades.</li>\r\n<li>Comprobar los devanados de un motor de inducci&oacute;n.</li>\r\n<li>Arrancar e invertir el sentido de giro de un motor monof&aacute;sico de inducci&oacute;n con condensador.</li>\r\n<li>Conocer qu&eacute; son y c&oacute;mo funcionan los motores de espira.</li>\r\n<li>Identificar las aplicaciones de los motores de espira.</li>\r\n<li>Conocer qu&eacute; son los motores sin escobillas o<em> brushless</em>.</li>\r\n<li>Identificar las partes de los motores sin escobillas o b<em>rushless</em>.</li>\r\n<li>Conocer qu&eacute; es una electrov&aacute;lvula y como funciona.</li>\r\n<li>Identificar las aplicaciones de las electrov&aacute;lvulas en el interior de los electrodom&eacute;sticos.</li>\r\n<li>Reconocer las partes que constituyen una electrov&aacute;lvula.</li>\r\n<li>Diferenciar los diferentes tipos de electrov&aacute;lvulas que existen en el mercado y cu&aacute;les son sus aplicaciones.</li>\r\n<li>Comprobar con un pol&iacute;metro electrov&aacute;lvulas y resistencias de caldeo.</li>\r\n<li>Conocer qu&eacute; es una bomba y para qu&eacute; se utiliza en los electrodom&eacute;sticos.</li>\r\n<li>Identificar los diferentes elementos de caldeo utilizados en los electrodom&eacute;sticos.</li>\r\n<li>Conocer los elementos de iluminaci&oacute;n y se&ntilde;alizaci&oacute;n utilizados en los equipos el&eacute;ctricos y electrodom&eacute;sticos.</li>\r\n<li>Reconocer otros actuadores utilizados en el interior de los electrodom&eacute;sticos.</li>\r\n<li>Comprobar con un pol&iacute;metro electrov&aacute;lvulas y resistencias de caldeo.</li>\r\n<li>Identificar los motores y actuadores por su s&iacute;mbolo.</li>\r\n</ul>', '<p>Conocer los diferentes tipos de motores y sus funciones. As&iacute; como los fundamentos de &eacute;stos.</p>', '', '<ol>\r\n<li>Motores el&eacute;ctricos</li>\r\n</ol>\r\n<p>- De corriente continua</p>\r\n<p>- Universales</p>\r\n<p>- De inducci&oacute;n monof&aacute;sicos: de fase partida, de condensador, de espira, sin escobillas o brushless</p>\r\n<ol start=\"2\">\r\n<li>Electrov&aacute;lvulas y bombas</li>\r\n<li>Elementos de caldeo</li>\r\n</ol>\r\n<p>4. Elementos de iluminaci&oacute;n</p>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Los alumnos iran leyendo uno a uno un apartado del tema y a continuaci&oacute;n los explicar&eacute; poniendo ejemplos para su f&aacute;cil comprensi&oacute;n.</li>\r\n<li>Una vez terminado el tema haran un resumen de &eacute;ste.</li>\r\n<li>Realizaran el ejercicio tipo test del final del tema.</li>\r\n<li>Realizaran los ejercicios correspondientes al tema.</li>\r\n</ul>\r\n<p>Cada alumno realizar&aacute; todas las tareas anteriores en su libreta de la asignatura.</p>', '<p>Aula de inform&aacute;tica:</p>\r\n<ul>\r\n<li>Ordenadores conectados en red. El aula deber&aacute; disponer de al menos del suficiente n&uacute;mero de ordenadores para que no haya m&aacute;s de dos alumnos por puesto de trabajo, aunque es recomendable que cada alumno tenga su ordenador.</li>\r\n<li>Pizarra y altavoces</li>\r\n<li>Ca&ntilde;&oacute;n para mostrar la salida del ordenador del profesor a los alumnos.</li>\r\n<li>Ordenador-servidor conectado al ca&ntilde;&oacute;n.</li>\r\n<li>Conexi&oacute;n a Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Taller:</p>\r\n<ul>\r\n<li>Ordenadores antiguos.</li>\r\n<li>Electrodom&eacute;sticos para desmontar</li>\r\n<li>Componentes sueltos.</li>\r\n<li>Herramientas de taller.</li>\r\n<li>Material de limpieza de componentes.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>En cuanto al software a utilizar:</p>\r\n<ul>\r\n<li>Sistemas operativos Microsoft Windows, GNU/Linux</li>\r\n<li>Libre Office</li>\r\n<li>Programas de simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Libro de texto &ldquo;Equipos El&eacute;ctricos y electr&oacute;nicos&rdquo;. formaci&oacute;n Profesional B&aacute;sica,</p>\r\n<p>Juan Carlos Martin. Editorial Editex&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Diversos recursos de Internet.</p>', '<ol>\r\n<li>Observaci&oacute;n directa alumno/a: motivaci&oacute;n, inter&eacute;s, actitudes, comportamiento, asistencia, etc.</li>\r\n<li>Participaci&oacute;n en clase: intervenciones sobre actividades y ejercicios propuestos, valorando su dedicaci&oacute;n e inter&eacute;s.</li>\r\n<li>Realizaci&oacute;n de actividades individuales y grupales</li>\r\n<li>Prueba escrita al final de la unidad</li>\r\n</ol>', '<p>El profesor har&aacute; una exposici&oacute;n te&oacute;rico-pr&aacute;ctica de la unidad, mostrando a los alumnos cuales son los motores y elementos de actuaci&oacute;n mayormente utilizados en equipos el&eacute;ctricos y electr&oacute;nicos y electrodom&eacute;sticos.</p>\r\n<p>Inicialmente los alumnos realizar&aacute;n, de forma individual o en grupo, la pr&aacute;ctica profesional resuelta, posteriormente las Reto profesional y por &uacute;ltimo las Eval&uacute;o mi aprendizaje de la unidad.</p>\r\n<p>Todas las actividades se realizar&aacute;n en un aula-taller dotada de bancos de trabajo.</p>\r\n<p>Posteriormente, resolver&aacute;n el TEST de la p&aacute;gina &ldquo;Eval&uacute;o mis conocimientos&rdquo; para afianzar los contenidos trabajados a lo largo de la unidad.</p>\r\n<p>A lo largo de la unidad se potenciar&aacute; la intervenci&oacute;n oral de los alumnos/as con actividades de debate, puesto que la unidad permite relacionar los conocimientos previos con los que se pretende que adquieran. Estas actividades persiguen un modelo constructivista.</p>\r\n<p>Asimismo, se potenciar&aacute; la comunicaci&oacute;n y el trabajo en equipo, la educaci&oacute;n no sexista y tolerante con otras culturas, la educaci&oacute;n para la convivencia, el uso de la lengua inglesa y los objetivos de desarrollo sostenible (ODS).</p>', '', 1, 0, 0, 1),
(90, 112, 9, 'Electrodomésticos y otros equipos', 46, 3, 17, '<p>En esta unidad vamos a ver:</p>\r\n<ul>\r\n<li>Conocer las diferentes l&iacute;neas o gamas de electrodom&eacute;sticos.</li>\r\n<li>Conocer algunos elementos comunes utilizados en los circuitos el&eacute;ctricos de los electrodom&eacute;sticos.</li>\r\n<li>Conocer qu&eacute; es y para qu&eacute; sirve un filtro antiparasitario.</li>\r\n<li>Identificar las patillas de conexi&oacute;n e un filtro antiparasitario.</li>\r\n<li>Comprobar un filtro antiparasitario.</li>\r\n<li>Conocer qu&eacute; es y para qu&eacute; sirve un blocapuertas.</li>\r\n<li>Comprobar el funcionamiento de un blocapuertas.</li>\r\n<li>Conocer qu&eacute; es y para qu&eacute; su utiliza un <em>timer</em>-programador.</li>\r\n<li>Conocer qu&eacute; es un conmutador de funciones.</li>\r\n<li>Conocer qu&eacute; es y para qu&eacute; se utiliza un presostato.</li>\r\n<li>Probar el funcionamiento de un presostato.</li>\r\n<li>Conocer qu&eacute; es y para qu&eacute; sirve un caudal&iacute;metro.</li>\r\n<li>Conocer qu&eacute; es y para qu&eacute; se utilizan los termostatos.</li>\r\n<li>Comprobar un termostato.</li>\r\n<li>Conocer los esquemas de bloques de los electrodom&eacute;sticos m&aacute;s representativos.</li>\r\n<li>Identificar en los esquemas los componentes de los electrodom&eacute;sticos por su s&iacute;mbolo.</li>\r\n<li>Conocer algunas de las partes que requieren mantenimiento en los equipos inform&aacute;ticos.</li>\r\n<li>Abrir un equipo inform&aacute;tico, sustituir sus m&oacute;dulos de memoria y su disco duro.</li>\r\n<li>Conocer c&oacute;mo son los circuitos caracter&iacute;sticos de las herramientas el&eacute;ctricas.</li>\r\n</ul>', '<p>Conocer los tipos de electrodom&eacute;sticos seg&uacute;n su clasificaci&oacute;n por gama. Ver los esquemas el&eacute;ctricos de algunos de ellos.</p>', '', '<ol>\r\n<li>Electrodom&eacute;sticos</li>\r\n</ol>\r\n<p>- L&iacute;neas de los electrodom&eacute;sticos</p>\r\n<p>- Componentes de los electrom&eacute;tricos: filtro antiparasitario, blocapuertas, timer-programador, conmutador de funciones, presostato, termostato, caudal&iacute;metro</p>\r\n<ol start=\"2\">\r\n<li>Circuitos de electrodom&eacute;sticos</li>\r\n</ol>\r\n<p>- Horno el&eacute;ctrico de cocci&oacute;n</p>\r\n<p>- Placa vitrocer&aacute;mica</p>\r\n<p>- Lavadora</p>\r\n<p>- Secadora de ropa</p>\r\n<p>- Lavavajillas</p>\r\n<p>- Plancha de tejidos</p>\r\n<p>- Plancha de alimentos</p>\r\n<ol start=\"3\">\r\n<li>Equipos inform&aacute;ticos</li>\r\n</ol>\r\n<p>- Ordenadores de sobremesa</p>\r\n<p>- Ordenadores port&aacute;tiles</p>\r\n<p>4. Herramientas el&eacute;ctricas port&aacute;tiles</p>', '<p>El desarrollo de la unidad se realizar&aacute; de la siguiente manera:</p>\r\n<ul>\r\n<li>Los alumnos iran leyendo uno a uno un apartado del tema y a continuaci&oacute;n los explicar&eacute; poniendo ejemplos para su f&aacute;cil comprensi&oacute;n.</li>\r\n<li>Una vez terminado el tema haran un resumen de &eacute;ste.</li>\r\n<li>Realizaran el ejercicio tipo test del final del tema.</li>\r\n<li>Realizaran los ejercicios correspondientes al tema.</li>\r\n</ul>\r\n<p>Cada alumno realizar&aacute; todas las tareas anteriores en su libreta de la asignatura.</p>', '<p>Aula de inform&aacute;tica:</p>\r\n<ul>\r\n<li>Ordenadores conectados en red. El aula deber&aacute; disponer de al menos del suficiente n&uacute;mero de ordenadores para que no haya m&aacute;s de dos alumnos por puesto de trabajo, aunque es recomendable que cada alumno tenga su ordenador.</li>\r\n<li>Pizarra y altavoces</li>\r\n<li>Ca&ntilde;&oacute;n para mostrar la salida del ordenador del profesor a los alumnos.</li>\r\n<li>Ordenador-servidor conectado al ca&ntilde;&oacute;n.</li>\r\n<li>Conexi&oacute;n a Internet.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Taller:</p>\r\n<ul>\r\n<li>Ordenadores antiguos.</li>\r\n<li>Electrodom&eacute;sticos para desmontar</li>\r\n<li>Componentes sueltos.</li>\r\n<li>Herramientas de taller.</li>\r\n<li>Material de limpieza de componentes.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>En cuanto al software a utilizar:</p>\r\n<ul>\r\n<li>Sistemas operativos Microsoft Windows, GNU/Linux</li>\r\n<li>Libre Office</li>\r\n<li>Programas de simulaci&oacute;n de circuitos el&eacute;ctricos y electr&oacute;nicos.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<p>Libro de texto &ldquo;Equipos El&eacute;ctricos y electr&oacute;nicos&rdquo;. formaci&oacute;n Profesional B&aacute;sica,</p>\r\n<p>Juan Carlos Martin. Editorial Editex&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Diversos recursos de Internet.</p>', '<ol>\r\n<li>Observaci&oacute;n directa alumno/a: motivaci&oacute;n, inter&eacute;s, actitudes, comportamiento, asistencia, etc.</li>\r\n<li>Participaci&oacute;n en clase: intervenciones sobre actividades y ejercicios propuestos, valorando su dedicaci&oacute;n e inter&eacute;s.</li>\r\n<li>Realizaci&oacute;n de actividades individuales y grupales</li>\r\n<li>Prueba escrita al final de la unidad</li>\r\n</ol>', '<p>El profesor har&aacute; una exposici&oacute;n te&oacute;rico-pr&aacute;ctica de la unidad, mostrando a los alumnos algunos tipos de electrodom&eacute;sticos y los elementos que los constituyen.</p>\r\n<p>Inicialmente los alumnos realizar&aacute;n, de forma individual o en grupo, la pr&aacute;ctica profesional resuelta, posteriormente las Reto profesional y por &uacute;ltimo las Eval&uacute;o mi aprendizaje de la unidad.</p>\r\n<p>Todas las actividades se realizar&aacute;n en un aula-taller dotada de bancos de trabajo.</p>\r\n<p>Posteriormente, resolver&aacute;n el TEST de la p&aacute;gina &ldquo;Eval&uacute;o mis conocimientos&rdquo; para afianzar los contenidos trabajados a lo largo de la unidad.</p>\r\n<p>A lo largo de la unidad se potenciar&aacute; la intervenci&oacute;n oral de los alumnos/as con actividades de debate, puesto que la unidad permite relacionar los conocimientos previos con los que se pretende que adquieran. Estas actividades persiguen un modelo constructivista.</p>\r\n<p>Asimismo, se potenciar&aacute; la comunicaci&oacute;n y el trabajo en equipo, la educaci&oacute;n no sexista y tolerante con otras culturas, la educaci&oacute;n para la convivencia, el uso de la lengua inglesa y los objetivos de desarrollo sostenible (ODS).</p>', '', 1, 0, 0, 1),
(101, 8, 5, 'Administración de sistemas operativos Windows y Linux ', 35, 2, 15, '<p>Esta unidad profundiza en las tareas de administraci&oacute;n de sistemas tanto en entornos Windows como Linux, abordando la gesti&oacute;n del rendimiento del sistema, la monitorizaci&oacute;n y seguridad b&aacute;sica.</p>', '<p>Administrar de manera eficiente los recursos y servicios de un sistema operativo garantiza su funcionamiento &oacute;ptimo, estabilidad y seguridad, lo que constituye una competencia esencial para t&eacute;cnicos y administradores de sistemas.</p>', '', '<ul>\r\n<li class=\"p1\">Herramientas de monitorizaci&oacute;n en tiempo real.</li>\r\n<li class=\"p1\">Herramientas de monitorizaci&oacute;n continuada.</li>\r\n<li class=\"p1\">Herramientas de an&aacute;lisis del rendimiento.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li class=\"p1\">Requisitos de seguridad del sistema y de los datos.</li>\r\n<li class=\"p1\">\r\n<p class=\"p1\">Extensi&oacute;n de un volumen. Vol&uacute;menes distribuidos. RAID0 por software.</p>\r\n</li>\r\n<li class=\"p1\">\r\n<p class=\"p1\">Tolerancia a fallos de hardware. RAID1 y RAID5 por software.</p>\r\n</li>\r\n<li class=\"p1\">\r\n<p class=\"p1\">Tolerancia a fallos de software de los datos.</p>\r\n</li>\r\n<li class=\"p1\">Recuperaci&oacute;n en caso de fallo del sistema. Discos de recuperaci&oacute;n.</li>\r\n<li class=\"p1\">Recuperaci&oacute;n del sistema mediante consola.</li>\r\n<li class=\"p1\">Puntos de recuperaci&oacute;n.</li>\r\n<li class=\"p1\">Partes de incidencias.</li>\r\n<li class=\"p1\">Protocolos de actuaci&oacute;n.</li>\r\n<li class=\"p1\">Administraci&oacute;n remota.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li class=\"p1\">Derechos de usuario.</li>\r\n<li class=\"p1\">Directivas de seguridad local.</li>\r\n<li class=\"p1\">Registro del sistema operativo.</li>\r\n<li class=\"p1\">Objetivos de la auditor&iacute;a.</li>\r\n<li class=\"p1\">&Aacute;mbito de la auditor&iacute;a. Aspectos auditables.</li>\r\n<li class=\"p1\">Mecanismos de auditor&iacute;a. Alarmas y acciones correctivas.</li>\r\n<li class=\"p1\">Informaci&oacute;n del registro de auditor&iacute;a.</li>\r\n<li class=\"p1\">T&eacute;cnicas y herramientas de auditor&iacute;a.</li>\r\n<li class=\"p1\">Informes de auditor&iacute;a.</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li class=\"p1\">Instalaciones desatendidas.</li>\r\n<li class=\"p1\">Implementaci&oacute;n de ficheros de respuestas.</li>\r\n<li class=\"p1\">Servidores de actualizaciones autom&aacute;ticas.</li>\r\n</ul>', '<p>Abordaremos herramientas para la monitorizaci&oacute;n del sistema y an&aacute;lisis del rendimiento</p>\r\n<p>Mecanismos de seguridad y redundancia:</p>\r\n<ul>\r\n<li>Sistema RAID</li>\r\n<li>Copias de seguridad y recuperaci&oacute;n del sistema.</li>\r\n<li>Seguridad b&aacute;sica: permisos, actualizaciones y pol&iacute;ticas de seguridad.</li>\r\n<li>Herramientas de administraci&oacute;n remota.</li>\r\n</ul>\r\n<p>Mecanismos de auditor&iacute;a</p>\r\n<p>Mecanismos de optimizaci&oacute;n de instalaciones y actualizaciones</p>', '', '<ul>\r\n<li>La evaluaci&oacute;n de cada unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para el mismo.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:&nbsp;</li>\r\n<ul>\r\n<li><strong>ejercicios de clase:&nbsp;</strong>ser&aacute;n tareas realizadas en el transcurso de clase destinadas a la comprensi&oacute;n de conceptos te&oacute;ricos y pr&aacute;cticos fundamentales.</li>\r\n<li><strong>cuestionarios</strong>: permiten la autoevaluaci&oacute;n por parte del alumno/a de los conceptos vistos en la unidad.</li>\r\n<li><strong>pr&aacute;cticas individuales y grupales</strong>: est&aacute;n orientadas a profundizar y facilitar en la adquisici&oacute;n de los conceptos y destrezas pr&aacute;cticas planteadas en la unidad. Algunas de estas actividades podr&aacute; requerir defensa presencial o exposici&oacute;n oral.</li>\r\n<li><strong>proyectos individuales y grupales:&nbsp;</strong>permiten trabajar los resultados de aprendizaje vistos en varias unidades de manera transversal. En este caso, se puede solicitar la defensa y exposici&oacute;n oral de manera presencial y/o a trav&eacute;s de un videotutorial o videoconferencia, si la profesora lo considera necesario.</li>\r\n<li><strong>pruebas objetivas</strong>: permiten la evaluaci&oacute;n de los resultados de aprendizaje trabajados en la unidad en una &uacute;nica prueba realizada en clase.</li>\r\n</ul>\r\n</ul>\r\n<ul>\r\n<li><strong>En caso de que en la unidad se incluya la realizaci&oacute;n de una prueba objetiva (examen y/o exposici&oacute;n de proyecto final), se aplicar&aacute; </strong>la baremaci&oacute;n siguiente en la puntuaci&oacute;n obtenida en la unidad, siempre y cuando se supere una calificaci&oacute;n m&iacute;nima de 5 en la prueba objetiva:</li>\r\n<ul>\r\n<li>60% prueba objetiva (presencial)</li>\r\n<li>40% pr&aacute;cticas obligatorias/proyectos/ejercicios en clase</li>\r\n</ul>\r\n</ul>\r\n<p><strong>Consideraciones sobre los instrumentos de evaluaci&oacute;n de la unidad:</strong></p>\r\n<ul>\r\n<li>En aquellas pr&aacute;cticas y/o proyectos que se realicen de manera grupal, la calificaci&oacute;n podr&aacute; contar con una&nbsp;<strong>puntuaci&oacute;n individual y colectiva</strong>&nbsp;que permita valorar tanto la aportaci&oacute;n individual de cada alumno como el resultado global obtenido por el grupo, para obtener la calificaci&oacute;n final.</li>\r\n<li>Se podr&aacute;&nbsp;<strong>penalizar&nbsp;la&nbsp;calificaci&oacute;n</strong>&nbsp;m&aacute;xima de las pr&aacute;cticas entregadas con retraso o entregadas para recuperar una pr&aacute;ctica suspendida.</li>\r\n<li>La profesora se&nbsp;<strong>reserva el derecho a convocar al alumno&nbsp;</strong>para en caso de duda, poder&nbsp;<strong>comprobar los conceptos evaluados en las pr&aacute;cticas, proyectos o ejercicios</strong>.</li>\r\n</ul>', '', '', 1, 1, 1, 1),
(102, 8, 6, 'Administración de dominios y recursos compartidos', 35, 3, 15, '<p>En esta unidad se abordan los conceptos de redes de dominio, controladores de dominio, autenticaci&oacute;n centralizada y la gesti&oacute;n de recursos compartidos en entornos corporativos.</p>', '<p>La administraci&oacute;n de dominios y recursos compartidos es clave en infraestructuras empresariales, donde se requiere control centralizado de usuarios, pol&iacute;ticas y recursos para garantizar eficiencia, seguridad y colaboraci&oacute;n.</p>', '', '<ul>\r\n<li class=\"p1\">\r\n<p class=\"p1\">Licencias de cliente y licencias de servidor.</p>\r\n</li>\r\n<li class=\"p1\">Estructura cliente-servidor.</li>\r\n<li class=\"p1\">Protocolo LDAP.</li>\r\n<li class=\"p1\">Concepto de dominio. Subdominios. Requisitos necesarios para montar un dominio.</li>\r\n<li class=\"p1\">Administraci&oacute;n de cuentas. Cuentas predeterminadas.</li>\r\n<li class=\"p1\">Contrase&ntilde;as. Bloqueos de cuenta.</li>\r\n<li class=\"p1\">Cuentas de usuarios y equipos.</li>\r\n<li class=\"p1\">Perfiles m&oacute;viles y obligatorios.</li>\r\n<li class=\"p1\">Carpetas personales.</li>\r\n<li class=\"p1\">Plantillas de usuario. Variables de entorno.</li>\r\n<li class=\"p1\">Administraci&oacute;n de grupos. Tipos. Estrategias de anidamiento. Grupos predeterminados.</li>\r\n<li class=\"p1\">Administraci&oacute;n del acceso al dominio:</li>\r\n<li class=\"p1\">Equipos del dominio.</li>\r\n<li class=\"p1\">Permisos y derechos.</li>\r\n<li class=\"p1\">Administraci&oacute;n del acceso a recursos. SAMBA. NFS.</li>\r\n<li class=\"p1\">Permisos de red. Permisos locales. Herencia. Permisos efectivos.</li>\r\n<li class=\"p1\">Delegaci&oacute;n de permisos.</li>\r\n<li class=\"p1\">Listas de control de acceso.</li>\r\n<li class=\"p1\">Directivas de grupo. Derechos de usuarios. Directivas de seguridad. Objetos de directiva.</li>\r\n<li class=\"p1\">&Aacute;mbito de las directivas. Plantillas.</li>\r\n<li class=\"p1\">Cuotas de disco. Niveles de cuota y niveles de advertencia.</li>\r\n</ul>', '<ul>\r\n<li>Conceptos de dominio, grupo de trabajo y directorio activo.</li>\r\n<li>Instalaci&oacute;n y configuraci&oacute;n de controladores de dominio.</li>\r\n<li>Creaci&oacute;n y administraci&oacute;n de usuarios, grupos y pol&iacute;ticas.</li>\r\n<li>Compartici&oacute;n de recursos (carpetas, impresoras, unidades de red).</li>\r\n<li>Configuraci&oacute;n de cuotas y listas de control de acceso</li>\r\n<li>Permisos y control de acceso en red.</li>\r\n<li>Perfiles m&oacute;viles y scripts de inicio</li>\r\n<li>Administraci&oacute;n de pol&iacute;ticas de grupo (GPO).</li>\r\n</ul>', '', '<ul>\r\n<li>La evaluaci&oacute;n de cada unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para el mismo.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:&nbsp;</li>\r\n<ul>\r\n<li><strong>ejercicios de clase:&nbsp;</strong>ser&aacute;n tareas realizadas en el transcurso de clase destinadas a la comprensi&oacute;n de conceptos te&oacute;ricos y pr&aacute;cticos fundamentales.</li>\r\n<li><strong>cuestionarios</strong>: permiten la autoevaluaci&oacute;n por parte del alumno/a de los conceptos vistos en la unidad.</li>\r\n<li><strong>pr&aacute;cticas individuales y grupales</strong>: est&aacute;n orientadas a profundizar y facilitar en la adquisici&oacute;n de los conceptos y destrezas pr&aacute;cticas planteadas en la unidad. Algunas de estas actividades podr&aacute; requerir defensa presencial o exposici&oacute;n oral.</li>\r\n<li><strong>proyectos individuales y grupales:&nbsp;</strong>permiten trabajar los resultados de aprendizaje vistos en varias unidades de manera transversal. En este caso, se puede solicitar la defensa y exposici&oacute;n oral de manera presencial y/o a trav&eacute;s de un videotutorial o videoconferencia, si la profesora lo considera necesario.</li>\r\n<li><strong>pruebas objetivas</strong>: permiten la evaluaci&oacute;n de los resultados de aprendizaje trabajados en la unidad en una &uacute;nica prueba realizada en clase.</li>\r\n</ul>\r\n</ul>\r\n<ul>\r\n<li><strong>En caso de que en la unidad se incluya la realizaci&oacute;n de una prueba objetiva (examen y/o exposici&oacute;n de proyecto final), se aplicar&aacute; </strong>la baremaci&oacute;n siguiente en la puntuaci&oacute;n obtenida en la unidad, siempre y cuando se supere una calificaci&oacute;n m&iacute;nima de 5 en la prueba objetiva:</li>\r\n<ul>\r\n<li>60% prueba objetiva (presencial)</li>\r\n<li>40% pr&aacute;cticas obligatorias/proyectos/ejercicios en clase</li>\r\n</ul>\r\n</ul>\r\n<p><strong>Consideraciones sobre los instrumentos de evaluaci&oacute;n de la unidad:</strong></p>\r\n<ul>\r\n<li>En aquellas pr&aacute;cticas y/o proyectos que se realicen de manera grupal, la calificaci&oacute;n podr&aacute; contar con una&nbsp;<strong>puntuaci&oacute;n individual y colectiva</strong>&nbsp;que permita valorar tanto la aportaci&oacute;n individual de cada alumno como el resultado global obtenido por el grupo, para obtener la calificaci&oacute;n final.</li>\r\n<li>Se podr&aacute;&nbsp;<strong>penalizar&nbsp;la&nbsp;calificaci&oacute;n</strong>&nbsp;m&aacute;xima de las pr&aacute;cticas entregadas con retraso o entregadas para recuperar una pr&aacute;ctica suspendida.</li>\r\n<li>La profesora se&nbsp;<strong>reserva el derecho a convocar al alumno&nbsp;</strong>para en caso de duda, poder&nbsp;<strong>comprobar los conceptos evaluados en las pr&aacute;cticas, proyectos o ejercicios</strong>.</li>\r\n</ul>', '', '', 1, 1, 1, 1),
(103, 8, 7, 'Proyecto administración de sistemas ', 36, 3, 10, '', '', '', '', '', '', '', '', '', 1, 1, 1, 1),
(106, 315, 1, 'Warm Up', 16, 1, 5, '<p>Puesta a punto de Windows/Linux y servicios b&aacute;sicos (NAT, RDP/SSH, DHCP, DNS, Web, Correo, AWS).</p>', '<p>Sienta los cimientos t&eacute;cnicos para todo el curso y estandariza el entorno de laboratorio.</p>', '', '<ol>\r\n<li>Virtualizaci&oacute;n de m&aacute;quinas</li>\r\n<li>Instalaci&oacute;n de Kali Linux</li>\r\n<li>Virtualizaci&oacute;n de redes p&uacute;blicas y privadas</li>\r\n<li>Servicios en red</li>\r\n</ol>', '<p>Breve teor&iacute;a de redes/servicios y buenas pr&aacute;cticas &rarr; instalaciones guiadas (Windows Server, Ubuntu, Rocky, Kali) &rarr; NAT y redirecciones &rarr; RDP/SSH/2FA y t&uacute;neles controlados &rarr; montaje de DHCP/DNS &rarr; HTTP(S) en IIS/Apache/Tomcat con TLS &rarr; correo (Postfix/Dovecot, AV/antispam) &rarr; primeras instancias y VPC en AWS.</p>', '', '<p>La calificaci&oacute;n final de la unidad se calcular&aacute; como la media aritm&eacute;tica de las calificaciones obtenidas en todas las pr&aacute;cticas.</p>', '', '', 1, 1, 1, 1),
(119, 406, 1, 'Economías Lineal y Circular', 4, 1, 20, '<p data-start=\"315\" data-end=\"781\">En esta primera unidad did&aacute;ctica, el alumnado se introduce en los conceptos fundamentales de las <strong data-start=\"412\" data-end=\"443\">econom&iacute;as lineal y circular</strong>, comprendiendo sus diferencias, implicaciones y repercusiones en el sistema productivo actual. A trav&eacute;s del estudio comparativo de ambos modelos, se analizan los <strong data-start=\"606\" data-end=\"642\">procesos de producci&oacute;n y consumo</strong>, las <strong data-start=\"648\" data-end=\"681\">estrategias de sostenibilidad</strong>, y la forma en que las empresas pueden adaptarse a modelos m&aacute;s responsables con el medioambiente.</p>\r\n<p data-start=\"783\" data-end=\"1270\">El desarrollo de la unidad permitir&aacute; al alumnado <strong data-start=\"832\" data-end=\"863\">identificar ejemplos reales</strong> de empresas que aplican tanto la econom&iacute;a lineal como la circular, reflexionando sobre las <strong data-start=\"955\" data-end=\"1007\">consecuencias sociales, ambientales y econ&oacute;micas</strong> de cada modelo. Se abordar&aacute; tambi&eacute;n el papel de la <strong data-start=\"1059\" data-end=\"1103\">responsabilidad social corporativa (RSC)</strong> y su influencia en la transformaci&oacute;n hacia sistemas m&aacute;s sostenibles, as&iacute; como la <strong data-start=\"1185\" data-end=\"1233\">importancia del reciclaje y la reutilizaci&oacute;n</strong> dentro de las cadenas productivas.</p>\r\n<p data-start=\"1272\" data-end=\"1543\">La unidad combina contenidos te&oacute;ricos con el an&aacute;lisis de <strong data-start=\"1329\" data-end=\"1359\">casos pr&aacute;cticos y actuales</strong>, fomentando la comprensi&oacute;n de c&oacute;mo los <strong data-start=\"1399\" data-end=\"1443\">Objetivos de Desarrollo Sostenible (ODS)</strong> se relacionan directamente con la digitalizaci&oacute;n y con la transici&oacute;n hacia una econom&iacute;a circular.</p>', '<p data-start=\"1576\" data-end=\"1978\">Esta unidad resulta esencial para contextualizar el m&oacute;dulo, ya que ofrece una <strong data-start=\"1654\" data-end=\"1713\">visi&oacute;n global de la transformaci&oacute;n digital y sostenible</strong> que caracteriza la actual cuarta revoluci&oacute;n industrial. Antes de abordar tecnolog&iacute;as habilitadoras o procesos de digitalizaci&oacute;n, el alumnado necesita comprender los <strong data-start=\"1879\" data-end=\"1924\">fundamentos econ&oacute;micos y medioambientales</strong> que impulsan el cambio en los sectores productivos.</p>\r\n<p data-start=\"1980\" data-end=\"2436\">El an&aacute;lisis de la econom&iacute;a lineal frente a la econom&iacute;a circular permite reflexionar sobre <strong data-start=\"2070\" data-end=\"2105\">modelos de consumo responsables</strong>, la <strong data-start=\"2110\" data-end=\"2146\">eficiencia en el uso de recursos</strong> y la necesidad de aplicar la <strong data-start=\"2176\" data-end=\"2235\">innovaci&oacute;n tecnol&oacute;gica al servicio de la sostenibilidad</strong>. Esta perspectiva es clave para los futuros profesionales del &aacute;mbito inform&aacute;tico, que deber&aacute;n participar en la <strong data-start=\"2347\" data-end=\"2406\">digitalizaci&oacute;n de procesos industriales y empresariales</strong> respetuosos con el entorno.</p>\r\n<p data-start=\"2438\" data-end=\"2913\">Asimismo, la unidad favorece la <strong data-start=\"2470\" data-end=\"2519\">conciencia medioambiental y &eacute;tica profesional</strong> del alumnado, promoviendo actitudes responsables hacia el uso de los recursos tecnol&oacute;gicos y energ&eacute;ticos. Al relacionar estos contenidos con los <strong data-start=\"2665\" data-end=\"2712\">ODS y la responsabilidad social corporativa</strong>, se sientan las bases para entender el papel que la digitalizaci&oacute;n desempe&ntilde;a en la <strong data-start=\"2796\" data-end=\"2820\">transici&oacute;n ecol&oacute;gica</strong> de las empresas y en el cumplimiento de los compromisos internacionales de sostenibilidad.</p>', '', '<p>Econom&iacute;as lineal y circular. <br />Modelos de empresas basados en las econom&iacute;as lineal y circular. <br />Responsabilidad social: modelos de empresas y afectaci&oacute;n del medioambiente. <br />Importancia del reciclaje en los modelos econ&oacute;micos. <br />Procesos reales basados en la econom&iacute;a lineal. <br />Procesos reales basados en la econom&iacute;a circular. <br />Comparativa de los modelos en relaci&oacute;n con su impacto medioambiental y los objetivos de desarrollo sostenible.</p>', '<p>Econom&iacute;a lineal (EL) y econom&iacute;a circular (EC) <br />1. La econom&iacute;a lineal: un trayecto unidireccional en un mundo de recursos finitos <br />2. Un futuro sostenible: econom&iacute;a circular, redefiniendo la forma en que consumimos <br />3. Ventajas ambientales, sociales y econ&oacute;micas de la econom&iacute;a circular</p>', '', '<p style=\"text-align: justify;\">La calificaci&oacute;n de cada evaluaci&oacute;n o bloque coincidir&aacute; con la media de las calificaciones obtenidas en cada una de las partes que a continuaci&oacute;n se indican: <br />40% En las pruebas escritas (ex&aacute;menes). Resoluci&oacute;n de problemas. Preguntas de desarrollo. Preguntas tipo test. <br />60% En los ejercicios pr&aacute;cticos. Observaci&oacute;n diaria. Desarrollo y elaboraci&oacute;n, individual o en grupo de casos pr&aacute;cticos. Entrega de trabajos en los plazos convenidos. Exposici&oacute;n del trabajo en un tiempo predeterminado. Resoluci&oacute;n de casos pr&aacute;cticos.</p>\r\n<p style=\"text-align: justify;\">Es condici&oacute;n necesaria para aprobar un bloque que se alcance una nota m&iacute;nima de 5. De no ser as&iacute;, se considerar&aacute; que el bloque no ha sido superado y ser&aacute; necesaria la recuperaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">Respecto a las pruebas escritas y los ejercicios pr&aacute;cticos, se calcula como la media ponderada de las actividades, pruebas o pr&aacute;cticas realizadas durante la unidad. Aunque si alguna&nbsp;pr&aacute;ctica es de nivel m&aacute;s complicado o requiere m&aacute;s trabajo que el resto, se avisar&aacute; con antelaci&oacute;n al alumnado del porcentaje en el tema.</p>', '', '', 1, 1, 1, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(120, 406, 2, 'La cuarta revolución industrial', 4, 1, 20, '<p data-start=\"320\" data-end=\"809\">En esta unidad did&aacute;ctica, el alumnado profundiza en el concepto de la <strong data-start=\"390\" data-end=\"422\">Cuarta Revoluci&oacute;n Industrial</strong> o <strong data-start=\"425\" data-end=\"442\">Industria 4.0</strong>, comprendiendo su origen, evoluci&oacute;n y el impacto que est&aacute; generando en los procesos productivos, las empresas y la sociedad. Se analizan los <strong data-start=\"584\" data-end=\"609\">sistemas ciberf&iacute;sicos</strong> como base de esta transformaci&oacute;n, junto con la integraci&oacute;n entre el <strong data-start=\"678\" data-end=\"707\">mundo f&iacute;sico y el digital</strong> mediante el uso de sensores, automatizaci&oacute;n, inteligencia artificial, rob&oacute;tica y an&aacute;lisis de datos.</p>\r\n<p data-start=\"811\" data-end=\"1294\">La unidad aborda los <strong data-start=\"832\" data-end=\"885\">cambios provocados por los sistemas automatizados</strong> en la gesti&oacute;n y producci&oacute;n industrial, as&iacute; como las <strong data-start=\"938\" data-end=\"981\">ventajas de la migraci&oacute;n a entornos 4.0</strong>, que permiten optimizar la eficiencia, reducir costes y mejorar la calidad de los productos y servicios. Tambi&eacute;n se reflexiona sobre los beneficios que estos avances aportan tanto a las <strong data-start=\"1168\" data-end=\"1200\">empresas como a los clientes</strong>, destacando la personalizaci&oacute;n, la sostenibilidad y la toma de decisiones basadas en datos.</p>\r\n<p data-start=\"1296\" data-end=\"1578\">Mediante ejemplos pr&aacute;cticos y casos reales, el alumnado conocer&aacute; c&oacute;mo la digitalizaci&oacute;n est&aacute; transformando los distintos sectores productivos, y adquirir&aacute; una visi&oacute;n global del papel de las tecnolog&iacute;as emergentes en el desarrollo de una econom&iacute;a inteligente, conectada y sostenible.</p>', '<p data-start=\"1611\" data-end=\"2018\">Esta unidad se justifica como un <strong data-start=\"1644\" data-end=\"1665\">pilar fundamental</strong> dentro del m&oacute;dulo, ya que permite comprender el <strong data-start=\"1714\" data-end=\"1750\">contexto tecnol&oacute;gico y econ&oacute;mico</strong> en el que se desarrolla la actual digitalizaci&oacute;n de los sectores productivos. Antes de abordar las tecnolog&iacute;as espec&iacute;ficas o las estrategias de transformaci&oacute;n digital, el alumnado debe conocer los <strong data-start=\"1948\" data-end=\"1980\">principios, causas y efectos</strong> de la Cuarta Revoluci&oacute;n Industrial.</p>\r\n<p data-start=\"2020\" data-end=\"2499\">El estudio de la Industria 4.0 proporciona las bases necesarias para entender c&oacute;mo la <strong data-start=\"2106\" data-end=\"2211\">automatizaci&oacute;n, la inteligencia artificial, el Internet de las Cosas (IoT), la rob&oacute;tica o el Big Data</strong> est&aacute;n modificando radicalmente la forma de producir, gestionar y consumir. Esta comprensi&oacute;n resulta esencial para los futuros t&eacute;cnicos en sistemas microinform&aacute;ticos y redes, ya que ser&aacute;n parte activa en la <strong data-start=\"2418\" data-end=\"2496\">implantaci&oacute;n y mantenimiento de infraestructuras digitales y automatizadas</strong>.</p>\r\n<p data-start=\"2501\" data-end=\"2966\">Asimismo, esta unidad contribuye a desarrollar una <strong data-start=\"2552\" data-end=\"2583\">actitud cr&iacute;tica y reflexiva</strong> ante los retos y oportunidades de la digitalizaci&oacute;n, fomentando la <strong data-start=\"2651\" data-end=\"2684\">adaptabilidad y la innovaci&oacute;n</strong> como competencias clave del siglo XXI. La conexi&oacute;n con los <strong data-start=\"2744\" data-end=\"2782\">Objetivos de Desarrollo Sostenible</strong> refuerza adem&aacute;s la visi&oacute;n &eacute;tica y responsable de la tecnolog&iacute;a, mostrando c&oacute;mo la Industria 4.0 puede impulsar una econom&iacute;a m&aacute;s <strong data-start=\"2911\" data-end=\"2963\">eficiente, sostenible y centrada en las personas</strong>.</p>', '', '<p>1. Sistemas ciberf&iacute;sicos. Relaci&oacute;n con la evoluci&oacute;n industrial <br />2. Sistemas automatizados. Cambios provocados por la cuarta revoluci&oacute;n <br />3. Interrelaci&oacute;n entre el mundo f&iacute;sico y el virtual <br />4. Ventajas de la migraci&oacute;n a entornos 4.0 con la mejora de resultados de las empresas <br />5. Ventajas de la 4.&ordf; revoluci&oacute;n industrial para clientes y empresas</p>', '<p>La cuarta revoluci&oacute;n industrial (EC) <br />1. La cuarta revoluci&oacute;n industrial: transformando el futuro de la sociedad <br />2. Las tecnolog&iacute;as clave de la cuarta revoluci&oacute;n industrial y su impacto en los sectores productivos <br />3. Las transformaciones en los modelos de negocio y en la forma de trabajar</p>', '', '<p style=\"text-align: justify;\">La calificaci&oacute;n de cada evaluaci&oacute;n o bloque coincidir&aacute; con la media de las calificaciones obtenidas en cada una de las partes que a continuaci&oacute;n se indican: <br />40% En las pruebas escritas (ex&aacute;menes). Resoluci&oacute;n de problemas. Preguntas de desarrollo. Preguntas tipo test. <br />60% En los ejercicios pr&aacute;cticos. Observaci&oacute;n diaria. Desarrollo y elaboraci&oacute;n, individual o en grupo de casos pr&aacute;cticos. Entrega de trabajos en los plazos convenidos. Exposici&oacute;n del trabajo en un tiempo predeterminado. Resoluci&oacute;n de casos pr&aacute;cticos.</p>\r\n<p style=\"text-align: justify;\">Es condici&oacute;n necesaria para aprobar un bloque que se alcance una nota m&iacute;nima de 5. De no ser as&iacute;, se considerar&aacute; que el bloque no ha sido superado y ser&aacute; necesaria la recuperaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">Respecto a las pruebas escritas y los ejercicios pr&aacute;cticos, se calcula como la media ponderada de las actividades, pruebas o pr&aacute;cticas realizadas durante la unidad. Aunque si alguna&nbsp;pr&aacute;ctica es de nivel m&aacute;s complicado o requiere m&aacute;s trabajo que el resto, se avisar&aacute; con antelaci&oacute;n al alumnado del porcentaje en el tema.</p>', '', '', 1, 1, 1, 1),
(121, 406, 3, 'Cloud y sistemas conectados', 4, 2, 20, '<p data-start=\"342\" data-end=\"758\">En esta unidad did&aacute;ctica, el alumnado se adentra en el concepto de <strong data-start=\"409\" data-end=\"453\">computaci&oacute;n en la nube (cloud computing)</strong> y su papel clave en la digitalizaci&oacute;n de los sectores productivos. Se estudian los <strong data-start=\"537\" data-end=\"570\">niveles y modelos de servicio</strong> (IaaS, PaaS y SaaS), as&iacute; como las distintas <strong data-start=\"615\" data-end=\"637\">tipolog&iacute;as de nube</strong> (p&uacute;blica, privada, h&iacute;brida y comunitaria), analizando sus caracter&iacute;sticas, ventajas e implicaciones para las empresas.</p>\r\n<p data-start=\"760\" data-end=\"1223\">La unidad explora las <strong data-start=\"782\" data-end=\"832\">posibilidades que ofrece el trabajo en la nube</strong>, como el acceso remoto, la colaboraci&oacute;n en tiempo real o la disponibilidad permanente de los recursos. Adem&aacute;s, se aborda la relaci&oacute;n entre la <strong data-start=\"975\" data-end=\"1013\">cloud y las tecnolog&iacute;as emergentes</strong> que ampl&iacute;an su alcance, como el <strong data-start=\"1046\" data-end=\"1064\">edge computing</strong>, el <strong data-start=\"1069\" data-end=\"1086\">fog computing</strong> y el <strong data-start=\"1092\" data-end=\"1110\">mist computing</strong>, destacando su funci&oacute;n en la optimizaci&oacute;n de procesos y en la reducci&oacute;n de la latencia en sistemas conectados.</p>\r\n<p data-start=\"1225\" data-end=\"1556\">Finalmente, el alumnado reflexionar&aacute; sobre las <strong data-start=\"1272\" data-end=\"1336\">ventajas del uso de la cloud en la productividad empresarial</strong>, su <strong data-start=\"1341\" data-end=\"1371\">impacto en la rentabilidad</strong> y en la <strong data-start=\"1380\" data-end=\"1405\">eficiencia energ&eacute;tica</strong>, comprendiendo c&oacute;mo la adopci&oacute;n de soluciones cloud contribuye a mejorar la competitividad, la flexibilidad y la sostenibilidad de las organizaciones.</p>', '<p data-start=\"1589\" data-end=\"2026\">Esta unidad resulta fundamental dentro del m&oacute;dulo, ya que proporciona las bases para entender <strong data-start=\"1683\" data-end=\"1756\">la infraestructura tecnol&oacute;gica que sostiene la digitalizaci&oacute;n moderna</strong>. En un contexto empresarial cada vez m&aacute;s interconectado, la computaci&oacute;n en la nube constituye la <strong data-start=\"1854\" data-end=\"1913\">columna vertebral de los sistemas productivos digitales</strong>, permitiendo el almacenamiento, la gesti&oacute;n y el procesamiento de datos de forma escalable, segura y eficiente.</p>\r\n<p data-start=\"2028\" data-end=\"2497\">El estudio del <strong data-start=\"2043\" data-end=\"2062\">cloud computing</strong> y de sus tecnolog&iacute;as asociadas (edge, fog y mist) ayuda al alumnado a comprender c&oacute;mo se construyen y despliegan los servicios digitales en la actualidad, as&iacute; como las <strong data-start=\"2231\" data-end=\"2286\">tendencias hacia sistemas distribuidos y conectados</strong> que caracterizan la industria 4.0. Adem&aacute;s, favorece la adquisici&oacute;n de una <strong data-start=\"2361\" data-end=\"2391\">visi&oacute;n pr&aacute;ctica y aplicada</strong> de los recursos tecnol&oacute;gicos que las empresas utilizan para optimizar sus operaciones y reducir costes.</p>\r\n<p data-start=\"2499\" data-end=\"3094\">Desde el punto de vista formativo, esta unidad fomenta competencias esenciales del perfil profesional del t&eacute;cnico en sistemas microinform&aacute;ticos y redes, como la <strong data-start=\"2660\" data-end=\"2710\">adaptabilidad a entornos de trabajo en la nube</strong>, la <strong data-start=\"2715\" data-end=\"2771\">comprensi&oacute;n de infraestructuras digitales conectadas</strong> y la <strong data-start=\"2777\" data-end=\"2864\">valoraci&oacute;n cr&iacute;tica de la tecnolog&iacute;a como herramienta de eficiencia y sostenibilidad</strong>. Tambi&eacute;n contribuye a sensibilizar al alumnado sobre el papel de la <strong data-start=\"2933\" data-end=\"2983\">cloud en la transformaci&oacute;n digital responsable</strong>, en l&iacute;nea con los <strong data-start=\"3002\" data-end=\"3040\">Objetivos de Desarrollo Sostenible</strong> y las estrategias de innovaci&oacute;n tecnol&oacute;gica actuales.</p>', '', '<p>1. Cloud. Definici&oacute;n y niveles <br />2. Posibilidades del trabajo en la cloud <br />3. Edge computing y su relaci&oacute;n con la cloud <br />4. Fog y mist. Relaci&oacute;n con la cloud <br />5. Ventajas del uso de los recursos de la cloud <br />6. Uso de la cloud y la rentabilidad de la empresa</p>', '<p>Sistemas basados en la nube <br />1. Cloud computing: conceptos b&aacute;sicos <br />2. Arquitecturas y servicios esenciales en la nube</p>', '', '<p style=\"text-align: justify;\">La calificaci&oacute;n de cada evaluaci&oacute;n o bloque coincidir&aacute; con la media de las calificaciones obtenidas en cada una de las partes que a continuaci&oacute;n se indican: <br />40% En las pruebas escritas (ex&aacute;menes). Resoluci&oacute;n de problemas. Preguntas de desarrollo. Preguntas tipo test. <br />60% En los ejercicios pr&aacute;cticos. Observaci&oacute;n diaria. Desarrollo y elaboraci&oacute;n, individual o en grupo de casos pr&aacute;cticos. Entrega de trabajos en los plazos convenidos. Exposici&oacute;n del trabajo en un tiempo predeterminado. Resoluci&oacute;n de casos pr&aacute;cticos.</p>\r\n<p style=\"text-align: justify;\">Es condici&oacute;n necesaria para aprobar un bloque que se alcance una nota m&iacute;nima de 5. De no ser as&iacute;, se considerar&aacute; que el bloque no ha sido superado y ser&aacute; necesaria la recuperaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">Respecto a las pruebas escritas y los ejercicios pr&aacute;cticos, se calcula como la media ponderada de las actividades, pruebas o pr&aacute;cticas realizadas durante la unidad. Aunque si alguna&nbsp;pr&aacute;ctica es de nivel m&aacute;s complicado o requiere m&aacute;s trabajo que el resto, se avisar&aacute; con antelaci&oacute;n al alumnado del porcentaje en el tema.</p>', '', '', 1, 1, 1, 1),
(122, 406, 4, 'Características de los sistemas de producción', 4, 2, 20, '<p data-start=\"360\" data-end=\"663\">En esta unidad did&aacute;ctica, el alumnado profundiza en las <strong data-start=\"416\" data-end=\"491\">caracter&iacute;sticas y funcionamiento de los sistemas de producci&oacute;n actuales</strong>, comprendiendo el papel que desempe&ntilde;an las <strong data-start=\"535\" data-end=\"580\">tecnolog&iacute;as digitales habilitadoras (TDH)</strong> en la mejora de la productividad, la eficiencia y la competitividad empresarial.</p>\r\n<p data-start=\"665\" data-end=\"1194\">A lo largo de la unidad se estudian las <strong data-start=\"705\" data-end=\"746\">principales tecnolog&iacute;as habilitadoras</strong>, como la <strong data-start=\"756\" data-end=\"895\">inteligencia artificial, el Internet de las Cosas (IoT), la rob&oacute;tica colaborativa, el Big Data, la realidad aumentada o la impresi&oacute;n 3D</strong>, analizando sus <strong data-start=\"912\" data-end=\"958\">caracter&iacute;sticas, aplicaciones y beneficios</strong> en entornos industriales y de servicios. Se abordar&aacute; adem&aacute;s la <strong data-start=\"1022\" data-end=\"1095\">relaci&oacute;n directa entre la implantaci&oacute;n tecnol&oacute;gica y la productividad</strong>, as&iacute; como su impacto en la <strong data-start=\"1123\" data-end=\"1157\">reducci&oacute;n de costes operativos</strong> y la <strong data-start=\"1163\" data-end=\"1191\">optimizaci&oacute;n de procesos</strong>.</p>\r\n<p data-start=\"1196\" data-end=\"1672\">El alumnado conocer&aacute; <strong data-start=\"1217\" data-end=\"1262\">ejemplos reales de sistemas digitalizados</strong> que ilustran la transformaci&oacute;n hacia modelos de producci&oacute;n inteligentes y flexibles, as&iacute; como <strong data-start=\"1357\" data-end=\"1393\">casos de tecnolog&iacute;as disruptivas</strong> que han modificado de forma radical la manera de producir, almacenar y gestionar informaci&oacute;n. Finalmente, se estudiar&aacute;n los <strong data-start=\"1518\" data-end=\"1557\">sistemas de almacenamiento de datos</strong>, esenciales para el funcionamiento de los entornos digitales conectados y la toma de decisiones basada en datos.</p>', '<p data-start=\"1705\" data-end=\"2162\">Esta unidad resulta esencial dentro del m&oacute;dulo, ya que proporciona una <strong data-start=\"1776\" data-end=\"1837\">visi&oacute;n pr&aacute;ctica y actualizada de los avances tecnol&oacute;gicos</strong> que impulsan la digitalizaci&oacute;n de los sectores productivos. Entender las <strong data-start=\"1911\" data-end=\"1946\">tecnolog&iacute;as habilitadoras (TDH)</strong> y su relaci&oacute;n con la eficiencia, la competitividad y la sostenibilidad es clave para los futuros profesionales del &aacute;mbito inform&aacute;tico, quienes desempe&ntilde;ar&aacute;n un papel protagonista en su implantaci&oacute;n y mantenimiento.</p>\r\n<p data-start=\"2164\" data-end=\"2570\">El an&aacute;lisis de sistemas productivos digitalizados permite al alumnado <strong data-start=\"2234\" data-end=\"2284\">conectar la teor&iacute;a con la realidad empresarial</strong>, observando c&oacute;mo las organizaciones adoptan soluciones innovadoras para mejorar su rendimiento. Adem&aacute;s, el estudio de <strong data-start=\"2403\" data-end=\"2430\">tecnolog&iacute;as disruptivas</strong> fomenta la <strong data-start=\"2442\" data-end=\"2491\">capacidad de adaptaci&oacute;n al cambio tecnol&oacute;gico</strong>, una competencia indispensable en un mercado laboral en constante evoluci&oacute;n.</p>\r\n<p data-start=\"2572\" data-end=\"3083\">Desde una perspectiva pedag&oacute;gica, esta unidad contribuye a desarrollar el <strong data-start=\"2646\" data-end=\"2681\">pensamiento anal&iacute;tico y cr&iacute;tico</strong> ante el impacto de la digitalizaci&oacute;n, la <strong data-start=\"2723\" data-end=\"2768\">valoraci&oacute;n &eacute;tica del uso de la tecnolog&iacute;a</strong> y la comprensi&oacute;n de los <strong data-start=\"2793\" data-end=\"2831\">procesos de transformaci&oacute;n digital</strong> que atraviesan todos los sectores. Asimismo, refuerza la vinculaci&oacute;n entre los <strong data-start=\"2911\" data-end=\"2949\">Objetivos de Desarrollo Sostenible</strong> y la innovaci&oacute;n tecnol&oacute;gica, al mostrar c&oacute;mo las TDH pueden contribuir a modelos productivos m&aacute;s sostenibles, seguros y eficientes.</p>', '', '<p>1. Tecnolog&iacute;as habilitadoras (TDH) actuales. Caracter&iacute;sticas y aplicaciones <br />2. Relaci&oacute;n entre TDH y productividad <br />3. Implantaci&oacute;n de las tecnolog&iacute;as habilitadoras: relaci&oacute;n con la reducci&oacute;n de costes&nbsp;y la mejora de la competitividad <br />4. Sistemas digitalizados reales. Ejemplos <br />5. Tecnolog&iacute;a disruptiva. Ejemplos <br />6. Sistemas de almacenamiento de datos</p>', '<p>Tecnolog&iacute;as habilitadoras <br />1. Tecnolog&iacute;as habilitadoras digitales (THD)</p>', '', '<p style=\"text-align: justify;\">La calificaci&oacute;n de cada evaluaci&oacute;n o bloque coincidir&aacute; con la media de las calificaciones obtenidas en cada una de las partes que a continuaci&oacute;n se indican: <br />40% En las pruebas escritas (ex&aacute;menes). Resoluci&oacute;n de problemas. Preguntas de desarrollo. Preguntas tipo test. <br />60% En los ejercicios pr&aacute;cticos. Observaci&oacute;n diaria. Desarrollo y elaboraci&oacute;n, individual o en grupo de casos pr&aacute;cticos. Entrega de trabajos en los plazos convenidos. Exposici&oacute;n del trabajo en un tiempo predeterminado. Resoluci&oacute;n de casos pr&aacute;cticos.</p>\r\n<p style=\"text-align: justify;\">Es condici&oacute;n necesaria para aprobar un bloque que se alcance una nota m&iacute;nima de 5. De no ser as&iacute;, se considerar&aacute; que el bloque no ha sido superado y ser&aacute; necesaria la recuperaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">Respecto a las pruebas escritas y los ejercicios pr&aacute;cticos, se calcula como la media ponderada de las actividades, pruebas o pr&aacute;cticas realizadas durante la unidad. Aunque si alguna&nbsp;pr&aacute;ctica es de nivel m&aacute;s complicado o requiere m&aacute;s trabajo que el resto, se avisar&aacute; con antelaci&oacute;n al alumnado del porcentaje en el tema.</p>', '', '', 1, 1, 1, 1),
(123, 406, 5, 'Plan de transformación', 18, 3, 20, '<p data-start=\"337\" data-end=\"597\">En esta unidad did&aacute;ctica, el alumnado se centra en el <strong data-start=\"391\" data-end=\"449\">dise&ntilde;o y an&aacute;lisis de un plan de transformaci&oacute;n digital</strong>, comprendiendo las etapas, recursos y tecnolog&iacute;as necesarias para que una empresa tradicional evolucione hacia un modelo productivo digitalizado.</p>\r\n<p data-start=\"599\" data-end=\"1017\">Se comienza con el estudio de la <strong data-start=\"632\" data-end=\"672\">configuraci&oacute;n de una empresa cl&aacute;sica</strong>, identificando sus &aacute;reas funcionales (producci&oacute;n, log&iacute;stica, administraci&oacute;n, ventas, etc.) y sus posibles puntos de mejora mediante la digitalizaci&oacute;n. A partir de esta base, se aborda la <strong data-start=\"860\" data-end=\"924\">integraci&oacute;n de las Tecnolog&iacute;as Digitales Habilitadoras (TDH)</strong> en cada etapa del proceso productivo, analizando su <strong data-start=\"977\" data-end=\"1014\">interrelaci&oacute;n y complementariedad</strong>.</p>\r\n<p data-start=\"1019\" data-end=\"1468\">Posteriormente, se describe la <strong data-start=\"1050\" data-end=\"1095\">configuraci&oacute;n de una empresa digitalizada</strong>, reconociendo los cambios organizativos, tecnol&oacute;gicos y culturales que conlleva. Finalmente, el alumnado aprende a <strong data-start=\"1211\" data-end=\"1260\">estructurar un plan de transformaci&oacute;n digital</strong>, definiendo objetivos, fases, recursos humanos y materiales implicados, y herramientas de seguimiento que permitan evaluar el impacto de la digitalizaci&oacute;n en la rentabilidad y competitividad de la empresa.</p>', '<p data-start=\"1501\" data-end=\"1796\">Esta unidad representa la <strong data-start=\"1527\" data-end=\"1564\">culminaci&oacute;n conceptual y pr&aacute;ctica</strong> del m&oacute;dulo, al integrar los conocimientos adquiridos en unidades anteriores (econom&iacute;a circular, Industria 4.0, cloud, tecnolog&iacute;as habilitadoras, etc.) en una <strong data-start=\"1723\" data-end=\"1793\">visi&oacute;n global y aplicada del proceso de digitalizaci&oacute;n empresarial</strong>.</p>\r\n<p data-start=\"1798\" data-end=\"2231\">La comprensi&oacute;n del <strong data-start=\"1817\" data-end=\"1851\">plan de transformaci&oacute;n digital</strong> resulta esencial para que el alumnado adquiera una <strong data-start=\"1903\" data-end=\"1930\">perspectiva estrat&eacute;gica</strong> sobre c&oacute;mo las tecnolog&iacute;as modifican los modelos de negocio, los flujos de trabajo y la estructura de las organizaciones. Adem&aacute;s, fomenta la <strong data-start=\"2072\" data-end=\"2133\">capacidad de planificaci&oacute;n, an&aacute;lisis y toma de decisiones</strong>, competencias clave en el perfil profesional del t&eacute;cnico en sistemas microinform&aacute;ticos y redes.</p>\r\n<p data-start=\"2233\" data-end=\"2691\">Desde una perspectiva formativa, esta unidad promueve la <strong data-start=\"2290\" data-end=\"2370\">autonom&iacute;a, el trabajo colaborativo y la aplicaci&oacute;n pr&aacute;ctica del conocimiento</strong>, ya que el alumnado puede simular o dise&ntilde;ar su propio plan de digitalizaci&oacute;n para un caso empresarial concreto. Tambi&eacute;n refuerza la <strong data-start=\"2503\" data-end=\"2536\">conciencia &eacute;tica y sostenible</strong> en la transformaci&oacute;n digital, vinculando los procesos tecnol&oacute;gicos con los <strong data-start=\"2612\" data-end=\"2650\">Objetivos de Desarrollo Sostenible</strong> y el desarrollo econ&oacute;mico responsable.</p>\r\n<p data-start=\"2693\" data-end=\"2900\">De este modo, el estudiante no solo comprende la dimensi&oacute;n t&eacute;cnica de la digitalizaci&oacute;n, sino tambi&eacute;n su impacto global en la <strong data-start=\"2819\" data-end=\"2866\">eficiencia, competitividad y sostenibilidad</strong> de las organizaciones modernas.</p>', '', '<p>1. Configuraci&oacute;n de una empresa cl&aacute;sica. Digitalizaci&oacute;n de la empresa o unidades de &eacute;sta <br />2. TDH implicadas en la digitalizaci&oacute;n de las etapas. Relaci&oacute;n entre etapas <br />3. Configuraci&oacute;n de la empresa digitalizada <br />4. Plan de transformaci&oacute;n. Recursos empleados</p>', '<p>Sistemas de producci&oacute;n de servicios digitalizados <br />1. Producci&oacute;n de servicios digitalizados: automatizaci&oacute;n, digitalizaci&oacute;n y aplicaci&oacute;n de tecnolog&iacute;as digitales</p>', '', '<p style=\"text-align: justify;\">La calificaci&oacute;n de cada evaluaci&oacute;n o bloque coincidir&aacute; con la media de las calificaciones obtenidas en cada una de las partes que a continuaci&oacute;n se indican: <br />40% En las pruebas escritas (ex&aacute;menes). Resoluci&oacute;n de problemas. Preguntas de desarrollo. Preguntas tipo test. <br />60% En los ejercicios pr&aacute;cticos. Observaci&oacute;n diaria. Desarrollo y elaboraci&oacute;n, individual o en grupo de casos pr&aacute;cticos. Entrega de trabajos en los plazos convenidos. Exposici&oacute;n del trabajo en un tiempo predeterminado. Resoluci&oacute;n de casos pr&aacute;cticos.</p>\r\n<p style=\"text-align: justify;\">Es condici&oacute;n necesaria para aprobar un bloque que se alcance una nota m&iacute;nima de 5. De no ser as&iacute;, se considerar&aacute; que el bloque no ha sido superado y ser&aacute; necesaria la recuperaci&oacute;n.</p>\r\n<p style=\"text-align: justify;\">Respecto a las pruebas escritas y los ejercicios pr&aacute;cticos, se calcula como la media ponderada de las actividades, pruebas o pr&aacute;cticas realizadas durante la unidad. Aunque si alguna&nbsp;pr&aacute;ctica es de nivel m&aacute;s complicado o requiere m&aacute;s trabajo que el resto, se avisar&aacute; con antelaci&oacute;n al alumnado del porcentaje en el tema.</p>', '', '', 1, 1, 1, 1),
(130, 414, 1, 'La sostenibilidad en las organizaciones empresariales', 4, 1, 10, '', '', '', '', '', '', '', '', '', 1, 1, 1, 1),
(131, 414, 2, 'Retos ambientales y sociales', 4, 1, 10, '', '', '', '', '', '', '<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) asociados a la misma. Para la comprobaci&oacute;n del progreso del alumnado en la unidad&nbsp;emplear&aacute;n los siguientes instrumentos:</p>\r\n<ul style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<li><strong>Pruebas objetivas</strong>, destinadas a verificar la adquisici&oacute;n de los contenidos te&oacute;ricos y la comprensi&oacute;n de los conceptos fundamentales.</li>\r\n<li><strong>Ejercicios y pr&aacute;cticas</strong>, individuales o en grupo, orientados a la aplicaci&oacute;n de los contenidos del m&oacute;dulo. Algunas de estas actividades podr&aacute;n requerir defensa presencial o exposici&oacute;n oral.</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de 5 puntos sobre 10 en las pruebas y actividades asociadas a dicho resultado.</p>\r\n<h4 id=\"criterios-de-calificacion\" style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">&nbsp;</h4>', '', '', 1, 1, 1, 1),
(132, 414, 3, 'Los ODS en el desempeño profesional', 4, 2, 10, '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Se analiza c&oacute;mo los Objetivos de Desarrollo Sostenible pueden integrarse en el ejercicio profesional y en la gesti&oacute;n empresarial. La unidad conecta los ODS con la realidad laboral, destacando su aplicaci&oacute;n pr&aacute;ctica en el &aacute;mbito de la inform&aacute;tica, la tecnolog&iacute;a y los servicios digitales.</span></p>', '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Relacionar los ODS con la pr&aacute;ctica profesional ayuda a los estudiantes a comprender su capacidad de impacto positivo desde el &aacute;mbito t&eacute;cnico y empresarial. Este enfoque refuerza la responsabilidad social individual y colectiva, orientando la profesi&oacute;n hacia modelos sostenibles de trabajo y desarrollo.</span></p>', '', '<ol style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<li>La sostenibilidad empresarial y profesional&nbsp;</li>\r\n<li>Los 17 ODS en la actividad empresarial y profesional</li>\r\n</ol>', '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Esta unidad profundiza en la sostenibilidad aplicada al &aacute;mbito empresarial y profesional, entendida como un compromiso &eacute;tico con el equilibrio econ&oacute;mico, social y ambiental. Se estudia c&oacute;mo las organizaciones y los profesionales pueden integrar la sostenibilidad en su gesti&oacute;n diaria y en la toma de decisiones. Adem&aacute;s, se analizan los 17 Objetivos de Desarrollo Sostenible (ODS) y su aplicaci&oacute;n pr&aacute;ctica en la empresa, destacando su papel como gu&iacute;a para promover un desarrollo justo, responsable y respetuoso con el entorno.</span></p>', '', '<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) asociados a la misma. Para la comprobaci&oacute;n del progreso del alumnado en la unidad&nbsp;emplear&aacute;n los siguientes instrumentos:</p>\r\n<ul style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<li><strong>Pruebas objetivas</strong>, destinadas a verificar la adquisici&oacute;n de los contenidos te&oacute;ricos y la comprensi&oacute;n de los conceptos fundamentales.</li>\r\n<li><strong>Ejercicios y pr&aacute;cticas</strong>, individuales o en grupo, orientados a la aplicaci&oacute;n de los contenidos del m&oacute;dulo. Algunas de estas actividades podr&aacute;n requerir defensa presencial o exposici&oacute;n oral.</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de 5 puntos sobre 10 en las pruebas y actividades asociadas a dicho resultado.</p>\r\n<h4 id=\"criterios-de-calificacion\" style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">&nbsp;</h4>', '', '', 1, 1, 1, 1),
(133, 414, 4, 'Economía verde y circular', 4, 2, 10, '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Esta unidad explora los modelos econ&oacute;micos alternativos a la econom&iacute;a lineal tradicional. Se profundiza en los principios de la econom&iacute;a verde y circular, el an&aacute;lisis del ciclo de vida de los productos y el ecodise&ntilde;o como herramientas para optimizar recursos y reducir residuos.</span></p>', '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">El conocimiento de estos modelos permite a los futuros profesionales comprender la importancia de la innovaci&oacute;n sostenible en los procesos productivos y de consumo. Promueve una visi&oacute;n estrat&eacute;gica en la que la eficiencia y la sostenibilidad se convierten en ventajas competitivas para las organizaciones.</span></p>', '', '<ol style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<li><span style=\"font-weight: 400;\">El modelo de producci&oacute;n y consumo actual: la econom&iacute;a lineal&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Econom&iacute;a verde&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Econom&iacute;a circular&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Beneficios de la econom&iacute;a verde y circular&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">An&aacute;lisis del ciclo de vida&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Ecodise&ntilde;o</span></li>\r\n</ol>', '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Primero se analiza el modelo de producci&oacute;n y consumo actual, basado en una econom&iacute;a lineal, caracterizada por el uso intensivo de recursos y la generaci&oacute;n de residuos. A continuaci&oacute;n, se introducen los conceptos de econom&iacute;a verde y econom&iacute;a circular como alternativas sostenibles, estudiando despu&eacute;s los beneficios que aportan en t&eacute;rminos ambientales, sociales y econ&oacute;micos. Seguidamente, se aborda el an&aacute;lisis del ciclo de vida de los productos como herramienta para evaluar su impacto en cada fase del proceso productivo, y finalmente se estudia el ecodise&ntilde;o, que aplica los principios de la sostenibilidad desde la concepci&oacute;n del producto para minimizar su huella ambiental.</span></p>', '', '<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) asociados a la misma. Para la comprobaci&oacute;n del progreso del alumnado en la unidad&nbsp;emplear&aacute;n los siguientes instrumentos:</p>\r\n<ul style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<li><strong>Pruebas objetivas</strong>, destinadas a verificar la adquisici&oacute;n de los contenidos te&oacute;ricos y la comprensi&oacute;n de los conceptos fundamentales.</li>\r\n<li><strong>Ejercicios y pr&aacute;cticas</strong>, individuales o en grupo, orientados a la aplicaci&oacute;n de los contenidos del m&oacute;dulo. Algunas de estas actividades podr&aacute;n requerir defensa presencial o exposici&oacute;n oral.</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de 5 puntos sobre 10 en las pruebas y actividades asociadas a dicho resultado.</p>\r\n<h4 id=\"criterios-de-calificacion\" style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">&nbsp;</h4>', '', '', 1, 1, 1, 1),
(134, 414, 5, 'Actividades sostenibles y medioambiente', 4, 3, 10, '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Se estudian m&eacute;todos para medir y reducir el impacto ambiental de las actividades personales, profesionales y empresariales. La unidad introduce pr&aacute;cticas sostenibles, la certificaci&oacute;n ambiental y la normativa aplicable al &aacute;mbito tecnol&oacute;gico y empresarial.</span></p>', '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Fomentar la responsabilidad ambiental en las actividades cotidianas y profesionales consolida h&aacute;bitos sostenibles en el entorno laboral. Adem&aacute;s, conocer la normativa y los sistemas de certificaci&oacute;n proporciona herramientas concretas para garantizar la calidad ambiental en las organizaciones.</span></p>', '', '<ol style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<li><span style=\"font-weight: 400;\">Medici&oacute;n del impacto ambiental de las actividades personales y profesionales&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Actividades personales sostenibles&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Actividades empresariales y profesionales&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Certificaci&oacute;n de sostenibilidad&nbsp;</span></li>\r\n<li><span style=\"font-weight: 400;\">Normativa ambiental</span></li>\r\n</ol>', '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Esta unidad aborda la medici&oacute;n del impacto ambiental derivado de las actividades personales, empresariales y profesionales, analizando c&oacute;mo nuestras acciones cotidianas inciden en el entorno. Se estudian las buenas pr&aacute;cticas sostenibles que pueden aplicarse tanto a nivel individual como organizacional, fomentando la responsabilidad ambiental en todos los &aacute;mbitos. Adem&aacute;s, se profundiza en los sistemas de certificaci&oacute;n de sostenibilidad y en la normativa ambiental vigente, como herramientas clave para garantizar el cumplimiento de los est&aacute;ndares ecol&oacute;gicos y promover una cultura de mejora continua hacia la sostenibilidad.</span></p>', '', '<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) asociados a la misma. Para la comprobaci&oacute;n del progreso del alumnado en la unidad&nbsp;emplear&aacute;n los siguientes instrumentos:</p>\r\n<ul style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<li><strong>Pruebas objetivas</strong>, destinadas a verificar la adquisici&oacute;n de los contenidos te&oacute;ricos y la comprensi&oacute;n de los conceptos fundamentales.</li>\r\n<li><strong>Ejercicios y pr&aacute;cticas</strong>, individuales o en grupo, orientados a la aplicaci&oacute;n de los contenidos del m&oacute;dulo. Algunas de estas actividades podr&aacute;n requerir defensa presencial o exposici&oacute;n oral.</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de 5 puntos sobre 10 en las pruebas y actividades asociadas a dicho resultado.</p>\r\n<h4 id=\"criterios-de-calificacion\" style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">&nbsp;</h4>', '', '', 1, 1, 1, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(135, 414, 6, 'El plan de sostenibilidad', 14, 3, 50, '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">La unidad final integra los conocimientos adquiridos en el dise&ntilde;o de un plan de sostenibilidad empresarial. Se abordan las fases del proceso: diagn&oacute;stico, an&aacute;lisis de stakeholders, establecimiento de objetivos, indicadores, seguimiento y comunicaci&oacute;n de resultados.</span></p>', '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Elaborar un plan de sostenibilidad permite aplicar de manera pr&aacute;ctica los conceptos te&oacute;ricos del m&oacute;dulo. Desarrolla competencias en planificaci&oacute;n estrat&eacute;gica, gesti&oacute;n por objetivos y mejora continua, imprescindibles para incorporar la sostenibilidad como eje transversal en la gesti&oacute;n organizacional y tecnol&oacute;gica.</span></p>', '', '<ol style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<li>La importancia del plan de sostenibilidad&nbsp;</li>\r\n<li>La estrategia empresarial&nbsp;</li>\r\n<li>El compromiso de la Direcci&oacute;n&nbsp;</li>\r\n<li>An&aacute;lisis de diagn&oacute;stico inicial&nbsp;</li>\r\n<li>An&aacute;lisis de los&nbsp;<em>skateholders</em></li>\r\n<li>An&aacute;lisis de materialidad&nbsp;</li>\r\n<li>Objetivos y metas&nbsp;</li>\r\n<li>Asignar responsabilidades&nbsp;</li>\r\n<li>Indicadores de desempe&ntilde;o&nbsp;</li>\r\n<li>Seguimiento, evaluaci&oacute;n y mejora&nbsp;</li>\r\n<li>Comunicaci&oacute;n e integraci&oacute;n</li>\r\n</ol>', '<p><span style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: justify; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: #ffffff; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; display: inline !important; float: none;\">Primero se introduce la importancia del plan de sostenibilidad, destacando su papel estrat&eacute;gico dentro de la estrategia empresarial y la necesidad del compromiso de la Direcci&oacute;n para su implantaci&oacute;n efectiva. A continuaci&oacute;n, se realiza un an&aacute;lisis de diagn&oacute;stico inicial que permita conocer la situaci&oacute;n de partida, seguido del an&aacute;lisis de los stakeholders y del an&aacute;lisis de materialidad para identificar los temas m&aacute;s relevantes en materia ambiental, social y de gobernanza. Posteriormente, se establecen los objetivos y metas, se asignan responsabilidades y se definen los indicadores de desempe&ntilde;o para medir los avances. Finalmente, se lleva a cabo el seguimiento, evaluaci&oacute;n y mejora continua del plan, concluyendo con la comunicaci&oacute;n e integraci&oacute;n de los resultados en la organizaci&oacute;n, garantizando la transparencia y el compromiso con la sostenibilidad.</span></p>', '', '<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) asociados a la misma. Para la comprobaci&oacute;n del progreso del alumnado en la unidad&nbsp;emplear&aacute;n los siguientes instrumentos:</p>\r\n<ul style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<li><strong>Pruebas objetivas</strong>, destinadas a verificar la adquisici&oacute;n de los contenidos te&oacute;ricos y la comprensi&oacute;n de los conceptos fundamentales.</li>\r\n<li><strong>Ejercicios y pr&aacute;cticas</strong>, individuales o en grupo, orientados a la aplicaci&oacute;n de los contenidos del m&oacute;dulo. Algunas de estas actividades podr&aacute;n requerir defensa presencial o exposici&oacute;n oral.</li>\r\n</ul>\r\n<p style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de 5 puntos sobre 10 en las pruebas y actividades asociadas a dicho resultado.</p>\r\n<h4 id=\"criterios-de-calificacion\" style=\"color: #000000; font-family: Arial, Verdana; font-size: 17.6px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">&nbsp;</h4>', '', '', 1, 1, 1, 1),
(136, 71, 1, ' Conceptos básicos de la seguridad informática', 15, 1, 15, '<p>Este apartado introduce los fundamentos de la seguridad inform&aacute;tica, incluyendo los tipos de amenazas, vulnerabilidades, ataques y medidas de protecci&oacute;n. Se abordan principios como la confidencialidad, integridad y disponibilidad de la informaci&oacute;n.</p>', '<p>Comprender los conceptos b&aacute;sicos es esencial para identificar riesgos y aplicar medidas adecuadas. Este bloque sienta las bases te&oacute;ricas necesarias para abordar el resto del m&oacute;dulo con criterio t&eacute;cnico y preventivo.</p>', '', '<p>1. Seguridad inform&aacute;tica &iquest;por qu&eacute;? <br />2. Objetivos de la seguridad inform&aacute;tica <br />3. Clasificaci&oacute;n de seguridad <br />3.1. Seguridad f&iacute;sica y l&oacute;gica <br />3.2. Seguridad activa y pasiva <br />4. Amenazas y fraudes en los sistemas de la informaci&oacute;n <br />4.1. Actuaciones para mejorar la seguridad <br />4.2. Vulnerabilidades <br />4.3. Tipos de amenazas <br />4.4. Pautas de protecci&oacute;n para nuestro sistema <br />5. Leyes relacionadas con la seguridad de la informaci&oacute;n <br />5.1. Normativa que protege los datos personales <br />5.2. Normativa de los sistemas de informaci&oacute;n y comercio electr&oacute;nico</p>', '<p>1. Seguridad inform&aacute;tica<br />2. Objetivos de la seguridad inform&aacute;tica<br />3. Clasificaci&oacute;n de seguridad<br />4. Amenazas y fraudes en los sistemas de la informaci&oacute;n<br />5. Leyes relacionadas con la seguridad de la informaci&oacute;n</p>', '', '<p>Dado que el enfoque de la metodolog&iacute;a did&aacute;ctica a emplear en este m&oacute;dulo es fundamentalmente procedimental, la evaluaci&oacute;n dar&aacute; importancia a la realizaci&oacute;n de&nbsp;ejercicios (pr&aacute;cticas o proyectos) en el aula de inform&aacute;tica y a la presentaci&oacute;n de trabajos por parte de los estudiantes. No obstante, tambi&eacute;n se realizar&aacute; una prueba&nbsp;objetiva al t&eacute;rmino de la unidad, cuya finalidad es comprobar el grado de asimilaci&oacute;n de los contenidos, tanto conceptuales como procedimientales.</p>\r\n<p>&nbsp;</p>\r\n<p>La calificaci&oacute;n de cada&nbsp;estudiante&nbsp;se obtiene, por tanto, a partir de estos dos componentes:</p>\r\n<ul>\r\n<li>Ejercicios (50 %): Observaci&oacute;n del trabajo diario de los alumnos, correcci&oacute;n de los informes de pr&aacute;cticas de los alumnos, proyectos en grupo e individuales.</li>\r\n<li>Pruebas objetivas (50 %): Preguntas tipo test, preguntas objetivas de respuestas cortas, ejercicios delante del ordenador.</li>\r\n</ul>\r\n<p>Se debe obtener al menos un 5 en cada apartado.&nbsp;</p>', '', '', 1, 1, 1, 1),
(137, 71, 2, 'Seguridad pasiva. Hardware y almacenamiento', 18, 1, 10, '<p>Se estudian las medidas f&iacute;sicas y t&eacute;cnicas que protegen los equipos y dispositivos de almacenamiento, como sistemas de alimentaci&oacute;n ininterrumpida (SAI), controles de acceso f&iacute;sico, y copias de seguridad.</p>', '<p>La seguridad pasiva es clave para evitar p&eacute;rdidas de datos por fallos el&eacute;ctricos, robos o accidentes. Proteger el hardware y los soportes garantiza la continuidad operativa y la integridad de la informaci&oacute;n.</p>', '', '<p>1. Ubicaci&oacute;n y protecci&oacute;n f&iacute;sica <br />1.1. Factores para elegir la ubicaci&oacute;n <br />1.2. Control de acceso <br />1.3. Sistemas de climatizaci&oacute;n y protecci&oacute;n en el CPD <br />1.4. Recuperaci&oacute;n en caso de desastre<br /> 2. Sistemas de alimentaci&oacute;n ininterrumpida <br />2.1. Definici&oacute;n de SAI <br />2.2. Tipos de SAI <br />2.3. Modo de funcionamiento <br />3. Almacenamiento de la informaci&oacute;n <br />4. Almacenamiento redundante y distribuido <br />4.1. RAID en sistemas operativos GNU/Linux <br />4.2. RAID en sistemas operativos Windows <br />5. Clusters de servidores <br />5.1. Clasificaci&oacute;n de los clusters <br />5.2. Componentes de los clusters <br />6. Almacenamiento externo Network Attached Storage Storage Area Network</p>', '<p>1. Ubicaci&oacute;n y protecci&oacute;n f&iacute;sica<br />2. Sistemas de alimentaci&oacute;n ininterrumpida<br />3. Almacenamiento de la informaci&oacute;n<br />4. Almacenamiento redundante y distribuido<br />5. Clusters de servidores<br />6. Almacenamiento externo Network Attached Storage Storage Area Network</p>', '', '<p>Dado que el enfoque de la metodolog&iacute;a did&aacute;ctica a emplear en este m&oacute;dulo es fundamentalmente procedimental, la evaluaci&oacute;n dar&aacute; importancia a la realizaci&oacute;n de&nbsp;ejercicios (pr&aacute;cticas o proyectos) en el aula de inform&aacute;tica y a la presentaci&oacute;n de trabajos por parte de los estudiantes. No obstante, tambi&eacute;n se realizar&aacute; una prueba&nbsp;objetiva al t&eacute;rmino de la unidad, cuya finalidad es comprobar el grado de asimilaci&oacute;n de los contenidos, tanto conceptuales como procedimientales.</p>\r\n<p>&nbsp;</p>\r\n<p>La calificaci&oacute;n de cada&nbsp;estudiante&nbsp;se obtiene, por tanto, a partir de estos dos componentes:</p>\r\n<ul>\r\n<li>Ejercicios (50 %): Observaci&oacute;n del trabajo diario de los alumnos, correcci&oacute;n de los informes de pr&aacute;cticas de los alumnos, proyectos en grupo e individuales.</li>\r\n<li>Pruebas objetivas (50 %): Preguntas tipo test, preguntas objetivas de respuestas cortas, ejercicios delante del ordenador.</li>\r\n</ul>\r\n<p>Se debe obtener al menos un 5 en cada apartado.&nbsp;</p>', '', '', 1, 1, 1, 1),
(138, 71, 3, 'Seguridad Pasiva. Recuperación de datos', 20, 1, 10, '<p>Este apartado se centra en t&eacute;cnicas y herramientas para recuperar datos perdidos o da&ntilde;ados, ya sea por errores humanos, fallos t&eacute;cnicos o ataques. Incluye el uso de software especializado y procedimientos de restauraci&oacute;n.</p>', '<p>La capacidad de recuperar informaci&oacute;n es vital para minimizar el impacto de incidentes. Formar al alumnado en estas t&eacute;cnicas les prepara para actuar con rapidez y eficacia ante situaciones cr&iacute;ticas.</p>', '', '<p>1. Introducci&oacute;n <br />2. Tipos de copias de seguridad <br />3. Copias de seguridad de los datos <br />3.1. Copia de seguridad de datos en Windows <br />3.2. Copia de seguridad de datos en Linux <br />4. Modos de recuperaci&oacute;n frente a p&eacute;rdidas en el sistema operativo <br />5. Creaci&oacute;n de im&aacute;genes del sistema <br />6. Copia de seguridad del registro <br />7. Pol&iacute;ticas de copias de seguridad</p>', '<p>1. Introducci&oacute;n<br />2. Tipos de copias de seguridad<br />3. Copias de seguridad de los datos<br />4. Modos de recuperaci&oacute;n frente a p&eacute;rdidas en el sistema operativo<br />5. Creaci&oacute;n de im&aacute;genes del sistema<br />6. Copia de seguridad del registro<br />7. Pol&iacute;ticas de copias de seguridad</p>', '', '<p>Dado que el enfoque de la metodolog&iacute;a did&aacute;ctica a emplear en este m&oacute;dulo es fundamentalmente procedimental, la evaluaci&oacute;n dar&aacute; importancia a la realizaci&oacute;n de&nbsp;ejercicios (pr&aacute;cticas o proyectos) en el aula de inform&aacute;tica y a la presentaci&oacute;n de trabajos por parte de los estudiantes. No obstante, tambi&eacute;n se realizar&aacute; una prueba&nbsp;objetiva al t&eacute;rmino de la unidad, cuya finalidad es comprobar el grado de asimilaci&oacute;n de los contenidos, tanto conceptuales como procedimientales.</p>\r\n<p>&nbsp;</p>\r\n<p>La calificaci&oacute;n de cada&nbsp;estudiante&nbsp;se obtiene, por tanto, a partir de estos dos componentes:</p>\r\n<ul>\r\n<li>Ejercicios (50 %): Observaci&oacute;n del trabajo diario de los alumnos, correcci&oacute;n de los informes de pr&aacute;cticas de los alumnos, proyectos en grupo e individuales.</li>\r\n<li>Pruebas objetivas (50 %): Preguntas tipo test, preguntas objetivas de respuestas cortas, ejercicios delante del ordenador.</li>\r\n</ul>\r\n<p>Se debe obtener al menos un 5 en cada apartado.&nbsp;</p>', '', '', 1, 1, 1, 1),
(139, 71, 4, 'Sistemas de identificación. Criptografía', 20, 1, 15, '<p>Se analizan los m&eacute;todos de autenticaci&oacute;n de usuarios y dispositivos, as&iacute; como los fundamentos de la criptograf&iacute;a: cifrado, firmas digitales y certificados. Se estudian protocolos seguros y su aplicaci&oacute;n pr&aacute;ctica.</p>', '<p>Garantizar que solo usuarios autorizados accedan a los sistemas es fundamental. La criptograf&iacute;a refuerza la seguridad de las comunicaciones y protege los datos frente a accesos no autorizados.</p>', '', '<p>1. &iquest;C&oacute;mo aseguramos la privacidad de la informaci&oacute;n? <br />2. Un poco de historia de la criptograf&iacute;a <br />3. Criptograf&iacute;a sim&eacute;trica y asim&eacute;trica <br />3.1. Criptograf&iacute;a sim&eacute;trica <br />3.2. Criptograf&iacute;a asim&eacute;trica <br />3.3. Criptograf&iacute;a h&iacute;brida <br />4. Algoritmos <br />5. Funci&oacute;n Resumen <br />6. Firma digital <br />7. Certificados digitales <br />8. PKI</p>', '<p>1. &iquest;C&oacute;mo aseguramos la privacidad de la informaci&oacute;n?<br />2. Un poco de historia de la criptograf&iacute;a<br />3. Criptograf&iacute;a sim&eacute;trica y asim&eacute;trica<br />4. Algoritmos<br />5. Funci&oacute;n Resumen<br />6. Firma digital<br />7. Certificados digitales<br />8. PKI</p>', '', '<p>Dado que el enfoque de la metodolog&iacute;a did&aacute;ctica a emplear en este m&oacute;dulo es fundamentalmente procedimental, la evaluaci&oacute;n dar&aacute; importancia a la realizaci&oacute;n de&nbsp;ejercicios (pr&aacute;cticas o proyectos) en el aula de inform&aacute;tica y a la presentaci&oacute;n de trabajos por parte de los estudiantes. No obstante, tambi&eacute;n se realizar&aacute; una prueba&nbsp;objetiva al t&eacute;rmino de la unidad, cuya finalidad es comprobar el grado de asimilaci&oacute;n de los contenidos, tanto conceptuales como procedimientales.</p>\r\n<p>&nbsp;</p>\r\n<p>La calificaci&oacute;n de cada&nbsp;estudiante&nbsp;se obtiene, por tanto, a partir de estos dos componentes:</p>\r\n<ul>\r\n<li>Ejercicios (50 %): Observaci&oacute;n del trabajo diario de los alumnos, correcci&oacute;n de los informes de pr&aacute;cticas de los alumnos, proyectos en grupo e individuales.</li>\r\n<li>Pruebas objetivas (50 %): Preguntas tipo test, preguntas objetivas de respuestas cortas, ejercicios delante del ordenador.</li>\r\n</ul>\r\n<p>Se debe obtener al menos un 5 en cada apartado.&nbsp;</p>', '', '', 1, 1, 1, 1),
(140, 71, 5, 'Seguridad activa en el sistema', 20, 2, 10, '<p>Este bloque aborda las herramientas y configuraciones que protegen el sistema operativo y las aplicaciones frente a amenazas activas, como antivirus, antimalware, actualizaciones y pol&iacute;ticas de seguridad.</p>', '<p>La seguridad activa permite detectar y neutralizar amenazas en tiempo real. Ense&ntilde;ar su implementaci&oacute;n ayuda a mantener los sistemas protegidos y operativos frente a ataques constantes.</p>', '', '<p>1. Introducci&oacute;n a la seguridad del sistema <br />2. Seguridad en el acceso al ordenador<br /> 2.1. &iquest;C&oacute;mo evitamos que personas ajenas modifiquen la BIOS? <br />2.2. &iquest;C&oacute;mo proteger el GRUB con contrase&ntilde;a? <br />2.3. Cifrado de particiones <br />3. Autenticaci&oacute;n de los usuarios <br />3.1. Pol&iacute;ticas de contrase&ntilde;as <br />3.2. Sistemas biom&eacute;tricos <br />4. Vulnerabilidades del sistema <br />4.1. Evitar vulnerabilidades en Windows <br />5. Monitorizaci&oacute;n del sistema <br />5.1. Monitorizaci&oacute;n en Windows <br />5.2. Monitorizaci&oacute;n en Linux<br /> 6. Software que vulnera la seguridad del sistema <br />6.1. Clasificaci&oacute;n de los atacantes Tipos de ataques <br />7.Seguridad en redes cableadas <br />7.1. Red privada virtual (VPN)&iquest;Qu&eacute; es una VPN?&iquest;C&oacute;mo funciona una VPN? Instalaci&oacute;n y configuraci&oacute;n de una VPN <br />7.2. Detecci&oacute;n de intrusos <br />7.3. Arranque de servicios Servicios en Windows Vista Servicios en Ubuntu <br />8. Seguridad en redes inal&aacute;mbricas <br />8.1. Tecnolog&iacute;as Wi-fi <br />8.2. Conceptos de redes Wi-fi <br />8.3. Seguridad Wi-fi <br />8.4. Seguridad WEP <br />8.5. Seguridad WPA Seguridad WPA personal Seguridad WPA empresarial</p>', '<p>1. Introducci&oacute;n a la seguridad del sistema <br />2. Seguridad en el acceso al ordenador<br />3. Autenticaci&oacute;n de los usuarios<br />4. Vulnerabilidades del sistema<br />5. Monitorizaci&oacute;n del sistema<br />6. Software que vulnera la seguridad del sistema<br />7.Seguridad en redes cableadas<br />8. Seguridad en redes inal&aacute;mbricas</p>', '', '<p>Dado que el enfoque de la metodolog&iacute;a did&aacute;ctica a emplear en este m&oacute;dulo es fundamentalmente procedimental, la evaluaci&oacute;n dar&aacute; importancia a la realizaci&oacute;n de&nbsp;ejercicios (pr&aacute;cticas o proyectos) en el aula de inform&aacute;tica y a la presentaci&oacute;n de trabajos por parte de los estudiantes. No obstante, tambi&eacute;n se realizar&aacute; una prueba&nbsp;objetiva al t&eacute;rmino de la unidad, cuya finalidad es comprobar el grado de asimilaci&oacute;n de los contenidos, tanto conceptuales como procedimientales.</p>\r\n<p>&nbsp;</p>\r\n<p>La calificaci&oacute;n de cada&nbsp;estudiante&nbsp;se obtiene, por tanto, a partir de estos dos componentes:</p>\r\n<ul>\r\n<li>Ejercicios (50 %): Observaci&oacute;n del trabajo diario de los alumnos, correcci&oacute;n de los informes de pr&aacute;cticas de los alumnos, proyectos en grupo e individuales.</li>\r\n<li>Pruebas objetivas (50 %): Preguntas tipo test, preguntas objetivas de respuestas cortas, ejercicios delante del ordenador.</li>\r\n</ul>\r\n<p>Se debe obtener al menos un 5 en cada apartado.&nbsp;</p>', '', '', 1, 1, 1, 1),
(141, 71, 6, 'Seguridad de alto nivel en redes: cortafuegos', 20, 2, 20, '<p>Se estudia el funcionamiento y configuraci&oacute;n de cortafuegos (firewalls), tanto f&iacute;sicos como l&oacute;gicos, para controlar el tr&aacute;fico de red y prevenir accesos no autorizados desde el exterior.</p>', '<p>Los cortafuegos son la primera l&iacute;nea de defensa en redes. Saber c&oacute;mo configurarlos correctamente permite proteger los sistemas frente a intrusiones y ataques externos.</p>', '', '<p>1. Seguridad de alto nivel <br />2. Cortafuegos: qu&eacute; son y para qu&eacute; sirven <br />3. Tipos de cortafuegos <br />3.1. Seg&uacute;n su ubicaci&oacute;n Cortafuegos personales Cortafuegos de subredes <br />3.2. Seg&uacute;n su tecnolog&iacute;a<br />4. Filtrado de paquetes <br />4.1. Par&aacute;metros utilizados para filtrar paquetes <br />4.2. Reglas de filtrado <br />5. Uso de cortafuegos <br />5.1. Criterios para elegir un cortafuegos <br />5.2. Instalaci&oacute;n y configuraci&oacute;n de un cortafuegos comercial <br />6. Arquitecturas de red con cortafuegos <br />6.1. Dual-Homed Host <br />6.2. Screened Host <br />6.3. Screened subnet <br />7. Monitorizaci&oacute;n y logs <br />7.1. Registro de actividad de los sistemas operativos <br />7.2. Registros de actividad del cortafuegos</p>', '<p>1. Seguridad de alto nivel <br />2. Cortafuegos: qu&eacute; son y para qu&eacute; sirven <br />3. Tipos de cortafuegos<br />4. Filtrado de paquetes<br />5. Uso de cortafuegos<br />6. Arquitecturas de red con cortafuegos<br />7. Monitorizaci&oacute;n y logs</p>', '', '<p>Dado que el enfoque de la metodolog&iacute;a did&aacute;ctica a emplear en este m&oacute;dulo es fundamentalmente procedimental, la evaluaci&oacute;n dar&aacute; importancia a la realizaci&oacute;n de&nbsp;ejercicios (pr&aacute;cticas o proyectos) en el aula de inform&aacute;tica y a la presentaci&oacute;n de trabajos por parte de los estudiantes. No obstante, tambi&eacute;n se realizar&aacute; una prueba&nbsp;objetiva al t&eacute;rmino de la unidad, cuya finalidad es comprobar el grado de asimilaci&oacute;n de los contenidos, tanto conceptuales como procedimientales.</p>\r\n<p>&nbsp;</p>\r\n<p>La calificaci&oacute;n de cada&nbsp;estudiante&nbsp;se obtiene, por tanto, a partir de estos dos componentes:</p>\r\n<ul>\r\n<li>Ejercicios (50 %): Observaci&oacute;n del trabajo diario de los alumnos, correcci&oacute;n de los informes de pr&aacute;cticas de los alumnos, proyectos en grupo e individuales.</li>\r\n<li>Pruebas objetivas (50 %): Preguntas tipo test, preguntas objetivas de respuestas cortas, ejercicios delante del ordenador.</li>\r\n</ul>\r\n<p>Se debe obtener al menos un 5 en cada apartado.&nbsp;</p>', '', '', 1, 1, 1, 1),
(142, 71, 7, 'Seguridad de alto nivel en redes: proxy', 20, 2, 20, '<p>Este apartado trata el uso de servidores proxy para filtrar, controlar y registrar el tr&aacute;fico de red. Se analizan sus funciones como intermediarios entre usuarios e Internet, y su papel en la seguridad.</p>', '<p>Este apartado trata el uso de servidores proxy para filtrar, controlar y registrar el tr&aacute;fico de red. Se analizan sus funciones como intermediarios entre usuarios e Internet, y su papel en la seguridad.</p>', '', '<p>1. Introducci&oacute;n <br />2. Caracter&iacute;sticas del proxy <br />3. Funcionamiento del proxy <br />4. WinGate <br />4.1. Instalaci&oacute;n <br />4.2. Configuraci&oacute;n inicial <br />4.3. Servicios de WinGate Parada y arranque de los servicios Configuraci&oacute;n de los servicios <br />4.4. Tipos de proxy&nbsp; <br />4.5. Creaci&oacute;n de usuarios <br />5. PureSight <br />6. Control de log en WinGate <br />7. Squid <br />7.1. Instalaci&oacute;n de Squid <br />7.2. Configuraci&oacute;n inicial <br />7.3. Control de acceso en Squid <br />7.4. Autenticaci&oacute;n <br />7.5. Clasificaci&oacute;n de sitios en Squid <br />7.6. Gesti&oacute;n del proxy con Webmin. <br />Control de log Instalar y configurar Webmin para Squid <br />Utilizaci&oacute;n de Webmin<br /> An&aacute;lisis del log de Squid con Webmin</p>', '<p>1. Introducci&oacute;n <br />2. Caracter&iacute;sticas del proxy <br />3. Funcionamiento del proxy <br />4. WinGate<br />5. PureSight <br />6. Control de log en WinGate <br />7. Squid<br /><br /></p>', '', '<p>Dado que el enfoque de la metodolog&iacute;a did&aacute;ctica a emplear en este m&oacute;dulo es fundamentalmente procedimental, la evaluaci&oacute;n dar&aacute; importancia a la realizaci&oacute;n de&nbsp;ejercicios (pr&aacute;cticas o proyectos) en el aula de inform&aacute;tica y a la presentaci&oacute;n de trabajos por parte de los estudiantes. No obstante, tambi&eacute;n se realizar&aacute; una prueba&nbsp;objetiva al t&eacute;rmino de la unidad, cuya finalidad es comprobar el grado de asimilaci&oacute;n de los contenidos, tanto conceptuales como procedimientales.</p>\r\n<p>&nbsp;</p>\r\n<p>La calificaci&oacute;n de cada&nbsp;estudiante&nbsp;se obtiene, por tanto, a partir de estos dos componentes:</p>\r\n<ul>\r\n<li>Ejercicios (50 %): Observaci&oacute;n del trabajo diario de los alumnos, correcci&oacute;n de los informes de pr&aacute;cticas de los alumnos, proyectos en grupo e individuales.</li>\r\n<li>Pruebas objetivas (50 %): Preguntas tipo test, preguntas objetivas de respuestas cortas, ejercicios delante del ordenador.</li>\r\n</ul>\r\n<p>Se debe obtener al menos un 5 en cada apartado.&nbsp;</p>', '', '', 1, 1, 1, 1),
(145, 72, 1, 'Interconexión de redes privadas con redes públicas', 24, 1, 10, '<p>En esta unidad se estudian los mecanismos que permiten la comunicaci&oacute;n entre redes privadas y redes p&uacute;blicas, centr&aacute;ndose en las funciones de enrutamiento, filtrado y control del tr&aacute;fico. Se abordan herramientas como cortafuegos, pasarelas, reenv&iacute;o de puertos y sistemas de cach&eacute; que garantizan la conectividad segura y eficiente entre entornos internos y externos.</p>', '<p>El conocimiento de la interconexi&oacute;n de redes es esencial para cualquier t&eacute;cnico de sistemas, ya que la mayor&iacute;a de infraestructuras actuales combinan redes locales con acceso a Internet. Comprender c&oacute;mo se gestiona el tr&aacute;fico y se protegen los recursos internos frente a amenazas externas es la base para garantizar la seguridad y el rendimiento de los servicios de red.</p>', '', '<ul>\r\n<li>Pasarelas a nivel de aplicaci&oacute;n.</li>\r\n<li>Almacenamiento en memoria cach&eacute;.</li>\r\n<li>Enrutamiento de tr&aacute;fico entre interfaces de red.</li>\r\n<li>Cortafuegos.</li>\r\n<li>Filtrado del tr&aacute;fico entre redes.</li>\r\n<li>Reenv&iacute;o de puertos.</li>\r\n</ul>', '', '', '<p style=\"font-weight: 400;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para la misma.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:</p>\r\n<ul style=\"font-weight: 400;\">\r\n<li><strong>Pruebas objetivas</strong>&nbsp;(te&oacute;ricas o pr&aacute;cticas, 50 % de la calificaci&oacute;n)</li>\r\n<li><strong>Ejercicios</strong> (proyectos, pr&aacute;cticas y trabajos de aula, 50 % de la calificaci&oacute;n)&nbsp;</li>\r\n</ul>\r\n<p style=\"font-weight: 400;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de&nbsp;<strong>5 puntos</strong>&nbsp;sobre 10 en las pruebas objetivas, y <strong>5 puntos</strong> sobre 10 en los ejercicios correspondientes.</p>', '', '', 1, 1, 1, 1),
(146, 72, 2, 'Servicio DHCP', 35, 1, 15, '<p>Esta unidad aborda el funcionamiento del protocolo DHCP (Dynamic Host Configuration Protocol) y su papel en la asignaci&oacute;n autom&aacute;tica de direcciones IP y otros par&aacute;metros de red. Se estudian conceptos como rangos, exclusiones, concesiones y reservas, as&iacute; como las opciones adicionales que optimizan la configuraci&oacute;n de dispositivos en diferentes segmentos de red.</p>', '<p>La administraci&oacute;n eficiente de direcciones IP es fundamental en cualquier red. Automatizar este proceso mediante DHCP reduce errores, ahorra tiempo y facilita la gesti&oacute;n de redes din&aacute;micas. Dominar este servicio prepara al alumnado para implementar soluciones profesionales de configuraci&oacute;n y mantenimiento de redes locales y empresariales.</p>', '', '<ul>\r\n<li>Direcci&oacute;n IP, m&aacute;scara de red, puerta de enlace.</li>\r\n<li>Dispositivos de red. Encaminadores y segmentos de red. Difusiones.</li>\r\n<li>DHCP. Rangos, exclusiones, concesiones y reservas.</li>\r\n<li>Opciones adicionales del protoco</li>\r\n</ul>', '', '', '<p style=\"font-weight: 400;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para la misma.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:</p>\r\n<ul style=\"font-weight: 400;\">\r\n<li><strong>Pruebas objetivas</strong>&nbsp;(te&oacute;ricas o pr&aacute;cticas, 50 % de la calificaci&oacute;n)</li>\r\n<li><strong>Ejercicios</strong> (proyectos, pr&aacute;cticas y trabajos de aula, 50 % de la calificaci&oacute;n)&nbsp;</li>\r\n</ul>\r\n<p style=\"font-weight: 400;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de&nbsp;<strong>5 puntos</strong>&nbsp;sobre 10 en las pruebas objetivas, y <strong>5 puntos</strong> sobre 10 en los ejercicios correspondientes.</p>', '', '', 1, 1, 1, 1),
(147, 72, 3, 'Servicio DNS', 35, 1, 15, '<p>En esta unidad se analiza el sistema de nombres de dominio (DNS), que traduce nombres legibles por humanos en direcciones IP. Se estudian su estructura jer&aacute;rquica, los distintos tipos de servidores y zonas, as&iacute; como el proceso de resoluci&oacute;n de nombres y los diferentes registros que lo conforman.</p>', '<p>El DNS es una pieza clave del funcionamiento de Internet y de cualquier red corporativa. Comprender su arquitectura y administraci&oacute;n permite mantener servicios accesibles y resolver incidencias relacionadas con la conectividad. Esta competencia es esencial para desplegar y mantener infraestructuras de red fiables y escalables.</p>', '', '<ul>\r\n<li>Sistemas de nombres planos y jer&aacute;rquicos.</li>\r\n<li>Resolutores de nombres. Proceso de resoluci&oacute;n de un nombre de dominio.</li>\r\n<li>Servidores ra&iacute;z y dominios de primer nivel y sucesivos.</li>\r\n<li>Zonas primarias y secundarias. Transferencias de zona.</li>\r\n<li>Tipos de registros.</li>\r\n</ul>', '', '', '<p style=\"font-weight: 400;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para la misma.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:</p>\r\n<ul style=\"font-weight: 400;\">\r\n<li><strong>Pruebas objetivas</strong>&nbsp;(te&oacute;ricas o pr&aacute;cticas, 50 % de la calificaci&oacute;n)</li>\r\n<li><strong>Ejercicios</strong> (proyectos, pr&aacute;cticas y trabajos de aula, 50 % de la calificaci&oacute;n)&nbsp;</li>\r\n</ul>\r\n<p style=\"font-weight: 400;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de&nbsp;<strong>5 puntos</strong>&nbsp;sobre 10 en las pruebas objetivas, y <strong>5 puntos</strong> sobre 10 en los ejercicios correspondientes.</p>', '', '', 1, 1, 1, 1),
(148, 72, 4, 'Servicio FTP', 23, 1, 10, '<p>Esta unidad se centra en el protocolo FTP (File Transfer Protocol), explicando su funcionamiento, modos de conexi&oacute;n y configuraci&oacute;n de permisos, cuotas y ancho de banda. Se estudia el acceso mediante usuarios locales o an&oacute;nimos, as&iacute; como la diferencia entre transferencia en modo texto y binario.</p>', '<p>El intercambio de archivos entre servidores y clientes sigue siendo una necesidad recurrente en entornos profesionales. Conocer c&oacute;mo implementar y administrar un servicio FTP permite ofrecer soluciones seguras y controladas para la distribuci&oacute;n de datos, mantenimiento web o copias de seguridad.</p>', '', '<ul>\r\n<li>Usuarios y grupos. Acceso an&oacute;nimo.</li>\r\n<li>Permisos. Cuotas. L&iacute;mite de ancho de banda.</li>\r\n<li>Conexi&oacute;n de datos y conexi&oacute;n de control.</li>\r\n<li>Comandos de control, autenticaci&oacute;n, gesti&oacute;n y transferencia de ficheros.</li>\r\n<li>Transferencia en modo texto y binario.</li>\r\n<li>Modo activo y modo pasivo.</li>\r\n</ul>', '', '', '<p style=\"font-weight: 400;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para la misma.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:</p>\n<ul style=\"font-weight: 400;\">\n<li><strong>Pruebas objetivas</strong>&nbsp;(te&oacute;ricas o pr&aacute;cticas, 50 % de la calificaci&oacute;n)</li>\n<li><strong>Ejercicios</strong> (proyectos, pr&aacute;cticas y trabajos de aula, 50 % de la calificaci&oacute;n)&nbsp;</li>\n</ul>\n<p style=\"font-weight: 400;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de&nbsp;<strong>5 puntos</strong>&nbsp;sobre 10 en las pruebas objetivas, y <strong>5 puntos</strong> sobre 10 en los ejercicios correspondientes.</p>', '', '', 1, 1, 1, 1),
(149, 72, 5, 'Servicio HTTP', 35, 2, 15, '<p>En esta unidad se exploran los fundamentos del protocolo HTTP y el funcionamiento de los servidores web. Se abordan los conceptos de servidores virtuales, autenticaci&oacute;n, ejecuci&oacute;n de scripts y conexiones seguras mediante HTTPS, entendiendo el flujo de comunicaci&oacute;n entre cliente y servidor.</p>', '<p>El servicio HTTP es el pilar sobre el que se construyen la mayor&iacute;a de aplicaciones y servicios en l&iacute;nea. Su conocimiento capacita al alumnado para desplegar y gestionar sitios web, comprender la arquitectura cliente-servidor y aplicar medidas de seguridad en la publicaci&oacute;n de contenidos en Internet.</p>', '', '<ul>\r\n<li>Servidores virtuales. Nombre de encabezado de host.</li>\r\n<li>Identificaci&oacute;n de un servidor virtual.</li>\r\n<li>Acceso an&oacute;nimo y autentificado. M&eacute;todos de autentificaci&oacute;n.</li>\r\n<li>Ejecuci&oacute;n de c&oacute;digo. Scripts de servidor y de cliente.</li>\r\n<li>Establecimiento de conexiones seguras.</li>\r\n</ul>', '', '', '<p style=\"font-weight: 400;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para la misma.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:</p>\n<ul style=\"font-weight: 400;\">\n<li><strong>Pruebas objetivas</strong>&nbsp;(te&oacute;ricas o pr&aacute;cticas, 50 % de la calificaci&oacute;n)</li>\n<li><strong>Ejercicios</strong> (proyectos, pr&aacute;cticas y trabajos de aula, 50 % de la calificaci&oacute;n)&nbsp;</li>\n</ul>\n<p style=\"font-weight: 400;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de&nbsp;<strong>5 puntos</strong>&nbsp;sobre 10 en las pruebas objetivas, y <strong>5 puntos</strong> sobre 10 en los ejercicios correspondientes.</p>', '', '', 1, 1, 1, 1),
(150, 72, 6, 'Servicio de acceso y control remoto', 35, 2, 15, '<p>Esta unidad trata sobre los distintos protocolos y herramientas que permiten el acceso remoto a sistemas, tanto en modo texto como gr&aacute;fico. Se estudian los servicios de administraci&oacute;n y control remoto, as&iacute; como su configuraci&oacute;n segura para la gesti&oacute;n de equipos a distancia.</p>', '<p>El mantenimiento remoto es una pr&aacute;ctica habitual en la administraci&oacute;n de redes y sistemas. Aprender a configurar y asegurar conexiones remotas garantiza una gesti&oacute;n eficiente sin necesidad de intervenci&oacute;n f&iacute;sica, optimizando tiempos y recursos t&eacute;cnicos en entornos profesionales.</p>', '', '<ul>\r\n<li>Terminales en modo texto.</li>\r\n<li>Terminales en modo gr&aacute;fico.</li>\r\n<li>Protocolos de acceso.</li>\r\n<li>Protocolos de administraci&oacute;n remota.</li>\r\n</ul>', '', '', '<p style=\"font-weight: 400;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para la misma.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:</p>\n<ul style=\"font-weight: 400;\">\n<li><strong>Pruebas objetivas</strong>&nbsp;(te&oacute;ricas o pr&aacute;cticas, 50 % de la calificaci&oacute;n)</li>\n<li><strong>Ejercicios</strong> (proyectos, pr&aacute;cticas y trabajos de aula, 50 % de la calificaci&oacute;n)&nbsp;</li>\n</ul>\n<p style=\"font-weight: 400;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de&nbsp;<strong>5 puntos</strong>&nbsp;sobre 10 en las pruebas objetivas, y <strong>5 puntos</strong> sobre 10 en los ejercicios correspondientes.</p>', '', '', 1, 1, 1, 1),
(151, 72, 7, 'Servicios de correo electrónico', 23, 2, 10, '<p>En esta unidad se estudia la arquitectura del correo electr&oacute;nico, los protocolos implicados en el env&iacute;o y recepci&oacute;n de mensajes (SMTP, POP, IMAP), y la configuraci&oacute;n de buzones, alias y filtros. Se aborda tambi&eacute;n la gesti&oacute;n del correo no deseado y las pol&iacute;ticas de reenv&iacute;o.</p>', '<p>El correo electr&oacute;nico sigue siendo una herramienta fundamental de comunicaci&oacute;n en cualquier organizaci&oacute;n. Comprender su funcionamiento interno permite implantar, administrar y asegurar servidores de correo, garantizando la disponibilidad y fiabilidad de este servicio esencial.</p>', '', '<ul>\r\n<li>Agentes y protocolo de transferencia de mensajes.</li>\r\n<li>Cuentas de correo, alias y buzones de usuario.</li>\r\n<li>Reenv&iacute;o de correo y correo no deseado.</li>\r\n<li>Protocolos y servicios de descarga de correo.</li>\r\n</ul>', '', '', '<p style=\"font-weight: 400;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para la misma.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:</p>\n<ul style=\"font-weight: 400;\">\n<li><strong>Pruebas objetivas</strong>&nbsp;(te&oacute;ricas o pr&aacute;cticas, 50 % de la calificaci&oacute;n)</li>\n<li><strong>Ejercicios</strong> (proyectos, pr&aacute;cticas y trabajos de aula, 50 % de la calificaci&oacute;n)&nbsp;</li>\n</ul>\n<p style=\"font-weight: 400;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de&nbsp;<strong>5 puntos</strong>&nbsp;sobre 10 en las pruebas objetivas, y <strong>5 puntos</strong> sobre 10 en los ejercicios correspondientes.</p>', '', '', 1, 1, 1, 1),
(152, 72, 8, 'Despliegue de redes inalámbricas', 23, 2, 10, '<p>Esta unidad aborda los fundamentos de las redes inal&aacute;mbricas, sus est&aacute;ndares, modos de conexi&oacute;n y medidas de seguridad. Se estudian los componentes como puntos de acceso y encaminadores Wi-Fi, la configuraci&oacute;n de identificadores de servicio (SSID) y las t&eacute;cnicas de filtrado por direcciones MAC.</p>', '<p>El crecimiento de las redes inal&aacute;mbricas hace imprescindible dominar su instalaci&oacute;n y protecci&oacute;n. Conocer los est&aacute;ndares, los m&eacute;todos de autenticaci&oacute;n y las configuraciones adecuadas permite ofrecer conexiones estables, seguras y adaptadas a distintos entornos, desde oficinas hasta espacios p&uacute;blicos.</p>', '', '<ul>\r\n<li>Puntos de acceso.</li>\r\n<li>Encaminadores inal&aacute;mbricos.</li>\r\n<li>Est&aacute;ndares de conexi&oacute;n y velocidades soportadas.</li>\r\n<li>Identificadores de servicio.</li>\r\n<li>Seguridad en redes inal&aacute;mbricas.</li>\r\n<li>Conexiones punto a punto y en infraestructura.</li>\r\n<li>Direcciones MAC y filtrado de tr&aacute;fico.</li>\r\n</ul>', '', '', '<p style=\"font-weight: 400;\">La evaluaci&oacute;n de la unidad se realizar&aacute; de forma continua, tomando como referencia el grado de consecuci&oacute;n de los Resultados de Aprendizaje (RA) establecidos para la misma.&nbsp;Para la comprobaci&oacute;n del progreso del alumnado se emplear&aacute;n los siguientes instrumentos:</p>\n<ul style=\"font-weight: 400;\">\n<li><strong>Pruebas objetivas</strong>&nbsp;(te&oacute;ricas o pr&aacute;cticas, 50 % de la calificaci&oacute;n)</li>\n<li><strong>Ejercicios</strong> (proyectos, pr&aacute;cticas y trabajos de aula, 50 % de la calificaci&oacute;n)&nbsp;</li>\n</ul>\n<p style=\"font-weight: 400;\">Para considerar alcanzado un RA, el alumnado deber&aacute; obtener una calificaci&oacute;n m&iacute;nima de&nbsp;<strong>5 puntos</strong>&nbsp;sobre 10 en las pruebas objetivas, y <strong>5 puntos</strong> sobre 10 en los ejercicios correspondientes.</p>', '', '', 1, 1, 1, 1);
INSERT INTO `temas` (`id`, `idMateria`, `orden`, `titulo`, `horas`, `trimestre`, `peso_evaluacion`, `descripcion`, `justificacion`, `contexto`, `contenidos`, `secuenciacion`, `recursos`, `evaluacion`, `metodologia`, `adaptaciones`, `contexto_defecto`, `recursos_defecto`, `metodologia_defecto`, `adaptaciones_defecto`) VALUES
(153, 64, 1, 'Desarrollo de aplicaciones cliente con JavaScript y TypeScript', 100, 1, 50, '<p><span class=\"ng-star-inserted\">Esta unidad did&aacute;ctica,&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">\"Desarrollo de aplicaciones cliente con JavaScript y TypeScript\"</span></strong><span class=\"ng-star-inserted\">, introduce al alumnado en el n&uacute;cleo de la programaci&oacute;n web del lado del cliente. Se inicia el recorrido con un estudio profundo de los fundamentos de&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">JavaScript moderno (ES6+)</span></strong><span class=\"ng-star-inserted\">, abarcando desde la sintaxis b&aacute;sica, las estructuras de control y las funciones, hasta conceptos m&aacute;s avanzados como la asincron&iacute;a.</span></p>\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">A continuaci&oacute;n, se explora la interacci&oacute;n de JavaScript con el navegador a trav&eacute;s de la&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">manipulaci&oacute;n del Document Object Model (DOM)</span></strong><span class=\"ng-star-inserted\">, capacitando al alumnado para crear interfaces de usuario din&aacute;micas e interactivas que respondan a las acciones del usuario.</span></p>\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">El aprendizaje se expande hacia la comunicaci&oacute;n con servicios externos, ense&ntilde;ando a consumir&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">APIs REST</span></strong><span class=\"ng-star-inserted\">&nbsp;mediante el uso de la&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">API Fetch</span></strong><span class=\"ng-star-inserted\">, una habilidad crucial para construir aplicaciones ricas y basadas en datos.</span></p>\r\n<p><span class=\"ng-star-inserted\">Finalmente, la unidad integra un enfoque profesional al introducir el ecosistema de herramientas moderno. Se abordar&aacute; la gesti&oacute;n de proyectos y dependencias con&nbsp;<strong class=\"ng-star-inserted\">NPM</strong>&nbsp;y el uso de&nbsp;<strong class=\"ng-star-inserted\">Vite</strong>&nbsp;como servidor de desarrollo y empaquetador, optimizando el flujo de trabajo. Como colof&oacute;n, se presentar&aacute;&nbsp;<strong class=\"ng-star-inserted\">TypeScript</strong>, el superconjunto de JavaScript que a&ntilde;ade un sistema de tipado est&aacute;tico, sentando las bases para el desarrollo de aplicaciones m&aacute;s robustas, escalables y mantenibles.</span></p>', '<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Esta primera unidad did&aacute;ctica constituye el pilar fundamental del m&oacute;dulo de Desarrollo Web en Entorno Cliente. Su objetivo es sentar las bases del lenguaje que domina la web,&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">JavaScript</span></strong><span class=\"ng-star-inserted\">, y presentar el ecosistema de herramientas moderno que define el desarrollo de aplicaciones frontend en la actualidad.</span></p>\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Se parte de los conceptos esenciales de JavaScript, no solo como un lenguaje de scripting para a&ntilde;adir interactividad simple, sino como un lenguaje robusto y vers&aacute;til capaz de construir aplicaciones complejas. A continuaci&oacute;n, se aborda la manipulaci&oacute;n del&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Document Object Model (DOM)</span></strong><span class=\"ng-star-inserted\">, la habilidad clave para que las aplicaciones web cobren vida y respondan a las acciones del usuario.</span></p>\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">La unidad evoluciona hacia problem&aacute;ticas del mundo real, como el consumo de datos desde servicios externos a trav&eacute;s de la&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">API Fetch</span></strong><span class=\"ng-star-inserted\">&nbsp;para interactuar con&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">APIs REST</span></strong><span class=\"ng-star-inserted\">, una competencia indispensable para cualquier desarrollador web.</span></p>\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Finalmente, se introduce al alumnado en el flujo de trabajo profesional mediante herramientas como&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">NPM</span></strong><span class=\"ng-star-inserted\">&nbsp;para la gesti&oacute;n de dependencias y&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Vite</span></strong><span class=\"ng-star-inserted\">&nbsp;como sistema de empaquetado y servidor de desarrollo. Como colof&oacute;n, se presenta&nbsp;</span><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">TypeScript</span></strong><span class=\"ng-star-inserted\">, el superconjunto de JavaScript que a&ntilde;ade tipado est&aacute;tico, permitiendo construir aplicaciones m&aacute;s escalables, robustas y f&aacute;ciles de mantener.</span></p>\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Al finalizar esta unidad, el alumnado no solo habr&aacute; adquirido los conocimientos te&oacute;ricos, sino que habr&aacute; desarrollado la capacidad pr&aacute;ctica para crear, gestionar y depurar una aplicaci&oacute;n web cliente moderna desde cero.</span></p>', '', '<ol>\r\n<li>\r\n<h4 class=\"ng-star-inserted\"><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Bloque 1: Programaci&oacute;n b&aacute;sica en JavaScript. Colecciones.</span></strong></h4>\r\n<ul class=\"ng-star-inserted\">\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">1.1. Introducci&oacute;n a JavaScript y su Ecosistema</span></strong></p>\r\n<ul class=\"ng-star-inserted\">\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Historia y evoluci&oacute;n (ECMAScript, ES6+).</span></p>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">El papel de JavaScript en el desarrollo web.</span></p>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Herramientas de desarrollo: consola del navegador y editores de c&oacute;digo.</span></p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">1.2. Sintaxis y Fundamentos del Lenguaje</span></strong></p>\r\n<ul class=\"ng-star-inserted\">\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Variables, constantes y tipos de datos primitivos (</span><span class=\"inline-code ng-star-inserted\">let</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">const</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">string</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">number</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">boolean</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">null</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">undefined</span><span class=\"ng-star-inserted\">).</span></p>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Operadores: aritm&eacute;ticos, de asignaci&oacute;n, de comparaci&oacute;n y l&oacute;gicos.</span></p>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Estructuras de control de flujo:</span></p>\r\n<ul class=\"ng-star-inserted\">\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Condicionales:&nbsp;</span><span class=\"inline-code ng-star-inserted\">if</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">else if</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">else</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">switch</span><span class=\"ng-star-inserted\">.</span></p>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Bucles:&nbsp;</span><span class=\"inline-code ng-star-inserted\">for</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">while</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">do...while</span><span class=\"ng-star-inserted\">.</span></p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">1.3. Funciones</span></strong></p>\r\n<ul class=\"ng-star-inserted\">\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Declaraci&oacute;n de funciones y funciones de expresi&oacute;n.</span></p>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Funciones flecha (</span><span class=\"inline-code ng-star-inserted\">arrow functions</span><span class=\"ng-star-inserted\">) y su contexto (</span><span class=\"inline-code ng-star-inserted\">this</span><span class=\"ng-star-inserted\">).</span></p>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Par&aacute;metros, valores de retorno y par&aacute;metros por defecto.</span></p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">1.4. Colecciones de Datos</span></strong></p>\r\n<ul class=\"ng-star-inserted\">\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><strong class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">Arrays</span></strong><span class=\"ng-star-inserted\">: Creaci&oacute;n, acceso a elementos, propiedades (</span><span class=\"inline-code ng-star-inserted\">length</span><span class=\"ng-star-inserted\">).</span></p>\r\n<ul class=\"ng-star-inserted\">\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">M&eacute;todos de mutaci&oacute;n:&nbsp;</span><span class=\"inline-code ng-star-inserted\">push</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">pop</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">shift</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">unshift</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">splice</span><span class=\"ng-star-inserted\">.</span></p>\r\n</li>\r\n<li class=\"ng-star-inserted\">\r\n<p class=\"ng-star-inserted\"><span class=\"ng-star-inserted\">M&eacute;todos de iteraci&oacute;n y transformaci&oacute;n:&nbsp;</span><span class=\"inline-code ng-star-inserted\">forEach</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">map</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">filter</span><span class=\"ng-star-inserted\">,&nbsp;</span><span class=\"inline-code ng-star-inserted\">reduce</span><span class=\"ng-star-inserted\"